window.VOCAB_DATA = {"meta":{"name":"Theo哥哥 真经词汇","source":"Theo哥哥词汇真经学习工具（B站 @Theo哥哥教雅思）","chapters":22,"totalWords":3568,"generatedAt":"2026-10-15"},"chapters":{"1":[{"chapter":1,"key":"1:1","id":1,"word":"atmosphere","phonetic":"/ˈætməsfɪə/","pos":"n.","meaningCN":"大气层，大气圈；气氛","tag":"核心","root":"atmo（水汽）+ sphere（球体，球形）→ 大气圈","exampleEN":"The planet's thick atmosphere traps heat and keeps the surface warm.","exampleCN":"这颗行星厚厚的大气层锁住热量，使表面保持温暖。","extra":""},{"chapter":1,"key":"1:2","id":2,"word":"hydrosphere","phonetic":"/ˈhaɪdrəʊsfɪə/","pos":"n.","meaningCN":"水圈；大气中的水汽","tag":"核心","root":"hydro（水）+ sphere（球体，球形）→ 水圈","exampleEN":"The hydrosphere covers about 70% of the Earth's surface.","exampleCN":"水圈覆盖了地球表面约70%。","extra":""},{"chapter":1,"key":"1:3","id":3,"word":"lithosphere","phonetic":"/ˈlɪθəʊsfɪə/","pos":"n.","meaningCN":"岩石圈","tag":"核心","root":"litho（石头）+ sphere（球体，球形）→ 岩石圈","exampleEN":"Scientists study the lithosphere to understand how continents drift over time.","exampleCN":"科学家研究岩石圈以了解大陆如何随时间漂移。","extra":""},{"chapter":1,"key":"1:4","id":4,"word":"oxygen","phonetic":"/ˈɒksɪdʒən/","pos":"n.","meaningCN":"氧气","tag":"核心","root":"oxy（酸）+ gen（产生）→ 早期误以为所有酸都含氧而得名","exampleEN":"Plants absorb carbon dioxide and release oxygen during photosynthesis.","exampleCN":"植物在光合作用中吸收二氧化碳并释放氧气。","extra":""},{"chapter":1,"key":"1:5","id":5,"word":"oxide","phonetic":"/ˈɒksaɪd/","pos":"n.","meaningCN":"氧化物","tag":"核心","root":"ox(y)（氧）+ ide（化合物后缀）→ 氧化物","exampleEN":"Rust is a common type of iron oxide that forms when metal is exposed to moisture.","exampleCN":"铁锈是一种常见的氧化铁，当金属接触水分时就会形成。","extra":""},{"chapter":1,"key":"1:6","id":6,"word":"carbon dioxide","phonetic":"/ˈkɑːbən daɪˈɒksaɪd/","pos":"n.","meaningCN":"二氧化碳","tag":"核心","root":"carbon（碳）+ di（二）+ oxide（氧化物）→ 二氧化碳","exampleEN":"Burning coal in power stations releases large amounts of carbon dioxide into the air.","exampleCN":"发电站燃烧煤炭会向空气中释放大量二氧化碳。","extra":""},{"chapter":1,"key":"1:7","id":7,"word":"hydrogen","phonetic":"/ˈhaɪdrədʒən/","pos":"n.","meaningCN":"氢气","tag":"核心","root":"hydro（水）+ gen（生成）→ 燃烧后生成水的元素","exampleEN":"Hydrogen fuel is widely studied as a clean energy substitute for oil.","exampleCN":"氢燃料作为石油的清洁替代能源，正在被广泛研究。","extra":""},{"chapter":1,"key":"1:8","id":8,"word":"core","phonetic":"/kɔː/","pos":"n.","meaningCN":"中心，核心；地核","tag":"高频","root":"源自拉丁语 cor（心）→ 核心、中心","exampleEN":"At the core of any great school lies a strong team of teachers.","exampleCN":"任何优秀学校的核心都有一支强大的教师团队。","extra":""},{"chapter":1,"key":"1:9","id":9,"word":"crust","phonetic":"/krʌst/","pos":"n.","meaningCN":"地壳；外壳","tag":"高频","root":"源自拉丁语 crusta（硬壳）→ 外壳","exampleEN":"The outermost crust of the Earth is broken into many tectonic plates.","exampleCN":"地球最外层的地壳分裂成了多个构造板块。","extra":""},{"chapter":1,"key":"1:10","id":10,"word":"mantle","phonetic":"/ˈmæntl/","pos":"n.","meaningCN":"地幔；斗篷，披风","tag":"高频","root":"源自拉丁语 mantellum（披风）→ 覆盖物；地幔","exampleEN":"Below the crust lies the mantle, which is thousands of kilometres thick.","exampleCN":"地壳之下是厚达数千公里的地幔。","extra":""},{"chapter":1,"key":"1:11","id":11,"word":"longitude","phonetic":"/ˈlɒndʒɪtjuːd/","pos":"n.","meaningCN":"经度","tag":"高频","root":"long（长）+ -itude（表示状态）→ 经度","exampleEN":"Using longitude and latitude, navigators can pinpoint any location on the ocean.","exampleCN":"利用经纬度，航海者可以精确定位海洋上任何一处。","extra":""},{"chapter":1,"key":"1:12","id":12,"word":"latitude","phonetic":"/ˈlætɪtjuːd/","pos":"n.","meaningCN":"纬度","tag":"高频","root":"lat（宽）+ -itude（表示状态）→ 纬度","exampleEN":"Cities located at higher latitudes receive much less sunlight in winter.","exampleCN":"高纬度城市在冬天接收的阳光要少得多。","extra":""},{"chapter":1,"key":"1:13","id":13,"word":"horizon","phonetic":"/həˈraɪzən/","pos":"n.","meaningCN":"地平线；眼界，见识","tag":"核心","root":"源自希腊语 horizon（界限）→ 地平线；眼界","exampleEN":"Watching the sun disappear below the ocean horizon is a breathtaking experience.","exampleCN":"看着太阳消失在海平面之下是一种令人屏息的体验。","extra":""},{"chapter":1,"key":"1:14","id":14,"word":"altitude","phonetic":"/ˈæltɪtjuːd/","pos":"n.","meaningCN":"高度，海拔","tag":"核心","root":"alt（高）+ -itude（表示性质、状态）→ 高度","exampleEN":"Hikers often struggle with low oxygen when they reach high altitudes.","exampleCN":"徒步者在到达高海拔地区时通常会因低氧而感到吃力。","extra":""},{"chapter":1,"key":"1:15","id":15,"word":"disaster","phonetic":"/dɪˈzɑːstə/","pos":"n.","meaningCN":"灾难","tag":"核心","root":"dis（表示否定）+ aster（星星）→ 星相不吉 → 灾难","exampleEN":"The oil leak caused an environmental disaster along the entire coastline.","exampleCN":"这次石油泄漏给整条海岸线带来了环境灾难。","extra":""},{"chapter":1,"key":"1:16","id":16,"word":"mishap","phonetic":"/ˈmɪshæp/","pos":"n.","meaningCN":"小灾难","tag":"高频","root":"mis（坏的，错的）+ hap（运气）→ 不幸；小事故","exampleEN":"A slight mishap in the laboratory caused a short delay to the experiment.","exampleCN":"实验室的一个小事故让实验短暂推迟。","extra":""},{"chapter":1,"key":"1:17","id":17,"word":"catastrophic","phonetic":"/ˌkætəˈstrɒfɪk/","pos":"adj.","meaningCN":"灾难性的","tag":"高频","root":"源自希腊语 katastrophē（翻转；毁灭）→ 灾难性的","exampleEN":"A sudden rise in sea levels could have catastrophic effects on coastal cities.","exampleCN":"海平面突然上升可能会给沿海城市带来灾难性后果。","extra":""},{"chapter":1,"key":"1:18","id":18,"word":"calamity","phonetic":"/kəˈlæməti/","pos":"n.","meaningCN":"灾难，不幸的事","tag":"高频","root":"源自拉丁语 calamitas（灾害，损失）→ 灾难","exampleEN":"Years of conflict turned the once peaceful valley into a calamity zone.","exampleCN":"多年的冲突把曾经安宁的山谷变成了一片灾区。","extra":""},{"chapter":1,"key":"1:19","id":19,"word":"endanger","phonetic":"/ɪnˈdeɪndʒə/","pos":"v.","meaningCN":"使遭受危险，危及","tag":"核心","root":"en（使）+ danger（危险）→ 使遭受危险","exampleEN":"The increase in plastic waste endangers birds and sea creatures.","exampleCN":"塑料垃圾的增加危及鸟类和海洋生物。","extra":""},{"chapter":1,"key":"1:20","id":20,"word":"jeopardise","phonetic":"/ˈdʒepədaɪz/","pos":"v.","meaningCN":"危害，危及","tag":"核心","root":"源自古法语 jeu parti（平分的棋局）→ 危险处境 → 危及","exampleEN":"Pollution from nearby factories jeopardises the local water supply.","exampleCN":"附近工厂的污染危及当地供水。","extra":""},{"chapter":1,"key":"1:21","id":21,"word":"destructive","phonetic":"/dɪˈstrʌktɪv/","pos":"adj.","meaningCN":"破坏性的，有害的","tag":"核心","root":"de（除去）+ struct（建造）+ -ive（形容词后缀）→ 破坏性的","exampleEN":"The destructive storm swept through several villages, leaving hundreds homeless.","exampleCN":"这场破坏性风暴席卷了好几个村庄，数百人流离失所。","extra":""},{"chapter":1,"key":"1:22","id":22,"word":"El Nino","phonetic":"/el ˈniːnjəʊ/","pos":"n.","meaningCN":"厄尔尼诺现象","tag":"识记","root":"西班牙语“圣婴”，指南美沿岸海水异常增温现象","exampleEN":"During El Nino periods, fishing yields near Peru tend to drop sharply.","exampleCN":"在厄尔尼诺期间，秘鲁附近的渔获量往往会大幅下降。","extra":""},{"chapter":1,"key":"1:23","id":23,"word":"greenhouse","phonetic":"/ˈɡriːnhaʊs/","pos":"n.","meaningCN":"温室，暖房","tag":"核心","root":"green（绿色，植物）+ house（房屋）→ 温室","exampleEN":"Crops grown in a greenhouse are protected from extreme cold and pests.","exampleCN":"在温室中种植的作物能免于极寒和虫害侵袭。","extra":""},{"chapter":1,"key":"1:24","id":24,"word":"phenomenon","phonetic":"/fɪˈnɒmɪnən/","pos":"n.","meaningCN":"现象","tag":"核心","root":"pheno（显示，出现）+ menon（名词后缀）→ 现象","exampleEN":"The sudden phenomenon caught the attention of scientists around the world.","exampleCN":"这一突然现象引起了全球科学家的注意。","extra":""},{"chapter":1,"key":"1:25","id":25,"word":"pebble","phonetic":"/ˈpebl/","pos":"n.","meaningCN":"鹅卵石","tag":"低频","root":"源自古英语 papol（小石子）→ 鹅卵石","exampleEN":"She picked up a smooth white pebble as a souvenir of the beach.","exampleCN":"她捡起一块光滑的白色鹅卵石当作海滩的纪念。","extra":""},{"chapter":1,"key":"1:26","id":26,"word":"magnet","phonetic":"/ˈmæɡnɪt/","pos":"n.","meaningCN":"磁铁，吸铁石","tag":"高频","root":"源自希腊语 Magnēsia（马格内西亚，古地名）→ 磁石","exampleEN":"The child used a magnet to collect all the scattered metal pins.","exampleCN":"孩子用一块磁铁把所有散落的大头针吸了起来。","extra":""},{"chapter":1,"key":"1:27","id":27,"word":"ore","phonetic":"/ɔː/","pos":"n.","meaningCN":"矿石；矿","tag":"高频","root":"源自古英语 ōra（黄铜，矿石）→ 矿石","exampleEN":"The region is known for its rich deposits of copper and iron ore.","exampleCN":"该地区以丰富的铜矿和铁矿而闻名。","extra":""},{"chapter":1,"key":"1:28","id":28,"word":"mineral","phonetic":"/ˈmɪnərəl/","pos":"n.","meaningCN":"矿物，矿物质；矿产","tag":"核心","root":"mine（矿山）+ -eral（表示名词）→ 矿物","exampleEN":"Many cereals are fortified with essential minerals like zinc and iron.","exampleCN":"许多谷物食品都强化添加了锌和铁等必需矿物质。","extra":""},{"chapter":1,"key":"1:29","id":29,"word":"marble","phonetic":"/ˈmɑːbl/","pos":"n.","meaningCN":"大理石；弹球","tag":"高频","root":"源自希腊语 marmaros（闪光的石头）→ 大理石","exampleEN":"The floor of the cathedral was made of polished white marble.","exampleCN":"大教堂的地面由抛光白色大理石铺成。","extra":""},{"chapter":1,"key":"1:30","id":30,"word":"quartz","phonetic":"/kwɔːts/","pos":"n.","meaningCN":"石英","tag":"低频","root":"源自德语 Quarz，可能来自斯拉夫语（硬的）→ 石英","exampleEN":"The watch is powered by a tiny quartz crystal that vibrates constantly.","exampleCN":"这块表由一颗不断振动的小石英晶体驱动。","extra":""},{"chapter":1,"key":"1:31","id":31,"word":"granite","phonetic":"/ˈɡrænɪt/","pos":"n.","meaningCN":"花岗岩","tag":"低频","root":"gran（颗粒）+ -ite（名词后缀）→ 有颗粒的石头 → 花岗岩","exampleEN":"The old bridge was built from solid granite and survived several floods.","exampleCN":"这座古桥用坚固的花岗岩建成，历经多次洪水仍屹立不倒。","extra":""},{"chapter":1,"key":"1:32","id":32,"word":"gust","phonetic":"/ɡʌst/","pos":"n.","meaningCN":"一阵狂风；迸发","tag":"高频","root":"源自古诺斯语 gustr（风）→ 一阵狂风","exampleEN":"A powerful gust of wind blew the papers off the outdoor table.","exampleCN":"一阵强风把文件从户外桌上吹落。","extra":""},{"chapter":1,"key":"1:33","id":33,"word":"breeze","phonetic":"/briːz/","pos":"n.","meaningCN":"微风，和风","tag":"高频","root":"可能源自西班牙语 brisa（东北风）→ 微风","exampleEN":"We enjoyed a gentle evening breeze as we walked along the beach.","exampleCN":"我们沿着海滩散步时享受着傍晚轻柔的微风。","extra":""},{"chapter":1,"key":"1:34","id":34,"word":"monsoon","phonetic":"/mɒnˈsuːn/","pos":"n.","meaningCN":"季风；雨季","tag":"高频","root":"源自阿拉伯语 mausim（季节）→ 季风","exampleEN":"Farmers in South Asia depend on the monsoon to water their rice fields.","exampleCN":"南亚的农民依赖季风给稻田浇水。","extra":""},{"chapter":1,"key":"1:35","id":35,"word":"gale","phonetic":"/ɡeɪl/","pos":"n.","meaningCN":"大风","tag":"高频","root":"起源不确定，可能源自古诺斯语 gal（狂风）→ 大风","exampleEN":"The ship radioed for help as it was caught in a fierce gale.","exampleCN":"那艘船遭遇狂风，发出无线电求救。","extra":""},{"chapter":1,"key":"1:36","id":36,"word":"hurricane","phonetic":"/ˈhʌrɪkən/","pos":"n.","meaningCN":"飓风；暴风","tag":"高频","root":"源自西班牙语 huracán，来自加勒比土著语风暴之神 → 飓风","exampleEN":"Coastal residents evacuated their homes before the hurricane made landfall.","exampleCN":"沿海居民在飓风登陆前撤离了家园。","extra":""},{"chapter":1,"key":"1:37","id":37,"word":"tornado","phonetic":"/tɔːˈneɪdəʊ/","pos":"n.","meaningCN":"龙卷风","tag":"高频","root":"可能源自西班牙语 tronada（雷暴）→ 龙卷风","exampleEN":"The tornado lifted farm vehicles off the ground and tossed them aside.","exampleCN":"龙卷风把农用车辆掀离地面，抛到一旁。","extra":""},{"chapter":1,"key":"1:38","id":38,"word":"typhoon","phonetic":"/taɪˈfuːn/","pos":"n.","meaningCN":"台风","tag":"高频","root":"源自汉语粤方言“大风”（daai fung）→ 台风","exampleEN":"Ferry services were suspended as the typhoon grew stronger overnight.","exampleCN":"随着台风夜间加强，渡轮服务暂停。","extra":""},{"chapter":1,"key":"1:39","id":39,"word":"volcano","phonetic":"/vɒlˈkeɪnəʊ/","pos":"n.","meaningCN":"火山","tag":"高频","root":"源自罗马神话火神 Vulcan（武尔坎）→ 火山","exampleEN":"Tourists gathered at the viewpoint to watch the volcano erupt at sunset.","exampleCN":"游客聚集在观景台观看日落时分的火山喷发。","extra":""},{"chapter":1,"key":"1:40","id":40,"word":"erupt","phonetic":"/ɪˈrʌpt/","pos":"v.","meaningCN":"爆发，喷发；突然出现","tag":"高频","root":"e（向外）+ rupt（破裂）→ 向外破裂 → 爆发","exampleEN":"Thick smoke and ash erupted from the crater, darkening the sky.","exampleCN":"浓烟和火山灰从火山口喷出，天空变得昏暗。","extra":""},{"chapter":1,"key":"1:41","id":41,"word":"magma","phonetic":"/ˈmæɡmə/","pos":"n.","meaningCN":"岩浆","tag":"识记","root":"源自希腊语 magma（揉捏，浓厚的软膏）→ 岩浆","exampleEN":"As magma rises closer to the surface, it can trigger tremors in nearby areas.","exampleCN":"当岩浆上升接近地表时，会引发附近地区的震动。","extra":""},{"chapter":1,"key":"1:42","id":42,"word":"thermodynamic","phonetic":"/ˌθɜːməʊdaɪˈnæmɪk/","pos":"adj.","meaningCN":"热力的；热力学的","tag":"识记","root":"thermo（热）+ dynamic（力的；力学）→ 热力的；热力学的","exampleEN":"The engine was designed using advanced thermodynamic principles for better fuel efficiency.","exampleCN":"这台发动机采用先进热力学原理设计，以提高燃油效率。","extra":""},{"chapter":1,"key":"1:43","id":43,"word":"smog","phonetic":"/smɒɡ/","pos":"n.","meaningCN":"烟雾，雾霾","tag":"高频","root":"smoke（烟）+ fog（雾）→ 烟雾","exampleEN":"The city banned many older cars to reduce the smog that covered its streets.","exampleCN":"该市禁止许多旧车上路，以减少覆盖街道的雾霾。","extra":""},{"chapter":1,"key":"1:44","id":44,"word":"fume","phonetic":"/fjuːm/","pos":"n.","meaningCN":"烟，气体","tag":"高频","root":"源自拉丁语 fumus（烟）→ 烟，气体","exampleEN":"Workers wore masks to avoid inhaling the toxic fumes from burning plastics.","exampleCN":"工人戴着口罩以避免吸入燃烧塑料产生的有毒烟气。","extra":""},{"chapter":1,"key":"1:45","id":45,"word":"mist","phonetic":"/mɪst/","pos":"n.","meaningCN":"薄雾；水汽；使视线模糊的东西","tag":"高频","root":"源自古英语 mist（薄雾）→ 薄雾","exampleEN":"A cold mist rolled off the river, making it hard to see the opposite bank.","exampleCN":"一股寒冷的薄雾从河面升起，使对岸难以看清。","extra":""},{"chapter":1,"key":"1:46","id":46,"word":"tsunami","phonetic":"/tsuːˈnɑːmi/","pos":"n.","meaningCN":"海啸","tag":"高频","root":"源自日语“津波”（港口波浪）→ 海啸","exampleEN":"The earthquake generated a huge tsunami that swept over the coastal villages.","exampleCN":"地震引发了巨大的海啸，淹没了沿海村庄。","extra":""},{"chapter":1,"key":"1:47","id":47,"word":"drought","phonetic":"/draʊt/","pos":"n.","meaningCN":"干旱，旱灾","tag":"高频","root":"词源同 dry（干燥的）→ 干旱","exampleEN":"Long months of drought forced the local government to restrict water use.","exampleCN":"长达数月的干旱迫使当地政府限制用水。","extra":""},{"chapter":1,"key":"1:48","id":48,"word":"flooding","phonetic":"/ˈflʌdɪŋ/","pos":"n.","meaningCN":"洪水泛滥","tag":"高频","root":"flood（洪水）+ -ing（表示过程）→ 洪水泛滥","exampleEN":"The flooding submerged the entire ground floor of the hospital.","exampleCN":"洪水淹没了医院整个一楼。","extra":""},{"chapter":1,"key":"1:49","id":49,"word":"torrent","phonetic":"/ˈtɒrənt/","pos":"n.","meaningCN":"激流，洪流","tag":"高频","root":"源自拉丁语 torrens（急流）→ 激流","exampleEN":"After the heavy rain, a torrent of brown water rushed down the mountain.","exampleCN":"大雨过后，一股棕色的激流从山上奔涌而下。","extra":""},{"chapter":1,"key":"1:50","id":50,"word":"earthquake","phonetic":"/ˈɜːθkweɪk/","pos":"n.","meaningCN":"地震","tag":"核心","root":"earth（地球）+ quake（震动）→ 地震","exampleEN":"The earthquake rattled windows and knocked books off the shelves.","exampleCN":"地震震得窗户咯吱响，把书架上的书震落。","extra":""},{"chapter":1,"key":"1:51","id":51,"word":"seismic","phonetic":"/ˈsaɪzmɪk/","pos":"adj.","meaningCN":"地震的，地震引起的","tag":"高频","root":"源自希腊语 seismos（地震）→ 地震的","exampleEN":"Researchers placed sensors across the fault to monitor seismic changes.","exampleCN":"研究人员在断层各处放置传感器以监测地震变化。","extra":""},{"chapter":1,"key":"1:52","id":52,"word":"avalanche","phonetic":"/ˈævəlɑːnʃ/","pos":"n.","meaningCN":"雪崩","tag":"高频","root":"源自古法语 avaler（下降）→ 雪崩","exampleEN":"The skiers were warned to stay away from the steep slope because of avalanche danger.","exampleCN":"滑雪者被警告远离陡峭山坡，因为有雪崩危险。","extra":""},{"chapter":1,"key":"1:53","id":53,"word":"terrain","phonetic":"/təˈreɪn/","pos":"n.","meaningCN":"地形","tag":"高频","root":"源自拉丁语 terrenum（大地）→ 地形","exampleEN":"The mountainous terrain made it difficult to build a railway through the region.","exampleCN":"多山的地形使得在该地区修建铁路十分困难。","extra":""},{"chapter":1,"key":"1:54","id":54,"word":"landscape","phonetic":"/ˈlændskeɪp/","pos":"n.","meaningCN":"风景，地貌","tag":"核心","root":"land（陆地）+ -scape（表示性质、状况）→ 地貌","exampleEN":"The dramatic desert landscape attracted artists from around the world.","exampleCN":"这种壮观的沙漠地貌吸引了世界各地的艺术家。","extra":""},{"chapter":1,"key":"1:55","id":55,"word":"continent","phonetic":"/ˈkɒntɪnənt/","pos":"n.","meaningCN":"大陆；洲","tag":"核心","root":"源自拉丁语 continens（连绵的土地）→ 大陆","exampleEN":"Australia is unique because it is both a country and an entire continent.","exampleCN":"澳大利亚很独特，因为它既是一个国家，又是一整块大陆。","extra":""},{"chapter":1,"key":"1:56","id":56,"word":"cave","phonetic":"/keɪv/","pos":"n.","meaningCN":"洞穴，山洞","tag":"高频","root":"源自拉丁语 cava（空洞）→ 洞穴","exampleEN":"The explorers lit their torches before entering the dark limestone cave.","exampleCN":"探险者点燃火把，然后才进入漆黑的石灰岩洞穴。","extra":""},{"chapter":1,"key":"1:57","id":57,"word":"cliff","phonetic":"/klɪf/","pos":"n.","meaningCN":"悬崖，峭壁","tag":"高频","root":"源自古英语 clif（岩石，陡坡）→ 悬崖","exampleEN":"They stood at the edge of the cliff, looking down at the waves crashing below.","exampleCN":"他们站在悬崖边缘，俯视下方翻腾的海浪。","extra":""},{"chapter":1,"key":"1:58","id":58,"word":"glacier","phonetic":"/ˈɡlæsiə/","pos":"n.","meaningCN":"冰河，冰川","tag":"高频","root":"源自拉丁语 glacies（冰）→ 冰川","exampleEN":"Slowly moving glaciers carved deep valleys into the landscape over many centuries.","exampleCN":"缓慢移动的冰川经过许多世纪雕刻出深深的峡谷。","extra":""},{"chapter":1,"key":"1:59","id":59,"word":"swamp","phonetic":"/swɒmp/","pos":"n.","meaningCN":"沼泽，湿地","tag":"高频","root":"起源不确定，可能来自日耳曼语（浸水的土地）→ 沼泽","exampleEN":"A wooden boardwalk let visitors cross the swamp without getting their feet wet.","exampleCN":"一条木板栈道让游客可以穿过沼泽而不会弄湿双脚。","extra":""},{"chapter":1,"key":"1:60","id":60,"word":"delta","phonetic":"/ˈdeltə/","pos":"n.","meaningCN":"三角洲","tag":"高频","root":"源自希腊字母首个字母 Δ（三角形）→ 三角洲","exampleEN":"The Yangtze Delta is one of China's most economically developed regions.","exampleCN":"长江三角洲是中国经济最发达的地区之一。","extra":""},{"chapter":1,"key":"1:61","id":61,"word":"plain","phonetic":"/pleɪn/","pos":"n.","meaningCN":"平原","tag":"核心","root":"源自拉丁语 planus（平坦的）→ 平原","exampleEN":"Vast wheat fields stretched across the flat plain as far as the eye could see.","exampleCN":"广阔的麦田穿过平坦的平原，一眼望不到边。","extra":""},{"chapter":1,"key":"1:62","id":62,"word":"plateau","phonetic":"/ˈplætəʊ/","pos":"n.","meaningCN":"高原","tag":"高频","root":"源自法语 plateau（平盘）→ 高原","exampleEN":"The Tibetan Plateau rises so high that it is often called the roof of the world.","exampleCN":"青藏高原海拔如此之高，常被称为世界屋脊。","extra":""},{"chapter":1,"key":"1:63","id":63,"word":"oasis","phonetic":"/əʊˈeɪsɪs/","pos":"n.","meaningCN":"绿洲；宜人之地","tag":"高频","root":"源自希腊语 oasis（绿洲）→ 沙漠中的水源地","exampleEN":"The small oasis offered a shaded resting spot for travelers crossing the dry desert.","exampleCN":"这片小绿洲为穿越干燥沙漠的旅人提供了一处阴凉歇脚地。","extra":""},{"chapter":1,"key":"1:64","id":64,"word":"globe","phonetic":"/ɡləʊb/","pos":"n.","meaningCN":"球体；地球仪；地球","tag":"核心","root":"源自拉丁语 globus（球体）→ 地球","exampleEN":"The museum had a giant globe that showed all the world's shipping routes.","exampleCN":"博物馆里有一个巨大的地球仪，展示着全世界的航线。","extra":""},{"chapter":1,"key":"1:65","id":65,"word":"hemisphere","phonetic":"/ˈhemɪsfɪə/","pos":"n.","meaningCN":"半球","tag":"高频","root":"hemi（半）+ sphere（球）→ 半球","exampleEN":"When it is summer in the northern hemisphere, it is winter in the southern.","exampleCN":"当北半球是夏季时，南半球就是冬季。","extra":""},{"chapter":1,"key":"1:66","id":66,"word":"equator","phonetic":"/ɪˈkweɪtə/","pos":"n.","meaningCN":"赤道","tag":"高频","root":"源自拉丁语 aequare（使相等）→ 赤道（将地球平分）","exampleEN":"The sun blazed directly overhead as the ship crossed the equator.","exampleCN":"当船只越过赤道时，太阳直直地照在头顶上。","extra":""},{"chapter":1,"key":"1:67","id":67,"word":"Arctic","phonetic":"/ˈɑːktɪk/","pos":"adj.","meaningCN":"极冷的；北极的","tag":"高频","root":"源自希腊语 arktikos（靠近大熊星座的；北方的）→ 北极的","exampleEN":"Polar bears are specially adapted to survive in the harsh Arctic environment.","exampleCN":"北极熊特别适应在严酷的北极环境中生存。","extra":""},{"chapter":1,"key":"1:68","id":68,"word":"Antarctic","phonetic":"/ænˈtɑːktɪk/","pos":"adj.","meaningCN":"南极的","tag":"高频","root":"ant（对面的）+ arctic（北极）→ 北极的对面 → 南极","exampleEN":"The Antarctic ice sheet holds most of the planet's fresh water.","exampleCN":"南极冰盖储存着地球上大部分的淡水。","extra":""},{"chapter":1,"key":"1:69","id":69,"word":"pole","phonetic":"/pəʊl/","pos":"n.","meaningCN":"地极；截然相反的两极之一","tag":"核心","root":"源自拉丁语 polus（轴的端点）→ 地极","exampleEN":"Scientists set up a temporary station near the South Pole to study the climate.","exampleCN":"科学家在南极附近设立了临时站研究气候。","extra":""},{"chapter":1,"key":"1:70","id":70,"word":"polar","phonetic":"/ˈpəʊlə/","pos":"adj.","meaningCN":"极地的，近极地的；对立的","tag":"核心","root":"pole（极地）+ -ar（形容词后缀）→ 极地的","exampleEN":"The rapid warming of polar regions is alarming climate experts.","exampleCN":"极地地区的快速升温令气候专家感到担忧。","extra":""},{"chapter":1,"key":"1:71","id":71,"word":"axis","phonetic":"/ˈæksɪs/","pos":"n.","meaningCN":"轴，轴线","tag":"高频","root":"源自拉丁语 axis（车轴；轴线）→ 轴线","exampleEN":"The Earth rotates around its tilted axis once every twenty-four hours.","exampleCN":"地球每二十四小时绕其倾斜的轴线自转一圈。","extra":""},{"chapter":1,"key":"1:72","id":72,"word":"deteriorate","phonetic":"/dɪˈtɪəriəreɪt/","pos":"v.","meaningCN":"恶化，变坏","tag":"核心","root":"源自拉丁语 deterior（更差的）+ -ate（动词后缀）→ 恶化","exampleEN":"Air quality in the capital began to deteriorate as more factories opened.","exampleCN":"随着更多工厂开工，首都的空气质量开始恶化。","extra":""},{"chapter":1,"key":"1:73","id":73,"word":"aggravate","phonetic":"/ˈæɡrəveɪt/","pos":"v.","meaningCN":"加重，加剧，使恶化","tag":"核心","root":"ag（加强意义）+ grav（重的）+ -ate（动词后缀）→ 加重","exampleEN":"Exhaust from cars may aggravate breathing problems in elderly people.","exampleCN":"汽车排放的废气可能加重老年人的呼吸问题。","extra":""},{"chapter":1,"key":"1:74","id":74,"word":"degrade","phonetic":"/dɪˈɡreɪd/","pos":"v.","meaningCN":"降解；降低身份；使恶化","tag":"核心","root":"de（向下）+ grade（层级）→ 降级 → 退化","exampleEN":"Plastic bags take centuries to degrade naturally in the environment.","exampleCN":"塑料袋需要几个世纪才能在环境中自然降解。","extra":""},{"chapter":1,"key":"1:75","id":75,"word":"upgrade","phonetic":"/ʌpˈɡreɪd/","pos":"v.","meaningCN":"使升级；提高，改善","tag":"核心","root":"up（向上）+ grade（层级）→ 升级","exampleEN":"They decided to upgrade the old power station to reduce air pollution.","exampleCN":"他们决定升级那座旧发电站以减少空气污染。","extra":""},{"chapter":1,"key":"1:76","id":76,"word":"erode","phonetic":"/ɪˈrəʊd/","pos":"v.","meaningCN":"侵蚀，腐蚀","tag":"核心","root":"e（向外）+ rod（咬）+ e → 咬掉 → 侵蚀","exampleEN":"Constant rainfall will erode the topsoil on hills rebuilt without trees.","exampleCN":"持续降雨会侵蚀没有树木的山坡上的表层土壤。","extra":""},{"chapter":1,"key":"1:77","id":77,"word":"Mediterranean","phonetic":"/ˌmedɪtəˈreɪniən/","pos":"adj.","meaningCN":"地中海的；地中海地区的","tag":"识记","root":"medi（中间）+ terra（陆地）→ 陆地之间的海 → 地中海","exampleEN":"The Mediterranean climate, with hot dry summers, attracts many tourists.","exampleCN":"夏季炎热干燥的地中海气候吸引了大量游客。","extra":""},{"chapter":1,"key":"1:78","id":78,"word":"Atlantic","phonetic":"/ətˈlæntɪk/","pos":"adj.","meaningCN":"大西洋的","tag":"识记","root":"源自希腊语 Atlantikos（阿特拉斯之海）→ 大西洋","exampleEN":"The Atlantic trade winds helped early explorers cross the vast ocean.","exampleCN":"大西洋信风帮助早期探险者横渡这片广阔海洋。","extra":""},{"chapter":1,"key":"1:79","id":79,"word":"Pacific","phonetic":"/pəˈsɪfɪk/","pos":"adj.","meaningCN":"平静的，和平的；太平洋的","tag":"识记","root":"源自拉丁语 pacificus（带来和平的）→ 太平洋（麦哲伦命名）","exampleEN":"The Pacific Ocean covers nearly one third of the Earth's total surface.","exampleCN":"太平洋几乎覆盖了地球总面积的三分之一。","extra":""},{"chapter":1,"key":"1:80","id":80,"word":"ocean","phonetic":"/ˈəʊʃən/","pos":"n.","meaningCN":"海洋；洋","tag":"核心","root":"源自希腊语 ōkeanos（环绕大地的大河）→ 海洋","exampleEN":"The deep ocean remains one of the least explored areas on the planet.","exampleCN":"深海仍然是地球上探索最少的区域之一。","extra":""},{"chapter":1,"key":"1:81","id":81,"word":"marine","phonetic":"/məˈriːn/","pos":"adj.","meaningCN":"海生的，海洋的；海事的","tag":"高频","root":"源自拉丁语 mare（海）→ 海洋的","exampleEN":"The government set up a protected area to preserve the region's marine life.","exampleCN":"政府设立保护区以保护该地区的海洋生物。","extra":""},{"chapter":1,"key":"1:82","id":82,"word":"navigation","phonetic":"/ˌnævɪˈɡeɪʃən/","pos":"n.","meaningCN":"航行；航海","tag":"高频","root":"源自拉丁语 navis（船）+ agere（驾驶）→ 航海","exampleEN":"Modern ships rely on satellite navigation more than paper charts.","exampleCN":"现代船只更多地依赖卫星导航而非纸质海图。","extra":""},{"chapter":1,"key":"1:83","id":83,"word":"gulf","phonetic":"/ɡʌlf/","pos":"n.","meaningCN":"海湾","tag":"高频","root":"源自希腊语 kolpos（怀抱；海湾）→ 海湾","exampleEN":"The gulf provides a natural harbor for fishing boats during bad weather.","exampleCN":"这个海湾在恶劣天气时为渔船提供了天然避风港。","extra":""},{"chapter":1,"key":"1:84","id":84,"word":"beach","phonetic":"/biːtʃ/","pos":"n.","meaningCN":"海滩，河滩","tag":"高频","root":"源自古英语 bæce（溪流边的小石头）→ 海滩","exampleEN":"Children spent all afternoon building sand castles on the beach.","exampleCN":"孩子们整个下午都在海滩上堆沙堡。","extra":""},{"chapter":1,"key":"1:85","id":85,"word":"coast","phonetic":"/kəʊst/","pos":"n.","meaningCN":"海岸，海滨","tag":"核心","root":"源自拉丁语 costa（肋骨；侧边）→ 海岸","exampleEN":"A series of wind farms was installed along the coast to generate clean power.","exampleCN":"沿岸安装了一系列风力发电机以产生清洁能源。","extra":""},{"chapter":1,"key":"1:86","id":86,"word":"shore","phonetic":"/ʃɔː/","pos":"n.","meaningCN":"岸，滨","tag":"高频","root":"源自古英语 scora（岸）→ 岸","exampleEN":"They launched the lifeboat from the shore and rowed toward the sinking boat.","exampleCN":"他们从岸边放下救生艇，向正在下沉的船只划去。","extra":""},{"chapter":1,"key":"1:87","id":87,"word":"tide","phonetic":"/taɪd/","pos":"n.","meaningCN":"趋势，潮流；潮汐","tag":"核心","root":"源自古英语 tīd（时间，时节）→ 潮汐","exampleEN":"The tide carried the drifting wood far up the beach during the night.","exampleCN":"潮水在夜间把漂流的木头冲到了海滩很远的地方。","extra":""},{"chapter":1,"key":"1:88","id":88,"word":"current","phonetic":"/ˈkʌrənt/","pos":"n.","meaningCN":"水流，潮流；电流；气流","tag":"核心","root":"源自拉丁语 currere（跑）→ 流动 → 水流","exampleEN":"Swimmers were warned of a strong undercurrent that could pull them out to sea.","exampleCN":"游泳者被警告有一股强底流，可能将他们拖入外海。","extra":""},{"chapter":1,"key":"1:89","id":89,"word":"brook","phonetic":"/brʊk/","pos":"n.","meaningCN":"小河，溪","tag":"高频","root":"源自古英语 brōc（小溪）→ 小河","exampleEN":"A clear brook runs through the middle of the village from the nearby hills.","exampleCN":"一条清澈的小溪从附近山上流过村庄中央。","extra":""},{"chapter":1,"key":"1:90","id":90,"word":"stream","phonetic":"/striːm/","pos":"n.","meaningCN":"小河，溪；流","tag":"核心","root":"源自古英语 strēam（溪流）→ 溪","exampleEN":"They set up their tent beside a mountain stream to have fresh water nearby.","exampleCN":"他们在一条山间小溪旁搭起帐篷，以便就近取用淡水。","extra":""},{"chapter":1,"key":"1:91","id":91,"word":"source","phonetic":"/sɔːs/","pos":"n.","meaningCN":"河的源头；根源","tag":"核心","root":"源自古法语 sourse（涌出）→ 源头","exampleEN":"The team followed the river all the way to its source high in the mountains.","exampleCN":"团队沿着河流一路走到它位于高山深处的源头。","extra":""},{"chapter":1,"key":"1:92","id":92,"word":"shallow","phonetic":"/ˈʃæləʊ/","pos":"adj.","meaningCN":"浅的；肤浅的，浅薄的","tag":"核心","root":"源自古英语 sceald（浅的）→ 浅的","exampleEN":"The water near the shore was so shallow that we could walk out quite far.","exampleCN":"靠近岸边的水很浅，我们可以走出相当远。","extra":""},{"chapter":1,"key":"1:93","id":93,"word":"superficial","phonetic":"/ˌsuːpəˈfɪʃəl/","pos":"adj.","meaningCN":"表面的，表层的","tag":"高频","root":"super（上）+ facies（面）+ -ial → 表面的","exampleEN":"The repair was only superficial; the deeper damage to the wall remained.","exampleCN":"修复只是表面的；墙壁内部更深的损坏依然存在。","extra":""},{"chapter":1,"key":"1:94","id":94,"word":"flat","phonetic":"/flæt/","pos":"adj.","meaningCN":"平坦的；扁平的；单调的","tag":"核心","root":"源自古诺斯语 flatr（平坦的）→ 平坦的","exampleEN":"The team picked a flat and open area for their science camp.","exampleCN":"团队挑选了一块平坦开阔的区域作为科学营地。","extra":""},{"chapter":1,"key":"1:95","id":95,"word":"smooth","phonetic":"/smuːð/","pos":"adj.","meaningCN":"光滑的；平稳的；流畅的","tag":"核心","root":"源自古英语 smōth（光滑的）→ 光滑的","exampleEN":"The river rocks had been worn smooth by thousands of years of running water.","exampleCN":"河中的石头被数千年流水磨得光滑。","extra":""},{"chapter":1,"key":"1:96","id":96,"word":"rough","phonetic":"/rʌf/","pos":"adj.","meaningCN":"粗糙的；粗略的","tag":"核心","root":"源自古英语 rūh（粗糙的）→ 粗糙的","exampleEN":"The trail became rough and steep, forcing the hikers to slow their pace.","exampleCN":"小径变得崎岖陡峭，迫使徒步者放慢脚步。","extra":""},{"chapter":1,"key":"1:97","id":97,"word":"sandy","phonetic":"/ˈsændi/","pos":"adj.","meaningCN":"铺满沙的；含沙的","tag":"高频","root":"sand（沙）+ -y（形容词后缀）→ 含沙的","exampleEN":"They cycled along a narrow sandy track that ran through the dunes.","exampleCN":"他们沿着一条穿过沙丘的窄沙土小路骑行。","extra":""},{"chapter":1,"key":"1:98","id":98,"word":"stony","phonetic":"/ˈstəʊni/","pos":"adj.","meaningCN":"石头的；多石的","tag":"高频","root":"stone（石头）+ -y（形容词后缀）→ 多石的","exampleEN":"The farmer struggled to grow crops on the stony and unproductive land.","exampleCN":"这位农夫在那片多石的贫瘠土地上艰难耕种。","extra":""},{"chapter":1,"key":"1:99","id":99,"word":"vertical","phonetic":"/ˈvɜːtɪkəl/","pos":"adj.","meaningCN":"垂直的，直立的","tag":"核心","root":"源自拉丁语 vertex（顶点；旋涡）→ 垂直","exampleEN":"The climber used ropes to safely ascend the nearly vertical cliff face.","exampleCN":"攀岩者用绳索安全地攀登近乎垂直的岩壁。","extra":""},{"chapter":1,"key":"1:100","id":100,"word":"steep","phonetic":"/stiːp/","pos":"adj.","meaningCN":"陡峭的，陡直的","tag":"核心","root":"源自古英语 stēap（高的，陡的）→ 陡峭的","exampleEN":"Cars had to drive slowly down the steep road when it was covered with ice.","exampleCN":"路面结冰时，汽车不得不缓慢驶下陡坡。","extra":""},{"chapter":1,"key":"1:101","id":101,"word":"parallel","phonetic":"/ˈpærəlel/","pos":"adj.","meaningCN":"平行的；相似","tag":"核心","root":"para（旁边）+ allelon（彼此）→ 平行的","exampleEN":"The two mountain ridges run almost perfectly parallel for dozens of miles.","exampleCN":"这两条山脊几乎完美平行地延伸数十英里。","extra":""},{"chapter":1,"key":"1:102","id":102,"word":"narrow","phonetic":"/ˈnærəʊ/","pos":"adj.","meaningCN":"狭窄的；有局限的","tag":"核心","root":"源自古英语 nearu（狭窄的）→ 狭窄的","exampleEN":"Only one small boat could pass through the narrow channel at a time.","exampleCN":"一次只有一艘小船能通过这条狭窄的航道。","extra":""},{"chapter":1,"key":"1:103","id":103,"word":"Oceania","phonetic":"/ˌəʊʃiˈɑːniə/","pos":"n.","meaningCN":"大洋洲","tag":"识记","root":"ocean（海洋）+ -ia（表示地方）→ 大洋洲","exampleEN":"Oceania consists of Australia, New Zealand, and many small Pacific islands.","exampleCN":"大洋洲包括澳大利亚、新西兰和许多太平洋小岛。","extra":""},{"chapter":1,"key":"1:104","id":104,"word":"mainland","phonetic":"/ˈmeɪnlænd/","pos":"n.","meaningCN":"大陆，本土","tag":"核心","root":"main（主要的）+ land（陆地）→ 大陆","exampleEN":"Ferries run daily between the island and the mainland carrying supplies.","exampleCN":"渡船每天往返海岛和大陆之间运送物资。","extra":""},{"chapter":1,"key":"1:105","id":105,"word":"peninsula","phonetic":"/pɪˈnɪnsjʊlə/","pos":"n.","meaningCN":"半岛","tag":"高频","root":"pen（几乎）+ insula（岛）→ 几乎是一个岛 → 半岛","exampleEN":"The Arabian Peninsula is bordered by the Red Sea on its western side.","exampleCN":"阿拉伯半岛西侧濒临红海。","extra":""},{"chapter":1,"key":"1:106","id":106,"word":"climate","phonetic":"/ˈklaɪmɪt/","pos":"n.","meaningCN":"气候；风气，思潮，环境","tag":"核心","root":"源自希腊语 klima（倾斜；地区）→ 气候","exampleEN":"A warming climate is already affecting harvests in several farming regions.","exampleCN":"日益变暖的气候已经影响到几个农业区的收成。","extra":""},{"chapter":1,"key":"1:107","id":107,"word":"weather","phonetic":"/ˈweðə/","pos":"n.","meaningCN":"天气，气象","tag":"核心","root":"源自古英语 weder（天气）→ 天气","exampleEN":"Due to bad weather, all outdoor sports activities were cancelled for the day.","exampleCN":"由于天气恶劣，当天所有户外体育活动都被取消。","extra":""},{"chapter":1,"key":"1:108","id":108,"word":"meteorology","phonetic":"/ˌmiːtiəˈrɒlədʒi/","pos":"n.","meaningCN":"气象学","tag":"识记","root":"meteor（高处的事物）+ logy（学说）→ 气象学","exampleEN":"Advances in meteorology now allow forecasters to warn of storms days ahead.","exampleCN":"气象学的进步如今使得预报员可以提前数天预警暴风雨。","extra":""},{"chapter":1,"key":"1:109","id":109,"word":"mild","phonetic":"/maɪld/","pos":"adj.","meaningCN":"温和的；不严重的","tag":"核心","root":"源自古英语 milde（温和的）→ 温和的","exampleEN":"The region has a mild spring that draws many outdoor painters every year.","exampleCN":"这个地区春季温和，每年都吸引许多户外写生画家。","extra":""},{"chapter":1,"key":"1:110","id":110,"word":"heating","phonetic":"/ˈhiːtɪŋ/","pos":"n.","meaningCN":"供暖；暖气装置","tag":"高频","root":"heat（热）+ -ing（表示过程或设备）→ 供暖","exampleEN":"The old school was closed temporarily because its heating system failed.","exampleCN":"这所老学校因供暖系统故障而暂时关闭。","extra":""},{"chapter":1,"key":"1:111","id":111,"word":"moderate","phonetic":"/ˈmɒdərɪt/","pos":"adj.","meaningCN":"适度的；温和的；中等的","tag":"核心","root":"源自拉丁语 moderatus（有节制的）→ 适度的","exampleEN":"The coastal area enjoys moderate temperatures all year thanks to the ocean breeze.","exampleCN":"受海风影响，这个沿海区域全年温度适中。","extra":""},{"chapter":1,"key":"1:112","id":112,"word":"warm","phonetic":"/wɔːm/","pos":"adj.","meaningCN":"温暖的","tag":"核心","root":"源自古英语 wearm（温暖的）→ 温暖的","exampleEN":"A warm current from the south keeps the harbor free of ice in winter.","exampleCN":"一股来自南方的暖流使得港口在冬天不会结冰。","extra":""},{"chapter":1,"key":"1:113","id":113,"word":"thermal","phonetic":"/ˈθɜːməl/","pos":"adj.","meaningCN":"热量的","tag":"高频","root":"源自希腊语 thermē（热）→ 热量的","exampleEN":"Birds use thermal columns of warm air to soar higher without flapping wings.","exampleCN":"鸟类借助热空气柱上升，无需扇动翅膀就能飞得更高。","extra":""},{"chapter":1,"key":"1:114","id":114,"word":"tropics","phonetic":"/ˈtrɒpɪks/","pos":"n.","meaningCN":"热带地区","tag":"高频","root":"源自希腊语 tropikos（回转），与太阳回归线有关 → 热带","exampleEN":"Crops like bananas and pineapples grow well in the warm, wet tropics.","exampleCN":"香蕉和菠萝之类作物在温暖湿润的热带地区生长良好。","extra":""},{"chapter":1,"key":"1:115","id":115,"word":"arid","phonetic":"/ˈærɪd/","pos":"adj.","meaningCN":"干燥的，干旱的；枯燥的","tag":"高频","root":"源自拉丁语 aridus（干燥的）→ 干旱的","exampleEN":"Only a few types of tough grass can survive in this arid environment.","exampleCN":"只有寥寥几种坚韧的草类能在这片干燥环境中生存。","extra":""},{"chapter":1,"key":"1:116","id":116,"word":"moist","phonetic":"/mɔɪst/","pos":"adj.","meaningCN":"潮湿的，湿润的","tag":"高频","root":"源自古法语 moiste（潮湿的）→ 湿润的","exampleEN":"The forest floor stays cool and moist even during the hottest summer days.","exampleCN":"即使在最热的夏日，森林地面也保持凉爽湿润。","extra":""},{"chapter":1,"key":"1:117","id":117,"word":"damp","phonetic":"/dæmp/","pos":"adj.","meaningCN":"潮湿的，湿气重的","tag":"高频","root":"源自中古低地德语 damp（蒸汽）→ 潮湿的","exampleEN":"The basement remained damp after the pipe leak, so we put a heater down there.","exampleCN":"管道泄漏后地下室里仍然很潮，我们在下面放了一台暖炉。","extra":""},{"chapter":1,"key":"1:118","id":118,"word":"humid","phonetic":"/ˈhjuːmɪd/","pos":"adj.","meaningCN":"潮湿的，湿热的","tag":"高频","root":"源自拉丁语 humidus（湿的）→ 湿热的","exampleEN":"The humid air made even sitting still feel exhausting that afternoon.","exampleCN":"那天下午湿热的空气让人即使静静坐着也觉得疲惫。","extra":""},{"chapter":1,"key":"1:119","id":119,"word":"snowy","phonetic":"/ˈsnəʊi/","pos":"adj.","meaningCN":"下雪多的；被雪覆盖的","tag":"高频","root":"snow（雪）+ -y（形容词后缀）→ 下雪多的","exampleEN":"The snowy peaks could be seen from the valley even in early summer.","exampleCN":"即使在初夏，从山谷也能望见白雪皑皑的山峰。","extra":""},{"chapter":1,"key":"1:120","id":120,"word":"frost","phonetic":"/frɒst/","pos":"n.","meaningCN":"霜；霜冻；严寒","tag":"高频","root":"源自古英语 frost（霜）→ 霜冻","exampleEN":"A late frost in April damaged the early vegetable crops.","exampleCN":"四月的晚霜冻坏了早期蔬菜作物。","extra":""},{"chapter":1,"key":"1:121","id":121,"word":"hail","phonetic":"/heɪl/","pos":"n.","meaningCN":"雹，冰雹","tag":"高频","root":"源自古英语 hægl（冰雹）→ 冰雹","exampleEN":"The sudden burst of hail cracked the greenhouse windows and flattened the seedlings.","exampleCN":"突然降下的冰雹打裂了温室玻璃，压倒了幼苗。","extra":""},{"chapter":1,"key":"1:122","id":122,"word":"thaw","phonetic":"/θɔː/","pos":"v.","meaningCN":"解冻，融解，融化","tag":"高频","root":"源自古英语 þawian（融化）→ 解冻","exampleEN":"After a long winter, the rivers slowly began to thaw in early March.","exampleCN":"漫长的冬天过后，河流在三月初开始慢慢解冻。","extra":""},{"chapter":1,"key":"1:123","id":123,"word":"chill","phonetic":"/tʃɪl/","pos":"n.","meaningCN":"寒冷；害怕","tag":"高频","root":"源自古英语 cele（寒冷）→ 寒冷","exampleEN":"A sudden chill filled the room when the window blew open at night.","exampleCN":"夜里窗户被风吹开时，一阵寒意充满了房间。","extra":""},{"chapter":1,"key":"1:124","id":124,"word":"freeze","phonetic":"/friːz/","pos":"v.","meaningCN":"结冰；霜冻；严寒期","tag":"核心","root":"源自古英语 frēosan（结冰）→ 结冰","exampleEN":"The pond will freeze over if the night temperature keeps falling at this rate.","exampleCN":"如果夜间温度按这个速度继续下降，池塘就要结冰了。","extra":""},{"chapter":1,"key":"1:125","id":125,"word":"frigid","phonetic":"/ˈfrɪdʒɪd/","pos":"adj.","meaningCN":"寒冷的","tag":"高频","root":"源自拉丁语 frigidus（寒冷的）→ 寒冷的","exampleEN":"Explorers wrapped themselves in thick coats to bear the frigid polar wind.","exampleCN":"探险者裹着厚外套忍受极地的寒风。","extra":""},{"chapter":1,"key":"1:126","id":126,"word":"tremble","phonetic":"/ˈtrembəl/","pos":"v.","meaningCN":"战栗，颤抖","tag":"高频","root":"源自拉丁语 tremulus（颤抖的）→ 战栗","exampleEN":"Leaves on the tree began to tremble just before the earthquake struck.","exampleCN":"就在地震来临前，树上的叶子开始颤抖。","extra":""},{"chapter":1,"key":"1:127","id":127,"word":"shiver","phonetic":"/ˈʃɪvə/","pos":"v.","meaningCN":"颤抖，哆嗦，发抖","tag":"高频","root":"起源不确定，可能与中古英语 chiveren（发抖）相关 → 发抖","exampleEN":"The little dog sat in the cold rain and shivered until we brought it inside.","exampleCN":"小狗坐在冰冷的雨中发抖，直到我们把它抱进屋里。","extra":""},{"chapter":1,"key":"1:128","id":128,"word":"thunder","phonetic":"/ˈθʌndə/","pos":"n.","meaningCN":"雷；雷声","tag":"高频","root":"源自古英语 þunor（雷声）→ 雷","exampleEN":"A loud clap of thunder woke the whole campsite in the early morning.","exampleCN":"清晨一声响雷把整个营地都吵醒了。","extra":""},{"chapter":1,"key":"1:129","id":129,"word":"lightning","phonetic":"/ˈlaɪtnɪŋ/","pos":"n.","meaningCN":"闪电","tag":"高频","root":"lighten（发光）+ -ing（名词后缀）→ 闪电","exampleEN":"A flash of lightning split the dark sky in two for just a brief moment.","exampleCN":"一道闪电霎时间把黑暗的天空劈成两半。","extra":""},{"chapter":1,"key":"1:130","id":130,"word":"stormy","phonetic":"/ˈstɔːmi/","pos":"adj.","meaningCN":"有暴风雨的；争吵激烈的；波涛汹涌的","tag":"高频","root":"storm（暴风雨）+ -y（形容词后缀）→ 有暴风雨的","exampleEN":"The ship rocked heavily as the stormy sea tossed it from side to side.","exampleCN":"波涛汹涌的海面把船猛烈地左右摇晃。","extra":""},{"chapter":1,"key":"1:131","id":131,"word":"downpour","phonetic":"/ˈdaʊnpɔː/","pos":"n.","meaningCN":"倾盆大雨","tag":"高频","root":"down（向下）+ pour（倾倒）→ 倾盆大雨","exampleEN":"The sudden downpour flooded the streets within minutes.","exampleCN":"突如其来的倾盆大雨几分钟内就淹了街道。","extra":""},{"chapter":1,"key":"1:132","id":132,"word":"rainfall","phonetic":"/ˈreɪnfɔːl/","pos":"n.","meaningCN":"降雨量","tag":"高频","root":"rain（雨）+ fall（降落）→ 降雨量","exampleEN":"Heavy rainfall in the mountains led to a rapid rise in the river level.","exampleCN":"山区强降雨导致河水位迅速上涨。","extra":""},{"chapter":1,"key":"1:133","id":133,"word":"sprinkle","phonetic":"/ˈsprɪŋkl/","pos":"v.","meaningCN":"撒，洒；下小雨","tag":"高频","root":"起源不确定，可能与中古荷兰语 sprenkelen（洒）相关 → 洒","exampleEN":"Light rain began to sprinkle the windows as we sat by the fireplace.","exampleCN":"我们坐在壁炉旁时，小雨开始淅淅沥沥地打在窗户上。","extra":""},{"chapter":1,"key":"1:134","id":134,"word":"rainbow","phonetic":"/ˈreɪnbəʊ/","pos":"n.","meaningCN":"虹，彩虹","tag":"高频","root":"rain（雨）+ bow（弓）→ 彩虹","exampleEN":"A bright double rainbow appeared across the valley after the storm passed.","exampleCN":"暴风雨过后，一道明亮的双彩虹横跨山谷出现。","extra":""},{"chapter":1,"key":"1:135","id":135,"word":"shower","phonetic":"/ˈʃaʊə/","pos":"n.","meaningCN":"阵雨；淋浴","tag":"高频","root":"源自古英语 scūr（阵雨）→ 阵雨","exampleEN":"We waited in the tent for the shower to pass before hiking again.","exampleCN":"我们在帐篷里等阵雨过去再继续徒步。","extra":""},{"chapter":1,"key":"1:136","id":136,"word":"Celsius","phonetic":"/ˈselsiəs/","pos":"adj.","meaningCN":"摄氏的","tag":"识记","root":"以瑞典科学家 Anders Celsius 命名 → 摄氏","exampleEN":"Water boils at one hundred degrees Celsius under normal air pressure.","exampleCN":"在正常气压下，水在100摄氏度沸腾。","extra":""},{"chapter":1,"key":"1:137","id":137,"word":"temperature","phonetic":"/ˈtemprɪtʃə/","pos":"n.","meaningCN":"气温；体温；温度","tag":"核心","root":"源自拉丁语 temperatura（恰当比例混合）→ 温度","exampleEN":"The temperature dropped sharply after sunset, so we lit a campfire.","exampleCN":"日落之后温度骤降，我们便点燃了篝火。","extra":""},{"chapter":1,"key":"1:138","id":138,"word":"forecast","phonetic":"/ˈfɔːkɑːst/","pos":"n.","meaningCN":"预测，预报","tag":"核心","root":"fore（前，先）+ cast（扔）→ 提前抛出的信息 → 预报","exampleEN":"According to the forecast, clear skies will return to the coast by Friday.","exampleCN":"根据预报，周五之前沿海地区将恢复晴好天气。","extra":""},{"chapter":1,"key":"1:139","id":139,"word":"peak","phonetic":"/piːk/","pos":"n.","meaningCN":"山峰；顶点","tag":"核心","root":"起源不确定，可能来自中古低地德语 pēk（尖端）→ 山峰","exampleEN":"They reached the peak just as the sun rose over the horizon.","exampleCN":"他们正好在太阳从地平线升起时到达了山顶。","extra":""},{"chapter":1,"key":"1:140","id":140,"word":"mount","phonetic":"/maʊnt/","pos":"v.","meaningCN":"渐渐增加；爬上，登上","tag":"核心","root":"源自拉丁语 mons（山）→ 登上；增加","exampleEN":"The team slowly mounted the rocky slope as the wind grew stronger.","exampleCN":"队伍缓慢地爬上岩石山坡，风也越来越大。","extra":""},{"chapter":1,"key":"1:141","id":141,"word":"mountain","phonetic":"/ˈmaʊntɪn/","pos":"n.","meaningCN":"山，山岳，高山","tag":"核心","root":"源自拉丁语 mons（山）→ 山","exampleEN":"Snow on the mountain top had not melted even by late June.","exampleCN":"即使到了六月末，山顶的积雪也没有融化。","extra":""},{"chapter":1,"key":"1:142","id":142,"word":"range","phonetic":"/reɪndʒ/","pos":"n.","meaningCN":"山脉；范围","tag":"核心","root":"源自古法语 range（排，行）→ 山脉；范围","exampleEN":"The long mountain range stretches across the entire northern part of the country.","exampleCN":"这条长长的山脉横贯整个国家的北部。","extra":""},{"chapter":1,"key":"1:143","id":143,"word":"ridge","phonetic":"/rɪdʒ/","pos":"n.","meaningCN":"山脊，山脉","tag":"高频","root":"源自古英语 hrycg（背脊）→ 山脊","exampleEN":"They walked along a narrow ridge with steep drops on both sides.","exampleCN":"他们沿着一条两边都是陡坡的狭窄山脊行走。","extra":""},{"chapter":1,"key":"1:144","id":144,"word":"slope","phonetic":"/sləʊp/","pos":"n.","meaningCN":"山坡；斜坡","tag":"核心","root":"源自古英语 āslopen（滑离）→ 斜坡","exampleEN":"The ski school uses the gentler slope for beginners to practise.","exampleCN":"滑雪学校用较平缓的坡给初学者练习。","extra":""},{"chapter":1,"key":"1:145","id":145,"word":"valley","phonetic":"/ˈvæli/","pos":"n.","meaningCN":"山谷，溪谷","tag":"核心","root":"源自拉丁语 vallis（山谷）→ 山谷","exampleEN":"The green valley below was covered with orchards and small farms.","exampleCN":"下方的翠绿山谷遍布果园和小型农场。","extra":""},{"chapter":1,"key":"1:146","id":146,"word":"hillside","phonetic":"/ˈhɪlsaɪd/","pos":"n.","meaningCN":"山腰，山坡","tag":"高频","root":"hill（小山）+ side（侧面）→ 山腰","exampleEN":"Sheep grazed peacefully on the sunny hillside above the village.","exampleCN":"绵羊在村庄上方阳光明媚的山坡上安静地吃草。","extra":""},{"chapter":1,"key":"1:147","id":147,"word":"overlook","phonetic":"/ˌəʊvəˈlʊk/","pos":"v.","meaningCN":"俯瞰，远眺；未注意到","tag":"核心","root":"over（在上）+ look（看）→ 从上面往下看 → 俯瞰","exampleEN":"The viewing platform lets visitors overlook the entire lake and its islands.","exampleCN":"观景台让游客可以俯瞰整个湖泊及其岛屿。","extra":""},{"chapter":1,"key":"1:148","id":148,"word":"southern","phonetic":"/ˈsʌðən/","pos":"adj.","meaningCN":"南部的；南方的","tag":"核心","root":"south（南）+ -ern（表示方向的形容词后缀）→ 南部的","exampleEN":"The southern region of the island gets more sunshine than the north.","exampleCN":"岛屿的南部地区比北部日照更充足。","extra":""},{"chapter":1,"key":"1:149","id":149,"word":"southeast","phonetic":"/ˌsaʊθˈiːst/","pos":"n.","meaningCN":"东南方；东南部","tag":"高频","root":"south（南）+ east（东）→ 东南方","exampleEN":"The storm is currently moving toward the southeast at about fifteen miles per hour.","exampleCN":"暴风雨目前正以大约每小时十五英里的速度向东南方向移动。","extra":""},{"chapter":1,"key":"1:150","id":150,"word":"southwest","phonetic":"/ˌsaʊθˈwest/","pos":"n.","meaningCN":"西南方；西南部","tag":"高频","root":"south（南）+ west（西）→ 西南方","exampleEN":"The southwest monsoon brings heavy rain to this coastal town every summer.","exampleCN":"每年夏天，西南季风都会给这个沿海小镇带来大量降雨。","extra":""},{"chapter":1,"key":"1:151","id":151,"word":"northeast","phonetic":"/ˌnɔːθˈiːst/","pos":"n.","meaningCN":"东北方；东北部","tag":"高频","root":"north（北）+ east（东）→ 东北方","exampleEN":"Winds from the northeast pushed the thick fog out to sea by late morning.","exampleCN":"来自东北方向的风在上午快结束时将浓雾推向外海。","extra":""},{"chapter":1,"key":"1:152","id":152,"word":"northwest","phonetic":"/ˌnɔːθˈwest/","pos":"n.","meaningCN":"西北方；西北部","tag":"高频","root":"north（北）+ west（西）→ 西北方","exampleEN":"The northwest coast is famous for its rugged cliffs and winding trails.","exampleCN":"西北海岸以崎岖的悬崖和蜿蜒的小径闻名。","extra":""},{"chapter":1,"key":"1:153","id":153,"word":"eastern","phonetic":"/ˈiːstən/","pos":"adj.","meaningCN":"东部的；东方的","tag":"核心","root":"east（东）+ -ern（形容词后缀）→ 东部的","exampleEN":"The eastern part of the forest is home to a large deer population.","exampleCN":"这片森林的东部有大量鹿群栖息。","extra":""},{"chapter":1,"key":"1:154","id":154,"word":"oriental","phonetic":"/ˌɔːriˈentl/","pos":"adj.","meaningCN":"东方的（尤指中国和日本的）","tag":"高频","root":"源自拉丁语 oriens（升起；东方）→ 东方的","exampleEN":"The gallery displays a fine collection of oriental ceramics from various dynasties.","exampleCN":"这座画廊展出来自不同朝代的精美东方陶瓷藏品。","extra":""},{"chapter":1,"key":"1:155","id":155,"word":"inevitable","phonetic":"/ɪnˈevɪtəbl/","pos":"adj.","meaningCN":"不可避免的，必然的","tag":"核心","root":"in（不）+ evitable（可避免的）→ 不可避免的","exampleEN":"With rising sea levels, some erosion of coastal roads is almost inevitable.","exampleCN":"随着海平面上升，沿海道路遭到一些侵蚀几乎是不可避免的。","extra":""},{"chapter":1,"key":"1:156","id":156,"word":"irreversible","phonetic":"/ˌɪrɪˈvɜːsɪbəl/","pos":"adj.","meaningCN":"不可逆转的；不可挽回的","tag":"高频","root":"ir（不）+ re（回）+ vers（转）+ -ible（可……的）→ 不可逆转的","exampleEN":"The desertification of this once green land now seems irreversible.","exampleCN":"这片曾经绿意盎然的土地的荒漠化如今似乎不可逆转。","extra":""},{"chapter":1,"key":"1:157","id":157,"word":"irregularly","phonetic":"/ɪˈreɡjʊləli/","pos":"adv.","meaningCN":"不规则地；不合常规地","tag":"高频","root":"ir（不）+ regular（规律的）+ -ly（副词后缀）→ 不规则地","exampleEN":"Rain falls very irregularly across the region, causing frequent dry spells.","exampleCN":"整个地区的降雨非常不规律，导致频繁出现干旱期。","extra":""},{"chapter":1,"key":"1:158","id":158,"word":"inappropriate","phonetic":"/ˌɪnəˈprəʊpriɪt/","pos":"adj.","meaningCN":"不合适的","tag":"核心","root":"in（不）+ appropriate（恰当的）→ 不合适的","exampleEN":"The plan to build a factory so close to the river was clearly inappropriate.","exampleCN":"在如此靠近河流的地方建工厂的计划明显不合适。","extra":""},{"chapter":1,"key":"1:159","id":159,"word":"abnormal","phonetic":"/æbˈnɔːməl/","pos":"adj.","meaningCN":"不正常的，反常的；变态的","tag":"核心","root":"ab（不）+ normal（正常的）→ 不正常的","exampleEN":"Scientists were worried by the abnormal warming of the sea surface this spring.","exampleCN":"科学家对今春海面异常升温感到担忧。","extra":""},{"chapter":1,"key":"1:160","id":160,"word":"sediment","phonetic":"/ˈsedɪmənt/","pos":"n.","meaningCN":"沉淀物；沉积物","tag":"高频","root":"源自拉丁语 sedere（坐下；沉淀）→ 沉淀物","exampleEN":"The river delta was formed by sediment carried downstream over many centuries.","exampleCN":"这条河流三角洲是由数世纪不断带往下游的沉积物形成的。","extra":""},{"chapter":1,"key":"1:161","id":161,"word":"silt","phonetic":"/sɪlt/","pos":"n.","meaningCN":"淤泥，泥沙","tag":"高频","root":"起源不确定，可能与中古低地德语 sulte（盐碱地）相关 → 淤泥","exampleEN":"The removal of trees from the river bank has allowed more silt to enter the channel.","exampleCN":"河岸树木被清除后，更多泥沙进入了河道。","extra":""},{"chapter":1,"key":"1:162","id":162,"word":"muddy","phonetic":"/ˈmʌdi/","pos":"adj.","meaningCN":"泥泞的；浑浊的","tag":"高频","root":"mud（泥）+ -y（形容词后缀）→ 泥泞的","exampleEN":"After the heavy rain, the path became so muddy that we had to turn back.","exampleCN":"大雨过后，小路变得泥泞不堪，我们只好原路返回。","extra":""},{"chapter":1,"key":"1:163","id":163,"word":"clay","phonetic":"/kleɪ/","pos":"n.","meaningCN":"黏土，陶土","tag":"高频","root":"源自古英语 clǣg（黏土）→ 黏土","exampleEN":"Local artists dig clay from the riverbank to make traditional pottery.","exampleCN":"当地艺人从河岸挖取黏土制作传统陶器。","extra":""},{"chapter":1,"key":"1:164","id":164,"word":"dirt","phonetic":"/dɜːt/","pos":"n.","meaningCN":"污垢，灰尘；泥土","tag":"核心","root":"源自古诺斯语 drit（排泄物）→ 泥土；污垢","exampleEN":"The children returned from the forest hike with dirt on their boots and smiles.","exampleCN":"孩子们从森林徒步回来，靴子上沾满泥土，脸上带着笑容。","extra":""},{"chapter":1,"key":"1:165","id":165,"word":"rural","phonetic":"/ˈrʊərəl/","pos":"adj.","meaningCN":"农村的，乡村的；田园的","tag":"核心","root":"源自拉丁语 rus（乡村）+ -al（形容词后缀）→ 农村的","exampleEN":"Internet access in many rural areas remains slower than in large cities.","exampleCN":"许多农村地区的网络连接仍然比大城市慢。","extra":""},{"chapter":1,"key":"1:166","id":166,"word":"suburb","phonetic":"/ˈsʌbɜːb/","pos":"n.","meaningCN":"郊区，郊外，近郊","tag":"核心","root":"sub（接近）+ urb（城市）→ 城市附近的区域 → 郊区","exampleEN":"The factory was built on former farmland on the edge of the northern suburb.","exampleCN":"工厂建在北郊边缘以前的农田上。","extra":""},{"chapter":1,"key":"1:167","id":167,"word":"outskirts","phonetic":"/ˈaʊtskɜːts/","pos":"n.","meaningCN":"郊区，市郊","tag":"高频","root":"out（外）+ skirt（边缘）+ -s → 外围地区 → 市郊","exampleEN":"The nature reserve lies on the outskirts of the capital, about an hour away.","exampleCN":"自然保护区位于首都郊外约一小时路程处。","extra":""},{"chapter":1,"key":"1:168","id":168,"word":"remote","phonetic":"/rɪˈməʊt/","pos":"adj.","meaningCN":"遥远的；偏僻的；疏远的","tag":"核心","root":"源自拉丁语 remotus（移开的；遥远的）→ 遥远的","exampleEN":"The research team set up instruments at several remote mountain stations.","exampleCN":"研究团队在好几个偏远的山区站点安装了仪器。","extra":""},{"chapter":1,"key":"1:169","id":169,"word":"desolate","phonetic":"/ˈdesələt/","pos":"adj.","meaningCN":"荒凉的","tag":"高频","root":"源自拉丁语 desolatus（被遗弃的）→ 荒凉的","exampleEN":"The old mining town was now completely desolate, with only wind and dust.","exampleCN":"这座旧矿镇如今已完全荒凉，只剩风声和尘土。","extra":""},{"chapter":1,"key":"1:170","id":170,"word":"distant","phonetic":"/ˈdɪstənt/","pos":"adj.","meaningCN":"疏远的；遥远的","tag":"核心","root":"dis（分开）+ stant（站立）→ 站得分开的 → 遥远的","exampleEN":"We could hear the distant sound of waterfalls as we reached the forest edge.","exampleCN":"我们到达森林边缘时可以听见远处瀑布的声音。","extra":""},{"chapter":1,"key":"1:171","id":171,"word":"adjacent","phonetic":"/əˈdʒeɪsənt/","pos":"adj.","meaningCN":"邻近的，毗连的","tag":"高频","root":"源自拉丁语 adjacere（躺在附近）→ 邻近的","exampleEN":"The hotel and its adjacent nature trail attract many bird watchers.","exampleCN":"酒店和它邻近的自然小径吸引了许多观鸟者。","extra":""},{"chapter":1,"key":"1:172","id":172,"word":"toxic","phonetic":"/ˈtɒksɪk/","pos":"adj.","meaningCN":"有毒的","tag":"核心","root":"源自希腊语 toxon（弓；毒箭）→ 有毒的","exampleEN":"The lake was closed to fishing after tests showed toxic levels of mercury.","exampleCN":"检验显示湖泊汞含量有毒后，该湖被禁止捕鱼。","extra":""},{"chapter":1,"key":"1:173","id":173,"word":"pollution","phonetic":"/pəˈljuːʃən/","pos":"n.","meaningCN":"污染","tag":"核心","root":"pollute（弄脏）+ -ion（名词后缀）→ 污染","exampleEN":"Oil spills at sea are among the most difficult types of pollution to clean up.","exampleCN":"海上石油泄漏是最难清理的污染类型之一。","extra":""},{"chapter":1,"key":"1:174","id":174,"word":"pollutant","phonetic":"/pəˈljuːtənt/","pos":"n.","meaningCN":"污染物质","tag":"核心","root":"pollute（污染）+ -ant（表示物质的名词后缀）→ 污染物","exampleEN":"Researchers have identified several harmful pollutants in the city's drinking water.","exampleCN":"研究人员在该市饮用水中鉴定出了好几种有害污染物。","extra":""},{"chapter":1,"key":"1:175","id":175,"word":"contaminate","phonetic":"/kənˈtæmɪneɪt/","pos":"v.","meaningCN":"弄脏，污染","tag":"核心","root":"con（共同）+ tam（接触）+ in（里面）+ -ate（动词后缀）→ 污染","exampleEN":"Heavy rain washed the chemical waste into the river, contaminating the fish.","exampleCN":"大雨把化工废料冲进河中，污染了鱼类。","extra":""},{"chapter":1,"key":"1:176","id":176,"word":"geology","phonetic":"/dʒiˈɒlədʒi/","pos":"n.","meaningCN":"地质学；地质状况","tag":"高频","root":"geo（地球）+ logy（学说）→ 地质学","exampleEN":"Understanding the geology of the region helps engineers design safer tunnels.","exampleCN":"了解该地区的地质状况有助于工程师设计更安全的隧道。","extra":""},{"chapter":1,"key":"1:177","id":177,"word":"border","phonetic":"/ˈbɔːdə/","pos":"n.","meaningCN":"边界；边界地区；镶边","tag":"核心","root":"源自古法语 bordure（边缘）→ 边界","exampleEN":"The border between the two countries runs through thick forests and high ridges.","exampleCN":"两国之间的边界穿过茂密的森林和高高的山脊。","extra":""},{"chapter":1,"key":"1:178","id":178,"word":"margin","phonetic":"/ˈmɑːdʒɪn/","pos":"n.","meaningCN":"边缘；页边空白；余地","tag":"核心","root":"源自拉丁语 margo（边缘）→ 边缘；余地","exampleEN":"There is little margin left for error in the final week of the project.","exampleCN":"在项目最后一周几乎没有出错的余地了。","extra":""},{"chapter":1,"key":"1:179","id":179,"word":"fringe","phonetic":"/frɪndʒ/","pos":"n.","meaningCN":"边缘；刘海儿","tag":"高频","root":"源自拉丁语 fimbria（流苏；边缘）→ 边缘","exampleEN":"The town sits on the fringe of the vast desert, where dust storms are common.","exampleCN":"小镇坐落在大沙漠边缘，那里沙尘暴很常见。","extra":""},{"chapter":1,"key":"1:180","id":180,"word":"plate","phonetic":"/pleɪt/","pos":"n.","meaningCN":"板块；盘","tag":"高频","root":"源自希腊语 platus（扁平的）→ 平板 → 板块","exampleEN":"The collision of two massive plates gave rise to the great mountain belt.","exampleCN":"两块巨大板块的碰撞造就了这条宏伟的山脉带。","extra":""},{"chapter":1,"key":"1:181","id":181,"word":"debris","phonetic":"/ˈdebriː/","pos":"n.","meaningCN":"碎片，残骸","tag":"高频","root":"源自法语 débris（碎片）→ 残骸","exampleEN":"Emergency workers spent days clearing the debris after the landslide.","exampleCN":"紧急救援人员花了数天清理滑坡后的碎石残骸。","extra":""},{"chapter":1,"key":"1:182","id":182,"word":"crack","phonetic":"/kræk/","pos":"v.","meaningCN":"破裂；发出爆裂声","tag":"高频","root":"源自古英语 cracian（发出爆裂声）→ 破裂","exampleEN":"A thin crack in the dam wall had engineers working through the night.","exampleCN":"堤坝上一条细小的裂缝令工程师们连夜抢修。","extra":""},{"chapter":1,"key":"1:183","id":183,"word":"gap","phonetic":"/ɡæp/","pos":"n.","meaningCN":"缺口，裂缝；差距；空白","tag":"核心","root":"源自古诺斯语 gap（开口）→ 缺口","exampleEN":"The study found a wide gap between the predicted and actual rainfall totals.","exampleCN":"研究发现预测降雨总量与实际降雨总量之间存在巨大差距。","extra":""},{"chapter":1,"key":"1:184","id":184,"word":"splendid","phonetic":"/ˈsplendɪd/","pos":"adj.","meaningCN":"极好的；壮观的","tag":"核心","root":"源自拉丁语 splendidus（辉煌的）→ 壮观的","exampleEN":"From the flight window, we had a splendid view of the snow-capped volcanoes.","exampleCN":"从飞机窗口，我们看到了白雪覆盖的火山壮丽景色。","extra":""},{"chapter":1,"key":"1:185","id":185,"word":"grand","phonetic":"/ɡrænd/","pos":"adj.","meaningCN":"宏大的；豪华的，宏伟的；极好的","tag":"核心","root":"源自拉丁语 grandis（巨大的）→ 宏伟的","exampleEN":"The grand canyon stretched out below us, carved over millions of years.","exampleCN":"宏伟的大峡谷在我们下方延伸，是历经数百万年雕刻而成。","extra":""},{"chapter":1,"key":"1:186","id":186,"word":"magnificent","phonetic":"/mæɡˈnɪfɪsənt/","pos":"adj.","meaningCN":"壮丽的，宏伟的；令人印象深刻的","tag":"核心","root":"源自拉丁语 magnificus（伟大的）→ 壮丽的","exampleEN":"The magnificent waterfall drops three hundred metres straight into the pool below.","exampleCN":"壮丽的瀑布直落三百米坠入下方的水潭。","extra":""},{"chapter":1,"key":"1:187","id":187,"word":"super","phonetic":"/ˈsuːpə/","pos":"adj.","meaningCN":"超级的，极好的","tag":"核心","root":"源自拉丁语 super（上等的）→ 极好的","exampleEN":"The guide showed us a super spot on the hillside to watch the sunrise.","exampleCN":"向导指给我们山坡上一个绝佳地点观看日出。","extra":""},{"chapter":1,"key":"1:188","id":188,"word":"interesting","phonetic":"/ˈɪntrɪstɪŋ/","pos":"adj.","meaningCN":"有趣的；引人入胜的","tag":"核心","root":"interest（兴趣）+ -ing（形容词后缀）→ 有趣的","exampleEN":"It is interesting to compare the different weather patterns of these two regions.","exampleCN":"比较这两个地区不同的天气模式很有趣。","extra":""},{"chapter":1,"key":"1:189","id":189,"word":"dramatic","phonetic":"/drəˈmætɪk/","pos":"adj.","meaningCN":"戏剧的；引人注目的","tag":"核心","root":"源自希腊语 dramatikos（有关戏剧的）→ 引人注目的","exampleEN":"The beach has undergone dramatic changes after last winter's series of storms.","exampleCN":"经历了去年冬天一连串风暴后，这片海滩发生了显著变化。","extra":""},{"chapter":1,"key":"1:190","id":190,"word":"wilderness","phonetic":"/ˈwɪldənɪs/","pos":"n.","meaningCN":"荒野","tag":"高频","root":"wild（野生的）+ -ness（表示地带的词缀）→ 荒野","exampleEN":"They spent ten days hiking through a vast wilderness of frozen lakes and forests.","exampleCN":"他们花了十天在满是冻湖和森林的广阔荒野中徒步。","extra":""},{"chapter":1,"key":"1:191","id":191,"word":"desert","phonetic":"/ˈdezət/","pos":"n.","meaningCN":"沙漠","tag":"核心","root":"源自拉丁语 desertum（被遗弃的地方）→ 沙漠","exampleEN":"Cacti have shallow roots that spread wide to absorb rare desert rains.","exampleCN":"仙人掌有浅浅的宽根，以吸收沙漠中罕见的雨水。","extra":""},{"chapter":1,"key":"1:192","id":192,"word":"deforest","phonetic":"/diːˈfɒrɪst/","pos":"v.","meaningCN":"毁掉森林","tag":"识记","root":"de（除去）+ forest（森林）→ 毁林","exampleEN":"Large areas were deforested to make room for coffee and palm oil farms.","exampleCN":"大片森林被砍伐，为咖啡和棕榈油种植园腾出空间。","extra":""},{"chapter":1,"key":"1:193","id":193,"word":"barren","phonetic":"/ˈbærən/","pos":"adj.","meaningCN":"贫瘠的，荒芜的；不结果实的","tag":"高频","root":"源自古法语 baraigne（不能生育的）→ 贫瘠的","exampleEN":"Years of mining left the landscape barren and empty of plant life.","exampleCN":"多年采矿使这片土地贫瘠荒芜，寸草不生。","extra":""},{"chapter":1,"key":"1:194","id":194,"word":"fertile","phonetic":"/ˈfɜːtaɪl/","pos":"adj.","meaningCN":"肥沃的，富饶的","tag":"高频","root":"源自拉丁语 fertilis（结果实的）→ 肥沃的","exampleEN":"The volcanic soil around the mountain is dark and extremely fertile.","exampleCN":"火山周围的土壤呈黑色，极其肥沃。","extra":""},{"chapter":1,"key":"1:195","id":195,"word":"fertilise","phonetic":"/ˈfɜːtɪlaɪz/","pos":"v.","meaningCN":"施肥于","tag":"高频","root":"fertile（肥沃的）+ -ise（动词后缀）→ 施肥","exampleEN":"Farmers fertilise the rice fields before the rainy season arrives.","exampleCN":"农民在雨季来临前给稻田施肥。","extra":""},{"chapter":1,"key":"1:196","id":196,"word":"solar","phonetic":"/ˈsəʊlə/","pos":"adj.","meaningCN":"太阳的，日光的","tag":"核心","root":"源自拉丁语 sol（太阳）+ -ar（形容词后缀）→ 太阳的","exampleEN":"The village now relies on solar panels to power its small school and clinic.","exampleCN":"这个村庄现在靠太阳能板给小型学校和诊所供电。","extra":""},{"chapter":1,"key":"1:197","id":197,"word":"lunar","phonetic":"/ˈluːnə/","pos":"adj.","meaningCN":"月亮的，月球的","tag":"核心","root":"源自拉丁语 luna（月亮）+ -ar（形容词后缀）→ 月亮的","exampleEN":"The lunar surface is covered with craters, stones and fine grey dust.","exampleCN":"月球表面布满陨石坑、石块和灰色细尘。","extra":""},{"chapter":1,"key":"1:198","id":198,"word":"calendar","phonetic":"/ˈkælɪndə/","pos":"n.","meaningCN":"日历；历法","tag":"核心","root":"源自拉丁语 kalendarium（账本；记录）→ 日历","exampleEN":"The farmer marked the planting dates on a large paper calendar in the barn.","exampleCN":"农夫在谷仓里的大纸日历上标记了播种日期。","extra":""},{"chapter":1,"key":"1:199","id":199,"word":"sunrise","phonetic":"/ˈsʌnraɪz/","pos":"n.","meaningCN":"日出","tag":"核心","root":"sun（太阳）+ rise（升起）→ 日出","exampleEN":"The fishermen set out on their boats just before sunrise each day.","exampleCN":"渔民每天在日出前就乘小船出海。","extra":""},{"chapter":1,"key":"1:200","id":200,"word":"sunset","phonetic":"/ˈsʌnset/","pos":"n.","meaningCN":"日落","tag":"核心","root":"sun（太阳）+ set（落下）→ 日落","exampleEN":"We packed up our cameras after the last light of the sunset faded.","exampleCN":"日落的最后一道光消失后，我们收起了相机。","extra":""},{"chapter":1,"key":"1:201","id":201,"word":"eclipse","phonetic":"/ɪˈklɪps/","pos":"n.","meaningCN":"日食；月食","tag":"高频","root":"源自希腊语 ekleipsis（放弃；消失）→ 日/月食","exampleEN":"Hundreds of people gathered with special glasses to watch the solar eclipse.","exampleCN":"数百人戴着特制眼镜聚集在一起观看日食。","extra":""},{"chapter":1,"key":"1:202","id":202,"word":"dusk","phonetic":"/dʌsk/","pos":"n.","meaningCN":"黄昏，傍晚","tag":"核心","root":"源自古英语 dox（暗色）→ 黄昏","exampleEN":"Bats start to hunt for insects over the river shortly after dusk.","exampleCN":"黄昏刚过，蝙蝠就开始在河面上捕食昆虫。","extra":""},{"chapter":1,"key":"1:203","id":203,"word":"heaven","phonetic":"/ˈhevn/","pos":"n.","meaningCN":"天堂；极乐之地；天空","tag":"核心","root":"源自古英语 heofon（天；天堂）→ 天空；天堂","exampleEN":"The peak rose into a clear blue heaven without a single cloud in sight.","exampleCN":"山顶耸入清澈的蓝天，看不到一丝云彩。","extra":""},{"chapter":1,"key":"1:204","id":204,"word":"paradise","phonetic":"/ˈpærədaɪs/","pos":"n.","meaningCN":"天堂；乐园，福地","tag":"核心","root":"源自波斯语 pairidaeza（围墙花园）→ 乐园","exampleEN":"The tiny island with its white beaches looked like a tropical paradise.","exampleCN":"有着白色沙滩的小岛看上去像一个热带天堂。","extra":""},{"chapter":1,"key":"1:205","id":205,"word":"drip","phonetic":"/drɪp/","pos":"v.","meaningCN":"滴出（液体）；滴下","tag":"高频","root":"源自中古英语 dripen（滴下）→ 滴出","exampleEN":"Rainwater began to drip through a crack in the ceiling during the storm.","exampleCN":"暴风雨期间，雨水开始从天花板的裂缝中滴下。","extra":""},{"chapter":1,"key":"1:206","id":206,"word":"drown","phonetic":"/draʊn/","pos":"v.","meaningCN":"（使）淹死；浸泡","tag":"高频","root":"起源不确定，可能与古英语 druncnian（淹死）有关 → 淹没","exampleEN":"The low fields near the mouth of the river drown every few years when floods come.","exampleCN":"河口的低洼田地每隔几年就被洪水淹没一次。","extra":""},{"chapter":1,"key":"1:207","id":207,"word":"blow","phonetic":"/bləʊ/","pos":"v.","meaningCN":"吹；（风）吹","tag":"核心","root":"源自古英语 blāwan（吹）→ 吹","exampleEN":"Strong winds began to blow in from the sea, rattling the wooden shutters.","exampleCN":"强风开始从海上吹来，吹得木百叶窗咯吱作响。","extra":""},{"chapter":1,"key":"1:208","id":208,"word":"puff","phonetic":"/pʌf/","pos":"n.","meaningCN":"（吹出的）一股，一缕","tag":"高频","root":"源自中古英语 puff（一股气）→ 一股","exampleEN":"A puff of white steam rose from the kettle as the water started to boil.","exampleCN":"水开始沸腾时，水壶冒出一股白汽。","extra":""},{"chapter":1,"key":"1:209","id":209,"word":"gush","phonetic":"/ɡʌʃ/","pos":"v.","meaningCN":"涌出","tag":"高频","root":"可能源自中古英语 guschen（涌出）→ 涌出","exampleEN":"Muddy water gushed down the street when the neighbourhood drain burst.","exampleCN":"社区排水管爆裂时，泥水沿街涌下。","extra":""},{"chapter":1,"key":"1:210","id":210,"word":"dense","phonetic":"/dens/","pos":"adj.","meaningCN":"密集的；稠密的","tag":"核心","root":"源自拉丁语 densus（稠密的）→ 密集的","exampleEN":"The dense fog made it impossible to see the road signs clearly.","exampleCN":"浓雾让人无法看清路牌。","extra":""},{"chapter":1,"key":"1:211","id":211,"word":"intensity","phonetic":"/ɪnˈtensɪti/","pos":"n.","meaningCN":"强度；强烈","tag":"核心","root":"intense（强烈的）+ -ity（名词后缀）→ 强度","exampleEN":"The intensity of the midday sun forced the hikers to rest in the shade.","exampleCN":"正午强烈的阳光迫使徒步者在阴凉处休息。","extra":""},{"chapter":1,"key":"1:212","id":212,"word":"intensive","phonetic":"/ɪnˈtensɪv/","pos":"adj.","meaningCN":"加强的，集中的，密集的","tag":"核心","root":"源自拉丁语 intendere（拉紧；专注）+ -ive → 集中的","exampleEN":"The team carried out an intensive survey of the volcano after it showed activity.","exampleCN":"在火山出现活动迹象后，团队对其进行了密集勘测。","extra":""},{"chapter":1,"key":"1:213","id":213,"word":"emerge","phonetic":"/ɪˈmɜːdʒ/","pos":"v.","meaningCN":"浮现，露出；暴露","tag":"核心","root":"e（向外）+ merge（浸没）→ 从浸没中出来 → 浮现","exampleEN":"The tops of the old stone houses slowly emerged as the floodwater retreated.","exampleCN":"随着洪水退去，旧石屋的屋顶慢慢露了出来。","extra":""},{"chapter":1,"key":"1:214","id":214,"word":"flash","phonetic":"/flæʃ/","pos":"v.","meaningCN":"（使）闪光；（使）闪现；快速发送","tag":"核心","root":"可能源自中古英语 flasken（溅出；闪光）→ 闪光","exampleEN":"An alert notice was flashed to all port workers as the storm approached.","exampleCN":"暴风雨逼近时，警报通知被迅速发送给所有港口工人。","extra":""},{"chapter":1,"key":"1:215","id":215,"word":"float","phonetic":"/fləʊt/","pos":"v.","meaningCN":"漂浮；飘浮","tag":"核心","root":"源自古英语 flotian（漂浮）→ 漂浮","exampleEN":"Thin sheets of ice still float on the surface of the lake in early spring.","exampleCN":"早春时节，薄冰层仍漂浮在湖面上。","extra":""},{"chapter":1,"key":"1:216","id":216,"word":"environment","phonetic":"/ɪnˈvaɪrənmənt/","pos":"n.","meaningCN":"自然环境；环境，周围状况","tag":"核心","root":"environ（环绕）+ -ment（名词后缀）→ 环境","exampleEN":"Scientists urged governments to invest more in protecting the coastal environment.","exampleCN":"科学家敦促政府加大对沿海环境保护的投入。","extra":""},{"chapter":1,"key":"1:217","id":217,"word":"surrounding","phonetic":"/səˈraʊndɪŋ/","pos":"adj.","meaningCN":"周围的，附近的","tag":"核心","root":"surround（围绕）+ -ing（形容词后缀）→ 周围的","exampleEN":"The building and its surrounding fields were swallowed by the rising water.","exampleCN":"建筑物及其周围的田地被上涨的洪水吞没。","extra":""},{"chapter":1,"key":"1:218","id":218,"word":"condition","phonetic":"/kənˈdɪʃən/","pos":"n.","meaningCN":"条件；情况，状态","tag":"核心","root":"源自拉丁语 condicio（协议；条件）→ 条件","exampleEN":"Roads were closed because of dangerously poor driving conditions after the ice storm.","exampleCN":"冰暴过后，由于驾驶条件极差且危险，道路被封闭。","extra":""},{"chapter":1,"key":"1:219","id":219,"word":"situation","phonetic":"/ˌsɪtjuˈeɪʃən/","pos":"n.","meaningCN":"情况，处境，形势","tag":"核心","root":"源自拉丁语 situs（位置）+ -ation（名词后缀）→ 处境","exampleEN":"The situation on the flooded plain was described by officials as critical.","exampleCN":"官员称，被淹没平原上的情况非常危急。","extra":""},{"chapter":1,"key":"1:220","id":220,"word":"nature","phonetic":"/ˈneɪtʃə/","pos":"n.","meaningCN":"大自然；本性；性质","tag":"核心","root":"源自拉丁语 natura（出生；本性）→ 自然","exampleEN":"Walking in nature helps many city workers reduce their daily stress levels.","exampleCN":"在大自然中散步有助于许多城市工作者降低日常压力。","extra":""},{"chapter":1,"key":"1:221","id":221,"word":"natural","phonetic":"/ˈnætʃrəl/","pos":"adj.","meaningCN":"自然的；天然的","tag":"核心","root":"nature（自然）+ -al（形容词后缀）→ 自然的","exampleEN":"The reserve was created to keep this unique landscape in its natural state.","exampleCN":"建立保护区是为了让这片独特地貌保持自然原貌。","extra":""},{"chapter":1,"key":"1:222","id":222,"word":"artificial","phonetic":"/ˌɑːtɪˈfɪʃəl/","pos":"adj.","meaningCN":"人造的","tag":"核心","root":"art（技巧；人工）+ fic（制作）+ -ial → 人造的","exampleEN":"An artificial lake was built to provide drinking water for the growing town.","exampleCN":"修建了一座人工湖为不断扩大的城镇提供饮用水。","extra":""},{"chapter":1,"key":"1:223","id":223,"word":"synthetic","phonetic":"/sɪnˈθetɪk/","pos":"adj.","meaningCN":"人造的，合成的","tag":"高频","root":"syn（一起）+ thesis（放置）→ 合成 → 人造的","exampleEN":"The jacket is filled with a synthetic material that stays warm even when wet.","exampleCN":"这件夹克填充了一种即使湿了也能保暖的合成材料。","extra":""},{"chapter":1,"key":"1:224","id":224,"word":"petrol","phonetic":"/ˈpetrəl/","pos":"n.","meaningCN":"汽油","tag":"高频","root":"源自法语 pétrole（石油）→ 汽油","exampleEN":"The generator ran out of petrol after working for two hours straight.","exampleCN":"发电机连续工作两小时后汽油耗尽。","extra":""},{"chapter":1,"key":"1:225","id":225,"word":"gas","phonetic":"/ɡæs/","pos":"n.","meaningCN":"气体；汽油","tag":"核心","root":"由比利时化学家 Van Helmont 基于希腊语 chaos（混沌）新造的词 → 气体","exampleEN":"A faint smell of gas from the stove suggested the pipe needed checking.","exampleCN":"炉子里隐隐有股煤气味，说明管道需要检查。","extra":""},{"chapter":1,"key":"1:226","id":226,"word":"gasoline","phonetic":"/ˈɡæsəliːn/","pos":"n.","meaningCN":"汽油","tag":"高频","root":"gas（气体）+ ol + -ine（化学后缀）→ 汽油","exampleEN":"The price of gasoline in coastal towns often rises during the summer months.","exampleCN":"沿海城镇的汽油价格在夏季几个月里经常上涨。","extra":""},{"chapter":1,"key":"1:227","id":227,"word":"petroleum","phonetic":"/pɪˈtrəʊliəm/","pos":"n.","meaningCN":"石油","tag":"高频","root":"petr（石头）+ oleum（油）→ 石里的油 → 石油","exampleEN":"Petroleum remains one of the most traded natural resources in the world.","exampleCN":"石油仍然是世界上交易量最大的自然资源之一。","extra":""}],"2":[{"chapter":2,"key":"2:1","id":1,"word":"photosynthesis","phonetic":"/ˌfəʊtəʊˈsɪnθəsɪs/","pos":"n.","meaningCN":"光合作用","tag":"核心","root":"photo（光）+ synthesis（合成）→ 用光合成","exampleEN":"Without photosynthesis, plants would not be able to produce the food they need.","exampleCN":"没有光合作用，植物就无法制造自身所需的食物。","extra":""},{"chapter":2,"key":"2:2","id":2,"word":"respire","phonetic":"/rɪˈspaɪə/","pos":"v.","meaningCN":"呼吸","tag":"高频","root":"源自拉丁语 respirare（重新呼吸）→ 呼吸","exampleEN":"All living creatures that respire need oxygen to turn food into energy.","exampleCN":"所有会呼吸的生物都需要氧气来将食物转化为能量。","extra":""},{"chapter":2,"key":"2:3","id":3,"word":"dioxide","phonetic":"/daɪˈɒksaɪd/","pos":"n.","meaningCN":"二氧化物","tag":"高频","root":"di（二）+ oxide（氧化物）→ 二氧化物","exampleEN":"Sulfur dioxide is a gas released by some factories that can harm the lungs.","exampleCN":"二氧化硫是一些工厂排放的一种气体，会伤害肺部。","extra":""},{"chapter":2,"key":"2:4","id":4,"word":"vegetation","phonetic":"/ˌvedʒəˈteɪʃən/","pos":"n.","meaningCN":"植物，草木","tag":"核心","root":"源自拉丁语 vegetare（使生长）→ 植物","exampleEN":"The hills were once covered in thick vegetation, but most of it has now been cut down.","exampleCN":"这些山丘曾经覆盖着茂密的植被，但如今大部分已被砍伐。","extra":""},{"chapter":2,"key":"2:5","id":5,"word":"herb","phonetic":"/hɜːb/","pos":"n.","meaningCN":"药草；香草","tag":"高频","root":"源自拉丁语 herba（草）→ 药草","exampleEN":"She grows several herbs, like rosemary and basil, on her kitchen windowsill.","exampleCN":"她在厨房窗台上种了好几种香草，比如迷迭香和罗勒。","extra":""},{"chapter":2,"key":"2:6","id":6,"word":"perennial","phonetic":"/pəˈreniəl/","pos":"n.","meaningCN":"多年生植物","tag":"高频","root":"per（贯穿）+ enn（年）+ ial → 贯穿全年的 → 多年生","exampleEN":"Unlike most garden flowers, these perennials return year after year with little care.","exampleCN":"和大多数花园花卉不同，这些多年生植物无需过多照料，每年都会重新生长。","extra":""},{"chapter":2,"key":"2:7","id":7,"word":"botany","phonetic":"/ˈbɒtəni/","pos":"n.","meaningCN":"植物学","tag":"高频","root":"源自希腊语 botanē（植物）→ 植物学","exampleEN":"Her love of wildflowers led her to study botany at university.","exampleCN":"她对野花的热爱促使她进入大学攻读植物学。","extra":""},{"chapter":2,"key":"2:8","id":8,"word":"ecology","phonetic":"/iˈkɒlədʒi/","pos":"n.","meaningCN":"生态学；生态","tag":"核心","root":"eco（家；环境）+ logy（学说）→ 生态学","exampleEN":"The ecology of the reef is so delicate that even a small change in temperature can damage it.","exampleCN":"珊瑚礁的生态非常脆弱，即使微小的温度变化也可能造成破坏。","extra":""},{"chapter":2,"key":"2:9","id":9,"word":"ecosystem","phonetic":"/ˈiːkəʊˌsɪstəm/","pos":"n.","meaningCN":"生态系统","tag":"核心","root":"eco（生态）+ system（系统）→ 生态系统","exampleEN":"The entire ecosystem of the lake was affected by the chemical waste.","exampleCN":"整个湖泊的生态系统都受到了化工废料的影响。","extra":""},{"chapter":2,"key":"2:10","id":10,"word":"eco-friendly","phonetic":"/ˈiːkəʊˌfrendli/","pos":"adj.","meaningCN":"对生态环境友好的","tag":"核心","root":"eco（生态）+ friendly（友好的）→ 环保的","exampleEN":"More shoppers now choose eco-friendly bags made of cloth instead of plastic.","exampleCN":"如今更多顾客选择布制的环保袋来代替塑料袋。","extra":""},{"chapter":2,"key":"2:11","id":11,"word":"horticulture","phonetic":"/ˈhɔːtɪˌkʌltʃə/","pos":"n.","meaningCN":"园艺学；园艺","tag":"识记","root":"horti（花园）+ culture（培育）→ 园艺学","exampleEN":"The city runs a horticulture programme that teaches residents how to grow their own food.","exampleCN":"该市开办了一个园艺项目，教居民如何自己种植食物。","extra":""},{"chapter":2,"key":"2:12","id":12,"word":"organism","phonetic":"/ˈɔːɡənɪzəm/","pos":"n.","meaningCN":"有机体，生物","tag":"核心","root":"organ（器官）+ ism（表示系统）→ 有机体","exampleEN":"A single drop of pond water can contain thousands of tiny organisms.","exampleCN":"一滴池塘水中就能含有数千个微小生物。","extra":""},{"chapter":2,"key":"2:13","id":13,"word":"genetics","phonetic":"/dʒəˈnetɪks/","pos":"n.","meaningCN":"遗传学","tag":"高频","root":"gene（基因）+ tics（学科）→ 遗传学","exampleEN":"Thanks to advances in genetics, farmers can now breed crops that resist drought.","exampleCN":"由于遗传学的进步，农民如今可以培育抗旱作物。","extra":""},{"chapter":2,"key":"2:14","id":14,"word":"mutation","phonetic":"/mjuːˈteɪʃən/","pos":"n.","meaningCN":"突变，变异","tag":"高频","root":"源自拉丁语 mutare（改变）→ 突变","exampleEN":"A single gene mutation can sometimes give a plant resistance to a deadly disease.","exampleCN":"单个基因突变有时能让植物对致命病害产生抗性。","extra":""},{"chapter":2,"key":"2:15","id":15,"word":"variation","phonetic":"/ˌveəriˈeɪʃən/","pos":"n.","meaningCN":"变种；变异","tag":"核心","root":"vary（变化）+ ation（名词后缀）→ 变异","exampleEN":"Natural variation in leaf shape helps botanists identify different tree types.","exampleCN":"叶片形状的自然变异有助于植物学家辨认不同的树种。","extra":""},{"chapter":2,"key":"2:16","id":16,"word":"diversity","phonetic":"/daɪˈvɜːsɪti/","pos":"n.","meaningCN":"多样性","tag":"核心","root":"diverse（不同的）+ ity（性质）→ 多样性","exampleEN":"The diversity of plants in a rainforest is far greater than in any other land habitat.","exampleCN":"雨林里的植物多样性远高于任何其他陆地栖息地。","extra":""},{"chapter":2,"key":"2:17","id":17,"word":"hybridisation","phonetic":"/haɪˌbrɪdaɪˈzeɪʃən/","pos":"n.","meaningCN":"杂交","tag":"识记","root":"hybrid（杂种）+ isation（过程）→ 杂交","exampleEN":"Hybridisation of wild and farmed rice has created stronger and more productive varieties.","exampleCN":"野生稻与栽培稻的杂交已经创造出更强壮、更高产的品种。","extra":""},{"chapter":2,"key":"2:18","id":18,"word":"classify","phonetic":"/ˈklæsɪfaɪ/","pos":"v.","meaningCN":"分类","tag":"核心","root":"class（类别）+ ify（动词后缀）→ 分类","exampleEN":"Scientists classify flowering plants into more than 300 families.","exampleCN":"科学家把开花植物分为三百多个科。","extra":""},{"chapter":2,"key":"2:19","id":19,"word":"reproduce","phonetic":"/ˌriːprəˈdjuːs/","pos":"v.","meaningCN":"繁殖","tag":"核心","root":"re（再）+ produce（产生）→ 繁殖","exampleEN":"Many plants can reproduce both by seeds and by sending out shoots.","exampleCN":"许多植物既可以通过种子繁殖，也可以通过抽出新芽来繁殖。","extra":""},{"chapter":2,"key":"2:20","id":20,"word":"evolve","phonetic":"/ɪˈvɒlv/","pos":"v.","meaningCN":"进化；（使）发展","tag":"核心","root":"e（向外）+ volve（滚；转）→ 向外展开 → 进化","exampleEN":"Over millions of years, some ferns evolved into towering trees.","exampleCN":"经过数百万年，一些蕨类植物进化成了高大的乔木。","extra":""},{"chapter":2,"key":"2:21","id":21,"word":"fluctuate","phonetic":"/ˈflʌktʃueɪt/","pos":"v.","meaningCN":"波动，起伏","tag":"高频","root":"源自拉丁语 fluctus（波浪）→ 波动","exampleEN":"Crop prices tend to fluctuate greatly depending on the weather.","exampleCN":"作物价格往往会因天气原因大幅波动。","extra":""},{"chapter":2,"key":"2:22","id":22,"word":"reclaim","phonetic":"/rɪˈkleɪm/","pos":"v.","meaningCN":"开垦，开拓，利用","tag":"高频","root":"re（回）+ claim（喊；索取）→ 收回 → 开垦","exampleEN":"Local farmers worked together to reclaim the marshland for rice planting.","exampleCN":"当地农民齐心协力开垦沼泽地用于种植水稻。","extra":""},{"chapter":2,"key":"2:23","id":23,"word":"cultivate","phonetic":"/ˈkʌltɪveɪt/","pos":"v.","meaningCN":"耕作；培养","tag":"核心","root":"源自拉丁语 cultivare（耕种）→ 耕作","exampleEN":"It takes years of effort to cultivate a healthy and productive orchard.","exampleCN":"要花数年时间才能培育出一片健康高产的果园。","extra":""},{"chapter":2,"key":"2:24","id":24,"word":"sow","phonetic":"/səʊ/","pos":"v.","meaningCN":"播种","tag":"高频","root":"源自古英语 sāwan（播种）→ 播种","exampleEN":"The best time to sow carrot seeds outdoors is late spring.","exampleCN":"胡萝卜种子最佳的户外播种时间是春末。","extra":""},{"chapter":2,"key":"2:25","id":25,"word":"harvest","phonetic":"/ˈhɑːvɪst/","pos":"v.","meaningCN":"收割","tag":"核心","root":"源自古英语 hærfest（秋天；收获期）→ 收割","exampleEN":"They hire extra workers every autumn to harvest the apple crop.","exampleCN":"他们每年秋天都额外雇人收割苹果。","extra":""},{"chapter":2,"key":"2:26","id":26,"word":"pluck","phonetic":"/plʌk/","pos":"v.","meaningCN":"采，摘","tag":"高频","root":"源自古英语 pluccian（拔）→ 采摘","exampleEN":"She carefully plucked a few ripe strawberries and placed them in her basket.","exampleCN":"她小心地摘下几颗熟透的草莓放进篮子里。","extra":""},{"chapter":2,"key":"2:27","id":27,"word":"pick","phonetic":"/pɪk/","pos":"v.","meaningCN":"拾；摘","tag":"核心","root":"源自古英语 pician（捡；摘）→ 拾；摘","exampleEN":"We went to the farm to pick fresh berries for the family picnic.","exampleCN":"我们去了农场采摘新鲜浆果，为家庭野餐做准备。","extra":""},{"chapter":2,"key":"2:28","id":28,"word":"yield","phonetic":"/jiːld/","pos":"v.","meaningCN":"出产；屈服","tag":"核心","root":"源自古英语 gieldan（支付；产出）→ 出产","exampleEN":"With good rainfall, the land can yield two full harvests in a single year.","exampleCN":"雨水充足的话，这块地一年能产出两季收成。","extra":""},{"chapter":2,"key":"2:29","id":29,"word":"rear","phonetic":"/rɪə/","pos":"v.","meaningCN":"培养，抚养；饲养","tag":"高频","root":"源自古英语 rǣran（举起；养育）→ 饲养","exampleEN":"The family rears a small herd of goats on the hills behind their house.","exampleCN":"这家人在屋后的山上饲养了一小群山羊。","extra":""},{"chapter":2,"key":"2:30","id":30,"word":"arable","phonetic":"/ˈærəbəl/","pos":"adj.","meaningCN":"适于耕种的","tag":"高频","root":"源自拉丁语 arare（犁地）→ 适于耕种的","exampleEN":"Only a small fraction of the country's land is arable and suitable for wheat.","exampleCN":"该国只有一小部分土地适合耕种小麦。","extra":""},{"chapter":2,"key":"2:31","id":31,"word":"plough","phonetic":"/plaʊ/","pos":"n.","meaningCN":"犁","tag":"高频","root":"源自古英语 plōg（犁）→ 犁","exampleEN":"The old wooden plough was replaced by a modern steel one last season.","exampleCN":"上个季节，那把旧木犁被现代钢犁取代了。","extra":""},{"chapter":2,"key":"2:32","id":32,"word":"spade","phonetic":"/speɪd/","pos":"n.","meaningCN":"铲，锹","tag":"低频","root":"源自古英语 spadu（铲子）→ 铲","exampleEN":"He used a sharp spade to dig neat rows for the vegetable seeds.","exampleCN":"他用一把锋利的铲子为蔬菜种子挖出了整齐的垄沟。","extra":""},{"chapter":2,"key":"2:33","id":33,"word":"rake","phonetic":"/reɪk/","pos":"n.","meaningCN":"耙子","tag":"低频","root":"源自古诺斯语 reka（耙）→ 耙子","exampleEN":"Leaves covered the lawn, so she took out the rake and began clearing them away.","exampleCN":"草坪上铺满了落叶，她便拿出耙子开始清理。","extra":""},{"chapter":2,"key":"2:34","id":34,"word":"stack","phonetic":"/stæk/","pos":"n.","meaningCN":"堆，垛","tag":"高频","root":"源自古诺斯语 stakkr（堆）→ 堆","exampleEN":"A tall stack of firewood stood ready beside the barn for winter.","exampleCN":"谷仓旁整齐地堆着一大堆劈好的柴，供冬天使用。","extra":""},{"chapter":2,"key":"2:35","id":35,"word":"heap","phonetic":"/hiːp/","pos":"n.","meaningCN":"（大而杂乱的）堆","tag":"高频","root":"源自古英语 hēap（堆）→ 堆","exampleEN":"A heap of fallen apples lay under the old tree, attracting wasps.","exampleCN":"老树下堆着大堆落果，引来许多黄蜂。","extra":""},{"chapter":2,"key":"2:36","id":36,"word":"bundle","phonetic":"/ˈbʌndl/","pos":"n.","meaningCN":"捆，包，束","tag":"高频","root":"源自古英语 byndele（捆绑）→ 捆","exampleEN":"She tied the dried herbs into small bundles and hung them in the kitchen.","exampleCN":"她把干草药扎成小捆，挂在厨房里。","extra":""},{"chapter":2,"key":"2:37","id":37,"word":"bunch","phonetic":"/bʌntʃ/","pos":"n.","meaningCN":"一束（花），一串（钥匙）","tag":"高频","root":"可能源自中古英语 bunche（捆）→ 一束","exampleEN":"He arrived at the door with a bunch of wildflowers he had picked along the path.","exampleCN":"他捧着一扎沿路采来的野花来到门前。","extra":""},{"chapter":2,"key":"2:38","id":38,"word":"vase","phonetic":"/vɑːz/","pos":"n.","meaningCN":"瓶，花瓶","tag":"低频","root":"源自法语 vase（花瓶）→ 花瓶","exampleEN":"She placed the tulips in a tall glass vase on the dining table.","exampleCN":"她把郁金香插在餐桌上一只高高的玻璃花瓶里。","extra":""},{"chapter":2,"key":"2:39","id":39,"word":"sunlight","phonetic":"/ˈsʌnlaɪt/","pos":"n.","meaningCN":"阳光","tag":"核心","root":"sun（太阳）+ light（光）→ 阳光","exampleEN":"The seedlings need at least six hours of direct sunlight daily.","exampleCN":"秧苗每天至少需要六小时直射阳光。","extra":""},{"chapter":2,"key":"2:40","id":40,"word":"short-day","phonetic":"/ˈʃɔːt deɪ/","pos":"adj.","meaningCN":"短日照的","tag":"识记","root":"short（短）+ day（日）→ 短日照的","exampleEN":"Chrysanthemums are short-day plants that only bloom when nights grow longer.","exampleCN":"菊花是短日照植物，只有当夜晚变长时才会开花。","extra":""},{"chapter":2,"key":"2:41","id":41,"word":"shade-tolerant","phonetic":"/ˈʃeɪdˌtɒlərənt/","pos":"adj.","meaningCN":"耐阴的","tag":"识记","root":"shade（阴凉）+ tolerant（忍受的）→ 耐阴的","exampleEN":"Ferns are shade-tolerant and can thrive under the thick canopy of the forest.","exampleCN":"蕨类植物耐阴，能在茂密的森林树冠下茂盛生长。","extra":""},{"chapter":2,"key":"2:42","id":42,"word":"fungus","phonetic":"/ˈfʌŋɡəs/","pos":"n.","meaningCN":"真菌","tag":"高频","root":"源自拉丁语 fungus（蘑菇）→ 真菌","exampleEN":"A strange orange fungus began growing on the old wooden fence post.","exampleCN":"一根旧木栅栏柱上长出了奇怪的橙色真菌。","extra":""},{"chapter":2,"key":"2:43","id":43,"word":"mould","phonetic":"/məʊld/","pos":"n.","meaningCN":"霉菌","tag":"高频","root":"可能源自古诺斯语 mygla（发霉）→ 霉菌","exampleEN":"Bread left in a warm, damp place will quickly grow mould.","exampleCN":"面包放在温暖潮湿的地方很快就会长出霉菌。","extra":""},{"chapter":2,"key":"2:44","id":44,"word":"pollen","phonetic":"/ˈpɒlən/","pos":"n.","meaningCN":"花粉","tag":"高频","root":"源自拉丁语 pollen（细粉）→ 花粉","exampleEN":"Bees carry pollen from blossom to blossom, helping trees produce fruit.","exampleCN":"蜜蜂在花朵间传播花粉，帮助果树结出果实。","extra":""},{"chapter":2,"key":"2:45","id":45,"word":"germinate","phonetic":"/ˈdʒɜːmɪneɪt/","pos":"v.","meaningCN":"（使）发芽；开始生长","tag":"高频","root":"源自拉丁语 germinare（发芽）→ 发芽","exampleEN":"The seeds need warmth and moisture to germinate indoors before spring arrives.","exampleCN":"这些种子需要在春天到来前在室内靠温暖和湿气发芽。","extra":""},{"chapter":2,"key":"2:46","id":46,"word":"seed","phonetic":"/siːd/","pos":"n.","meaningCN":"种子，籽；萌芽","tag":"核心","root":"源自古英语 sǣd（种子）→ 种子","exampleEN":"She saved some seeds from last year's best tomatoes to plant again.","exampleCN":"她从去年最好的番茄里留了一些种子以便再次种植。","extra":""},{"chapter":2,"key":"2:47","id":47,"word":"burgeon","phonetic":"/ˈbɜːdʒən/","pos":"n.","meaningCN":"嫩枝，新芽","tag":"低频","root":"源自古法语 burjon（嫩芽）→ 嫩枝","exampleEN":"Tiny burgeons appeared on the willow branches just days after the frost ended.","exampleCN":"霜冻刚过去几天，柳树枝上就冒出了小小的新芽。","extra":""},{"chapter":2,"key":"2:48","id":48,"word":"bud","phonetic":"/bʌd/","pos":"n.","meaningCN":"芽，苞，蓓蕾","tag":"高频","root":"可能源自中古英语 budde（芽）→ 蓓蕾","exampleEN":"The rose buds begin to open in May, filling the garden with their scent.","exampleCN":"玫瑰花蕾五月开始绽放，让花园充满芬芳。","extra":""},{"chapter":2,"key":"2:49","id":49,"word":"flower","phonetic":"/ˈflaʊə/","pos":"v.","meaningCN":"开花","tag":"核心","root":"源自拉丁语 flos（花）→ 开花","exampleEN":"These bulbs flower in late spring, producing bright red petals.","exampleCN":"这些球茎植物迟至春末开花，开出鲜红花瓣。","extra":""},{"chapter":2,"key":"2:50","id":50,"word":"blossom","phonetic":"/ˈblɒsəm/","pos":"v.","meaningCN":"开花","tag":"高频","root":"源自古英语 blōstm（花）→ 开花","exampleEN":"The park's cherry trees blossom in early April, drawing large crowds.","exampleCN":"公园的樱花树在四月初开花，吸引了大批游客。","extra":""},{"chapter":2,"key":"2:51","id":51,"word":"bloom","phonetic":"/bluːm/","pos":"n.","meaningCN":"花朵","tag":"高频","root":"源自古诺斯语 blóm（花）→ 花朵","exampleEN":"The daisies are now in full bloom across the meadow.","exampleCN":"草地上雏菊正盛开着。","extra":""},{"chapter":2,"key":"2:52","id":52,"word":"scent","phonetic":"/sent/","pos":"n.","meaningCN":"气味；香味","tag":"高频","root":"源自拉丁语 sentire（感觉到）→ 气味","exampleEN":"The sweet scent of fresh lavender drifted through the open window.","exampleCN":"新鲜薰衣草的甜香从敞开的窗户飘进来。","extra":""},{"chapter":2,"key":"2:53","id":53,"word":"aromatic","phonetic":"/ˌærəˈmætɪk/","pos":"adj.","meaningCN":"芳香的","tag":"高频","root":"源自希腊语 aroma（香料）→ 芳香的","exampleEN":"Basil and mint are aromatic plants used to add flavour to many dishes.","exampleCN":"罗勒和薄荷是芳香植物，被用来为许多菜肴增添风味。","extra":""},{"chapter":2,"key":"2:54","id":54,"word":"ripen","phonetic":"/ˈraɪpən/","pos":"v.","meaningCN":"（使）成熟","tag":"高频","root":"ripe（成熟的）+ en（动词后缀）→ 成熟","exampleEN":"Tomatoes need plenty of sun to ripen fully on the vine.","exampleCN":"番茄需要充足的阳光才能在藤上完全成熟。","extra":""},{"chapter":2,"key":"2:55","id":55,"word":"fruit","phonetic":"/fruːt/","pos":"v.","meaningCN":"结果实","tag":"核心","root":"源自拉丁语 fructus（果实）→ 结果实","exampleEN":"The pear tree has fruited well this year, its branches bending low.","exampleCN":"今年梨树果实累累，树枝都被压弯了。","extra":""},{"chapter":2,"key":"2:56","id":56,"word":"wither","phonetic":"/ˈwɪðə/","pos":"v.","meaningCN":"（使）枯萎","tag":"高频","root":"源自古英语 wiðerian（枯萎）→ 枯萎","exampleEN":"The long hot summer caused many garden plants to wither before they could bloom.","exampleCN":"漫长炎热的夏天让许多花园植物还没来得及开花就枯萎了。","extra":""},{"chapter":2,"key":"2:57","id":57,"word":"decompose","phonetic":"/ˌdiːkəmˈpəʊz/","pos":"v.","meaningCN":"（使）分解；（使）腐烂","tag":"高频","root":"de（非，相反）+ compose（组成）→ 分解","exampleEN":"Fall leaves decompose on the forest floor, returning nutrients to the soil.","exampleCN":"秋叶在森林地面腐烂分解，把养分归还给土壤。","extra":""},{"chapter":2,"key":"2:58","id":58,"word":"rot","phonetic":"/rɒt/","pos":"v.","meaningCN":"（使）腐烂","tag":"高频","root":"源自古英语 rotian（腐烂）→ 腐烂","exampleEN":"Too much water in the pot caused the orchid roots to rot.","exampleCN":"花盆里积水过多导致兰花根部腐烂。","extra":""},{"chapter":2,"key":"2:59","id":59,"word":"decay","phonetic":"/dɪˈkeɪ/","pos":"v.","meaningCN":"腐烂","tag":"高频","root":"de（向下）+ cay（掉落）→ 腐烂","exampleEN":"The old tree stump began to decay, slowly turning into soft wood.","exampleCN":"那棵老树桩开始腐烂，慢慢变成了松软的木材。","extra":""},{"chapter":2,"key":"2:60","id":60,"word":"stale","phonetic":"/steɪl/","pos":"adj.","meaningCN":"不新鲜的；陈腐的","tag":"高频","root":"可能源自古法语 estale（陈旧的）→ 不新鲜的","exampleEN":"The seeds had gone stale and would no longer sprout, no matter how much water they got.","exampleCN":"这些种子已经陈了，不论浇多少水都不会再发芽。","extra":""},{"chapter":2,"key":"2:61","id":61,"word":"rainforest","phonetic":"/ˈreɪnˌfɒrɪst/","pos":"n.","meaningCN":"雨林","tag":"核心","root":"rain（雨）+ forest（森林）→ 雨林","exampleEN":"The Amazon rainforest is home to countless plant species yet to be studied.","exampleCN":"亚马逊雨林是无数尚待研究的植物物种的家园。","extra":""},{"chapter":2,"key":"2:62","id":62,"word":"jungle","phonetic":"/ˈdʒʌŋɡəl/","pos":"n.","meaningCN":"（热带）丛林，密林","tag":"高频","root":"源自印地语 jangal（荒野）→ 丛林","exampleEN":"Thick jungle vines made it almost impossible to walk without a machete.","exampleCN":"茂密的丛林藤蔓让人几乎无法在没有砍刀的情况下行走。","extra":""},{"chapter":2,"key":"2:63","id":63,"word":"plantation","phonetic":"/plænˈteɪʃən/","pos":"n.","meaningCN":"种植园；栽植","tag":"高频","root":"plant（种植）+ ation（地点）→ 种植园","exampleEN":"The old tea plantation on the hillside still produces some of the finest leaves in the region.","exampleCN":"山坡上的老茶园仍然出产该地区最好的茶叶。","extra":""},{"chapter":2,"key":"2:64","id":64,"word":"field","phonetic":"/fiːld/","pos":"n.","meaningCN":"原野；场地；野外","tag":"核心","root":"源自古英语 feld（田野）→ 原野","exampleEN":"The wheat field stretched so far that the golden stalks seemed to meet the sky.","exampleCN":"麦田一望无际，金色的麦秆仿佛与天空相接。","extra":""},{"chapter":2,"key":"2:65","id":65,"word":"terrace","phonetic":"/ˈterəs/","pos":"n.","meaningCN":"梯田","tag":"高频","root":"源自拉丁语 terra（土地）→ 梯田","exampleEN":"Rice grows on narrow terraces cut into the steep green hillsides.","exampleCN":"稻谷生长在陡峭绿山坡上开垦出的狭长梯田里。","extra":""},{"chapter":2,"key":"2:66","id":66,"word":"timber","phonetic":"/ˈtɪmbə/","pos":"n.","meaningCN":"木材，木料；林木","tag":"核心","root":"源自古英语 timber（木材）→ 木材","exampleEN":"The forest provides high-quality timber for local furniture makers.","exampleCN":"这片森林为当地家具制作者提供优质木材。","extra":""},{"chapter":2,"key":"2:67","id":67,"word":"charcoal","phonetic":"/ˈtʃɑːkəʊl/","pos":"n.","meaningCN":"木炭","tag":"高频","root":"char（烧焦）+ coal（煤）→ 木炭","exampleEN":"In some villages, people still burn charcoal for cooking and heating.","exampleCN":"在一些村子里，人们仍然烧木炭做饭取暖。","extra":""},{"chapter":2,"key":"2:68","id":68,"word":"log","phonetic":"/lɒɡ/","pos":"n.","meaningCN":"原木；（航海、飞行）日志","tag":"高频","root":"可能源自古诺斯语 lág（倒下的树）→ 原木","exampleEN":"They floated the logs down the river to the sawmill.","exampleCN":"他们顺流漂浮着原木运往锯木厂。","extra":""},{"chapter":2,"key":"2:69","id":69,"word":"logo","phonetic":"/ˈlɒɡəʊ/","pos":"n.","meaningCN":"标识，标志，徽标","tag":"核心","root":"源自希腊语 logos（字；话语）→ 标识","exampleEN":"The environmental group chose a green leaf as its logo to show its mission.","exampleCN":"那个环保组织选用一片绿叶作为标志，以体现其使命。","extra":""},{"chapter":2,"key":"2:70","id":70,"word":"forestry","phonetic":"/ˈfɒrɪstri/","pos":"n.","meaningCN":"林学；林业","tag":"高频","root":"forest（森林）+ ry（行业）→ 林业","exampleEN":"Sustainable forestry practices help protect forests for future generations.","exampleCN":"可持续的林业做法有助于为后代保护森林。","extra":""},{"chapter":2,"key":"2:71","id":71,"word":"branch","phonetic":"/brɑːntʃ/","pos":"n.","meaningCN":"树枝；分支机构","tag":"核心","root":"源自古法语 branche（树枝）→ 树枝","exampleEN":"A small bird built its nest in the fork of a low branch.","exampleCN":"一只小鸟在一根低矮树枝的分叉处筑了巢。","extra":""},{"chapter":2,"key":"2:72","id":72,"word":"trunk","phonetic":"/trʌŋk/","pos":"n.","meaningCN":"树干；躯干；大箱子","tag":"高频","root":"源自拉丁语 truncus（被砍掉的树枝；树干）→ 树干","exampleEN":"The ancient oak had a trunk so wide that three children could not wrap their arms around it.","exampleCN":"那棵古橡树的树干粗得三个孩子都合抱不过来。","extra":""},{"chapter":2,"key":"2:73","id":73,"word":"bough","phonetic":"/baʊ/","pos":"n.","meaningCN":"大树枝","tag":"低频","root":"源自古英语 bōg（树枝）→ 大树枝","exampleEN":"A heavy bough broke off during the storm and crashed onto the garden shed.","exampleCN":"暴风雨中一根沉重的大树枝折断，砸在了花园棚屋上。","extra":""},{"chapter":2,"key":"2:74","id":74,"word":"root","phonetic":"/ruːt/","pos":"n.","meaningCN":"根","tag":"核心","root":"源自古诺斯语 rót（根）→ 根","exampleEN":"Strong roots help trees survive strong winds and dry spells.","exampleCN":"强壮的根系帮助树木抵御强风和干旱。","extra":""},{"chapter":2,"key":"2:75","id":75,"word":"hay","phonetic":"/heɪ/","pos":"n.","meaningCN":"干草","tag":"高频","root":"源自古英语 hēg（干草）→ 干草","exampleEN":"After cutting the grass, they left it in the sun to dry into hay.","exampleCN":"割完草后，他们把草留在阳光下晒成干草。","extra":""},{"chapter":2,"key":"2:76","id":76,"word":"straw","phonetic":"/strɔː/","pos":"n.","meaningCN":"稻草，麦秆；吸管","tag":"高频","root":"源自古英语 strēaw（稻草）→ 稻草","exampleEN":"The stable floor was covered with fresh straw to keep the horses dry.","exampleCN":"马厩地板上铺着新鲜稻草，让马匹保持干爽。","extra":""},{"chapter":2,"key":"2:77","id":77,"word":"reed","phonetic":"/riːd/","pos":"n.","meaningCN":"芦苇","tag":"低频","root":"源自古英语 hrēod（芦苇）→ 芦苇","exampleEN":"Tall reeds grew along the marshy edges of the lake, hiding the waterbirds.","exampleCN":"高大的芦苇长在湖泊的沼泽边缘，藏住了水鸟。","extra":""},{"chapter":2,"key":"2:78","id":78,"word":"thorn","phonetic":"/θɔːn/","pos":"n.","meaningCN":"刺，棘刺；荆棘","tag":"高频","root":"源自古英语 þorn（刺）→ 刺","exampleEN":"Be careful of the thorns when you pick those wild roses.","exampleCN":"摘那些野玫瑰时小心荆棘刺。","extra":""},{"chapter":2,"key":"2:79","id":79,"word":"weed","phonetic":"/wiːd/","pos":"n.","meaningCN":"杂草","tag":"高频","root":"源自古英语 wēod（野草）→ 杂草","exampleEN":"She spent the morning pulling out weeds that had taken over the vegetable patch.","exampleCN":"她花了一上午清除已经占满菜地的杂草。","extra":""},{"chapter":2,"key":"2:80","id":80,"word":"grass","phonetic":"/ɡrɑːs/","pos":"n.","meaningCN":"草；草地","tag":"核心","root":"源自古英语 græs（草）→ 草","exampleEN":"Morning dew sparkled on every blade of grass in the meadow.","exampleCN":"晨露在草地的每片草叶上闪闪发光。","extra":""},{"chapter":2,"key":"2:81","id":81,"word":"meadow","phonetic":"/ˈmedəʊ/","pos":"n.","meaningCN":"草地；牧场","tag":"高频","root":"源自古英语 mǣdwe（牧场）→ 草地","exampleEN":"Sheep grazed peacefully across the wide green meadow, knee-deep in wildflowers.","exampleCN":"羊群在宽阔的绿草地上安静地吃草，野花没过膝间。","extra":""},{"chapter":2,"key":"2:82","id":82,"word":"lawn","phonetic":"/lɔːn/","pos":"n.","meaningCN":"草地，草坪","tag":"高频","root":"源自古法语 lande（荒地）→ 草坪","exampleEN":"The garden had a neat green lawn where children could play safely.","exampleCN":"花园里有一片整洁的绿草坪，孩子们可以安全玩耍。","extra":""},{"chapter":2,"key":"2:83","id":83,"word":"olive","phonetic":"/ˈɒlɪv/","pos":"n.","meaningCN":"橄榄；橄榄树","tag":"高频","root":"源自希腊语 elaia（橄榄）→ 橄榄","exampleEN":"The ancient olive trees on the hillside are said to be over a thousand years old.","exampleCN":"山坡上那些古老的橄榄树据说已有上千年树龄。","extra":""},{"chapter":2,"key":"2:84","id":84,"word":"pine","phonetic":"/paɪn/","pos":"n.","meaningCN":"松树；松木","tag":"高频","root":"源自拉丁语 pinus（松树）→ 松树","exampleEN":"A line of tall pine trees protected the farmhouse from the cold north wind.","exampleCN":"一排高大的松树保护农舍免受北方寒风侵袭。","extra":""},{"chapter":2,"key":"2:85","id":85,"word":"vine","phonetic":"/vaɪn/","pos":"n.","meaningCN":"葡萄藤","tag":"高频","root":"源自拉丁语 vinea（葡萄园）→ 葡萄藤","exampleEN":"The vine climbed all the way up to the balcony, loaded with purple grapes.","exampleCN":"葡萄藤一直爬到阳台上，挂满了紫葡萄。","extra":""},{"chapter":2,"key":"2:86","id":86,"word":"violet","phonetic":"/ˈvaɪələt/","pos":"n.","meaningCN":"紫罗兰","tag":"低频","root":"源自拉丁语 viola（紫罗兰）→ 紫罗兰","exampleEN":"Little violets appeared in the shade of the trees, adding colour to the woodland floor.","exampleCN":"小紫罗兰在树荫下出现，为林地铺上一层色彩。","extra":""},{"chapter":2,"key":"2:87","id":87,"word":"tulip","phonetic":"/ˈtjuːlɪp/","pos":"n.","meaningCN":"郁金香","tag":"低频","root":"源自土耳其语 tülbent（头巾）→ 郁金香（花形似头巾）","exampleEN":"Rows of red and yellow tulips lined the path to the old windmill.","exampleCN":"红黄相间的郁金香成行排列在通往老风车的小路旁。","extra":""},{"chapter":2,"key":"2:88","id":88,"word":"mint","phonetic":"/mɪnt/","pos":"n.","meaningCN":"薄荷；铸币厂","tag":"高频","root":"源自希腊语 minthē（薄荷）→ 薄荷","exampleEN":"A few leaves of fresh mint can make a simple cup of tea taste special.","exampleCN":"几片新鲜薄荷叶就能让一杯简单的茶变得与众不同。","extra":""},{"chapter":2,"key":"2:89","id":89,"word":"reef","phonetic":"/riːf/","pos":"n.","meaningCN":"（暗）礁，礁脉","tag":"高频","root":"可能源自古诺斯语 rif（暗礁）→ 礁石","exampleEN":"The coral reef shelters thousands of tiny sea creatures among its colourful branches.","exampleCN":"珊瑚礁在它色彩斑斓的分枝间庇护了成千上万微小海洋生物。","extra":""},{"chapter":2,"key":"2:90","id":90,"word":"alga","phonetic":"/ˈælɡə/","pos":"n.","meaningCN":"海藻，藻","tag":"识记","root":"源自拉丁语 alga（海藻）→ 藻类","exampleEN":"Tiny green alga covered the surface of the pond, turning the water bright green.","exampleCN":"微小的绿藻覆盖了池塘表面，把水染成鲜绿色。","extra":""},{"chapter":2,"key":"2:91","id":91,"word":"enzyme","phonetic":"/ˈenzaɪm/","pos":"n.","meaningCN":"酶","tag":"高频","root":"en（在…里）+ zyme（酵母）→ 酶","exampleEN":"Some fruits contain enzymes that help break down tough meat fibres.","exampleCN":"一些水果含有能帮助分解坚韧肉纤维的酶。","extra":""},{"chapter":2,"key":"2:92","id":92,"word":"catalyst","phonetic":"/ˈkætəlɪst/","pos":"n.","meaningCN":"催化剂；促进因素","tag":"高频","root":"cata（向下）+ lyst（松开）→ 催化剂","exampleEN":"The new environmental law served as a catalyst for cleaner farming methods.","exampleCN":"新环境法成了推广更清洁耕作方式的催化剂。","extra":""},{"chapter":2,"key":"2:93","id":93,"word":"release","phonetic":"/rɪˈliːs/","pos":"v.","meaningCN":"释放；发布","tag":"核心","root":"re（回）+ lease（松开）→ 释放","exampleEN":"Trees release oxygen back into the air, which is vital for all animals.","exampleCN":"树木把氧气释放回空气中，这对所有动物都至关重要。","extra":""},{"chapter":2,"key":"2:94","id":94,"word":"emission","phonetic":"/ɪˈmɪʃən/","pos":"n.","meaningCN":"排放，散发；排放物","tag":"核心","root":"e（向外）+ mit（送）+ sion → 排放","exampleEN":"The country agreed to cut its carbon emissions by planting more forests.","exampleCN":"该国同意通过种植更多森林来减少碳排放。","extra":""},{"chapter":2,"key":"2:95","id":95,"word":"absorb","phonetic":"/əbˈsɔːb/","pos":"v.","meaningCN":"吸收；吸引全部注意力","tag":"核心","root":"ab（离开）+ sorb（吸）→ 吸收","exampleEN":"The thick layer of dead leaves slowly absorbed the heavy rain, preventing floods.","exampleCN":"厚厚一层落叶慢慢吸收了大雨，避免了洪水。","extra":""},{"chapter":2,"key":"2:96","id":96,"word":"circulation","phonetic":"/ˌsɜːkjʊˈleɪʃən/","pos":"n.","meaningCN":"流通；循环；流传","tag":"高频","root":"circul（圆环）+ ation → 循环","exampleEN":"Good air circulation inside a greenhouse helps prevent fungal diseases on plants.","exampleCN":"温室内良好的空气流通有助于预防植物真菌病害。","extra":""},{"chapter":2,"key":"2:97","id":97,"word":"exceed","phonetic":"/ɪkˈsiːd/","pos":"v.","meaningCN":"超过","tag":"核心","root":"ex（向外）+ ceed（走）→ 超过","exampleEN":"The high summer temperatures exceeded what the delicate seedlings could bear.","exampleCN":"夏季高温超过了这些娇嫩幼苗能承受的限度。","extra":""},{"chapter":2,"key":"2:98","id":98,"word":"uptake","phonetic":"/ˈʌpteɪk/","pos":"n.","meaningCN":"摄取；领会","tag":"高频","root":"up（向上）+ take（拿）→ 摄取","exampleEN":"Adding organic matter improves the plant's uptake of nutrients from the soil.","exampleCN":"添加有机物质能促进植物从土壤中摄取养分。","extra":""},{"chapter":2,"key":"2:99","id":99,"word":"nutrient","phonetic":"/ˈnjuːtriənt/","pos":"n.","meaningCN":"营养物质","tag":"核心","root":"nutri（滋养）+ ent（物质）→ 营养物质","exampleEN":"The vegetable plants turned yellow because the soil lacked key nutrients.","exampleCN":"蔬菜变黄了，因为土壤缺乏关键营养物质。","extra":""},{"chapter":2,"key":"2:100","id":100,"word":"energy","phonetic":"/ˈenədʒi/","pos":"n.","meaningCN":"能源；精力","tag":"核心","root":"en（在…里）+ erg（工作）+ y → 能量","exampleEN":"Sunlight provides the energy that plants need to turn water and air into food.","exampleCN":"阳光提供了植物将水和空气转化成食物所需的能量。","extra":""},{"chapter":2,"key":"2:101","id":101,"word":"surroundings","phonetic":"/səˈraʊndɪŋz/","pos":"n.","meaningCN":"环境","tag":"核心","root":"surround（围绕）+ ings（复数名词）→ 环境","exampleEN":"The plant quickly adapts its leaf shape to its immediate surroundings.","exampleCN":"这种植物会根据所处环境迅速调整叶片形状。","extra":""},{"chapter":2,"key":"2:102","id":102,"word":"mechanism","phonetic":"/ˈmekənɪzəm/","pos":"n.","meaningCN":"机制；构造","tag":"核心","root":"源自希腊语 mēkhanē（机器）→ 机制","exampleEN":"Scientists are still studying the cellular mechanism by which roots detect water.","exampleCN":"科学家仍在研究根系探测水分的细胞机制。","extra":""},{"chapter":2,"key":"2:103","id":103,"word":"counterbalance","phonetic":"/ˌkaʊntəˈbæləns/","pos":"n.","meaningCN":"起平衡作用的事物","tag":"高频","root":"counter（对抗）+ balance（平衡）→ 抵消","exampleEN":"The growth of new leaves serves as a natural counterbalance to the loss of old ones.","exampleCN":"新叶的生长是对老叶损失的天然平衡。","extra":""},{"chapter":2,"key":"2:104","id":104,"word":"protect","phonetic":"/prəˈtekt/","pos":"v.","meaningCN":"保护","tag":"核心","root":"pro（前）+ tect（盖）→ 保护","exampleEN":"Thick bark protects the inner tree from insect damage and extreme cold.","exampleCN":"厚实的树皮保护树干内部免受虫害和极寒侵袭。","extra":""},{"chapter":2,"key":"2:105","id":105,"word":"preserve","phonetic":"/prɪˈzɜːv/","pos":"v.","meaningCN":"保护；维持（原状）；保存","tag":"核心","root":"pre（预先）+ serve（保持）→ 保护","exampleEN":"The national park was set up to preserve the unique flora of the region.","exampleCN":"这个国家公园的建立是为了保护该地区独特的植物群。","extra":""},{"chapter":2,"key":"2:106","id":106,"word":"conservation","phonetic":"/ˌkɒnsəˈveɪʃən/","pos":"n.","meaningCN":"保护；保存","tag":"核心","root":"conserv（保存）+ ation → 保护","exampleEN":"Water conservation is critical for farming in dry regions.","exampleCN":"水资源保护对于干旱地区的农业至关重要。","extra":""},{"chapter":2,"key":"2:107","id":107,"word":"bush fire","phonetic":"/ˈbʊʃ faɪə/","pos":"n.","meaningCN":"林区大火","tag":"识记","root":"bush（灌木丛）+ fire（火）→ 林区大火","exampleEN":"The bush fire swept through the dry grass and destroyed several old olive trees.","exampleCN":"林区大火席卷了干草地，毁掉了几棵老橄榄树。","extra":""},{"chapter":2,"key":"2:108","id":108,"word":"extinguish","phonetic":"/ɪkˈstɪŋɡwɪʃ/","pos":"v.","meaningCN":"扑灭（火）；使破灭","tag":"高频","root":"ex（向外）+ tingu（熄灭）+ ish → 扑灭","exampleEN":"Firefighters worked for hours to extinguish the flames threatening the pine forest.","exampleCN":"消防员奋战数小时才扑灭威胁松林的火焰。","extra":""},{"chapter":2,"key":"2:109","id":109,"word":"destruct","phonetic":"/dɪˈstrʌkt/","pos":"v.","meaningCN":"（使）自毁","tag":"高频","root":"de（除去）+ struct（建造）→ 毁灭","exampleEN":"The virus caused the infected plant cells to self-destruct.","exampleCN":"病毒导致受感染的植物细胞自毁。","extra":""},{"chapter":2,"key":"2:110","id":110,"word":"ruin","phonetic":"/ˈruːɪn/","pos":"v.","meaningCN":"毁坏","tag":"核心","root":"源自拉丁语 ruina（倒塌）→ 毁坏","exampleEN":"A late spring frost ruined the entire year's apple crop.","exampleCN":"一场晚春霜冻毁了整年的苹果收成。","extra":""},{"chapter":2,"key":"2:111","id":111,"word":"perish","phonetic":"/ˈperɪʃ/","pos":"v.","meaningCN":"毁灭，消亡；腐烂","tag":"高频","root":"源自拉丁语 perire（死去）→ 消亡","exampleEN":"Many seedlings perished in the unexpected heatwave before they could be transplanted.","exampleCN":"许多秧苗在移栽前就在突如其来的热浪中死去了。","extra":""},{"chapter":2,"key":"2:112","id":112,"word":"demolish","phonetic":"/dɪˈmɒlɪʃ/","pos":"v.","meaningCN":"拆除；毁坏","tag":"高频","root":"de（向下）+ mol（堆）+ ish → 拆毁","exampleEN":"The old greenhouse was demolished to make space for a larger community garden.","exampleCN":"旧温室被拆除，为更大的社区花园腾出空间。","extra":""},{"chapter":2,"key":"2:113","id":113,"word":"infringe","phonetic":"/ɪnˈfrɪndʒ/","pos":"v.","meaningCN":"侵犯；违反","tag":"高频","root":"in（入）+ fringe（边缘）→ 破坏边缘 → 侵犯","exampleEN":"The new housing development would infringe on the protected forest area.","exampleCN":"新住宅开发将侵占受保护的森林区域。","extra":""},{"chapter":2,"key":"2:114","id":114,"word":"undermine","phonetic":"/ˌʌndəˈmaɪn/","pos":"v.","meaningCN":"破坏；逐渐削弱","tag":"核心","root":"under（在…下面）+ mine（挖矿）→ 破坏根基","exampleEN":"Overuse of chemical fertilisers may undermine the natural fertility of the soil.","exampleCN":"过度使用化肥可能会逐渐削弱土壤的自然肥力。","extra":""},{"chapter":2,"key":"2:115","id":115,"word":"extinction","phonetic":"/ɪkˈstɪŋkʃən/","pos":"n.","meaningCN":"灭绝","tag":"核心","root":"extinct（灭绝的）+ ion → 灭绝","exampleEN":"Several rare orchid species are facing extinction as their rainforest habitat shrinks.","exampleCN":"随着雨林栖息地缩小，好几种稀有兰花正面临灭绝。","extra":""},{"chapter":2,"key":"2:116","id":116,"word":"pattern","phonetic":"/ˈpætən/","pos":"n.","meaningCN":"模式；式样；底样","tag":"核心","root":"源自拉丁语 patronus（模型）→ 模式","exampleEN":"The rings in a tree trunk follow a clear pattern that reflects years of growth.","exampleCN":"树干中的年轮遵循清晰的模式，反映了多年的生长状况。","extra":""},{"chapter":2,"key":"2:117","id":117,"word":"outcome","phonetic":"/ˈaʊtkʌm/","pos":"n.","meaningCN":"结果","tag":"核心","root":"out（出来）+ come（来到）→ 结果","exampleEN":"The final outcome of the experiment showed that the new rice variety needed far less water.","exampleCN":"实验的最终结果表明，这种新水稻品种所需的水量要少得多。","extra":""},{"chapter":2,"key":"2:118","id":118,"word":"impact","phonetic":"/ˈɪmpækt/","pos":"n.","meaningCN":"影响","tag":"核心","root":"im（入）+ pact（紧压）→ 影响","exampleEN":"The introduction of foreign insects had a severe impact on the local plants.","exampleCN":"外来昆虫的引入对当地植物造成了严重影响。","extra":""},{"chapter":2,"key":"2:119","id":119,"word":"seasonal","phonetic":"/ˈsiːzənəl/","pos":"adj.","meaningCN":"季节性的","tag":"核心","root":"season（季节）+ al（形容词）→ 季节性的","exampleEN":"The river's flow is highly seasonal, swelling with snow melt in spring.","exampleCN":"这条河的流量季节性很强，春天融雪时会上涨。","extra":""},{"chapter":2,"key":"2:120","id":120,"word":"experimental","phonetic":"/ɪkˌsperɪˈmentl/","pos":"adj.","meaningCN":"实验的；试验性的","tag":"高频","root":"experiment（实验）+ al → 实验性的","exampleEN":"The experimental farm trials a new kind of wheat that needs no chemical sprays.","exampleCN":"这个实验农场正在试种一种无需喷洒化学药剂的新型小麦。","extra":""},{"chapter":2,"key":"2:121","id":121,"word":"favourable","phonetic":"/ˈfeɪvərəbl/","pos":"adj.","meaningCN":"有利的；赞成的","tag":"核心","root":"favour（有利于）+ able（能…的）→ 有利的","exampleEN":"Warm, moist weather is favourable for the rapid growth of most garden vegetables.","exampleCN":"温暖潮湿的天气有利于大多数蔬菜快速生长。","extra":""},{"chapter":2,"key":"2:122","id":122,"word":"productive","phonetic":"/prəˈdʌktɪv/","pos":"adj.","meaningCN":"多产的","tag":"核心","root":"product（产品）+ ive → 多产的","exampleEN":"With good care, a single tomato plant can be highly productive throughout summer.","exampleCN":"在良好照料下，单棵番茄植株整个夏天都能保持高产量。","extra":""},{"chapter":2,"key":"2:123","id":123,"word":"effective","phonetic":"/ɪˈfektɪv/","pos":"adj.","meaningCN":"有效的","tag":"核心","root":"effect（效果）+ ive → 有效的","exampleEN":"This natural pesticide proved very effective against common garden pests.","exampleCN":"这种天然杀虫剂被证明对常见花园害虫非常有效。","extra":""},{"chapter":2,"key":"2:124","id":124,"word":"efficient","phonetic":"/ɪˈfɪʃənt/","pos":"adj.","meaningCN":"效率高的","tag":"核心","root":"ef（出）+ fic（做）+ ient → 有效率的","exampleEN":"Drip irrigation is a far more efficient way to water crops than flooding fields.","exampleCN":"滴灌是一种远比大水漫灌更高效的浇灌作物的方式。","extra":""},{"chapter":2,"key":"2:125","id":125,"word":"considerable","phonetic":"/kənˈsɪdərəbəl/","pos":"adj.","meaningCN":"相当多的","tag":"核心","root":"consider（考虑）+ able（能…的）→ 值得考虑的 → 相当多的","exampleEN":"A considerable amount of the world's coffee comes from small family farms.","exampleCN":"世界上相当大一部分咖啡来自小型家庭农场。","extra":""},{"chapter":2,"key":"2:126","id":126,"word":"massive","phonetic":"/ˈmæsɪv/","pos":"adj.","meaningCN":"巨大的，大规模的","tag":"核心","root":"mass（大块）+ ive → 巨大的","exampleEN":"The plantation was destroyed by a massive swarm of locusts in just a few days.","exampleCN":"几天之内，种植园就被一大群蝗虫毁掉了。","extra":""},{"chapter":2,"key":"2:127","id":127,"word":"immense","phonetic":"/ɪˈmens/","pos":"adj.","meaningCN":"巨大的","tag":"高频","root":"im（不）+ mense（测量）→ 无法测量 → 巨大的","exampleEN":"The immense forest stretched to the horizon, covering a huge part of the country.","exampleCN":"那片广袤的森林一直延伸到地平线，覆盖了该国很大一部分。","extra":""},{"chapter":2,"key":"2:128","id":128,"word":"maximal","phonetic":"/ˈmæksɪməl/","pos":"adj.","meaningCN":"最大的","tag":"高频","root":"maxim（最大）+ al → 最大的","exampleEN":"The greenhouse is designed to capture maximal sunlight throughout the winter months.","exampleCN":"温室被设计成在冬季几个月里能捕获最大量的阳光。","extra":""},{"chapter":2,"key":"2:129","id":129,"word":"minimal","phonetic":"/ˈmɪnɪməl/","pos":"adj.","meaningCN":"最小的，极小的","tag":"高频","root":"minim（最小）+ al → 最小的","exampleEN":"With minimal water and no fertilisers, this cactus can live for decades.","exampleCN":"只需极少的水而且无需肥料，这棵仙人掌就能活几十年。","extra":""},{"chapter":2,"key":"2:130","id":130,"word":"optimal","phonetic":"/ˈɒptɪməl/","pos":"adj.","meaningCN":"最佳的，最理想的","tag":"核心","root":"optim（最佳）+ al → 最佳的","exampleEN":"A soil temperature around twenty degrees Celsius is optimal for most vegetable seeds.","exampleCN":"摄氏二十度左右的土温对大多数蔬菜种子来说是最理想的。","extra":""}],"3":[{"chapter":3,"key":"3:1","id":1,"word":"biologist","phonetic":"/baɪˈblɒdʒɪst/","pos":"n.","meaningCN":"生物学家","tag":"核心","root":"","exampleEN":"The biologist spent years studying the behavior of marine mammals in their natural habitat.","exampleCN":"这位生物学家花了多年时间研究海洋哺乳动物在其自然栖息地中的行为。","extra":"派生词：biology (生物学)；biological (生物的)"},{"chapter":3,"key":"3:2","id":2,"word":"zoologist","phonetic":"/zuːˈblɒdʒɪst/","pos":"n.","meaningCN":"动物学家","tag":"核心","root":"","exampleEN":"As a zoologist, she specializes in the social structure of primate groups.","exampleCN":"作为一名动物学家，她专门研究灵长类群体的社会结构。","extra":"派生词：zoology (动物学)；zoological (动物学的)"},{"chapter":3,"key":"3:3","id":3,"word":"ecologist","phonetic":"/iˈkɒlədʒɪst/","pos":"n.","meaningCN":"生态学家","tag":"核心","root":"","exampleEN":"The ecologist warned that deforestation would disrupt the entire ecosystem.","exampleCN":"生态学家警告说，砍伐森林会破坏整个生态系统。","extra":"派生词：ecology (生态学)；ecological (生态的)"},{"chapter":3,"key":"3:4","id":4,"word":"botanist","phonetic":"/ˈbɒtənɪst/","pos":"n.","meaningCN":"植物学家","tag":"高频","root":"","exampleEN":"A botanist can identify thousands of plant species by their leaf patterns.","exampleCN":"植物学家可以通过叶子的图案识别成千上万种植物。","extra":"派生词：botany (植物学)；botanical (植物学的)"},{"chapter":3,"key":"3:5","id":5,"word":"mammal","phonetic":"/ˈmæməl/","pos":"n.","meaningCN":"哺乳动物","tag":"核心","root":"","exampleEN":"Unlike reptiles, mammals are warm-blooded and usually have hair or fur.","exampleCN":"与爬行动物不同，哺乳动物是温血的，通常有毛发或皮毛。","extra":"形容词：mammalian"},{"chapter":3,"key":"3:6","id":6,"word":"primate","phonetic":"/ˈpraɪmeɪt/","pos":"n.","meaningCN":"灵长目动物","tag":"核心","root":"","exampleEN":"Primates, such as chimpanzees and gorillas, have highly developed brains.","exampleCN":"灵长类动物，如黑猩猩和大猩猩，拥有高度发达的大脑。","extra":"包括人类、猿、猴等"},{"chapter":3,"key":"3:7","id":7,"word":"vertebrate","phonetic":"/ˈvɜːtɪbrət/","pos":"n.","meaningCN":"脊椎动物","tag":"核心","root":"","exampleEN":"All vertebrates have a backbone, which supports their body structure.","exampleCN":"所有脊椎动物都有脊柱，用于支撑身体结构。","extra":"反义词：invertebrate (无脊椎动物)"},{"chapter":3,"key":"3:8","id":8,"word":"reptile","phonetic":"/ˈreptaɪl/","pos":"n.","meaningCN":"爬行动物","tag":"高频","root":"","exampleEN":"Snakes and lizards are reptiles that rely on external heat to regulate their body temperature.","exampleCN":"蛇和蜥蜴是依赖外部热量调节体温的爬行动物。","extra":"形容词：reptilian"},{"chapter":3,"key":"3:9","id":9,"word":"amphibian","phonetic":"/æmˈfɪbiən/","pos":"n.","meaningCN":"两栖动物；水陆两用车","tag":"高频","root":"","exampleEN":"Frogs are amphibians, meaning they can live both in water and on land.","exampleCN":"青蛙是两栖动物，这意味着它们既能生活在水中也能生活在陆地上。","extra":"形容词：amphibious"},{"chapter":3,"key":"3:10","id":10,"word":"carnivore","phonetic":"/ˈkɑːnɪvɔː/","pos":"n.","meaningCN":"食肉动物","tag":"核心","root":"carn（肉）+ vore（吞食）","exampleEN":"Lions are apex carnivores, preying on large herbivores like zebras.","exampleCN":"狮子是顶级食肉动物，捕食像斑马这样的大型食草动物。","extra":"形容词：carnivorous；对比：herbivore (食草动物), omnivore (杂食动物)"},{"chapter":3,"key":"3:11","id":11,"word":"herbivore","phonetic":"/ˈhɜːbɪvɔː/","pos":"n.","meaningCN":"食草动物","tag":"核心","root":"","exampleEN":"Cows and sheep are herbivores, feeding mainly on grass and plants.","exampleCN":"牛和羊是食草动物，主要以草和植物为食。","extra":"形容词：herbivorous；对比：carnivore"},{"chapter":3,"key":"3:12","id":12,"word":"creature","phonetic":"/ˈkriːtʃə/","pos":"n.","meaningCN":"生物，动物","tag":"核心","root":"","exampleEN":"The ocean is home to countless mysterious creatures living in the deep sea.","exampleCN":"海洋是无数生活在深海的神秘生物的家园。","extra":"同义词：being, organism"},{"chapter":3,"key":"3:13","id":13,"word":"wildlife","phonetic":"/ˈwaɪldlaɪf/","pos":"n.","meaningCN":"野生动物；野生生物","tag":"核心","root":"","exampleEN":"Protecting wildlife habitats is essential for maintaining biodiversity.","exampleCN":"保护野生动物栖息地对于维持生物多样性至关重要。","extra":"常见搭配：wildlife conservation (野生动物保护)"},{"chapter":3,"key":"3:14","id":14,"word":"fauna","phonetic":"/ˈfɔːnə/","pos":"n.","meaningCN":"（尤指某一地区的）动物群","tag":"识记","root":"","exampleEN":"The Galapagos Islands have a unique fauna that cannot be found anywhere else.","exampleCN":"加拉帕戈斯群岛拥有其他地方找不到的独特动物群。","extra":"对应词：flora (植物群)"},{"chapter":3,"key":"3:15","id":15,"word":"flora","phonetic":"/ˈflɔːrə/","pos":"n.","meaningCN":"（尤指某一地区的）植物群","tag":"识记","root":"","exampleEN":"The desert flora has adapted to survive with very little water.","exampleCN":"沙漠植物群已经适应了在极少水分下生存。","extra":"对应词：fauna (动物群)"},{"chapter":3,"key":"3:16","id":16,"word":"species","phonetic":"/ˈspiːʃiːz/","pos":"n.","meaningCN":"（单复数同形）种，物种","tag":"核心","root":"","exampleEN":"More than a million species of insects have been identified so far.","exampleCN":"到目前为止，已经发现了一百多万种昆虫。","extra":"单复数同形；常见搭配：endangered species (濒危物种)"},{"chapter":3,"key":"3:17","id":17,"word":"flock","phonetic":"/flɒk/","pos":"n.","meaningCN":"（羊或鸟）群 v.聚集","tag":"高频","root":"","exampleEN":"A flock of geese flew overhead, heading south for the winter.","exampleCN":"一群大雁从头顶飞过，向南前往过冬。","extra":"动词用法：Tourists flock to the city every summer."},{"chapter":3,"key":"3:18","id":18,"word":"herd","phonetic":"/hɜːd/","pos":"n.","meaningCN":"兽群，畜群","tag":"高频","root":"","exampleEN":"A herd of elephants moved slowly across the savanna.","exampleCN":"一群大象缓慢地穿过大草原。","extra":"常与 grazing animals 搭配，如 cattle, deer, elephants"},{"chapter":3,"key":"3:19","id":19,"word":"swarm","phonetic":"/swɔːm/","pos":"n.","meaningCN":"（蜜蜂等昆虫的）一大群；（迅速移动的）人群","tag":"高频","root":"","exampleEN":"A swarm of locusts can destroy entire crops within hours.","exampleCN":"一群蝗虫能在几小时内摧毁整片庄稼。","extra":"动词用法：The bees swarmed around the hive."},{"chapter":3,"key":"3:20","id":20,"word":"throng","phonetic":"/θrɒŋ/","pos":"n.","meaningCN":"人群，一大群人 v.群集","tag":"低频","root":"","exampleEN":"A huge throng gathered in the square to celebrate the victory.","exampleCN":"一大群人聚集在广场上庆祝胜利。","extra":"同义词：crowd; 常见搭配：be thronged with (挤满)"},{"chapter":3,"key":"3:21","id":21,"word":"crowd","phonetic":"/kraʊd/","pos":"n.","meaningCN":"人群；观众；一伙人","tag":"核心","root":"","exampleEN":"The crowd cheered as the marathon runner crossed the finish line.","exampleCN":"当马拉松选手冲过终点线时，人群欢呼起来。","extra":"形容词：crowded (拥挤的)"},{"chapter":3,"key":"3:22","id":22,"word":"beast","phonetic":"/biːst/","pos":"n.","meaningCN":"兽，野兽；凶残的人，畜生","tag":"高频","root":"","exampleEN":"Legends tell of a terrible beast that dwells in the deep forest.","exampleCN":"传说深林中住着一头可怕的野兽。","extra":"形容词：beastly"},{"chapter":3,"key":"3:23","id":23,"word":"brute","phonetic":"/bruːt/","pos":"n.","meaningCN":"粗野的人，残忍的人","tag":"高频","root":"","exampleEN":"The dictator was a brute who showed no mercy to his opponents.","exampleCN":"那个独裁者是个残忍的人，对对手毫不留情。","extra":"形容词：brutal (残暴的)；名词：brutality"},{"chapter":3,"key":"3:24","id":24,"word":"cruel","phonetic":"/ˈkruːəl/","pos":"adj.","meaningCN":"残酷的，残忍的，残暴的","tag":"核心","root":"","exampleEN":"It is cruel to keep wild animals in small cages for entertainment.","exampleCN":"为了娱乐而把野生动物关在小笼子里是残忍的。","extra":"名词：cruelty；反义词：kind"},{"chapter":3,"key":"3:25","id":25,"word":"originate","phonetic":"/əˈrɪdʒɪneɪt/","pos":"v.","meaningCN":"发源，来自；创始","tag":"高频","root":"","exampleEN":"Many scientific ideas originated from simple observations of nature.","exampleCN":"许多科学思想起源于对自然的简单观察。","extra":"常见搭配：originate from/in；派生词：origin (起源), original (原始的)"},{"chapter":3,"key":"3:26","id":26,"word":"derive","phonetic":"/dɪˈraɪv/","pos":"v.","meaningCN":"得到；（使）源自","tag":"核心","root":"","exampleEN":"The English word 'restaurant' derives from a French verb meaning 'to restore'.","exampleCN":"英语单词'restaurant'源自一个意为'恢复'的法语动词。","extra":"常见搭配：derive from / be derived from"},{"chapter":3,"key":"3:27","id":27,"word":"stem","phonetic":"/stem/","pos":"v.","meaningCN":"起源于，来自","tag":"高频","root":"","exampleEN":"His fear of water stems from a childhood drowning accident.","exampleCN":"他对水的恐惧源于童年时的一次溺水事故。","extra":"搭配：stem from；名词词义：茎，梗"},{"chapter":3,"key":"3:28","id":28,"word":"ancestor","phonetic":"/ˈænsəstə/","pos":"n.","meaningCN":"祖宗，祖先","tag":"核心","root":"","exampleEN":"Scientists believe that humans and chimpanzees share a common ancestor.","exampleCN":"科学家认为人类和黑猩猩有共同的祖先。","extra":"反义词：descendant；形容词：ancestral"},{"chapter":3,"key":"3:29","id":29,"word":"descendant","phonetic":"/dɪˈsɛndənt/","pos":"n.","meaningCN":"后裔，后代","tag":"高频","root":"","exampleEN":"The royal descendants still live in the palace today.","exampleCN":"王室后裔至今仍住在宫殿里。","extra":"动词：descend (下降；传下)；反义词：ancestor"},{"chapter":3,"key":"3:30","id":30,"word":"offspring","phonetic":"/ˈɒfˌsprɪŋ/","pos":"n.","meaningCN":"（单复数同形）后代，子孙；产物","tag":"核心","root":"","exampleEN":"The female bird feeds her offspring until they are ready to fly.","exampleCN":"雌鸟喂养它的后代，直到它们准备好飞翔。","extra":"单复数同形；同义词：young, progeny"},{"chapter":3,"key":"3:31","id":31,"word":"subgroup","phonetic":"/ˈsʌbɡruːp/","pos":"n.","meaningCN":"子群","tag":"低频","root":"","exampleEN":"In the study, the patients were divided into subgroups based on age.","exampleCN":"在这项研究中，患者根据年龄被分成子群。","extra":"前缀 sub- 表示'下，次'"},{"chapter":3,"key":"3:32","id":32,"word":"feed","phonetic":"/fiːd/","pos":"v.","meaningCN":"供养；喂，饲养；进食","tag":"核心","root":"","exampleEN":"Farmers feed their cattle with hay during the winter months.","exampleCN":"冬季农民用干草喂养他们的牛。","extra":"搭配：feed on (以……为食)；名词：food"},{"chapter":3,"key":"3:33","id":33,"word":"breed","phonetic":"/briːd/","pos":"v.","meaningCN":"饲养；繁殖 n.品种","tag":"核心","root":"","exampleEN":"These dogs were originally bred for hunting in cold climates.","exampleCN":"这些狗最初是为在寒冷气候中狩猎而培育的。","extra":"名词：breeding (繁殖)；过去式/过去分词：bred"},{"chapter":3,"key":"3:34","id":34,"word":"interbreed","phonetic":"/ˌɪntəˈbriːd/","pos":"v.","meaningCN":"（使）品种间杂交，（使）生混种","tag":"低频","root":"","exampleEN":"Wolves and domestic dogs can interbreed and produce fertile offspring.","exampleCN":"狼和家犬可以杂交并产生可育的后代。","extra":"前缀 inter- (之间) + breed"},{"chapter":3,"key":"3:35","id":35,"word":"hybridise","phonetic":"/ˈhaɪbrɪdaɪz/","pos":"v.","meaningCN":"（使）杂交","tag":"低频","root":"","exampleEN":"Gardeners often hybridise different rose varieties to create new colors.","exampleCN":"园丁经常将不同的玫瑰品种杂交以创造新的颜色。","extra":"名词：hybrid (杂种)；美式拼写：hybridize"},{"chapter":3,"key":"3:36","id":36,"word":"proliferate","phonetic":"/prəˈlɪfəreɪt/","pos":"v.","meaningCN":"迅速增殖；剧增","tag":"高频","root":"","exampleEN":"Without natural predators, the rabbit population proliferated rapidly.","exampleCN":"没有天敌，兔子的数量迅速剧增。","extra":"名词：proliferation (激增)"},{"chapter":3,"key":"3:37","id":37,"word":"sterility","phonetic":"/stəˈrɪlɪti/","pos":"n.","meaningCN":"不生育","tag":"低频","root":"","exampleEN":"The pollution caused sterility in many fish species living in the river.","exampleCN":"污染导致河中许多鱼类不生育。","extra":"形容词：sterile (不育的；无菌的)"},{"chapter":3,"key":"3:38","id":38,"word":"mate","phonetic":"/meɪt/","pos":"v.","meaningCN":"交配 n.配偶","tag":"核心","root":"","exampleEN":"Penguins usually find a new mate each breeding season.","exampleCN":"企鹅通常每个繁殖季节都会寻找新的配偶。","extra":"名词：mating (交配)"},{"chapter":3,"key":"3:39","id":39,"word":"courtship","phonetic":"/ˈkɔːtʃɪp/","pos":"n.","meaningCN":"求偶","tag":"高频","root":"","exampleEN":"Male birds often display colorful feathers during courtship to attract females.","exampleCN":"雄性鸟类在求偶时常常展示色彩鲜艳的羽毛来吸引雌性。","extra":"动词：court (求爱)"},{"chapter":3,"key":"3:40","id":40,"word":"lay","phonetic":"/leɪ/","pos":"v.","meaningCN":"产（卵）；放置；铺设","tag":"核心","root":"","exampleEN":"Sea turtles return to the same beach to lay their eggs every year.","exampleCN":"海龟每年都回到同一个海滩产卵。","extra":"过去式/过去分词：laid；易混：lie (躺)"},{"chapter":3,"key":"3:41","id":41,"word":"hatch","phonetic":"/hætʃ/","pos":"v./n.","meaningCN":"孵化","tag":"核心","root":"","exampleEN":"The eggs will hatch after about three weeks of incubation.","exampleCN":"这些蛋经过大约三周的孵化后就会孵出。","extra":"谚语：Don't count your chickens before they hatch."},{"chapter":3,"key":"3:42","id":42,"word":"fin","phonetic":"/fɪn/","pos":"n.","meaningCN":"鳍","tag":"高频","root":"","exampleEN":"Sharks use their dorsal fin to maintain stability while swimming.","exampleCN":"鲨鱼用它们的背鳍在游泳时保持稳定。","extra":"形容词：finned (有鳍的)"},{"chapter":3,"key":"3:43","id":43,"word":"wing","phonetic":"/wɪŋ/","pos":"n.","meaningCN":"翼，翅膀","tag":"核心","root":"","exampleEN":"The butterfly's wings were covered in bright orange and black patterns.","exampleCN":"蝴蝶的翅膀上覆盖着明亮的橙色和黑色图案。","extra":"动词：wing (飞行)；习语：on the wing (在飞行中)"},{"chapter":3,"key":"3:44","id":44,"word":"brood","phonetic":"/bruːd/","pos":"n.","meaningCN":"一窝幼鸟 v.孵（蛋）","tag":"低频","root":"","exampleEN":"The mother robin feeds her brood with worms she finds in the garden.","exampleCN":"知更鸟妈妈用她在花园里找到的虫子喂养她的一窝幼鸟。","extra":"动词 brooding 可指'沉思'"},{"chapter":3,"key":"3:45","id":45,"word":"plume","phonetic":"/pluːm/","pos":"n.","meaningCN":"羽毛","tag":"低频","root":"","exampleEN":"The peacock displayed its magnificent tail plume to impress potential mates.","exampleCN":"孔雀展示其华丽的尾羽来打动潜在的配偶。","extra":"同义词：feather (但 plume 多指大而华丽的羽毛)"},{"chapter":3,"key":"3:46","id":46,"word":"spawn","phonetic":"/spɔːn/","pos":"n.","meaningCN":"（鱼、蛙等的）卵 v.产卵；引起","tag":"高频","root":"","exampleEN":"Salmon swim upstream to spawn in the same river where they were born.","exampleCN":"鲑鱼逆流而上，在它们出生的同一条河流中产卵。","extra":"比喻用法：The new technology spawned an entire industry."},{"chapter":3,"key":"3:47","id":47,"word":"feather","phonetic":"/ˈfeðə/","pos":"n.","meaningCN":"羽毛，翎毛","tag":"核心","root":"","exampleEN":"Birds clean their feathers to keep them in good condition for flying.","exampleCN":"鸟类清洁羽毛以保持飞行时的良好状态。","extra":"习语：light as a feather, birds of a feather (一丘之貉)"},{"chapter":3,"key":"3:48","id":48,"word":"fur","phonetic":"/fɜː/","pos":"n.","meaningCN":"（动物的）软毛；（用于制衣等的）毛皮","tag":"核心","root":"","exampleEN":"Arctic animals like foxes grow thick white fur to survive the cold.","exampleCN":"像狐狸这样的北极动物长出厚厚的白色皮毛来抵御寒冷。","extra":"形容词：furry (毛茸茸的)"},{"chapter":3,"key":"3:49","id":49,"word":"mature","phonetic":"/məˈtjʊə/","pos":"adj.","meaningCN":"成熟的 v.成熟","tag":"核心","root":"","exampleEN":"Young eagles take several years to mature fully.","exampleCN":"幼鹰需要几年时间才能完全成熟。","extra":"反义词：immature (不成熟的)；名词：maturity"},{"chapter":3,"key":"3:50","id":50,"word":"bristle","phonetic":"/ˈbrɪsəl/","pos":"n.","meaningCN":"鬃毛；（刷子的）毛","tag":"低频","root":"","exampleEN":"The wild boar's bristles stood up when it sensed danger.","exampleCN":"野猪的鬃毛在它察觉到危险时竖了起来。","extra":"动词：bristle (发怒；竖起)"},{"chapter":3,"key":"3:51","id":51,"word":"skin","phonetic":"/skɪn/","pos":"n.","meaningCN":"皮肤；外皮","tag":"核心","root":"","exampleEN":"Many reptiles shed their skin as they grow larger.","exampleCN":"许多爬行动物在长大时会蜕皮。","extra":"形容词：skinny (皮包骨的)；习语：save one's skin (保全性命)"},{"chapter":3,"key":"3:52","id":52,"word":"claw","phonetic":"/klɔː/","pos":"n.","meaningCN":"爪；钳；螯；爪状物","tag":"高频","root":"","exampleEN":"The cat used its claws to climb up the tree effortlessly.","exampleCN":"猫用它的爪子毫不费力地爬上了树。","extra":"动词：claw (抓，撕)"},{"chapter":3,"key":"3:53","id":53,"word":"curl","phonetic":"/kɜːl/","pos":"n.","meaningCN":"鬃发；卷曲；螺旋状物 v.（使）卷曲","tag":"低频","root":"","exampleEN":"The pig's tail has a tight curl at the end.","exampleCN":"猪的尾巴末端有一个紧密的卷曲。","extra":"形容词：curly (卷曲的)"},{"chapter":3,"key":"3:54","id":54,"word":"paw","phonetic":"/pɔː/","pos":"n.","meaningCN":"（动物的）脚掌，爪子","tag":"核心","root":"","exampleEN":"The dog lifted its paw to shake hands with its owner.","exampleCN":"狗抬起它的爪子与主人握手。","extra":"动词：paw (用爪子抓)"},{"chapter":3,"key":"3:55","id":55,"word":"beak","phonetic":"/biːk/","pos":"n.","meaningCN":"鸟嘴，喙","tag":"高频","root":"","exampleEN":"The woodpecker uses its sharp beak to drill holes in tree trunks.","exampleCN":"啄木鸟用其锋利的喙在树干上钻孔。","extra":"同义词：bill (多用于鸭鹅类)"},{"chapter":3,"key":"3:56","id":56,"word":"insect","phonetic":"/ˈɪnsekt/","pos":"n.","meaningCN":"昆虫","tag":"核心","root":"sect（切割）","exampleEN":"Bees, ants, and butterflies are all common insects found in gardens.","exampleCN":"蜜蜂、蚂蚁和蝴蝶都是花园中常见的昆虫。","extra":"词根相关：bisect (二等分), intersection (交叉)"},{"chapter":3,"key":"3:57","id":57,"word":"worm","phonetic":"/wɜːm/","pos":"n.","meaningCN":"蠕虫","tag":"高频","root":"","exampleEN":"Earthworms help improve soil quality by breaking down organic matter.","exampleCN":"蚯蚓通过分解有机物帮助改善土壤质量。","extra":"动词：worm (蠕动)；习语：the early bird catches the worm"},{"chapter":3,"key":"3:58","id":58,"word":"pest","phonetic":"/pest/","pos":"n.","meaningCN":"害虫；有害动物","tag":"核心","root":"","exampleEN":"Farmers use various methods to control pests that damage their crops.","exampleCN":"农民使用各种方法来控制破坏庄稼的害虫。","extra":"派生词：pesticide (杀虫剂)；比喻：social pest (社会败类)"},{"chapter":3,"key":"3:59","id":59,"word":"parasite","phonetic":"/ˈpærəsaɪt/","pos":"n.","meaningCN":"寄生虫","tag":"高频","root":"","exampleEN":"Ticks are parasites that feed on the blood of mammals and birds.","exampleCN":"蜱虫是以哺乳动物和鸟类血液为食的寄生虫。","extra":"形容词：parasitic (寄生的)"},{"chapter":3,"key":"3:60","id":60,"word":"tortoise","phonetic":"/ˈtɔːtəs/","pos":"n.","meaningCN":"龟，陆龟","tag":"高频","root":"","exampleEN":"Giant tortoises can live for more than a hundred years.","exampleCN":"巨型陆龟可以活一百多年。","extra":"对比：turtle (海龟/水龟)"},{"chapter":3,"key":"3:61","id":61,"word":"turtle","phonetic":"/ˈtɜːtl/","pos":"n.","meaningCN":"海龟","tag":"高频","root":"","exampleEN":"Sea turtles return to the beach where they were born to lay their eggs.","exampleCN":"海龟回到它们出生的海滩产卵。","extra":"对比：tortoise (陆龟)"},{"chapter":3,"key":"3:62","id":62,"word":"whale","phonetic":"/weɪl/","pos":"n.","meaningCN":"鲸鱼","tag":"核心","root":"","exampleEN":"Whales are marine mammals that communicate using complex sounds.","exampleCN":"鲸鱼是使用复杂声音进行交流的海洋哺乳动物。","extra":"动词：whale (捕鲸；猛击)；习语：have a whale of a time (玩得非常开心)"},{"chapter":3,"key":"3:63","id":63,"word":"spider","phonetic":"/ˈspaɪdə/","pos":"n.","meaningCN":"蜘蛛","tag":"核心","root":"","exampleEN":"The spider spins a web to catch flying insects for food.","exampleCN":"蜘蛛织网捕捉飞行的昆虫作为食物。","extra":"搭配：a spider's web (蜘蛛网)"},{"chapter":3,"key":"3:64","id":64,"word":"butterfly","phonetic":"/ˈbʌtəflaɪ/","pos":"n.","meaningCN":"蝴蝶","tag":"核心","root":"","exampleEN":"Butterflies undergo complete metamorphosis from caterpillar to adult.","exampleCN":"蝴蝶经历从毛虫到成虫的完全变态。","extra":"搭配：social butterfly (交际花)；形容词：butterfly-like"},{"chapter":3,"key":"3:65","id":65,"word":"mosquito","phonetic":"/məˈskiːtəʊ/","pos":"n.","meaningCN":"蚊子","tag":"核心","root":"","exampleEN":"Mosquitoes are attracted to human body heat and carbon dioxide.","exampleCN":"蚊子被人体的热量和二氧化碳吸引。","extra":"复数：mosquitoes 或 mosquitos"},{"chapter":3,"key":"3:66","id":66,"word":"cricket","phonetic":"/ˈkrɪkɪt/","pos":"n.","meaningCN":"蟋蟀","tag":"低频","root":"","exampleEN":"The sound of crickets chirping is common on warm summer nights.","exampleCN":"蟋蟀鸣叫的声音在温暖的夏夜很常见。","extra":"另义：板球运动；习语：not cricket (不公平)"},{"chapter":3,"key":"3:67","id":67,"word":"penguin","phonetic":"/ˈpeŋɡwɪn/","pos":"n.","meaningCN":"企鹅","tag":"核心","root":"","exampleEN":"Penguins huddle together to keep warm in the freezing Antarctic winter.","exampleCN":"在寒冷的南极冬季，企鹅挤在一起取暖。","extra":"注意拼写：不是 penguinn"},{"chapter":3,"key":"3:68","id":68,"word":"seal","phonetic":"/siːl/","pos":"n.","meaningCN":"海豹；封条；图章 v.密封","tag":"高频","root":"","exampleEN":"Seals use their flippers to swim quickly through the water.","exampleCN":"海豹用它们的鳍状肢在水中快速游动。","extra":"形容词：sealed (密封的)"},{"chapter":3,"key":"3:69","id":69,"word":"kangaroo","phonetic":"/ˌkæŋɡəˈruː/","pos":"n.","meaningCN":"袋鼠","tag":"高频","root":"","exampleEN":"Kangaroos carry their young in a pouch on their belly.","exampleCN":"袋鼠把它们的幼崽放在腹部的育儿袋里。","extra":"群体名词：a mob of kangaroos"},{"chapter":3,"key":"3:70","id":70,"word":"camel","phonetic":"/ˈkæməl/","pos":"n.","meaningCN":"骆驼","tag":"高频","root":"","exampleEN":"Camels store fat in their humps, which they use as energy when food is scarce.","exampleCN":"骆驼把脂肪储存在驼峰中，在食物稀缺时用作能量。","extra":"双峰驼：Bactrian camel；单峰驼：dromedary"},{"chapter":3,"key":"3:71","id":71,"word":"panda","phonetic":"/ˈpændə/","pos":"n.","meaningCN":"熊猫","tag":"核心","root":"","exampleEN":"Giant pandas spend most of their day eating bamboo in the forest.","exampleCN":"大熊猫一天中的大部分时间都在森林里吃竹子。","extra":"保护现状：vulnerable (易危)"},{"chapter":3,"key":"3:72","id":72,"word":"elephant","phonetic":"/ˈelɪfənt/","pos":"n.","meaningCN":"象","tag":"核心","root":"","exampleEN":"Elephants have excellent memories and can recognize individuals after many years.","exampleCN":"大象有极好的记忆力，多年后仍能认出个体。","extra":"群体名词：a herd of elephants"},{"chapter":3,"key":"3:73","id":73,"word":"trunk","phonetic":"/trʌŋk/","pos":"n.","meaningCN":"象鼻","tag":"高频","root":"","exampleEN":"The elephant uses its trunk to pick up food and spray water.","exampleCN":"大象用它的鼻子捡起食物和喷水。","extra":"其他意思：树干；行李箱；躯干"},{"chapter":3,"key":"3:74","id":74,"word":"ivory","phonetic":"/ˈaɪvəri/","pos":"n.","meaningCN":"象牙","tag":"高频","root":"","exampleEN":"The international ivory trade has been banned to protect elephants.","exampleCN":"为了保护大象，国际象牙贸易已被禁止。","extra":"习语：ivory tower (象牙塔)"},{"chapter":3,"key":"3:75","id":75,"word":"horn","phonetic":"/hɔːn/","pos":"n.","meaningCN":"（牛、羊等动物的）角；（乐器）号","tag":"高频","root":"","exampleEN":"Rhinoceros horns are made of keratin, the same material as human hair.","exampleCN":"犀牛角由角蛋白构成，与人类头发是相同的物质。","extra":"动词：horn (用角抵撞)"},{"chapter":3,"key":"3:76","id":76,"word":"bear","phonetic":"/beə/","pos":"n.","meaningCN":"熊","tag":"核心","root":"","exampleEN":"Brown bears hibernate during winter and live off their stored fat.","exampleCN":"棕熊在冬天冬眠，依靠储存的脂肪生存。","extra":"搭配：polar bear (北极熊)；动词 bear (忍受；生育)"},{"chapter":3,"key":"3:77","id":77,"word":"wolf","phonetic":"/wʊlf/","pos":"n.","meaningCN":"狼","tag":"核心","root":"","exampleEN":"Wolves hunt in packs to take down large prey like deer.","exampleCN":"狼成群狩猎以捕杀像鹿这样的大型猎物。","extra":"习语：a wolf in sheep's clothing (披着羊皮的狼)；复数：wolves"},{"chapter":3,"key":"3:78","id":78,"word":"dragon","phonetic":"/ˈdræɡən/","pos":"n.","meaningCN":"龙；悍妇","tag":"高频","root":"","exampleEN":"In European myths, dragons are often depicted as fire-breathing monsters.","exampleCN":"在欧洲神话中，龙通常被描绘成喷火的怪物。","extra":"形容词：draconian (严厉的)"},{"chapter":3,"key":"3:79","id":79,"word":"fox","phonetic":"/fɒks/","pos":"n.","meaningCN":"狐狸；狡猾的人","tag":"核心","root":"","exampleEN":"The fox is known for its cleverness and adaptability to urban environments.","exampleCN":"狐狸以其聪明和对城市环境的适应能力而闻名。","extra":"形容词：foxy (狡猾的；迷人的)"},{"chapter":3,"key":"3:80","id":80,"word":"cub","phonetic":"/kʌb/","pos":"n.","meaningCN":"幼兽","tag":"高频","root":"","exampleEN":"Lion cubs stay with their mother for about two years before becoming independent.","exampleCN":"幼狮在独立前会与母亲一起生活大约两年。","extra":"常见于：bear cub, lion cub, wolf cub"},{"chapter":3,"key":"3:81","id":81,"word":"calf","phonetic":"/kɑːf/","pos":"n.","meaningCN":"幼兽；小牛","tag":"高频","root":"","exampleEN":"The elephant calf stayed close to its mother for protection.","exampleCN":"小象紧挨着它的母亲以寻求保护。","extra":"复数：calves；另指：小腿"},{"chapter":3,"key":"3:82","id":82,"word":"pup","phonetic":"/pʌp/","pos":"n.","meaningCN":"幼小动物","tag":"高频","root":"","exampleEN":"Seal pups are born with white fur that helps them blend into the ice.","exampleCN":"海豹幼崽出生时带有白色皮毛，帮助它们融入冰雪环境。","extra":"同义词：puppy (特指幼犬)"},{"chapter":3,"key":"3:83","id":83,"word":"lamb","phonetic":"/læm/","pos":"n.","meaningCN":"小羊，羔羊","tag":"高频","root":"","exampleEN":"The lamb followed its mother everywhere in the meadow.","exampleCN":"小羊在草地上到处跟着它的母亲。","extra":"习语：like a lamb to the slaughter (像待宰的羔羊)"},{"chapter":3,"key":"3:84","id":84,"word":"cattle","phonetic":"/ˈkætl/","pos":"n.","meaningCN":"牛","tag":"核心","root":"","exampleEN":"Farmers raise cattle for milk, meat, and leather.","exampleCN":"农民饲养牛以获取牛奶、肉和皮革。","extra":"集合名词，复数形式；单数：head of cattle"},{"chapter":3,"key":"3:85","id":85,"word":"ox","phonetic":"/ɒks/","pos":"n.","meaningCN":"（阉割的）公牛","tag":"高频","root":"","exampleEN":"Oxen were traditionally used to pull plows on farms.","exampleCN":"公牛传统上被用于在农场拉犁。","extra":"复数：oxen"},{"chapter":3,"key":"3:86","id":86,"word":"bull","phonetic":"/bʊl/","pos":"n.","meaningCN":"公牛","tag":"高频","root":"","exampleEN":"The bull charged at the red cape waved by the matador.","exampleCN":"公牛冲向斗牛士挥舞的红布。","extra":"习语：take the bull by the horns (勇敢面对困难)"},{"chapter":3,"key":"3:87","id":87,"word":"buffalo","phonetic":"/ˈbʌfələʊ/","pos":"n.","meaningCN":"水牛；野牛","tag":"高频","root":"","exampleEN":"Large herds of buffalo once roamed the North American plains.","exampleCN":"大群野牛曾经漫游在北美的平原上。","extra":"复数：buffaloes 或 buffalo"},{"chapter":3,"key":"3:88","id":88,"word":"horse","phonetic":"/hɔːs/","pos":"n.","meaningCN":"马","tag":"核心","root":"","exampleEN":"Horses are social animals that live in groups called herds.","exampleCN":"马是群居动物，生活在被称为马群的群体中。","extra":"习语：put the cart before the horse (本末倒置)"},{"chapter":3,"key":"3:89","id":89,"word":"zebra","phonetic":"/ˈziːbrə/","pos":"n.","meaningCN":"斑马","tag":"高频","root":"","exampleEN":"Each zebra has a unique stripe pattern, just like human fingerprints.","exampleCN":"每只斑马都有独特的条纹图案，就像人类的指纹一样。","extra":"群体名词：a herd of zebras"},{"chapter":3,"key":"3:90","id":90,"word":"donkey","phonetic":"/ˈdɒŋki/","pos":"n.","meaningCN":"驴；傻瓜","tag":"高频","root":"","exampleEN":"Donkeys are known for their stubbornness but also their intelligence.","exampleCN":"驴以倔强著称，但也以聪明闻名。","extra":"同义词：ass"},{"chapter":3,"key":"3:91","id":91,"word":"saddle","phonetic":"/ˈsædl/","pos":"n.","meaningCN":"鞍，马鞍；车座","tag":"高频","root":"","exampleEN":"The rider adjusted the saddle to fit the horse comfortably.","exampleCN":"骑手调整马鞍使其适合马匹的舒适度。","extra":"动词：saddle (给……备鞍)；习语：in the saddle (在职)"},{"chapter":3,"key":"3:92","id":92,"word":"harness","phonetic":"/ˈhɑːnɪs/","pos":"n.","meaningCN":"马具，挽具","tag":"低频","root":"","exampleEN":"The farmer attached the harness to the horse before plowing the field.","exampleCN":"农民在犁地前把马具套在马身上。","extra":"动词：harness (利用；给……上挽具)；习语：in harness (通力合作)"},{"chapter":3,"key":"3:93","id":93,"word":"falcon","phonetic":"/ˈfɔːlkən/","pos":"n.","meaningCN":"隼，猎鹰","tag":"低频","root":"","exampleEN":"Falcons are extremely fast and can dive at speeds over 200 miles per hour.","exampleCN":"隼极其快速，能以每小时超过200英里的速度俯冲。","extra":"相关：falconry (猎鹰术)"},{"chapter":3,"key":"3:94","id":94,"word":"hawk","phonetic":"/hɔːk/","pos":"n.","meaningCN":"鹰，隼","tag":"高频","root":"","exampleEN":"The hawk circled above the field, scanning for small rodents.","exampleCN":"鹰在田野上方盘旋，寻找小型啮齿动物。","extra":"动词：hawk (兜售；咳出)；政治术语：hawk (鹰派)"},{"chapter":3,"key":"3:95","id":95,"word":"eagle","phonetic":"/ˈiːɡl/","pos":"n.","meaningCN":"雕","tag":"核心","root":"","exampleEN":"The bald eagle is a symbol of strength and freedom in the United States.","exampleCN":"白头雕在美国是力量和自由的象征。","extra":"形容词：eagle-eyed (目光锐利的)"},{"chapter":3,"key":"3:96","id":96,"word":"owl","phonetic":"/aʊl/","pos":"n.","meaningCN":"猫头鹰","tag":"高频","root":"","exampleEN":"Owls have excellent night vision and can rotate their heads almost 270 degrees.","exampleCN":"猫头鹰有极佳的夜视能力，并且几乎可以将头部旋转270度。","extra":"群体名词：a parliament of owls"},{"chapter":3,"key":"3:97","id":97,"word":"swallow","phonetic":"/ˈswɒləʊ/","pos":"n.","meaningCN":"燕子","tag":"高频","root":"","exampleEN":"Swallows migrate long distances between their summer and winter homes.","exampleCN":"燕子在夏季和冬季的家园之间长途迁徙。","extra":"动词 swallow (吞咽) 为不同词"},{"chapter":3,"key":"3:98","id":98,"word":"sparrow","phonetic":"/ˈspærəʊ/","pos":"n.","meaningCN":"麻雀","tag":"高频","root":"","exampleEN":"Sparrows are small brown birds commonly found in cities and farmlands.","exampleCN":"麻雀是城市和农田常见的小型棕色鸟类。","extra":"群体名词：a flock of sparrows"},{"chapter":3,"key":"3:99","id":99,"word":"pigeon","phonetic":"/ˈpɪdʒɪn/","pos":"n.","meaningCN":"鸽子","tag":"核心","root":"","exampleEN":"Pigeons have an amazing ability to find their way home over long distances.","exampleCN":"鸽子在长距离中找到回家路的能力令人惊叹。","extra":"同义词：dove (但 dove 通常象征和平)"},{"chapter":3,"key":"3:100","id":100,"word":"crow","phonetic":"/krəʊ/","pos":"n.","meaningCN":"乌鸦","tag":"高频","root":"","exampleEN":"Crows are highly intelligent and can even use tools to obtain food.","exampleCN":"乌鸦非常聪明，甚至能使用工具获取食物。","extra":"动词：crow (啼叫；得意洋洋)"},{"chapter":3,"key":"3:101","id":101,"word":"swan","phonetic":"/swɒn/","pos":"n.","meaningCN":"天鹅","tag":"高频","root":"","exampleEN":"Swans usually mate for life and are often seen swimming in pairs.","exampleCN":"天鹅通常终生交配，常常成对游泳。","extra":"习语：sb.'s swan song (某人最后的作品)"},{"chapter":3,"key":"3:102","id":102,"word":"goose","phonetic":"/ɡuːs/","pos":"n.","meaningCN":"鹅；鹅肉","tag":"高频","root":"","exampleEN":"Geese are known to be protective of their nests and may chase intruders.","exampleCN":"鹅以保护巢穴而闻名，甚至会追逐闯入者。","extra":"复数：geese；雄性：gander"},{"chapter":3,"key":"3:103","id":103,"word":"cock","phonetic":"/kɒk/","pos":"n.","meaningCN":"雄禽；公鸡","tag":"高频","root":"","exampleEN":"The cock crowed at dawn to announce the beginning of a new day.","exampleCN":"公鸡在黎明时打鸣宣告新一天的开始。","extra":"对比：hen (母鸡)"},{"chapter":3,"key":"3:104","id":104,"word":"mouse","phonetic":"/maʊs/","pos":"n.","meaningCN":"老鼠","tag":"核心","root":"","exampleEN":"Mice are often used in laboratory experiments due to their genetic similarity to humans.","exampleCN":"由于与人类的基因相似性，小鼠常被用于实验室实验。","extra":"复数：mice；对比：rat (大鼠，更大型)"},{"chapter":3,"key":"3:105","id":105,"word":"rat","phonetic":"/ræt/","pos":"n.","meaningCN":"老鼠；卑鄙的人","tag":"核心","root":"","exampleEN":"Rats are known carriers of diseases and have adapted well to urban life.","exampleCN":"老鼠是已知的疾病携带者，并且很好地适应了城市生活。","extra":"动词：rat (背叛；告密)"},{"chapter":3,"key":"3:106","id":106,"word":"squirrel","phonetic":"/ˈskwɪrəl/","pos":"n.","meaningCN":"松鼠","tag":"高频","root":"","exampleEN":"Squirrels bury nuts in the ground to eat later during winter.","exampleCN":"松鼠把坚果埋在地里，留到冬天吃。","extra":"动词：squirrel away (贮藏)"},{"chapter":3,"key":"3:107","id":107,"word":"hare","phonetic":"/heə/","pos":"n.","meaningCN":"野兔","tag":"低频","root":"","exampleEN":"Hares can run at high speeds to escape from predators.","exampleCN":"野兔能以高速奔跑来躲避捕食者。","extra":"对比：rabbit (家兔)；习语：mad as a March hare"},{"chapter":3,"key":"3:108","id":108,"word":"frog","phonetic":"/frɒɡ/","pos":"n.","meaningCN":"蛙","tag":"核心","root":"","exampleEN":"Frogs absorb water through their skin rather than drinking it.","exampleCN":"青蛙通过皮肤吸收水分，而不是直接饮用。","extra":"变态过程：tadpole (蝌蚪) → frog"},{"chapter":3,"key":"3:109","id":109,"word":"behaviour","phonetic":"/bɪˈheɪvjə/","pos":"n.","meaningCN":"行为；活动方式","tag":"核心","root":"","exampleEN":"The mating behaviour of birds varies greatly among different species.","exampleCN":"鸟类的交配行为在不同物种之间差异很大。","extra":"形容词：behavioural；美式拼写：behavior"},{"chapter":3,"key":"3:110","id":110,"word":"bite","phonetic":"/baɪt/","pos":"v./n.","meaningCN":"咬；（昆虫）叮；吞饵","tag":"核心","root":"","exampleEN":"The snake bit the man's leg before slithering away.","exampleCN":"那条蛇咬了那个男人的腿然后滑走了。","extra":"习语：bite off more than one can chew (不自量力), bite the bullet (硬着头皮)"},{"chapter":3,"key":"3:111","id":111,"word":"sting","phonetic":"/stɪŋ/","pos":"v.","meaningCN":"刺，叮；（使）感觉刺痛 n.刺，螫针","tag":"核心","root":"","exampleEN":"A bee sting can be very painful for people who are allergic.","exampleCN":"对过敏的人来说，蜜蜂蜇伤可能非常痛苦。","extra":"搭配：sting sb. into doing sth. (刺激某人做某事)"},{"chapter":3,"key":"3:112","id":112,"word":"bark","phonetic":"/bɑːk/","pos":"v.","meaningCN":"（狗等）吠；大声嚷 n.树皮","tag":"核心","root":"","exampleEN":"The neighbor's dog always barks loudly whenever someone walks past.","exampleCN":"每当有人走过时，邻居的狗总是大声吠叫。","extra":"习语：Barking dogs seldom bite. (吠犬不咬人)"},{"chapter":3,"key":"3:113","id":113,"word":"roar","phonetic":"/rɔː/","pos":"n./v.","meaningCN":"吼叫，咆哮","tag":"核心","root":"","exampleEN":"The lion roared loudly to warn other animals to stay away from its territory.","exampleCN":"狮子大声咆哮，警告其他动物远离其领地。","extra":"也可用于形容人群或机器的轰鸣"},{"chapter":3,"key":"3:114","id":114,"word":"rub","phonetic":"/rʌb/","pos":"v.","meaningCN":"擦；摩擦 n.困难，障碍","tag":"高频","root":"","exampleEN":"The cat rubbed its head against my leg to show affection.","exampleCN":"猫用头蹭我的腿以示亲昵。","extra":"习语：rub sb. the wrong way (惹怒某人)"},{"chapter":3,"key":"3:115","id":115,"word":"creep","phonetic":"/kriːp/","pos":"v.","meaningCN":"爬行；悄悄地缓慢行进","tag":"高频","root":"","exampleEN":"The hunter crept through the bushes to get closer to the deer.","exampleCN":"猎人悄悄地穿过灌木丛接近鹿。","extra":"搭配：creep along (匍匐前行)；过去式/过去分词：crept"},{"chapter":3,"key":"3:116","id":116,"word":"crawl","phonetic":"/krɔːl/","pos":"v.","meaningCN":"爬，爬行；卑躬屈膝","tag":"高频","root":"","exampleEN":"The baby learned to crawl before she could walk.","exampleCN":"婴儿在学会走路之前先学会了爬行。","extra":"比喻用法：crawl to sb. (巴结某人)"},{"chapter":3,"key":"3:117","id":117,"word":"habitat","phonetic":"/ˈhæbɪtæt/","pos":"n.","meaningCN":"（动植物的）生活环境，栖息地","tag":"核心","root":"","exampleEN":"Deforestation destroys the natural habitat of countless species.","exampleCN":"森林砍伐破坏了无数物种的自然栖息地。","extra":"同源词：inhabit (居住于), inhabitant (居民)"},{"chapter":3,"key":"3:118","id":118,"word":"nest","phonetic":"/nest/","pos":"n.","meaningCN":"巢，窝，穴","tag":"核心","root":"","exampleEN":"The bird built a nest using twigs and grass high up in the tree.","exampleCN":"那只鸟用树枝和草在高高的树上筑了一个巢。","extra":"动词：nest (筑巢)；习语：fly the nest (离巢独立)"},{"chapter":3,"key":"3:119","id":119,"word":"hive","phonetic":"/haɪv/","pos":"n.","meaningCN":"蜂房；繁忙的场所 v.（使）入蜂箱","tag":"高频","root":"","exampleEN":"A beehive can contain tens of thousands of bees living together.","exampleCN":"一个蜂箱可以容纳数万只蜜蜂共同生活。","extra":"比喻：a hive of activity (繁忙的场所)"},{"chapter":3,"key":"3:120","id":120,"word":"cell","phonetic":"/sel/","pos":"n.","meaningCN":"蜂房巢室；细胞；单人牢房","tag":"核心","root":"","exampleEN":"Honeybees store honey in wax cells within the hive.","exampleCN":"蜜蜂将蜂蜜储存在蜂巢内的蜡质巢室中。","extra":"形容词：cellular (细胞的；蜂窝状的)"},{"chapter":3,"key":"3:121","id":121,"word":"cage","phonetic":"/keɪdʒ/","pos":"n.","meaningCN":"笼子","tag":"核心","root":"","exampleEN":"Many people believe that keeping birds in cages is cruel.","exampleCN":"许多人认为把鸟关在笼子里是残忍的。","extra":"动词：cage (关进笼子)"},{"chapter":3,"key":"3:122","id":122,"word":"stable","phonetic":"/ˈsteɪbəl/","pos":"n.","meaningCN":"马厩；牛棚 adj.稳定的","tag":"高频","root":"","exampleEN":"The horses were led back to the stable after the long ride.","exampleCN":"长途骑行后，马被带回了马厩。","extra":"形容词词义更常用；反义词：unstable"},{"chapter":3,"key":"3:123","id":123,"word":"barn","phonetic":"/bɑːn/","pos":"n.","meaningCN":"谷仓；牲口棚","tag":"高频","root":"","exampleEN":"The farmer stored hay and farm equipment inside the large barn.","exampleCN":"农民把干草和农具存放在大谷仓里。","extra":"习语：close the barn door after the horse is stolen (亡羊补牢)"},{"chapter":3,"key":"3:124","id":124,"word":"hedge","phonetic":"/hedʒ/","pos":"n.","meaningCN":"树篱；障碍物","tag":"高频","root":"","exampleEN":"The garden was surrounded by a tall hedge that provided privacy.","exampleCN":"花园被一道高高的树篱环绕，提供了隐私。","extra":"动词：hedge (规避；用树篱围住)；习语：on the hedge (骑墙观望)"},{"chapter":3,"key":"3:125","id":125,"word":"barrier","phonetic":"/ˈbæriə/","pos":"n.","meaningCN":"障碍；屏障","tag":"核心","root":"","exampleEN":"Language barrier can be a major obstacle for international students.","exampleCN":"语言障碍可能是留学生面临的主要困难。","extra":"同义词：obstacle, hurdle"},{"chapter":3,"key":"3:126","id":126,"word":"bar","phonetic":"/bɑː/","pos":"n.","meaningCN":"栅，栏杆；条，长块","tag":"高频","root":"","exampleEN":"The chimpanzee used a metal bar to break open the nuts.","exampleCN":"黑猩猩用一根金属棒砸开坚果。","extra":"动词：bar (禁止；闩上)；习语：behind bars (坐牢)"},{"chapter":3,"key":"3:127","id":127,"word":"anatomy","phonetic":"/əˈnætəmi/","pos":"n.","meaningCN":"解剖学","tag":"高频","root":"","exampleEN":"Studying anatomy helps doctors understand how the human body works.","exampleCN":"学习解剖学帮助医生理解人体如何运作。","extra":"形容词：anatomical (解剖的)"},{"chapter":3,"key":"3:128","id":128,"word":"epidemic","phonetic":"/ˌepɪˈdemɪk/","pos":"n.","meaningCN":"流行病；（坏事的）盛行 adj.流行性的","tag":"核心","root":"","exampleEN":"The government took swift measures to contain the epidemic.","exampleCN":"政府迅速采取措施控制流行病。","extra":"搭配：control an epidemic (控制疫情)；对比：pandemic (大流行)"},{"chapter":3,"key":"3:129","id":129,"word":"gene","phonetic":"/dʒiːn/","pos":"n.","meaningCN":"基因","tag":"核心","root":"","exampleEN":"Certain genes determine the color of a person's eyes and hair.","exampleCN":"某些基因决定人的眼睛和头发颜色。","extra":"形容词：genetic (基因的)；搭配：gene pool (基因库)"},{"chapter":3,"key":"3:130","id":130,"word":"germ","phonetic":"/dʒɜːm/","pos":"n.","meaningCN":"微生物，细菌","tag":"高频","root":"","exampleEN":"Washing your hands regularly can help kill germs and prevent illness.","exampleCN":"经常洗手有助于杀死细菌并预防疾病。","extra":"同义词：microbe, bacterium"},{"chapter":3,"key":"3:131","id":131,"word":"bacteria","phonetic":"/bækˈtɪəriə/","pos":"n.","meaningCN":"（bacterium的复数）细菌","tag":"核心","root":"","exampleEN":"Some bacteria are harmful, but many are essential for digestion.","exampleCN":"有些细菌是有害的，但许多对消化至关重要。","extra":"单数：bacterium；形容词：bacterial"},{"chapter":3,"key":"3:132","id":132,"word":"virus","phonetic":"/ˈvaɪrəs/","pos":"n.","meaningCN":"病毒","tag":"核心","root":"","exampleEN":"The flu virus spreads easily through coughs and sneezes.","exampleCN":"流感病毒通过咳嗽和打喷嚏轻易传播。","extra":"形容词：viral (病毒的)；计算机术语：computer virus"},{"chapter":3,"key":"3:133","id":133,"word":"microbe","phonetic":"/ˈmaɪkrəʊb/","pos":"n.","meaningCN":"微生物","tag":"高频","root":"","exampleEN":"Microbes are so tiny that you need a microscope to see them.","exampleCN":"微生物非常微小，需要显微镜才能看到。","extra":"相关：microbiology (微生物学)"},{"chapter":3,"key":"3:134","id":134,"word":"metabolism","phonetic":"/məˈtæbəlɪzəm/","pos":"n.","meaningCN":"新陈代谢","tag":"高频","root":"","exampleEN":"Exercise can speed up your metabolism and help you burn more calories.","exampleCN":"运动可以加速新陈代谢，帮助燃烧更多卡路里。","extra":"形容词：metabolic (新陈代谢的)"},{"chapter":3,"key":"3:135","id":135,"word":"protein","phonetic":"/ˈprəʊtiːn/","pos":"n.","meaningCN":"蛋白质","tag":"核心","root":"","exampleEN":"Protein is essential for building and repairing muscles after exercise.","exampleCN":"蛋白质对于运动后肌肉的构建和修复至关重要。","extra":"来源：肉类、豆类、乳制品"},{"chapter":3,"key":"3:136","id":136,"word":"vitamin","phonetic":"/ˈvɪtəmɪn/","pos":"n.","meaningCN":"维生素","tag":"核心","root":"vita（生命）","exampleEN":"Oranges are rich in vitamin C, which helps boost the immune system.","exampleCN":"橙子富含维生素C，有助于增强免疫系统。","extra":"词根含义：vita-生命；vitamin 即'维持生命所必需的物质'"},{"chapter":3,"key":"3:137","id":137,"word":"intelligence","phonetic":"/ɪnˈtelɪdʒəns/","pos":"n.","meaningCN":"智慧，智力；情报","tag":"核心","root":"","exampleEN":"Dolphins are known for their high intelligence and complex social behavior.","exampleCN":"海豚以高智商和复杂的社会行为而闻名。","extra":"形容词：intelligent (聪明的)；搭配：artificial intelligence (AI)"},{"chapter":3,"key":"3:138","id":138,"word":"functional","phonetic":"/ˈfʌŋkʃənəl/","pos":"adj.","meaningCN":"功能的；起作用的","tag":"核心","root":"","exampleEN":"The wings of a bird have a functional role in flight.","exampleCN":"鸟类的翅膀在飞行中起着功能性的作用。","extra":"名词：function (功能)；副词：functionally"},{"chapter":3,"key":"3:139","id":139,"word":"secrete","phonetic":"/sɪˈkriːt/","pos":"v.","meaningCN":"分泌","tag":"高频","root":"","exampleEN":"The salivary glands secrete saliva to help digest food.","exampleCN":"唾液腺分泌唾液以帮助消化食物。","extra":"注意与 secret (秘密) 区分"},{"chapter":3,"key":"3:140","id":140,"word":"excrete","phonetic":"/ɪkˈskriːt/","pos":"v.","meaningCN":"排泄；分泌","tag":"高频","root":"","exampleEN":"The kidneys excrete waste products from the blood in the form of urine.","exampleCN":"肾脏以尿液的形式排泄血液中的废物。","extra":"名词：excretion (排泄物)"},{"chapter":3,"key":"3:141","id":141,"word":"devour","phonetic":"/dɪˈvaʊə/","pos":"v.","meaningCN":"吞食，狼吞虎咽地吃","tag":"高频","root":"","exampleEN":"The hungry wolf devoured the entire deer in minutes.","exampleCN":"饥饿的狼在几分钟内就吞食了整只鹿。","extra":"比喻用法：devour books (如饥似渴地读书)"},{"chapter":3,"key":"3:142","id":142,"word":"instinct","phonetic":"/ˈɪnstɪŋkt/","pos":"n.","meaningCN":"本能，天性；直觉","tag":"核心","root":"","exampleEN":"Birds build nests by instinct, without being taught.","exampleCN":"鸟类凭本能筑巢，不需要被教导。","extra":"形容词：instinctive (本能的)；搭配：follow one's instincts"},{"chapter":3,"key":"3:143","id":143,"word":"intuitive","phonetic":"/ɪnˈtjuːɪtɪv/","pos":"adj.","meaningCN":"直觉的","tag":"高频","root":"","exampleEN":"She had an intuitive feeling that something was wrong with the experiment.","exampleCN":"她有一种直觉，觉得实验出了问题。","extra":"名词：intuition (直觉)"},{"chapter":3,"key":"3:144","id":144,"word":"potential","phonetic":"/pəˈtenʃəl/","pos":"n.","meaningCN":"潜力 adj.潜在的","tag":"核心","root":"","exampleEN":"Every student has the potential to succeed with hard work.","exampleCN":"每个学生都有通过努力取得成功的潜力。","extra":"常见搭配：realize one's potential (发挥潜力)"},{"chapter":3,"key":"3:145","id":145,"word":"sensitive","phonetic":"/ˈsensɪtɪv/","pos":"adj.","meaningCN":"灵敏的；过敏的；易担忧的","tag":"核心","root":"","exampleEN":"Dogs have a highly sensitive sense of smell, much better than humans.","exampleCN":"狗有高度灵敏的嗅觉，比人类强得多。","extra":"搭配：be sensitive to (对……敏感)；名词：sensitivity"},{"chapter":3,"key":"3:146","id":146,"word":"flexible","phonetic":"/ˈfleksəbəl/","pos":"adj.","meaningCN":"可弯曲的；灵活的","tag":"核心","root":"","exampleEN":"The spine of a snake is extremely flexible, allowing it to move in many ways.","exampleCN":"蛇的脊柱极其灵活，使其能以多种方式移动。","extra":"名词：flexibility (灵活性)"},{"chapter":3,"key":"3:147","id":147,"word":"acoustic","phonetic":"/əˈkuːstɪk/","pos":"adj.","meaningCN":"听觉的；声音的","tag":"高频","root":"","exampleEN":"Bats use acoustic signals to navigate in the dark.","exampleCN":"蝙蝠利用声音信号在黑暗中导航。","extra":"名词：acoustics (声学；音响效果)"},{"chapter":3,"key":"3:148","id":148,"word":"optical","phonetic":"/ˈɒptɪkəl/","pos":"adj.","meaningCN":"视觉的；光学的","tag":"高频","root":"","exampleEN":"Eagles have sharp optical ability to spot prey from great heights.","exampleCN":"鹰有敏锐的视觉能力，能从高处发现猎物。","extra":"相关：optic (眼睛的), optician (验光师)"},{"chapter":3,"key":"3:149","id":149,"word":"nocturnal","phonetic":"/nɒkˈtɜːnəl/","pos":"adj.","meaningCN":"夜间发生的；夜间活动的","tag":"高频","root":"","exampleEN":"Owls are nocturnal hunters, sleeping during the day and hunting at night.","exampleCN":"猫头鹰是夜行性猎手，白天睡觉，夜晚捕食。","extra":"反义词：diurnal (白天的)"},{"chapter":3,"key":"3:150","id":150,"word":"dormant","phonetic":"/ˈdɔːmənt/","pos":"adj.","meaningCN":"睡着的；休眠的；冬眠的","tag":"高频","root":"","exampleEN":"Some volcanoes remain dormant for centuries before erupting again.","exampleCN":"一些火山在再次喷发前会休眠数百年。","extra":"名词：dormancy (休眠)"},{"chapter":3,"key":"3:151","id":151,"word":"hibernation","phonetic":"/ˌhaɪbəˈneɪʃən/","pos":"n.","meaningCN":"冬眠","tag":"高频","root":"","exampleEN":"During hibernation, a bear's heart rate slows down dramatically.","exampleCN":"在冬眠期间，熊的心率显著减慢。","extra":"动词：hibernate (冬眠)"},{"chapter":3,"key":"3:152","id":152,"word":"track","phonetic":"/træk/","pos":"v.","meaningCN":"追踪 n.足迹，踪迹；轨道","tag":"核心","root":"","exampleEN":"The hunter tracked the deer through the snow-covered forest.","exampleCN":"猎人穿过白雪覆盖的森林追踪那只鹿。","extra":"搭配：track down (追捕到)"},{"chapter":3,"key":"3:153","id":153,"word":"trace","phonetic":"/treɪs/","pos":"v.","meaningCN":"追踪；查出；追溯 n.痕迹；少许","tag":"核心","root":"","exampleEN":"Scientists traced the origin of the virus to a bat species.","exampleCN":"科学家将病毒的起源追溯到一种蝙蝠。","extra":"搭配：trace back to (追溯到)；a trace of (一丝)"},{"chapter":3,"key":"3:154","id":154,"word":"alternate","phonetic":"/ˈɔːltəneɪt/","pos":"v.","meaningCN":"（使）交替，（使）轮流","tag":"高频","root":"","exampleEN":"In some bird species, parents alternate sitting on the eggs.","exampleCN":"在一些鸟类中，父母轮流孵蛋。","extra":"形容词：alternate (交替的)；名词：alternative (替代选择)"},{"chapter":3,"key":"3:155","id":155,"word":"prey","phonetic":"/preɪ/","pos":"n.","meaningCN":"被捕食的动物，猎物 v.捕食","tag":"核心","root":"","exampleEN":"Lions often hunt at night when their prey is less alert.","exampleCN":"狮子常常在夜间猎食，那时它们的猎物警惕性较低。","extra":"搭配：prey on (捕食；掠夺)"},{"chapter":3,"key":"3:156","id":156,"word":"predator","phonetic":"/ˈpredətə/","pos":"n.","meaningCN":"掠夺者；捕食性动物","tag":"核心","root":"","exampleEN":"The cheetah is one of the fastest predators on land.","exampleCN":"猎豹是陆地上最快的捕食者之一。","extra":"名词：predation (捕食)；形容词：predatory"},{"chapter":3,"key":"3:157","id":157,"word":"victim","phonetic":"/ˈvɪktɪm/","pos":"n.","meaningCN":"受害者；牺牲者","tag":"核心","root":"","exampleEN":"The deer became a victim of the hungry wolf pack.","exampleCN":"那只鹿成了饥饿狼群的牺牲品。","extra":"搭配：fall victim to (成为……的受害者)"},{"chapter":3,"key":"3:158","id":158,"word":"captive","phonetic":"/ˈkæptɪv/","pos":"n.","meaningCN":"俘虏 adj.被关押的；受控制的","tag":"高频","root":"","exampleEN":"Wild animals in captivity often exhibit abnormal behaviors.","exampleCN":"被关押的野生动物常常表现出异常行为。","extra":"动词：capture (捕获)；形容词：captivating (迷人的)"},{"chapter":3,"key":"3:159","id":159,"word":"defensive","phonetic":"/dɪˈfensɪv/","pos":"adj.","meaningCN":"防御性的","tag":"核心","root":"","exampleEN":"The porcupine raises its quills as a defensive reaction to threats.","exampleCN":"豪猪竖起它的刺作为对威胁的防御反应。","extra":"动词：defend (防卫)；名词：defense"},{"chapter":3,"key":"3:160","id":160,"word":"undergo","phonetic":"/ˌʌndəˈɡəʊ/","pos":"v.","meaningCN":"经历，经受","tag":"核心","root":"","exampleEN":"Caterpillars undergo a complete transformation into butterflies.","exampleCN":"毛毛虫经历完全变态成为蝴蝶。","extra":"过去式：underwent；过去分词：undergone"},{"chapter":3,"key":"3:161","id":161,"word":"suffer","phonetic":"/ˈsʌfə/","pos":"v.","meaningCN":"遭受；受折磨；变糟","tag":"核心","root":"","exampleEN":"Many animals suffer from habitat loss due to human activities.","exampleCN":"由于人类活动，许多动物遭受栖息地丧失的痛苦。","extra":"搭配：suffer from (受……之苦)；名词：suffering"},{"chapter":3,"key":"3:162","id":162,"word":"vulnerable","phonetic":"/ˈvʌlnərəbəl/","pos":"adj.","meaningCN":"易受伤的，脆弱的；易受影响的","tag":"核心","root":"","exampleEN":"Young animals are especially vulnerable to predators in the wild.","exampleCN":"幼小动物在野外尤其容易受到捕食者的攻击。","extra":"搭配：be vulnerable to；反义词：invulnerable"},{"chapter":3,"key":"3:163","id":163,"word":"subsistence","phonetic":"/səbˈsɪstəns/","pos":"n.","meaningCN":"勉强维持生活","tag":"高频","root":"","exampleEN":"Farmers in the region live at a subsistence level, growing only enough food for their families.","exampleCN":"该地区的农民生活在勉强糊口的水平，只种植够家人吃的食物。","extra":"动词：subsist (生存；维持生活)"},{"chapter":3,"key":"3:164","id":164,"word":"exist","phonetic":"/ɪɡˈzɪst/","pos":"v.","meaningCN":"存在；生存","tag":"核心","root":"","exampleEN":"Many species cannot exist outside their natural habitat.","exampleCN":"许多物种无法在其自然栖息地之外生存。","extra":"名词：existence (存在)；形容词：existing (现存的)"},{"chapter":3,"key":"3:165","id":165,"word":"exterminate","phonetic":"/ɪkˈstɜːmɪneɪt/","pos":"v.","meaningCN":"消灭，根除","tag":"高频","root":"","exampleEN":"Efforts to exterminate the invasive species have been costly but necessary.","exampleCN":"根除入侵物种的努力代价高昂但却是必要的。","extra":"名词：extermination (消灭)"},{"chapter":3,"key":"3:166","id":166,"word":"tame","phonetic":"/teɪm/","pos":"v.","meaningCN":"驯养；制服 adj.驯服的；乏味的","tag":"高频","root":"","exampleEN":"It takes patience and time to tame a wild horse.","exampleCN":"驯服一匹野马需要耐心和时间。","extra":"名词：tameness；反义词：wild"},{"chapter":3,"key":"3:167","id":167,"word":"keeper","phonetic":"/ˈkiːpə/","pos":"n.","meaningCN":"看守人；饲养员","tag":"高频","root":"","exampleEN":"The zoo keeper feeds the animals and cleans their enclosures every day.","exampleCN":"动物园管理员每天喂食动物并清洁它们的围栏。","extra":"常见搭配：zookeeper (动物园管理员)"},{"chapter":3,"key":"3:168","id":168,"word":"shepherd","phonetic":"/ˈʃepəd/","pos":"n.","meaningCN":"牧羊人，羊倌","tag":"高频","root":"","exampleEN":"The shepherd guided his flock through the valley to fresh grazing land.","exampleCN":"牧羊人引导他的羊群穿过山谷前往新鲜的牧场。","extra":"动词：shepherd (引导；照料)；相关：sheepdog (牧羊犬)"}],"4":[{"chapter":4,"key":"4:1","id":1,"word":"galaxy","phonetic":"/ˈɡæləksi/","pos":"n.","meaningCN":"星系；[the G-] 银河系","tag":"高频","root":"源于希腊语galakt-，意为“牛奶”，银河也称为the Milky Way。希腊神话中，赫拉的乳汁喷出形成银河。","exampleEN":"Our solar system is located in the Milky Way galaxy, which contains billions of stars.","exampleCN":"我们的太阳系位于包含数十亿颗恒星的银河系中。","extra":"常用搭配：a spiral galaxy 螺旋星系。"},{"chapter":4,"key":"4:2","id":2,"word":"cosmos","phonetic":"/ˈkɒzmɒs/","pos":"n.","meaningCN":"宇宙","tag":"低频","root":"","exampleEN":"The documentary explores the mysteries of the cosmos, from black holes to distant galaxies.","exampleCN":"这部纪录片探索了宇宙的奥秘，从黑洞到遥远的星系。","extra":"近义词：universe。"},{"chapter":4,"key":"4:3","id":3,"word":"universe","phonetic":"/ˈjuːnɪvɜːs/","pos":"n.","meaningCN":"宇宙；万物，世界","tag":"高频","root":"universal adj. 全世界的；字根uni（一）+ vers（转）→ 万物旋转成为一体","exampleEN":"Scientists are still debating whether the universe will expand forever or eventually collapse.","exampleCN":"科学家们仍在争论宇宙是会永远膨胀还是最终坍缩。","extra":"搭配：throughout the universe 在整个宇宙中。"},{"chapter":4,"key":"4:4","id":4,"word":"interstellar","phonetic":"/ˌɪntəˈstelə/","pos":"adj.","meaningCN":"星际的","tag":"高频","root":"inter（之间）+ stell（星）+ ar（后缀）→ 星星之间的 → 星际的","exampleEN":"Interstellar travel remains a distant dream due to the enormous distances between stars.","exampleCN":"由于恒星之间距离遥远，星际旅行仍是一个遥远的梦想。","extra":"常见搭配：interstellar medium 星际介质。"},{"chapter":4,"key":"4:5","id":5,"word":"terrestrial","phonetic":"/təˈrestriəl/","pos":"adj.","meaningCN":"地球的；（动植物）陆地的","tag":"高频","root":"extraterrestrial adj. 地球外的 n. 外星人（E.T.）","exampleEN":"While some species are aquatic, the majority of animals on Earth are terrestrial.","exampleCN":"虽然有些物种是水生的，但地球上大多数动物是陆生的。","extra":"反义词：aquatic 水生的。"},{"chapter":4,"key":"4:6","id":6,"word":"celestial","phonetic":"/səˈlestiəl/","pos":"adj.","meaningCN":"天上的","tag":"识记","root":"","exampleEN":"Ancient astronomers carefully mapped the movements of celestial bodies across the night sky.","exampleCN":"古代天文学家仔细绘制了天体在夜空中的运动轨迹。","extra":"搭配：celestial body 天体。"},{"chapter":4,"key":"4:7","id":7,"word":"astronomy","phonetic":"/əˈstrɒnəmi/","pos":"n.","meaningCN":"天文学","tag":"高频","root":"astronomical adj. 天文学的；字根astr指“星”","exampleEN":"The discovery of exoplanets has been one of the most exciting developments in modern astronomy.","exampleCN":"系外行星的发现是现代天文学最激动人心的进展之一。","extra":"形容词 astronomical 也可表示“极其巨大的”。"},{"chapter":4,"key":"4:8","id":8,"word":"astrology","phonetic":"/əˈstrɒlədʒi/","pos":"n.","meaningCN":"占星学；占星术","tag":"识记","root":"","exampleEN":"Although astrology is popular in many cultures, it lacks scientific evidence to support its claims.","exampleCN":"尽管占星学在许多文化中很流行，但它缺乏科学证据来支持其主张。","extra":"区分：astronomy（天文学）vs astrology（占星术）。"},{"chapter":4,"key":"4:9","id":9,"word":"astronaut","phonetic":"/ˈæstrənɔːt/","pos":"n.","meaningCN":"宇航员","tag":"高频","root":"naut（船）→ 在星星间航行的人；同根词：navy, navigate","exampleEN":"The astronaut spent six months aboard the space station conducting scientific experiments.","exampleCN":"这位宇航员在空间站上度过了六个月，进行科学实验。","extra":"同义词（俄）：cosmonaut。"},{"chapter":4,"key":"4:10","id":10,"word":"comet","phonetic":"/ˈkɒmɪt/","pos":"n.","meaningCN":"彗星","tag":"高频","root":"","exampleEN":"A bright comet with a glowing tail could be seen in the night sky last summer.","exampleCN":"去年夏天，夜空中可以看到一颗拖着发光尾巴的明亮彗星。","extra":"搭配：comet tail 彗尾。"},{"chapter":4,"key":"4:11","id":11,"word":"meteorite","phonetic":"/ˈmiːtiəraɪt/","pos":"n.","meaningCN":"陨石","tag":"低频","root":"","exampleEN":"The museum displayed a large iron meteorite that had fallen in the desert decades ago.","exampleCN":"博物馆陈列了一块数十年前坠落在沙漠中的大型铁陨石。","extra":"区分：meteoroid（流星体），meteor（流星），meteorite（陨石）。"},{"chapter":4,"key":"4:12","id":12,"word":"crater","phonetic":"/ˈkreɪtə/","pos":"n.","meaningCN":"（撞击或爆炸形成的）坑","tag":"低频","root":"","exampleEN":"High-resolution images show that the moon's surface is covered with impact craters of all sizes.","exampleCN":"高分辨率图像显示，月球表面布满了大小不一的撞击坑。","extra":"搭配：volcanic crater 火山口。"},{"chapter":4,"key":"4:13","id":13,"word":"dust","phonetic":"/dʌst/","pos":"n.","meaningCN":"尘土，灰尘，粉尘","tag":"核心","root":"","exampleEN":"After the sandstorm, a thick layer of dust covered every surface in the house.","exampleCN":"沙尘暴过后，房子里每个表面都覆盖了一层厚厚的灰尘。","extra":"搭配：cosmic dust 宇宙尘埃。"},{"chapter":4,"key":"4:14","id":14,"word":"ash","phonetic":"/æʃ/","pos":"n.","meaningCN":"灰烬","tag":"高頻","root":"","exampleEN":"Volcanic ash can travel thousands of kilometres and disrupt air travel.","exampleCN":"火山灰可以飘行数千公里，扰乱航空旅行。","extra":"搭配：volcanic ash 火山灰。"},{"chapter":4,"key":"4:15","id":15,"word":"envelope","phonetic":"/ˈenvələʊp/","pos":"n.","meaningCN":"外裹物，外层","tag":"低频","root":"","exampleEN":"The Sun's outer envelope, called the corona, is visible during a total solar eclipse.","exampleCN":"太阳的外层，即日冕，在日全食期间可以见到。","extra":"此处为天文学专业用法，非日常的信封。"},{"chapter":4,"key":"4:16","id":16,"word":"chunk","phonetic":"/tʃʌŋk/","pos":"n.","meaningCN":"厚块","tag":"高频","root":"","exampleEN":"He broke off a chunk of dark chocolate to have with his afternoon coffee.","exampleCN":"他掰下一大块黑巧克力，配下午咖啡食用。","extra":"搭配：a chunk of 一大块。"},{"chapter":4,"key":"4:17","id":17,"word":"spacecraft","phonetic":"/ˈspeɪskrɑːft/","pos":"n.","meaningCN":"宇宙飞船","tag":"高频","root":"aircraft n. 飞行器","exampleEN":"The unmanned spacecraft successfully landed on the rocky surface of an asteroid.","exampleCN":"这艘无人飞船成功降落在了一颗小行星的岩石表面上。","extra":"单复数同形。"},{"chapter":4,"key":"4:18","id":18,"word":"spaceship","phonetic":"/ˈspeɪsʃɪp/","pos":"n.","meaningCN":"宇宙飞船","tag":"低频","root":"","exampleEN":"In science fiction, spaceships often travel faster than light to explore distant stars.","exampleCN":"在科幻小说中，宇宙飞船常常超光速飞行以探索遥远的恒星。","extra":"同义词：spacecraft；spaceship 较口语化。"},{"chapter":4,"key":"4:19","id":19,"word":"probe","phonetic":"/prəʊb/","pos":"n.","meaningCN":"太空探测器；详尽调查","tag":"高频","root":"","exampleEN":"The space probe has sent back astonishing images of the rings around Saturn.","exampleCN":"太空探测器发回了土星环的惊人图像。","extra":"搭配：launch a probe 发射探测器。"},{"chapter":4,"key":"4:20","id":20,"word":"module","phonetic":"/ˈmɒdjuːl/","pos":"n.","meaningCN":"（航天器上各个独立的）舱；模块","tag":"高频","root":"","exampleEN":"The lunar module separated from the command module and began its descent to the moon.","exampleCN":"登月舱与指令舱分离，开始向月球下降。","extra":"搭配：service module 服务舱。"},{"chapter":4,"key":"4:21","id":21,"word":"propulsion","phonetic":"/prəˈpʌlʃən/","pos":"n.","meaningCN":"推进力","tag":"低频","root":"","exampleEN":"Electric propulsion systems are becoming more common in modern satellites.","exampleCN":"电推进系统在现代卫星中正变得越来越普遍。","extra":"搭配：jet propulsion 喷气推进。"},{"chapter":4,"key":"4:22","id":22,"word":"pressure","phonetic":"/ˈpreʃə/","pos":"n.","meaningCN":"压力","tag":"核心","root":"","exampleEN":"High atmospheric pressure usually brings clear skies, while low pressure often means rain.","exampleCN":"高气压通常带来晴天，而低气压常意味着降雨。","extra":"搭配：blood pressure 血压；under pressure 在压力之下。"},{"chapter":4,"key":"4:23","id":23,"word":"dynamics","phonetic":"/daɪˈnæmɪks/","pos":"n.","meaningCN":"动力学；动态","tag":"低频","root":"dynamic adj. 动态的；有活力的","exampleEN":"The course covers the dynamics of fluids and how they behave under different conditions.","exampleCN":"这门课程涵盖了流体动力学以及流体在不同条件下的表现。","extra":"搭配：group dynamics 群体动态。"},{"chapter":4,"key":"4:24","id":24,"word":"motion","phonetic":"/ˈməʊʃən/","pos":"n.","meaningCN":"动作；移动","tag":"核心","root":"motive n. 动机","exampleEN":"Newton's first law states that an object in motion will stay in motion unless acted upon by a force.","exampleCN":"牛顿第一定律指出，运动中的物体会保持运动，除非有外力作用。","extra":"搭配：in slow motion 慢动作。"},{"chapter":4,"key":"4:25","id":25,"word":"vent","phonetic":"/vent/","pos":"n.","meaningCN":"排气口 v. 排放；发泄","tag":"低频","root":"","exampleEN":"Hydrothermal vents on the deep ocean floor release superheated water rich in minerals.","exampleCN":"深海海底的热液喷口释放富含矿物质的超高温水。","extra":"搭配：give vent to 发泄（情绪）。"},{"chapter":4,"key":"4:26","id":26,"word":"tail","phonetic":"/teɪl/","pos":"n.","meaningCN":"尾部","tag":"高频","root":"","exampleEN":"As the comet approaches the Sun, its tail of gas and dust becomes longer and brighter.","exampleCN":"彗星靠近太阳时，其气体和尘埃尾变得更长更亮。","extra":"搭配：tail light 尾灯。"},{"chapter":4,"key":"4:27","id":27,"word":"curve","phonetic":"/kɜːv/","pos":"n.","meaningCN":"曲线，弧线","tag":"高频","root":"curvy adj. 弯曲的","exampleEN":"The spacecraft followed a gentle curve as it entered the planet's orbit.","exampleCN":"航天器进入行星轨道时沿着一道平缓的曲线飞行。","extra":"搭配：learning curve 学习曲线。"},{"chapter":4,"key":"4:28","id":28,"word":"exploration","phonetic":"/ˌekspləˈreɪʃən/","pos":"n.","meaningCN":"探索","tag":"核心","root":"","exampleEN":"Space exploration has led to the development of many technologies we now use in daily life.","exampleCN":"太空探索促进了许多我们如今在日常生活中使用的技术的发展。","extra":"搭配：deep-sea exploration 深海探索。"},{"chapter":4,"key":"4:29","id":29,"word":"expedition","phonetic":"/ˌekspɪˈdɪʃən/","pos":"n.","meaningCN":"远征，探险","tag":"高频","root":"字根ped（足）→ 使脚向外 → 远征","exampleEN":"The scientific expedition to Antarctica collected valuable samples from beneath the ice.","exampleCN":"南极科考探险从冰层下采集了珍贵的样本。","extra":"搭配：mount an expedition 组织探险。"},{"chapter":4,"key":"4:30","id":30,"word":"flyby","phonetic":"/ˈflaɪbaɪ/","pos":"n.","meaningCN":"（航天器对行星或卫星的）飞掠","tag":"识记","root":"","exampleEN":"The spacecraft performed a flyby of Jupiter to gather data before heading deeper into space.","exampleCN":"航天器飞掠木星收集数据，然后向太空更深处进发。","extra":"也可拼作 fly-by。"},{"chapter":4,"key":"4:31","id":31,"word":"observatory","phonetic":"/əbˈzɜːvətəri/","pos":"n.","meaningCN":"天文台","tag":"低频","root":"","exampleEN":"The observatory on the remote mountain peak offers excellent conditions for stargazing.","exampleCN":"偏远山顶上的天文台提供了极佳的观星条件。","extra":"搭配：space observatory 太空天文台。"},{"chapter":4,"key":"4:32","id":32,"word":"telescope","phonetic":"/ˈtelɪskəʊp/","pos":"n.","meaningCN":"望远镜","tag":"高频","root":"","exampleEN":"With a small telescope, you can clearly see the craters on the moon and the rings of Saturn.","exampleCN":"用一架小型望远镜，你可以清楚地看到月球上的陨石坑和土星的光环。","extra":"搭配：radio telescope 射电望远镜。"},{"chapter":4,"key":"4:33","id":33,"word":"spectacle","phonetic":"/ˈspektəkəl/","pos":"n.","meaningCN":"壮观的景象；奇观；[~s] 眼镜","tag":"低频","root":"spectacular adj. 壮观的；字根spect（看）→ 用来看的东西","exampleEN":"The total solar eclipse was an unforgettable spectacle that attracted viewers from across the globe.","exampleCN":"日全食是一场令人难忘的奇观，吸引了全球各地的观看者。","extra":"复数 spectacles 可指眼镜。"},{"chapter":4,"key":"4:34","id":34,"word":"orbit","phonetic":"/ˈɔːbɪt/","pos":"n.","meaningCN":"轨道","tag":"核心","root":"","exampleEN":"The satellite was placed into a stable orbit around the Earth at an altitude of 400 kilometres.","exampleCN":"卫星被送入距地球400公里的稳定轨道。","extra":"搭配：put into orbit 送入轨道。"},{"chapter":4,"key":"4:35","id":35,"word":"ecliptic","phonetic":"/ɪˈklɪptɪk/","pos":"n.","meaningCN":"黄道","tag":"识记","root":"","exampleEN":"The ecliptic is the apparent path of the Sun against the background stars throughout the year.","exampleCN":"黄道是太阳一年中在背景恒星间的视轨迹。","extra":"天文学术语，了解即可。"},{"chapter":4,"key":"4:36","id":36,"word":"diameter","phonetic":"/daɪˈæmɪtə/","pos":"n.","meaningCN":"直径","tag":"核心","root":"dia（通过）+ meter（测量）→ 测量通过中心的线段长度","exampleEN":"The diameter of the asteroid was estimated to be roughly 500 metres.","exampleCN":"这颗小行星的直径估计约为500米。","extra":"搭配：in diameter 在直径上。"},{"chapter":4,"key":"4:37","id":37,"word":"radius","phonetic":"/ˈreɪdiəs/","pos":"n.","meaningCN":"半径","tag":"核心","root":"","exampleEN":"They searched for the missing hiker within a radius of five kilometres from the camp.","exampleCN":"他们在营地五公里半径范围内搜寻失踪的徒步者。","extra":"复数形式为 radii。"},{"chapter":4,"key":"4:38","id":38,"word":"substance","phonetic":"/ˈsʌbstəns/","pos":"n.","meaningCN":"物质；实质，要旨","tag":"核心","root":"substantial adj. 大量的；牢固的","exampleEN":"Water is a fascinating substance because it exists in all three states on Earth.","exampleCN":"水是一种迷人的物质，因为它在地球上以三种状态存在。","extra":"搭配：a controlled substance 管控物质。"},{"chapter":4,"key":"4:39","id":39,"word":"particle","phonetic":"/ˈpɑːtɪkəl/","pos":"n.","meaningCN":"颗粒，微粒；极小量","tag":"核心","root":"","exampleEN":"Air filters remove tiny dust particles that can cause allergies and breathing problems.","exampleCN":"空气过滤器清除可能导致过敏和呼吸问题的微小灰尘颗粒。","extra":"搭配：particle physics 粒子物理学。"},{"chapter":4,"key":"4:40","id":40,"word":"molecule","phonetic":"/ˈmɒlɪkjuːl/","pos":"n.","meaningCN":"分子","tag":"核心","root":"","exampleEN":"A molecule of DNA carries the genetic instructions essential for the development of living organisms.","exampleCN":"DNA分子携带着生物体发育所必需的遗传指令。","extra":"分子由原子组成。"},{"chapter":4,"key":"4:41","id":41,"word":"atom","phonetic":"/ˈætəm/","pos":"n.","meaningCN":"原子","tag":"核心","root":"源自希腊语atomos（不可分割）","exampleEN":"Every cell in our body is made up of countless atoms arranged in complex molecules.","exampleCN":"我们身体中的每一个细胞都由无数个排列成复杂分子的原子构成。","extra":"atom bomb 原子弹。"},{"chapter":4,"key":"4:42","id":42,"word":"ion","phonetic":"/ˈaɪən/","pos":"n.","meaningCN":"离子","tag":"低频","root":"","exampleEN":"When table salt dissolves in water, it separates into sodium and chloride ions.","exampleCN":"食盐溶于水时，会分解成钠离子和氯离子。","extra":"搭配：ion channel 离子通道。"},{"chapter":4,"key":"4:43","id":43,"word":"electron","phonetic":"/ɪˈlektrɒn/","pos":"n.","meaningCN":"电子","tag":"低频","root":"","exampleEN":"In a conductor, free-moving electrons carry electric charge from one end to the other.","exampleCN":"在导体中，自由移动的电子将电荷从一端带到另一端。","extra":"搭配：electron microscope 电子显微镜。"},{"chapter":4,"key":"4:44","id":44,"word":"quantum","phonetic":"/ˈkwɒntəm/","pos":"n.","meaningCN":"量子","tag":"识记","root":"","exampleEN":"Quantum computing has the potential to solve problems that traditional computers cannot handle.","exampleCN":"量子计算有潜力解决传统计算机无法处理的问题。","extra":"搭配：quantum mechanics 量子力学。"},{"chapter":4,"key":"4:45","id":45,"word":"liquid","phonetic":"/ˈlɪkwɪd/","pos":"n.","meaningCN":"液体 adj. 液态的","tag":"核心","root":"","exampleEN":"Water is the only substance on Earth found naturally as a solid, a liquid, and a gas.","exampleCN":"水是地球上唯一一种自然存在的固、液、气三态物质。","extra":"搭配：liquid assets 流动资产。"},{"chapter":4,"key":"4:46","id":46,"word":"fluid","phonetic":"/ˈfluːɪd/","pos":"n.","meaningCN":"液体，流体 adj. 流动的","tag":"核心","root":"","exampleEN":"When you have a fever, doctors recommend that you drink plenty of fluids to stay hydrated.","exampleCN":"发烧时，医生建议多喝水以保持体内水分。","extra":"流体包括液体和气体。"},{"chapter":4,"key":"4:47","id":47,"word":"solid","phonetic":"/ˈsɒlɪd/","pos":"n.","meaningCN":"固体 adj. 固体的；牢固的","tag":"核心","root":"","exampleEN":"Ice is the solid form of water, which melts into a liquid when heated.","exampleCN":"冰是水的固体形态，加热时会融化成液体。","extra":"三态：solid，liquid，gas。"},{"chapter":4,"key":"4:48","id":48,"word":"synthesis","phonetic":"/ˈsɪnθəsɪs/","pos":"n.","meaningCN":"合成；综合","tag":"高频","root":"synthetic adj. 合成的","exampleEN":"The laboratory successfully achieved the synthesis of a new compound that shows anti-cancer properties.","exampleCN":"实验室成功合成了一种具有抗癌特性的新化合物。","extra":"搭配：protein synthesis 蛋白质合成。"},{"chapter":4,"key":"4:49","id":49,"word":"formation","phonetic":"/fɔːˈmeɪʃən/","pos":"n.","meaningCN":"形成","tag":"核心","root":"","exampleEN":"The formation of galaxies is thought to have begun shortly after the Big Bang.","exampleCN":"星系的形成被认为在大爆炸后不久就开始了。","extra":"搭配：rock formation 岩层。"},{"chapter":4,"key":"4:50","id":50,"word":"method","phonetic":"/ˈmeθəd/","pos":"n.","meaningCN":"方法","tag":"核心","root":"methodology n. 方法学","exampleEN":"Researchers are developing new methods to detect water on planets outside our solar system.","exampleCN":"研究人员正在开发新方法来探测太阳系外行星上的水。","extra":"搭配：scientific method 科学方法。"},{"chapter":4,"key":"4:51","id":51,"word":"spectrum","phonetic":"/ˈspektrəm/","pos":"n.","meaningCN":"光谱；范围","tag":"高频","root":"","exampleEN":"A prism can break a beam of white light into a spectrum of different colours.","exampleCN":"棱镜可以将一束白光分解成不同颜色的光谱。","extra":"复数 spectra；搭配：broad spectrum 广谱。"},{"chapter":4,"key":"4:52","id":52,"word":"dimension","phonetic":"/daɪˈmenʃən/","pos":"n.","meaningCN":"范围；维（度）","tag":"高频","root":"3D = three-dimensional","exampleEN":"In physics, time is often treated as a fourth dimension alongside the three of space.","exampleCN":"在物理学中，时间常被视作与空间的三维并列的第四维。","extra":"搭配：of great dimensions 规模宏大的。"},{"chapter":4,"key":"4:53","id":53,"word":"frequency","phonetic":"/ˈfriːkwənsi/","pos":"n.","meaningCN":"频率；发生次数","tag":"核心","root":"frequent adj. 频繁的","exampleEN":"The frequency of extreme weather events seems to be increasing due to climate change.","exampleCN":"由于气候变化，极端天气事件的发生频率似乎在增加。","extra":"搭配：high/low frequency 高/低频。"},{"chapter":4,"key":"4:54","id":54,"word":"signal","phonetic":"/ˈsɪɡnəl/","pos":"n.","meaningCN":"信号","tag":"核心","root":"sign n. 符号","exampleEN":"The radio telescope detected a faint but regular signal coming from a distant pulsar.","exampleCN":"射电望远镜探测到来自遥远脉冲星的微弱但规律的信号。","extra":"搭配：send a signal 发送信号。"},{"chapter":4,"key":"4:55","id":55,"word":"antenna","phonetic":"/ænˈtenə/","pos":"n.","meaningCN":"天线","tag":"低频","root":"","exampleEN":"The spacecraft extended a long antenna to send data back to Earth.","exampleCN":"航天器伸出一根长天线，将数据发回地球。","extra":"复数形式 antennae 或 antennas。"},{"chapter":4,"key":"4:56","id":56,"word":"circuit","phonetic":"/ˈsɜːkɪt/","pos":"n.","meaningCN":"线路，电路；巡回","tag":"低频","root":"","exampleEN":"When the circuit is complete, electricity can flow and the light bulb will shine.","exampleCN":"当电路闭合时，电流通过，灯泡就会发光。","extra":"搭配：integrated circuit 集成电路。"},{"chapter":4,"key":"4:57","id":57,"word":"refraction","phonetic":"/rɪˈfrækʃən/","pos":"n.","meaningCN":"折射","tag":"识记","root":"","exampleEN":"Refraction causes a pencil placed in a glass of water to look bent at the surface.","exampleCN":"折射使放在水杯中的铅笔在水面处看起来弯折。","extra":"常见光学现象。"},{"chapter":4,"key":"4:58","id":58,"word":"ultraviolet","phonetic":"/ˌʌltrəˈvaɪələt/","pos":"n.","meaningCN":"紫外辐射 adj. 紫外线的","tag":"高频","root":"infrared n. 红外辐射","exampleEN":"Sunscreen protects the skin from the sun's harmful ultraviolet rays that can cause sunburn.","exampleCN":"防晒霜保护皮肤免受太阳有害紫外线的伤害，这些紫外线可导致晒伤。","extra":"缩写为 UV。"},{"chapter":4,"key":"4:59","id":59,"word":"radioactive","phonetic":"/ˌreɪdiəʊˈæktɪv/","pos":"adj.","meaningCN":"放射性的","tag":"低频","root":"radio（发光）+ active（活性的）","exampleEN":"The radioactive material must be stored in specially designed containers to prevent leakage.","exampleCN":"放射性物质必须存放在特制容器中，以防泄漏。","extra":"搭配：radioactive decay 放射性衰变。"},{"chapter":4,"key":"4:60","id":60,"word":"distinct","phonetic":"/dɪˈstɪŋkt/","pos":"adj.","meaningCN":"明显的；截然不同的","tag":"核心","root":"distinctive adj. 有特色的；distinguish v. 区分","exampleEN":"The newly discovered species has several distinct features that set it apart from its relatives.","exampleCN":"新发现的物种有几个明显的特征，将其与它的近亲区分开来。","extra":"搭配：distinct from 与......完全不同。"},{"chapter":4,"key":"4:61","id":61,"word":"discernible","phonetic":"/dɪˈsɜːnɪbəl/","pos":"adj.","meaningCN":"可辨别的，看得清的","tag":"低频","root":"indiscernible adj. 看不清的","exampleEN":"After the fog cleared, the outline of the distant mountains became barely discernible.","exampleCN":"雾散后，远山的轮廓勉强可辨。","extra":"常用否定形式：no discernible effect 无明显效果。"},{"chapter":4,"key":"4:62","id":62,"word":"invisible","phonetic":"/ɪnˈvɪzəbəl/","pos":"adj.","meaningCN":"看不见的","tag":"核心","root":"","exampleEN":"Many gases are invisible, making leaks dangerous because they cannot be seen or smelled.","exampleCN":"许多气体是看不见的，这使得泄漏很危险，因为它们看不到也闻不到。","extra":"反义词：visible。"},{"chapter":4,"key":"4:63","id":63,"word":"collision","phonetic":"/kəˈlɪʒən/","pos":"n.","meaningCN":"碰撞事故；冲突","tag":"高频","root":"来自collide（v. 碰撞）","exampleEN":"Two satellites were destroyed in a high-speed collision, leaving thousands of pieces of debris in orbit.","exampleCN":"两颗卫星在高速碰撞中被毁，在轨道上留下了数千块碎片。","extra":"搭配：a collision with 与......的碰撞事故。"},{"chapter":4,"key":"4:64","id":64,"word":"squash","phonetic":"/skwɒʃ/","pos":"v.","meaningCN":"压扁 n. 壁球","tag":"识记","root":"壁球击中墙壁时发出squash的声音","exampleEN":"Be careful not to squash the ripe strawberries when you pack them into the basket.","exampleCN":"把熟草莓装进篮子时，小心别压扁它们。","extra":"名词也指南瓜属植物。"},{"chapter":4,"key":"4:65","id":65,"word":"fragment","phonetic":"/ˈfræɡmənt/","pos":"n.","meaningCN":"碎片，片断","tag":"低频","root":"","exampleEN":"Archaeologists carefully pieced together small fragments of pottery to reconstruct the ancient bowl.","exampleCN":"考古学家仔细地拼凑陶器碎片，复原了这只古代碗。","extra":"动词读 /fræɡˈment/，意为（使）碎裂。"},{"chapter":4,"key":"4:66","id":66,"word":"despair","phonetic":"/dɪˈspeə/","pos":"v./n.","meaningCN":"绝望","tag":"低频","root":"","exampleEN":"After several failed attempts, a sense of despair began to set in among the rescue team.","exampleCN":"几次尝试失败后，救援队中开始弥漫一种绝望感。","extra":"搭配：despair of 对......绝望。"},{"chapter":4,"key":"4:67","id":67,"word":"desperate","phonetic":"/ˈdespərət/","pos":"adj.","meaningCN":"绝望的；极需要的","tag":"核心","root":"字根sper（希望）+ de（没有）→ 没有希望的","exampleEN":"The stranded hikers were desperate for water after wandering in the desert for two days.","exampleCN":"在沙漠中游荡了两天后，被困的徒步者极度渴望喝水。","extra":"搭配：be desperate for 急需......"},{"chapter":4,"key":"4:68","id":68,"word":"overwhelming","phonetic":"/ˌəʊvəˈwelmɪŋ/","pos":"adj.","meaningCN":"压倒性的","tag":"低频","root":"over（在......上）+ whelm（淹没）→ 压倒","exampleEN":"The overwhelming majority of scientists agree that climate change is primarily caused by human activity.","exampleCN":"压倒性多数的科学家一致认为，气候变化主要是由人类活动引起的。","extra":"搭配：overwhelming evidence 压倒性的证据。"},{"chapter":4,"key":"4:69","id":69,"word":"cataclysmic","phonetic":"/ˌkætəˈklɪzmɪk/","pos":"adj.","meaningCN":"剧变的；灾难性的","tag":"识记","root":"","exampleEN":"The asteroid impact had cataclysmic effects on the climate, leading to the extinction of the dinosaurs.","exampleCN":"小行星撞击对气候造成了灾难性影响，导致恐龙灭绝。","extra":"名词 cataclysm 大灾难。"},{"chapter":4,"key":"4:70","id":70,"word":"hopeless","phonetic":"/ˈhəʊpləs/","pos":"adj.","meaningCN":"无望的；极差的","tag":"低频","root":"后缀-less 表示“没有......的”","exampleEN":"After hours of searching in the thick fog, the team felt the situation was hopeless.","exampleCN":"在浓雾中搜寻数小时后，团队觉得情况已经无望了。","extra":"反义词：hopeful。"}],"5":[{"chapter":5,"key":"5:1","id":1,"word":"education","phonetic":"/edjuˈkeɪʃən/","pos":"n.","meaningCN":"教育；教育学","tag":"核心","root":"e（向外）+ duc（引导）+ ation（后缀）→ 引导出学习的兴趣和天性 → 教育","exampleEN":"A quality education equips individuals with the skills needed to succeed in life.","exampleCN":"优质的教育使个人具备在生活中取得成功所需的技能。","extra":"educate v. 教育；educational adj. 教育的。"},{"chapter":5,"key":"5:2","id":2,"word":"primary","phonetic":"/ˈpraɪməri/","pos":"adj.","meaningCN":"主要的；最初的；小学教育的","tag":"核心","root":"","exampleEN":"The primary goal of the project is to improve literacy rates among children.","exampleCN":"该项目的主要目标是提高儿童的识字率。","extra":"搭配：primary school 小学；primary election 初选。"},{"chapter":5,"key":"5:3","id":3,"word":"secondary","phonetic":"/ˈsekəndəri/","pos":"adj.","meaningCN":"中等教育的；次要的","tag":"核心","root":"","exampleEN":"While salary is important, job satisfaction is not a secondary consideration.","exampleCN":"虽然薪水很重要，但工作满意度并非次要的考虑因素。","extra":"搭配：secondary school 中学。"},{"chapter":5,"key":"5:4","id":4,"word":"university","phonetic":"/ˌjuːnɪˈvɜːsəti/","pos":"n.","meaningCN":"（综合性）大学","tag":"核心","root":"vers 表示“转”，如：diverse（不同的），adverse（不利的），conversation（交谈），universe（宇宙），university（大学）","exampleEN":"She decided to pursue a degree in engineering at a leading university.","exampleCN":"她决定在一所顶尖大学攻读工程学学位。","extra":"搭配：go to university 上大学。"},{"chapter":5,"key":"5:5","id":5,"word":"college","phonetic":"/ˈkɒlɪdʒ/","pos":"n.","meaningCN":"学院；大学","tag":"核心","root":"","exampleEN":"After graduating from college, he started his own business.","exampleCN":"大学毕业后，他创办了自己的公司。","extra":"搭配：go to college 上大学；community college 社区学院。"},{"chapter":5,"key":"5:6","id":6,"word":"institute","phonetic":"/ˈɪnstɪtjuːt/","pos":"n.","meaningCN":"研究所，学院","tag":"高频","root":"institution n. 制度；（大学、教会等规模大的）机构","exampleEN":"The research institute published a groundbreaking study on renewable energy.","exampleCN":"该研究所发表了一项关于可再生能源的突破性研究。","extra":"institution 是更广泛的机构。"},{"chapter":5,"key":"5:7","id":7,"word":"academy","phonetic":"/əˈkædəmi/","pos":"n.","meaningCN":"专科院校；（美国的）私立中学；研究院，学会","tag":"低频","root":"academic adj. 学院的；学术的","exampleEN":"He was accepted into a prestigious military academy after passing rigorous exams.","exampleCN":"在通过严格的考试后，他被一所著名的军事院校录取。","extra":"academic 学术的。"},{"chapter":5,"key":"5:8","id":8,"word":"learn","phonetic":"/lɜːn/","pos":"v.","meaningCN":"学习；得知","tag":"核心","root":"learning n. 学习；知识； learned adj. 有学问的；学术性的","exampleEN":"Children learn best when they are actively engaged in the process.","exampleCN":"当孩子们积极参与过程时，他们学得最好。","extra":"搭配：learn from 从……中学习。"},{"chapter":5,"key":"5:9","id":9,"word":"study","phonetic":"/ˈstʌdi/","pos":"v./n.","meaningCN":"学习；研究","tag":"核心","root":"","exampleEN":"She plans to study abroad for a semester to broaden her horizons.","exampleCN":"她计划出国学习一个学期以开阔视野。","extra":"搭配：do a study 进行一项研究。"},{"chapter":5,"key":"5:10","id":10,"word":"acquire","phonetic":"/əˈkwaɪə/","pos":"v.","meaningCN":"获得（技能、知识等）；购得","tag":"核心","root":"acquisition n. 习得；获得，取得","exampleEN":"It takes years of practice to acquire a high level of proficiency in a language.","exampleCN":"要获得高水平的语言能力需要多年的练习。","extra":"名词 acquisition。"},{"chapter":5,"key":"5:11","id":11,"word":"knowledge","phonetic":"/ˈnɒlɪdʒ/","pos":"n.","meaningCN":"知识，学识；知悉","tag":"核心","root":"knowledgeable adj. 知识渊博的","exampleEN":"Sharing knowledge freely with colleagues creates a more productive work environment.","exampleCN":"与同事自由分享知识能创造一个更高效的工作环境。","extra":"搭配：to my knowledge 据我所知。"},{"chapter":5,"key":"5:12","id":12,"word":"expertise","phonetic":"/ˌekspɜːˈtiːz/","pos":"n.","meaningCN":"专门知识，专门技能","tag":"高频","root":"expert n. 专家","exampleEN":"The consultant brought valuable expertise in digital marketing to the team.","exampleCN":"这位顾问为团队带来了数字营销方面的宝贵专业知识。","extra":"expert 专家。"},{"chapter":5,"key":"5:13","id":13,"word":"novice","phonetic":"/ˈnɒvɪs/","pos":"n.","meaningCN":"新手","tag":"识记","root":"源自拉丁语 novus，表示“新（new）”","exampleEN":"As a novice in the kitchen, she still relies on recipes for simple dishes.","exampleCN":"作为厨房新手，她做简单的菜仍然要依赖食谱。","extra":"反义词：expert 专家。"},{"chapter":5,"key":"5:14","id":14,"word":"issue","phonetic":"/ˈɪʃuː/","pos":"n.","meaningCN":"重要问题；发行 v. 公布，发出","tag":"核心","root":"","exampleEN":"The report raises important issues about the quality of healthcare in rural areas.","exampleCN":"该报告提出了关于农村地区医疗质量的重要问题。","extra":"搭配：social issue 社会问题。"},{"chapter":5,"key":"5:15","id":15,"word":"affair","phonetic":"/əˈfeə/","pos":"n.","meaningCN":"事件；[~s] 公共事务，政治事务","tag":"高频","root":"","exampleEN":"The minister is responsible for managing foreign affairs and international relations.","exampleCN":"部长负责处理外交事务和国际关系。","extra":"搭配：state affairs 国务。"},{"chapter":5,"key":"5:16","id":16,"word":"controversial","phonetic":"/ˌkɒntrəˈvɜːʃəl/","pos":"adj.","meaningCN":"有争议的","tag":"高频","root":"","exampleEN":"The new education policy remains highly controversial among teachers and parents.","exampleCN":"新的教育政策在教师和家长中仍极具争议。","extra":"搭配：a controversial issue 有争议的问题。"},{"chapter":5,"key":"5:17","id":17,"word":"recruit","phonetic":"/rɪˈkruːt/","pos":"v.","meaningCN":"吸收（新成员）","tag":"高频","root":"re（再）+ cru（生长）+ it（后缀）→ 再次增多 → 增加新成员","exampleEN":"The university launched a campaign to recruit more international students.","exampleCN":"这所大学发起了一场运动来招收更多的国际学生。","extra":"recruitment n. 招聘。"},{"chapter":5,"key":"5:18","id":18,"word":"literate","phonetic":"/ˈlɪtərət/","pos":"adj.","meaningCN":"有读写能力的","tag":"高频","root":"literacy n. 读写能力","exampleEN":"Being digitally literate is an essential skill in today's job market.","exampleCN":"具备数字素养是当今就业市场的一项基本技能。","extra":"反义词：illiterate 文盲的。"},{"chapter":5,"key":"5:19","id":19,"word":"illiteracy","phonetic":"/ɪˈlɪtərəsi/","pos":"n.","meaningCN":"文盲","tag":"低频","root":"","exampleEN":"The government aims to eliminate illiteracy within the next five years.","exampleCN":"政府的目标是在未来五年内消除文盲。","extra":"搭配：eliminate illiteracy 扫除文盲。"},{"chapter":5,"key":"5:20","id":20,"word":"numerate","phonetic":"/ˈnjuːmərət/","pos":"adj.","meaningCN":"识数的，有计算能力的","tag":"识记","root":"numeracy n. 计算能力","exampleEN":"Basic numeracy skills are necessary for understanding personal finances.","exampleCN":"基本的计算能力对于理解个人财务是必要的。","extra":"numeracy 计算能力。"},{"chapter":5,"key":"5:21","id":21,"word":"problem","phonetic":"/ˈprɒbləm/","pos":"n.","meaningCN":"习题；问题","tag":"核心","root":"","exampleEN":"Solving complex math problems helps develop logical thinking skills.","exampleCN":"解决复杂的数学问题有助于培养逻辑思维能力。","extra":"搭配：solve a problem 解决问题。"},{"chapter":5,"key":"5:22","id":22,"word":"puzzle","phonetic":"/ˈpʌzəl/","pos":"n.","meaningCN":"难题；谜 v. 使迷惑","tag":"低频","root":"","exampleEN":"The crossword puzzle in today's newspaper was particularly challenging.","exampleCN":"今天报纸上的填字游戏特别有挑战性。","extra":"puzzled adj. 困惑的。"},{"chapter":5,"key":"5:23","id":23,"word":"riddle","phonetic":"/ˈrɪdəl/","pos":"n.","meaningCN":"谜，谜语","tag":"识记","root":"","exampleEN":"The old man spoke in riddles that were hard for the children to interpret.","exampleCN":"老人说的话像谜语，孩子们很难理解。","extra":"搭配：solve a riddle 解谜。"},{"chapter":5,"key":"5:24","id":24,"word":"obscure","phonetic":"/əbˈskjʊə/","pos":"adj.","meaningCN":"难以理解的","tag":"低频","root":"","exampleEN":"The professor's lecture was filled with obscure references that confused the students.","exampleCN":"教授的讲座充满了晦涩的引用，让学生们很困惑。","extra":"动词意为“使模糊”。"},{"chapter":5,"key":"5:25","id":25,"word":"instil","phonetic":"/ɪnˈstɪl/","pos":"v.","meaningCN":"逐渐灌输","tag":"低频","root":"in（进入）+ stil（滴）→ 滴进去","exampleEN":"Parents and teachers should work together to instil a love of reading in children.","exampleCN":"家长和老师应该共同努力，向孩子们灌输对阅读的热爱。","extra":"同义词：implant, infuse。"},{"chapter":5,"key":"5:26","id":26,"word":"cram","phonetic":"/kræm/","pos":"v.","meaningCN":"把......塞进；（为应考）临时死记硬背","tag":"低频","root":"","exampleEN":"Cramming the night before an exam is not an effective long-term study strategy.","exampleCN":"考前临时抱佛脚不是有效的长期学习策略。","extra":"搭配：cram for an exam 考前突击。"},{"chapter":5,"key":"5:27","id":27,"word":"emphasise","phonetic":"/ˈemfəsaɪz/","pos":"v.","meaningCN":"强调，着重","tag":"核心","root":"emphasis n. 强调，重点","exampleEN":"The teacher emphasised the importance of regular revision for exam success.","exampleCN":"老师强调了定期复习对于考试成功的重要性。","extra":"名词 emphasis。"},{"chapter":5,"key":"5:28","id":28,"word":"enhance","phonetic":"/ɪnˈhɑːns/","pos":"v.","meaningCN":"提高，增强","tag":"核心","root":"","exampleEN":"Taking part in extracurricular activities can significantly enhance your university application.","exampleCN":"参加课外活动能显著增强你的大学申请竞争力。","extra":"enhancement n. 增强。"},{"chapter":5,"key":"5:29","id":29,"word":"enable","phonetic":"/ɪˈneɪbəl/","pos":"v.","meaningCN":"使能够","tag":"核心","root":"able adj. 能够......的； ability n. 能力","exampleEN":"This scholarship will enable talented students from low-income families to attend university.","exampleCN":"这项奖学金将使来自低收入家庭的优秀学生能够上大学。","extra":"搭配：enable sb. to do sth.。"},{"chapter":5,"key":"5:30","id":30,"word":"inspire","phonetic":"/ɪnˈspaɪə/","pos":"v.","meaningCN":"鼓舞；给......灵感","tag":"核心","root":"in（进入）+ spire（呼吸）→ 吸入活力，吸收灵感 → 鼓舞；给......灵感","exampleEN":"The documentary inspired many young people to pursue careers in science.","exampleCN":"这部纪录片鼓舞了许多年轻人从事科学事业。","extra":"inspiration n. 灵感。"},{"chapter":5,"key":"5:31","id":31,"word":"motive","phonetic":"/ˈməʊtɪv/","pos":"n.","meaningCN":"动机，（行动的）缘由","tag":"高频","root":"","exampleEN":"Detectives are still trying to establish a motive for the crime.","exampleCN":"侦探们仍在努力确定犯罪动机。","extra":"motivate v. 激发。"},{"chapter":5,"key":"5:32","id":32,"word":"motivate","phonetic":"/ˈməʊtɪveɪt/","pos":"v.","meaningCN":"激发，驱使","tag":"核心","root":"mov/mob/mot 表示“移动”，如：motivate（激发），motive（动机），motion（运动），motor（发动机），promote（晋升），remote（遥远的），emotion（情绪）","exampleEN":"A good leader knows how to motivate employees to perform at their best.","exampleCN":"好的领导者知道如何激励员工发挥最佳水平。","extra":"名词 motivation。"},{"chapter":5,"key":"5:33","id":33,"word":"stimulate","phonetic":"/ˈstɪmjʊleɪt/","pos":"v.","meaningCN":"刺激；激励","tag":"高频","root":"stimulation n. 刺激；激励； stimulus n. 刺激物；激励因素","exampleEN":"Educational toys are designed to stimulate a child's imagination and curiosity.","exampleCN":"教育玩具旨在激发孩子的想象力和好奇心。","extra":"名词 stimulus 复数 stimuli。"},{"chapter":5,"key":"5:34","id":34,"word":"spur","phonetic":"/spɜː/","pos":"v.","meaningCN":"鞭策，刺激 n. 马刺；刺激","tag":"低频","root":"","exampleEN":"The desire to support her family spurred her to work two jobs.","exampleCN":"养家的愿望鞭策她打两份工。","extra":"搭配：spur sb. to do sth.。"},{"chapter":5,"key":"5:35","id":35,"word":"impetus","phonetic":"/ˈɪmpɪtəs/","pos":"n.","meaningCN":"推动，促进；动量；惯性","tag":"低频","root":"","exampleEN":"The new funding provided fresh impetus for the medical research project.","exampleCN":"新的资金为这项医学研究项目提供了新的动力。","extra":"注意词性：名词。"},{"chapter":5,"key":"5:36","id":36,"word":"indulge","phonetic":"/ɪnˈdʌldʒ/","pos":"v.","meaningCN":"迁就，放任；沉湎；让......享受一下","tag":"低频","root":"indulgent adj. 放纵的，溺爱的","exampleEN":"Parents should not indulge every whim of their children.","exampleCN":"父母不应该对孩子的每一个心血来潮都迁就。","extra":"搭配：indulge in 沉湎于。"},{"chapter":5,"key":"5:37","id":37,"word":"spoil","phonetic":"/spɔɪl/","pos":"v.","meaningCN":"宠坏，溺爱；破坏，糟蹋","tag":"高频","root":"","exampleEN":"Constantly giving in to a child's demands can spoil them and lead to behavioral issues.","exampleCN":"不断顺从孩子的要求会宠坏他们，导致行为问题。","extra":"搭配：spoil the fun 扫兴。"},{"chapter":5,"key":"5:38","id":38,"word":"abuse","phonetic":"/əˈbjuːz/","pos":"v./n.","meaningCN":"滥用；虐待","tag":"核心","root":"","exampleEN":"The system is in place to prevent the abuse of power by officials.","exampleCN":"该制度旨在防止官员滥用权力。","extra":"搭配：child abuse 虐待儿童；alcohol abuse 酗酒。"},{"chapter":5,"key":"5:39","id":39,"word":"intelligent","phonetic":"/ɪnˈtelɪdʒənt/","pos":"adj.","meaningCN":"聪明的，有才智的","tag":"核心","root":"intelligence n. 智慧，智力； intellectual adj. 智力的 n. 知识分子； intelligible adj. 可理解的，明白易懂的","exampleEN":"An intelligent approach to studying involves understanding concepts rather than memorizing facts.","exampleCN":"聪明的学习方法涉及理解概念，而不是死记硬背事实。","extra":"名词 intelligence。"},{"chapter":5,"key":"5:40","id":40,"word":"elite","phonetic":"/eɪˈliːt/","pos":"n.","meaningCN":"精英人物；精华；上层人士","tag":"高频","root":"","exampleEN":"The university has a reputation for educating the nation's future elite.","exampleCN":"这所大学以培养国家未来的精英而闻名。","extra":"elite athletes 精英运动员。"},{"chapter":5,"key":"5:41","id":41,"word":"idiot","phonetic":"/ˈɪdiət/","pos":"n.","meaningCN":"白痴，傻瓜","tag":"识记","root":"","exampleEN":"He felt like an idiot when he realized he had been reading the map upside down.","exampleCN":"当他意识到自己把地图拿倒了时，他觉得自己像个傻瓜。","extra":"非正式用语，慎用。"},{"chapter":5,"key":"5:42","id":42,"word":"wisdom","phonetic":"/ˈwɪzdəm/","pos":"n.","meaningCN":"智慧；学问","tag":"高频","root":"","exampleEN":"The wisdom gained from life experience is often more valuable than academic knowledge.","exampleCN":"从生活经验中获得的智慧往往比学术知识更有价值。","extra":"反义词：folly 愚蠢。"},{"chapter":5,"key":"5:43","id":43,"word":"wit","phonetic":"/wɪt/","pos":"n.","meaningCN":"风趣的人；机智，风趣；智慧","tag":"低频","root":"","exampleEN":"Her quick wit and humour made her a popular speaker at the conference.","exampleCN":"她的机智和幽默使她成为会议上受欢迎的演讲者。","extra":"搭配：at one's wit's end 不知所措。"},{"chapter":5,"key":"5:44","id":44,"word":"aptitude","phonetic":"/ˈæptɪtjuːd/","pos":"n.","meaningCN":"天生的才能，资质","tag":"低频","root":"apt adj. 恰当的；聪明的","exampleEN":"The aptitude test showed that she had a natural talent for languages.","exampleCN":"能力倾向测试显示她在语言方面有天赋。","extra":"搭配：aptitude for music 音乐天赋。"},{"chapter":5,"key":"5:45","id":45,"word":"clever","phonetic":"/ˈklevə/","pos":"adj.","meaningCN":"聪明的；精明的","tag":"核心","root":"","exampleEN":"That was a clever solution to a seemingly impossible problem.","exampleCN":"那是一个对看似不可能的问题的巧妙解决方案。","extra":"比较级 cleverer，最高级 cleverest。"},{"chapter":5,"key":"5:46","id":46,"word":"smart","phonetic":"/smɑːt/","pos":"adj.","meaningCN":"聪明的；智能的","tag":"核心","root":"","exampleEN":"Smart technology is changing the way students interact with educational content.","exampleCN":"智能技术正在改变学生与教育内容互动的方式。","extra":"smartphone 智能手机。"},{"chapter":5,"key":"5:47","id":47,"word":"capable","phonetic":"/ˈkeɪpəbəl/","pos":"adj.","meaningCN":"有能力的，有才能的","tag":"核心","root":"capability n. 能力； capacity n. 能力；容积","exampleEN":"She is a highly capable researcher who has published several influential papers.","exampleCN":"她是一位能力出众的研究员，发表过几篇有影响力的论文。","extra":"搭配：be capable of 能够。"},{"chapter":5,"key":"5:48","id":48,"word":"all-round","phonetic":"/ˌɔːlˈraʊnd/","pos":"adj.","meaningCN":"有多方面才能的，全面的","tag":"低频","root":"","exampleEN":"The school aims to provide an all-round education that develops both academic and social skills.","exampleCN":"学校旨在提供全面教育，培养学术和社交技能。","extra":"同义：well-rounded。"},{"chapter":5,"key":"5:49","id":49,"word":"excellent","phonetic":"/ˈeksələnt/","pos":"adj.","meaningCN":"优秀的，杰出的","tag":"核心","root":"excel v. 擅长，突出","exampleEN":"The student received excellent grades in all her subjects this semester.","exampleCN":"这名学生这学期所有科目的成绩都很优秀。","extra":"名词 excellence。"},{"chapter":5,"key":"5:50","id":50,"word":"genius","phonetic":"/ˈdʒiːniəs/","pos":"n.","meaningCN":"天才人物；天赋","tag":"低频","root":"gen 意为“生”，如：genius（生来如此 → 天才），gene（基因），regenerate（再生）","exampleEN":"Einstein is often regarded as one of the greatest scientific geniuses of all time.","exampleCN":"爱因斯坦常被认为是有史以来最伟大的科学天才之一。","extra":"复数 geniuses。"},{"chapter":5,"key":"5:51","id":51,"word":"outstanding","phonetic":"/aʊtˈstændɪŋ/","pos":"adj.","meaningCN":"突出的，杰出的","tag":"高频","root":"","exampleEN":"The teacher was given an award for her outstanding contribution to education.","exampleCN":"这位老师因对教育做出的杰出贡献而获奖。","extra":"也可指债务等未偿付的。"},{"chapter":5,"key":"5:52","id":52,"word":"brilliant","phonetic":"/ˈbrɪljənt/","pos":"adj.","meaningCN":"光辉的；聪颖的；（光线等）明亮的；非常好的","tag":"高频","root":"","exampleEN":"She came up with a brilliant idea for the science fair project.","exampleCN":"她为科学展项目想出了一个绝妙的主意。","extra":"名词 brilliance。"},{"chapter":5,"key":"5:53","id":53,"word":"prestige","phonetic":"/preˈstiːʒ/","pos":"n.","meaningCN":"威望，声望","tag":"高频","root":"prestigious adj. 有名望的，享有声望的","exampleEN":"Working at a company with international prestige can advance one's career significantly.","exampleCN":"在一家享有国际声望的公司工作可以极大地推动职业发展。","extra":"prestigious universities 名校。"},{"chapter":5,"key":"5:54","id":54,"word":"reputation","phonetic":"/ˌrepjʊˈteɪʃən/","pos":"n.","meaningCN":"名誉，声誉","tag":"核心","root":"reputable adj. 声誉好的，享有声望的","exampleEN":"The university has built a strong reputation for its research output in environmental science.","exampleCN":"这所大学因其在环境科学方面的研究成果而建立了良好的声誉。","extra":"搭配：damage one's reputation 损害名誉。"},{"chapter":5,"key":"5:55","id":55,"word":"eminent","phonetic":"/ˈemɪnənt/","pos":"adj.","meaningCN":"著名的；杰出的","tag":"低频","root":"min 表示“突出”，eminent 为 e（向外）+ min（突出）+ ent → 杰出的","exampleEN":"The conference was attended by several eminent scholars from around the world.","exampleCN":"几位来自世界各地的著名学者出席了会议。","extra":"近义词：distinguished, prominent。"},{"chapter":5,"key":"5:56","id":56,"word":"notorious","phonetic":"/nəʊˈtɔːriəs/","pos":"adj.","meaningCN":"声名狼藉的","tag":"低频","root":"notoriety n. 坏名声","exampleEN":"The college is notorious for its strict disciplinary policies.","exampleCN":"这所学院以其严格的纪律政策而声名狼藉。","extra":"反义词：famous 著名的（褒义）。"},{"chapter":5,"key":"5:57","id":57,"word":"esteem","phonetic":"/ɪˈstiːm/","pos":"v.","meaningCN":"尊重，尊敬","tag":"低频","root":"self-esteem n. 自尊（心）","exampleEN":"In many cultures, teachers are highly esteemed for their role in shaping young minds.","exampleCN":"在许多文化中，教师因在塑造年轻人思想方面的作用而备受尊敬。","extra":"self-esteem 自尊。"},{"chapter":5,"key":"5:58","id":58,"word":"respect","phonetic":"/rɪˈspekt/","pos":"n./v.","meaningCN":"尊敬，敬重","tag":"核心","root":"respectable adj. 可敬的； respectful adj. 表示敬意的","exampleEN":"Mutual respect between teachers and students creates a positive learning environment.","exampleCN":"师生之间的相互尊重创造出积极的学习环境。","extra":"搭配：show respect 表示尊敬。"},{"chapter":5,"key":"5:59","id":59,"word":"diligent","phonetic":"/ˈdɪlɪdʒənt/","pos":"adj.","meaningCN":"勤勉的，勤奋的","tag":"核心","root":"","exampleEN":"Diligent students tend to perform better academically over the long term.","exampleCN":"勤奋的学生从长远来看往往在学业上表现更好。","extra":"搭配：diligent in 勤勉于。"},{"chapter":5,"key":"5:60","id":60,"word":"painstaking","phonetic":"/ˈpeɪnzˌteɪkɪŋ/","pos":"adj.","meaningCN":"极其仔细的，辛苦的","tag":"低频","root":"","exampleEN":"The researcher conducted a painstaking analysis of the historical documents.","exampleCN":"研究人员对历史文献进行了极其仔细的分析。","extra":"搭配：painstaking effort 艰苦的努力。"},{"chapter":5,"key":"5:61","id":61,"word":"skill","phonetic":"/skɪl/","pos":"n.","meaningCN":"技巧，技能","tag":"核心","root":"skilled adj. 有技能的，熟练的； skillful adj. 巧妙的；娴熟的","exampleEN":"Public speaking is a skill that can be developed with practice and feedback.","exampleCN":"公共演讲是一项可以通过练习和反馈来培养的技能。","extra":"搭配：practical skills 实用技能。"},{"chapter":5,"key":"5:62","id":62,"word":"approach","phonetic":"/əˈprəʊtʃ/","pos":"n.","meaningCN":"方法 v. 接近","tag":"核心","root":"","exampleEN":"A hands-on approach to learning often produces better results than passive listening.","exampleCN":"动手实践的学习方法通常比被动听课产生更好的效果。","extra":"搭配：a fresh approach 新颖的方法。"},{"chapter":5,"key":"5:63","id":63,"word":"scheme","phonetic":"/skiːm/","pos":"n.","meaningCN":"计划，方案；阴谋 v. 谋划","tag":"高频","root":"","exampleEN":"The government introduced a new scheme to support students from disadvantaged backgrounds.","exampleCN":"政府推出了一项新计划来支持来自弱势背景的学生。","extra":"搭配：a training scheme 培训计划。"},{"chapter":5,"key":"5:64","id":64,"word":"headmaster","phonetic":"/ˌhedˈmɑːstə/","pos":"n.","meaningCN":"[英] 男校长","tag":"低频","root":"","exampleEN":"The headmaster announced that the school would be introducing a new uniform policy.","exampleCN":"男校长宣布学校将引入新的校服政策。","extra":"美式英语多用 principal。"},{"chapter":5,"key":"5:65","id":65,"word":"principal","phonetic":"/ˈprɪnsəpəl/","pos":"n.","meaningCN":"[美]（中小学）校长；[英]大学校长，学院院长 adj. 首要的","tag":"高频","root":"","exampleEN":"The principal invited parents to discuss the new curriculum changes.","exampleCN":"校长邀请家长们讨论新的课程变化。","extra":"注意与 principle（原则）区分。"},{"chapter":5,"key":"5:66","id":66,"word":"dean","phonetic":"/diːn/","pos":"n.","meaningCN":"[大学的]学院院长，系主任","tag":"低频","root":"","exampleEN":"The dean of the medical school oversaw a significant increase in research funding.","exampleCN":"医学院院长监督了研究经费的显著增长。","extra":"常见于大学。"},{"chapter":5,"key":"5:67","id":67,"word":"faculty","phonetic":"/ˈfækəlti/","pos":"n.","meaningCN":"[大学的]系，院；[美]（大学的）全体教员","tag":"低频","root":"","exampleEN":"The faculty of arts and humanities offers a wide selection of interdisciplinary courses.","exampleCN":"艺术与人文学院提供广泛的跨学科课程。","extra":"faculty members 教职员。"},{"chapter":5,"key":"5:68","id":68,"word":"professor","phonetic":"/prəˈfesə/","pos":"n.","meaningCN":"教授","tag":"核心","root":"","exampleEN":"The professor encouraged her students to question traditional assumptions in the field.","exampleCN":"教授鼓励她的学生质疑该领域的传统假设。","extra":"associate professor 副教授。"},{"chapter":5,"key":"5:69","id":69,"word":"scholar","phonetic":"/ˈskɒlə/","pos":"n.","meaningCN":"学者","tag":"高频","root":"","exampleEN":"As a scholar of ancient history, she spent years studying archaeological evidence.","exampleCN":"作为一名古代史学者，她花了多年时间研究考古证据。","extra":"scholarship 奖学金，学识。"},{"chapter":5,"key":"5:70","id":70,"word":"scientist","phonetic":"/ˈsaɪəntɪst/","pos":"n.","meaningCN":"科学家","tag":"核心","root":"","exampleEN":"The scientist published her findings in a respected peer-reviewed journal.","exampleCN":"这位科学家将她的发现发表在了一家受人尊敬的同行评审期刊上。","extra":"science n. 科学。"},{"chapter":5,"key":"5:71","id":71,"word":"mentor","phonetic":"/ˈmentɔː/","pos":"n.","meaningCN":"导师；顾问","tag":"低频","root":"","exampleEN":"Having a good mentor can greatly accelerate your professional development.","exampleCN":"有一位好的导师可以大大加速你的职业发展。","extra":"mentorship n. 导师指导。"},{"chapter":5,"key":"5:72","id":72,"word":"tutor","phonetic":"/ˈtjuːtə/","pos":"n.","meaningCN":"家庭教师；（英国大学或学院中的）导师","tag":"低频","root":"tutorial n. 辅导课； tuition n. 教学，讲授","exampleEN":"She worked as a private tutor to help high school students prepare for university entrance exams.","exampleCN":"她担任私人教师，帮助高中生准备大学入学考试。","extra":"tuition 教学，学费。"},{"chapter":5,"key":"5:73","id":73,"word":"lecturer","phonetic":"/ˈlektʃərə/","pos":"n.","meaningCN":"[英]（大学的）讲师","tag":"低频","root":"lecture n. 演讲，讲课 v. 开讲座，讲课","exampleEN":"The lecturer used interactive polls to keep the audience engaged during the talk.","exampleCN":"讲师在演讲中使用互动投票来保持听众的参与度。","extra":"senior lecturer 高级讲师。"},{"chapter":5,"key":"5:74","id":74,"word":"assistant","phonetic":"/əˈsɪstənt/","pos":"n.","meaningCN":"助手，助理","tag":"核心","root":"TA (teaching assistant) 助教","exampleEN":"The teaching assistant graded the quizzes and provided feedback to the students.","exampleCN":"助教给测验打分并向学生提供反馈。","extra":"teaching assistant 助教。"},{"chapter":5,"key":"5:75","id":75,"word":"candidate","phonetic":"/ˈkændɪdət/","pos":"n.","meaningCN":"候选人；求职者；[英]考生","tag":"高频","root":"cand 表示“白”，古罗马竞选公职的人穿白色宽外袍","exampleEN":"Each candidate was required to give a short presentation on their research proposal.","exampleCN":"每位候选人都需要就其研究计划做一个简短的陈述。","extra":"candidacy n. 候选人资格。"},{"chapter":5,"key":"5:76","id":76,"word":"degree","phonetic":"/dɪˈɡriː/","pos":"n.","meaningCN":"学位；学位课程；程度","tag":"核心","root":"","exampleEN":"After completing her master's degree, she decided to continue onto a PhD programme.","exampleCN":"完成硕士学位后，她决定继续攻读博士课程。","extra":"搭配：to a certain degree 在某种程度上。"},{"chapter":5,"key":"5:77","id":77,"word":"qualify","phonetic":"/ˈkwɒlɪfaɪ/","pos":"v.","meaningCN":"使具备资格；使有权","tag":"核心","root":"qualification n. 资历；资格","exampleEN":"This training course will qualify you to work as a certified accountant.","exampleCN":"这个培训课程将使你具备担任注册会计师的资格。","extra":"搭配：qualify sb. for sth.。"},{"chapter":5,"key":"5:78","id":78,"word":"certify","phonetic":"/ˈsɜːtɪfaɪ/","pos":"v.","meaningCN":"证明；颁发专业合格证书","tag":"低频","root":"certificate n. 合格证书；证明书； certification n. 证明，鉴定","exampleEN":"The board will certify teachers who meet the required professional standards.","exampleCN":"委员会将向符合规定专业标准的教师颁发证书。","extra":"certificate 证书。"},{"chapter":5,"key":"5:79","id":79,"word":"license","phonetic":"/ˈlaɪsəns/","pos":"n.","meaningCN":"执照，许可证","tag":"核心","root":"","exampleEN":"You need to obtain a driving license before you can legally drive a car.","exampleCN":"你需要先取得驾驶执照才能合法驾驶汽车。","extra":"动词 license。"},{"chapter":5,"key":"5:80","id":80,"word":"permit","phonetic":"/ˈpɜːmɪt/","pos":"n.","meaningCN":"许可证","tag":"高频","root":"","exampleEN":"Students must apply for a parking permit to use the campus car park.","exampleCN":"学生必须申请停车许可证才能使用校园停车场。","extra":"动词读 /pəˈmɪt/。"},{"chapter":5,"key":"5:81","id":81,"word":"diploma","phonetic":"/dɪˈpləʊmə/","pos":"n.","meaningCN":"毕业文凭","tag":"低频","root":"","exampleEN":"He was awarded a diploma in graphic design after completing the two-year course.","exampleCN":"完成两年课程后，他获得了平面设计文凭。","extra":"diplomat 外交官。"},{"chapter":5,"key":"5:82","id":82,"word":"diplomat","phonetic":"/ˈdɪpləmæt/","pos":"n.","meaningCN":"外交官；善于交际的人","tag":"低频","root":"","exampleEN":"As a diplomat, she was posted to embassies in several Asian countries.","exampleCN":"作为一名外交官，她被派驻到几个亚洲国家的大使馆。","extra":"diplomatic adj. 外交的。"},{"chapter":5,"key":"5:83","id":83,"word":"ambassador","phonetic":"/æmˈbæsədə/","pos":"n.","meaningCN":"大使","tag":"低频","root":"embassy n. 大使馆","exampleEN":"The ambassador gave a speech at the cultural exchange event at the university.","exampleCN":"大使在大学的文化交流活动上发表了演讲。","extra":"embassy 大使馆。"},{"chapter":5,"key":"5:84","id":84,"word":"pupil","phonetic":"/ˈpjuːpəl/","pos":"n.","meaningCN":"小学生；瞳孔","tag":"低频","root":"","exampleEN":"The school has about 500 pupils, ranging from ages six to eleven.","exampleCN":"这所学校约有500名小学生，年龄从6岁到11岁不等。","extra":"pupil 也指瞳孔。"},{"chapter":5,"key":"5:85","id":85,"word":"graduate","phonetic":"/ˈɡrædʒʊət/","pos":"n.","meaningCN":"大学毕业生；[美]（大学、中学等的）毕业生","tag":"核心","root":"grad（步，级）+ uate → 达到一定级别，获得学位 → 毕业","exampleEN":"The job fair attracted hundreds of recent graduates looking for employment.","exampleCN":"招聘会吸引了数百名寻找工作的应届毕业生。","extra":"搭配：graduate from 从……毕业。"},{"chapter":5,"key":"5:86","id":86,"word":"ceremony","phonetic":"/ˈserɪməni/","pos":"n.","meaningCN":"典礼；礼节","tag":"高频","root":"","exampleEN":"The graduation ceremony was held outdoors, with families and friends in attendance.","exampleCN":"毕业典礼在户外举行，家人和朋友都到场了。","extra":"搭配：opening ceremony 开幕式。"},{"chapter":5,"key":"5:87","id":87,"word":"bachelor","phonetic":"/ˈbætʃələ/","pos":"n.","meaningCN":"学士；单身汉","tag":"核心","root":"","exampleEN":"He earned his Bachelor of Science in Computer Science in just three years.","exampleCN":"他仅用三年就获得了计算机科学理学士学位。","extra":"bachelor's degree 学士学位。"},{"chapter":5,"key":"5:88","id":88,"word":"master","phonetic":"/ˈmɑːstə/","pos":"n.","meaningCN":"硕士；大师 v. 精通；控制","tag":"核心","root":"","exampleEN":"She is pursuing a Master of Arts in Education while working part-time.","exampleCN":"她一边兼职工作，一边攻读教育学文学硕士。","extra":"a master's degree 硕士学位。"},{"chapter":5,"key":"5:89","id":89,"word":"doctor","phonetic":"/ˈdɒktə/","pos":"n.","meaningCN":"博士；医生","tag":"核心","root":"","exampleEN":"After years of research, she finally received her Doctor of Philosophy in biochemistry.","exampleCN":"经过多年的研究，她终于获得了生物化学哲学博士学位。","extra":"PhD 博士学位。"},{"chapter":5,"key":"5:90","id":90,"word":"fresher","phonetic":"/ˈfreʃə/","pos":"n.","meaningCN":"[英]（大学）一年级新生","tag":"识记","root":"freshman n.（大学）一年级新生","exampleEN":"During the first week, freshers attended various orientation events to get to know the campus.","exampleCN":"在第一周，大一新生们参加了各种迎新活动来了解校园。","extra":"美式：freshman。"},{"chapter":5,"key":"5:91","id":91,"word":"sophomore","phonetic":"/ˈsɒfəmɔː/","pos":"n.","meaningCN":"[美]（大学或高中）二年级学生","tag":"识记","root":"","exampleEN":"During his sophomore year, he changed his major from chemistry to physics.","exampleCN":"在大二时，他从化学专业转到了物理专业。","extra":"大二学生。"},{"chapter":5,"key":"5:92","id":92,"word":"junior","phonetic":"/ˈdʒuːniə/","pos":"n.","meaningCN":"[美]（大学或高中）三年级学生；较年幼者 adj. 级别（或地位）较低的","tag":"低频","root":"","exampleEN":"Juniors are expected to start thinking seriously about their career paths.","exampleCN":"大三学生应该开始认真思考他们的职业道路了。","extra":"junior high school 初中。"},{"chapter":5,"key":"5:93","id":93,"word":"senior","phonetic":"/ˈsiːniə/","pos":"n.","meaningCN":"[美]（大学或高中）毕业班学生；较年长者 adj. 级别（或地位）高的","tag":"低频","root":"","exampleEN":"Seniors often take a lighter course load to allow time for job applications and interviews.","exampleCN":"大四学生通常选课较少，以便有时间申请工作和面试。","extra":"senior high school 高中。"},{"chapter":5,"key":"5:94","id":94,"word":"alumni","phonetic":"/əˈlʌmnaɪ/","pos":"n.","meaningCN":"[alumnus 的复数形式] 毕业生，校友","tag":"识记","root":"alumna n. 女毕业生，女校友","exampleEN":"The university maintains close ties with its alumni through regular events and newsletters.","exampleCN":"这所大学通过定期活动和通讯与校友保持密切联系。","extra":"单数 alumnus（男），alumna（女）。"},{"chapter":5,"key":"5:95","id":95,"word":"campus","phonetic":"/ˈkæmpəs/","pos":"n.","meaningCN":"（大专院校的）校园","tag":"核心","root":"","exampleEN":"The new library is one of the most popular buildings on campus.","exampleCN":"新图书馆是校园里最受欢迎的建筑之一。","extra":"搭配：on campus 在校内。"},{"chapter":5,"key":"5:96","id":96,"word":"orientation","phonetic":"/ˌɔːriənˈteɪʃən/","pos":"n.","meaningCN":"（学前、岗前等的）情况介绍，迎新会；方向","tag":"低频","root":"","exampleEN":"The orientation programme helped international students adjust to life on campus.","exampleCN":"迎新活动帮助国际学生适应校园生活。","extra":"动词 orient 使适应。"},{"chapter":5,"key":"5:97","id":97,"word":"platform","phonetic":"/ˈplætfɔːm/","pos":"n.","meaningCN":"平台；讲台","tag":"高频","root":"","exampleEN":"The professor stepped onto the platform and began his lecture on quantum mechanics.","exampleCN":"教授走上讲台，开始了他的量子力学讲座。","extra":"online platform 在线平台。"},{"chapter":5,"key":"5:98","id":98,"word":"coed","phonetic":"/ˈkəʊˈed/","pos":"adj.","meaningCN":"男女同校的 n.（男女同校的大学中的）女生","tag":"识记","root":"","exampleEN":"The school transitioned from a single-sex institution to a coed campus in the 1980s.","exampleCN":"这所学校在20世纪80年代从单一性别学校转变为男女同校。","extra":"co-educational 的缩写。"},{"chapter":5,"key":"5:99","id":99,"word":"register","phonetic":"/ˈredʒɪstə/","pos":"v.","meaningCN":"登记，注册 n. 登记表，注册簿","tag":"核心","root":"registration n. 登记，注册；挂号","exampleEN":"All new students must register for their courses before the semester begins.","exampleCN":"所有新生必须在学期开始前注册课程。","extra":"registration 注册。"},{"chapter":5,"key":"5:100","id":100,"word":"roster","phonetic":"/ˈrɒstə/","pos":"n.","meaningCN":"花名册，登记表；执勤表","tag":"识记","root":"","exampleEN":"The coach checked the team roster to confirm which players were available for the match.","exampleCN":"教练查看了球队名单，确认哪些球员可以上场比赛。","extra":"常见于体育和排班。"},{"chapter":5,"key":"5:101","id":101,"word":"enrol","phonetic":"/ɪnˈrəʊl/","pos":"v.","meaningCN":"登记；注册（课程）；（使）加入","tag":"核心","root":"en（进入，使）+ rol（卷轴）→ 使之登记在册","exampleEN":"You need to enrol on the course before the deadline next Friday.","exampleCN":"你需要在下周五截止日期之前注册这门课程。","extra":"名词 enrolment 注册人数。"},{"chapter":5,"key":"5:102","id":102,"word":"matriculation","phonetic":"/məˌtrɪkjʊˈleɪʃən/","pos":"n.","meaningCN":"注册入学","tag":"识记","root":"","exampleEN":"Matriculation rates increased significantly as more families could afford higher education.","exampleCN":"随着更多家庭能负担高等教育，入学注册率显著上升。","extra":""},{"chapter":5,"key":"5:103","id":103,"word":"accommodation","phonetic":"/əˌkɒməˈdeɪʃən/","pos":"n.","meaningCN":"住处；食宿招待","tag":"核心","root":"","exampleEN":"The university guarantees accommodation for all first-year international students.","exampleCN":"这所大学保证为所有一年级国际学生提供住宿。","extra":"student accommodation 学生宿舍。"},{"chapter":5,"key":"5:104","id":104,"word":"dorm","phonetic":"/dɔːm/","pos":"n.","meaningCN":"宿舍","tag":"核心","root":"简化自 dormitory","exampleEN":"Living in a dorm helps freshmen make friends quickly and adjust to college life.","exampleCN":"住在宿舍能帮助大一新生快速交到朋友并适应大学生活。","extra":"dormitory 的简写。"},{"chapter":5,"key":"5:105","id":105,"word":"dining hall","phonetic":"/ˈdaɪnɪŋ hɔːl/","pos":"n.","meaningCN":"食堂","tag":"核心","root":"","exampleEN":"The dining hall serves a variety of healthy meals throughout the day.","exampleCN":"食堂全天供应各种健康餐食。","extra":"等同于 canteen。"},{"chapter":5,"key":"5:106","id":106,"word":"canteen","phonetic":"/kænˈtiːn/","pos":"n.","meaningCN":"水壶；[英]食堂","tag":"低频","root":"","exampleEN":"Students often gather in the canteen during lunch break to chat and relax.","exampleCN":"学生们常在午休时聚在食堂聊天放松。","extra":"英式英语。"},{"chapter":5,"key":"5:107","id":107,"word":"laboratory","phonetic":"/ləˈbɒrətəri/","pos":"n.","meaningCN":"实验室，研究室","tag":"核心","root":"源自拉丁语 laborare（劳作，工作）→ 工作的地方 → 实验室","exampleEN":"The chemistry laboratory is equipped with advanced instruments for molecular analysis.","exampleCN":"化学实验室配备了用于分子分析的先进仪器。","extra":"缩写 lab。"},{"chapter":5,"key":"5:108","id":108,"word":"experiment","phonetic":"/ɪkˈsperɪmənt/","pos":"n.","meaningCN":"实验；试验","tag":"核心","root":"experimental adj. 实验性的；试验性的","exampleEN":"The students designed a simple experiment to test the effect of light on plant growth.","exampleCN":"学生们设计了一个简单实验来检测光照对植物生长的影响。","extra":"搭配：do/have an experiment 做实验。"},{"chapter":5,"key":"5:109","id":109,"word":"data","phonetic":"/ˈdeɪtə/","pos":"n.","meaningCN":"[datum 的复数形式] 数据","tag":"核心","root":"","exampleEN":"The researchers collected data from over 2,000 participants for the study.","exampleCN":"研究人员为这项研究收集了2000多名参与者的数据。","extra":"data 通常作不可数名词。"},{"chapter":5,"key":"5:110","id":110,"word":"quantity","phonetic":"/ˈkwɒntəti/","pos":"n.","meaningCN":"数量","tag":"核心","root":"quantitative adj. 数量的","exampleEN":"It is better to focus on the quality of your work rather than the quantity.","exampleCN":"最好关注工作的质量而非数量。","extra":"反义词：quality 质量。"},{"chapter":5,"key":"5:111","id":111,"word":"quality","phonetic":"/ˈkwɒləti/","pos":"n.","meaningCN":"质量","tag":"核心","root":"qualitative adj. 性质的；定性的","exampleEN":"The quality of teaching has a direct impact on student achievement.","exampleCN":"教学质量直接影响学生的成绩。","extra":"搭配：high quality 高质量。"},{"chapter":5,"key":"5:112","id":112,"word":"library","phonetic":"/ˈlaɪbrəri/","pos":"n.","meaningCN":"图书馆；（书、唱片等）个人收藏","tag":"核心","root":"librarian n. 图书馆管理员","exampleEN":"She spends most afternoons in the library preparing for her final exams.","exampleCN":"她大部分下午都在图书馆准备期末考试。","extra":"librarian 图书管理员。"},{"chapter":5,"key":"5:113","id":113,"word":"literature","phonetic":"/ˈlɪtərətʃə/","pos":"n.","meaningCN":"文学；文学作品；文献","tag":"核心","root":"literary adj. 文学（上）的","exampleEN":"Reading classic literature helps students develop critical thinking and empathy.","exampleCN":"阅读经典文学有助于学生培养批判性思维和同理心。","extra":"literary works 文学作品。"},{"chapter":5,"key":"5:114","id":114,"word":"article","phonetic":"/ˈɑːtɪkəl/","pos":"n.","meaningCN":"文章","tag":"核心","root":"","exampleEN":"She published an article discussing the challenges of online learning.","exampleCN":"她发表了一篇讨论在线学习挑战的文章。","extra":""},{"chapter":5,"key":"5:115","id":115,"word":"author","phonetic":"/ˈɔːθə/","pos":"n.","meaningCN":"作者，作家","tag":"核心","root":"","exampleEN":"The author of this textbook has years of experience in teaching physics.","exampleCN":"这本教科书的作者有多年的物理教学经验。","extra":"co-author 合著者。"},{"chapter":5,"key":"5:116","id":116,"word":"tale","phonetic":"/teɪl/","pos":"n.","meaningCN":"故事，传说","tag":"低频","root":"","exampleEN":"The novel is a captivating tale of adventure and friendship.","exampleCN":"这本小说是一个关于冒险和友谊的迷人故事。","extra":"fairy tale 童话。"},{"chapter":5,"key":"5:117","id":117,"word":"fiction","phonetic":"/ˈfɪkʃən/","pos":"n.","meaningCN":"小说；虚构，杜撰","tag":"高频","root":"","exampleEN":"Science fiction often explores how technology might change society in the future.","exampleCN":"科幻小说常探讨技术未来可能如何改变社会。","extra":"non-fiction 非小说类。"},{"chapter":5,"key":"5:118","id":118,"word":"story","phonetic":"/ˈstɔːri/","pos":"n.","meaningCN":"故事，小说；（尤指口头的）叙述","tag":"核心","root":"","exampleEN":"The teacher told the children a fascinating story about life in ancient China.","exampleCN":"老师给孩子们讲了一个关于古代中国生活的迷人故事。","extra":"搭配：short story 短篇小说。"},{"chapter":5,"key":"5:119","id":119,"word":"diary","phonetic":"/ˈdaɪəri/","pos":"n.","meaningCN":"日记，日记簿","tag":"低频","root":"","exampleEN":"Keeping a diary is a great way to reflect on your daily experiences.","exampleCN":"写日记是反思日常经历的好方法。","extra":""},{"chapter":5,"key":"5:120","id":120,"word":"poetry","phonetic":"/ˈpəʊətri/","pos":"n.","meaningCN":"诗，诗歌，诗作","tag":"高频","root":"poem n. 诗； poet n. 诗人","exampleEN":"Reading poetry aloud can help learners appreciate the rhythm and beauty of a language.","exampleCN":"大声朗读诗歌有助于学习者体会语言的韵律和美感。","extra":"poem 指单首诗。"},{"chapter":5,"key":"5:121","id":121,"word":"magazine","phonetic":"/ˌmæɡəˈziːn/","pos":"n.","meaningCN":"杂志，期刊","tag":"核心","root":"","exampleEN":"The scientific magazine publishes monthly articles on recent discoveries.","exampleCN":"这本科学杂志每月刊登关于最新发现的文章。","extra":"weekly magazine 周刊。"},{"chapter":5,"key":"5:122","id":122,"word":"journal","phonetic":"/ˈdʒɜːnəl/","pos":"n.","meaningCN":"日报，周报；（尤指专门学科的）杂志；日志","tag":"核心","root":"","exampleEN":"Her research was published in a leading medical journal.","exampleCN":"她的研究发表在了一家顶级医学期刊上。","extra":"academic journal 学术期刊。"},{"chapter":5,"key":"5:123","id":123,"word":"coverage","phonetic":"/ˈkʌvərɪdʒ/","pos":"n.","meaningCN":"新闻报道；覆盖范围","tag":"高频","root":"cover n. 封面；掩蔽物 v. 覆盖","exampleEN":"The event received extensive media coverage both nationally and internationally.","exampleCN":"该事件在国内和国际上都得到了广泛的媒体报道。","extra":"insurance coverage 保险范围。"},{"chapter":5,"key":"5:124","id":124,"word":"bibliography","phonetic":"/ˌbɪbliˈɒɡrəfi/","pos":"n.","meaningCN":"参考书目","tag":"低频","root":"biblio 表示“书”，graphy 表示“写”","exampleEN":"Make sure to include a complete bibliography at the end of your research paper.","exampleCN":"确保在研究论文末尾附上完整的参考书目。","extra":""},{"chapter":5,"key":"5:125","id":125,"word":"encyclopedia","phonetic":"/ɪnˌsaɪkləʊˈpiːdiə/","pos":"n.","meaningCN":"百科全书","tag":"低频","root":"en（进入）+ cyclo（圈）+ pedia（教育）→ 原指教育","exampleEN":"Before the internet, students often turned to an encyclopedia for research.","exampleCN":"互联网之前，学生们常常查阅百科全书进行研究。","extra":""},{"chapter":5,"key":"5:126","id":126,"word":"biography","phonetic":"/baɪˈɒɡrəfi/","pos":"n.","meaningCN":"传记","tag":"高频","root":"","exampleEN":"She read a fascinating biography of Marie Curie that inspired her to study science.","exampleCN":"她读了一本引人入胜的居里夫人传记，激励了她学习科学。","extra":"autobiography 自传。"},{"chapter":5,"key":"5:127","id":127,"word":"documentary","phonetic":"/ˌdɒkjʊˈmentəri/","pos":"n.","meaningCN":"纪录片 adj. 纪录的","tag":"高频","root":"documentation n. 证明文件","exampleEN":"The documentary about climate change presented compelling evidence from scientists.","exampleCN":"这部关于气候变化的纪录片展示了科学家们令人信服的证据。","extra":""},{"chapter":5,"key":"5:128","id":128,"word":"series","phonetic":"/ˈsɪəriːz/","pos":"n.","meaningCN":"连续；一系列；系列节目","tag":"核心","root":"","exampleEN":"The lecturer will give a series of talks on modern educational methods.","exampleCN":"这位讲师将就现代教育方法发表系列演讲。","extra":"单复数同形。"},{"chapter":5,"key":"5:129","id":129,"word":"record","phonetic":"/ˈrekɔːd/","pos":"n.","meaningCN":"记录；履历","tag":"核心","root":"recorder n. 记录员；录音机，录像机","exampleEN":"Students are asked to keep a record of the books they read over the summer.","exampleCN":"学生们被要求记录下暑假期间阅读的书籍。","extra":"动词读 /rɪˈkɔːd/。"},{"chapter":5,"key":"5:130","id":130,"word":"file","phonetic":"/faɪl/","pos":"n.","meaningCN":"档案 v. 把......归档","tag":"核心","root":"","exampleEN":"Please save all the project files in the shared folder for team access.","exampleCN":"请将所有项目文件保存在共享文件夹中以便团队访问。","extra":"搭配：save a file 保存文件。"},{"chapter":5,"key":"5:131","id":131,"word":"profile","phonetic":"/ˈprəʊfaɪl/","pos":"n.","meaningCN":"概述；人物简介；侧面轮廓","tag":"高频","root":"","exampleEN":"The magazine featured a detailed profile of the award-winning author.","exampleCN":"杂志刊登了这位获奖作家的详细简介。","extra":"online profile 在线个人资料。"},{"chapter":5,"key":"5:132","id":132,"word":"draft","phonetic":"/drɑːft/","pos":"n.","meaningCN":"草稿；汇票 v. 起草","tag":"高频","root":"","exampleEN":"She wrote a rough draft of her essay before typing up the final version.","exampleCN":"她在打出最终版之前先写了论文的初稿。","extra":"first draft 初稿。"},{"chapter":5,"key":"5:133","id":133,"word":"sketch","phonetic":"/sketʃ/","pos":"n.","meaningCN":"概略 v. 概述","tag":"低频","root":"","exampleEN":"The architect drew a quick sketch of the building's design on a napkin.","exampleCN":"建筑师在餐巾纸上画了建筑物设计的草图。","extra":""},{"chapter":5,"key":"5:134","id":134,"word":"brochure","phonetic":"/ˈbrəʊʃə/","pos":"n.","meaningCN":"小册子","tag":"低频","root":"","exampleEN":"The university mailed a colourful brochure about its study abroad programmes.","exampleCN":"大学邮寄了一本关于其留学项目的彩色小册子。","extra":""},{"chapter":5,"key":"5:135","id":135,"word":"manual","phonetic":"/ˈmænjʊəl/","pos":"n.","meaningCN":"使用手册，指南 adj. 手工的","tag":"高频","root":"manually adv. 用手地；手工地","exampleEN":"Before using the equipment, read the instruction manual carefully.","exampleCN":"使用设备前，请仔细阅读使用手册。","extra":""},{"chapter":5,"key":"5:136","id":136,"word":"frame","phonetic":"/freɪm/","pos":"n.","meaningCN":"（画、镜子等的）框架；眼镜框；构架","tag":"低频","root":"","exampleEN":"The photograph was displayed in a simple wooden frame on the desk.","exampleCN":"照片放在书桌上一个简单的木制相框里。","extra":"frame of reference 参考框架。"},{"chapter":5,"key":"5:137","id":137,"word":"index","phonetic":"/ˈɪndeks/","pos":"n.","meaningCN":"指数；指标；索引 v. 为......编索引","tag":"高频","root":"","exampleEN":"Use the index at the back of the textbook to find specific topics quickly.","exampleCN":"利用教材后面的索引可以快速找到特定主题。","extra":"复数 indices 或 indexes。"},{"chapter":5,"key":"5:138","id":138,"word":"catalogue","phonetic":"/ˈkætəlɒɡ/","pos":"n.","meaningCN":"目录","tag":"低频","root":"","exampleEN":"You can search the library's online catalogue to see if the book is available.","exampleCN":"你可以搜索图书馆的在线目录，查看那本书是否可借。","extra":""},{"chapter":5,"key":"5:139","id":139,"word":"category","phonetic":"/ˈkætɪɡəri/","pos":"n.","meaningCN":"种类，类别，范畴","tag":"核心","root":"","exampleEN":"The books in the library are divided into several categories for easier browsing.","exampleCN":"图书馆的书籍分为几大类，便于浏览。","extra":"categorise v. 分类。"},{"chapter":5,"key":"5:140","id":140,"word":"inventory","phonetic":"/ˈɪnvəntɔːri/","pos":"n.","meaningCN":"库存；详细目录","tag":"低频","root":"","exampleEN":"The librarian conducted an inventory of all the resources available in the school.","exampleCN":"图书管理员对学校所有的资源进行了清点。","extra":""},{"chapter":5,"key":"5:141","id":141,"word":"content","phonetic":"/ˈkɒntent/","pos":"n.","meaningCN":"内容；目录；含量","tag":"核心","root":"","exampleEN":"The content of the course covers both theory and practical applications.","exampleCN":"课程内容涵盖理论和实际应用。","extra":"形容词读 /kənˈtent/ 满足的。"},{"chapter":5,"key":"5:142","id":142,"word":"context","phonetic":"/ˈkɒntekst/","pos":"n.","meaningCN":"上下文，语境；背景，来龙去脉","tag":"核心","root":"","exampleEN":"It is easier to guess the meaning of a new word if you understand the context.","exampleCN":"如果理解了上下文，猜测生词的含义会更容易。","extra":"搭配：in context 在上下文中。"},{"chapter":5,"key":"5:143","id":143,"word":"list","phonetic":"/lɪst/","pos":"n.","meaningCN":"一览表，目录 v. 列举；把......列表","tag":"核心","root":"","exampleEN":"She made a list of all the topics she needed to review before the exam.","exampleCN":"她把考前需要复习的所有题目列了一个清单。","extra":"shopping list 购物清单。"},{"chapter":5,"key":"5:144","id":144,"word":"chapter","phonetic":"/ˈtʃæptə/","pos":"n.","meaningCN":"（书等的）章；（人生或历史的）重要时期","tag":"核心","root":"","exampleEN":"The most important concepts are discussed in chapter five of the textbook.","exampleCN":"最重要的概念在教材的第五章讨论。","extra":""},{"chapter":5,"key":"5:145","id":145,"word":"volume","phonetic":"/ˈvɒljuːm/","pos":"n.","meaningCN":"容积，体积；卷，册；音量","tag":"高频","root":"","exampleEN":"The library holds several thousand volumes of historical documents.","exampleCN":"图书馆藏有数千卷历史文献。","extra":"turn up the volume 调高音量。"},{"chapter":5,"key":"5:146","id":146,"word":"reel","phonetic":"/riːl/","pos":"n.","meaningCN":"卷轴；卷筒；一卷胶卷","tag":"识记","root":"","exampleEN":"The old film was stored on a metal reel in the archive room.","exampleCN":"旧胶片保存在档案室的一个金属卷轴上。","extra":""},{"chapter":5,"key":"5:147","id":147,"word":"subject","phonetic":"/ˈsʌbdʒɪkt/","pos":"n.","meaningCN":"科目；主题；实验对象","tag":"核心","root":"subjective adj. 主观的","exampleEN":"Maths was always her favourite subject throughout secondary school.","exampleCN":"整个中学阶段，数学一直是她最喜欢的科目。","extra":"搭配：change the subject 转移话题。"},{"chapter":5,"key":"5:148","id":148,"word":"object","phonetic":"/ˈɒbdʒɪkt/","pos":"n.","meaningCN":"物体；目标","tag":"核心","root":"ject 表示“投掷”，如：object（反对），eject（逐出），projector（投影仪）","exampleEN":"The object of the experiment is to measure the rate of reaction.","exampleCN":"实验的目的是测量反应速率。","extra":"动词读 /əbˈdʒekt/ 反对。"},{"chapter":5,"key":"5:149","id":149,"word":"major","phonetic":"/ˈmeɪdʒə/","pos":"n.","meaningCN":"[美]主修科目，专业 v. [美]主修 adj. 主要的","tag":"核心","root":"majority n. 大多数","exampleEN":"She decided to major in biology because of her interest in marine life.","exampleCN":"由于对海洋生物的兴趣，她决定主修生物学。","extra":"搭配：major in 主修......专业。"},{"chapter":5,"key":"5:150","id":150,"word":"minor","phonetic":"/ˈmaɪnə/","pos":"n.","meaningCN":"[美]辅修科目 adj. 不严重的","tag":"核心","root":"minority n. 少数派；少数民族","exampleEN":"He is majoring in economics with a minor in statistics.","exampleCN":"他主修经济学，辅修统计学。","extra":"minor in 辅修。"},{"chapter":5,"key":"5:151","id":151,"word":"sociology","phonetic":"/ˌsəʊsiˈɒlədʒi/","pos":"n.","meaningCN":"社会学","tag":"高频","root":"society n. 社会； social adj. 社会的","exampleEN":"Sociology examines how social structures influence human behaviour and attitudes.","exampleCN":"社会学研究社会结构如何影响人类行为和态度。","extra":"sociologist n. 社会学家。"},{"chapter":5,"key":"5:152","id":152,"word":"politics","phonetic":"/ˈpɒlətɪks/","pos":"n.","meaningCN":"政治学；政治；政治事务","tag":"核心","root":"political adj. 政治的； politic adj. 得当的，明智的","exampleEN":"She studied politics and international relations at university.","exampleCN":"她在大学学习政治学和国际关系。","extra":""},{"chapter":5,"key":"5:153","id":153,"word":"economics","phonetic":"/ˌiːkəˈnɒmɪks/","pos":"n.","meaningCN":"经济学","tag":"核心","root":"economy n. 经济； economic adj. 经济上的","exampleEN":"Economics helps us understand how resources are allocated in society.","exampleCN":"经济学帮助我们理解资源在社会中如何分配。","extra":""},{"chapter":5,"key":"5:154","id":154,"word":"marketing","phonetic":"/ˈmɑːkɪtɪŋ/","pos":"n.","meaningCN":"市场营销","tag":"高频","root":"market n. 市场","exampleEN":"She took a marketing course to learn how to promote products effectively.","exampleCN":"她修了一门市场营销课程，学习如何有效推广产品。","extra":""},{"chapter":5,"key":"5:155","id":155,"word":"accounting","phonetic":"/əˈkaʊntɪŋ/","pos":"n.","meaningCN":"会计","tag":"高频","root":"account n. 账户； accountant n. 会计师","exampleEN":"A solid understanding of accounting is essential for running a successful business.","exampleCN":"扎实的会计知识对成功经营企业至关重要。","extra":""},{"chapter":5,"key":"5:156","id":156,"word":"audit","phonetic":"/ˈɔːdɪt/","pos":"n.","meaningCN":"审计 v. 旁听；审计","tag":"低频","root":"","exampleEN":"The company undergoes an annual audit to ensure financial transparency.","exampleCN":"公司每年接受审计以确保财务透明。","extra":""},{"chapter":5,"key":"5:157","id":157,"word":"statistics","phonetic":"/stəˈtɪstɪks/","pos":"n.","meaningCN":"统计学","tag":"核心","root":"","exampleEN":"Statistics is a useful tool for analysing data in social science research.","exampleCN":"统计学是社会科学研究中分析数据的有用工具。","extra":""},{"chapter":5,"key":"5:158","id":158,"word":"psychology","phonetic":"/saɪˈkɒlədʒi/","pos":"n.","meaningCN":"心理学；心理特征","tag":"核心","root":"psycho 表示“灵魂的，精神的”","exampleEN":"Psychology helps us understand why people think and behave the way they do.","exampleCN":"心理学帮助我们理解人们为何如此思考和行动。","extra":""},{"chapter":5,"key":"5:159","id":159,"word":"philosophy","phonetic":"/fɪˈlɒsəfi/","pos":"n.","meaningCN":"哲学","tag":"高频","root":"philo（爱）+ sophos（智慧）→ 爱智慧","exampleEN":"Philosophy encourages students to ask fundamental questions about existence and knowledge.","exampleCN":"哲学鼓励学生对存在和知识提出根本性问题。","extra":"philosopher n. 哲学家。"},{"chapter":5,"key":"5:160","id":160,"word":"logic","phonetic":"/ˈlɒdʒɪk/","pos":"n.","meaningCN":"逻辑；逻辑学","tag":"高频","root":"logical adj. 符合逻辑的","exampleEN":"The philosophy course includes a module on logic and critical reasoning.","exampleCN":"这门哲学课程包含一个逻辑与批判性推理模块。","extra":""},{"chapter":5,"key":"5:161","id":161,"word":"biology","phonetic":"/baɪˈɒlədʒi/","pos":"n.","meaningCN":"生物学；生命机理","tag":"核心","root":"biological adj. 生物的","exampleEN":"Biology covers topics ranging from cell structure to entire ecosystems.","exampleCN":"生物学涵盖从细胞结构到整个生态系统的主题。","extra":""},{"chapter":5,"key":"5:162","id":162,"word":"physics","phonetic":"/ˈfɪzɪks/","pos":"n.","meaningCN":"物理学","tag":"核心","root":"physicist n. 物理学家","exampleEN":"Physics explains the fundamental laws that govern the universe.","exampleCN":"物理学解释了支配宇宙的基本定律。","extra":""},{"chapter":5,"key":"5:163","id":163,"word":"chemistry","phonetic":"/ˈkemɪstri/","pos":"n.","meaningCN":"化学","tag":"核心","root":"chemist n. 化学家","exampleEN":"Chemistry experiments in the lab help students understand chemical reactions.","exampleCN":"实验室的化学实验有助于学生理解化学反应。","extra":""},{"chapter":5,"key":"5:164","id":164,"word":"agriculture","phonetic":"/ˈæɡrɪkʌltʃə/","pos":"n.","meaningCN":"农业；农学","tag":"高频","root":"agricultural adj. 农业的","exampleEN":"Sustainable agriculture is essential for ensuring food security in the future.","exampleCN":"可持续农业对于确保未来的粮食安全至关重要。","extra":""},{"chapter":5,"key":"5:165","id":165,"word":"logistics","phonetic":"/ləˈdʒɪstɪks/","pos":"n.","meaningCN":"物流；后勤","tag":"低频","root":"","exampleEN":"The course in logistics covers supply chain management and transportation.","exampleCN":"物流课程涵盖供应链管理和运输。","extra":""},{"chapter":5,"key":"5:166","id":166,"word":"geography","phonetic":"/dʒiˈɒɡrəfi/","pos":"n.","meaningCN":"地理学；地形，地势","tag":"核心","root":"geographic adj. 地理的","exampleEN":"Geography helps us understand the relationship between people and their environment.","exampleCN":"地理学帮助我们理解人与环境的关系。","extra":""},{"chapter":5,"key":"5:167","id":167,"word":"history","phonetic":"/ˈhɪstəri/","pos":"n.","meaningCN":"历史；历史学","tag":"核心","root":"historian n. 历史学家","exampleEN":"Studying history allows us to learn from past mistakes and achievements.","exampleCN":"学习历史使我们能从过去的错误和成就中吸取教训。","extra":""},{"chapter":5,"key":"5:168","id":168,"word":"engineering","phonetic":"/ˌendʒɪˈnɪərɪŋ/","pos":"n.","meaningCN":"工程；工程学","tag":"核心","root":"","exampleEN":"Engineering students often complete practical projects alongside theoretical coursework.","exampleCN":"工科生常常在理论学习的同时完成实践项目。","extra":""},{"chapter":5,"key":"5:169","id":169,"word":"mechanics","phonetic":"/mɪˈkænɪks/","pos":"n.","meaningCN":"力学；机械学","tag":"低频","root":"mechanical adj. 机械的","exampleEN":"The module in mechanics introduces students to the behaviour of physical systems.","exampleCN":"力学模块向学生介绍物理系统的行为。","extra":""},{"chapter":5,"key":"5:170","id":170,"word":"electronics","phonetic":"/ɪˌlekˈtrɒnɪks/","pos":"n.","meaningCN":"电子学；电子器件","tag":"高频","root":"electron n. 电子； electronic adj. 电子的","exampleEN":"Electronics is a rapidly evolving field with new devices emerging every year.","exampleCN":"电子学是一个快速发展的领域，每年都有新设备涌现。","extra":""},{"chapter":5,"key":"5:171","id":171,"word":"maths","phonetic":"/mæθs/","pos":"n.","meaningCN":"数学","tag":"核心","root":"mathematical adj. 数学的","exampleEN":"Maths plays a critical role in fields as diverse as engineering, finance, and computing.","exampleCN":"数学在工程、金融和计算机等多种领域都发挥着关键作用。","extra":"mathematics 的全称。"},{"chapter":5,"key":"5:172","id":172,"word":"arithmetic","phonetic":"/əˈrɪθmətɪk/","pos":"n.","meaningCN":"算术","tag":"低频","root":"","exampleEN":"Children usually learn basic arithmetic like addition and subtraction in primary school.","exampleCN":"孩子们通常在小学学习加法和减法等基本算术。","extra":""},{"chapter":5,"key":"5:173","id":173,"word":"geometry","phonetic":"/dʒiˈɒmətri/","pos":"n.","meaningCN":"几何学","tag":"低频","root":"geometric adj. 几何（学）的","exampleEN":"Geometry deals with the properties and relations of points, lines, and surfaces.","exampleCN":"几何学研究点、线、面的性质和关系。","extra":""},{"chapter":5,"key":"5:174","id":174,"word":"algebra","phonetic":"/ˈældʒɪbrə/","pos":"n.","meaningCN":"代数学，代数","tag":"低频","root":"","exampleEN":"Algebra teaches students how to solve equations and work with unknown variables.","exampleCN":"代数教学生如何解方程和处理未知变量。","extra":""},{"chapter":5,"key":"5:175","id":175,"word":"calculus","phonetic":"/ˈkælkjʊləs/","pos":"n.","meaningCN":"微积分；结石","tag":"低频","root":"","exampleEN":"Calculus is essential for understanding concepts in advanced physics and engineering.","exampleCN":"微积分对于理解高等物理和工程学概念至关重要。","extra":""},{"chapter":5,"key":"5:176","id":176,"word":"plus","phonetic":"/plʌs/","pos":"prep.","meaningCN":"加上 adj. 正（数）的，在零以上的","tag":"核心","root":"","exampleEN":"Two plus two equals four, which is one of the first equations children learn.","exampleCN":"二加二等于四，这是孩子们最早学的等式之一。","extra":""},{"chapter":5,"key":"5:177","id":177,"word":"sum","phonetic":"/sʌm/","pos":"n.","meaningCN":"总数，总和；金额","tag":"核心","root":"","exampleEN":"The sum of all the angles in a triangle is always 180 degrees.","exampleCN":"三角形三个内角之和总是180度。","extra":""},{"chapter":5,"key":"5:178","id":178,"word":"total","phonetic":"/ˈtəʊtəl/","pos":"adj.","meaningCN":"总的，全部的 n. 总数","tag":"核心","root":"","exampleEN":"The total cost of the course includes tuition fees and learning materials.","exampleCN":"课程的总费用包括学费和学习材料。","extra":""},{"chapter":5,"key":"5:179","id":179,"word":"merger","phonetic":"/ˈmɜːdʒə/","pos":"n.","meaningCN":"合并，归并","tag":"低频","root":"","exampleEN":"The merger of two universities created one of the largest institutions in the country.","exampleCN":"两所大学的合并形成了全国最大的高等学府之一。","extra":""},{"chapter":5,"key":"5:180","id":180,"word":"equation","phonetic":"/ɪˈkweɪʒən/","pos":"n.","meaningCN":"相等；平衡，综合体；方程式，等式","tag":"核心","root":"equivalent adj. 相等的","exampleEN":"The student solved a complex equation involving two unknown variables.","exampleCN":"学生解了一道包含两个未知变量的复杂方程式。","extra":""},{"chapter":5,"key":"5:181","id":181,"word":"identical","phonetic":"/aɪˈdentɪkəl/","pos":"adj.","meaningCN":"同一的","tag":"高频","root":"identity n. 同一性","exampleEN":"The two copies of the document appeared identical, so it was hard to tell them apart.","exampleCN":"这两份文件看起来一模一样，很难区分。","extra":""},{"chapter":5,"key":"5:182","id":182,"word":"minus","phonetic":"/ˈmaɪnəs/","pos":"adj.","meaningCN":"负的，零以下的 prep. 减（去）","tag":"核心","root":"","exampleEN":"The temperature dropped to minus five degrees overnight.","exampleCN":"夜间气温降至零下五度。","extra":""},{"chapter":5,"key":"5:183","id":183,"word":"subtract","phonetic":"/səbˈtrækt/","pos":"v.","meaningCN":"减去，减","tag":"低频","root":"","exampleEN":"If you subtract ten from thirty, you get twenty.","exampleCN":"三十减去十等于二十。","extra":""},{"chapter":5,"key":"5:184","id":184,"word":"multiply","phonetic":"/ˈmʌltɪplaɪ/","pos":"v.","meaningCN":"乘，使相乘；（使）成倍增加；繁殖","tag":"核心","root":"","exampleEN":"If you multiply six by seven, the result is forty-two.","exampleCN":"六乘以七等于四十二。","extra":""},{"chapter":5,"key":"5:185","id":185,"word":"divide","phonetic":"/dɪˈvaɪd/","pos":"v.","meaningCN":"除以；除","tag":"核心","root":"","exampleEN":"The teacher asked the students to divide 100 by 4 and write down the answer.","exampleCN":"老师让学生用100除以4并写下答案。","extra":"搭配：divide A by B。"},{"chapter":5,"key":"5:186","id":186,"word":"dividend","phonetic":"/ˈdɪvɪdend/","pos":"n.","meaningCN":"被除数","tag":"识记","root":"division n. 分配；除法","exampleEN":"In the equation 15 ÷ 3 = 5, the dividend is 15.","exampleCN":"在等式15 ÷ 3 = 5中，被除数是15。","extra":""},{"chapter":5,"key":"5:187","id":187,"word":"remainder","phonetic":"/rɪˈmeɪndə/","pos":"n.","meaningCN":"余数；剩余部分","tag":"识记","root":"","exampleEN":"When you divide 17 by 5, the remainder is 2.","exampleCN":"17除以5，余数是2。","extra":""},{"chapter":5,"key":"5:188","id":188,"word":"rational","phonetic":"/ˈræʃənəl/","pos":"n.","meaningCN":"有理数 adj.（数、式等）有理的","tag":"低频","root":"","exampleEN":"A rational number is any number that can be written as a simple fraction.","exampleCN":"有理数是可以写成简单分数的数。","extra":""},{"chapter":5,"key":"5:189","id":189,"word":"parameter","phonetic":"/pəˈræmɪtə/","pos":"n.","meaningCN":"参数；起限定作用的因素","tag":"低频","root":"para 指“旁，侧”","exampleEN":"The researchers defined the parameters of the study before collecting data.","exampleCN":"研究人员在收集数据前定义了研究的参数。","extra":""},{"chapter":5,"key":"5:190","id":190,"word":"variable","phonetic":"/ˈveəriəbəl/","pos":"n.","meaningCN":"变量；可变因素 adj. 易变的","tag":"高频","root":"","exampleEN":"In this experiment, temperature is the independent variable.","exampleCN":"在这个实验中，温度是自变量。","extra":""},{"chapter":5,"key":"5:191","id":191,"word":"even","phonetic":"/ˈiːvən/","pos":"adj.","meaningCN":"均匀的；偶数的；相等的 adv. 甚至","tag":"核心","root":"","exampleEN":"All even numbers can be divided by two without a remainder.","exampleCN":"所有偶数都能被2整除，无余数。","extra":""},{"chapter":5,"key":"5:192","id":192,"word":"odd","phonetic":"/ɒd/","pos":"adj.","meaningCN":"奇数的；古怪的","tag":"核心","root":"odds n. 可能性","exampleEN":"One, three, and five are examples of odd numbers.","exampleCN":"1、3、5都是奇数的例子。","extra":""},{"chapter":5,"key":"5:193","id":193,"word":"mean","phonetic":"/miːn/","pos":"n.","meaningCN":"平均数，平均值 adj. 平均的","tag":"核心","root":"","exampleEN":"To find the mean, add up all the numbers and divide by how many there are.","exampleCN":"求平均数的方法是：将所有数字相加，然后除以数字的个数。","extra":""},{"chapter":5,"key":"5:194","id":194,"word":"double","phonetic":"/ˈdʌbəl/","pos":"adj.","meaningCN":"两倍的 n. 两倍数，两倍量 v.（使）加倍","tag":"核心","root":"","exampleEN":"The number of students in the programme has doubled over the past five years.","exampleCN":"过去五年里，该项目学生人数翻了一番。","extra":""},{"chapter":5,"key":"5:195","id":195,"word":"triple","phonetic":"/ˈtrɪpəl/","pos":"adj.","meaningCN":"三倍的 n. 三倍 v.（使）增至三倍","tag":"低频","root":"","exampleEN":"The company's profits tripled after the launch of their new product line.","exampleCN":"推出新生产线后，公司利润增至原来的三倍。","extra":""},{"chapter":5,"key":"5:196","id":196,"word":"quadruple","phonetic":"/ˈkwɒdrʊpəl/","pos":"adj.","meaningCN":"四倍的 n. 四倍 v.（使）成四倍","tag":"识记","root":"quarter n. 四分之一","exampleEN":"The number of applicants has quadrupled compared to last year.","exampleCN":"与去年相比，申请人数翻了两番。","extra":""},{"chapter":5,"key":"5:197","id":197,"word":"multiple","phonetic":"/ˈmʌltɪpəl/","pos":"n.","meaningCN":"倍数 adj. 多样的，数量多的","tag":"核心","root":"","exampleEN":"The exam consists of multiple choice questions and a short essay section.","exampleCN":"考试由多项选择题和一个短文部分组成。","extra":""},{"chapter":5,"key":"5:198","id":198,"word":"maximum","phonetic":"/ˈmæksɪməm/","pos":"n.","meaningCN":"最大值，最大限度","tag":"核心","root":"maximise v. 使最大化","exampleEN":"The maximum score on the test is 100 points.","exampleCN":"测试的最高分是100分。","extra":""},{"chapter":5,"key":"5:199","id":199,"word":"minimum","phonetic":"/ˈmɪnɪməm/","pos":"n.","meaningCN":"最小值，最低限度","tag":"核心","root":"minimise v. 使最小化","exampleEN":"A minimum of 60 points is required to pass the exam.","exampleCN":"至少需要60分才能通过考试。","extra":""},{"chapter":5,"key":"5:200","id":200,"word":"approximately","phonetic":"/əˈprɒksɪmətli/","pos":"adv.","meaningCN":"大约","tag":"核心","root":"proximity n. 接近","exampleEN":"Approximately 300 students took part in the survey.","exampleCN":"大约有300名学生参与了这项调查。","extra":""},{"chapter":5,"key":"5:201","id":201,"word":"chart","phonetic":"/tʃɑːt/","pos":"n.","meaningCN":"图，图表；海图","tag":"核心","root":"","exampleEN":"The pie chart clearly shows how students spend their time each day.","exampleCN":"饼状图清楚地显示了学生每天如何分配时间。","extra":""},{"chapter":5,"key":"5:202","id":202,"word":"graph","phonetic":"/ɡrɑːf/","pos":"n.","meaningCN":"图，图表","tag":"核心","root":"graphic adj. 绘画的，图像的","exampleEN":"The graph illustrates the steady increase in online course enrolments.","exampleCN":"图表表明在线课程注册人数稳步增长。","extra":""},{"chapter":5,"key":"5:203","id":203,"word":"diagram","phonetic":"/ˈdaɪəɡræm/","pos":"n.","meaningCN":"图表；示意图，图解","tag":"高频","root":"","exampleEN":"The textbook includes a diagram of the human digestive system.","exampleCN":"教科书里有人体消化系统的示意图。","extra":""},{"chapter":5,"key":"5:204","id":204,"word":"table","phonetic":"/ˈteɪbəl/","pos":"n.","meaningCN":"表格；桌子","tag":"核心","root":"","exampleEN":"The results of the experiment are presented in a clear table.","exampleCN":"实验结果显示在一个清晰的表格中。","extra":""},{"chapter":5,"key":"5:205","id":205,"word":"matrix","phonetic":"/ˈmeɪtrɪks/","pos":"n.","meaningCN":"矩阵；铸模","tag":"识记","root":"","exampleEN":"Students learn to perform matrix multiplication in advanced algebra.","exampleCN":"学生在高等代数学中学习矩阵乘法。","extra":""},{"chapter":5,"key":"5:206","id":206,"word":"rectangle","phonetic":"/ˈrektæŋɡəl/","pos":"n.","meaningCN":"长方形，矩形","tag":"低频","root":"","exampleEN":"The area of a rectangle is calculated by multiplying its length by its width.","exampleCN":"长方形的面积等于长乘以宽。","extra":""},{"chapter":5,"key":"5:207","id":207,"word":"cube","phonetic":"/kjuːb/","pos":"n.","meaningCN":"立方体；立方，三次幂；立方形的东西","tag":"低频","root":"cubic adj. 立方形的","exampleEN":"The volume of a cube is found by raising the length of one side to the third power.","exampleCN":"立方体的体积等于边长的三次幂。","extra":""},{"chapter":5,"key":"5:208","id":208,"word":"angle","phonetic":"/ˈæŋɡəl/","pos":"n.","meaningCN":"角；角度","tag":"核心","root":"","exampleEN":"A right angle measures exactly 90 degrees.","exampleCN":"直角正好是90度。","extra":""},{"chapter":5,"key":"5:209","id":209,"word":"triangle","phonetic":"/ˈtraɪæŋɡəl/","pos":"n.","meaningCN":"三角形；三角关系","tag":"低频","root":"","exampleEN":"An equilateral triangle has three sides of equal length.","exampleCN":"等边三角形有三条等长的边。","extra":""},{"chapter":5,"key":"5:210","id":210,"word":"diagonal","phonetic":"/daɪˈæɡənəl/","pos":"adj.","meaningCN":"斜纹的；对角线的 n. 对角线；斜纹织物","tag":"识记","root":"","exampleEN":"Draw a diagonal line from the top left corner to the bottom right.","exampleCN":"从左上角到右下角画一条对角线。","extra":""},{"chapter":5,"key":"5:211","id":211,"word":"straight","phonetic":"/streɪt/","pos":"adj.","meaningCN":"直的 adv. 笔直地；直接","tag":"核心","root":"","exampleEN":"Draw a straight line connecting the two points on the graph.","exampleCN":"在图上画一条直线连接两点。","extra":""},{"chapter":5,"key":"5:212","id":212,"word":"circle","phonetic":"/ˈsɜːkəl/","pos":"n.","meaningCN":"圆","tag":"核心","root":"circular adj. 圆的； circulate v. 循环","exampleEN":"The students sat in a circle to discuss their project ideas.","exampleCN":"学生们围坐成一圈讨论项目构想。","extra":""},{"chapter":5,"key":"5:213","id":213,"word":"round","phonetic":"/raʊnd/","pos":"adj.","meaningCN":"圆的 n. 绕圈；一轮 adv. 环绕","tag":"核心","root":"","exampleEN":"The teacher handed out worksheets for the next round of group activities.","exampleCN":"老师为下一轮小组活动分发了工作表。","extra":""},{"chapter":5,"key":"5:214","id":214,"word":"dot","phonetic":"/dɒt/","pos":"n.","meaningCN":"点，圆点 v. 在......上打点","tag":"低频","root":"","exampleEN":"The graph uses a red dot to highlight the average score for each group.","exampleCN":"图表用红点标示每组的平均分。","extra":""},{"chapter":5,"key":"5:215","id":215,"word":"sphere","phonetic":"/sfɪə/","pos":"n.","meaningCN":"球体；球状物；范围，领域","tag":"高频","root":"","exampleEN":"Her expertise lies in the sphere of higher education policy.","exampleCN":"她的专长在高等教育政策领域。","extra":""},{"chapter":5,"key":"5:216","id":216,"word":"cone","phonetic":"/kəʊn/","pos":"n.","meaningCN":"圆锥体；锥形物","tag":"识记","root":"","exampleEN":"The students used a paper cone to demonstrate how sound waves travel.","exampleCN":"学生们用纸锥演示声波如何传播。","extra":""},{"chapter":5,"key":"5:217","id":217,"word":"extent","phonetic":"/ɪkˈstent/","pos":"n.","meaningCN":"广度，范围；程度","tag":"核心","root":"","exampleEN":"To a certain extent, test scores reflect a student's understanding of the material.","exampleCN":"在某种程度上，考试分数反映了学生对材料的理解。","extra":"搭配：to some extent 在某种程度上。"},{"chapter":5,"key":"5:218","id":218,"word":"width","phonetic":"/wɪdθ/","pos":"n.","meaningCN":"宽度","tag":"核心","root":"","exampleEN":"Measure the width of the desk to see if it will fit in the study corner.","exampleCN":"量一下书桌的宽度，看能不能放进学习角。","extra":""},{"chapter":5,"key":"5:219","id":219,"word":"length","phonetic":"/leŋkθ/","pos":"n.","meaningCN":"长度","tag":"核心","root":"","exampleEN":"The length of the swimming pool is 50 metres, which is standard for competitions.","exampleCN":"游泳池长50米，是竞赛标准长度。","extra":""},{"chapter":5,"key":"5:220","id":220,"word":"decimal","phonetic":"/ˈdesɪməl/","pos":"adj.","meaningCN":"小数的；十进位的 n. 小数","tag":"低频","root":"deci 表示“十分之一”","exampleEN":"In many countries, the decimal point is used to separate whole numbers from fractions.","exampleCN":"在许多国家，小数点用于将整数与小数部分分开。","extra":"搭配：a decimal point 小数点。"},{"chapter":5,"key":"5:221","id":221,"word":"per cent","phonetic":"/pə ˈsent/","pos":"n.","meaningCN":"百分之......","tag":"核心","root":"cent 指“一百”","exampleEN":"About 75 per cent of the students in the survey said they enjoyed online learning.","exampleCN":"调查中约75%的学生表示喜欢在线学习。","extra":""},{"chapter":5,"key":"5:222","id":222,"word":"proportion","phonetic":"/prəˈpɔːʃən/","pos":"n.","meaningCN":"比例","tag":"核心","root":"","exampleEN":"A large proportion of the university's budget is spent on research projects.","exampleCN":"大学预算的一大部分用于研究项目。","extra":""},{"chapter":5,"key":"5:223","id":223,"word":"rate","phonetic":"/reɪt/","pos":"n.","meaningCN":"比率，率；速度","tag":"核心","root":"","exampleEN":"The graduation rate has improved significantly after the new support programmes.","exampleCN":"实施新的支持计划后，毕业率显著提高。","extra":""},{"chapter":5,"key":"5:224","id":224,"word":"ratio","phonetic":"/ˈreɪʃiəʊ/","pos":"n.","meaningCN":"比（率）","tag":"高频","root":"","exampleEN":"The optimal student-to-teacher ratio in a language class is around 15 to 1.","exampleCN":"语言课最佳师生比约为15:1。","extra":""},{"chapter":5,"key":"5:225","id":225,"word":"fraction","phonetic":"/ˈfrækʃən/","pos":"n.","meaningCN":"分数；小部分；片断","tag":"高频","root":"","exampleEN":"Only a fraction of the students had previous experience with coding.","exampleCN":"只有一小部分学生以前有过编程经验。","extra":""},{"chapter":5,"key":"5:226","id":226,"word":"scale","phonetic":"/skeɪl/","pos":"n.","meaningCN":"刻度；规模；[~s] 天平；鳞 v. 攀登","tag":"核心","root":"","exampleEN":"The graph has a vertical scale from zero to one hundred per cent.","exampleCN":"图表的纵轴刻度从0%到100%。","extra":"搭配：on a large scale 大规模地。"},{"chapter":5,"key":"5:227","id":227,"word":"ounce","phonetic":"/aʊns/","pos":"n.","meaningCN":"盎司；少量","tag":"识记","root":"","exampleEN":"An ounce of practice is worth a pound of theory in language learning.","exampleCN":"在语言学习中，一分实践胜过十分理论。","extra":""},{"chapter":5,"key":"5:228","id":228,"word":"density","phonetic":"/ˈdensəti/","pos":"n.","meaningCN":"密度；浓度","tag":"高频","root":"","exampleEN":"Population density is usually higher in urban areas than in rural regions.","exampleCN":"城市地区的人口密度通常高于农村地区。","extra":""},{"chapter":5,"key":"5:229","id":229,"word":"Fahrenheit","phonetic":"/ˈfærənhaɪt/","pos":"adj.","meaningCN":"华氏温标的","tag":"识记","root":"","exampleEN":"In the Fahrenheit scale, water freezes at 32 degrees.","exampleCN":"在华氏温标中，水在32度结冰。","extra":""},{"chapter":5,"key":"5:230","id":230,"word":"mercury","phonetic":"/ˈmɜːkjəri/","pos":"n.","meaningCN":"水银，汞；[M-]水星","tag":"低频","root":"","exampleEN":"The science teacher explained how mercury expands in a thermometer when heated.","exampleCN":"科学老师解释了温度计中的水银如何受热膨胀。","extra":""},{"chapter":5,"key":"5:231","id":231,"word":"battery","phonetic":"/ˈbætəri/","pos":"n.","meaningCN":"电池；（物品的）一组","tag":"核心","root":"","exampleEN":"The electronic dictionary runs on two small batteries.","exampleCN":"电子词典靠两节小电池运行。","extra":""},{"chapter":5,"key":"5:232","id":232,"word":"volt","phonetic":"/vəʊlt/","pos":"n.","meaningCN":"伏特（电压单位）","tag":"识记","root":"","exampleEN":"Standard household voltage in many countries is 220 to 240 volts.","exampleCN":"许多国家的标准家用电压为220至240伏。","extra":""},{"chapter":5,"key":"5:233","id":233,"word":"radiate","phonetic":"/ˈreɪdieɪt/","pos":"v.","meaningCN":"辐射，发散；从中心向四周散开","tag":"低频","root":"radiation n. 辐射","exampleEN":"The sun radiates energy that is essential for life on Earth.","exampleCN":"太阳辐射的能量对地球上的生命至关重要。","extra":""},{"chapter":5,"key":"5:234","id":234,"word":"emit","phonetic":"/ɪˈmɪt/","pos":"v.","meaningCN":"散发（光、热、气等）；发出（声音）","tag":"高频","root":"emission n. 散发，排放","exampleEN":"Burning fossil fuels emits carbon dioxide into the atmosphere.","exampleCN":"燃烧化石燃料会向大气中排放二氧化碳。","extra":""},{"chapter":5,"key":"5:235","id":235,"word":"transparent","phonetic":"/trænsˈpærənt/","pos":"adj.","meaningCN":"透明的；易看穿的","tag":"高频","root":"","exampleEN":"The laboratory uses transparent containers so students can observe the reactions.","exampleCN":"实验室使用透明容器，以便学生观察反应。","extra":""},{"chapter":5,"key":"5:236","id":236,"word":"hollow","phonetic":"/ˈhɒləʊ/","pos":"adj.","meaningCN":"空（心）的，中空的","tag":"低频","root":"","exampleEN":"The sample appears solid from the outside but is actually hollow inside.","exampleCN":"样品外表看上去是实心的，但实际上是中空的。","extra":""},{"chapter":5,"key":"5:237","id":237,"word":"ozone","phonetic":"/ˈəʊzəʊn/","pos":"n.","meaningCN":"臭氧","tag":"高频","root":"","exampleEN":"The ozone layer protects living organisms from harmful ultraviolet radiation.","exampleCN":"臭氧层保护生物免受有害紫外线的伤害。","extra":"搭配：ozone layer 臭氧层。"},{"chapter":5,"key":"5:238","id":238,"word":"gravity","phonetic":"/ˈɡrævəti/","pos":"n.","meaningCN":"地球引力，重力","tag":"核心","root":"","exampleEN":"The concept of gravity was famously explored by Isaac Newton.","exampleCN":"艾萨克·牛顿对重力概念进行了著名的探索。","extra":""},{"chapter":5,"key":"5:239","id":239,"word":"friction","phonetic":"/ˈfrɪkʃən/","pos":"n.","meaningCN":"摩擦；摩擦力；不和，矛盾","tag":"高频","root":"","exampleEN":"Rubbing your hands together creates friction and generates warmth.","exampleCN":"双手摩擦产生摩擦力并产生热量。","extra":""},{"chapter":5,"key":"5:240","id":240,"word":"eccentric","phonetic":"/ɪkˈsentrɪk/","pos":"adj.","meaningCN":"不同圆心的；古怪的","tag":"低频","root":"","exampleEN":"The professor was known for his eccentric teaching style, which students found fascinating.","exampleCN":"这位教授以古怪的教学风格闻名，学生们觉得很吸引人。","extra":""},{"chapter":5,"key":"5:241","id":241,"word":"displace","phonetic":"/dɪsˈpleɪs/","pos":"v.","meaningCN":"移动......的位置；取代，替代","tag":"低频","root":"","exampleEN":"Heavy textbooks have largely been displaced by digital resources in many classrooms.","exampleCN":"在许多教室里，厚重的教科书已在很大程度上被数字资源所取代。","extra":""},{"chapter":5,"key":"5:242","id":242,"word":"boil","phonetic":"/bɔɪl/","pos":"v.","meaningCN":"煮沸，（使）沸腾 n. 沸点","tag":"核心","root":"","exampleEN":"In the experiment, we heated the water until it began to boil.","exampleCN":"在实验中，我们把水加热直到沸腾。","extra":""},{"chapter":5,"key":"5:243","id":243,"word":"melt","phonetic":"/melt/","pos":"v.","meaningCN":"（使）融化；（使）熔化","tag":"核心","root":"","exampleEN":"Ice cream melts quickly under the hot sun, so eat it fast.","exampleCN":"冰淇淋在烈日下融化得很快，所以快吃吧。","extra":""},{"chapter":5,"key":"5:244","id":244,"word":"dissolve","phonetic":"/dɪˈzɒlv/","pos":"v.","meaningCN":"（使）溶解；解散","tag":"高频","root":"","exampleEN":"Stir the powder into the warm water until it completely dissolves.","exampleCN":"把粉末搅拌进温水中，直到完全溶解。","extra":""},{"chapter":5,"key":"5:245","id":245,"word":"rust","phonetic":"/rʌst/","pos":"v.","meaningCN":"（使）生锈 n. 锈，铁锈","tag":"低频","root":"rusty adj. 生锈的","exampleEN":"If you leave the metal tools outside, the rain will cause them to rust.","exampleCN":"如果把金属工具留在外面，雨水会使它们生锈。","extra":""},{"chapter":5,"key":"5:246","id":246,"word":"ferment","phonetic":"/fɜːˈment/","pos":"v.","meaningCN":"（使）发酵；骚动","tag":"低频","root":"yeast n. 酵母","exampleEN":"The grapes are left to ferment in large barrels for several weeks.","exampleCN":"葡萄被放在大桶中发酵数周。","extra":"名词读 /ˈfɜːment/。"},{"chapter":5,"key":"5:247","id":247,"word":"dilute","phonetic":"/daɪˈluːt/","pos":"v.","meaningCN":"冲淡，稀释 adj. 稀释了的；减弱了的","tag":"低频","root":"dilution n. 稀释","exampleEN":"You can dilute the concentrated juice with water to make it taste milder.","exampleCN":"你可以用水稀释浓缩果汁，使其味道变淡。","extra":""},{"chapter":5,"key":"5:248","id":248,"word":"inherent","phonetic":"/ɪnˈherənt/","pos":"adj.","meaningCN":"内在的，固有的","tag":"高频","root":"","exampleEN":"There are risks inherent in any scientific experiment, but safety measures reduce them.","exampleCN":"任何科学实验都存在固有风险，但安全措施能降低风险。","extra":"搭配：be inherent in 为......所固有。"},{"chapter":5,"key":"5:249","id":249,"word":"acid","phonetic":"/ˈæsɪd/","pos":"n.","meaningCN":"酸 adj. 酸的；讽刺的，尖刻的","tag":"核心","root":"acidification n. 酸化","exampleEN":"In chemistry class, we tested the liquid with litmus paper to see if it was an acid.","exampleCN":"化学课上，我们用石蕊试纸测试液体，看它是不是酸。","extra":"搭配：acid rain 酸雨。"},{"chapter":5,"key":"5:250","id":250,"word":"noxious","phonetic":"/ˈnɒkʃəs/","pos":"adj.","meaningCN":"有害的","tag":"低频","root":"","exampleEN":"Noxious chemicals must be handled with protective equipment in the lab.","exampleCN":"在实验室处理有毒化学品时必须佩戴防护装备。","extra":""},{"chapter":5,"key":"5:251","id":251,"word":"static","phonetic":"/ˈstætɪk/","pos":"adj.","meaningCN":"静态的；静力的","tag":"低频","root":"","exampleEN":"The data on the screen remained static until the system refreshed.","exampleCN":"屏幕上的数据保持静态，直到系统刷新。","extra":""},{"chapter":5,"key":"5:252","id":252,"word":"inert","phonetic":"/ɪˈnɜːt/","pos":"adj.","meaningCN":"无生气的；惰性的，不活泼的","tag":"识记","root":"","exampleEN":"Helium is an inert gas that does not react with other substances.","exampleCN":"氦是一种惰性气体，不与其他物质发生反应。","extra":""},{"chapter":5,"key":"5:253","id":253,"word":"formula","phonetic":"/ˈfɔːmjʊlə/","pos":"n.","meaningCN":"公式，方程式；原则；配方；分子式","tag":"核心","root":"","exampleEN":"The chemical formula for carbon dioxide is CO₂.","exampleCN":"二氧化碳的化学式是CO₂。","extra":""},{"chapter":5,"key":"5:254","id":254,"word":"component","phonetic":"/kəmˈpəʊnənt/","pos":"n.","meaningCN":"成分，组成部分","tag":"核心","root":"","exampleEN":"Teamwork is a crucial component of the course, so students work in groups on projects.","exampleCN":"团队合作是课程的重要组成部分，因此学生们分组完成项目。","extra":""},{"chapter":5,"key":"5:255","id":255,"word":"compose","phonetic":"/kəmˈpəʊz/","pos":"v.","meaningCN":"组成；构成；创作（音乐）；写","tag":"核心","root":"pos 指“放置”","exampleEN":"The textbook is composed of ten chapters, each covering a different topic.","exampleCN":"这本教材由十章组成，每章涵盖一个不同主题。","extra":"搭配：be composed of 由......组成。"},{"chapter":5,"key":"5:256","id":256,"word":"mixture","phonetic":"/ˈmɪkstʃə/","pos":"n.","meaningCN":"混合（物）","tag":"核心","root":"mix v. 混合","exampleEN":"The city's culture is a fascinating mixture of old traditions and modern life.","exampleCN":"这座城市的文化是古老传统与现代生活的迷人结合。","extra":""},{"chapter":5,"key":"5:257","id":257,"word":"blend","phonetic":"/blend/","pos":"v.","meaningCN":"混合；（使）交融 n. 混合物","tag":"高频","root":"","exampleEN":"The course blends online lectures with face-to-face tutorials.","exampleCN":"这门课程融合了在线讲座和面对面辅导。","extra":""},{"chapter":5,"key":"5:258","id":258,"word":"theory","phonetic":"/ˈθɪəri/","pos":"n.","meaningCN":"理论；学说","tag":"核心","root":"theoretical adj. 理论上的","exampleEN":"In science, a theory must be supported by repeated experiments and evidence.","exampleCN":"在科学中，理论必须得到反复实验和证据的支持。","extra":""},{"chapter":5,"key":"5:259","id":259,"word":"empirical","phonetic":"/ɪmˈpɪrɪkəl/","pos":"adj.","meaningCN":"以实验为依据的；经验主义的","tag":"高频","root":"em（进入）+ pir（尝试）+ ical → 尝试过的，有经验的","exampleEN":"The researchers gathered empirical data through a large-scale survey.","exampleCN":"研究人员通过大规模调查收集了经验数据。","extra":""},{"chapter":5,"key":"5:260","id":260,"word":"practical","phonetic":"/ˈpræktɪkəl/","pos":"adj.","meaningCN":"实际的；有用的；务实的；心灵手巧的","tag":"核心","root":"practice n. 实践；练习","exampleEN":"The course aims to provide students with practical skills for the workplace.","exampleCN":"这门课程旨在为学生提供实用的职场技能。","extra":""},{"chapter":5,"key":"5:261","id":261,"word":"doctrine","phonetic":"/ˈdɒktrɪn/","pos":"n.","meaningCN":"学说；教义；信条","tag":"低频","root":"doctrinal adj. 学说的","exampleEN":"The professor challenged the long-held doctrine by presenting new findings.","exampleCN":"教授通过展示新发现挑战了长期以来的学说。","extra":""},{"chapter":5,"key":"5:262","id":262,"word":"principle","phonetic":"/ˈprɪnsəpəl/","pos":"n.","meaningCN":"原则；（科学）原理","tag":"核心","root":"","exampleEN":"The course introduces the basic principles of economics.","exampleCN":"这门课程介绍经济学的基本原理。","extra":""},{"chapter":5,"key":"5:263","id":263,"word":"discipline","phonetic":"/ˈdɪsɪplɪn/","pos":"n.","meaningCN":"纪律；训练","tag":"核心","root":"","exampleEN":"Self-discipline is often more important than talent in achieving academic success.","exampleCN":"在取得学业成功方面，自律往往比天赋更重要。","extra":""},{"chapter":5,"key":"5:264","id":264,"word":"term","phonetic":"/tɜːm/","pos":"n.","meaningCN":"期限；术语；[尤英]学期","tag":"核心","root":"terminal adj. 末端的","exampleEN":"The autumn term usually starts in September and ends in December.","exampleCN":"秋季学期通常从九月开始，十二月结束。","extra":"搭配：in the long term 从长远来看。"},{"chapter":5,"key":"5:265","id":265,"word":"semester","phonetic":"/sɪˈmestə/","pos":"n.","meaningCN":"学期","tag":"核心","root":"","exampleEN":"Each semester lasts about 15 weeks, followed by a short break.","exampleCN":"每个学期持续约15周，之后有一个短假期。","extra":""},{"chapter":5,"key":"5:266","id":266,"word":"timetable","phonetic":"/ˈtaɪmˌteɪbəl/","pos":"n.","meaningCN":"时间表；课程表","tag":"核心","root":"","exampleEN":"Check the online timetable to see when your lectures and seminars are scheduled.","exampleCN":"查看在线课表，了解你的讲座和讨论课安排在何时。","extra":""},{"chapter":5,"key":"5:267","id":267,"word":"schedule","phonetic":"/ˈʃedjuːl/","pos":"n.","meaningCN":"日程安排；[美]时刻表","tag":"核心","root":"","exampleEN":"She planned a study schedule to make sure she covered all topics before the exam.","exampleCN":"她制定了一个学习日程，确保在考试前覆盖所有主题。","extra":"搭配：on schedule 准时。"},{"chapter":5,"key":"5:268","id":268,"word":"deadline","phonetic":"/ˈdedlaɪn/","pos":"n.","meaningCN":"截止日期","tag":"核心","root":"","exampleEN":"The deadline for submitting the application is next Monday at noon.","exampleCN":"提交申请的截止日期是下周一中午。","extra":""},{"chapter":5,"key":"5:269","id":269,"word":"course","phonetic":"/kɔːs/","pos":"n.","meaningCN":"课程","tag":"核心","root":"","exampleEN":"She decided to take an online course to improve her programming skills.","exampleCN":"她决定修一门在线课程来提高编程技能。","extra":""},{"chapter":5,"key":"5:270","id":270,"word":"lesson","phonetic":"/ˈlesən/","pos":"n.","meaningCN":"一堂课；课程；教训","tag":"核心","root":"","exampleEN":"Each lesson begins with a short review of the previous topic.","exampleCN":"每节课开始时都会简要复习上一课的内容。","extra":"搭配：learn a lesson 吸取教训。"},{"chapter":5,"key":"5:271","id":271,"word":"curriculum","phonetic":"/kəˈrɪkjʊləm/","pos":"n.","meaningCN":"课程；（学校等的）全部课程","tag":"高频","root":"extra-curricular adj. 课外的","exampleEN":"The school is redesigning its curriculum to include more technology-related subjects.","exampleCN":"学校正在重新设计课程，以纳入更多与技术相关的科目。","extra":"复数 curricula 或 curriculums。"},{"chapter":5,"key":"5:272","id":272,"word":"seminar","phonetic":"/ˈsemɪnɑː/","pos":"n.","meaningCN":"研讨会；讨论课","tag":"高频","root":"semin 指“种子”，如：disseminate（传播）","exampleEN":"The seminar on global literature attracted students from various departments.","exampleCN":"关于全球文学的研讨会吸引了来自各个系的学生。","extra":""},{"chapter":5,"key":"5:273","id":273,"word":"forum","phonetic":"/ˈfɔːrəm/","pos":"n.","meaningCN":"讨论会，论坛；公开讨论的广场","tag":"高频","root":"","exampleEN":"The university set up an online forum where students can discuss course materials.","exampleCN":"大学设立了一个在线论坛，学生可以在上面讨论课程材料。","extra":""},{"chapter":5,"key":"5:274","id":274,"word":"syllabus","phonetic":"/ˈsɪləbəs/","pos":"n.","meaningCN":"教学大纲","tag":"低频","root":"","exampleEN":"The syllabus for the course includes the reading list and assessment criteria.","exampleCN":"课程的教学大纲包括阅读书目和评估标准。","extra":""},{"chapter":5,"key":"5:275","id":275,"word":"system","phonetic":"/ˈsɪstəm/","pos":"n.","meaningCN":"系统；体系，制度","tag":"核心","root":"systematic adj. 系统的","exampleEN":"The education system in Finland is often praised for its innovative approach.","exampleCN":"芬兰的教育体系常因创新的方法而受到称赞。","extra":""},{"chapter":5,"key":"5:276","id":276,"word":"rudimentary","phonetic":"/ˌruːdɪˈmentəri/","pos":"adj.","meaningCN":"基本的，粗浅的","tag":"低频","root":"rudiment n. 基本原理","exampleEN":"He had only a rudimentary knowledge of the language before starting the course.","exampleCN":"在开始这门课之前，他只掌握该语言的基础知识。","extra":""},{"chapter":5,"key":"5:277","id":277,"word":"basic","phonetic":"/ˈbeɪsɪk/","pos":"adj.","meaningCN":"基本的，基础的","tag":"核心","root":"base n. 基础","exampleEN":"The literacy programme teaches basic reading and writing skills to adults.","exampleCN":"这个扫盲计划向成年人教授基本的读写技能。","extra":""},{"chapter":5,"key":"5:278","id":278,"word":"fundamental","phonetic":"/ˌfʌndəˈmentəl/","pos":"adj.","meaningCN":"基础的，基本的；根本的","tag":"核心","root":"","exampleEN":"Understanding the fundamental concepts of physics is necessary before tackling advanced topics.","exampleCN":"在攻克高深课题之前，理解物理学的基本概念是必要的。","extra":""},{"chapter":5,"key":"5:279","id":279,"word":"elementary","phonetic":"/ˌelɪˈmentəri/","pos":"adj.","meaningCN":"基本的；初级的","tag":"高频","root":"","exampleEN":"The book covers elementary principles of biology suitable for beginners.","exampleCN":"这本书涵盖了适合初学者的生物学基本概念。","extra":""},{"chapter":5,"key":"5:280","id":280,"word":"profound","phonetic":"/prəˈfaʊnd/","pos":"adj.","meaningCN":"（影响）深刻的，深远的；见解深刻的","tag":"高频","root":"","exampleEN":"The lecture had a profound impact on how students viewed environmental issues.","exampleCN":"这场讲座对学生看待环境问题的方式产生了深远的影响。","extra":""},{"chapter":5,"key":"5:281","id":281,"word":"superficial","phonetic":"/ˌsuːpəˈfɪʃəl/","pos":"adj.","meaningCN":"表面的，外表的；肤浅的","tag":"高频","root":"","exampleEN":"A superficial reading of the text will not prepare you for the detailed exam questions.","exampleCN":"肤浅地阅读课文无法使你应对考试中的详细问题。","extra":""},{"chapter":5,"key":"5:282","id":282,"word":"surface","phonetic":"/ˈsɜːfɪs/","pos":"n.","meaningCN":"表面；地面；水面","tag":"核心","root":"sur（在上）+ face（脸）→ 表面","exampleEN":"On the surface, the problem seemed simple, but it was actually quite complex.","exampleCN":"表面上看，这个问题很简单，但实际上相当复杂。","extra":""},{"chapter":5,"key":"5:283","id":283,"word":"compulsory","phonetic":"/kəmˈpʌlsəri/","pos":"adj.","meaningCN":"强制的","tag":"核心","root":"","exampleEN":"Physical education is a compulsory subject for all first-year students.","exampleCN":"体育是所有一年级学生的必修科目。","extra":"搭配：compulsory education 义务教育。"},{"chapter":5,"key":"5:284","id":284,"word":"prerequisite","phonetic":"/ˌpriːˈrekwɪzɪt/","pos":"n.","meaningCN":"必备条件 adj. 必备的","tag":"低频","root":"requisite adj. 必要的","exampleEN":"A foundational course in statistics is a prerequisite for the advanced research methods class.","exampleCN":"基础统计学课程是高级研究方法课的必备条件。","extra":""},{"chapter":5,"key":"5:285","id":285,"word":"selective","phonetic":"/sɪˈlektɪv/","pos":"adj.","meaningCN":"选择性的","tag":"高频","root":"select v. 选择","exampleEN":"The university has a highly selective admission process, accepting only the top applicants.","exampleCN":"这所大学的录取过程非常挑剔，只接受最优秀的申请者。","extra":""},{"chapter":5,"key":"5:286","id":286,"word":"elective","phonetic":"/ɪˈlektɪv/","pos":"adj.","meaningCN":"选举的；[美]选修的 n. [美]选修科目","tag":"低频","root":"","exampleEN":"Students can choose an elective module from a wide range of subjects.","exampleCN":"学生可以从广泛的科目中选择一个选修模块。","extra":""},{"chapter":5,"key":"5:287","id":287,"word":"assignment","phonetic":"/əˈsaɪnmənt/","pos":"n.","meaningCN":"（布置的）作业；（分派的）任务","tag":"核心","root":"","exampleEN":"The teacher gave the class a reading assignment to complete over the weekend.","exampleCN":"老师给学生布置了一项周末完成的阅读作业。","extra":""},{"chapter":5,"key":"5:288","id":288,"word":"submit","phonetic":"/səbˈmɪt/","pos":"v.","meaningCN":"服从；提交，呈递","tag":"核心","root":"","exampleEN":"All students must submit their final essays before the end of the term.","exampleCN":"所有学生必须在学期结束前提交期末论文。","extra":"搭配：submit to 服从于。"},{"chapter":5,"key":"5:289","id":289,"word":"preview","phonetic":"/ˈpriːvjuː/","pos":"n./v.","meaningCN":"预习","tag":"高频","root":"","exampleEN":"It is helpful to preview the textbook chapter before attending the lecture.","exampleCN":"在听课前预习教材的章节是有帮助的。","extra":""},{"chapter":5,"key":"5:290","id":290,"word":"review","phonetic":"/rɪˈvjuː/","pos":"n./v.","meaningCN":"回顾；复习","tag":"核心","root":"","exampleEN":"She set aside an hour each evening to review her lecture notes.","exampleCN":"她每晚留出一小时复习课堂笔记。","extra":""},{"chapter":5,"key":"5:291","id":291,"word":"revise","phonetic":"/rɪˈvaɪz/","pos":"v.","meaningCN":"修订，修改","tag":"核心","root":"revision n. 修订，修改","exampleEN":"After receiving feedback, the student revised her essay and improved the argument.","exampleCN":"收到反馈后，学生修改了论文并完善了论点。","extra":""},{"chapter":5,"key":"5:292","id":292,"word":"inspect","phonetic":"/ɪnˈspekt/","pos":"v.","meaningCN":"检查；检阅，视察","tag":"高频","root":"inspection n. 检查","exampleEN":"The health and safety officer visited the school to inspect the science laboratories.","exampleCN":"健康安全官员来到学校检查科学实验室。","extra":""},{"chapter":5,"key":"5:293","id":293,"word":"consult","phonetic":"/kənˈsʌlt/","pos":"v.","meaningCN":"请教；查阅","tag":"核心","root":"","exampleEN":"If you are unsure about the topic, you should consult your professor during office hours.","exampleCN":"如果对主题不确定，你应该在办公时间请教教授。","extra":""},{"chapter":5,"key":"5:294","id":294,"word":"skim","phonetic":"/skɪm/","pos":"v.","meaningCN":"掠过，擦过；略读","tag":"核心","root":"","exampleEN":"Before a detailed study, skim the chapter to get a general idea of the content.","exampleCN":"在详细学习之前，略读一下章节以了解内容大意。","extra":""},{"chapter":5,"key":"5:295","id":295,"word":"scan","phonetic":"/skæn/","pos":"v.","meaningCN":"细看；浏览；扫描 n. 扫描检查；浏览","tag":"核心","root":"scanner n. 扫描仪","exampleEN":"She scanned the library shelves quickly, looking for a book on modern art.","exampleCN":"她快速扫视图书馆书架，寻找一本关于现代艺术的书。","extra":""},{"chapter":5,"key":"5:296","id":296,"word":"scrutinise","phonetic":"/ˈskruːtɪnaɪz/","pos":"v.","meaningCN":"详细检查，仔细查看","tag":"低频","root":"scrutiny n. 详细审查","exampleEN":"The examiner scrutinised the student's work to look for any signs of plagiarism.","exampleCN":"考官仔细检查学生的作业，寻找任何抄袭的痕迹。","extra":""},{"chapter":5,"key":"5:297","id":297,"word":"recite","phonetic":"/rɪˈsaɪt/","pos":"v.","meaningCN":"背诵，朗诵","tag":"低频","root":"recitation n. 背诵","exampleEN":"The language teacher asked each student to recite a short poem from memory.","exampleCN":"语言老师让每个学生背诵一首短诗。","extra":""},{"chapter":5,"key":"5:298","id":298,"word":"dictate","phonetic":"/dɪkˈteɪt/","pos":"v.","meaningCN":"让（某人）听写；命令，强行规定","tag":"低频","root":"dict 指“说”，如：diction（措辞），dictionary（字典），predict（预言）","exampleEN":"The professor dictated the key points of the lecture while students took notes.","exampleCN":"教授口述讲座要点，学生们做笔记。","extra":"名词 dictation 听写。"},{"chapter":5,"key":"5:299","id":299,"word":"examination","phonetic":"/ɪɡˌzæmɪˈneɪʃən/","pos":"n.","meaningCN":"考试；细查","tag":"核心","root":"","exampleEN":"The final examination will cover all the topics from the entire semester.","exampleCN":"期末考试将涵盖整个学期的所有主题。","extra":"简称 exam。"},{"chapter":5,"key":"5:300","id":300,"word":"test","phonetic":"/test/","pos":"n./v.","meaningCN":"试验，检验","tag":"核心","root":"tester n. 测试者","exampleEN":"The teacher will test the students on their vocabulary at the end of each unit.","exampleCN":"老师将在每个单元结束时测验学生的词汇。","extra":""},{"chapter":5,"key":"5:301","id":301,"word":"quiz","phonetic":"/kwɪz/","pos":"n.","meaningCN":"智力竞赛；小测验","tag":"高频","root":"","exampleEN":"The pop quiz helped the teacher check whether students had done the reading.","exampleCN":"突击小测验帮助老师检查学生是否完成了阅读。","extra":""},{"chapter":5,"key":"5:302","id":302,"word":"presentation","phonetic":"/ˌprezənˈteɪʃən/","pos":"n.","meaningCN":"陈述；表演，演出","tag":"核心","root":"present v. 呈现","exampleEN":"Each group will give a short presentation on their research findings.","exampleCN":"每个小组将就其研究结果做一个简短的陈述。","extra":"搭配：give a presentation 做展示。"},{"chapter":5,"key":"5:303","id":303,"word":"plagiarise","phonetic":"/ˈpleɪdʒəraɪz/","pos":"v.","meaningCN":"抄袭","tag":"高频","root":"","exampleEN":"Students must be careful not to plagiarise when writing their essays.","exampleCN":"学生在写论文时必须小心避免抄袭。","extra":""},{"chapter":5,"key":"5:304","id":304,"word":"copy","phonetic":"/ˈkɒpi/","pos":"n.","meaningCN":"复制品 v. 抄写；复制","tag":"核心","root":"","exampleEN":"Please make a copy of your assignment before handing in the original.","exampleCN":"在交原件之前，请把你作业复印一份。","extra":""},{"chapter":5,"key":"5:305","id":305,"word":"print","phonetic":"/prɪnt/","pos":"v.","meaningCN":"打印 n. 印刷品；（冲印出来的）照片","tag":"核心","root":"printer n. 打印机","exampleEN":"Remember to print your boarding pass before heading to the airport.","exampleCN":"去机场前记得打印登机牌。","extra":""},{"chapter":5,"key":"5:306","id":306,"word":"thesis","phonetic":"/ˈθiːsɪs/","pos":"n.","meaningCN":"论文","tag":"高频","root":"","exampleEN":"She is currently writing her master's thesis on climate change policy.","exampleCN":"她目前正在撰写关于气候变化政策的硕士论文。","extra":"复数 theses。"},{"chapter":5,"key":"5:307","id":307,"word":"essay","phonetic":"/ˈeseɪ/","pos":"n.","meaningCN":"（学生为某门课程写的）短文，论说文；（关于政治、社会等的）小品文","tag":"核心","root":"","exampleEN":"The exam will include a short essay question on the topic of sustainability.","exampleCN":"考试将包括一道关于可持续发展主题的短文题。","extra":""},{"chapter":5,"key":"5:308","id":308,"word":"paper","phonetic":"/ˈpeɪpə/","pos":"n.","meaningCN":"论文；纸","tag":"核心","root":"","exampleEN":"He presented his research paper at an international education conference.","exampleCN":"他在一次国际教育会议上宣读了自己的研究论文。","extra":""},{"chapter":5,"key":"5:309","id":309,"word":"dissertation","phonetic":"/ˌdɪsəˈteɪʃən/","pos":"n.","meaningCN":"专题论文；（尤指）学位论文","tag":"低频","root":"","exampleEN":"Writing a dissertation requires months of independent research and regular meetings with a supervisor.","exampleCN":"撰写学位论文需要数月独立研究并定期与导师会面。","extra":""},{"chapter":5,"key":"5:310","id":310,"word":"project","phonetic":"/ˈprɒdʒekt/","pos":"n.","meaningCN":"（大中学学生的）专题研究；项目，方案","tag":"核心","root":"overhead projector n. 投影仪","exampleEN":"The science project involved building a small wind turbine and testing its efficiency.","exampleCN":"这个科学项目包括建造一台小型风力涡轮机并测试其效率。","extra":""},{"chapter":5,"key":"5:311","id":311,"word":"heading","phonetic":"/ˈhedɪŋ/","pos":"n.","meaningCN":"标题；主题","tag":"低频","root":"","exampleEN":"Each section of the report should have a clear heading.","exampleCN":"报告的每个部分都应有一个清晰的标题。","extra":""},{"chapter":5,"key":"5:312","id":312,"word":"outset","phonetic":"/ˈaʊtset/","pos":"n.","meaningCN":"开端，开始","tag":"低频","root":"","exampleEN":"It is important to set clear research questions at the outset of a project.","exampleCN":"项目一开始就提出明确的研究问题很重要。","extra":""},{"chapter":5,"key":"5:313","id":313,"word":"outline","phonetic":"/ˈaʊtlaɪn/","pos":"n.","meaningCN":"概要；轮廓，略图","tag":"高频","root":"","exampleEN":"Before writing the essay, she prepared a detailed outline of her arguments.","exampleCN":"在写文章之前，她准备了一份详尽的论点提纲。","extra":""},{"chapter":5,"key":"5:314","id":314,"word":"point","phonetic":"/pɔɪnt/","pos":"n.","meaningCN":"点；要点","tag":"核心","root":"","exampleEN":"The most important point in the lecture was that practice is essential for language learning.","exampleCN":"讲座最重要的一点是，练习对语言学习至关重要。","extra":"搭配：a point of view 观点。"},{"chapter":5,"key":"5:315","id":315,"word":"gist","phonetic":"/dʒɪst/","pos":"n.","meaningCN":"主旨，要点","tag":"低频","root":"","exampleEN":"I did not catch every word, but I got the gist of the professor's argument.","exampleCN":"我没有听清每个词，但我明白了教授论点的要旨。","extra":""},{"chapter":5,"key":"5:316","id":316,"word":"opinion","phonetic":"/əˈpɪnjən/","pos":"n.","meaningCN":"看法；评价","tag":"核心","root":"","exampleEN":"The students were encouraged to express their own opinions during the debate.","exampleCN":"辩论中鼓励学生表达自己的观点。","extra":""},{"chapter":5,"key":"5:317","id":317,"word":"introduce","phonetic":"/ˌɪntrəˈdjuːs/","pos":"v.","meaningCN":"介绍；引进","tag":"核心","root":"introduction n. 介绍；引进","exampleEN":"The first lecture will introduce the main themes of the course.","exampleCN":"第一堂课将介绍课程的主要主题。","extra":""},{"chapter":5,"key":"5:318","id":318,"word":"reference","phonetic":"/ˈrefərəns/","pos":"n.","meaningCN":"参考；推荐函；提及，涉及","tag":"核心","root":"","exampleEN":"Check the reference list at the back of the book for further reading suggestions.","exampleCN":"查阅书末的参考文献列表以获取进一步阅读的建议。","extra":""},{"chapter":5,"key":"5:319","id":319,"word":"cite","phonetic":"/saɪt/","pos":"v.","meaningCN":"引用","tag":"高频","root":"","exampleEN":"When you use another person's ideas, you must cite the source correctly.","exampleCN":"当你使用他人的观点时，必须正确引用出处。","extra":""},{"chapter":5,"key":"5:320","id":320,"word":"elicit","phonetic":"/ɪˈlɪsɪt/","pos":"v.","meaningCN":"引出；探出，套出","tag":"低频","root":"","exampleEN":"The teacher's open-ended questions helped elicit thoughtful responses from the class.","exampleCN":"老师开放性的提问帮助引出了全班深思熟虑的回答。","extra":""},{"chapter":5,"key":"5:321","id":321,"word":"quote","phonetic":"/kwəʊt/","pos":"v.","meaningCN":"引用，引述；报（价）","tag":"核心","root":"quotation n. 引用语","exampleEN":"She quoted a famous scientist to support her argument in the essay.","exampleCN":"她在文章中引用了一位著名科学家的话来支持自己的论点。","extra":""},{"chapter":5,"key":"5:322","id":322,"word":"extract","phonetic":"/ˈekstrækt/","pos":"n.","meaningCN":"摘录","tag":"低频","root":"ex（向外）+ tract（拉）→ 抽出来的一块 → 摘录","exampleEN":"The handout included an extract from a leading textbook on the subject.","exampleCN":"讲义中包括了一流教科书上关于该主题的摘录。","extra":""},{"chapter":5,"key":"5:323","id":323,"word":"abstract","phonetic":"/ˈæbstrækt/","pos":"n.","meaningCN":"摘要 adj. 抽象的","tag":"高频","root":"","exampleEN":"The abstract of the paper summarises the research aims, methods, and conclusions.","exampleCN":"论文摘要概括了研究目的、方法和结论。","extra":"动词读 /æbˈstrækt/ 提取。"},{"chapter":5,"key":"5:324","id":324,"word":"summary","phonetic":"/ˈsʌməri/","pos":"n.","meaningCN":"摘要，概要","tag":"核心","root":"","exampleEN":"At the end of each chapter, there is a summary of the key concepts covered.","exampleCN":"每章末尾有涵盖的主要概念的摘要。","extra":"搭配：in summary 总之。"},{"chapter":5,"key":"5:325","id":325,"word":"assume","phonetic":"/əˈsjuːm/","pos":"v.","meaningCN":"假定，设想；承担（责任）；取得（权力）","tag":"核心","root":"assumption n. 假设","exampleEN":"Many students wrongly assume that speed reading means understanding less.","exampleCN":"许多学生错误地认为快速阅读意味着理解得更少。","extra":""},{"chapter":5,"key":"5:326","id":326,"word":"presume","phonetic":"/prɪˈzjuːm/","pos":"v.","meaningCN":"假定，假设；料想","tag":"低频","root":"","exampleEN":"I presume you have done the reading, since you raised such a detailed question.","exampleCN":"我料想你已读过材料，因为你提了如此详细的问题。","extra":""},{"chapter":5,"key":"5:327","id":327,"word":"suppose","phonetic":"/səˈpəʊz/","pos":"v.","meaningCN":"假定；认为","tag":"核心","root":"","exampleEN":"Suppose you only had one hour to study—what would you focus on first?","exampleCN":"假设你只有一个小时学习——你会首先关注什么？","extra":"搭配：be supposed to 应该。"},{"chapter":5,"key":"5:328","id":328,"word":"hypothesis","phonetic":"/haɪˈpɒθəsɪs/","pos":"n.","meaningCN":"假说，假设","tag":"高频","root":"","exampleEN":"The students formulated a hypothesis about the effect of music on concentration.","exampleCN":"学生们提出了一个关于音乐对注意力影响的假说。","extra":"复数 hypotheses。"},{"chapter":5,"key":"5:329","id":329,"word":"postulate","phonetic":"/ˈpɒstjʊleɪt/","pos":"v.","meaningCN":"假定，假设","tag":"识记","root":"","exampleEN":"The theory postulates that language ability is partly innate.","exampleCN":"该理论假定语言能力在某种程度上是与生俱来的。","extra":""},{"chapter":5,"key":"5:330","id":330,"word":"speculate","phonetic":"/ˈspekjʊleɪt/","pos":"v.","meaningCN":"推测","tag":"高频","root":"","exampleEN":"Without enough data, scientists can only speculate about the cause of the phenomenon.","exampleCN":"没有足够的数据，科学家只能推测这一现象的原因。","extra":""},{"chapter":5,"key":"5:331","id":331,"word":"predict","phonetic":"/prɪˈdɪkt/","pos":"v.","meaningCN":"预测","tag":"核心","root":"prediction n. 预测","exampleEN":"It is difficult to predict which students will adapt best to online learning.","exampleCN":"很难预测哪些学生最能适应在线学习。","extra":""},{"chapter":5,"key":"5:332","id":332,"word":"perceive","phonetic":"/pəˈsiːv/","pos":"v.","meaningCN":"感知，察觉，意识到","tag":"高频","root":"","exampleEN":"Students often perceive group work as an opportunity to share ideas.","exampleCN":"学生常常将小组合作视为交流想法的机会。","extra":""},{"chapter":5,"key":"5:333","id":333,"word":"detect","phonetic":"/dɪˈtekt/","pos":"v.","meaningCN":"察觉，发觉；侦察出","tag":"高频","root":"","exampleEN":"The software can detect plagiarism by comparing essays with online sources.","exampleCN":"该软件可以通过与在线资源比对来发现抄袭。","extra":""},{"chapter":5,"key":"5:334","id":334,"word":"discern","phonetic":"/dɪˈsɜːn/","pos":"v.","meaningCN":"觉察出；分辨出","tag":"低频","root":"discernible adj. 可辨别的","exampleEN":"In the noisy classroom, it was difficult to discern the teacher's instructions.","exampleCN":"在嘈杂的教室里，很难听清老师的指示。","extra":""},{"chapter":5,"key":"5:335","id":335,"word":"recognise","phonetic":"/ˈrekəɡnaɪz/","pos":"v.","meaningCN":"认识，辨认出","tag":"核心","root":"recognition n. 认出","exampleEN":"It is important to recognise that each student learns at a different pace.","exampleCN":"认识到每个学生的学习进度不同是很重要的。","extra":""},{"chapter":5,"key":"5:336","id":336,"word":"conscious","phonetic":"/ˈkɒnʃəs/","pos":"adj.","meaningCN":"意识到的；有知觉的","tag":"高频","root":"consciousness n. 意识","exampleEN":"Teachers need to be conscious of the different learning needs in their classroom.","exampleCN":"教师需要意识到班级里不同的学习需求。","extra":"搭配：be conscious of 知道。"},{"chapter":5,"key":"5:337","id":337,"word":"reckon","phonetic":"/ˈrekən/","pos":"v.","meaningCN":"估计；期望；认为","tag":"低频","root":"","exampleEN":"I reckon that regular breaks during study sessions actually improve focus.","exampleCN":"我认为学习过程中定时休息实际上能提高注意力。","extra":""},{"chapter":5,"key":"5:338","id":338,"word":"deem","phonetic":"/diːm/","pos":"v.","meaningCN":"认为，相信","tag":"低频","root":"","exampleEN":"The university deemed it necessary to update its digital library system.","exampleCN":"大学认为有必要升级数字图书馆系统。","extra":""},{"chapter":5,"key":"5:339","id":339,"word":"imply","phonetic":"/ɪmˈplaɪ/","pos":"v.","meaningCN":"暗指，意味着","tag":"核心","root":"implication n. 含意","exampleEN":"A high attendance rate usually implies that students are engaged and motivated.","exampleCN":"高出勤率通常意味着学生积极参与且积极性高。","extra":""},{"chapter":5,"key":"5:340","id":340,"word":"deliberate","phonetic":"/dɪˈlɪbərət/","pos":"adj.","meaningCN":"审慎的","tag":"低频","root":"","exampleEN":"After deliberate consideration, she chose to pursue further studies abroad.","exampleCN":"经过深思熟虑后，她选择出国深造。","extra":"动词读 /dɪˈlɪbəreɪt/。"},{"chapter":5,"key":"5:341","id":341,"word":"represent","phonetic":"/ˌreprɪˈzent/","pos":"v.","meaningCN":"代表；象征","tag":"核心","root":"representative n. 代表","exampleEN":"The student council represents the interests of the entire student body.","exampleCN":"学生会代表全体学生的利益。","extra":""},{"chapter":5,"key":"5:342","id":342,"word":"insist","phonetic":"/ɪnˈsɪst/","pos":"v.","meaningCN":"坚持，坚决认为（或主张、要求）","tag":"核心","root":"","exampleEN":"The professor insisted on clear referencing in every assignment.","exampleCN":"教授坚持每份作业都要有清晰的文献引用。","extra":"搭配：insist on 坚持。"},{"chapter":5,"key":"5:343","id":343,"word":"persist","phonetic":"/pəˈsɪst/","pos":"v.","meaningCN":"坚持不懈；持续存在","tag":"高频","root":"sist 指“站”，如：insist（坚持），superstition（迷信）","exampleEN":"If you persist with daily practice, your language skills will improve dramatically.","exampleCN":"如果你坚持每天练习，语言技能将大大提高。","extra":"搭配：persist in doing sth. 坚持做某事。"},{"chapter":5,"key":"5:344","id":344,"word":"infer","phonetic":"/ɪnˈfɜː/","pos":"v.","meaningCN":"推断，推理","tag":"高频","root":"inference n. 推理","exampleEN":"From the test results, we can infer that the new teaching method is effective.","exampleCN":"从测试结果我们可以推断，新教学方法是有效的。","extra":""},{"chapter":5,"key":"5:345","id":345,"word":"understand","phonetic":"/ˌʌndəˈstænd/","pos":"v.","meaningCN":"懂得，理解","tag":"核心","root":"understanding n. 理解","exampleEN":"To understand complex concepts, it is helpful to break them down into simpler parts.","exampleCN":"要理解复杂概念，将其分解为更简单的部分是有帮助的。","extra":""},{"chapter":5,"key":"5:346","id":346,"word":"comprehend","phonetic":"/ˌkɒmprɪˈhend/","pos":"v.","meaningCN":"理解，领悟","tag":"高频","root":"comprehension n. 理解（力）","exampleEN":"Some students find it difficult to comprehend dense academic texts without guidance.","exampleCN":"一些学生发现没有指导很难理解密集的学术文本。","extra":""},{"chapter":5,"key":"5:347","id":347,"word":"analyse","phonetic":"/ˈænəlaɪz/","pos":"v.","meaningCN":"分析","tag":"核心","root":"analysis n. 分析","exampleEN":"The assignment requires students to analyse a scientific article and discuss its strengths.","exampleCN":"作业要求学生分析一篇科学文章并讨论其优点。","extra":""},{"chapter":5,"key":"5:348","id":348,"word":"diagnose","phonetic":"/ˈdaɪəɡnəʊz/","pos":"v.","meaningCN":"判断；诊断","tag":"低频","root":"gno 表示“认识”","exampleEN":"Teachers sometimes use informal tests to diagnose students' strengths and weaknesses.","exampleCN":"教师有时使用非正式测验来诊断学生的强项和弱点。","extra":""},{"chapter":5,"key":"5:349","id":349,"word":"deduce","phonetic":"/dɪˈdjuːs/","pos":"v.","meaningCN":"演绎，推论","tag":"低频","root":"de（向下）+ duce（引导）→ 向下引导 → 演绎，推论","exampleEN":"From the observations, we can deduce that plants grow faster under this light.","exampleCN":"根据观察，我们可以推断植物在这种光照下生长更快。","extra":""},{"chapter":5,"key":"5:350","id":350,"word":"conclude","phonetic":"/kənˈkluːd/","pos":"v.","meaningCN":"推断出，得出结论；（使）结束","tag":"核心","root":"conclusion n. 结论","exampleEN":"After reviewing the evidence, the researchers concluded that exercise improves memory.","exampleCN":"回顾证据后，研究人员得出结论：锻炼改善记忆力。","extra":""},{"chapter":5,"key":"5:351","id":351,"word":"analogy","phonetic":"/əˈnælədʒi/","pos":"n.","meaningCN":"类比；类推","tag":"低频","root":"analogous adj. 类似的","exampleEN":"The teacher used the analogy of a sponge to explain how children absorb knowledge.","exampleCN":"老师用海绵的类比来解释孩子如何吸收知识。","extra":"搭配：by analogy 通过类推法。"},{"chapter":5,"key":"5:352","id":352,"word":"compare","phonetic":"/kəmˈpeə/","pos":"v.","meaningCN":"比较；把......比作；比得上","tag":"核心","root":"comparison n. 比较","exampleEN":"The essay asked students to compare two different approaches to early childhood education.","exampleCN":"文章要求学生比较两种不同的幼儿教育方法。","extra":"搭配：compare A with B 比较。"},{"chapter":5,"key":"5:353","id":353,"word":"contrast","phonetic":"/ˈkɒntrɑːst/","pos":"n.","meaningCN":"对比；明显的差异","tag":"核心","root":"","exampleEN":"The contrast between active learning and passive listening is striking in terms of student outcomes.","exampleCN":"主动学习与被动听课在学生学习效果上的差异是显著的。","extra":""},{"chapter":5,"key":"5:354","id":354,"word":"overlap","phonetic":"/ˌəʊvəˈlæp/","pos":"v.","meaningCN":"与......重叠；与......部分相同","tag":"高频","root":"","exampleEN":"The content of the two courses overlaps, so some students take both for a deeper understanding.","exampleCN":"两门课的内容重叠，所以一些学生两门都修以求更深理解。","extra":""},{"chapter":5,"key":"5:355","id":355,"word":"contradiction","phonetic":"/ˌkɒntrəˈdɪkʃən/","pos":"n.","meaningCN":"矛盾，不一致；反驳","tag":"高频","root":"","exampleEN":"The student quickly spotted a contradiction in the textbook's explanation.","exampleCN":"学生很快发现了教科书解释中的矛盾。","extra":""},{"chapter":5,"key":"5:356","id":356,"word":"disagree","phonetic":"/ˌdɪsəˈɡriː/","pos":"v.","meaningCN":"有分歧；不同意","tag":"核心","root":"agree v. 同意","exampleEN":"It is fine to disagree with the author, as long as you support your view with evidence.","exampleCN":"不同意作者的观点没关系，只要你用证据支持自己的观点。","extra":"搭配：disagree with 不同意。"},{"chapter":5,"key":"5:357","id":357,"word":"differ","phonetic":"/ˈdɪfə/","pos":"v.","meaningCN":"不同，相异","tag":"核心","root":"difference n. 差别","exampleEN":"Learning styles can differ greatly from one student to another.","exampleCN":"学习风格因人而异，差别可能很大。","extra":"搭配：differ from 与......不同。"},{"chapter":5,"key":"5:358","id":358,"word":"diverse","phonetic":"/daɪˈvɜːs/","pos":"adj.","meaningCN":"不一样的，多种多样的","tag":"核心","root":"diversity n. 多样性","exampleEN":"A diverse student body brings a wide range of perspectives to classroom discussions.","exampleCN":"多元化的学生群体为课堂讨论带来了广泛的观点。","extra":""},{"chapter":5,"key":"5:359","id":359,"word":"nuance","phonetic":"/ˈnjuːɑːns/","pos":"n.","meaningCN":"细微差别","tag":"低频","root":"","exampleEN":"Advanced language learners must learn to recognise the nuances of word meanings.","exampleCN":"高级语言学习者必须学会识别词义的细微差别。","extra":""},{"chapter":5,"key":"5:360","id":360,"word":"inductive","phonetic":"/ɪnˈdʌktɪv/","pos":"adj.","meaningCN":"归纳的；诱导的","tag":"识记","root":"induce v. 引起","exampleEN":"In science lessons, students often use inductive reasoning to form general rules from examples.","exampleCN":"在科学课上，学生经常使用归纳推理从例子中形成一般规律。","extra":""},{"chapter":5,"key":"5:361","id":361,"word":"detail","phonetic":"/ˈdiːteɪl/","pos":"n.","meaningCN":"细节；（画等的）细部","tag":"核心","root":"detailed adj. 详细的","exampleEN":"The instructor explained the experiment procedure in great detail before the lab session.","exampleCN":"老师在实验课前非常详细地解释了实验步骤。","extra":"搭配：in detail 详细地。"},{"chapter":5,"key":"5:362","id":362,"word":"thorough","phonetic":"/ˈθʌrə/","pos":"adj.","meaningCN":"彻底的，详尽的","tag":"核心","root":"","exampleEN":"A thorough review of lecture notes each week can significantly reduce exam stress.","exampleCN":"每周彻底复习课堂笔记可以显著减轻考试压力。","extra":""},{"chapter":5,"key":"5:363","id":363,"word":"example","phonetic":"/ɪɡˈzɑːmpəl/","pos":"n.","meaningCN":"例子；榜样","tag":"核心","root":"exemplify v. 举例说明","exampleEN":"The teacher gave several clear examples to help students understand the complex theory.","exampleCN":"老师举了几个清晰的例子来帮助学生理解这一复杂理论。","extra":"搭配：for example 例如。"},{"chapter":5,"key":"5:364","id":364,"word":"instance","phonetic":"/ˈɪnstəns/","pos":"n.","meaningCN":"实例；情况，场合","tag":"核心","root":"","exampleEN":"China, for instance, has made great progress in promoting higher education in rural areas.","exampleCN":"例如，中国在推动农村地区高等教育方面取得了巨大进步。","extra":"搭配：for instance 例如。"},{"chapter":5,"key":"5:365","id":365,"word":"confirm","phonetic":"/kənˈfɜːm/","pos":"v.","meaningCN":"证实；确保，巩固","tag":"核心","root":"","exampleEN":"The latest data confirmed that the new tutoring programme was beneficial for students.","exampleCN":"最新数据证实，新的辅导项目对学生是有益的。","extra":""},{"chapter":5,"key":"5:366","id":366,"word":"demonstrate","phonetic":"/ˈdemənstreɪt/","pos":"v.","meaningCN":"示范，演示；证明","tag":"核心","root":"monstr 指“展示”","exampleEN":"The instructor demonstrated how to use the microscope step by step.","exampleCN":"老师在一步步演示如何使用显微镜。","extra":""},{"chapter":5,"key":"5:367","id":367,"word":"survey","phonetic":"/ˈsɜːveɪ/","pos":"n.","meaningCN":"民意调查","tag":"核心","root":"","exampleEN":"A survey of high school students revealed that many feel anxious about final exams.","exampleCN":"对高中生的调查显示，许多人对期末考试感到焦虑。","extra":"动词读 /sɜːˈveɪ/。"},{"chapter":5,"key":"5:368","id":368,"word":"illustrate","phonetic":"/ˈɪləstreɪt/","pos":"v.","meaningCN":"[用图等]说明；给（书）加插图（或图表）","tag":"高频","root":"","exampleEN":"The teacher illustrated the water cycle with a large colourful diagram.","exampleCN":"老师用一幅彩色大图说明了水循环。","extra":""},{"chapter":5,"key":"5:369","id":369,"word":"manifest","phonetic":"/ˈmænɪfest/","pos":"v.","meaningCN":"显示，表明","tag":"低频","root":"","exampleEN":"A student's interest in a subject often manifests as active participation in class.","exampleCN":"学生对一门学科的兴趣常表现为积极参与课堂。","extra":""},{"chapter":5,"key":"5:370","id":370,"word":"prove","phonetic":"/pruːv/","pos":"v.","meaningCN":"证明；结果是","tag":"核心","root":"","exampleEN":"These results prove that consistent effort is more important than talent alone.","exampleCN":"这些结果证明，持续的努力比单纯的天赋更重要。","extra":""},{"chapter":5,"key":"5:371","id":371,"word":"determine","phonetic":"/dɪˈtɜːmɪn/","pos":"v.","meaningCN":"决定；下定决心；查明","tag":"核心","root":"determined adj. 下定决心的","exampleEN":"The education board determined that additional funding was necessary for science labs.","exampleCN":"教育委员会认为，科学实验室需要增加拨款。","extra":"搭配：determine to do sth. 决心做某事。"},{"chapter":5,"key":"5:372","id":372,"word":"decide","phonetic":"/dɪˈsaɪd/","pos":"v.","meaningCN":"决定","tag":"核心","root":"decision n. 决定","exampleEN":"After visiting several campuses, she finally decided which university to attend.","exampleCN":"参观了几所校园后，她终于决定上哪所大学。","extra":""},{"chapter":5,"key":"5:373","id":373,"word":"resolve","phonetic":"/rɪˈzɒlv/","pos":"v.","meaningCN":"决心，决定；（使）分解为；解决","tag":"高频","root":"solv 指“松开”","exampleEN":"The student resolved to improve his grades by studying at least two hours every evening.","exampleCN":"这名学生下定决心提高成绩，每晚至少学习两小时。","extra":"名词 resolution 决心。"},{"chapter":5,"key":"5:374","id":374,"word":"research","phonetic":"/rɪˈsɜːtʃ/","pos":"n.","meaningCN":"调查；探索","tag":"核心","root":"researcher n. 调查者","exampleEN":"Extensive research has shown that early reading habits influence later academic success.","exampleCN":"广泛的研究表明，早期阅读习惯影响以后的学业成功。","extra":"搭配：do research 进行研究。"},{"chapter":5,"key":"5:375","id":375,"word":"observe","phonetic":"/əbˈzɜːv/","pos":"v.","meaningCN":"观察，观测；注意到","tag":"核心","root":"observation n. 观察","exampleEN":"During the experiment, students carefully observed the colour change in the solution.","exampleCN":"在实验中，学生仔细观察了溶液的颜色变化。","extra":""},{"chapter":5,"key":"5:376","id":376,"word":"inquire","phonetic":"/ɪnˈkwaɪə/","pos":"v.","meaningCN":"询问；调查","tag":"核心","root":"inquiry n. 询问；调查","exampleEN":"Several parents inquired about the school's new anti-bullying policy.","exampleCN":"几位家长询问了学校新的反欺凌政策。","extra":"搭配：inquire into 调查。"},{"chapter":5,"key":"5:377","id":377,"word":"query","phonetic":"/ˈkwɪəri/","pos":"n.","meaningCN":"疑问；询问 v. 怀疑；询问","tag":"低频","root":"","exampleEN":"If you have any queries about the assignment, please contact your tutor.","exampleCN":"如果你对作业有任何疑问，请联系导师。","extra":""},{"chapter":5,"key":"5:378","id":378,"word":"questionnaire","phonetic":"/ˌkwestʃəˈneə/","pos":"n.","meaningCN":"调查表，调查问卷","tag":"高频","root":"","exampleEN":"The students were asked to fill in a questionnaire about their learning habits.","exampleCN":"学生们被要求填写一份关于学习习惯的调查问卷。","extra":""},{"chapter":5,"key":"5:379","id":379,"word":"achieve","phonetic":"/əˈtʃiːv/","pos":"v.","meaningCN":"实现，达到","tag":"核心","root":"achievement n. 成就","exampleEN":"By setting small daily goals, you can gradually achieve large long-term objectives.","exampleCN":"通过设定小目标，你可以逐步实现远大的长期目标。","extra":"搭配：achieve success 取得成功。"},{"chapter":5,"key":"5:380","id":380,"word":"accomplish","phonetic":"/əˈkʌmplɪʃ/","pos":"v.","meaningCN":"达到（目的），完成","tag":"高频","root":"accomplishment n. 成就","exampleEN":"She accomplished her goal of learning basic conversational French in six months.","exampleCN":"她实现了在六个月内学会法语基础会话的目标。","extra":""},{"chapter":5,"key":"5:381","id":381,"word":"attain","phonetic":"/əˈteɪn/","pos":"v.","meaningCN":"获得；达到","tag":"高频","root":"attainment n. 达到","exampleEN":"He attained a high score on the language proficiency test after months of study.","exampleCN":"经过数月的学习，他在语言能力测试中取得了高分。","extra":"搭配：attain one's goal 达成目标。"},{"chapter":5,"key":"5:382","id":382,"word":"credit","phonetic":"/ˈkredɪt/","pos":"n.","meaningCN":"赊购；学分；信任","tag":"核心","root":"","exampleEN":"This module is worth 15 credits towards your degree.","exampleCN":"该模块可获得15个学分，计入学位。","extra":"搭配：a credit card 信用卡。"},{"chapter":5,"key":"5:383","id":383,"word":"grade","phonetic":"/ɡreɪd/","pos":"v.","meaningCN":"给......分等级 n. 等级；成绩等级","tag":"核心","root":"upgrade v. 使升级","exampleEN":"The teacher graded the essays based on clarity, structure, and evidence.","exampleCN":"老师根据清晰度、结构和论据给作文打分。","extra":""},{"chapter":5,"key":"5:384","id":384,"word":"rank","phonetic":"/ræŋk/","pos":"n.","meaningCN":"等级；排，列 v. 给......评级；位列","tag":"高频","root":"ranking n. 排名","exampleEN":"The university's education programme is ranked among the best in the country.","exampleCN":"该大学的教育项目名列全国前茅。","extra":""},{"chapter":5,"key":"5:385","id":385,"word":"row","phonetic":"/rəʊ/","pos":"n.","meaningCN":"（一）排，（一）行","tag":"低频","root":"","exampleEN":"The students sat in neat rows, waiting for the lecture to begin.","exampleCN":"学生们整齐地排排坐着，等待讲座开始。","extra":""},{"chapter":5,"key":"5:386","id":386,"word":"queue","phonetic":"/kjuː/","pos":"n.","meaningCN":"行列 v. 排队等候","tag":"低频","root":"","exampleEN":"A long queue formed outside the library as students waited to check out study rooms.","exampleCN":"图书馆外排起了长队，学生们等着签出自习室。","extra":""},{"chapter":5,"key":"5:387","id":387,"word":"score","phonetic":"/skɔː/","pos":"n.","meaningCN":"得分，成绩","tag":"核心","root":"","exampleEN":"After taking extra tuition, his test scores showed a noticeable improvement.","exampleCN":"补课之后，他的考试成绩有了明显提高。","extra":""},{"chapter":5,"key":"5:388","id":388,"word":"mark","phonetic":"/mɑːk/","pos":"n.","meaningCN":"分数；标记 v. 标志着；给......打分；在......上做记号","tag":"核心","root":"","exampleEN":"The examiners awarded high marks for clear reasoning and original analysis.","exampleCN":"考官对清晰的推理和新颖的分析给予高分。","extra":""},{"chapter":5,"key":"5:389","id":389,"word":"grant","phonetic":"/ɡrɑːnt/","pos":"v.","meaningCN":"授予；准予；承认","tag":"高频","root":"","exampleEN":"The university granted her a scholarship to cover the full tuition fee.","exampleCN":"大学授予她一项奖学金，用以支付全额学费。","extra":"搭配：take sth. for granted 视为理所当然。"},{"chapter":5,"key":"5:390","id":390,"word":"praise","phonetic":"/preɪz/","pos":"n.","meaningCN":"赞美 v. 赞扬","tag":"核心","root":"","exampleEN":"The teacher's praise motivated the students to work even harder on their next project.","exampleCN":"老师的赞扬激励学生在下一个项目上更加努力。","extra":"搭配：praise sb. for sth. 为某事赞扬某人。"},{"chapter":5,"key":"5:391","id":391,"word":"appreciate","phonetic":"/əˈpriːʃieɪt/","pos":"v.","meaningCN":"赏识；感激；意识到","tag":"核心","root":"","exampleEN":"Students should appreciate the feedback given by their teachers and use it to improve.","exampleCN":"学生应该重视老师的反馈，并利用它来进步。","extra":""},{"chapter":5,"key":"5:392","id":392,"word":"feedback","phonetic":"/ˈfiːdbæk/","pos":"n.","meaningCN":"反馈，反应","tag":"核心","root":"","exampleEN":"Detailed feedback on your assignments can help you understand your strengths and weaknesses.","exampleCN":"作业的详细反馈能帮助你了解自己的长处和不足。","extra":""},{"chapter":5,"key":"5:393","id":393,"word":"underestimate","phonetic":"/ˌʌndərˈestɪmeɪt/","pos":"v.","meaningCN":"低估","tag":"核心","root":"estimate v. 估算","exampleEN":"Never underestimate the power of consistent daily practice in language learning.","exampleCN":"永远不要低估语言学习中每日坚持练习的力量。","extra":""},{"chapter":5,"key":"5:394","id":394,"word":"overestimate","phonetic":"/ˌəʊvərˈestɪmeɪt/","pos":"v.","meaningCN":"高估","tag":"核心","root":"","exampleEN":"Students often overestimate how much they can learn in a single night before an exam.","exampleCN":"学生往往高估了自己在考前一晚能学会的内容。","extra":""},{"chapter":5,"key":"5:395","id":395,"word":"apply","phonetic":"/əˈplaɪ/","pos":"v.","meaningCN":"申请","tag":"核心","root":"","exampleEN":"She plans to apply to several top universities for her postgraduate studies.","exampleCN":"她计划申请几所顶尖大学进行研究生学习。","extra":"搭配：apply to sb. for sth. 向某人申请某物。"},{"chapter":5,"key":"5:396","id":396,"word":"fellowship","phonetic":"/ˈfeləʊʃɪp/","pos":"n.","meaningCN":"研究生奖学金","tag":"低频","root":"","exampleEN":"The fellowship allowed him to focus entirely on his doctoral research without financial worries.","exampleCN":"研究生奖学金使他能全心投入博士研究，不必担心经济问题。","extra":""},{"chapter":5,"key":"5:397","id":397,"word":"scholarship","phonetic":"/ˈskɒləʃɪp/","pos":"n.","meaningCN":"奖学金；学问，学识","tag":"核心","root":"","exampleEN":"Thanks to a generous scholarship, she could afford to study at a world-class institution.","exampleCN":"多亏了一项慷慨的奖学金，她得以负担在世界一流学府的学习。","extra":""},{"chapter":5,"key":"5:398","id":398,"word":"reward","phonetic":"/rɪˈwɔːd/","pos":"n.","meaningCN":"报答；赏金 v. 报答","tag":"高频","root":"","exampleEN":"Hard work in education brings its own reward in the form of knowledge and opportunity.","exampleCN":"教育上的努力会以知识和机会的形式得到回报。","extra":"搭配：reward sb. for sth. 为某事报答某人。"},{"chapter":5,"key":"5:399","id":399,"word":"award","phonetic":"/əˈwɔːd/","pos":"n.","meaningCN":"奖；奖品","tag":"核心","root":"","exampleEN":"He received an award for his outstanding performance in the university mathematics contest.","exampleCN":"他因在大学数学竞赛中的杰出表现而获奖。","extra":""},{"chapter":5,"key":"5:400","id":400,"word":"prize","phonetic":"/praɪz/","pos":"n.","meaningCN":"奖赏 v. 珍视","tag":"低频","root":"","exampleEN":"The school awards prizes each year to students who show the most improvement.","exampleCN":"学校每年向进步最大的学生颁发奖品。","extra":""},{"chapter":5,"key":"5:401","id":401,"word":"fee","phonetic":"/fiː/","pos":"n.","meaningCN":"酬金；费用","tag":"核心","root":"","exampleEN":"University tuition fees have risen steadily over the past decade.","exampleCN":"过去十年里，大学学费稳步上升。","extra":""}],"6":[{"chapter":6,"key":"6:1","id":1,"word":"reveal","phonetic":"/rɪˈviːl/","pos":"v.","meaningCN":"展现；显示，透露","tag":"核心","root":"","exampleEN":"The latest research reveals a strong link between sleep quality and academic performance.","exampleCN":"最新研究揭示了睡眠质量与学业表现之间的密切联系。","extra":""},{"chapter":6,"key":"6:2","id":2,"word":"uncover","phonetic":"/ʌnˈkʌvə/","pos":"v.","meaningCN":"揭露，发现","tag":"高频","root":"","exampleEN":"Investigative journalists worked tirelessly to uncover the truth behind the corruption scandal.","exampleCN":"调查记者不懈努力，揭露了腐败丑闻背后的真相。","extra":""},{"chapter":6,"key":"6:3","id":3,"word":"expose","phonetic":"/ɪkˈspəʊz/","pos":"v.","meaningCN":"使暴露；揭发，使曝光","tag":"核心","root":"","exampleEN":"The documentary exposed the harsh working conditions in some factories overseas.","exampleCN":"这部纪录片曝光了海外一些工厂的恶劣工作条件。","extra":"名词 exposure 暴露；揭露。"},{"chapter":6,"key":"6:4","id":4,"word":"domain","phonetic":"/dəˈmeɪn/","pos":"n.","meaningCN":"（活动、学问等的）领域；领土，领地","tag":"高频","root":"dom 意为“房子”，引申为“主人，领主”，同根词：domestic（国内的；家庭的），dominate（统治，控制），dominant（占优势的；主要的）","exampleEN":"With the rise of the internet, digital marketing has become a crucial domain for businesses.","exampleCN":"随着互联网的兴起，数字营销已成为企业的关键领域。","extra":""},{"chapter":6,"key":"6:5","id":5,"word":"field","phonetic":"/fiːld/","pos":"n.","meaningCN":"领域","tag":"核心","root":"","exampleEN":"She is a leading expert in the field of environmental science.","exampleCN":"她是环境科学领域的顶尖专家。","extra":""},{"chapter":6,"key":"6:6","id":6,"word":"realm","phonetic":"/relm/","pos":"n.","meaningCN":"领域","tag":"低频","root":"","exampleEN":"The discovery opened up new realms of possibility in medical research.","exampleCN":"这一发现为医学研究开辟了新的可能性领域。","extra":""},{"chapter":6,"key":"6:7","id":7,"word":"foundation","phonetic":"/faʊnˈdeɪʃən/","pos":"n.","meaningCN":"基础；地基；基金会","tag":"核心","root":"","exampleEN":"A solid foundation in mathematics is essential for studying physics and engineering.","exampleCN":"扎实的数学基础对于学习物理和工程学至关重要。","extra":"founder n. 奠基人，创建人；搭配：a foundation course 基础课程。"},{"chapter":6,"key":"6:8","id":8,"word":"specialise","phonetic":"/ˈspeʃəlaɪz/","pos":"v.","meaningCN":"专攻","tag":"高频","root":"","exampleEN":"Many students choose to specialise in a particular field during their postgraduate studies.","exampleCN":"许多学生在研究生阶段选择专攻某个特定领域。","extra":"搭配：specialise in 专攻，专门研究；专门经营。"},{"chapter":6,"key":"6:9","id":9,"word":"absorb","phonetic":"/əbˈsɜːb/","pos":"v.","meaningCN":"理解；掌握","tag":"核心","root":"ab（离开）+ sorb（吸收，吮吸）","exampleEN":"It takes time to absorb new information, so regular review is important.","exampleCN":"吸收新信息需要时间，因此定期复习很重要。","extra":""},{"chapter":6,"key":"6:10","id":10,"word":"concentrate","phonetic":"/ˈkɒnsəntreɪt/","pos":"v.","meaningCN":"集中（心思）；（使）浓缩","tag":"核心","root":"","exampleEN":"To finish the project on time, she had to concentrate all her efforts on it.","exampleCN":"为了按时完成项目，她必须全神贯注。","extra":"名词 concentration 专心；浓度；搭配：concentrate on 专心于。"},{"chapter":6,"key":"6:11","id":11,"word":"focus","phonetic":"/ˈfəʊkəs/","pos":"v.","meaningCN":"（把......）集中（于）n. 焦点","tag":"核心","root":"源自拉丁语 focus（壁炉），引申为“焦点”","exampleEN":"The discussion should focus on solutions rather than problems.","exampleCN":"讨论应该集中在解决方案上，而不是问题上。","extra":"搭配：focus on 集中于。"},{"chapter":6,"key":"6:12","id":12,"word":"utilise","phonetic":"/ˈjuːtəlaɪz/","pos":"v.","meaningCN":"利用","tag":"高频","root":"","exampleEN":"Teachers are encouraged to utilise technology to make lessons more engaging.","exampleCN":"鼓励教师利用技术使课程更有吸引力。","extra":"名词 utility 效用；utilisation 利用。"},{"chapter":6,"key":"6:13","id":13,"word":"usage","phonetic":"/ˈjuːsɪdʒ/","pos":"n.","meaningCN":"使用；（词语的）用法","tag":"低频","root":"","exampleEN":"The dictionary provides clear explanations of word meanings and usage.","exampleCN":"这本词典提供了清晰的词义和用法解释。","extra":""},{"chapter":6,"key":"6:14","id":14,"word":"tester","phonetic":"/ˈtestə/","pos":"n.","meaningCN":"测试仪；测试员","tag":"识记","root":"","exampleEN":"A software tester is responsible for finding and reporting bugs before a product is released.","exampleCN":"软件测试员负责在产品发布前发现并报告漏洞。","extra":""},{"chapter":6,"key":"6:15","id":15,"word":"apply","phonetic":"/əˈplaɪ/","pos":"v.","meaningCN":"应用；适用","tag":"核心","root":"","exampleEN":"The theories learned in class can be applied to solve real-world problems.","exampleCN":"课堂上学到的理论可以应用于解决现实世界的问题。","extra":"名词 application 应用；申请；应用程序。"},{"chapter":6,"key":"6:16","id":16,"word":"device","phonetic":"/dɪˈvaɪs/","pos":"n.","meaningCN":"装置，设备；手段，策略","tag":"核心","root":"","exampleEN":"The security device scans fingerprints to allow access to the building.","exampleCN":"这个安全装置扫描指纹以允许进入大楼。","extra":""},{"chapter":6,"key":"6:17","id":17,"word":"appliance","phonetic":"/əˈplaɪəns/","pos":"n.","meaningCN":"应用；（家用）器具","tag":"核心","root":"","exampleEN":"Energy-efficient appliances can help reduce household electricity bills.","exampleCN":"节能电器有助于降低家庭电费。","extra":"搭配：a kitchen appliance 厨房用具。"},{"chapter":6,"key":"6:18","id":18,"word":"facility","phonetic":"/fəˈsɪlɪti/","pos":"n.","meaningCN":"设备；便利","tag":"高频","root":"源自拉丁语 facilis（简单的），即促进事物简化的设施或工具","exampleEN":"The sports facility includes a swimming pool, gym, and tennis courts.","exampleCN":"这个体育设施包括游泳池、健身房和网球场。","extra":""},{"chapter":6,"key":"6:19","id":19,"word":"equipment","phonetic":"/ɪˈkwɪpmənt/","pos":"n.","meaningCN":"设备","tag":"核心","root":"","exampleEN":"The laboratory is equipped with state-of-the-art equipment for genetic research.","exampleCN":"实验室配备了用于基因研究的最先进设备。","extra":"动词 equip 装备，配备。"},{"chapter":6,"key":"6:20","id":20,"word":"instrument","phonetic":"/ˈɪnstrəmənt/","pos":"n.","meaningCN":"仪器；工具；乐器","tag":"核心","root":"","exampleEN":"The surgeon carefully sterilised the instruments before the operation.","exampleCN":"外科医生在手术前仔细消毒了器械。","extra":""},{"chapter":6,"key":"6:21","id":21,"word":"tool","phonetic":"/tuːl/","pos":"n.","meaningCN":"工具","tag":"核心","root":"","exampleEN":"Language is a powerful tool for communication and cultural exchange.","exampleCN":"语言是交流和文化交流的强大工具。","extra":""},{"chapter":6,"key":"6:22","id":22,"word":"gauge","phonetic":"/ɡeɪdʒ/","pos":"n.","meaningCN":"测量仪器 v. 测量；判断","tag":"低频","root":"","exampleEN":"It is difficult to gauge public opinion on such a complex issue.","exampleCN":"在如此复杂的问题上，很难判断公众舆论。","extra":""},{"chapter":6,"key":"6:23","id":23,"word":"measure","phonetic":"/ˈmeʒə/","pos":"v.","meaningCN":"测量 n. 衡量；措施","tag":"核心","root":"","exampleEN":"The government introduced strict measures to control air pollution.","exampleCN":"政府采取了严格措施来控制空气污染。","extra":"搭配：take measures 采取措施。"},{"chapter":6,"key":"6:24","id":24,"word":"calculate","phonetic":"/ˈkælkjʊleɪt/","pos":"v.","meaningCN":"计算；考虑，打算","tag":"核心","root":"","exampleEN":"Engineers calculated the load capacity of the bridge before construction began.","exampleCN":"工程师在施工开始前计算了桥梁的承载能力。","extra":"名词 calculation 计算；calculator 计算器。"},{"chapter":6,"key":"6:25","id":25,"word":"compute","phonetic":"/kəmˈpjuːt/","pos":"v.","meaningCN":"计算；估计","tag":"低频","root":"","exampleEN":"The system can compute complex data sets in a matter of seconds.","exampleCN":"该系统可以在几秒钟内计算复杂的数据集。","extra":"名词 computer 计算机。"},{"chapter":6,"key":"6:26","id":26,"word":"count","phonetic":"/kaʊnt/","pos":"v.","meaningCN":"计算","tag":"核心","root":"","exampleEN":"The teacher asked the students to count the number of trees in the park.","exampleCN":"老师要求学生数公园里树木的数量。","extra":""},{"chapter":6,"key":"6:27","id":27,"word":"estimate","phonetic":"/ˈestɪmət/","pos":"n.","meaningCN":"估价；估计；评价","tag":"核心","root":"","exampleEN":"According to official estimates, the population of the city will reach two million by 2030.","exampleCN":"根据官方估计，到2030年该市人口将达到200万。","extra":""},{"chapter":6,"key":"6:28","id":28,"word":"assess","phonetic":"/əˈses/","pos":"v.","meaningCN":"评估；估算","tag":"核心","root":"","exampleEN":"Teachers use a variety of methods to assess students' progress.","exampleCN":"教师使用多种方法来评估学生的进步。","extra":"名词 assessment 评估；估价。"},{"chapter":6,"key":"6:29","id":29,"word":"evaluate","phonetic":"/ɪˈvæljʊeɪt/","pos":"v.","meaningCN":"评价，评估","tag":"核心","root":"val 指“值钱”，如：evaluate（评估价值 → 评价），value（价值），invaluable（非常宝贵的），devaluation（贬值）","exampleEN":"The committee will evaluate the proposals based on cost, feasibility, and impact.","exampleCN":"委员会将根据成本、可行性和影响来评估这些提案。","extra":""},{"chapter":6,"key":"6:30","id":30,"word":"accessory","phonetic":"/əkˈsesəri/","pos":"n.","meaningCN":"附件，配件","tag":"低频","root":"","exampleEN":"The phone comes with several accessories, including a charger and earphones.","exampleCN":"手机配有几个附件，包括充电器和耳机。","extra":""},{"chapter":6,"key":"6:31","id":31,"word":"byproduct","phonetic":"/ˈbaɪˌprɒdʌkt/","pos":"n.","meaningCN":"副产品","tag":"低频","root":"","exampleEN":"One byproduct of the manufacturing process is a gas that can be used as fuel.","exampleCN":"制造过程的一种副产品是一种可用作燃料的气体。","extra":"前缀 by- 表示“副，旁”。"},{"chapter":6,"key":"6:32","id":32,"word":"auxiliary","phonetic":"/ɔːɡˈzɪliəri/","pos":"adj.","meaningCN":"辅助的，协助的；备用的","tag":"低频","root":"","exampleEN":"The hospital installed an auxiliary power system for use during emergencies.","exampleCN":"医院安装了一套辅助电力系统供紧急情况使用。","extra":""},{"chapter":6,"key":"6:33","id":33,"word":"versatile","phonetic":"/ˈvɜːsətaɪl/","pos":"adj.","meaningCN":"多功能的，多用途的","tag":"低频","root":"","exampleEN":"This versatile tool can be used for cutting, shaping, and polishing wood.","exampleCN":"这种多功能工具可用于切割、塑形和抛光木材。","extra":""},{"chapter":6,"key":"6:34","id":34,"word":"add","phonetic":"/æd/","pos":"v.","meaningCN":"添加；附加","tag":"核心","root":"","exampleEN":"Please add your name to the list if you wish to participate.","exampleCN":"如果您想参加，请把名字加到名单上。","extra":"搭配：add up to 合计达，总计达。"},{"chapter":6,"key":"6:35","id":35,"word":"accumulate","phonetic":"/əˈkjuːmjʊleɪt/","pos":"v.","meaningCN":"积累；（数额）逐渐增加","tag":"核心","root":"","exampleEN":"Over the years, she accumulated a vast collection of rare books.","exampleCN":"多年来，她积累了大量的珍贵藏书。","extra":""},{"chapter":6,"key":"6:36","id":36,"word":"assemble","phonetic":"/əˈsembl/","pos":"v.","meaningCN":"集合，聚集","tag":"高频","root":"","exampleEN":"The students assembled in the main hall for the morning briefing.","exampleCN":"学生们在主厅集合听取晨会。","extra":""},{"chapter":6,"key":"6:37","id":37,"word":"gather","phonetic":"/ˈɡæðə/","pos":"v.","meaningCN":"聚集；采集","tag":"核心","root":"","exampleEN":"The researcher gathered data from over a thousand participants.","exampleCN":"研究人员从一千多名参与者那里收集了数据。","extra":""},{"chapter":6,"key":"6:38","id":38,"word":"attach","phonetic":"/əˈtætʃ/","pos":"v.","meaningCN":"使依附；附加；缚，系，贴","tag":"高频","root":"","exampleEN":"Please attach your CV and cover letter when applying for the position.","exampleCN":"申请该职位时，请附上简历和求职信。","extra":"搭配：attach importance to 重视；名词 attachment 附件。"},{"chapter":6,"key":"6:39","id":39,"word":"belong","phonetic":"/bɪˈlɒŋ/","pos":"v.","meaningCN":"应在（某处）；适合（某种情形）","tag":"核心","root":"","exampleEN":"These ancient artifacts belong to the museum's permanent collection.","exampleCN":"这些古代文物属于博物馆的永久藏品。","extra":"搭配：belong to 属于。"},{"chapter":6,"key":"6:40","id":40,"word":"optics","phonetic":"/ˈɒptɪks/","pos":"n.","meaningCN":"光学","tag":"识记","root":"","exampleEN":"The study of optics has led to the development of high-precision lasers.","exampleCN":"光学研究促进了高精度激光的发展。","extra":""},{"chapter":6,"key":"6:41","id":41,"word":"microscope","phonetic":"/ˈmaɪkrəskəʊp/","pos":"n.","meaningCN":"显微镜","tag":"核心","root":"","exampleEN":"Under the microscope, you can see the individual cells of the plant.","exampleCN":"在显微镜下，你可以看到植物的单个细胞。","extra":"前缀 micro- 表示“微小”。"},{"chapter":6,"key":"6:42","id":42,"word":"lens","phonetic":"/lenz/","pos":"n.","meaningCN":"透镜；（照相机等的）镜头","tag":"高频","root":"","exampleEN":"The camera lens was damaged, so all the photos came out blurred.","exampleCN":"相机镜头损坏了，所以所有照片都模糊不清。","extra":""},{"chapter":6,"key":"6:43","id":43,"word":"radar","phonetic":"/ˈreɪdɑː/","pos":"n.","meaningCN":"雷达，无线电定位装置","tag":"低频","root":"","exampleEN":"The military base uses advanced radar systems to monitor airspace.","exampleCN":"军事基地使用先进的雷达系统监视空域。","extra":""},{"chapter":6,"key":"6:44","id":44,"word":"echo","phonetic":"/ˈekəʊ/","pos":"n.","meaningCN":"回声 v. 发回声；模仿；重复","tag":"低频","root":"","exampleEN":"His voice echoed through the empty hall.","exampleCN":"他的声音在空荡荡的大厅里回响。","extra":"希腊神话中的仙女厄科（Echo）。"},{"chapter":6,"key":"6:45","id":45,"word":"sensor","phonetic":"/ˈsensə/","pos":"n.","meaningCN":"传感器","tag":"高频","root":"","exampleEN":"The motion sensor automatically turns on the lights when someone enters the room.","exampleCN":"运动传感器在有人进入房间时自动开灯。","extra":"相关词：sense 感受；sensory 感觉的。"},{"chapter":6,"key":"6:46","id":46,"word":"multimedia","phonetic":"/ˌmʌltiˈmiːdiə/","pos":"n.","meaningCN":"多媒体","tag":"高频","root":"","exampleEN":"The teacher used multimedia resources such as videos and animations to explain the concept.","exampleCN":"老师使用视频和动画等多媒体资源来解释概念。","extra":""},{"chapter":6,"key":"6:47","id":47,"word":"network","phonetic":"/ˈnetwɜːk/","pos":"n.","meaningCN":"网络；广播网，电视网","tag":"核心","root":"","exampleEN":"Social networks have changed the way people communicate and share information.","exampleCN":"社交网络改变了人们交流和分享信息的方式。","extra":""},{"chapter":6,"key":"6:48","id":48,"word":"browser","phonetic":"/ˈbraʊzə/","pos":"n.","meaningCN":"浏览器","tag":"低频","root":"","exampleEN":"Make sure your browser is updated to the latest version for better security.","exampleCN":"确保浏览器更新到最新版本以确保更好的安全性。","extra":""},{"chapter":6,"key":"6:49","id":49,"word":"dial","phonetic":"/ˈdaɪəl/","pos":"v.","meaningCN":"拨（电话号码）","tag":"核心","root":"","exampleEN":"She quickly dialled the emergency number when she saw the accident.","exampleCN":"看到事故后，她迅速拨打了紧急电话。","extra":""},{"chapter":6,"key":"6:50","id":50,"word":"microcomputer","phonetic":"/ˈmaɪkrəʊkəmˌpjuːtə/","pos":"n.","meaningCN":"微型计算机","tag":"识记","root":"","exampleEN":"In the 1980s, the microcomputer revolutionised home and office work.","exampleCN":"在20世纪80年代，微型计算机彻底改变了家庭和办公室工作。","extra":""},{"chapter":6,"key":"6:51","id":51,"word":"laptop","phonetic":"/ˈlæptɒp/","pos":"n.","meaningCN":"笔记本电脑","tag":"核心","root":"","exampleEN":"Many students prefer laptops to desktop computers because they are portable.","exampleCN":"许多学生更喜欢笔记本电脑而非台式机，因为便于携带。","extra":""},{"chapter":6,"key":"6:52","id":52,"word":"software","phonetic":"/ˈsɒftweə/","pos":"n.","meaningCN":"软件","tag":"核心","root":"","exampleEN":"The company develops software solutions for small businesses.","exampleCN":"这家公司为小型企业开发软件解决方案。","extra":"反义词：hardware 硬件。"},{"chapter":6,"key":"6:53","id":53,"word":"high-definition","phonetic":"/ˌhaɪ defɪˈnɪʃən/","pos":"adj.","meaningCN":"高分辨率的","tag":"识记","root":"","exampleEN":"The documentary was filmed in high-definition, capturing stunning details of wildlife.","exampleCN":"这部纪录片以高分辨率拍摄，捕捉了野生动物的惊人细节。","extra":""},{"chapter":6,"key":"6:54","id":54,"word":"keyboard","phonetic":"/ˈkiːbɔːd/","pos":"n.","meaningCN":"键盘","tag":"核心","root":"","exampleEN":"She spends most of her working day typing on a keyboard.","exampleCN":"她大部分工作时间都在键盘上打字。","extra":""},{"chapter":6,"key":"6:55","id":55,"word":"screen","phonetic":"/skriːn/","pos":"n.","meaningCN":"屏；屏幕 v. 遮蔽","tag":"核心","root":"","exampleEN":"Long hours of staring at a screen can cause eye strain.","exampleCN":"长时间盯着屏幕会导致眼睛疲劳。","extra":""},{"chapter":6,"key":"6:56","id":56,"word":"audio","phonetic":"/ˈɔːdiəʊ/","pos":"adj.","meaningCN":"声音的","tag":"高频","root":"","exampleEN":"The language lab provides audio materials for students to improve their listening skills.","exampleCN":"语言实验室提供音频材料，帮助学生提高听力技能。","extra":""},{"chapter":6,"key":"6:57","id":57,"word":"loudspeaker","phonetic":"/ˌlaʊdˈspiːkə/","pos":"n.","meaningCN":"扬声器，喇叭","tag":"低频","root":"","exampleEN":"The announcement was made over the loudspeaker for everyone to hear.","exampleCN":"通知通过扬声器播放，让每个人都能听到。","extra":""},{"chapter":6,"key":"6:58","id":58,"word":"vision","phonetic":"/ˈvɪʒən/","pos":"n.","meaningCN":"视觉，视力","tag":"核心","root":"","exampleEN":"Regular eye exams are important for maintaining good vision.","exampleCN":"定期眼科检查对于保持良好视力很重要。","extra":"形容词 visual 视觉的；visible 看得见的。"},{"chapter":6,"key":"6:59","id":59,"word":"microphone","phonetic":"/ˈmaɪkrəfəʊn/","pos":"n.","meaningCN":"话筒，麦克风","tag":"核心","root":"","exampleEN":"The speaker adjusted the microphone before beginning her talk.","exampleCN":"演讲者在开始前调整了麦克风。","extra":""},{"chapter":6,"key":"6:60","id":60,"word":"fantasy","phonetic":"/ˈfæntəsi/","pos":"n.","meaningCN":"幻想","tag":"高频","root":"","exampleEN":"The novel is a fantasy about a young wizard's adventures in a magical world.","exampleCN":"这部小说是一部关于年轻巫师在魔法世界冒险的奇幻作品。","extra":"形容词 fantastic 奇异的，奇妙的。"},{"chapter":6,"key":"6:61","id":61,"word":"cassette","phonetic":"/kəˈset/","pos":"n.","meaningCN":"盒式磁带；底片盒","tag":"识记","root":"来自 case（箱），-ette 是表示“小”的后缀","exampleEN":"I found an old cassette of my parents' wedding music in the attic.","exampleCN":"我在阁楼里发现了一盘我父母婚礼上的旧磁带。","extra":""},{"chapter":6,"key":"6:62","id":62,"word":"science fiction","phonetic":"/ˌsaɪəns ˈfɪkʃən/","pos":"n.","meaningCN":"科幻作品","tag":"高频","root":"","exampleEN":"Many technological innovations were first imagined in science fiction.","exampleCN":"许多科技创新最初是在科幻作品中想象的。","extra":""},{"chapter":6,"key":"6:63","id":63,"word":"tape","phonetic":"/teɪp/","pos":"n.","meaningCN":"磁带，录音带；胶带","tag":"低频","root":"","exampleEN":"He used duct tape to temporarily fix the broken pipe.","exampleCN":"他用胶带临时修补了破裂的管道。","extra":""},{"chapter":6,"key":"6:64","id":64,"word":"pump","phonetic":"/pʌmp/","pos":"n.","meaningCN":"泵 v.（用泵）抽","tag":"高频","root":"","exampleEN":"The heart acts as a pump, circulating blood throughout the body.","exampleCN":"心脏像一个泵，使血液循环全身。","extra":""},{"chapter":6,"key":"6:65","id":65,"word":"binary","phonetic":"/ˈbaɪnəri/","pos":"adj.","meaningCN":"二进制的；二元的","tag":"低频","root":"","exampleEN":"Computers process all information in binary code, using only 0s and 1s.","exampleCN":"计算机以二进制代码处理所有信息，仅使用0和1。","extra":""},{"chapter":6,"key":"6:66","id":66,"word":"digital","phonetic":"/ˈdɪdʒɪtəl/","pos":"adj.","meaningCN":"数字的","tag":"核心","root":"","exampleEN":"The shift from analogue to digital technology has transformed the media industry.","exampleCN":"从模拟技术到数字技术的转变改变了媒体行业。","extra":""},{"chapter":6,"key":"6:67","id":67,"word":"wireless","phonetic":"/ˈwaɪələs/","pos":"adj.","meaningCN":"不用电线的，无线的","tag":"核心","root":"","exampleEN":"The cafe offers free wireless internet access to all customers.","exampleCN":"这家咖啡馆为所有顾客提供免费无线上网。","extra":"Wi-Fi 是 wireless fidelity 的缩写。"},{"chapter":6,"key":"6:68","id":68,"word":"generator","phonetic":"/ˈdʒenəreɪtə/","pos":"n.","meaningCN":"发电机","tag":"高频","root":"","exampleEN":"During the blackout, the hospital relied on emergency generators for power.","exampleCN":"停电期间，医院依靠应急发电机供电。","extra":"动词 generate 产生（能量），发（电）。"},{"chapter":6,"key":"6:69","id":69,"word":"gear","phonetic":"/ɡɪə/","pos":"n.","meaningCN":"齿轮，传动装置 v. 使适合","tag":"低频","root":"","exampleEN":"The course is geared towards students who wish to study abroad.","exampleCN":"这门课程是为想要出国留学的学生开设的。","extra":"搭配：in high gear 以高速挡；gear up 促进。"},{"chapter":6,"key":"6:70","id":70,"word":"pivot","phonetic":"/ˈpɪvət/","pos":"n.","meaningCN":"枢轴，支点；中心，重点","tag":"低频","root":"","exampleEN":"The investigation quickly became the pivot around which the whole case revolved.","exampleCN":"调查迅速成为整个案件围绕的中心。","extra":""},{"chapter":6,"key":"6:71","id":71,"word":"hydraulic","phonetic":"/haɪˈdrɔːlɪk/","pos":"adj.","meaningCN":"水力的，液压的","tag":"高频","root":"","exampleEN":"Hydraulic systems are commonly used in heavy machinery such as excavators.","exampleCN":"液压系统通常用于挖掘机等重型机械。","extra":""},{"chapter":6,"key":"6:72","id":72,"word":"drainage","phonetic":"/ˈdreɪnɪdʒ/","pos":"n.","meaningCN":"排水系统；排水","tag":"低频","root":"","exampleEN":"The city's drainage system is being upgraded to prevent flooding during heavy rains.","exampleCN":"该市的排水系统正在升级，以防止暴雨时发生洪涝。","extra":"搭配：improve the drainage 改善排水系统。"},{"chapter":6,"key":"6:73","id":73,"word":"sewage","phonetic":"/ˈsuːɪdʒ/","pos":"n.","meaningCN":"（下水道的）污水","tag":"高频","root":"","exampleEN":"Untreated sewage should not be discharged into rivers because it harms aquatic life.","exampleCN":"未经处理的污水不应排入河流，因为它会危害水生生物。","extra":""},{"chapter":6,"key":"6:74","id":74,"word":"ventilation","phonetic":"/ˌventɪˈleɪʃən/","pos":"n.","meaningCN":"通风；通风设备","tag":"低频","root":"","exampleEN":"Good ventilation in the workplace helps maintain a healthy indoor environment.","exampleCN":"良好的工作场所通风有助于保持健康的室内环境。","extra":""},{"chapter":6,"key":"6:75","id":75,"word":"compress","phonetic":"/kəmˈpres/","pos":"v.","meaningCN":"压紧，压缩","tag":"低频","root":"","exampleEN":"You can compress the file to make it easier to send via email.","exampleCN":"你可以压缩文件以便通过电子邮件发送。","extra":""},{"chapter":6,"key":"6:76","id":76,"word":"condense","phonetic":"/kənˈdens/","pos":"v.","meaningCN":"简缩，精简；（使气体）凝结","tag":"低频","root":"","exampleEN":"The editor asked the author to condense the report to ten pages.","exampleCN":"编辑要求作者将报告精简到十页。","extra":""},{"chapter":6,"key":"6:77","id":77,"word":"refine","phonetic":"/rɪˈfaɪn/","pos":"v.","meaningCN":"精炼，提纯","tag":"高频","root":"","exampleEN":"The oil refining process separates crude oil into various useful products.","exampleCN":"炼油过程将原油分离成各种有用的产品。","extra":"搭配：refine on 对......进行精微改进。"},{"chapter":6,"key":"6:78","id":78,"word":"simplify","phonetic":"/ˈsɪmplɪfaɪ/","pos":"v.","meaningCN":"简化，精简","tag":"核心","root":"","exampleEN":"The government is trying to simplify the tax filing process for ordinary citizens.","exampleCN":"政府正试图简化普通市民的报税流程。","extra":"名词 simplicity 简单；形容词 simple 简单的。"},{"chapter":6,"key":"6:79","id":79,"word":"purify","phonetic":"/ˈpjʊərɪfaɪ/","pos":"v.","meaningCN":"净化，使纯净","tag":"低频","root":"","exampleEN":"Special filters are used to purify the water before it is bottled.","exampleCN":"水在装瓶前使用特殊过滤器进行净化。","extra":"名词 purity 纯洁；形容词 pure 纯净的。"},{"chapter":6,"key":"6:80","id":80,"word":"filter","phonetic":"/ˈfɪltə/","pos":"v.","meaningCN":"过滤；（光或声）透过 n. 过滤器","tag":"高频","root":"","exampleEN":"Air purifiers filter out dust and pollen, which can help allergy sufferers.","exampleCN":"空气净化器过滤掉灰尘和花粉，有助于过敏患者。","extra":"搭配：filter through（消息等）慢慢传开。"},{"chapter":6,"key":"6:81","id":81,"word":"distil","phonetic":"/dɪˈstɪl/","pos":"v.","meaningCN":"蒸馏；提取......的精华","tag":"低频","root":"","exampleEN":"The author managed to distil complex concepts into simple, engaging prose.","exampleCN":"作者成功地将复杂的概念提炼成简洁而引人入胜的文字。","extra":""},{"chapter":6,"key":"6:82","id":82,"word":"mode","phonetic":"/məʊd/","pos":"n.","meaningCN":"模式；方式","tag":"核心","root":"mod 指“方式，方法”，如：model（模型；模特儿），modest（谦虚的），modify（修改）","exampleEN":"Many smartphones have a power-saving mode that extends battery life.","exampleCN":"许多智能手机都有省电模式以延长电池续航。","extra":""},{"chapter":6,"key":"6:83","id":83,"word":"mould","phonetic":"/məʊld/","pos":"v.","meaningCN":"浇铸；塑造 n. 模子","tag":"低频","root":"","exampleEN":"The artist used clay to mould a beautiful sculpture of a horse.","exampleCN":"艺术家用粘土塑造了一匹美丽的马雕塑。","extra":""},{"chapter":6,"key":"6:84","id":84,"word":"prototype","phonetic":"/ˈprəʊtətaɪp/","pos":"n.","meaningCN":"原型；雏形","tag":"高频","root":"","exampleEN":"The company built a prototype of the new electric car for testing purposes.","exampleCN":"公司制造了新电动汽车的原型用于测试。","extra":""},{"chapter":6,"key":"6:85","id":85,"word":"framework","phonetic":"/ˈfreɪmwɜːk/","pos":"n.","meaningCN":"框架，结构；体系","tag":"核心","root":"","exampleEN":"The report provides a comprehensive framework for understanding climate change.","exampleCN":"该报告为理解气候变化提供了一个全面的框架。","extra":""},{"chapter":6,"key":"6:86","id":86,"word":"aspect","phonetic":"/ˈæspekt/","pos":"n.","meaningCN":"（问题、事物等的）方面","tag":"核心","root":"","exampleEN":"We need to examine every aspect of the plan before making a decision.","exampleCN":"在做决定之前，我们需要考察计划的每个方面。","extra":""},{"chapter":6,"key":"6:87","id":87,"word":"phase","phonetic":"/feɪz/","pos":"n.","meaningCN":"阶段，时期","tag":"核心","root":"","exampleEN":"The construction project is currently in its final phase.","exampleCN":"这个建设项目目前处于最后阶段。","extra":""},{"chapter":6,"key":"6:88","id":88,"word":"operate","phonetic":"/ˈɒpəreɪt/","pos":"v.","meaningCN":"操作；运营；做手术","tag":"核心","root":"","exampleEN":"The company operates factories in several countries across Asia.","exampleCN":"这家公司在亚洲多个国家经营工厂。","extra":"名词 operation 操作；企业；手术。"},{"chapter":6,"key":"6:89","id":89,"word":"facilitate","phonetic":"/fəˈsɪlɪteɪt/","pos":"v.","meaningCN":"使便利，促进","tag":"高频","root":"","exampleEN":"Digital platforms facilitate communication between teachers and students outside the classroom.","exampleCN":"数字平台促进了师生在课外的交流。","extra":""},{"chapter":6,"key":"6:90","id":90,"word":"transform","phonetic":"/trænsˈfɔːm/","pos":"v.","meaningCN":"使改变形态；使改观","tag":"核心","root":"trans（转移）+ form（形状）→ 改变形态","exampleEN":"The internet has transformed the way people access information.","exampleCN":"互联网改变了人们获取信息的方式。","extra":"名词 transformation 变化，转变。"},{"chapter":6,"key":"6:91","id":91,"word":"convert","phonetic":"/kənˈvɜːt/","pos":"v.","meaningCN":"（使）转变；（使）改变（信仰、观点等）","tag":"核心","root":"","exampleEN":"The old factory was converted into a modern art gallery.","exampleCN":"旧工厂被改造成了一个现代艺术画廊。","extra":"名词 conversion 转变；换算。"},{"chapter":6,"key":"6:92","id":92,"word":"alter","phonetic":"/ˈɔːltə/","pos":"v.","meaningCN":"改变，变更","tag":"核心","root":"拉丁语 alter 意为“其他的”","exampleEN":"The company had to alter its strategy due to the changing market conditions.","exampleCN":"由于市场环境变化，公司不得不改变策略。","extra":"形容词 alternative 可供选择的。"},{"chapter":6,"key":"6:93","id":93,"word":"shift","phonetic":"/ʃɪft/","pos":"v.","meaningCN":"转移，变换 n. 转移，变换；轮班","tag":"核心","root":"","exampleEN":"The government plans to shift the focus from manufacturing to service industries.","exampleCN":"政府计划将重点从制造业转向服务业。","extra":"搭配：the day shift 日班；the night shift 夜班。"},{"chapter":6,"key":"6:94","id":94,"word":"turn","phonetic":"/tɜːn/","pos":"v.","meaningCN":"转；翻 n.（依次轮到的）机会","tag":"核心","root":"","exampleEN":"It's your turn to present your findings to the class.","exampleCN":"轮到你向全班展示你的发现了。","extra":""},{"chapter":6,"key":"6:95","id":95,"word":"adapt","phonetic":"/əˈdæpt/","pos":"v.","meaningCN":"适应；改编","tag":"核心","root":"","exampleEN":"Children can adapt quickly to new environments.","exampleCN":"孩子们能很快适应新环境。","extra":"搭配：adapt to sth. 适应某事物；名词 adaptation 适应。"},{"chapter":6,"key":"6:96","id":96,"word":"adjust","phonetic":"/əˈdʒʌst/","pos":"v.","meaningCN":"调节；改变（行为或观点）以适应","tag":"核心","root":"","exampleEN":"The seat can be adjusted to the height of the driver.","exampleCN":"座椅可根据驾驶员的身高进行调节。","extra":"搭配：adjust to 适应；名词 adjustment 调整。"},{"chapter":6,"key":"6:97","id":97,"word":"pinpoint","phonetic":"/ˈpɪnpɔɪnt/","pos":"v.","meaningCN":"精确指明......的位置 n. 针尖；极小的事物","tag":"高频","root":"","exampleEN":"GPS technology can pinpoint the location of a mobile phone to within a few metres.","exampleCN":"GPS技术可以将手机位置精确到几米以内。","extra":""},{"chapter":6,"key":"6:98","id":98,"word":"accurate","phonetic":"/ˈækjʊrət/","pos":"adj.","meaningCN":"准确的，正确无误的","tag":"核心","root":"","exampleEN":"It is essential that the data used in the report is accurate and up-to-date.","exampleCN":"报告中使用的数据必须准确且是最新的。","extra":"名词 accuracy 精确（度），准确（性）；反义词 inaccurate 不准确的。"},{"chapter":6,"key":"6:99","id":99,"word":"precise","phonetic":"/prɪˈsaɪs/","pos":"adj.","meaningCN":"精确的，准确的；一丝不苟的","tag":"核心","root":"","exampleEN":"The surgeon needed a precise measurement of the patient's eye before the laser surgery.","exampleCN":"外科医生在激光手术前需要精确测量患者的眼睛。","extra":"副词 precisely 正是；恰好地。"},{"chapter":6,"key":"6:100","id":100,"word":"correct","phonetic":"/kəˈrekt/","pos":"adj.","meaningCN":"正确的","tag":"核心","root":"","exampleEN":"Please check that all the information on the form is correct before submitting.","exampleCN":"请在提交前检查表格上的所有信息是否正确。","extra":"名词 correction 改正；反义词 incorrect 错误的。"},{"chapter":6,"key":"6:101","id":101,"word":"error","phonetic":"/ˈerə/","pos":"n.","meaningCN":"错误，过失","tag":"核心","root":"","exampleEN":"A small error in calculation can lead to a completely different result.","exampleCN":"计算中的一个小错误可能导致完全不同的结果。","extra":""},{"chapter":6,"key":"6:102","id":102,"word":"mistake","phonetic":"/mɪˈsteɪk/","pos":"n.","meaningCN":"错误 v. 误解","tag":"核心","root":"","exampleEN":"Everyone makes mistakes, but the key is to learn from them.","exampleCN":"每个人都会犯错，但关键是要从中吸取教训。","extra":"搭配：by mistake 错误地；make a mistake 犯错误。"},{"chapter":6,"key":"6:103","id":103,"word":"flaw","phonetic":"/flɔː/","pos":"n.","meaningCN":"缺陷；错误","tag":"高频","root":"","exampleEN":"The investigation revealed serious flaws in the design of the bridge.","exampleCN":"调查揭示了桥梁设计中的严重缺陷。","extra":"形容词 flawless 完美的，没有瑕疵的。"},{"chapter":6,"key":"6:104","id":104,"word":"wrong","phonetic":"/rɒŋ/","pos":"adj.","meaningCN":"错误的 adv. 错误地","tag":"核心","root":"","exampleEN":"If something goes wrong with the equipment, call the maintenance team immediately.","exampleCN":"如果设备出现问题，立即致电维修队。","extra":"搭配：go wrong 出现问题；出差错。"},{"chapter":6,"key":"6:105","id":105,"word":"fault","phonetic":"/fɔːlt/","pos":"n.","meaningCN":"缺点；故障 v. 找出缺点","tag":"核心","root":"","exampleEN":"The power outage was caused by a fault in one of the underground cables.","exampleCN":"停电是由一根地下电缆故障引起的。","extra":"形容词 faulty 有错误的；搭配：find fault with 挑剔。"},{"chapter":6,"key":"6:106","id":106,"word":"stumble","phonetic":"/ˈstʌmbəl/","pos":"v.","meaningCN":"犯错误；绊脚；跌跌撞撞地走","tag":"高频","root":"","exampleEN":"The actor stumbled over his lines during the first rehearsal.","exampleCN":"演员在第一次排练时念错了台词。","extra":"搭配：stumble over 在......绊了一下。"},{"chapter":6,"key":"6:107","id":107,"word":"contingency","phonetic":"/kənˈtɪndʒənsi/","pos":"n.","meaningCN":"意外事件，可能发生的事","tag":"低频","root":"","exampleEN":"The company has a contingency plan in case of a sudden drop in sales.","exampleCN":"公司有一项应急计划，以防销售额突然下降。","extra":""},{"chapter":6,"key":"6:108","id":108,"word":"circumstance","phonetic":"/ˈsɜːkəmstəns/","pos":"n.","meaningCN":"情况；环境；条件；[-s] 境遇","tag":"核心","root":"circum/circ/cycl(o) 都和“圆、环”有关，如：circumstance（环境），circle（圆圈），circulate（循环），recycle（回收利用）","exampleEN":"Under no circumstances should passengers open the emergency door during the flight.","exampleCN":"在任何情况下，乘客都不得在飞行中打开紧急出口。","extra":"搭配：under/in no circumstances 决不。"},{"chapter":6,"key":"6:109","id":109,"word":"technology","phonetic":"/tekˈnɒlədʒi/","pos":"n.","meaningCN":"技术","tag":"核心","root":"","exampleEN":"Modern technology has completely transformed the way we communicate with each other.","exampleCN":"现代技术彻底改变了我们彼此沟通的方式。","extra":"形容词：technological；搭配：advanced technology（先进技术）"},{"chapter":6,"key":"6:110","id":110,"word":"technique","phonetic":"/tekˈniːk/","pos":"n.","meaningCN":"技巧；技术","tag":"核心","root":"","exampleEN":"The painter used an innovative technique to create the illusion of depth.","exampleCN":"这位画家使用了一种创新的技巧来创造深度的幻觉。","extra":"形容词：technical；名词：technician（技术员）"},{"chapter":6,"key":"6:111","id":111,"word":"polytechnic","phonetic":"/ˌpɒlɪˈteknɪk/","pos":"adj./n.","meaningCN":"有关多种工艺的 n. 理工学院","tag":"低频","root":"","exampleEN":"He graduated from a polytechnic with a degree in mechanical engineering.","exampleCN":"他毕业于一所理工学院，获得了机械工程学位。","extra":"常见于教育机构名称"},{"chapter":6,"key":"6:112","id":112,"word":"engineer","phonetic":"/ˌendʒɪˈnɪə/","pos":"n.","meaningCN":"工程师，技师","tag":"核心","root":"","exampleEN":"The civil engineer designed a bridge that can withstand earthquakes.","exampleCN":"这位土木工程师设计了一座能抵御地震的桥梁。","extra":"相关：engine（引擎）；engineering（工程学）"},{"chapter":6,"key":"6:113","id":113,"word":"mechanic","phonetic":"/məˈtʃænɪk/","pos":"n.","meaningCN":"技工，机械师，机修工","tag":"核心","root":"","exampleEN":"The mechanic quickly diagnosed the strange noise coming from the car engine.","exampleCN":"机修工迅速诊断出汽车发动机传来的奇怪噪音。","extra":"相关：machine（机器）；mechanism（机制）"},{"chapter":6,"key":"6:114","id":114,"word":"advance","phonetic":"/ədˈvɑːns/","pos":"n./v.","meaningCN":"发展；前进","tag":"核心","root":"","exampleEN":"Recent advances in medical science have saved millions of lives.","exampleCN":"医学科学的最新进展已经拯救了数百万人的生命。","extra":"搭配：in advance（预先）；形容词：advanced（先进的）"},{"chapter":6,"key":"6:115","id":115,"word":"innovate","phonetic":"/ˈɪnəveɪt/","pos":"v.","meaningCN":"创新，改革","tag":"核心","root":"","exampleEN":"Companies that fail to innovate often get left behind by their competitors.","exampleCN":"无法创新的公司往往会被竞争对手甩在身后。","extra":"名词：innovation（创新）；派生词：innovator（创新者）"},{"chapter":6,"key":"6:116","id":116,"word":"breakthrough","phonetic":"/ˌbreɪkˈθruː/","pos":"n.","meaningCN":"突破","tag":"核心","root":"","exampleEN":"Scientists have made a major breakthrough in cancer research.","exampleCN":"科学家们在癌症研究方面取得了重大突破。","extra":"常用搭配：make a breakthrough"},{"chapter":6,"key":"6:117","id":117,"word":"gizmo","phonetic":"/ˈɡɪzməʊ/","pos":"n.","meaningCN":"小装置","tag":"低频","root":"","exampleEN":"The kitchen is full of handy gizmos that make cooking easier.","exampleCN":"厨房里到处都是让烹饪变简单的小装置。","extra":"同义词：gadget"},{"chapter":6,"key":"6:118","id":118,"word":"patent","phonetic":"/ˈpeɪtnt/","pos":"n./v.","meaningCN":"专利，专利权 v. 得到......的专利权；给......专利证","tag":"高频","root":"","exampleEN":"The company applied for a patent to protect its new invention.","exampleCN":"该公司申请了专利以保护其新发明。","extra":"搭配：patent office（专利局）"},{"chapter":6,"key":"6:119","id":119,"word":"device","phonetic":"/ˈdiːvaɪs/","pos":"v.","meaningCN":"设计，发明","tag":"高频","root":"","exampleEN":"They are trying to device a more efficient way to store renewable energy.","exampleCN":"他们正尝试设计一种更有效的可再生能源存储方式。","extra":"注意：名词形式 device（装置）；动词实际应为 devise"},{"chapter":6,"key":"6:120","id":120,"word":"invent","phonetic":"/ɪnˈvent/","pos":"v.","meaningCN":"发明，创造","tag":"核心","root":"","exampleEN":"Alexander Graham Bell invented the telephone in 1876.","exampleCN":"亚历山大·格雷厄姆·贝尔于1876年发明了电话。","extra":"名词：invention（发明）；inventor（发明家）"},{"chapter":6,"key":"6:121","id":121,"word":"discover","phonetic":"/dɪˈskʌvə/","pos":"v.","meaningCN":"发现","tag":"核心","root":"","exampleEN":"Archaeologists discovered ancient artifacts buried beneath the city.","exampleCN":"考古学家发现了埋在城市地下的古代文物。","extra":"名词：discovery；对比：invent（发明不存在的事物）"},{"chapter":6,"key":"6:129","id":129,"word":"disclose","phonetic":"/dɪsˈkləʊz/","pos":"v.","meaningCN":"揭露；公开，透露","tag":"高频","root":"","exampleEN":"The company refused to disclose the details of the contract to the public.","exampleCN":"该公司拒绝向公众披露合同的细节。","extra":"名词：disclosure；同义词：reveal, uncover"}],"7":[{"chapter":7,"key":"7:1","id":1,"word":"culture","phonetic":"/ˈkʌltʃə/","pos":"n.","meaningCN":"文化，文明；教养","tag":"核心","root":"cult 指“耕种（to till）”。人类最早的文化之一就是农耕文化。","exampleEN":"Understanding local culture is essential for anyone planning to live and work abroad.","exampleCN":"理解当地文化对任何计划出国生活和工作的人都至关重要。","extra":"cultural adj. 文化的；multicultural adj. 文化多样的。"},{"chapter":7,"key":"7:2","id":2,"word":"civilisation","phonetic":"/ˌsɪvəlaɪˈzeɪʃən/","pos":"n.","meaningCN":"文明","tag":"高频","root":"civilise (= civilize) v. 使文明；开化","exampleEN":"The museum exhibits trace the development of ancient civilisations across five continents.","exampleCN":"博物馆的展品追溯了五大洲古代文明的发展。","extra":"同 civilization。"},{"chapter":7,"key":"7:3","id":3,"word":"renaissance","phonetic":"/rɪˈneɪsəns/","pos":"n.","meaningCN":"[the R-] 文艺复兴时期","tag":"高频","root":"","exampleEN":"The Renaissance sparked a renewed interest in science, art, and classical learning.","exampleCN":"文艺复兴重新点燃了人们对科学、艺术和古典学问的兴趣。","extra":"通常大写。"},{"chapter":7,"key":"7:4","id":4,"word":"epic","phonetic":"/ˈepɪk/","pos":"n.","meaningCN":"史诗 adj. 宏大的","tag":"低频","root":"","exampleEN":"Homer's 'Iliad' is an ancient Greek epic about the Trojan War.","exampleCN":"荷马的《伊利亚特》是一部关于特洛伊战争的古希腊史诗。","extra":"也可作形容词。"},{"chapter":7,"key":"7:5","id":5,"word":"ideology","phonetic":"/ˌaɪdɪˈɒlədʒi/","pos":"n.","meaningCN":"意识形态，思想体系","tag":"高频","root":"","exampleEN":"People's political ideology often influences how they interpret current events.","exampleCN":"人们的政治意识形态常常影响他们如何解读时事。","extra":""},{"chapter":7,"key":"7:6","id":6,"word":"tradition","phonetic":"/trəˈdɪʃən/","pos":"n.","meaningCN":"传统","tag":"核心","root":"traditional adj. 传统的；惯例的","exampleEN":"It is a family tradition to gather for a large meal at the Spring Festival.","exampleCN":"春节期间聚在一起吃大餐是一项家族传统。","extra":"搭配：by tradition 根据传统。"},{"chapter":7,"key":"7:7","id":7,"word":"convention","phonetic":"/kənˈvenʃən/","pos":"n.","meaningCN":"惯例；大型会议","tag":"高频","root":"conventional adj. 传统的；通常的","exampleEN":"Wearing formal attire to an interview is a social convention in many countries.","exampleCN":"面试时穿正装在许多国家是一种社会惯例。","extra":""},{"chapter":7,"key":"7:8","id":8,"word":"custom","phonetic":"/ˈkʌstəm/","pos":"n.","meaningCN":"习俗；（个人的）习惯","tag":"核心","root":"customs n. 海关；关税","exampleEN":"The custom of exchanging gifts during the holiday season is widely practised.","exampleCN":"节日期间交换礼物的习俗被广泛践行。","extra":"customs 海关。"},{"chapter":7,"key":"7:9","id":9,"word":"feudalism","phonetic":"/ˈfjuːdəlɪzəm/","pos":"n.","meaningCN":"封建主义；封建制度","tag":"识记","root":"feudal adj. 封建的","exampleEN":"Under feudalism, land was owned by nobles and worked by peasants in exchange for protection.","exampleCN":"在封建制度下，土地归贵族所有，由农民耕作以换取保护。","extra":""},{"chapter":7,"key":"7:10","id":10,"word":"slavery","phonetic":"/ˈsleɪvəri/","pos":"n.","meaningCN":"奴隶制","tag":"高频","root":"slave n. 奴隶","exampleEN":"Slavery was officially abolished in many countries during the nineteenth century.","exampleCN":"十九世纪，许多国家正式废除了奴隶制。","extra":""},{"chapter":7,"key":"7:11","id":11,"word":"ethical","phonetic":"/ˈeθɪkəl/","pos":"adj.","meaningCN":"伦理的，道德的","tag":"高频","root":"","exampleEN":"Scientists must consider the ethical implications of their experiments before proceeding.","exampleCN":"科学家在进行实验前必须考虑实验的伦理影响。","extra":""},{"chapter":7,"key":"7:12","id":12,"word":"moral","phonetic":"/ˈmɔːrəl/","pos":"adj.","meaningCN":"道德上的；有道德的 n. [-s] 道德","tag":"核心","root":"immoral adj. 不道德的","exampleEN":"The novel explores the moral dilemmas faced by people during wartime.","exampleCN":"这部小说探讨了战争期间人们面临的道德困境。","extra":"搭配：moral principles 道德准则。"},{"chapter":7,"key":"7:13","id":13,"word":"tribe","phonetic":"/traɪb/","pos":"n.","meaningCN":"部落","tag":"高频","root":"源自拉丁语 tribus，同源词：contribute（捐献），distribute（分发），attribute（归因于；属性），tributary（支流）","exampleEN":"The indigenous tribe has preserved its language and customs for thousands of years.","exampleCN":"这个土著部落将其语言和习俗保存了数千年。","extra":""},{"chapter":7,"key":"7:14","id":14,"word":"aboriginal","phonetic":"/ˌæbəˈrɪdʒɪnəl/","pos":"n.","meaningCN":"[A-] 澳大利亚土著人 adj. 本土原有的；土著的","tag":"识记","root":"original adj. 原本的，最初的； origin n. 起源","exampleEN":"Aboriginal Australians have a deep spiritual connection to the land that dates back millennia.","exampleCN":"澳大利亚土著人与土地有着数千年的深厚精神联系。","extra":""},{"chapter":7,"key":"7:15","id":15,"word":"inhabitant","phonetic":"/ɪnˈhæbɪtənt/","pos":"n.","meaningCN":"居民","tag":"高频","root":"in（进入）+ habit（持有，握住 → 居住）+ ant → 居民","exampleEN":"The island's original inhabitants were skilled fishermen and navigators.","exampleCN":"该岛的原住民是熟练的渔民和航海者。","extra":"inhabit v. 居住于。"},{"chapter":7,"key":"7:16","id":16,"word":"native","phonetic":"/ˈneɪtɪv/","pos":"adj.","meaningCN":"本土的 n. 本地人","tag":"核心","root":"","exampleEN":"He returned to his native country after spending twenty years overseas.","exampleCN":"在海外度过二十年后，他回到了故土。","extra":"搭配：native tongue 母语。"},{"chapter":7,"key":"7:17","id":17,"word":"local","phonetic":"/ˈləʊkəl/","pos":"adj.","meaningCN":"当地的 n. 当地人","tag":"核心","root":"localise (= localize) v. 使局部化","exampleEN":"Visitors are encouraged to try local dishes to fully experience the regional culture.","exampleCN":"鼓励游客品尝当地菜肴，以充分体验地域文化。","extra":""},{"chapter":7,"key":"7:18","id":18,"word":"exotic","phonetic":"/ɪɡˈzɒtɪk/","pos":"adj.","meaningCN":"外来的；异国情调的","tag":"高频","root":"","exampleEN":"The marketplace was filled with exotic spices and colourful fabrics from distant lands.","exampleCN":"市场上摆满了来自遥远国度的异国香料和色彩斑斓的织物。","extra":"注意与 erotic（色情的）区分。"},{"chapter":7,"key":"7:19","id":19,"word":"foreigner","phonetic":"/ˈfɒrɪnə/","pos":"n.","meaningCN":"外国人","tag":"核心","root":"","exampleEN":"As a foreigner, she found it challenging at first to adapt to the new social norms.","exampleCN":"作为外国人，起初她发现适应新的社会规范很有挑战性。","extra":""},{"chapter":7,"key":"7:20","id":20,"word":"alien","phonetic":"/ˈeɪliən/","pos":"n.","meaningCN":"外侨；外星生物 adj. 外国的；陌生的","tag":"高频","root":"alienate v. 使疏远，使不友好；离间","exampleEN":"Arriving in a foreign city alone can make anyone feel alien and isolated.","exampleCN":"独自抵达陌生城市会让人感到疏离和孤立。","extra":"搭配：an alien culture 异域文化。"},{"chapter":7,"key":"7:21","id":21,"word":"anthropologist","phonetic":"/ˌænθrəˈpɒlədʒɪst/","pos":"n.","meaningCN":"人类学家","tag":"低频","root":"anthropology n. 人类学","exampleEN":"Anthropologists often live within a community for months to study its social structures.","exampleCN":"人类学家常常在社区中生活数月，以研究其社会结构。","extra":""},{"chapter":7,"key":"7:22","id":22,"word":"humanitarian","phonetic":"/hjuːˌmænɪˈteəriən/","pos":"n.","meaningCN":"人道主义者 adj. 人道主义的，博爱的","tag":"低频","root":"","exampleEN":"The organisation is known for its humanitarian efforts in regions affected by natural disasters.","exampleCN":"该组织以在受自然灾害影响地区的人道主义工作而闻名。","extra":""},{"chapter":7,"key":"7:23","id":23,"word":"heritage","phonetic":"/ˈherɪtɪdʒ/","pos":"n.","meaningCN":"（国家的）遗产","tag":"高频","root":"","exampleEN":"The ancient temple has been listed as a World Heritage site by UNESCO.","exampleCN":"这座古庙已被联合国教科文组织列为世界遗产。","extra":"cultural heritage 文化遗产。"},{"chapter":7,"key":"7:24","id":24,"word":"inherit","phonetic":"/ɪnˈherɪt/","pos":"v.","meaningCN":"继承（财产等）；经遗传获得","tag":"高频","root":"inheritance n. 继承；遗产","exampleEN":"She inherited a collection of rare books from her grandfather.","exampleCN":"她从祖父那里继承了一批珍本书籍。","extra":""},{"chapter":7,"key":"7:25","id":25,"word":"antique","phonetic":"/ænˈtiːk/","pos":"n.","meaningCN":"古董 adj. 古董的","tag":"低频","root":"","exampleEN":"The antique vase was carefully restored to preserve its original beauty.","exampleCN":"这只古董花瓶被精心修复，以保留其原有的美感。","extra":""},{"chapter":7,"key":"7:26","id":26,"word":"archaeology","phonetic":"/ˌɑːkiˈɒlədʒi/","pos":"n.","meaningCN":"考古学","tag":"高频","root":"archaeological adj. 考古学的； archaeologist n. 考古学家","exampleEN":"Advances in archaeology have revealed new information about early human settlements.","exampleCN":"考古学的进步揭示了关于早期人类定居点的新信息。","extra":""},{"chapter":7,"key":"7:27","id":27,"word":"excavate","phonetic":"/ˈekskəveɪt/","pos":"v.","meaningCN":"挖掘，发掘","tag":"低频","root":"excavation n. 挖掘，发掘","exampleEN":"The team began to excavate the site where ancient pottery had been discovered.","exampleCN":"团队开始在发现古代陶器的地方进行挖掘。","extra":""},{"chapter":7,"key":"7:28","id":28,"word":"museum","phonetic":"/mjuːˈziːəm/","pos":"n.","meaningCN":"博物馆","tag":"核心","root":"来自 Muse（缪斯女神），um 表示地点，即缪斯女神的圣殿","exampleEN":"The museum offers free guided tours to help visitors understand the historical exhibits.","exampleCN":"博物馆提供免费导览，帮助参观者理解历史展品。","extra":""},{"chapter":7,"key":"7:29","id":29,"word":"pottery","phonetic":"/ˈpɒtəri/","pos":"n.","meaningCN":"陶器","tag":"低频","root":"pot n. 壶，罐子","exampleEN":"Beautiful hand-painted pottery from the region is popular with tourists.","exampleCN":"该地区精美的手绘陶器很受游客欢迎。","extra":""},{"chapter":7,"key":"7:30","id":30,"word":"engrave","phonetic":"/ɪnˈɡreɪv/","pos":"v.","meaningCN":"在......上雕刻","tag":"识记","root":"","exampleEN":"The watchmaker can engrave your initials on the back of the timepiece.","exampleCN":"钟表匠可以在表背上雕刻你名字的首字母。","extra":""},{"chapter":7,"key":"7:31","id":31,"word":"decorate","phonetic":"/ˈdekəreɪt/","pos":"v.","meaningCN":"装饰","tag":"核心","root":"decoration n. 装饰；装饰品； decorative adj. 装饰性的","exampleEN":"They decorated the hall with colourful banners and balloons for the cultural festival.","exampleCN":"他们用彩旗和气球装饰大厅，迎接文化节。","extra":"搭配：decorate A with B。"},{"chapter":7,"key":"7:32","id":32,"word":"religion","phonetic":"/rɪˈlɪdʒən/","pos":"n.","meaningCN":"宗教，宗教信仰","tag":"核心","root":"religious adj. 宗教的","exampleEN":"Religion has played a significant role in shaping art and architecture throughout history.","exampleCN":"纵观历史，宗教在塑造艺术和建筑方面发挥了重要作用。","extra":""},{"chapter":7,"key":"7:33","id":33,"word":"ritual","phonetic":"/ˈrɪtʃuəl/","pos":"n.","meaningCN":"仪式","tag":"高频","root":"","exampleEN":"Morning tea is a daily ritual that helps many people start the day calmly.","exampleCN":"早茶是许多人平静开启一天的日常仪式。","extra":""},{"chapter":7,"key":"7:34","id":34,"word":"etiquette","phonetic":"/ˈetɪket/","pos":"n.","meaningCN":"礼仪，礼节","tag":"低频","root":"法语借词，原指标签，签条；与 ticket 同源","exampleEN":"Understanding local dining etiquette can help you avoid embarrassment at formal dinners.","exampleCN":"了解当地用餐礼仪有助于在正式晚宴上避免尴尬。","extra":""},{"chapter":7,"key":"7:35","id":35,"word":"belief","phonetic":"/bɪˈliːf/","pos":"n.","meaningCN":"信念；信仰","tag":"核心","root":"believe v. 相信；认为","exampleEN":"Her strong belief in justice motivated her to become a human rights lawyer.","exampleCN":"她对正义的坚定信念激励她成为了一名维权律师。","extra":""},{"chapter":7,"key":"7:36","id":36,"word":"soul","phonetic":"/səʊl/","pos":"n.","meaningCN":"灵魂；心灵；精神","tag":"高频","root":"","exampleEN":"Music has the power to touch the soul and express emotions beyond words.","exampleCN":"音乐具有触动灵魂、表达文字之外情感的力量。","extra":"搭配：put one's heart and soul into sth. 全身心投入。"},{"chapter":7,"key":"7:37","id":37,"word":"spirit","phonetic":"/ˈspɪrɪt/","pos":"n.","meaningCN":"精神，心灵","tag":"核心","root":"spiritual adj. 精神上的","exampleEN":"The team showed great fighting spirit, even when they were losing the match.","exampleCN":"即使比赛失利，队员们也展现了昂扬的斗志。","extra":""},{"chapter":7,"key":"7:38","id":38,"word":"sacred","phonetic":"/ˈseɪkrɪd/","pos":"adj.","meaningCN":"神圣的；宗教的","tag":"高频","root":"","exampleEN":"The mountain is considered sacred by the indigenous people who live nearby.","exampleCN":"附近的原住民认为这座山是神圣的。","extra":""},{"chapter":7,"key":"7:39","id":39,"word":"hallowed","phonetic":"/ˈhæləʊd/","pos":"adj.","meaningCN":"神圣的；受尊崇的","tag":"识记","root":"","exampleEN":"The hallowed halls of the ancient university have inspired generations of scholars.","exampleCN":"这所古老大学神圣的殿堂激励了一代又一代学者。","extra":""},{"chapter":7,"key":"7:40","id":40,"word":"holy","phonetic":"/ˈhəʊli/","pos":"adj.","meaningCN":"神圣的；圣洁的，虔诚的","tag":"高频","root":"","exampleEN":"The city is regarded as a holy place by followers of several different faiths.","exampleCN":"这座城市被几种不同信仰的信徒视为圣地。","extra":""},{"chapter":7,"key":"7:41","id":41,"word":"Pope","phonetic":"/pəʊp/","pos":"n.","meaningCN":"教皇","tag":"识记","root":"","exampleEN":"The Pope delivered a message of peace during his address to the large crowd.","exampleCN":"教皇在对广大人群的讲话中传达了和平之意。","extra":""},{"chapter":7,"key":"7:42","id":42,"word":"bishop","phonetic":"/ˈbɪʃəp/","pos":"n.","meaningCN":"主教","tag":"识记","root":"","exampleEN":"The bishop led the service at the cathedral on Easter Sunday.","exampleCN":"复活节当天，主教在大教堂主持了礼拜仪式。","extra":""},{"chapter":7,"key":"7:43","id":43,"word":"missionary","phonetic":"/ˈmɪʃənəri/","pos":"n.","meaningCN":"传教士","tag":"识记","root":"mission n. 使命","exampleEN":"The missionary spent years learning the local language before beginning his work.","exampleCN":"传教士花了数年时间学习当地语言才开始工作。","extra":""},{"chapter":7,"key":"7:44","id":44,"word":"priest","phonetic":"/priːst/","pos":"n.","meaningCN":"牧师；神父；教士","tag":"低频","root":"","exampleEN":"The village priest was highly respected for his wisdom and kindness.","exampleCN":"村里的牧师因其智慧和善良而备受尊敬。","extra":""},{"chapter":7,"key":"7:45","id":45,"word":"Bible","phonetic":"/ˈbaɪbəl/","pos":"n.","meaningCN":"基督教的《圣经》","tag":"低频","root":"","exampleEN":"Stories from the Bible have influenced art and literature for centuries.","exampleCN":"《圣经》中的故事数个世纪以来一直影响着艺术和文学。","extra":""},{"chapter":7,"key":"7:46","id":46,"word":"church","phonetic":"/tʃɜːtʃ/","pos":"n.","meaningCN":"教堂","tag":"核心","root":"","exampleEN":"The small stone church on the hill dates back to the twelfth century.","exampleCN":"山上的小石教堂可追溯至十二世纪。","extra":""},{"chapter":7,"key":"7:47","id":47,"word":"cathedral","phonetic":"/kəˈθiːdrəl/","pos":"n.","meaningCN":"大教堂","tag":"低频","root":"","exampleEN":"Tourists gathered in the square to admire the Gothic architecture of the cathedral.","exampleCN":"游客们聚集在广场上，欣赏大教堂的哥特式建筑。","extra":""},{"chapter":7,"key":"7:48","id":48,"word":"choir","phonetic":"/kwaɪə/","pos":"n.","meaningCN":"唱诗班","tag":"识记","root":"","exampleEN":"The church choir practised every Wednesday evening to prepare for Sunday services.","exampleCN":"教堂唱诗班每周三晚上排练，为周日的礼拜做准备。","extra":""},{"chapter":7,"key":"7:49","id":49,"word":"monk","phonetic":"/mʌŋk/","pos":"n.","meaningCN":"僧侣","tag":"低频","root":"","exampleEN":"The monk spent hours each day in meditation and prayer.","exampleCN":"僧侣每天花数小时冥想和祈祷。","extra":""},{"chapter":7,"key":"7:50","id":50,"word":"temple","phonetic":"/ˈtempəl/","pos":"n.","meaningCN":"寺院，庙宇","tag":"核心","root":"","exampleEN":"Visitors are asked to remove their shoes before entering the temple.","exampleCN":"参观者被要求在进入寺庙前脱鞋。","extra":""},{"chapter":7,"key":"7:51","id":51,"word":"pagoda","phonetic":"/pəˈɡəʊdə/","pos":"n.","meaningCN":"佛塔","tag":"识记","root":"","exampleEN":"The ancient pagoda stands on a hill overlooking the river.","exampleCN":"古佛塔矗立在山上，俯瞰河流。","extra":""},{"chapter":7,"key":"7:52","id":52,"word":"empire","phonetic":"/ˈempaɪə/","pos":"n.","meaningCN":"帝国","tag":"高频","root":"","exampleEN":"The Roman Empire expanded across much of Europe and the Mediterranean region.","exampleCN":"罗马帝国曾扩张至欧洲和地中海地区的许多地方。","extra":""},{"chapter":7,"key":"7:53","id":53,"word":"imperial","phonetic":"/ɪmˈpɪəriəl/","pos":"adj.","meaningCN":"帝国的","tag":"低频","root":"","exampleEN":"The imperial palace was once the residence of emperors and their royal families.","exampleCN":"皇宫曾是皇帝及其皇室的居所。","extra":""},{"chapter":7,"key":"7:54","id":54,"word":"royal","phonetic":"/ˈrɔɪəl/","pos":"adj.","meaningCN":"皇家的；高贵的","tag":"核心","root":"royalty n. 王室成员，皇族","exampleEN":"The royal wedding attracted a global television audience of millions.","exampleCN":"皇家婚礼吸引了全球数百万电视观众。","extra":""},{"chapter":7,"key":"7:55","id":55,"word":"dynasty","phonetic":"/ˈdɪnəsti/","pos":"n.","meaningCN":"朝代","tag":"高频","root":"","exampleEN":"The Ming Dynasty is remembered for its achievements in art and overseas exploration.","exampleCN":"明朝因其在艺术和海外探索方面的成就而被铭记。","extra":""},{"chapter":7,"key":"7:56","id":56,"word":"chronology","phonetic":"/krəˈnɒlədʒi/","pos":"n.","meaningCN":"年表，事件发生顺序表；年代学","tag":"识记","root":"chron 意为“时间（time）”，如：chronic（长期的，慢性的）","exampleEN":"The teacher drew a timeline on the board to show the chronology of the major historical events.","exampleCN":"老师在黑板上画了一条时间线来展示主要历史事件的顺序。","extra":""},{"chapter":7,"key":"7:57","id":57,"word":"emperor","phonetic":"/ˈempərə/","pos":"n.","meaningCN":"皇帝","tag":"高频","root":"","exampleEN":"The young emperor's reign brought a period of stability and growth to the kingdom.","exampleCN":"年轻皇帝的统治给王国带来了一个稳定和发展的时期。","extra":""},{"chapter":7,"key":"7:58","id":58,"word":"king","phonetic":"/kɪŋ/","pos":"n.","meaningCN":"国王","tag":"核心","root":"kingdom n. 王国","exampleEN":"The king addressed his people from the balcony of the palace on the national holiday.","exampleCN":"国庆日，国王在宫殿阳台上向人民发表讲话。","extra":""},{"chapter":7,"key":"7:59","id":59,"word":"queen","phonetic":"/kwiːn/","pos":"n.","meaningCN":"王后；女王","tag":"核心","root":"","exampleEN":"The queen was known for her wisdom and dedication to public service.","exampleCN":"女王以其智慧和对公共服务的奉献而闻名。","extra":""},{"chapter":7,"key":"7:60","id":60,"word":"prince","phonetic":"/prɪns/","pos":"n.","meaningCN":"王子；亲王","tag":"高频","root":"","exampleEN":"The prince studied at a prestigious university before returning to serve his country.","exampleCN":"王子在一所顶尖大学学习后，回国服务。","extra":""},{"chapter":7,"key":"7:61","id":61,"word":"princess","phonetic":"/prɪnˈses/","pos":"n.","meaningCN":"公主；王妃","tag":"高频","root":"","exampleEN":"The princess became actively involved in charities supporting children's education.","exampleCN":"公主积极参与支持儿童教育的慈善机构。","extra":""},{"chapter":7,"key":"7:62","id":62,"word":"majesty","phonetic":"/ˈmædʒəsti/","pos":"n.","meaningCN":"威严，壮观；陛下","tag":"低频","root":"majestic adj. 宏伟的，庄严的","exampleEN":"The majesty of the snow-covered mountains left the travellers speechless.","exampleCN":"白雪皑皑的群山的壮观让旅行者们无言以对。","extra":""},{"chapter":7,"key":"7:63","id":63,"word":"nobility","phonetic":"/nəʊˈbɪlɪti/","pos":"n.","meaningCN":"高尚的品质；贵族","tag":"低频","root":"noble adj. 贵族的；高贵的 n. 贵族成员","exampleEN":"Her nobility of spirit shone through in the way she treated everyone with kindness.","exampleCN":"她高尚的精神体现在她善待每个人的方式上。","extra":""},{"chapter":7,"key":"7:64","id":64,"word":"lord","phonetic":"/lɔːd/","pos":"n.","meaningCN":"（英国）贵族；[L-]阁下，大人；[the L-]上帝","tag":"低频","root":"","exampleEN":"The lord of the manor was responsible for managing the village and protecting its people.","exampleCN":"庄园的领主负责管理村庄并保护其人民。","extra":""},{"chapter":7,"key":"7:65","id":65,"word":"knight","phonetic":"/naɪt/","pos":"n.","meaningCN":"骑士 v. 封（某人）为爵士","tag":"低频","root":"","exampleEN":"The knight swore an oath to defend the king and the realm with his life.","exampleCN":"骑士宣誓，要用生命保卫国王和王国。","extra":""},{"chapter":7,"key":"7:66","id":66,"word":"guardian","phonetic":"/ˈɡɑːdiən/","pos":"n.","meaningCN":"保卫者；监护人 adj. 守护的","tag":"低频","root":"guard v. 保护 n. 守卫","exampleEN":"After the child's parents passed away, the grandmother became her legal guardian.","exampleCN":"孩子的父母去世后，祖母成了她的法定监护人。","extra":""},{"chapter":7,"key":"7:67","id":67,"word":"nostalgia","phonetic":"/nɒˈstældʒə/","pos":"n.","meaningCN":"思乡之情；怀旧之情","tag":"高频","root":"","exampleEN":"Listening to songs from her youth filled her with a sense of nostalgia.","exampleCN":"听着年轻时的歌曲，她心中充满了怀旧之情。","extra":""},{"chapter":7,"key":"7:68","id":68,"word":"homesick","phonetic":"/ˈhəʊmsɪk/","pos":"adj.","meaningCN":"思乡的","tag":"高频","root":"homesickness n. 思乡情绪","exampleEN":"During her first month studying abroad, she often felt homesick for her family's cooking.","exampleCN":"在国外留学的第一个月，她常因想念家里的饭菜而想家。","extra":""},{"chapter":7,"key":"7:69","id":69,"word":"anecdote","phonetic":"/ˈænɪkdəʊt/","pos":"n.","meaningCN":"轶事，奇闻","tag":"低频","root":"don/dot 表示“给”，如：anecdote（不向外给 → 未传开的事 → 轶事），donor（献血者），pardon（原谅）","exampleEN":"The professor began the lecture with a funny anecdote about his own college days.","exampleCN":"教授用一则关于自己大学时代的趣闻轶事开始了讲座。","extra":""},{"chapter":7,"key":"7:70","id":70,"word":"accident","phonetic":"/ˈæksɪdənt/","pos":"n.","meaningCN":"事故；意外，偶然的事","tag":"核心","root":"accidental adj. 意外的，偶然的","exampleEN":"Historians believe that many great discoveries were made entirely by accident.","exampleCN":"历史学家认为，许多伟大的发现纯属偶然。","extra":"搭配：by accident 偶然。"},{"chapter":7,"key":"7:71","id":71,"word":"incident","phonetic":"/ˈɪnsɪdənt/","pos":"n.","meaningCN":"（尤指不寻常的、重要的或暴力的）事件；（两国间的）冲突","tag":"核心","root":"incidental adj. 附带的，次要的","exampleEN":"The border incident led to increased tension between the two neighbouring countries.","exampleCN":"边境事件导致两个邻国之间的紧张局势加剧。","extra":""},{"chapter":7,"key":"7:72","id":72,"word":"celebrity","phonetic":"/sɪˈlebrɪti/","pos":"n.","meaningCN":"名人；名誉","tag":"高频","root":"","exampleEN":"The celebrity used her fame to raise awareness about environmental issues.","exampleCN":"这位名人利用自己的名气来提高人们对环境问题的意识。","extra":""},{"chapter":7,"key":"7:73","id":73,"word":"status","phonetic":"/ˈsteɪtəs/","pos":"n.","meaningCN":"地位，身份","tag":"核心","root":"","exampleEN":"In some traditional societies, a person's status is determined by their family background.","exampleCN":"在一些传统社会中，一个人的地位由家庭背景决定。","extra":"搭配：social status 社会地位。"},{"chapter":7,"key":"7:74","id":74,"word":"background","phonetic":"/ˈbækɡraʊnd/","pos":"n.","meaningCN":"背景；（个人出身、受教育）经历","tag":"核心","root":"","exampleEN":"Students from diverse cultural backgrounds bring valuable perspectives to the classroom.","exampleCN":"来自不同文化背景的学生为课堂带来了宝贵的观点。","extra":""},{"chapter":7,"key":"7:75","id":75,"word":"experience","phonetic":"/ɪkˈspɪəriəns/","pos":"n.","meaningCN":"经验；（一次）经历，体验","tag":"核心","root":"experienced adj. 经验丰富的","exampleEN":"Volunteering abroad can be a life-changing experience that broadens your worldview.","exampleCN":"海外志愿服务可以是一次改变人生的经历，能拓宽你的世界观。","extra":""},{"chapter":7,"key":"7:76","id":76,"word":"thrive","phonetic":"/θraɪv/","pos":"v.","meaningCN":"繁荣，兴旺发达；茁壮生长","tag":"高频","root":"","exampleEN":"Cultural industries thrive when governments invest in the arts and creative sectors.","exampleCN":"当政府投资于艺术和创意产业时，文化产业就会蓬勃发展。","extra":""},{"chapter":7,"key":"7:77","id":77,"word":"prosperity","phonetic":"/prɒˈsperɪti/","pos":"n.","meaningCN":"繁荣，兴旺","tag":"高频","root":"prosper v. 成功，繁荣； prosperous adj. 繁荣的","exampleEN":"The period of economic prosperity led to a flourishing of literature and philosophy.","exampleCN":"经济繁荣的时期带来了文学和哲学的蓬勃发展。","extra":""},{"chapter":7,"key":"7:78","id":78,"word":"setback","phonetic":"/ˈsetbæk/","pos":"n.","meaningCN":"挫折，阻碍","tag":"高频","root":"","exampleEN":"The destruction of the library was a major setback for preserving the country's cultural heritage.","exampleCN":"图书馆被毁是保护该国文化遗产的重大挫折。","extra":"搭配：a business setback 生意上的挫折。"},{"chapter":7,"key":"7:79","id":79,"word":"adversity","phonetic":"/ædˈvɜːsɪti/","pos":"n.","meaningCN":"逆境","tag":"低频","root":"","exampleEN":"Many great works of literature were produced by authors who had faced personal adversity.","exampleCN":"许多伟大的文学作品都是由经历过个人逆境的作家创作的。","extra":""}],"8":[{"chapter":8,"key":"8:1","id":1,"word":"language","phonetic":"/ˈlæŋɡwɪdʒ/","pos":"n.","meaningCN":"语言","tag":"核心","root":"","exampleEN":"Learning a programming language can be challenging but rewarding for your career.","exampleCN":"学习一门编程语言对职业发展来说既具挑战性又有回报。","extra":"搭配：body language（身体语言）"},{"chapter":8,"key":"8:2","id":2,"word":"symbol","phonetic":"/ˈsɪmbəl/","pos":"n.","meaningCN":"象征；符号，记号","tag":"核心","root":"","exampleEN":"The red rose has long been a symbol of love and passion in many cultures.","exampleCN":"红玫瑰在许多文化中长期以来一直是爱情和激情的象征。","extra":"动词：symbolise（象征）"},{"chapter":8,"key":"8:3","id":3,"word":"sign","phonetic":"/saɪn/","pos":"n./v.","meaningCN":"符号；征兆，迹象；手势 v. 签（名）","tag":"核心","root":"","exampleEN":"A sudden drop in temperature is usually a sign that winter is approaching.","exampleCN":"气温突然下降通常是冬天临近的迹象。","extra":"搭配：sign up（报名）；sign language（手语）"},{"chapter":8,"key":"8:4","id":4,"word":"gesture","phonetic":"/ˈdʒestʃə/","pos":"n.","meaningCN":"手势，姿势","tag":"核心","root":"","exampleEN":"A simple wave of the hand is a common gesture of greeting around the world.","exampleCN":"简单的挥手是世界各地常见的问候手势。","extra":"搭配：make a gesture（做手势）"},{"chapter":8,"key":"8:5","id":5,"word":"handwriting","phonetic":"/ˈhændˌraɪtɪŋ/","pos":"n.","meaningCN":"笔迹；书写","tag":"高频","root":"","exampleEN":"The doctor's handwriting was so messy that the pharmacist could barely read it.","exampleCN":"医生的笔迹太潦草，药剂师几乎看不懂。","extra":"相关：handwritten（手写的）"},{"chapter":8,"key":"8:6","id":6,"word":"pictograph","phonetic":"/ˈpɪktəˌɡræf/","pos":"n.","meaningCN":"象形文字","tag":"识记","root":"","exampleEN":"Ancient cave paintings are considered early pictographs used to record daily life.","exampleCN":"古代洞穴壁画被认为是用以记录日常生活的早期象形文字。","extra":"同义词：pictogram"},{"chapter":8,"key":"8:7","id":7,"word":"wedge","phonetic":"/wedʒ/","pos":"n.","meaningCN":"楔子；楔形物；楔形文字","tag":"识记","root":"","exampleEN":"The carpenter drove a wedge between the boards to split them apart.","exampleCN":"木匠在两块木板之间打入楔子将其劈开。","extra":"形容词：wedge-shaped（楔形的）"},{"chapter":8,"key":"8:8","id":8,"word":"knot","phonetic":"/nɒt/","pos":"n.","meaningCN":"（绳、线等的）结；（树枝上的）节子","tag":"高频","root":"","exampleEN":"He tied a tight knot in the rope to secure the boat to the dock.","exampleCN":"他在绳子上打了个紧紧的结，把船固定在码头上。","extra":"搭配：tie a knot（打结）；cut the knot（快刀斩乱麻）"},{"chapter":8,"key":"8:9","id":9,"word":"linguistics","phonetic":"/lɪŋˈɡwɪstɪks/","pos":"n.","meaningCN":"语言学","tag":"核心","root":"","exampleEN":"Linguistics helps us understand how children acquire their native language so effortlessly.","exampleCN":"语言学帮助我们理解儿童为何能如此轻松地习得母语。","extra":"形容词：linguistic；派生词：linguist（语言学家）"},{"chapter":8,"key":"8:10","id":10,"word":"semantic","phonetic":"/sɪˈmæntɪk/","pos":"n.","meaningCN":"语义的","tag":"高频","root":"","exampleEN":"The word 'literally' has undergone a semantic shift in recent years.","exampleCN":"近年来，'literally'一词发生了语义上的变化。","extra":"名词：semantics（语义学）"},{"chapter":8,"key":"8:11","id":11,"word":"syntax","phonetic":"/ˈsɪntæks/","pos":"n.","meaningCN":"句法","tag":"核心","root":"","exampleEN":"English syntax typically follows a subject-verb-object order in declarative sentences.","exampleCN":"英语句法在陈述句中通常遵循主谓宾顺序。","extra":"形容词：syntactic"},{"chapter":8,"key":"8:12","id":12,"word":"grammar","phonetic":"/ˈɡræmə/","pos":"n.","meaningCN":"语法；语法书","tag":"核心","root":"","exampleEN":"Understanding basic grammar rules can help you avoid common mistakes in writing.","exampleCN":"理解基本语法规则有助于你在写作中避免常见错误。","extra":"形容词：grammatical"},{"chapter":8,"key":"8:13","id":13,"word":"phonetics","phonetic":"/fəˈnetɪks/","pos":"n.","meaningCN":"语音学","tag":"核心","root":"","exampleEN":"Phonetics focuses on the physical properties of speech sounds, not their meaning.","exampleCN":"语音学研究语音的物理属性，而非其含义。","extra":"形容词：phonetic"},{"chapter":8,"key":"8:14","id":14,"word":"pronounce","phonetic":"/prəˈnaʊns/","pos":"v.","meaningCN":"发......的音；宣布","tag":"核心","root":"","exampleEN":"Many English learners find it difficult to pronounce the 'th' sound correctly.","exampleCN":"许多英语学习者发现正确发出'th'音很困难。","extra":"名词：pronunciation（发音）"},{"chapter":8,"key":"8:15","id":15,"word":"intonation","phonetic":"/ˌɪntəˈneɪʃən/","pos":"n.","meaningCN":"语调","tag":"核心","root":"","exampleEN":"Rising intonation at the end of a sentence usually indicates a question in English.","exampleCN":"英语中句末的升调通常表示疑问。","extra":"搭配：falling intonation（降调）"},{"chapter":8,"key":"8:16","id":16,"word":"inflection","phonetic":"/ɪnˈflekʃən/","pos":"n.","meaningCN":"语调的抑扬变化","tag":"高频","root":"","exampleEN":"Her voice lacked any inflection, making her speech sound monotonous and boring.","exampleCN":"她的声音缺乏抑扬变化，让演讲听起来单调乏味。","extra":"动词：inflect"},{"chapter":8,"key":"8:17","id":17,"word":"dialect","phonetic":"/ˈdaɪəlekt/","pos":"n.","meaningCN":"方言，地方话","tag":"核心","root":"dia（在……之间）+ lect（说）","exampleEN":"People from different regions often speak distinct dialects of the same language.","exampleCN":"来自不同地区的人们通常说同一种语言的不同方言。","extra":"形容词：dialectal"},{"chapter":8,"key":"8:18","id":18,"word":"accent","phonetic":"/ˈæksənt/","pos":"n.","meaningCN":"重音；口音；读音符号","tag":"核心","root":"ac（加强意义）+ cent（歌唱）","exampleEN":"Even after living abroad for ten years, he still speaks with a strong native accent.","exampleCN":"即使在国外住了十年，他说话仍带有浓重的母语口音。","extra":"搭配：foreign accent（外国口音）"},{"chapter":8,"key":"8:19","id":19,"word":"utterance","phonetic":"/ˈʌtərəns/","pos":"n.","meaningCN":"说话；话语","tag":"高频","root":"","exampleEN":"His first utterance after waking up was a request for a glass of water.","exampleCN":"他醒来后说的第一句话是要一杯水。","extra":"动词：utter（说出）"},{"chapter":8,"key":"8:20","id":20,"word":"oral","phonetic":"/ˈɔːrəl/","pos":"adj.","meaningCN":"口头的","tag":"核心","root":"","exampleEN":"The final exam includes both a written test and an oral presentation.","exampleCN":"期末考试包括笔试和口头陈述。","extra":"反义词：written（书面的）"},{"chapter":8,"key":"8:21","id":21,"word":"verbal","phonetic":"/ˈvɜːbəl/","pos":"adj.","meaningCN":"口头的；言语的","tag":"核心","root":"","exampleEN":"Verbal communication is crucial for teamwork and building relationships at work.","exampleCN":"口头沟通对于团队合作和工作中的关系建立至关重要。","extra":"反义词：nonverbal（非语言的）"},{"chapter":8,"key":"8:22","id":22,"word":"syllable","phonetic":"/ˈsɪləbəl/","pos":"n.","meaningCN":"音节","tag":"核心","root":"","exampleEN":"The word 'beautiful' has three syllables: beau-ti-ful.","exampleCN":"单词'beautiful'有三个音节：beau-ti-ful。","extra":"搭配：stressed syllable（重读音节）"},{"chapter":8,"key":"8:23","id":23,"word":"phoneme","phonetic":"/ˈfəʊniːm/","pos":"n.","meaningCN":"音位","tag":"识记","root":"","exampleEN":"English has about 44 phonemes, which are the basic units of sound in the language.","exampleCN":"英语约有44个音位，它们是该语言中的基本声音单位。","extra":"形容词：phonemic"},{"chapter":8,"key":"8:24","id":24,"word":"vowel","phonetic":"/ˈvaʊəl/","pos":"n.","meaningCN":"元音","tag":"核心","root":"","exampleEN":"The letter 'y' can sometimes function as a vowel, as in the word 'myth'.","exampleCN":"字母'y'有时可以作为元音使用，如在单词'myth'中。","extra":"对比：consonant（辅音）"},{"chapter":8,"key":"8:25","id":25,"word":"consonant","phonetic":"/ˈkɒnsənənt/","pos":"n.","meaningCN":"辅音","tag":"核心","root":"","exampleEN":"The word 'strength' contains eight consonants and only two vowels.","exampleCN":"单词'strength'包含八个辅音，只有两个元音。","extra":"搭配：consonant cluster（辅音连缀）"},{"chapter":8,"key":"8:26","id":26,"word":"alphabet","phonetic":"/ˈælfəbet/","pos":"n.","meaningCN":"字母表，（一种语言的）全部字母","tag":"核心","root":"","exampleEN":"The English alphabet has 26 letters, from A to Z.","exampleCN":"英语字母表有26个字母，从A到Z。","extra":"形容词：alphabetical（按字母顺序的）"},{"chapter":8,"key":"8:27","id":27,"word":"logogram","phonetic":"/ˈlɒɡəɡræm/","pos":"n.","meaningCN":"词符，缩记符","tag":"识记","root":"","exampleEN":"Chinese characters are logograms, where each symbol represents a word or morpheme.","exampleCN":"汉字是词符文字，每个符号代表一个词或语素。","extra":"也称作logograph"},{"chapter":8,"key":"8:28","id":28,"word":"vocabulary","phonetic":"/vəˈkæbjələri/","pos":"n.","meaningCN":"词汇","tag":"核心","root":"voc（声音）","exampleEN":"Reading extensively is one of the best ways to expand your vocabulary.","exampleCN":"广泛阅读是扩大词汇量的最佳方法之一。","extra":"相关：vocab（缩写）"},{"chapter":8,"key":"8:29","id":29,"word":"dictionary","phonetic":"/ˈdɪkʃənəri/","pos":"n.","meaningCN":"词典，字典，辞典","tag":"核心","root":"","exampleEN":"A good dictionary provides not only definitions but also example sentences and pronunciation.","exampleCN":"一本好词典不仅提供定义，还提供例句和发音。","extra":"相关：diction（措辞）"},{"chapter":8,"key":"8:30","id":30,"word":"idiom","phonetic":"/ˈɪdiəm/","pos":"n.","meaningCN":"习语","tag":"高频","root":"","exampleEN":"The idiom 'break a leg' is used to wish someone good luck before a performance.","exampleCN":"习语'break a leg'用于在表演前祝某人好运。","extra":"形容词：idiomatic"},{"chapter":8,"key":"8:31","id":31,"word":"phrase","phonetic":"/freɪz/","pos":"n.","meaningCN":"短语；习语","tag":"核心","root":"","exampleEN":"The phrase 'in a nutshell' means to describe something briefly and concisely.","exampleCN":"短语'in a nutshell'意为简明扼要地描述某事。","extra":"动词：phrase（措辞）"},{"chapter":8,"key":"8:32","id":32,"word":"clause","phonetic":"/klɔːz/","pos":"n.","meaningCN":"分句，从句；条款","tag":"高频","root":"","exampleEN":"An independent clause can stand alone as a complete sentence.","exampleCN":"独立分句可以单独作为一个完整的句子。","extra":"搭配：main clause（主句），subordinate clause（从句）"},{"chapter":8,"key":"8:33","id":33,"word":"expression","phonetic":"/ɪkˈspreʃən/","pos":"n.","meaningCN":"词语；表达；表情","tag":"核心","root":"","exampleEN":"A puzzled expression crossed his face when he heard the unexpected news.","exampleCN":"听到这个意外的消息时，他脸上露出了困惑的表情。","extra":"动词：express（表达）"},{"chapter":8,"key":"8:34","id":34,"word":"tense","phonetic":"/tens/","pos":"n.","meaningCN":"时态 adj. 紧张的","tag":"核心","root":"","exampleEN":"She always gets tense before speaking in public, but once she starts, she relaxes.","exampleCN":"她在公开演讲前总是很紧张，但一开始演讲就放松了。","extra":"名词：tension（紧张）"},{"chapter":8,"key":"8:35","id":35,"word":"root","phonetic":"/ruːt/","pos":"n.","meaningCN":"词根，字根；根源","tag":"核心","root":"","exampleEN":"The root 'scrib' means 'write', which appears in words like 'describe' and 'manuscript'.","exampleCN":"词根'scrib'意为'写'，出现在'describe'和'manuscript'等词中。","extra":"搭配：root word（词根）"},{"chapter":8,"key":"8:36","id":36,"word":"prefix","phonetic":"/ˈpriːfɪks/","pos":"n.","meaningCN":"词首，前缀；前置代号","tag":"核心","root":"","exampleEN":"Adding the prefix 'un-' to 'happy' changes the meaning to 'not happy'.","exampleCN":"在'happy'前加上前缀'un-'，意思变为'不快乐'。","extra":"对比：suffix（后缀）"},{"chapter":8,"key":"8:37","id":37,"word":"suffix","phonetic":"/ˈsʌfɪks/","pos":"n.","meaningCN":"后缀，词尾；尾标","tag":"核心","root":"","exampleEN":"The suffix '-ful' turns the noun 'joy' into the adjective 'joyful'.","exampleCN":"后缀'-ful'将名词'joy'变成形容词'joyful'。","extra":"对比：prefix（前缀）"},{"chapter":8,"key":"8:38","id":38,"word":"abbreviation","phonetic":"/əˌbriːviˈeɪʃən/","pos":"n.","meaningCN":"缩写形式","tag":"高频","root":"","exampleEN":"'Dr.' is a common abbreviation for the title 'Doctor'.","exampleCN":"'Dr.'是头衔'Doctor'的常见缩写。","extra":"动词：abbreviate（缩写）"},{"chapter":8,"key":"8:39","id":39,"word":"synonym","phonetic":"/ˈsɪnənɪm/","pos":"n.","meaningCN":"同义词","tag":"核心","root":"","exampleEN":"'Happy' and 'joyful' are synonyms, as they have similar meanings.","exampleCN":"'Happy'和'joyful'是同义词，因为它们意思相近。","extra":"反义词：antonym（反义词）"},{"chapter":8,"key":"8:40","id":40,"word":"antonym","phonetic":"/ˈæntənɪm/","pos":"n.","meaningCN":"反义词","tag":"核心","root":"","exampleEN":"'Hot' is the antonym of 'cold' because they express opposite temperatures.","exampleCN":"'Hot'是'cold'的反义词，因为它们表达相反的温度。","extra":"对比：synonym（同义词）"},{"chapter":8,"key":"8:41","id":41,"word":"noun","phonetic":"/naʊn/","pos":"n.","meaningCN":"名词","tag":"核心","root":"","exampleEN":"In the sentence 'The cat sleeps,' both 'cat' and 'sleeps' are nouns? Actually 'sleeps' is a verb.","exampleCN":"在句子'The cat sleeps'中，'cat'是名词，'sleeps'是动词。","extra":"分类：proper noun（专有名词），common noun（普通名词）"},{"chapter":8,"key":"8:42","id":42,"word":"singular","phonetic":"/ˈsɪŋɡjələ/","pos":"n.","meaningCN":"单数 adj. 单数的；非凡的","tag":"核心","root":"","exampleEN":"The singular form of 'children' is 'child'.","exampleCN":"'children'的单数形式是'child'。","extra":"反义词：plural（复数）"},{"chapter":8,"key":"8:43","id":43,"word":"plural","phonetic":"/ˈplʊərəl/","pos":"n.","meaningCN":"复数 adj. 复数的；多元的","tag":"核心","root":"","exampleEN":"Most English nouns form their plural by adding -s or -es.","exampleCN":"大多数英语名词通过添加-s或-es构成复数。","extra":"搭配：plural society（多元社会）"},{"chapter":8,"key":"8:44","id":44,"word":"pronoun","phonetic":"/ˈprəʊnaʊn/","pos":"n.","meaningCN":"代词","tag":"核心","root":"","exampleEN":"Instead of repeating 'Maria', we can use the pronoun 'she'.","exampleCN":"与其重复'Maria'，我们可以使用代词'she'。","extra":"分类：personal pronoun（人称代词），possessive pronoun（物主代词）"},{"chapter":8,"key":"8:45","id":45,"word":"verb","phonetic":"/vɜːb/","pos":"n.","meaningCN":"动词","tag":"核心","root":"","exampleEN":"Every complete sentence must contain at least one verb.","exampleCN":"每个完整的句子必须至少包含一个动词。","extra":"分类：auxiliary verb（助动词），modal verb（情态动词）"},{"chapter":8,"key":"8:46","id":46,"word":"adjective","phonetic":"/ˈædʒɪktɪv/","pos":"n.","meaningCN":"形容词","tag":"核心","root":"","exampleEN":"Adjectives like 'beautiful', 'tall', and 'red' describe nouns.","exampleCN":"像'beautiful'、'tall'和'red'这样的形容词描述名词。","extra":"比较级：comparative，最高级：superlative"},{"chapter":8,"key":"8:47","id":47,"word":"adverb","phonetic":"/ˈædvɜːb/","pos":"n.","meaningCN":"副词","tag":"核心","root":"","exampleEN":"The adverb 'quickly' modifies the verb 'run' in the sentence 'She runs quickly'.","exampleCN":"副词'quickly'修饰句子'She runs quickly'中的动词'run'。","extra":"常以-ly结尾，但并非全部"},{"chapter":8,"key":"8:48","id":48,"word":"preposition","phonetic":"/ˌprepəˈzɪʃən/","pos":"n.","meaningCN":"介词","tag":"核心","root":"","exampleEN":"Common prepositions include 'in', 'on', 'at', 'for', and 'with'.","exampleCN":"常见的介词包括'in'、'on'、'at'、'for'和'with'。","extra":"相关：position（位置）"},{"chapter":8,"key":"8:49","id":49,"word":"conjunction","phonetic":"/kənˈdʒʌŋkʃən/","pos":"n.","meaningCN":"连词；结合","tag":"核心","root":"","exampleEN":"The conjunction 'and' is used to connect words or phrases in a sentence.","exampleCN":"连词'and'用于连接句子中的单词或短语。","extra":"相关：junction（汇合处）"},{"chapter":8,"key":"8:50","id":50,"word":"consistent","phonetic":"/kənˈsɪstənt/","pos":"adj.","meaningCN":"一致的；（观点或看法）连贯的","tag":"核心","root":"","exampleEN":"Your actions should be consistent with your words if you want people to trust you.","exampleCN":"如果你想让别人信任你，你的行动应该与言语一致。","extra":"反义词：inconsistent；搭配：be consistent with"},{"chapter":8,"key":"8:51","id":51,"word":"complicated","phonetic":"/ˈkɒmplɪkeɪtɪd/","pos":"adj.","meaningCN":"复杂的","tag":"核心","root":"","exampleEN":"The instructions for assembling the furniture were so complicated that I gave up.","exampleCN":"组装家具的说明太复杂了，我放弃了。","extra":"动词：complicate（使复杂化）"},{"chapter":8,"key":"8:52","id":52,"word":"complex","phonetic":"/ˈkɒmpleks/","pos":"adj.","meaningCN":"复杂的","tag":"核心","root":"","exampleEN":"The human brain is an incredibly complex organ that scientists are still studying.","exampleCN":"人脑是一个极其复杂的器官，科学家仍在研究它。","extra":"名词：complexity（复杂性）"},{"chapter":8,"key":"8:53","id":53,"word":"compile","phonetic":"/kəmˈpaɪl/","pos":"v.","meaningCN":"编纂","tag":"高频","root":"","exampleEN":"It took the team five years to compile all the data for the encyclopedia.","exampleCN":"这个团队花了五年时间编纂百科全书的所有数据。","extra":"名词：compilation（汇编）"},{"chapter":8,"key":"8:54","id":54,"word":"version","phonetic":"/ˈvɜːʃən/","pos":"n.","meaningCN":"译本；版本","tag":"核心","root":"","exampleEN":"This is the latest version of the software, with many new features.","exampleCN":"这是该软件的最新版本，有许多新功能。","extra":"搭配：cover version（翻唱版本）"},{"chapter":8,"key":"8:55","id":55,"word":"translate","phonetic":"/trænsˈleɪt/","pos":"v.","meaningCN":"翻译；（使）转变","tag":"核心","root":"","exampleEN":"Can you translate this document from French into English for me?","exampleCN":"你能帮我把这份文件从法语翻译成英语吗？","extra":"名词：translation；搭配：translate into"},{"chapter":8,"key":"8:56","id":56,"word":"paraphrase","phonetic":"/ˈpærəfreɪz/","pos":"v./n.","meaningCN":"意译，改述","tag":"高频","root":"","exampleEN":"The student was asked to paraphrase the poem in his own words.","exampleCN":"老师要求学生用自己的话改述这首诗。","extra":"同义词：rephrase"},{"chapter":8,"key":"8:57","id":57,"word":"interpret","phonetic":"/ɪnˈtɜːprɪt/","pos":"v.","meaningCN":"口译；解释，说明；领会，理解","tag":"核心","root":"","exampleEN":"The guide interpreted the ancient inscriptions for the tourists.","exampleCN":"导游为游客解释了古代铭文的意思。","extra":"名词：interpretation（解释）；interpreter（口译员）"},{"chapter":8,"key":"8:58","id":58,"word":"narrate","phonetic":"/nəˈreɪt/","pos":"v.","meaningCN":"讲（故事），叙述","tag":"高频","root":"","exampleEN":"The witness was asked to narrate the events exactly as they happened.","exampleCN":"目击者被要求如实叙述所发生的事情。","extra":"名词：narration（叙述），narrator（叙述者）"},{"chapter":8,"key":"8:59","id":59,"word":"illuminate","phonetic":"/ɪˈluːmɪneɪt/","pos":"v.","meaningCN":"阐释，说明；照亮","tag":"高频","root":"il（进入）+ lumin（光）","exampleEN":"The professor used diagrams to illuminate the complex theory for the students.","exampleCN":"教授使用图表向学生阐释复杂的理论。","extra":"名词：illumination"},{"chapter":8,"key":"8:60","id":60,"word":"decipher","phonetic":"/dɪˈsaɪfə/","pos":"v.","meaningCN":"译解；辨认","tag":"高频","root":"","exampleEN":"Archaeologists managed to decipher the ancient writing system after years of study.","exampleCN":"经过多年研究，考古学家成功破译了古代文字系统。","extra":"同义词：decode"},{"chapter":8,"key":"8:61","id":61,"word":"eloquence","phonetic":"/ˈeləkwəns/","pos":"n.","meaningCN":"雄辩；流利的口才","tag":"核心","root":"","exampleEN":"The politician's eloquence won over the audience during the debate.","exampleCN":"这位政客的雄辩在辩论中赢得了观众的支持。","extra":"形容词：eloquent（有口才的）"},{"chapter":8,"key":"8:62","id":62,"word":"communicate","phonetic":"/kəˈmjuːnɪkeɪt/","pos":"v.","meaningCN":"沟通，交流；传达","tag":"核心","root":"","exampleEN":"It's important to communicate your feelings clearly to avoid misunderstandings.","exampleCN":"清晰传达你的感受很重要，以避免误解。","extra":"名词：communication；搭配：communicate with"},{"chapter":8,"key":"8:63","id":63,"word":"discussion","phonetic":"/dɪˈskʌʃən/","pos":"n.","meaningCN":"讨论，谈论","tag":"核心","root":"cuss（摇）","exampleEN":"The class had a lively discussion about climate change solutions.","exampleCN":"全班就气候变化解决方案进行了热烈的讨论。","extra":"动词：discuss"},{"chapter":8,"key":"8:64","id":64,"word":"brainstorm","phonetic":"/ˈbreɪnstɔːm/","pos":"n./v.","meaningCN":"集体自由讨论，头脑风暴 v. 集思广益，进行头脑风暴","tag":"高频","root":"","exampleEN":"The team gathered to brainstorm ideas for the new marketing campaign.","exampleCN":"团队聚在一起为新的营销活动集思广益。","extra":"常见于商务和创意场合"},{"chapter":8,"key":"8:65","id":65,"word":"debate","phonetic":"/dɪˈbeɪt/","pos":"v./n.","meaningCN":"辩论；争论，讨论","tag":"核心","root":"","exampleEN":"The candidates will debate each other on live television tonight.","exampleCN":"候选人今晚将在电视直播中辩论。","extra":"形容词：debatable（有争议的）"},{"chapter":8,"key":"8:66","id":66,"word":"commentary","phonetic":"/ˈkɒməntəri/","pos":"n.","meaningCN":"评论，评注；批评；实况报道","tag":"高频","root":"","exampleEN":"The sports channel provides live commentary during football matches.","exampleCN":"体育频道在足球比赛期间提供现场解说。","extra":"动词：comment（评论）"},{"chapter":8,"key":"8:67","id":67,"word":"negotiate","phonetic":"/nɪˈɡəʊʃieɪt/","pos":"v.","meaningCN":"协商，谈判","tag":"核心","root":"","exampleEN":"The two countries are trying to negotiate a trade agreement.","exampleCN":"两国正试图通过谈判达成贸易协议。","extra":"名词：negotiation；搭配：negotiate about"},{"chapter":8,"key":"8:68","id":68,"word":"contention","phonetic":"/kənˈtenʃən/","pos":"n.","meaningCN":"争论，争辩；观点","tag":"高频","root":"","exampleEN":"The main point of contention between the two parties was the budget allocation.","exampleCN":"双方争论的主要焦点是预算分配。","extra":"相关：content（内容）；形容词：contentious"}],"9":[{"chapter":9,"key":"9:1","id":1,"word":"commentator","phonetic":"/ˈkɒmənteɪtə/","pos":"n.","meaningCN":"评论员；实况解说员","tag":"低频","root":"","exampleEN":"The sports commentator described every move of the players with great excitement.","exampleCN":"体育解说员激动地描述了球员的每一个动作。","extra":"动词 comment 评论。"},{"chapter":9,"key":"9:2","id":2,"word":"medium","phonetic":"/ˈmiːdiəm/","pos":"n.","meaningCN":"媒介 adj. 中间的，中等的","tag":"核心","root":"multimedia n. 多媒体； mediator n. 斡旋者； media n. 大众传播媒介，媒体","exampleEN":"Television is a powerful medium for spreading news and cultural ideas.","exampleCN":"电视是传播新闻和文化观念的强大媒介。","extra":"复数 media。"},{"chapter":9,"key":"9:3","id":3,"word":"press","phonetic":"/pres/","pos":"n.","meaningCN":"新闻界，记者；报刊；出版社","tag":"核心","root":"press 指“压”，同源词：compress（压缩），depress（使沮丧），express（表达），impress（给......留下印象）","exampleEN":"The press has a responsibility to report the truth accurately and fairly.","exampleCN":"新闻界有责任准确、公正地报道真相。","extra":"freedom of the press 新闻自由。"},{"chapter":9,"key":"9:4","id":4,"word":"journalist","phonetic":"/ˈdʒɜːnəlɪst/","pos":"n.","meaningCN":"记者，新闻工作者","tag":"核心","root":"","exampleEN":"Investigative journalists often spend months researching a single story.","exampleCN":"调查记者常常花费数月时间研究一篇报道。","extra":""},{"chapter":9,"key":"9:5","id":5,"word":"critic","phonetic":"/ˈkrɪtɪk/","pos":"n.","meaningCN":"批评家；挑剔的人","tag":"高频","root":"crit 指“判断”","exampleEN":"Film critics praised the director's unique visual style and storytelling.","exampleCN":"影评人称赞了导演独特的视觉风格和叙事手法。","extra":"critical adj. 批评的；criticism n. 批评。"},{"chapter":9,"key":"9:6","id":6,"word":"exponent","phonetic":"/ɪkˈspəʊnənt/","pos":"n.","meaningCN":"阐述者，倡导者，拥护者","tag":"低频","root":"","exampleEN":"She is a leading exponent of traditional music in the modern era.","exampleCN":"她是现代传统音乐的主要倡导者。","extra":""},{"chapter":9,"key":"9:7","id":7,"word":"announcer","phonetic":"/əˈnaʊnsə/","pos":"n.","meaningCN":"广播员，播音员","tag":"低频","root":"announce v. 宣布；播报","exampleEN":"The announcer's voice came through the speakers, welcoming everyone to the event.","exampleCN":"播音员的声音通过扬声器传来，欢迎大家参加活动。","extra":""},{"chapter":9,"key":"9:8","id":8,"word":"correspondent","phonetic":"/ˌkɒrɪˈspɒndənt/","pos":"n.","meaningCN":"通信者；通讯员，记者","tag":"高频","root":"","exampleEN":"The war correspondent reported live from the front lines despite the danger.","exampleCN":"战地记者不顾危险从前线发回现场报道。","extra":"搭配：a war correspondent 战地记者。"},{"chapter":9,"key":"9:9","id":9,"word":"messenger","phonetic":"/ˈmesɪndʒə/","pos":"n.","meaningCN":"邮递员，信使","tag":"低频","root":"message n. 信息 v. 给......发（电子）信息","exampleEN":"The messenger delivered the invitation just in time for the ceremony.","exampleCN":"信使及时在典礼开始前送来了邀请函。","extra":""},{"chapter":9,"key":"9:10","id":10,"word":"editor","phonetic":"/ˈedɪtə/","pos":"n.","meaningCN":"编辑，校订者；（电台或电视台的）记者，编辑","tag":"核心","root":"edit v. 编辑，校订；剪辑","exampleEN":"The editor suggested several improvements to the article before publication.","exampleCN":"编辑在文章发表前提出了几处修改建议。","extra":"搭配：chief editor 主编。"},{"chapter":9,"key":"9:11","id":11,"word":"typist","phonetic":"/ˈtaɪpɪst/","pos":"n.","meaningCN":"打字员","tag":"识记","root":"type v. 打字","exampleEN":"Before computers became common, typists played an essential role in offices.","exampleCN":"在电脑普及之前，打字员在办公室中起着至关重要的作用。","extra":"shorthand typist 速记打字员。"},{"chapter":9,"key":"9:12","id":12,"word":"handout","phonetic":"/ˈhændaʊt/","pos":"n.","meaningCN":"传单；讲义","tag":"低频","root":"","exampleEN":"The teacher gave each student a handout summarising the key points of the lecture.","exampleCN":"老师给每个学生发了一份讲义，总结了讲座的要点。","extra":""},{"chapter":9,"key":"9:13","id":13,"word":"leaflet","phonetic":"/ˈliːflɪt/","pos":"n.","meaningCN":"传单 v. 散发传单","tag":"低频","root":"","exampleEN":"Volunteers distributed leaflets to promote the upcoming charity concert.","exampleCN":"志愿者们分发传单宣传即将举行的慈善音乐会。","extra":""},{"chapter":9,"key":"9:14","id":14,"word":"propaganda","phonetic":"/ˌprɒpəˈɡændə/","pos":"n.","meaningCN":"宣传，鼓吹","tag":"高频","root":"","exampleEN":"During the war, both sides used propaganda to influence public opinion.","exampleCN":"战争期间，双方都利用宣传来影响公众舆论。","extra":""},{"chapter":9,"key":"9:15","id":15,"word":"publish","phonetic":"/ˈpʌblɪʃ/","pos":"v.","meaningCN":"公布；出版，发行","tag":"核心","root":"public n. 公众 adj. 公众的； publicity n. 关注，宣传； publication n. 出版物；出版，发行","exampleEN":"She hopes to publish her first novel by the end of next year.","exampleCN":"她希望在明年年底前出版自己的第一部小说。","extra":""},{"chapter":9,"key":"9:16","id":16,"word":"disseminate","phonetic":"/dɪˈsemɪneɪt/","pos":"v.","meaningCN":"散布，传播","tag":"低频","root":"","exampleEN":"Social media allows people to disseminate information quickly across the globe.","exampleCN":"社交媒体使人们能够迅速在全球传播信息。","extra":""},{"chapter":9,"key":"9:17","id":17,"word":"foresee","phonetic":"/fɔːˈsiː/","pos":"v.","meaningCN":"预见，预知","tag":"高频","root":"fore 表示“前面的”，如：forearm（前臂），forebear（祖先），forefather（祖先）","exampleEN":"No one could foresee how popular the new music streaming service would become.","exampleCN":"没有人能预见到新的音乐流媒体服务会变得如此流行。","extra":""},{"chapter":9,"key":"9:18","id":18,"word":"anticipate","phonetic":"/ænˈtɪsɪpeɪt/","pos":"v.","meaningCN":"预期，预料","tag":"核心","root":"participate v. 参与","exampleEN":"The organisers anticipate that over ten thousand visitors will attend the festival.","exampleCN":"组织者预计将有一万多名游客参加这个节日。","extra":""},{"chapter":9,"key":"9:19","id":19,"word":"expect","phonetic":"/ɪkˈspekt/","pos":"v.","meaningCN":"预料，预期","tag":"核心","root":"expectation n. 期待，期望","exampleEN":"Fans expect the band to release a new album before the world tour.","exampleCN":"歌迷们期待乐队在世界巡演前发行新专辑。","extra":""},{"chapter":9,"key":"9:20","id":20,"word":"await","phonetic":"/əˈweɪt/","pos":"v.","meaningCN":"等候，期待；将降临到......身上","tag":"高频","root":"","exampleEN":"A large crowd gathered at the airport to await the arrival of the famous actor.","exampleCN":"一大群人聚集在机场等候那位著名演员的到来。","extra":""},{"chapter":9,"key":"9:21","id":21,"word":"pastime","phonetic":"/ˈpɑːstaɪm/","pos":"n.","meaningCN":"消遣，娱乐","tag":"高频","root":"","exampleEN":"Reading has always been a popular pastime for people of all ages.","exampleCN":"阅读一直是各年龄段人们喜爱的消遣。","extra":""},{"chapter":9,"key":"9:22","id":22,"word":"entertain","phonetic":"/ˌentəˈteɪn/","pos":"v.","meaningCN":"娱乐；招待；心存，怀有","tag":"核心","root":"entertainment n. 娱乐，消遣；款待","exampleEN":"The magician entertained the children with a series of amazing tricks.","exampleCN":"魔术师用一系列精彩的戏法逗乐了孩子们。","extra":""},{"chapter":9,"key":"9:23","id":23,"word":"recreation","phonetic":"/ˌrekriˈeɪʃən/","pos":"n.","meaningCN":"休闲，娱乐","tag":"高频","root":"","exampleEN":"The park offers various facilities for recreation, including cycling paths and picnic areas.","exampleCN":"公园提供骑行道和野餐区等各种休闲设施。","extra":"搭配：a recreation ground 公共娱乐场。"},{"chapter":9,"key":"9:24","id":24,"word":"amuse","phonetic":"/əˈmjuːz/","pos":"v.","meaningCN":"逗乐；给......提供娱乐","tag":"高频","root":"","exampleEN":"He told a funny story to amuse his friends during the long journey.","exampleCN":"在长途旅行中，他讲了一个有趣的故事来逗朋友们开心。","extra":"搭配：amuse oneself 自娱自乐。"},{"chapter":9,"key":"9:25","id":25,"word":"gossip","phonetic":"/ˈɡɒsɪp/","pos":"n.","meaningCN":"闲聊；流言蜚语","tag":"高频","root":"","exampleEN":"Celebrities often find their private lives the subject of media gossip.","exampleCN":"名人们常发现自己的私生活成了媒体八卦的话题。","extra":""},{"chapter":9,"key":"9:26","id":26,"word":"rumour","phonetic":"/ˈruːmə/","pos":"n.","meaningCN":"谣言，传闻","tag":"高频","root":"","exampleEN":"The rumour about the band breaking up turned out to be false.","exampleCN":"关于乐队解散的传闻被证实是假的。","extra":""},{"chapter":9,"key":"9:27","id":27,"word":"consensus","phonetic":"/kənˈsensəs/","pos":"n.","meaningCN":"共识，一致的意见","tag":"高频","root":"","exampleEN":"After a long discussion, the committee finally reached a consensus on the issue.","exampleCN":"经过长时间讨论，委员会最终就该问题达成了共识。","extra":""},{"chapter":9,"key":"9:28","id":28,"word":"festival","phonetic":"/ˈfestɪvəl/","pos":"n.","meaningCN":"节日；（音乐、电影等的）节","tag":"核心","root":"","exampleEN":"The Spring Festival is the most important traditional holiday for many people.","exampleCN":"春节是许多人最重要的传统节日。","extra":""},{"chapter":9,"key":"9:29","id":29,"word":"feast","phonetic":"/fiːst/","pos":"n.","meaningCN":"盛宴；（宗教）节日","tag":"低频","root":"","exampleEN":"Families gather to share a feast on the evening before the new year.","exampleCN":"新年前夜，家人们聚在一起共享盛宴。","extra":""},{"chapter":9,"key":"9:30","id":30,"word":"programme","phonetic":"/ˈprəʊɡræm/","pos":"n.","meaningCN":"节目；方案；（演出或活动的）程序 v. 为（系统）设定程序；计划","tag":"核心","root":"programmer n. 程序设计员","exampleEN":"The cultural programme included performances of dance, music, and poetry.","exampleCN":"文化节目包括舞蹈、音乐和诗歌表演。","extra":"美式拼写 program。"},{"chapter":9,"key":"9:31","id":31,"word":"rehearsal","phonetic":"/rɪˈhɜːsəl/","pos":"n.","meaningCN":"排练","tag":"高频","root":"","exampleEN":"The actors stayed late after the rehearsal to perfect their lines.","exampleCN":"排练后演员们留到很晚以完善台词。","extra":""},{"chapter":9,"key":"9:32","id":32,"word":"perform","phonetic":"/pəˈfɔːm/","pos":"v.","meaningCN":"表演，演出","tag":"核心","root":"","exampleEN":"She will perform a piano solo at the school concert next week.","exampleCN":"下周她将在学校音乐会上表演钢琴独奏。","extra":""},{"chapter":9,"key":"9:33","id":33,"word":"imitate","phonetic":"/ˈɪmɪteɪt/","pos":"v.","meaningCN":"模仿，效仿","tag":"高频","root":"","exampleEN":"Children often imitate the behaviour of their favourite cartoon characters.","exampleCN":"孩子们经常模仿他们喜欢的卡通人物的行为。","extra":""},{"chapter":9,"key":"9:34","id":34,"word":"mimic","phonetic":"/ˈmɪmɪk/","pos":"v.","meaningCN":"模仿；戏仿","tag":"低频","root":"","exampleEN":"The comedian could perfectly mimic the voices of several famous politicians.","exampleCN":"这位喜剧演员能完美模仿几位著名政客的声音。","extra":""},{"chapter":9,"key":"9:35","id":35,"word":"simulate","phonetic":"/ˈsɪmjʊleɪt/","pos":"v.","meaningCN":"模拟；假装，冒充","tag":"高频","root":"simulative adj. 模拟的；假装的","exampleEN":"Virtual reality games can simulate the experience of flying through the sky.","exampleCN":"虚拟现实游戏可以模拟在天空飞行的体验。","extra":""},{"chapter":9,"key":"9:36","id":36,"word":"circus","phonetic":"/ˈsɜːkəs/","pos":"n.","meaningCN":"马戏团；圆形广场（常用于地名）","tag":"低频","root":"","exampleEN":"The circus came to town with acrobats, clowns, and trained animals.","exampleCN":"马戏团带着杂技演员、小丑和受过训练的动物来到镇上。","extra":"搭配：a circus clown 马戏团小丑。"},{"chapter":9,"key":"9:37","id":37,"word":"magic","phonetic":"/ˈmædʒɪk/","pos":"n.","meaningCN":"魔术；魔法","tag":"核心","root":"","exampleEN":"The magician's magic tricks left the audience completely amazed.","exampleCN":"魔术师的魔术让观众惊叹不已。","extra":""},{"chapter":9,"key":"9:38","id":38,"word":"drama","phonetic":"/ˈdrɑːmə/","pos":"n.","meaningCN":"戏，剧；戏剧艺术","tag":"核心","root":"dramatic adj. 戏剧性的","exampleEN":"She studied drama at university and later became a stage actress.","exampleCN":"她在大学学习戏剧，后来成了一名舞台剧演员。","extra":""},{"chapter":9,"key":"9:39","id":39,"word":"concert","phonetic":"/ˈkɒnsət/","pos":"n.","meaningCN":"音乐会","tag":"核心","root":"","exampleEN":"Thousands of fans filled the stadium to enjoy the open-air concert.","exampleCN":"数千名歌迷挤满了体育场欣赏露天音乐会。","extra":"搭配：in concert with 与......合作。"},{"chapter":9,"key":"9:40","id":40,"word":"symphony","phonetic":"/ˈsɪmfəni/","pos":"n.","meaningCN":"交响乐","tag":"高频","root":"","exampleEN":"Beethoven's Fifth Symphony is one of the most recognisable pieces of classical music.","exampleCN":"贝多芬的第五交响曲是古典音乐中最具辨识度的作品之一。","extra":""},{"chapter":9,"key":"9:41","id":41,"word":"orchestra","phonetic":"/ˈɔːkɪstrə/","pos":"n.","meaningCN":"管弦乐队","tag":"高频","root":"","exampleEN":"The orchestra played the national anthem at the opening ceremony.","exampleCN":"管弦乐队在开幕式上演奏了国歌。","extra":""},{"chapter":9,"key":"9:42","id":42,"word":"film","phonetic":"/fɪlm/","pos":"n.","meaningCN":"影片；胶卷","tag":"核心","root":"","exampleEN":"The documentary film explores the impact of technology on modern culture.","exampleCN":"这部纪录影片探讨了技术对现代文化的影响。","extra":""},{"chapter":9,"key":"9:43","id":43,"word":"movie","phonetic":"/ˈmuːvi/","pos":"n.","meaningCN":"电影","tag":"核心","root":"","exampleEN":"We decided to watch a comedy movie to relax after a long week.","exampleCN":"经过漫长的一周后，我们决定看部喜剧电影放松一下。","extra":""},{"chapter":9,"key":"9:44","id":44,"word":"X-rated","phonetic":"/ˈeks ˌreɪtɪd/","pos":"adj.","meaningCN":"X级的，青少年不宜的","tag":"识记","root":"","exampleEN":"The film was given an X-rated certificate because of its violent scenes.","exampleCN":"这部电影因含有暴力场面而被定为X级。","extra":""},{"chapter":9,"key":"9:45","id":45,"word":"artist","phonetic":"/ˈɑːtɪst/","pos":"n.","meaningCN":"艺术家","tag":"核心","root":"art n. 艺术； artistic adj. 艺术的；艺术家的","exampleEN":"The artist's latest exhibition features paintings inspired by nature.","exampleCN":"这位艺术家的最新展览展出了以自然为灵感的画作。","extra":""},{"chapter":9,"key":"9:46","id":46,"word":"ballet","phonetic":"/ˈbæleɪ/","pos":"n.","meaningCN":"芭蕾舞；芭蕾舞剧","tag":"高频","root":"","exampleEN":"She has been training in ballet since she was five years old.","exampleCN":"她从五岁起就开始接受芭蕾舞训练。","extra":"搭配：ice ballet 冰上芭蕾；water ballet 水上芭蕾。"},{"chapter":9,"key":"9:47","id":47,"word":"craftsman","phonetic":"/ˈkrɑːftsmən/","pos":"n.","meaningCN":"工匠，工艺师","tag":"低频","root":"craft n. 工艺 v. 精心制作","exampleEN":"The wooden furniture was made by a skilled craftsman using traditional methods.","exampleCN":"这套木制家具是由一位手艺精湛的工匠用传统方法制作的。","extra":""},{"chapter":9,"key":"9:48","id":48,"word":"opera","phonetic":"/ˈɒpərə/","pos":"n.","meaningCN":"歌剧","tag":"高频","root":"","exampleEN":"Watching an opera at the famous theatre was an unforgettable cultural experience.","exampleCN":"在著名的剧院观看歌剧是一次难忘的文化体验。","extra":"Beijing opera 京剧。"},{"chapter":9,"key":"9:49","id":49,"word":"painter","phonetic":"/ˈpeɪntə/","pos":"n.","meaningCN":"画家；油漆匠","tag":"高频","root":"","exampleEN":"The painter captured the beauty of the landscape with soft, warm colours.","exampleCN":"画家用柔和、温暖的色彩捕捉了风景之美。","extra":""},{"chapter":9,"key":"9:50","id":50,"word":"comedy","phonetic":"/ˈkɒmədi/","pos":"n.","meaningCN":"喜剧","tag":"核心","root":"","exampleEN":"The comedy show had the audience laughing from beginning to end.","exampleCN":"这场喜剧表演让观众从头笑到尾。","extra":""},{"chapter":9,"key":"9:51","id":51,"word":"role","phonetic":"/rəʊl/","pos":"n.","meaningCN":"角色；作用；职能","tag":"核心","root":"","exampleEN":"She played the lead role in the school play and received great applause.","exampleCN":"她在学校话剧里扮演主角，赢得了热烈掌声。","extra":"搭配：play a role in 在......中起作用。"},{"chapter":9,"key":"9:52","id":52,"word":"tragedy","phonetic":"/ˈtrædʒədi/","pos":"n.","meaningCN":"悲剧；悲惨的事","tag":"高频","root":"","exampleEN":"Shakespeare's 'Romeo and Juliet' is one of the most famous tragedies in literature.","exampleCN":"莎士比亚的《罗密欧与朱丽叶》是文学史上最著名的悲剧之一。","extra":""},{"chapter":9,"key":"9:53","id":53,"word":"scene","phonetic":"/siːn/","pos":"n.","meaningCN":"景色；现场；（戏剧的）场面","tag":"核心","root":"","exampleEN":"The opening scene of the film shows a breathtaking mountain view.","exampleCN":"电影的开场展现了一幅令人叹为观止的山景。","extra":""},{"chapter":9,"key":"9:54","id":54,"word":"stage","phonetic":"/steɪdʒ/","pos":"n.","meaningCN":"舞台；阶段；[the ~]戏剧演出","tag":"核心","root":"","exampleEN":"She felt nervous when she stepped onto the stage for the first time.","exampleCN":"第一次踏上舞台时，她感到很紧张。","extra":""},{"chapter":9,"key":"9:55","id":55,"word":"portrait","phonetic":"/ˈpɔːtrɪt/","pos":"n.","meaningCN":"肖像，半身画像","tag":"高频","root":"","exampleEN":"The artist painted a detailed portrait of the queen that now hangs in the national gallery.","exampleCN":"画家为女王画了一幅精细的肖像，现悬挂在国家美术馆。","extra":""},{"chapter":9,"key":"9:56","id":56,"word":"gallery","phonetic":"/ˈɡæləri/","pos":"n.","meaningCN":"美术馆","tag":"高频","root":"","exampleEN":"The gallery hosts an annual exhibition of contemporary Chinese art.","exampleCN":"这家美术馆每年举办中国当代艺术展。","extra":""},{"chapter":9,"key":"9:57","id":57,"word":"exhibition","phonetic":"/ˌeksɪˈbɪʃən/","pos":"n.","meaningCN":"展览","tag":"核心","root":"","exampleEN":"The photography exhibition attracted visitors from all over the city.","exampleCN":"这个摄影展吸引了全市各地的参观者。","extra":""},{"chapter":9,"key":"9:58","id":58,"word":"aesthetic","phonetic":"/iːsˈθetɪk/","pos":"adj.","meaningCN":"审美的 n. 审美观","tag":"高频","root":"","exampleEN":"The design combines modern technology with traditional Chinese aesthetic values.","exampleCN":"该设计将现代技术与中国传统审美价值相结合。","extra":""},{"chapter":9,"key":"9:59","id":59,"word":"collect","phonetic":"/kəˈlekt/","pos":"v.","meaningCN":"收集；收藏","tag":"核心","root":"collection n. 收集；收藏品","exampleEN":"He started to collect antique coins during his travels around the world.","exampleCN":"他在周游世界期间开始收集古钱币。","extra":""},{"chapter":9,"key":"9:60","id":60,"word":"select","phonetic":"/sɪˈlekt/","pos":"v.","meaningCN":"选择，挑选 adj. 精选的","tag":"核心","root":"selection n. 选择","exampleEN":"The judges will select the best painting from hundreds of entries.","exampleCN":"评委将从数百件参赛作品中选出最佳画作。","extra":""},{"chapter":9,"key":"9:61","id":61,"word":"opt","phonetic":"/ɒpt/","pos":"v.","meaningCN":"选择","tag":"高频","root":"option n. 选择；选择权","exampleEN":"More people now opt to stream music online rather than buy physical albums.","exampleCN":"如今更多人选择在线收听音乐，而不是购买实体专辑。","extra":"搭配：opt for sth. 选择某事物。"},{"chapter":9,"key":"9:62","id":62,"word":"photograph","phonetic":"/ˈfəʊtəɡrɑːf/","pos":"n.","meaningCN":"照片，相片","tag":"核心","root":"photographic adj. 摄影的，摄制的","exampleEN":"The photograph of the sunset over the ocean won first prize in the contest.","exampleCN":"那张海上落日的照片在比赛中获得了一等奖。","extra":""},{"chapter":9,"key":"9:63","id":63,"word":"painting","phonetic":"/ˈpeɪntɪŋ/","pos":"n.","meaningCN":"油画，绘画；作画；涂漆","tag":"核心","root":"","exampleEN":"The cave paintings show that early humans had a rich cultural and spiritual life.","exampleCN":"洞穴壁画表明早期人类拥有丰富的文化和精神生活。","extra":""},{"chapter":9,"key":"9:64","id":64,"word":"sculpture","phonetic":"/ˈskʌlptʃə/","pos":"n.","meaningCN":"雕塑","tag":"高频","root":"","exampleEN":"A large bronze sculpture of a horse stands in the centre of the square.","exampleCN":"广场中央矗立着一座巨大的青铜马雕塑。","extra":""},{"chapter":9,"key":"9:65","id":65,"word":"draw","phonetic":"/drɔː/","pos":"v.","meaningCN":"画；拉；拔出","tag":"核心","root":"drawing n. 图画，素描画；绘图（技巧）","exampleEN":"Children love to draw pictures of their families and pets.","exampleCN":"孩子们喜欢画家人和宠物。","extra":""},{"chapter":9,"key":"9:66","id":66,"word":"sketch","phonetic":"/sketʃ/","pos":"n.","meaningCN":"素描，速写，草图 v. 画素描，画速写","tag":"低频","root":"","exampleEN":"She made a quick sketch of the old building before it was torn down.","exampleCN":"在那座老建筑被拆之前，她快速画了一幅速写。","extra":"搭配：sketch out 画出......的轮廓。"},{"chapter":9,"key":"9:67","id":67,"word":"depict","phonetic":"/dɪˈpɪkt/","pos":"v.","meaningCN":"描述，描写；描绘","tag":"高频","root":"pict 指“画”","exampleEN":"The mural depicts scenes from the daily life of the community a hundred years ago.","exampleCN":"这幅壁画描绘了一百年前社区的日常生活场景。","extra":""},{"chapter":9,"key":"9:68","id":68,"word":"describe","phonetic":"/dɪˈskraɪb/","pos":"v.","meaningCN":"描述，形容","tag":"核心","root":"description n. 描述","exampleEN":"Can you describe the atmosphere of the festival in your own words?","exampleCN":"你能用自己的话描述一下那个节日的氛围吗？","extra":""},{"chapter":9,"key":"9:69","id":69,"word":"carve","phonetic":"/kɑːv/","pos":"v.","meaningCN":"雕刻；切下","tag":"低频","root":"","exampleEN":"The artist carved a delicate flower pattern into the block of wood.","exampleCN":"艺术家在一块木头上雕刻出精致的花朵图案。","extra":"搭配：carve up 瓜分。"},{"chapter":9,"key":"9:70","id":70,"word":"improvise","phonetic":"/ˈɪmprəvaɪz/","pos":"v.","meaningCN":"临时做；即兴创作","tag":"低频","root":"vis 指“看见”，im（否定）+ pro（预先）+ vise（看见）→ 预先没有看见 → 即兴创作","exampleEN":"When the microphone broke, the singer had to improvise by shouting the lyrics.","exampleCN":"麦克风坏了，歌手只好即兴喊着唱出歌词。","extra":""},{"chapter":9,"key":"9:71","id":71,"word":"musical","phonetic":"/ˈmjuːzɪkəl/","pos":"adj.","meaningCN":"音乐的；悦耳的","tag":"核心","root":"musician n. 音乐家，作曲家","exampleEN":"She comes from a very musical family and has played the violin since childhood.","exampleCN":"她来自一个很有音乐氛围的家庭，从小就开始拉小提琴。","extra":""},{"chapter":9,"key":"9:72","id":72,"word":"classical","phonetic":"/ˈklæsɪkəl/","pos":"adj.","meaningCN":"古典的，传统的","tag":"核心","root":"","exampleEN":"Many students are exposed to classical music for the first time through films and television.","exampleCN":"许多学生通过电影和电视第一次接触到古典音乐。","extra":""},{"chapter":9,"key":"9:73","id":73,"word":"jazz","phonetic":"/dʒæz/","pos":"n.","meaningCN":"爵士乐","tag":"高频","root":"","exampleEN":"The jazz band played lively tunes that got everyone tapping their feet.","exampleCN":"爵士乐队演奏的欢快曲调让每个人都随着打起了拍子。","extra":""},{"chapter":9,"key":"9:74","id":74,"word":"rock","phonetic":"/rɒk/","pos":"n.","meaningCN":"摇滚乐；岩石","tag":"核心","root":"","exampleEN":"Rock music emerged in the 1950s and quickly gained popularity worldwide.","exampleCN":"摇滚乐兴起于20世纪50年代，迅速风靡全球。","extra":""},{"chapter":9,"key":"9:75","id":75,"word":"hip-hop","phonetic":"/ˈhɪp hɒp/","pos":"n.","meaningCN":"嘻哈文化","tag":"高频","root":"","exampleEN":"Hip-hop culture has influenced fashion, language, and art around the world.","exampleCN":"嘻哈文化影响了世界各地的时尚、语言和艺术。","extra":""},{"chapter":9,"key":"9:76","id":76,"word":"pop","phonetic":"/pɒp/","pos":"n.","meaningCN":"流行音乐，流行乐曲","tag":"核心","root":"","exampleEN":"Pop songs often have catchy melodies that people enjoy humming along with.","exampleCN":"流行歌曲常有朗朗上口的旋律，人们喜欢跟着哼唱。","extra":""},{"chapter":9,"key":"9:77","id":77,"word":"lyric","phonetic":"/ˈlɪrɪk/","pos":"n.","meaningCN":"抒情诗；[-s]歌词 adj. 抒情的","tag":"高频","root":"","exampleEN":"She writes beautiful lyrics that express deep personal emotions.","exampleCN":"她写的歌词优美，表达了深刻的个人情感。","extra":""},{"chapter":9,"key":"9:78","id":78,"word":"band","phonetic":"/bænd/","pos":"n.","meaningCN":"乐队；带；波段","tag":"核心","root":"","exampleEN":"The band performed their new song for the first time at the festival.","exampleCN":"乐队在音乐节上首次表演了他们的新歌。","extra":""},{"chapter":9,"key":"9:79","id":79,"word":"solo","phonetic":"/ˈsəʊləʊ/","pos":"n.","meaningCN":"独奏，独唱 adj. 独奏的，独唱的；单独的","tag":"高频","root":"","exampleEN":"The guitarist impressed everyone with a brilliant solo in the middle of the song.","exampleCN":"吉他手在歌曲中间的一段精彩独奏给每个人都留下了深刻印象。","extra":""},{"chapter":9,"key":"9:80","id":80,"word":"melody","phonetic":"/ˈmelədi/","pos":"n.","meaningCN":"乐曲；旋律","tag":"高频","root":"","exampleEN":"The simple melody of the lullaby can calm even the most restless baby.","exampleCN":"这首摇篮曲简单的旋律甚至能让最不安的婴儿平静下来。","extra":""},{"chapter":9,"key":"9:81","id":81,"word":"rhythm","phonetic":"/ˈrɪðəm/","pos":"n.","meaningCN":"节奏，韵律","tag":"高频","root":"rhythmical adj. 有节奏的，有韵律的","exampleEN":"Drummers provide the rhythm that keeps the whole band in sync.","exampleCN":"鼓手提供节奏，使整个乐队保持同步。","extra":""},{"chapter":9,"key":"9:82","id":82,"word":"tone","phonetic":"/təʊn/","pos":"n.","meaningCN":"音色；声调；腔调","tag":"高频","root":"","exampleEN":"The teacher's gentle tone helped the nervous student feel more at ease.","exampleCN":"老师轻柔的语气让紧张的学生感到更自在了。","extra":""},{"chapter":9,"key":"9:83","id":83,"word":"tune","phonetic":"/tjuːn/","pos":"n.","meaningCN":"曲调；短乐曲 v. 调试","tag":"高频","root":"tuner n. 调音者","exampleEN":"She hummed a cheerful tune while preparing dinner.","exampleCN":"她一边做晚饭，一边哼着欢快的曲子。","extra":""},{"chapter":9,"key":"9:84","id":84,"word":"disc","phonetic":"/dɪsk/","pos":"n.","meaningCN":"光碟；唱片；[英]（计算机）磁碟，磁盘","tag":"低频","root":"","exampleEN":"Many music lovers still prefer the warm sound of vinyl discs over digital files.","exampleCN":"许多音乐爱好者仍然偏爱黑胶唱片温暖的音质，胜过数字文件。","extra":""},{"chapter":9,"key":"9:85","id":85,"word":"piano","phonetic":"/piˈænəʊ/","pos":"n.","meaningCN":"钢琴","tag":"核心","root":"","exampleEN":"Learning to play the piano requires patience and regular practice.","exampleCN":"学弹钢琴需要耐心和定期练习。","extra":""},{"chapter":9,"key":"9:86","id":86,"word":"violin","phonetic":"/ˌvaɪəˈlɪn/","pos":"n.","meaningCN":"小提琴","tag":"高频","root":"","exampleEN":"The sound of the violin filled the concert hall with a warm, rich tone.","exampleCN":"小提琴的声音充满了音乐厅，音色温暖而浑厚。","extra":""},{"chapter":9,"key":"9:87","id":87,"word":"cello","phonetic":"/ˈtʃeləʊ/","pos":"n.","meaningCN":"大提琴","tag":"低频","root":"","exampleEN":"The deep, mellow sound of the cello added a layer of emotion to the piece.","exampleCN":"大提琴深沉醇美的音色为乐曲增添了一层情感。","extra":""},{"chapter":9,"key":"9:88","id":88,"word":"guitar","phonetic":"/ɡɪˈtɑː/","pos":"n.","meaningCN":"吉他","tag":"核心","root":"","exampleEN":"He taught himself to play the guitar by watching online tutorials.","exampleCN":"他通过观看在线教程自学弹吉他。","extra":""},{"chapter":9,"key":"9:89","id":89,"word":"harmonica","phonetic":"/hɑːˈmɒnɪkə/","pos":"n.","meaningCN":"口琴","tag":"识记","root":"","exampleEN":"The folk musician pulled a small harmonica from his pocket and began to play a blues melody.","exampleCN":"民间音乐家从口袋里掏出一支小口琴，开始吹奏一首布鲁斯旋律。","extra":""},{"chapter":9,"key":"9:90","id":90,"word":"trumpet","phonetic":"/ˈtrʌmpɪt/","pos":"n.","meaningCN":"喇叭，小号","tag":"高频","root":"","exampleEN":"The bright sound of the trumpet announced the beginning of the ceremony.","exampleCN":"小号嘹亮的声音宣告了典礼的开始。","extra":""},{"chapter":9,"key":"9:91","id":91,"word":"drum","phonetic":"/drʌm/","pos":"n.","meaningCN":"鼓；鼓状物；大桶","tag":"核心","root":"","exampleEN":"The steady beat of the drum kept the dancers in perfect time.","exampleCN":"鼓声的稳定节拍使舞者们保持完美的同步。","extra":""},{"chapter":9,"key":"9:92","id":92,"word":"flute","phonetic":"/fluːt/","pos":"n.","meaningCN":"长笛","tag":"低频","root":"","exampleEN":"The soft, airy notes of the flute floated through the peaceful garden.","exampleCN":"长笛轻柔空灵的音符飘荡在宁静的花园里。","extra":""},{"chapter":9,"key":"9:93","id":93,"word":"competition","phonetic":"/ˌkɒmpɪˈtɪʃən/","pos":"n.","meaningCN":"竞争；比赛","tag":"核心","root":"compete v. 竞争； competitor n. 竞争者，对手","exampleEN":"The singing competition attracted talented performers from across the country.","exampleCN":"这次歌唱比赛吸引了全国各地的才华横溢的表演者。","extra":""},{"chapter":9,"key":"9:94","id":94,"word":"tournament","phonetic":"/ˈtʊənəmənt/","pos":"n.","meaningCN":"锦标赛，联赛","tag":"高频","root":"","exampleEN":"The international chess tournament brought together grandmasters from dozens of nations.","exampleCN":"国际象棋锦标赛汇聚了来自数十个国家的大师。","extra":""},{"chapter":9,"key":"9:95","id":95,"word":"Olympic","phonetic":"/əˈlɪmpɪk/","pos":"adj.","meaningCN":"奥林匹克运动会的 n.[the-s]奥林匹克运动会","tag":"核心","root":"","exampleEN":"Winning an Olympic medal is often the highlight of an athlete's entire career.","exampleCN":"赢得奥运奖牌通常是运动员整个职业生涯的最高光时刻。","extra":""},{"chapter":9,"key":"9:96","id":96,"word":"sponsor","phonetic":"/ˈspɒnsə/","pos":"n.","meaningCN":"发起人；主办人；赞助人 v. 发起；主办；赞助","tag":"高频","root":"sponsorship n. 资助","exampleEN":"The music festival was made possible by the generous support of its corporate sponsors.","exampleCN":"音乐节得以举办，多亏了企业赞助商的慷慨支持。","extra":""},{"chapter":9,"key":"9:97","id":97,"word":"patron","phonetic":"/ˈpeɪtrən/","pos":"n.","meaningCN":"赞助人；顾客，老主顾","tag":"低频","root":"","exampleEN":"A wealthy patron funded the young composer so he could focus on creating new works.","exampleCN":"一位富有的赞助人资助了这位年轻作曲家，使他能专心创作新作品。","extra":""},{"chapter":9,"key":"9:98","id":98,"word":"athlete","phonetic":"/ˈæθliːt/","pos":"n.","meaningCN":"运动员；[英]田径运动员","tag":"核心","root":"athletics n. 体育运动；田径运动","exampleEN":"Being a professional athlete demands years of dedicated training and discipline.","exampleCN":"成为一名职业运动员需要多年的专注训练和自律。","extra":""},{"chapter":9,"key":"9:99","id":99,"word":"champion","phonetic":"/ˈtʃæmpiən/","pos":"n.","meaningCN":"冠军，第一名 v. 拥护，支持","tag":"核心","root":"champ/camp 指“场地”","exampleEN":"She was declared the world champion after an intense final match.","exampleCN":"经过一场激烈的决赛后，她被宣布为世界冠军。","extra":""},{"chapter":9,"key":"9:100","id":100,"word":"spectator","phonetic":"/spekˈteɪtə/","pos":"n.","meaningCN":"观众","tag":"高频","root":"","exampleEN":"Thousands of spectators gathered along the river to watch the dragon boat race.","exampleCN":"成千上万的观众聚集在河边观看龙舟比赛。","extra":""},{"chapter":9,"key":"9:101","id":101,"word":"volunteer","phonetic":"/ˌvɒlənˈtɪə/","pos":"n.","meaningCN":"志愿者 v. 自愿做","tag":"核心","root":"volunt 指“意志，意愿”","exampleEN":"Many volunteers helped to organise the community sports day.","exampleCN":"许多志愿者帮助组织了社区运动会。","extra":""},{"chapter":9,"key":"9:102","id":102,"word":"famous","phonetic":"/ˈfeɪməs/","pos":"adj.","meaningCN":"著名的，出名的","tag":"核心","root":"fame n. 名声","exampleEN":"The city is famous for its lively music festivals and street performances.","exampleCN":"这座城市以其热闹的音乐节和街头表演而闻名。","extra":"搭配：be famous for 以......闻名。"},{"chapter":9,"key":"9:103","id":103,"word":"well-known","phonetic":"/ˌwel ˈnəʊn/","pos":"adj.","meaningCN":"众所周知的，出名的","tag":"核心","root":"","exampleEN":"He is a well-known television host with a career spanning three decades.","exampleCN":"他是一位知名的电视主持人，职业生涯长达三十年。","extra":""},{"chapter":9,"key":"9:104","id":104,"word":"energetic","phonetic":"/ˌenəˈdʒetɪk/","pos":"adj.","meaningCN":"充满活力的，精力充沛的","tag":"高频","root":"energy n. 精力，活力；能量","exampleEN":"The energetic dance performance energized the entire audience.","exampleCN":"充满活力的舞蹈表演让全场观众都活跃了起来。","extra":""},{"chapter":9,"key":"9:105","id":105,"word":"vigorous","phonetic":"/ˈvɪɡərəs/","pos":"adj.","meaningCN":"充满活力的；活跃的，积极的","tag":"低频","root":"vig 指“有生气的”","exampleEN":"Vigorous exercise for at least thirty minutes a day keeps the heart strong.","exampleCN":"每天至少进行30分钟剧烈的锻炼有助于保持心脏强健。","extra":""},{"chapter":9,"key":"9:106","id":106,"word":"stadium","phonetic":"/ˈsteɪdiəm/","pos":"n.","meaningCN":"体育场，运动场","tag":"核心","root":"","exampleEN":"The new sports stadium can hold up to sixty thousand people.","exampleCN":"新体育场最多可容纳六万人。","extra":""},{"chapter":9,"key":"9:107","id":107,"word":"gym","phonetic":"/dʒɪm/","pos":"n.","meaningCN":"体育活动；(= gymnasium) 健身房，体育馆","tag":"核心","root":"","exampleEN":"Many students go to the gym after class to stay fit and relieve stress.","exampleCN":"许多学生课后去健身房锻炼，以保持健康和缓解压力。","extra":""},{"chapter":9,"key":"9:108","id":108,"word":"training","phonetic":"/ˈtreɪnɪŋ/","pos":"n.","meaningCN":"训练，锻炼；培训","tag":"核心","root":"","exampleEN":"The football team undergoes intensive training before the start of the season.","exampleCN":"足球队在赛季开始前进行高强度训练。","extra":""},{"chapter":9,"key":"9:109","id":109,"word":"exercise","phonetic":"/ˈeksəsaɪz/","pos":"n.","meaningCN":"锻炼，运动；习题，练习 v. 锻炼","tag":"核心","root":"","exampleEN":"Regular exercise is key to maintaining both physical and mental health.","exampleCN":"经常锻炼是保持身心健康的关键。","extra":""},{"chapter":9,"key":"9:110","id":110,"word":"indoor","phonetic":"/ˈɪndɔː/","pos":"adj.","meaningCN":"室内的","tag":"高频","root":"indoors adv. 在室内","exampleEN":"They built an indoor swimming pool so they could swim all year round.","exampleCN":"他们建了一个室内游泳池，以便全年都能游泳。","extra":""},{"chapter":9,"key":"9:111","id":111,"word":"outdoor","phonetic":"/ˈaʊtdɔː/","pos":"adj.","meaningCN":"户外的，室外的","tag":"核心","root":"outdoors adv. 在室外，在户外","exampleEN":"The children prefer outdoor activities like climbing and running to sitting inside.","exampleCN":"比起坐在室内，孩子们更喜欢攀爬和跑步等户外活动。","extra":""},{"chapter":9,"key":"9:112","id":112,"word":"motion","phonetic":"/ˈməʊʃən/","pos":"v.","meaningCN":"做动作，示意","tag":"高频","root":"","exampleEN":"The guide motioned for the tourists to gather closer before telling the story.","exampleCN":"导游示意游客们聚拢些，然后才开始讲故事。","extra":""},{"chapter":9,"key":"9:113","id":113,"word":"mobile","phonetic":"/ˈməʊbaɪl/","pos":"adj.","meaningCN":"可移动的；流动的","tag":"高频","root":"","exampleEN":"Mobile phones have dramatically changed how people access entertainment.","exampleCN":"手机极大地改变了人们获取娱乐的方式。","extra":""},{"chapter":9,"key":"9:114","id":114,"word":"movement","phonetic":"/ˈmuːvmənt/","pos":"n.","meaningCN":"（身体部位的）活动；运动；移动","tag":"核心","root":"move v. 移动","exampleEN":"The dancer's graceful movements captivated the audience from the first moment.","exampleCN":"舞者优雅的动作从一开始就迷住了观众。","extra":""},{"chapter":9,"key":"9:115","id":115,"word":"yoga","phonetic":"/ˈjəʊɡə/","pos":"n.","meaningCN":"瑜伽","tag":"高频","root":"","exampleEN":"Practising yoga regularly can improve both flexibility and mental concentration.","exampleCN":"定期练习瑜伽可以提高身体柔韧性和精神集中力。","extra":""},{"chapter":9,"key":"9:116","id":116,"word":"sprawl","phonetic":"/sprɔːl/","pos":"v.","meaningCN":"伸开四肢坐着（或躺着）；延伸，蔓延 n.（城市）杂乱无序扩展的地区","tag":"低频","root":"","exampleEN":"He was too exhausted to do anything but sprawl on the sofa after work.","exampleCN":"他太累了，下班后只能四肢摊开躺在沙发上。","extra":""},{"chapter":9,"key":"9:117","id":117,"word":"stretch","phonetic":"/stretʃ/","pos":"v.","meaningCN":"伸展；伸长（胳膊、腿）","tag":"核心","root":"","exampleEN":"It is important to stretch your muscles before and after exercising.","exampleCN":"运动前后伸展肌肉很重要。","extra":""},{"chapter":9,"key":"9:118","id":118,"word":"strain","phonetic":"/streɪn/","pos":"v.","meaningCN":"拉紧；拉伤，扭伤 n. 张力，拉力；（精神上的）紧张","tag":"高频","root":"","exampleEN":"He strained a muscle in his leg while playing basketball.","exampleCN":"他打篮球时拉伤了腿部肌肉。","extra":""},{"chapter":9,"key":"9:119","id":119,"word":"chess","phonetic":"/tʃes/","pos":"n.","meaningCN":"国际象棋","tag":"高频","root":"","exampleEN":"Playing chess teaches you to think several steps ahead and anticipate your opponent's moves.","exampleCN":"下国际象棋教会你提前想好几步，预判对手的走法。","extra":""},{"chapter":9,"key":"9:120","id":120,"word":"badminton","phonetic":"/ˈbædmɪntən/","pos":"n.","meaningCN":"羽毛球","tag":"高频","root":"","exampleEN":"Badminton is a fast-paced sport that requires quick reflexes and agility.","exampleCN":"羽毛球是一项需要快速反应和敏捷性的快节奏运动。","extra":"搭配：a badminton tournament 羽毛球锦标赛。"},{"chapter":9,"key":"9:121","id":121,"word":"golf","phonetic":"/ɡɒlf/","pos":"n.","meaningCN":"高尔夫球","tag":"高频","root":"","exampleEN":"Many business meetings take place on the golf course as a way to combine work and recreation.","exampleCN":"许多商务会议在高尔夫球场进行，作为工作与休闲的一种结合。","extra":""},{"chapter":9,"key":"9:122","id":122,"word":"billiards","phonetic":"/ˈbɪliədz/","pos":"n.","meaningCN":"台球","tag":"低频","root":"","exampleEN":"They spent a relaxing evening playing billiards and chatting at the club.","exampleCN":"他们在俱乐部打台球聊天，度过了一个轻松的夜晚。","extra":""},{"chapter":9,"key":"9:123","id":123,"word":"soccer","phonetic":"/ˈsɒkə/","pos":"n.","meaningCN":"（英式）足球","tag":"核心","root":"","exampleEN":"Soccer is by far the most popular spectator sport in many parts of the world.","exampleCN":"足球是当今世界许多地方最受欢迎的观赏性运动。","extra":""},{"chapter":9,"key":"9:124","id":124,"word":"tennis","phonetic":"/ˈtenɪs/","pos":"n.","meaningCN":"网球","tag":"核心","root":"","exampleEN":"She has been taking tennis lessons every Saturday morning since she was seven.","exampleCN":"她七岁起每周六早上都上网球课。","extra":""},{"chapter":9,"key":"9:125","id":125,"word":"volleyball","phonetic":"/ˈvɒlibɔːl/","pos":"n.","meaningCN":"排球","tag":"高频","root":"","exampleEN":"Beach volleyball is a popular summer sport in coastal areas.","exampleCN":"沙滩排球是沿海地区一项受欢迎的夏季运动。","extra":""},{"chapter":9,"key":"9:126","id":126,"word":"hockey","phonetic":"/ˈhɒki/","pos":"n.","meaningCN":"曲棍球；冰球","tag":"低频","root":"","exampleEN":"Ice hockey players wear protective gear to prevent injuries from falls and collisions.","exampleCN":"冰球运动员穿戴护具，以防摔倒和碰撞时受伤。","extra":""},{"chapter":9,"key":"9:127","id":127,"word":"cricket","phonetic":"/ˈkrɪkɪt/","pos":"n.","meaningCN":"板球","tag":"低频","root":"","exampleEN":"Cricket matches can last several days, testing the endurance of both players and fans.","exampleCN":"板球比赛可持续数日，考验着球员和球迷的耐力。","extra":""},{"chapter":9,"key":"9:128","id":128,"word":"goal","phonetic":"/ɡəʊl/","pos":"n.","meaningCN":"球门；进球得分；目的","tag":"核心","root":"","exampleEN":"He scored the winning goal in the final minute of the match.","exampleCN":"他在比赛最后一分钟打进了制胜一球。","extra":""},{"chapter":9,"key":"9:129","id":129,"word":"bat","phonetic":"/bæt/","pos":"n.","meaningCN":"球拍，球棒，球板","tag":"低频","root":"","exampleEN":"The player stepped up to the plate and raised the bat, ready to hit.","exampleCN":"球员走向本垒，举起球棒准备击球。","extra":""},{"chapter":9,"key":"9:130","id":130,"word":"racket","phonetic":"/ˈrækɪt/","pos":"n.","meaningCN":"（网球、羽毛球等的）球拍","tag":"低频","root":"","exampleEN":"Before the final, she carefully checked the strings of her tennis racket.","exampleCN":"决赛前，她仔细检查了网球拍的弦。","extra":""},{"chapter":9,"key":"9:131","id":131,"word":"kick","phonetic":"/kɪk/","pos":"v./n.","meaningCN":"踢","tag":"核心","root":"","exampleEN":"The player kicked the ball so hard that it flew right into the top corner of the net.","exampleCN":"球员用力踢球，球直飞入球门上角。","extra":"搭配：kick the bucket 一命呜呼。"},{"chapter":9,"key":"9:132","id":132,"word":"knock","phonetic":"/nɒk/","pos":"v.","meaningCN":"敲，击；撞","tag":"核心","root":"","exampleEN":"Someone knocked on the door just as the concert was about to start on television.","exampleCN":"电视上的音乐会正要开始，有人敲了门。","extra":"搭配：knock at the door 敲门。"},{"chapter":9,"key":"9:133","id":133,"word":"flip","phonetic":"/flɪp/","pos":"v.","meaningCN":"掷；（使）快速翻动 adj. 随便的，轻率的","tag":"低频","root":"","exampleEN":"They decided to flip a coin to see who would pay for the movie tickets.","exampleCN":"他们决定掷硬币来决定谁出电影票钱。","extra":""},{"chapter":9,"key":"9:134","id":134,"word":"pitch","phonetic":"/pɪtʃ/","pos":"v.","meaningCN":"投，掷 n. 球场；（棒球中的）投球","tag":"高频","root":"","exampleEN":"The baseball pitcher trained for years to perfect his fast pitch.","exampleCN":"这名棒球投手训练了多年，以完善他的快速投球。","extra":"搭配：throw a pitch 投球。"},{"chapter":9,"key":"9:135","id":135,"word":"throw","phonetic":"/θrəʊ/","pos":"v.","meaningCN":"投，掷，抛，扔","tag":"核心","root":"","exampleEN":"Children love to throw frisbees in the park on sunny afternoons.","exampleCN":"晴朗的午后，孩子们喜欢在公园扔飞盘。","extra":""},{"chapter":9,"key":"9:136","id":136,"word":"toss","phonetic":"/tɒs/","pos":"v.","meaningCN":"扔，抛，掷；（使）颠簸","tag":"低频","root":"","exampleEN":"She tossed the ball to the dog, who caught it happily in its mouth.","exampleCN":"她把球抛给狗，狗高兴地用嘴接住。","extra":"搭配：toss and turn 辗转反侧。"},{"chapter":9,"key":"9:137","id":137,"word":"slide","phonetic":"/slaɪd/","pos":"v.","meaningCN":"滑动；逐渐降低 n. 滑行；下跌","tag":"高频","root":"","exampleEN":"Children love to slide down the big yellow slide in the playground.","exampleCN":"孩子们喜欢从操场上那个黄色大滑梯上滑下来。","extra":""},{"chapter":9,"key":"9:138","id":138,"word":"slip","phonetic":"/slɪp/","pos":"v.","meaningCN":"滑跤；滑落；溜 n. 滑倒","tag":"核心","root":"","exampleEN":"Be careful not to slip on the wet floor after swimming.","exampleCN":"游泳后小心别在湿地上滑倒。","extra":"搭配：a slip of the tongue 口误。"},{"chapter":9,"key":"9:139","id":139,"word":"glide","phonetic":"/ɡlaɪd/","pos":"v.","meaningCN":"滑动，掠过 n. 滑行","tag":"低频","root":"","exampleEN":"The skater glided effortlessly across the frozen lake.","exampleCN":"滑冰者在冰封的湖面上轻松地滑行。","extra":""},{"chapter":9,"key":"9:140","id":140,"word":"tumble","phonetic":"/ˈtʌmbəl/","pos":"v.","meaningCN":"摔倒，滚下","tag":"低频","root":"","exampleEN":"The toddler took a few steps and then tumbled gently onto the soft carpet.","exampleCN":"刚学步的小宝宝走了几步，然后轻轻地摔倒在柔软的地毯上。","extra":""},{"chapter":9,"key":"9:141","id":141,"word":"ski","phonetic":"/skiː/","pos":"v.","meaningCN":"滑雪 n. 滑雪板","tag":"高频","root":"","exampleEN":"Every winter, they travel to the mountains to ski and enjoy the snow.","exampleCN":"每年冬天，他们都去山里滑雪、赏雪。","extra":""},{"chapter":9,"key":"9:142","id":142,"word":"skate","phonetic":"/skeɪt/","pos":"v.","meaningCN":"滑冰","tag":"高频","root":"","exampleEN":"The ice rink is open to the public for skating on Friday evenings.","exampleCN":"溜冰场每周五晚对公众开放滑冰。","extra":""},{"chapter":9,"key":"9:143","id":143,"word":"cycling","phonetic":"/ˈsaɪklɪŋ/","pos":"n.","meaningCN":"骑自行车运动","tag":"高频","root":"cyclist n. 骑自行车的人； bicycle n. 自行车","exampleEN":"Cycling to work is a great way to combine exercise with daily commuting.","exampleCN":"骑自行车上班是将锻炼与日常通勤结合的绝佳方式。","extra":""},{"chapter":9,"key":"9:144","id":144,"word":"dive","phonetic":"/daɪv/","pos":"v.","meaningCN":"跳水；潜水；俯冲","tag":"高频","root":"","exampleEN":"She took a deep breath and dived into the clear blue water.","exampleCN":"她深吸一口气，潜入清澈湛蓝的水中。","extra":""},{"chapter":9,"key":"9:145","id":145,"word":"drift","phonetic":"/drɪft/","pos":"v.","meaningCN":"飘移，漂流；流浪，漂泊","tag":"低频","root":"","exampleEN":"The boat drifted slowly down the calm river as the sun began to set.","exampleCN":"太阳开始落山时，小船在平静的河面上缓缓漂流。","extra":""},{"chapter":9,"key":"9:146","id":146,"word":"jump","phonetic":"/dʒʌmp/","pos":"v.","meaningCN":"跳；暴涨；跳过","tag":"核心","root":"","exampleEN":"The children jumped with joy when they saw the presents under the tree.","exampleCN":"看到树下的礼物，孩子们高兴得跳了起来。","extra":""},{"chapter":9,"key":"9:147","id":147,"word":"leap","phonetic":"/liːp/","pos":"v.","meaningCN":"跳，跃 n. 跳跃","tag":"高频","root":"","exampleEN":"The dancer took a powerful leap across the stage, drawing gasps from the audience.","exampleCN":"舞者在舞台上强有力地一跃，引得观众发出惊叹声。","extra":""},{"chapter":9,"key":"9:148","id":148,"word":"plunge","phonetic":"/plʌndʒ/","pos":"v.","meaningCN":"纵身投入；猛跌；（使）投身 n. 跳水；猛跌","tag":"高频","root":"","exampleEN":"He decided to plunge into the adventure of learning a completely new instrument.","exampleCN":"他决定全身心投入到学习一件全新乐器的冒险中。","extra":""},{"chapter":9,"key":"9:149","id":149,"word":"spring","phonetic":"/sprɪŋ/","pos":"v./n.","meaningCN":"跳，跃","tag":"高频","root":"","exampleEN":"The cat sprang from the floor onto the windowsill in one smooth motion.","exampleCN":"猫一个轻巧的动作从地板上跳到窗台上。","extra":""},{"chapter":9,"key":"9:150","id":150,"word":"hop","phonetic":"/hɒp/","pos":"v.","meaningCN":"跳上（或下）；单脚跳行；齐足跳行","tag":"低频","root":"","exampleEN":"The rabbit hopped across the field and disappeared into the bushes.","exampleCN":"兔子跳着穿过田野，消失在灌木丛中。","extra":""},{"chapter":9,"key":"9:151","id":151,"word":"bounce","phonetic":"/baʊns/","pos":"v.","meaningCN":"（使）反弹，（使）弹起；（使）跳动","tag":"高频","root":"","exampleEN":"The children love to bounce on the trampoline in the backyard.","exampleCN":"孩子们喜欢在后院的蹦床上弹跳。","extra":""},{"chapter":9,"key":"9:152","id":152,"word":"tent","phonetic":"/tent/","pos":"n.","meaningCN":"帐篷","tag":"核心","root":"","exampleEN":"We pitched our tent by the lake and spent the night listening to the sounds of nature.","exampleCN":"我们在湖边支起帐篷，整晚听着大自然的声音。","extra":""},{"chapter":9,"key":"9:153","id":153,"word":"camp","phonetic":"/kæmp/","pos":"n.","meaningCN":"营地；阵营","tag":"核心","root":"","exampleEN":"Summer camp provides children with a chance to make new friends and try new activities.","exampleCN":"夏令营给孩子们提供了一个交新朋友、尝试新活动的机会。","extra":""},{"chapter":9,"key":"9:154","id":154,"word":"picnic","phonetic":"/ˈpɪknɪk/","pos":"n.","meaningCN":"野餐；野餐食物 v. 野餐","tag":"核心","root":"","exampleEN":"The family enjoyed a lovely picnic on the grassy riverbank.","exampleCN":"一家人在长满青草的河岸上享受了愉快的野餐。","extra":"搭配：go for a picnic 去野餐。"},{"chapter":9,"key":"9:155","id":155,"word":"hunt","phonetic":"/hʌnt/","pos":"v./n.","meaningCN":"打猎；搜寻","tag":"高频","root":"hunter n. 猎人","exampleEN":"We had great fun hunting for shells along the beach after the tide went out.","exampleCN":"退潮后，我们在海滩上寻找贝壳，玩得很开心。","extra":"搭配：hunt for 寻找。"},{"chapter":9,"key":"9:156","id":156,"word":"race","phonetic":"/reɪs/","pos":"n.","meaningCN":"赛跑，速度竞赛；人种，种族","tag":"核心","root":"","exampleEN":"The annual boat race on the river attracts teams from neighbouring cities.","exampleCN":"一年一度的河上划船比赛吸引了来自邻近城市的队伍。","extra":""},{"chapter":9,"key":"9:157","id":157,"word":"marathon","phonetic":"/ˈmærəθən/","pos":"n.","meaningCN":"马拉松赛跑；马拉松式的活动","tag":"高频","root":"","exampleEN":"Running a marathon requires months of careful preparation and mental strength.","exampleCN":"跑马拉松需要数月的精心准备和强大的心理素质。","extra":""},{"chapter":9,"key":"9:158","id":158,"word":"pedestrian","phonetic":"/pəˈdestriən/","pos":"n.","meaningCN":"步行者，行人","tag":"高频","root":"","exampleEN":"The city centre was closed to traffic, allowing pedestrians to walk freely.","exampleCN":"市中心禁止车辆通行，让行人可以自由行走。","extra":"搭配：a pedestrian crossing 人行横道。"},{"chapter":9,"key":"9:159","id":159,"word":"pace","phonetic":"/peɪs/","pos":"n.","meaningCN":"步速，速度；步调，节奏 v. 来回踱步","tag":"核心","root":"","exampleEN":"The guide set a steady pace so that everyone could enjoy the scenery without rushing.","exampleCN":"向导保持稳定的步速，让每个人都能从容欣赏风景。","extra":"搭配：set the pace 确立标准。"},{"chapter":9,"key":"9:160","id":160,"word":"step","phonetic":"/step/","pos":"n.","meaningCN":"步伐；步骤","tag":"核心","root":"footstep n. 脚步声；足迹","exampleEN":"Learning a dance routine is easier if you practise each step carefully.","exampleCN":"如果认真练习每一个舞步，学舞会更简单。","extra":"搭配：step by step 一步一步。"},{"chapter":9,"key":"9:161","id":161,"word":"excursion","phonetic":"/ɪkˈskɜːʃən/","pos":"n.","meaningCN":"远足，短程旅行","tag":"低频","root":"","exampleEN":"The school organised an excursion to the natural history museum.","exampleCN":"学校组织了一次去自然历史博物馆的短途旅行。","extra":""},{"chapter":9,"key":"9:162","id":162,"word":"cruise","phonetic":"/kruːz/","pos":"v.","meaningCN":"乘船游览；以平稳的速度行驶","tag":"高频","root":"cruiser n. 巡洋舰；舱式游艇；巡逻警车","exampleEN":"They plan to cruise around the Greek islands during their summer holiday.","exampleCN":"他们计划暑假乘船游览希腊群岛。","extra":""},{"chapter":9,"key":"9:163","id":163,"word":"trip","phonetic":"/trɪp/","pos":"v.","meaningCN":"绊倒 n. 旅行；绊倒","tag":"核心","root":"","exampleEN":"A trip to the countryside can be a refreshing break from city life.","exampleCN":"去乡下旅行可以让你从城市生活中暂时解脱出来。","extra":""},{"chapter":9,"key":"9:164","id":164,"word":"vacation","phonetic":"/vəˈkeɪʃən/","pos":"v.","meaningCN":"休假 n. 休假；假期","tag":"核心","root":"vocation n. 职业","exampleEN":"She spent her summer vacation volunteering at a local cultural festival.","exampleCN":"她利用暑假在当地的文化节做志愿者。","extra":""},{"chapter":9,"key":"9:165","id":165,"word":"hike","phonetic":"/haɪk/","pos":"v./n.","meaningCN":"徒步旅行，远足","tag":"高频","root":"hiking n. 徒步旅行","exampleEN":"They hiked up the mountain to watch the sunrise from the peak.","exampleCN":"他们徒步上山，去山顶看日出。","extra":""},{"chapter":9,"key":"9:166","id":166,"word":"jog","phonetic":"/dʒɒɡ/","pos":"v.","meaningCN":"慢跑","tag":"高频","root":"jogger n. 慢跑锻炼的人； jogging n. 慢跑","exampleEN":"Many people jog in the park in the early morning before starting their day.","exampleCN":"许多人清晨在公园慢跑，然后开始新的一天。","extra":""},{"chapter":9,"key":"9:167","id":167,"word":"stride","phonetic":"/straɪd/","pos":"v.","meaningCN":"大步走，阔步行走","tag":"低频","root":"","exampleEN":"She strode confidently onto the stage to receive the award.","exampleCN":"她自信地大步走上舞台领奖。","extra":""},{"chapter":9,"key":"9:168","id":168,"word":"wander","phonetic":"/ˈwɒndə/","pos":"v.","meaningCN":"闲逛，漫步；走神，开小差","tag":"高频","root":"","exampleEN":"We spent the afternoon wandering through the old streets and trying local snacks.","exampleCN":"我们整个下午都在老街上闲逛，品尝当地小吃。","extra":""},{"chapter":9,"key":"9:169","id":169,"word":"linger","phonetic":"/ˈlɪŋɡə/","pos":"v.","meaningCN":"逗留，流连；继续存留","tag":"低频","root":"","exampleEN":"The aroma of fresh coffee lingered in the café long after the customers had left.","exampleCN":"顾客离去很久之后，咖啡馆里仍飘着新鲜咖啡的香气。","extra":""},{"chapter":9,"key":"9:170","id":170,"word":"lag","phonetic":"/læɡ/","pos":"v.","meaningCN":"落后 n. 间隔，时间差","tag":"高频","root":"","exampleEN":"Some video games suffer from lag, making them less enjoyable to play.","exampleCN":"一些电子游戏存在延迟问题，影响游戏体验。","extra":"搭配：lag behind sb./sth. 落后于。"},{"chapter":9,"key":"9:171","id":171,"word":"climb","phonetic":"/klaɪm/","pos":"v.","meaningCN":"攀登，爬","tag":"核心","root":"limb n. 肢；树枝","exampleEN":"They spent the weekend climbing the steep cliffs along the coast.","exampleCN":"他们周末去攀登了沿海的陡峭悬崖。","extra":""},{"chapter":9,"key":"9:172","id":172,"word":"pull","phonetic":"/pʊl/","pos":"v.","meaningCN":"拉，拖，扯；划（小船）","tag":"核心","root":"","exampleEN":"The children pulled the sled up the hill for another ride down.","exampleCN":"孩子们把雪橇拉上山，准备再滑下来。","extra":""},{"chapter":9,"key":"9:173","id":173,"word":"drag","phonetic":"/dræɡ/","pos":"v.","meaningCN":"拖，拉，拽","tag":"高频","root":"","exampleEN":"He dragged the heavy suitcase up the stairs to the hotel room.","exampleCN":"他把沉重的行李箱拖上楼上的酒店房间。","extra":""},{"chapter":9,"key":"9:174","id":174,"word":"bend","phonetic":"/bend/","pos":"v.","meaningCN":"俯身，弯腰；使弯曲","tag":"核心","root":"","exampleEN":"She bent down to pick up the book that had fallen on the floor.","exampleCN":"她弯腰捡起掉在地上的书。","extra":"搭配：bend over backwards to do sth. 竭尽全力。"},{"chapter":9,"key":"9:175","id":175,"word":"bow","phonetic":"/baʊ/","pos":"v./n.","meaningCN":"鞠躬","tag":"高频","root":"","exampleEN":"The performers bowed deeply to thank the audience for their enthusiastic applause.","exampleCN":"表演者深深鞠躬，感谢观众热烈的掌声。","extra":"搭配：take a bow 谢幕。"}],"10":[{"chapter":10,"key":"10:1","id":1,"word":"stuff","phonetic":"/stʌf/","pos":"n.","meaningCN":"东西；原料","tag":"核心","root":"","exampleEN":"She packed all her stuff into two suitcases before leaving for university.","exampleCN":"她把所有东西装进两个箱子后就出发去上大学了。","extra":""},{"chapter":10,"key":"10:2","id":2,"word":"item","phonetic":"/ˈaɪtəm/","pos":"n.","meaningCN":"一件物品，一件商品","tag":"核心","root":"","exampleEN":"The receipt lists every item you purchased at the store.","exampleCN":"收据上列出了你在店里购买的每一件商品。","extra":""},{"chapter":10,"key":"10:3","id":3,"word":"merchandise","phonetic":"/ˈmɜːtʃəndaɪz/","pos":"n.","meaningCN":"商品","tag":"高频","root":"","exampleEN":"The shop offers a wide range of official sports merchandise.","exampleCN":"这家商店提供各式各样的官方体育商品。","extra":""},{"chapter":10,"key":"10:4","id":4,"word":"souvenir","phonetic":"/ˌsuːvəˈnɪə/","pos":"n.","meaningCN":"纪念品","tag":"高频","root":"","exampleEN":"I bought a small wooden carving as a souvenir of my trip to the ancient town.","exampleCN":"我买了一个小木雕作为古镇之旅的纪念品。","extra":""},{"chapter":10,"key":"10:5","id":5,"word":"artefact","phonetic":"/ˈɑːtɪfækt/","pos":"n.","meaningCN":"人造物品；手工艺品","tag":"高频","root":"artificial（人造的）+ fact（制作）→ 用技艺制作的东西","exampleEN":"The museum displays artefacts from the Ming Dynasty, including pottery and tools.","exampleCN":"博物馆展出了明代的器物，包括陶器和工具。","extra":""},{"chapter":10,"key":"10:6","id":6,"word":"material","phonetic":"/məˈtɪəriəl/","pos":"n.","meaningCN":"材料，原料；人才 adj. 物质的","tag":"核心","root":"","exampleEN":"The bridge was built using strong, weather-resistant materials.","exampleCN":"这座桥是用坚固耐候的材料建造的。","extra":""},{"chapter":10,"key":"10:7","id":7,"word":"raw","phonetic":"/rɔː/","pos":"adj.","meaningCN":"天然的，未经加工的；（感情）原始的","tag":"核心","root":"","exampleEN":"The factory imports raw cotton and exports finished textiles.","exampleCN":"这家工厂进口原棉，出口成品纺织品。","extra":"搭配：raw material 原材料。"},{"chapter":10,"key":"10:8","id":8,"word":"crude","phonetic":"/kruːd/","pos":"adj.","meaningCN":"天然的，未经加工的；粗糙的 n. 原油","tag":"高频","root":"","exampleEN":"Crude oil is refined into petrol, diesel, and other useful products.","exampleCN":"原油被提炼成汽油、柴油和其他有用的产品。","extra":""},{"chapter":10,"key":"10:9","id":9,"word":"necessity","phonetic":"/nəˈsesəti/","pos":"n.","meaningCN":"必需品，必不可少的事物；必要","tag":"高频","root":"necessary（必需的）","exampleEN":"Clean drinking water is a basic necessity for human survival.","exampleCN":"清洁的饮用水是人类生存的基本必需品。","extra":""},{"chapter":10,"key":"10:10","id":10,"word":"outfit","phonetic":"/ˈaʊtfɪt/","pos":"n.","meaningCN":"全套服装；全套装备 v. 配备，装备","tag":"高频","root":"","exampleEN":"She wore a stylish new outfit to the party.","exampleCN":"她穿了一套时髦的新衣服去参加聚会。","extra":""},{"chapter":10,"key":"10:11","id":11,"word":"kit","phonetic":"/kɪt/","pos":"n.","meaningCN":"成套工具","tag":"高频","root":"","exampleEN":"The emergency kit includes a flashlight, bandages, and bottled water.","exampleCN":"应急工具包里有手电筒、绷带和瓶装水。","extra":""},{"chapter":10,"key":"10:12","id":12,"word":"utensil","phonetic":"/juːˈtensəl/","pos":"n.","meaningCN":"（家庭）用具，器皿","tag":"低频","root":"","exampleEN":"She placed the cooking utensils neatly into the kitchen drawer.","exampleCN":"她把烹饪用具整齐地放进厨房抽屉里。","extra":""},{"chapter":10,"key":"10:13","id":13,"word":"garbage","phonetic":"/ˈɡɑːbɪdʒ/","pos":"n.","meaningCN":"【尤美】垃圾，废物","tag":"核心","root":"","exampleEN":"Please take out the garbage before the truck arrives.","exampleCN":"请在垃圾车来之前把垃圾拿出去。","extra":"搭配：a garbage can 垃圾箱。"},{"chapter":10,"key":"10:14","id":14,"word":"rubbish","phonetic":"/ˈrʌbɪʃ/","pos":"n.","meaningCN":"【尤英】垃圾，废弃物，废话","tag":"核心","root":"","exampleEN":"The playground was covered with rubbish after the concert.","exampleCN":"音乐会结束后，操场上到处都是垃圾。","extra":"搭配：clear away the rubbish 清除垃圾。"},{"chapter":10,"key":"10:15","id":15,"word":"trash","phonetic":"/træʃ/","pos":"n.","meaningCN":"【美】垃圾","tag":"核心","root":"","exampleEN":"He threw the empty can into the trash bin.","exampleCN":"他把空罐子扔进了垃圾桶。","extra":""},{"chapter":10,"key":"10:16","id":16,"word":"recycle","phonetic":"/riːˈsaɪkl/","pos":"v.","meaningCN":"使再循环，回收利用；反复应用","tag":"核心","root":"cycle（循环）+ re（重复）→ 回收利用","exampleEN":"People are encouraged to recycle paper, glass, and plastic.","exampleCN":"人们被鼓励回收纸张、玻璃和塑料。","extra":""},{"chapter":10,"key":"10:17","id":17,"word":"reuse","phonetic":"/riːˈjuːz/","pos":"v.","meaningCN":"再次使用","tag":"高频","root":"","exampleEN":"She washes and reuses glass jars for storing spices.","exampleCN":"她把玻璃罐洗干净后再次用来储存调料。","extra":""},{"chapter":10,"key":"10:18","id":18,"word":"litter","phonetic":"/ˈlɪtə/","pos":"n.","meaningCN":"垃圾，废弃物 v. 乱丢东西","tag":"高频","root":"","exampleEN":"Dropping litter in the park can result in a fine.","exampleCN":"在公园里乱扔垃圾可能会被罚款。","extra":""},{"chapter":10,"key":"10:19","id":19,"word":"waste","phonetic":"/weɪst/","pos":"n.","meaningCN":"废物；浪费 v. 浪费","tag":"核心","root":"","exampleEN":"Reducing food waste is an important step toward protecting the environment.","exampleCN":"减少食物浪费是保护环境的重要一步。","extra":""},{"chapter":10,"key":"10:20","id":20,"word":"junk","phonetic":"/dʒʌŋk/","pos":"n.","meaningCN":"无用的东西，废物","tag":"高频","root":"","exampleEN":"Eating too much junk food can lead to health problems.","exampleCN":"吃太多垃圾食品会导致健康问题。","extra":"搭配：junk food 垃圾食品。"},{"chapter":10,"key":"10:21","id":21,"word":"landfill","phonetic":"/ˈlændfɪl/","pos":"n.","meaningCN":"垃圾填埋地；垃圾填埋","tag":"低频","root":"","exampleEN":"Much of our household waste ends up in landfill sites.","exampleCN":"我们的许多家庭垃圾最终都进了填埋场。","extra":""},{"chapter":10,"key":"10:22","id":22,"word":"sewerage","phonetic":"/ˈsjuːərɪdʒ/","pos":"n.","meaningCN":"排水系统，污水处理系统；（= sewage）污水","tag":"识记","root":"","exampleEN":"The city invested millions in upgrading its sewerage system.","exampleCN":"该市投资了数百万升级排水系统。","extra":""},{"chapter":10,"key":"10:23","id":23,"word":"detergent","phonetic":"/dɪˈtɜːdʒənt/","pos":"n.","meaningCN":"洗涤剂","tag":"低频","root":"","exampleEN":"This detergent is gentle on hands but tough on stains.","exampleCN":"这种洗涤剂不伤手，但去污力很强。","extra":""},{"chapter":10,"key":"10:24","id":24,"word":"lotion","phonetic":"/ˈləʊʃən/","pos":"n.","meaningCN":"洁肤乳；润肤乳","tag":"低频","root":"","exampleEN":"Apply sunscreen lotion before going out in the sun.","exampleCN":"在阳光下外出前要涂防晒乳。","extra":""},{"chapter":10,"key":"10:25","id":25,"word":"shampoo","phonetic":"/ʃæmˈpuː/","pos":"v.","meaningCN":"用洗发剂洗（头发） n. 洗发剂","tag":"核心","root":"","exampleEN":"She shampoos her hair twice a week to keep it shiny.","exampleCN":"她每周洗两次头发，以保持头发光亮。","extra":""},{"chapter":10,"key":"10:26","id":26,"word":"soap","phonetic":"/səʊp/","pos":"n.","meaningCN":"肥皂 v. 用肥皂擦洗","tag":"核心","root":"","exampleEN":"Wash your hands carefully with soap and warm water.","exampleCN":"用肥皂和温水仔细洗手。","extra":"搭配：a soap opera 肥皂剧。"},{"chapter":10,"key":"10:27","id":27,"word":"tub","phonetic":"/tʌb/","pos":"n.","meaningCN":"桶，盆；【美】浴缸，浴盆","tag":"低频","root":"","exampleEN":"She filled the tub with hot water and added some bath salts.","exampleCN":"她把浴缸放满热水，加了一些浴盐。","extra":""},{"chapter":10,"key":"10:28","id":28,"word":"plug","phonetic":"/plʌɡ/","pos":"n.","meaningCN":"塞子；插头 v. 把......塞住","tag":"高频","root":"","exampleEN":"He put the plug in the sink and filled it with water.","exampleCN":"他把塞子塞在水槽里，放满了水。","extra":""},{"chapter":10,"key":"10:29","id":29,"word":"tap","phonetic":"/tæp/","pos":"n.","meaningCN":"旋塞，龙头","tag":"高频","root":"","exampleEN":"Turn off the tap while you are brushing your teeth to save water.","exampleCN":"刷牙时关掉水龙头以节约用水。","extra":""},{"chapter":10,"key":"10:30","id":30,"word":"pipe","phonetic":"/paɪp/","pos":"n.","meaningCN":"管子，管道；烟斗","tag":"高频","root":"pipeline n. 管道，管线","exampleEN":"A burst water pipe caused the street to flood.","exampleCN":"一根破裂的水管导致街道被淹。","extra":""},{"chapter":10,"key":"10:31","id":31,"word":"tube","phonetic":"/tjuːb/","pos":"n.","meaningCN":"管；（电视机的）显像管；【英】（伦敦）地铁","tag":"高频","root":"","exampleEN":"He squeezed the last bit of paint out of the tube.","exampleCN":"他从管里挤出了最后一点颜料。","extra":""},{"chapter":10,"key":"10:32","id":32,"word":"mop","phonetic":"/mɒp/","pos":"n.","meaningCN":"拖把 v. 用拖把擦","tag":"低频","root":"","exampleEN":"She used a mop to clean the kitchen floor after spilling juice.","exampleCN":"她把果汁洒了后，用拖把清洁厨房地面。","extra":""},{"chapter":10,"key":"10:33","id":33,"word":"broom","phonetic":"/bruːm/","pos":"n.","meaningCN":"扫帚 v. 用扫帚扫","tag":"低频","root":"","exampleEN":"He swept the fallen leaves off the path with a broom.","exampleCN":"他用扫帚扫去了小路上的落叶。","extra":""},{"chapter":10,"key":"10:34","id":34,"word":"sweep","phonetic":"/swiːp/","pos":"v.","meaningCN":"打扫；（迅猛地）吹走；掠过","tag":"高频","root":"","exampleEN":"Strong winds swept the dust high into the air.","exampleCN":"大风把尘土卷到了空中。","extra":"短语：sweep the board 囊括所有奖项。"},{"chapter":10,"key":"10:35","id":35,"word":"mattress","phonetic":"/ˈmætrəs/","pos":"n.","meaningCN":"床垫","tag":"低频","root":"","exampleEN":"A good mattress can greatly improve the quality of your sleep.","exampleCN":"一张好床垫能大大提高你的睡眠质量。","extra":""},{"chapter":10,"key":"10:36","id":36,"word":"carpet","phonetic":"/ˈkɑːpɪt/","pos":"n.","meaningCN":"地毯，毡毯，毛毯","tag":"高频","root":"","exampleEN":"They rolled out a thick red carpet for the guests at the ceremony.","exampleCN":"他们为典礼上的来宾铺上了厚厚的红地毯。","extra":"搭配：red carpet 红地毯。"},{"chapter":10,"key":"10:37","id":37,"word":"rug","phonetic":"/rʌɡ/","pos":"n.","meaningCN":"小地毯；（盖肩或腿的）小毯子","tag":"低频","root":"","exampleEN":"A colourful woven rug covered the floor of the old room.","exampleCN":"一张彩色编织地毯铺在老房间的地板上。","extra":""},{"chapter":10,"key":"10:38","id":38,"word":"mat","phonetic":"/mæt/","pos":"n.","meaningCN":"地垫，地席","tag":"低频","root":"","exampleEN":"Please wipe your feet on the mat before entering the temple.","exampleCN":"请在进庙前在地垫上擦擦脚。","extra":""},{"chapter":10,"key":"10:39","id":39,"word":"cushion","phonetic":"/ˈkʊʃən/","pos":"n.","meaningCN":"软垫","tag":"高频","root":"","exampleEN":"She placed a soft cushion on the chair before sitting down.","exampleCN":"她先放了个软垫在椅子上，然后才坐下。","extra":"搭配：a sofa cushion 沙发垫。"},{"chapter":10,"key":"10:40","id":40,"word":"pad","phonetic":"/pæd/","pos":"n.","meaningCN":"衬垫，垫；便笺本 v.（用软材料）填塞","tag":"低频","root":"","exampleEN":"She wrote the address on a pad of paper by the telephone.","exampleCN":"她把地址写在电话旁的便笺本上。","extra":""},{"chapter":10,"key":"10:41","id":41,"word":"blanket","phonetic":"/ˈblæŋkɪt/","pos":"n.","meaningCN":"毛毯，毯子","tag":"核心","root":"","exampleEN":"He pulled the blanket over himself and fell asleep.","exampleCN":"他把毯子拉过来盖好，睡着了。","extra":""},{"chapter":10,"key":"10:42","id":42,"word":"quilt","phonetic":"/kwɪlt/","pos":"n.","meaningCN":"被子","tag":"低频","root":"","exampleEN":"Her grandmother made a warm patchwork quilt by hand.","exampleCN":"她的祖母手工做了一床温暖的拼布被子。","extra":""},{"chapter":10,"key":"10:43","id":43,"word":"sheet","phonetic":"/ʃiːt/","pos":"n.","meaningCN":"被单，床单；一张（纸）；薄板","tag":"核心","root":"","exampleEN":"The hotel changes the bed sheets every day.","exampleCN":"酒店每天更换床单。","extra":""},{"chapter":10,"key":"10:44","id":44,"word":"pillow","phonetic":"/ˈpɪləʊ/","pos":"n.","meaningCN":"枕头","tag":"核心","root":"","exampleEN":"He rested his head on the soft pillow and quickly fell asleep.","exampleCN":"他把头靠在柔软的枕头上，很快就睡着了。","extra":""},{"chapter":10,"key":"10:45","id":45,"word":"sponge","phonetic":"/spʌndʒ/","pos":"n.","meaningCN":"海绵","tag":"高频","root":"","exampleEN":"Use a damp sponge to wipe the dust off the blackboard.","exampleCN":"用湿海绵擦去黑板上的灰尘。","extra":""},{"chapter":10,"key":"10:46","id":46,"word":"towel","phonetic":"/ˈtaʊəl/","pos":"n.","meaningCN":"毛巾，手巾","tag":"核心","root":"","exampleEN":"She dried her hair with a clean towel after the shower.","exampleCN":"淋浴后，她用一条干净毛巾擦干了头发。","extra":"搭配：wring a towel 拧毛巾。"},{"chapter":10,"key":"10:47","id":47,"word":"staple","phonetic":"/ˈsteɪpl/","pos":"n.","meaningCN":"订书钉；主要部分","tag":"高频","root":"","exampleEN":"Rice is a staple food for more than half of the world's population.","exampleCN":"大米是世界上一半以上人口的主食。","extra":""},{"chapter":10,"key":"10:48","id":48,"word":"nail","phonetic":"/neɪl/","pos":"n.","meaningCN":"指甲；钉子 v.（用钉子）钉住","tag":"核心","root":"","exampleEN":"She hammered a nail into the wall to hang the picture.","exampleCN":"她在墙上钉了个钉子挂画。","extra":""},{"chapter":10,"key":"10:49","id":49,"word":"razor","phonetic":"/ˈreɪzə/","pos":"n.","meaningCN":"剃刀 v.（用剃刀）剃","tag":"低频","root":"","exampleEN":"He used an electric razor to shave off his beard.","exampleCN":"他用电动剃须刀剃掉了胡须。","extra":"搭配：an electric razor 电动剃须刀。"},{"chapter":10,"key":"10:50","id":50,"word":"shave","phonetic":"/ʃeɪv/","pos":"v.","meaningCN":"剃须，刮脸","tag":"高频","root":"shaver n. 理发师；电动剃须刀","exampleEN":"He shaves every morning before going to work.","exampleCN":"他每天早上上班前刮胡子。","extra":""},{"chapter":10,"key":"10:51","id":51,"word":"fuse","phonetic":"/fjuːz/","pos":"n.","meaningCN":"保险丝；导火线 v.（使）熔化；（使）融合","tag":"低频","root":"","exampleEN":"The lights went out because a fuse had blown.","exampleCN":"灯灭了，因为保险丝烧断了。","extra":""},{"chapter":10,"key":"10:52","id":52,"word":"cable","phonetic":"/ˈkeɪbəl/","pos":"n.","meaningCN":"电缆；缆绳，钢索；电报；有线电视","tag":"高频","root":"","exampleEN":"The internet connection is provided through a fibre-optic cable.","exampleCN":"互联网连接是通过光纤电缆提供的。","extra":"搭配：a cable car 缆车。"},{"chapter":10,"key":"10:53","id":53,"word":"cord","phonetic":"/kɔːd/","pos":"n.","meaningCN":"细绳，粗线","tag":"低频","root":"与 chord（弦）相关：strike/touch a chord in/with sb. 拨动某人心弦","exampleEN":"She tied the package with a strong piece of cord.","exampleCN":"她用一根结实的绳子捆好包裹。","extra":""},{"chapter":10,"key":"10:54","id":54,"word":"strand","phonetic":"/strænd/","pos":"n.","meaningCN":"缕，股；滨，岸","tag":"低频","root":"","exampleEN":"A single strand of hair fell across her forehead.","exampleCN":"一缕头发垂落在她的前额上。","extra":""},{"chapter":10,"key":"10:55","id":55,"word":"match","phonetic":"/mætʃ/","pos":"n.","meaningCN":"火柴；比赛；匹配的人或物 v. 与......匹配","tag":"核心","root":"","exampleEN":"She lit the candle with a match from the box on the shelf.","exampleCN":"她用架子上火柴盒里的一根火柴点燃了蜡烛。","extra":"搭配：meet one's match 遇到对手。"},{"chapter":10,"key":"10:56","id":56,"word":"candle","phonetic":"/ˈkændl/","pos":"n.","meaningCN":"蜡烛","tag":"高频","root":"","exampleEN":"The room was lit by the soft glow of a single candle.","exampleCN":"房间被一支蜡烛的柔和光芒照亮。","extra":"搭配：light / blow out a candle 点亮/吹灭蜡烛。"},{"chapter":10,"key":"10:57","id":57,"word":"wax","phonetic":"/wæks/","pos":"n.","meaningCN":"蜡；蜂蜡","tag":"低频","root":"","exampleEN":"The floor was polished with wax until it shone.","exampleCN":"地板打了蜡，擦得闪闪发亮。","extra":""},{"chapter":10,"key":"10:58","id":58,"word":"portfolio","phonetic":"/pɔːtˈfəʊliəʊ/","pos":"n.","meaningCN":"文件夹，公事包","tag":"低频","root":"port（拿，带）+ folio（对开本）→ 公事包","exampleEN":"The designer showed her portfolio to the potential employer.","exampleCN":"设计师向潜在雇主展示了自己的作品集。","extra":""},{"chapter":10,"key":"10:59","id":59,"word":"paperback","phonetic":"/ˈpeɪpəbæk/","pos":"n.","meaningCN":"简装书，平装书","tag":"低频","root":"","exampleEN":"I prefer paperbacks because they are lighter to carry around.","exampleCN":"我更喜欢平装书，因为它们更轻，便于携带。","extra":""},{"chapter":10,"key":"10:60","id":60,"word":"pamphlet","phonetic":"/ˈpæmflət/","pos":"n.","meaningCN":"小册子","tag":"低频","root":"booklet, leaflet, brochure","exampleEN":"The health clinic distributed pamphlets about healthy eating.","exampleCN":"健康诊所分发了有关健康饮食的小册子。","extra":""},{"chapter":10,"key":"10:61","id":61,"word":"tissue","phonetic":"/ˈtɪʃuː/","pos":"n.","meaningCN":"薄绢，薄纸；组织；面巾纸","tag":"高频","root":"","exampleEN":"She handed me a tissue to wipe my tears.","exampleCN":"她递给我一张纸巾擦眼泪。","extra":""},{"chapter":10,"key":"10:62","id":62,"word":"cover","phonetic":"/ˈkʌvə/","pos":"n.","meaningCN":"封面；盖子；套子","tag":"核心","root":"","exampleEN":"The book's cover was torn, but the pages inside were still intact.","exampleCN":"书的封面破了，但里面的书页仍然完好。","extra":""},{"chapter":10,"key":"10:63","id":63,"word":"Xerox","phonetic":"/ˈzɪərɒks/","pos":"n.","meaningCN":"施乐复印件","tag":"识记","root":"","exampleEN":"He made a Xerox of the contract before signing it.","exampleCN":"他在签署合同前复印了一份。","extra":"搭配：a Xerox machine 施乐复印机。"},{"chapter":10,"key":"10:64","id":64,"word":"duplicate","phonetic":"/ˈdjuːplɪkət/","pos":"n.","meaningCN":"副本，复制品","tag":"高频","root":"","exampleEN":"Please keep the original document and give me a duplicate.","exampleCN":"请保留原件，给我一份副本。","extra":"动词读 /ˈdjuːplɪkeɪt/。"},{"chapter":10,"key":"10:65","id":65,"word":"memorandum","phonetic":"/ˌmeməˈrændəm/","pos":"n.","meaningCN":"备忘录；建议书；（= memo）公务便条","tag":"低频","root":"memor（记着）+ andum → 备忘录","exampleEN":"The manager sent a memorandum to all staff detailing the new policy.","exampleCN":"经理向所有员工发了一份备忘录，详细说明了新政策。","extra":""},{"chapter":10,"key":"10:66","id":66,"word":"stationery","phonetic":"/ˈsteɪʃənəri/","pos":"n.","meaningCN":"文具；信纸","tag":"低频","root":"stationer n. 文具店；文具商","exampleEN":"I bought some elegant stationery to write letters to my friends.","exampleCN":"我买了一些雅致的信纸给朋友们写信。","extra":""},{"chapter":10,"key":"10:67","id":67,"word":"glue","phonetic":"/ɡluː/","pos":"n.","meaningCN":"胶，胶水","tag":"高频","root":"","exampleEN":"He used strong glue to fix the broken handle of the mug.","exampleCN":"他用强力胶把杯子的断柄粘好了。","extra":""},{"chapter":10,"key":"10:68","id":68,"word":"ink","phonetic":"/ɪŋk/","pos":"n.","meaningCN":"墨水，油墨","tag":"高频","root":"","exampleEN":"The printer ran out of black ink in the middle of printing.","exampleCN":"印到一半，打印机的黑色墨水用完了。","extra":""},{"chapter":10,"key":"10:69","id":69,"word":"rubber","phonetic":"/ˈrʌbə/","pos":"n.","meaningCN":"橡胶；【英】橡皮擦","tag":"高频","root":"","exampleEN":"Please lend me your rubber; I need to erase this mistake.","exampleCN":"请借我你的橡皮，我需要擦掉这个错误。","extra":""},{"chapter":10,"key":"10:70","id":70,"word":"scissors","phonetic":"/ˈsɪzəz/","pos":"n.","meaningCN":"剪刀，剪子","tag":"核心","root":"","exampleEN":"She cut the paper into small shapes with a pair of scissors.","exampleCN":"她用剪刀把纸剪成各种小形状。","extra":""},{"chapter":10,"key":"10:71","id":71,"word":"shear","phonetic":"/ʃɪə/","pos":"n.","meaningCN":"[-s]（尤指修剪篱笆用的）大剪刀 v. 剪","tag":"识记","root":"","exampleEN":"The farmer used shears to trim the wool from the sheep.","exampleCN":"农夫用大剪刀给羊剪毛。","extra":""},{"chapter":10,"key":"10:72","id":72,"word":"edge","phonetic":"/edʒ/","pos":"n.","meaningCN":"边缘，边；刀口","tag":"核心","root":"","exampleEN":"Be careful not to cut your finger on the sharp edge of the knife.","exampleCN":"小心别被刀刃割了手指。","extra":""},{"chapter":10,"key":"10:73","id":73,"word":"rim","phonetic":"/rɪm/","pos":"n.","meaningCN":"（圆形物的）外缘，边缘","tag":"低频","root":"","exampleEN":"Water dripped slowly over the rim of the full glass.","exampleCN":"水从满杯的边缘慢慢滴下。","extra":""},{"chapter":10,"key":"10:74","id":74,"word":"element","phonetic":"/ˈelɪmənt/","pos":"n.","meaningCN":"（化学中的）元素；组成部分；基本部分","tag":"核心","root":"","exampleEN":"Carbon is a chemical element found in all living things.","exampleCN":"碳是所有生物中都含有的一种化学元素。","extra":""},{"chapter":10,"key":"10:75","id":75,"word":"factor","phonetic":"/ˈfæktə/","pos":"n.","meaningCN":"因素，要素","tag":"核心","root":"","exampleEN":"Price is a major factor when people decide which product to buy.","exampleCN":"价格是人们决定购买哪种产品时的一个主要因素。","extra":""},{"chapter":10,"key":"10:76","id":76,"word":"section","phonetic":"/ˈsekʃən/","pos":"n.","meaningCN":"部分；章，节","tag":"核心","root":"sect（切割）→ section","exampleEN":"The toy section is located on the third floor of the store.","exampleCN":"玩具区位于商店的三楼。","extra":""},{"chapter":10,"key":"10:77","id":77,"word":"tag","phonetic":"/tæɡ/","pos":"n.","meaningCN":"标签；称号","tag":"高频","root":"","exampleEN":"The price tag on the shirt said it was on sale.","exampleCN":"这件衬衫上的价格标签表明它在打折。","extra":""},{"chapter":10,"key":"10:78","id":78,"word":"label","phonetic":"/ˈleɪbəl/","pos":"n.","meaningCN":"标签，标贴","tag":"核心","root":"","exampleEN":"Read the label carefully to check the ingredients before buying.","exampleCN":"购买前仔细阅读标签，检查成分。","extra":""},{"chapter":10,"key":"10:79","id":79,"word":"badge","phonetic":"/bædʒ/","pos":"n.","meaningCN":"徽章；证章；标志，象征","tag":"低频","root":"","exampleEN":"Each conference participant wore a name badge.","exampleCN":"每位与会者都佩戴了姓名牌。","extra":""},{"chapter":10,"key":"10:80","id":80,"word":"bolt","phonetic":"/bəʊlt/","pos":"n.","meaningCN":"螺栓；插销 v. 闩上（门、窗）","tag":"低频","root":"","exampleEN":"He slid the bolt across to lock the gate securely.","exampleCN":"他推上插销，牢牢锁住了大门。","extra":""},{"chapter":10,"key":"10:81","id":81,"word":"knob","phonetic":"/nɒb/","pos":"n.","meaningCN":"球形把手；旋钮","tag":"低频","root":"","exampleEN":"Turn the knob to adjust the volume of the radio.","exampleCN":"转动旋钮来调节收音机的音量。","extra":""},{"chapter":10,"key":"10:82","id":82,"word":"handle","phonetic":"/ˈhændl/","pos":"n.","meaningCN":"柄；把手 v. 拿；处理","tag":"核心","root":"","exampleEN":"The suitcase has a sturdy handle that makes it easy to carry.","exampleCN":"这个箱子有一个坚固的把手，便于携带。","extra":"搭配：handle with care 小心轻放。"},{"chapter":10,"key":"10:83","id":83,"word":"shutter","phonetic":"/ˈʃʌtə/","pos":"n.","meaningCN":"百叶窗；（相机）快门 v. 停止（营业）","tag":"低频","root":"","exampleEN":"He closed the wooden shutters to keep out the bright afternoon sun.","exampleCN":"他关上木制百叶窗，挡住午后刺眼的阳光。","extra":""},{"chapter":10,"key":"10:84","id":84,"word":"curtain","phonetic":"/ˈkɜːtən/","pos":"n.","meaningCN":"窗帘；帘；幕布 v. 给......装上帘子","tag":"核心","root":"","exampleEN":"She drew the curtains aside to let the sunlight fill the room.","exampleCN":"她拉开窗帘，让阳光洒满房间。","extra":""},{"chapter":10,"key":"10:85","id":85,"word":"pane","phonetic":"/peɪn/","pos":"n.","meaningCN":"（一块）窗玻璃","tag":"低频","root":"","exampleEN":"A stone broke a pane of the kitchen window during the storm.","exampleCN":"暴风雨中，一块石头打破了厨房窗户的一块玻璃。","extra":""},{"chapter":10,"key":"10:86","id":86,"word":"opacity","phonetic":"/əʊˈpæsəti/","pos":"n.","meaningCN":"不透明性","tag":"识记","root":"opaque n. 不透明物 adj. 不透明的","exampleEN":"The opacity of the glass prevented anyone from seeing inside the room.","exampleCN":"玻璃的不透光性使人无法看到房间内部。","extra":""},{"chapter":10,"key":"10:87","id":87,"word":"jar","phonetic":"/dʒɑː/","pos":"n.","meaningCN":"罐，广口瓶；猛烈震动","tag":"高频","root":"","exampleEN":"She stored the cookies in a glass jar to keep them fresh.","exampleCN":"她把饼干放在一个玻璃罐里保鲜。","extra":""},{"chapter":10,"key":"10:88","id":88,"word":"barrel","phonetic":"/ˈbærəl/","pos":"n.","meaningCN":"桶","tag":"高频","root":"","exampleEN":"They used large wooden barrels to store the wine.","exampleCN":"他们用大木桶储存葡萄酒。","extra":""},{"chapter":10,"key":"10:89","id":89,"word":"bucket","phonetic":"/ˈbʌkɪt/","pos":"n.","meaningCN":"（有提手的）桶","tag":"核心","root":"","exampleEN":"He carried a bucket of water from the well to the garden.","exampleCN":"他从井里提了一桶水到花园。","extra":"搭配：a drop in the bucket 沧海一粟。"},{"chapter":10,"key":"10:90","id":90,"word":"pail","phonetic":"/peɪl/","pos":"n.","meaningCN":"【尤美】（通常是金属或木制的）桶，提桶","tag":"识记","root":"","exampleEN":"The child filled the pail with sand at the beach.","exampleCN":"小孩在海滩上把桶装满了沙子。","extra":""},{"chapter":10,"key":"10:91","id":91,"word":"phone","phonetic":"/fəʊn/","pos":"n.","meaningCN":"电话；电话机；电话听筒","tag":"核心","root":"","exampleEN":"She checked her phone for any new messages.","exampleCN":"她查看了手机，看有没有新消息。","extra":"搭配：make a phone call 打电话。"},{"chapter":10,"key":"10:92","id":92,"word":"bell","phonetic":"/bel/","pos":"n.","meaningCN":"钟；铃","tag":"核心","root":"","exampleEN":"The church bell rings every hour on the hour.","exampleCN":"教堂的钟每个整点敲响。","extra":"搭配：ring a bell 听起来有印象。"},{"chapter":10,"key":"10:93","id":93,"word":"camera","phonetic":"/ˈkæmərə/","pos":"n.","meaningCN":"照相机，摄影机","tag":"核心","root":"","exampleEN":"He bought a new camera to photograph the wildlife during his trip.","exampleCN":"他买了一台新相机，准备在旅行中拍摄野生动物。","extra":""},{"chapter":10,"key":"10:94","id":94,"word":"portable","phonetic":"/ˈpɔːtəbl/","pos":"adj.","meaningCN":"手提式的，便携式的","tag":"高频","root":"","exampleEN":"A portable charger is useful when you are travelling and cannot find a socket.","exampleCN":"旅行中找不到插座时，便携式充电器很有用。","extra":""},{"chapter":10,"key":"10:95","id":95,"word":"spotlight","phonetic":"/ˈspɒtlaɪt/","pos":"n.","meaningCN":"聚光灯；聚光灯照出的光圈","tag":"低频","root":"","exampleEN":"The singer stood alone in the spotlight on the dark stage.","exampleCN":"歌手独自站在黑暗舞台上的聚光灯下。","extra":""},{"chapter":10,"key":"10:96","id":96,"word":"lantern","phonetic":"/ˈlæntən/","pos":"n.","meaningCN":"提灯，灯笼","tag":"高频","root":"","exampleEN":"They hung red paper lanterns to decorate the street for the festival.","exampleCN":"他们挂起红纸灯笼装饰街道迎接节日。","extra":""},{"chapter":10,"key":"10:97","id":97,"word":"bulb","phonetic":"/bʌlb/","pos":"n.","meaningCN":"电灯泡；球茎；球茎状物","tag":"高频","root":"","exampleEN":"The light bulb flickered for a moment and then went out.","exampleCN":"灯泡闪了一下，然后灭了。","extra":""},{"chapter":10,"key":"10:98","id":98,"word":"flashlight","phonetic":"/ˈflæʃlaɪt/","pos":"n.","meaningCN":"（闪光灯的）闪光；手电筒","tag":"高频","root":"","exampleEN":"We used a flashlight to find our way through the dark cave.","exampleCN":"我们用手电筒在黑暗的洞穴中找路。","extra":""},{"chapter":10,"key":"10:99","id":99,"word":"refrigerator","phonetic":"/rɪˈfrɪdʒəreɪtə/","pos":"n.","meaningCN":"冰箱","tag":"核心","root":"refrigeration n. 冷藏","exampleEN":"They stored the fresh vegetables in the refrigerator to keep them crisp.","exampleCN":"他们把新鲜蔬菜存入冰箱保鲜。","extra":""},{"chapter":10,"key":"10:100","id":100,"word":"fridge","phonetic":"/frɪdʒ/","pos":"n.","meaningCN":"冰箱","tag":"核心","root":"","exampleEN":"There is some milk and cheese in the fridge if you are hungry.","exampleCN":"冰箱里有一些牛奶和奶酪，如果你饿了的话。","extra":""},{"chapter":10,"key":"10:101","id":101,"word":"vacuum","phonetic":"/ˈvækjuəm/","pos":"n.","meaningCN":"真空；真空吸尘器 adj. 真空的","tag":"高频","root":"vac(u)/void（空）→ vacuum, evacuate, avoid","exampleEN":"She used the vacuum to clean the dust from the corners of the carpet.","exampleCN":"她用吸尘器清理了地毯角落的灰尘。","extra":""},{"chapter":10,"key":"10:102","id":102,"word":"fan","phonetic":"/fæn/","pos":"n.","meaningCN":"扇子；风扇；狂热爱好者 v. 扇","tag":"核心","root":"","exampleEN":"The room was hot, so she turned on the electric fan.","exampleCN":"房间很热，所以她打开了电扇。","extra":""},{"chapter":10,"key":"10:103","id":103,"word":"switch","phonetic":"/swɪtʃ/","pos":"n.","meaningCN":"开关；转换 v. 转换","tag":"核心","root":"","exampleEN":"Flip the switch on the wall to turn on the light.","exampleCN":"按一下墙上的开关开灯。","extra":""},{"chapter":10,"key":"10:104","id":104,"word":"hurdle","phonetic":"/ˈhɜːdl/","pos":"n.","meaningCN":"栏架；跨栏赛跑","tag":"低频","root":"","exampleEN":"The athlete cleared every hurdle with ease and won the race.","exampleCN":"运动员轻松跨过每一个栏架，赢得了比赛。","extra":""},{"chapter":10,"key":"10:105","id":105,"word":"fence","phonetic":"/fens/","pos":"n.","meaningCN":"栅栏；围栏","tag":"高频","root":"","exampleEN":"They built a wooden fence around the garden to keep the rabbits out.","exampleCN":"他们在花园四周建了木栅栏，防止兔子进入。","extra":"搭配：set up fences 设立栅栏。"},{"chapter":10,"key":"10:106","id":106,"word":"bronze","phonetic":"/brɒnz/","pos":"n.","meaningCN":"青铜；青铜艺术品","tag":"高频","root":"","exampleEN":"The statue in the square is made of bronze and has turned green with age.","exampleCN":"广场上的雕像是青铜铸造的，随着时间流逝已变成绿色。","extra":""},{"chapter":10,"key":"10:107","id":107,"word":"cement","phonetic":"/sɪˈment/","pos":"n.","meaningCN":"水泥；胶接剂 v. 使黏结","tag":"高频","root":"cementer n. 水泥工人","exampleEN":"They mixed cement with sand and water to build the wall.","exampleCN":"他们把水泥与沙子和水混合来砌墙。","extra":""},{"chapter":10,"key":"10:108","id":108,"word":"pitch","phonetic":"/pɪtʃ/","pos":"n.","meaningCN":"沥青","tag":"识记","root":"","exampleEN":"The road workers spread hot pitch to repair the cracks in the surface.","exampleCN":"修路工人铺上热沥青来修补路面裂缝。","extra":""},{"chapter":10,"key":"10:109","id":109,"word":"lime","phonetic":"/laɪm/","pos":"n.","meaningCN":"石灰","tag":"低频","root":"","exampleEN":"Farmers sometimes add lime to the soil to reduce its acidity.","exampleCN":"农民有时往土壤中加石灰以降低其酸度。","extra":""},{"chapter":10,"key":"10:110","id":110,"word":"plaster","phonetic":"/ˈplɑːstə/","pos":"n.","meaningCN":"灰泥；熟石膏","tag":"低频","root":"","exampleEN":"The old plaster on the ceiling was cracked and beginning to fall.","exampleCN":"天花板上旧的灰泥开裂了，开始往下掉。","extra":""},{"chapter":10,"key":"10:111","id":111,"word":"leather","phonetic":"/ˈleðə/","pos":"n.","meaningCN":"皮革；（尤指骑摩托车者穿的）皮衣","tag":"高频","root":"","exampleEN":"She bought a brown leather handbag to match her shoes.","exampleCN":"她买了一个棕色皮手袋来配鞋子。","extra":""},{"chapter":10,"key":"10:112","id":112,"word":"plastic","phonetic":"/ˈplæstɪk/","pos":"n.","meaningCN":"塑料 adj. 有塑性的；塑料的","tag":"核心","root":"","exampleEN":"Reducing the use of single-use plastic is vital for protecting the oceans.","exampleCN":"减少使用一次性塑料对保护海洋至关重要。","extra":""},{"chapter":10,"key":"10:113","id":113,"word":"fibre","phonetic":"/ˈfaɪbə/","pos":"n.","meaningCN":"纤维；纤维素","tag":"高频","root":"","exampleEN":"Whole grains are an excellent source of dietary fibre.","exampleCN":"全谷物是膳食纤维的极佳来源。","extra":""},{"chapter":10,"key":"10:114","id":114,"word":"fabric","phonetic":"/ˈfæbrɪk/","pos":"n.","meaningCN":"织物，布料","tag":"高频","root":"","exampleEN":"The dress is made from a soft, lightweight fabric perfect for summer.","exampleCN":"这件连衣裙是用一种柔软轻薄的布料做的，非常适合夏天。","extra":""},{"chapter":10,"key":"10:115","id":115,"word":"knit","phonetic":"/nɪt/","pos":"v.","meaningCN":"编织，针织","tag":"高频","root":"","exampleEN":"She learned to knit a scarf for her father's birthday gift.","exampleCN":"她学会了织围巾，作为父亲的生日礼物。","extra":""},{"chapter":10,"key":"10:116","id":116,"word":"weave","phonetic":"/wiːv/","pos":"v.","meaningCN":"编织；编造","tag":"低频","root":"","exampleEN":"The women in the village weave beautiful baskets from local bamboo.","exampleCN":"村里的妇女用当地的竹子编织美丽的篮子。","extra":""},{"chapter":10,"key":"10:117","id":117,"word":"canvas","phonetic":"/ˈkænvəs/","pos":"n.","meaningCN":"帆布；油画布","tag":"低频","root":"","exampleEN":"The artist stretched a fresh canvas over the wooden frame before painting.","exampleCN":"画家在作画前把新画布拉紧在木框上。","extra":""},{"chapter":10,"key":"10:118","id":118,"word":"linen","phonetic":"/ˈlɪnɪn/","pos":"n.","meaningCN":"亚麻布；亚麻织品","tag":"低频","root":"","exampleEN":"She prefers bed sheets made of pure linen in the summer.","exampleCN":"夏天她更喜欢纯亚麻的床单。","extra":"搭配：fine linen 上等亚麻布。"},{"chapter":10,"key":"10:119","id":119,"word":"cotton","phonetic":"/ˈkɒtən/","pos":"n.","meaningCN":"棉；棉线；棉布","tag":"核心","root":"","exampleEN":"This shirt is made of one hundred per cent cotton and feels very soft.","exampleCN":"这件衬衫是百分之百纯棉的，触感非常柔软。","extra":""},{"chapter":10,"key":"10:120","id":120,"word":"nylon","phonetic":"/ˈnaɪlɒn/","pos":"n.","meaningCN":"尼龙","tag":"低频","root":"","exampleEN":"Nylon is a strong, lightweight man-made material often used for ropes.","exampleCN":"尼龙是一种坚固、轻质的人造材料，常用于制造绳索。","extra":""},{"chapter":10,"key":"10:121","id":121,"word":"lumber","phonetic":"/ˈlʌmbə/","pos":"n.","meaningCN":"木材，木料","tag":"低频","root":"","exampleEN":"The lumber was cut and dried before being used for building houses.","exampleCN":"木材在用于建房前经过了切割和干燥处理。","extra":""},{"chapter":10,"key":"10:122","id":122,"word":"wooden","phonetic":"/ˈwʊdən/","pos":"adj.","meaningCN":"木制的；呆板的","tag":"核心","root":"","exampleEN":"They sat on wooden benches around a long table in the garden.","exampleCN":"他们坐在花园里一张长桌旁的长木凳上。","extra":""},{"chapter":10,"key":"10:123","id":123,"word":"mine","phonetic":"/maɪn/","pos":"n.","meaningCN":"矿，矿井；地雷","tag":"高频","root":"miner, mineral","exampleEN":"The country is rich in natural resources, including gold and coal mines.","exampleCN":"这个国家自然资源丰富，拥有金矿和煤矿。","extra":""},{"chapter":10,"key":"10:124","id":124,"word":"pit","phonetic":"/pɪt/","pos":"n.","meaningCN":"深坑；煤矿；潜在危险","tag":"高频","root":"","exampleEN":"The excavator dug a deep pit for the foundation of the new building.","exampleCN":"挖掘机为新楼的地基挖了一个深坑。","extra":""},{"chapter":10,"key":"10:125","id":125,"word":"fuel","phonetic":"/ˈfjuːəl/","pos":"n.","meaningCN":"燃料 v. 给......加燃料","tag":"核心","root":"","exampleEN":"The plane stopped at the airport to refuel before continuing its journey.","exampleCN":"飞机在机场停下加油，然后继续航程。","extra":"搭配：add fuel to 火上浇油。"},{"chapter":10,"key":"10:126","id":126,"word":"lubricate","phonetic":"/ˈluːbrɪkeɪt/","pos":"v.","meaningCN":"润滑，加润滑油于","tag":"低频","root":"","exampleEN":"You should lubricate the gears regularly to keep the machine running smoothly.","exampleCN":"你应该定期给齿轮加润滑油，使机器运转顺畅。","extra":"搭配：lubricating oil 润滑油。"},{"chapter":10,"key":"10:127","id":127,"word":"diamond","phonetic":"/ˈdaɪəmənd/","pos":"n.","meaningCN":"金刚石，钻石；菱形","tag":"高频","root":"","exampleEN":"The diamond in her engagement ring sparkled under the candlelight.","exampleCN":"她订婚戒指上的钻石在烛光下闪闪发光。","extra":""},{"chapter":10,"key":"10:128","id":128,"word":"crystal","phonetic":"/ˈkrɪstəl/","pos":"n.","meaningCN":"水晶；结晶，晶体","tag":"高频","root":"","exampleEN":"The necklace was decorated with tiny crystals that caught the sunlight.","exampleCN":"项链上装饰着小水晶，在阳光下闪闪发光。","extra":""},{"chapter":10,"key":"10:129","id":129,"word":"inferior","phonetic":"/ɪnˈfɪəriə/","pos":"adj.","meaningCN":"差的；下级的，低等的 n. 级别（或地位）低的人；次品","tag":"高频","root":"inferiority n. 低等，劣等","exampleEN":"Cheaper products are sometimes inferior in quality compared to more expensive ones.","exampleCN":"便宜的产品有时在质量上比昂贵的产品差。","extra":""},{"chapter":10,"key":"10:130","id":130,"word":"counterfeit","phonetic":"/ˈkaʊntəfɪt/","pos":"adj.","meaningCN":"假冒的 v. 伪造","tag":"低频","root":"counter（反）+ feit（做）→ 伪造","exampleEN":"The police seized thousands of counterfeit designer handbags in the raid.","exampleCN":"警方在突袭中查获了数千个假冒名牌手提包。","extra":""},{"chapter":10,"key":"10:131","id":131,"word":"fake","phonetic":"/feɪk/","pos":"adj.","meaningCN":"假冒的 n. 冒充者；假货","tag":"高频","root":"","exampleEN":"He was tricked into buying a fake painting that looked exactly like the original.","exampleCN":"他上当买了一幅与真迹一模一样的假画。","extra":""},{"chapter":10,"key":"10:132","id":132,"word":"fragile","phonetic":"/ˈfrædʒaɪl/","pos":"adj.","meaningCN":"易碎的；脆弱的","tag":"高频","root":"","exampleEN":"The box contained fragile glassware, so she handled it with extra care.","exampleCN":"盒子里装着易碎的玻璃器皿，所以她格外小心地搬运。","extra":""},{"chapter":10,"key":"10:133","id":133,"word":"miniature","phonetic":"/ˈmɪnɪtʃə/","pos":"adj.","meaningCN":"微型的，很小的 n. 缩微模型；微型画","tag":"低频","root":"","exampleEN":"He collected miniature cars and displayed them on a shelf.","exampleCN":"他收集微型汽车模型，并把它们陈列在架子上。","extra":""},{"chapter":10,"key":"10:134","id":134,"word":"available","phonetic":"/əˈveɪləbəl/","pos":"adj.","meaningCN":"可获得的","tag":"核心","root":"","exampleEN":"This model is available in several different colours and sizes.","exampleCN":"这款型号有多种颜色和尺寸可供选择。","extra":"搭配：be available to do sth. 可用于做某事。"},{"chapter":10,"key":"10:135","id":135,"word":"durable","phonetic":"/ˈdjʊərəbəl/","pos":"adj.","meaningCN":"耐用的，持久的","tag":"高频","root":"","exampleEN":"They chose durable materials for the school playground to withstand constant use.","exampleCN":"他们为学校操场选了耐用材料，以承受长期频繁使用。","extra":""}],"11":[{"chapter":11,"key":"11:1","id":1,"word":"fashion","phonetic":"/ˈfæʃən/","pos":"n.","meaningCN":"时尚；制作，制成","tag":"核心","root":"fashionable adj.流行的","exampleEN":"Fashion trends change so quickly that what is popular today may be outdated tomorrow.","exampleCN":"时尚潮流变化如此之快，今天流行的东西明天可能就过时了。","extra":"搭配：come into fashion 流行起来；out of fashion 过时的。"},{"chapter":11,"key":"11:2","id":2,"word":"style","phonetic":"/staɪl/","pos":"n.","meaningCN":"风格；样式；时尚","tag":"核心","root":"stylish adj.时髦的，有格调的","exampleEN":"Her unique style of dressing always makes her stand out in a crowd.","exampleCN":"她独特的穿衣风格总是让她在人群中脱颖而出。","extra":""},{"chapter":11,"key":"11:3","id":3,"word":"trend","phonetic":"/trend/","pos":"n.","meaningCN":"趋势，倾向","tag":"核心","root":"","exampleEN":"There is a growing trend towards sustainable and eco-friendly fashion.","exampleCN":"如今有一种向可持续和环保时尚发展的增长趋势。","extra":""},{"chapter":11,"key":"11:4","id":4,"word":"tendency","phonetic":"/ˈtendənsi/","pos":"n.","meaningCN":"趋势；倾向，偏好","tag":"高频","root":"tend v.趋向；易于","exampleEN":"She has a tendency to buy clothes in neutral colours like black and grey.","exampleCN":"她有种买黑色和灰色等中性色衣服的倾向。","extra":""},{"chapter":11,"key":"11:5","id":5,"word":"current","phonetic":"/ˈkʌrənt/","pos":"n.","meaningCN":"潮流，趋势 adj. 当前的","tag":"核心","root":"","exampleEN":"His designs always reflect the current trends in international fashion.","exampleCN":"他的设计总是反映国际时尚的当前潮流。","extra":"搭配：against the current 逆流而行的。"},{"chapter":11,"key":"11:6","id":6,"word":"popularity","phonetic":"/ˌpɒpjʊˈlærɪti/","pos":"n.","meaningCN":"流行","tag":"核心","root":"popular adj.流行的","exampleEN":"The popularity of vintage clothing has grown rapidly among young consumers.","exampleCN":"复古服装在年轻消费者中的受欢迎程度迅速增长。","extra":""},{"chapter":11,"key":"11:7","id":7,"word":"vogue","phonetic":"/vəʊɡ/","pos":"n.","meaningCN":"流行","tag":"低频","root":"","exampleEN":"Platform shoes were in vogue during the 1970s disco era.","exampleCN":"厚底鞋在20世纪70年代迪斯科时代风靡一时。","extra":"搭配：in vogue 流行的。"},{"chapter":11,"key":"11:8","id":8,"word":"prevail","phonetic":"/prɪˈveɪl/","pos":"v.","meaningCN":"盛行；获胜","tag":"高频","root":"prevalence n.流行，普遍存在；prevailing adj.盛行的","exampleEN":"Although many new trends appear, classic styles still prevail in formal wear.","exampleCN":"尽管许多新趋势出现，经典风格在正装中依然盛行。","extra":"搭配：prevail over/against 压倒，战胜。"},{"chapter":11,"key":"11:9","id":9,"word":"model","phonetic":"/ˈmɒdəl/","pos":"n.","meaningCN":"模型；模范；模特儿 v. 使模仿","tag":"核心","root":"","exampleEN":"She worked part-time as a fashion model while studying at university.","exampleCN":"她上大学期间兼职做时装模特。","extra":""},{"chapter":11,"key":"11:10","id":10,"word":"icon","phonetic":"/ˈaɪkɒn/","pos":"n.","meaningCN":"偶像；图标","tag":"高频","root":"","exampleEN":"The actress became a style icon after wearing that striking gown at the awards ceremony.","exampleCN":"这位女演员在颁奖典礼上穿了那件惊艳的礼服后，成了一名时尚偶像。","extra":""},{"chapter":11,"key":"11:11","id":11,"word":"idol","phonetic":"/ˈaɪdəl/","pos":"n.","meaningCN":"偶像，受到崇拜的人或物；神像","tag":"高频","root":"","exampleEN":"Many teenagers regard the singer as their idol and imitate his hairstyle.","exampleCN":"许多青少年把这位歌手当作偶像，并模仿他的发型。","extra":""},{"chapter":11,"key":"11:12","id":12,"word":"luxury","phonetic":"/ˈlʌkʃəri/","pos":"n.","meaningCN":"奢侈；奢侈品","tag":"高频","root":"luxurious adj.奢侈的，豪华的","exampleEN":"For many people, buying designer handbags is an unaffordable luxury.","exampleCN":"对许多人来说，购买名牌手提包是一种负担不起的奢侈。","extra":""},{"chapter":11,"key":"11:13","id":13,"word":"extravagant","phonetic":"/ɪkˈstrævəɡənt/","pos":"adj.","meaningCN":"奢侈的；过分的","tag":"低频","root":"","exampleEN":"Her extravagant spending on jewellery eventually led to serious financial problems.","exampleCN":"她在珠宝上的奢侈花费最终导致了严重的财务问题。","extra":""},{"chapter":11,"key":"11:14","id":14,"word":"jewellery","phonetic":"/ˈdʒuːəlri/","pos":"n.","meaningCN":"珠宝，首饰","tag":"高频","root":"","exampleEN":"The museum has a beautiful collection of ancient gold jewellery.","exampleCN":"这家博物馆收藏了一批精美的古代金首饰。","extra":"同 jewelry。"},{"chapter":11,"key":"11:15","id":15,"word":"jewel","phonetic":"/ˈdʒuːəl/","pos":"n.","meaningCN":"宝石","tag":"高频","root":"","exampleEN":"The crown was decorated with precious jewels that sparkled in the light.","exampleCN":"王冠上装饰着珍贵的宝石，在光线下闪闪发光。","extra":""},{"chapter":11,"key":"11:16","id":16,"word":"gem","phonetic":"/dʒem/","pos":"n.","meaningCN":"宝石；珍品","tag":"低频","root":"gene n.基因；germ n.细菌","exampleEN":"She wore a necklace set with rare gems from around the world.","exampleCN":"她戴了一条镶有来自世界各地的稀有宝石的项链。","extra":""},{"chapter":11,"key":"11:17","id":17,"word":"jade","phonetic":"/dʒeɪd/","pos":"n.","meaningCN":"玉石，翡翠","tag":"低频","root":"","exampleEN":"In Chinese culture, jade is believed to bring good luck and protect the wearer.","exampleCN":"在中国文化中，玉被认为能带来好运并保护佩戴者。","extra":""},{"chapter":11,"key":"11:18","id":18,"word":"adorn","phonetic":"/əˈdɔːn/","pos":"v.","meaningCN":"装饰，装扮","tag":"低频","root":"","exampleEN":"She loves to adorn her hair with fresh flowers in the springtime.","exampleCN":"春天的时候，她喜欢用鲜花装点自己的头发。","extra":""},{"chapter":11,"key":"11:19","id":19,"word":"ornament","phonetic":"/ˈɔːnəmənt/","pos":"n.","meaningCN":"装饰品 v. 装饰","tag":"低频","root":"","exampleEN":"The delicate silver ornaments on the bracelet were handcrafted by skilled artisans.","exampleCN":"手镯上精致的银饰是由技艺娴熟的工匠手工制作的。","extra":""},{"chapter":11,"key":"11:20","id":20,"word":"embellish","phonetic":"/ɪmˈbelɪʃ/","pos":"v.","meaningCN":"修饰","tag":"识记","root":"","exampleEN":"The designer embellished the evening dress with tiny pearls and sequins.","exampleCN":"设计师用小珍珠和亮片装饰了这件晚礼服。","extra":""},{"chapter":11,"key":"11:21","id":21,"word":"embroider","phonetic":"/ɪmˈbrɔɪdə/","pos":"v.","meaningCN":"对（故事等）加以渲染；在......上刺绣","tag":"低频","root":"","exampleEN":"Her grandmother taught her how to embroider flowers onto handkerchiefs.","exampleCN":"她的祖母教她如何在手帕上绣花。","extra":""},{"chapter":11,"key":"11:22","id":22,"word":"hairdressing","phonetic":"/ˈheəˌdresɪŋ/","pos":"n.","meaningCN":"美发，理发","tag":"识记","root":"","exampleEN":"She completed a professional course in hairdressing and opened her own salon.","exampleCN":"她修完了一门专业美发课程，并开了自己的发廊。","extra":""},{"chapter":11,"key":"11:23","id":23,"word":"pigment","phonetic":"/ˈpɪɡmənt/","pos":"n.","meaningCN":"色素；颜料","tag":"低频","root":"","exampleEN":"Natural pigments from plants were used to dye the fabric a deep blue colour.","exampleCN":"从植物中提取的天然色素被用来把布料染成深蓝色。","extra":""},{"chapter":11,"key":"11:24","id":24,"word":"dye","phonetic":"/daɪ/","pos":"n.","meaningCN":"染料；（染上的）颜色 v. 染","tag":"高频","root":"","exampleEN":"She decided to dye her old white dress a bright shade of pink.","exampleCN":"她决定把旧白裙子染成鲜艳的粉色。","extra":""},{"chapter":11,"key":"11:25","id":25,"word":"masquerade","phonetic":"/ˌmæskəˈreɪd/","pos":"n.","meaningCN":"化装舞会 v. 化装；假扮","tag":"识记","root":"","exampleEN":"Guests arrived at the masquerade in elaborate costumes and feathered masks.","exampleCN":"宾客们身着精美服装，戴着羽毛面具来到了化装舞会。","extra":""},{"chapter":11,"key":"11:26","id":26,"word":"veil","phonetic":"/veɪl/","pos":"n.","meaningCN":"面纱；遮蔽物","tag":"低频","root":"","exampleEN":"The bride lifted her veil and smiled warmly at the groom.","exampleCN":"新娘掀起面纱，对新郎温暖地微笑。","extra":""},{"chapter":11,"key":"11:27","id":27,"word":"costume","phonetic":"/ˈkɒstjuːm/","pos":"n.","meaningCN":"戏服；（某历史时期或某地的）服装","tag":"高频","root":"","exampleEN":"The actors wore traditional Chinese costumes for the historical drama.","exampleCN":"演员们为这部历史剧穿上了中国传统服装。","extra":"搭配：a costume ball 化装舞会；cosplay。"},{"chapter":11,"key":"11:28","id":28,"word":"fascinate","phonetic":"/ˈfæsɪneɪt/","pos":"v.","meaningCN":"迷住","tag":"高频","root":"fascinating adj.迷人的","exampleEN":"The intricate patterns on the silk scarf fascinated everyone at the exhibition.","exampleCN":"丝巾上精致的图案迷住了展览上的每一个人。","extra":"搭配：be fascinated with 迷上。"},{"chapter":11,"key":"11:29","id":29,"word":"decent","phonetic":"/ˈdiːsənt/","pos":"adj.","meaningCN":"得体的；尚好的","tag":"高频","root":"indecent adj.下流的","exampleEN":"For a job interview, it is best to wear a decent and professional outfit.","exampleCN":"求职面试时，最好穿着一套得体而职业的服装。","extra":""},{"chapter":11,"key":"11:30","id":30,"word":"exquisite","phonetic":"/ɪkˈskwɪzɪt/","pos":"adj.","meaningCN":"精致的；雅致的","tag":"低频","root":"quist指“追求”","exampleEN":"The bride wore an exquisite lace gown that took weeks to make.","exampleCN":"新娘穿了一件精致的花边礼服，这件礼服花了几周时间制作。","extra":""},{"chapter":11,"key":"11:31","id":31,"word":"grace","phonetic":"/ɡreɪs/","pos":"n.","meaningCN":"优美，优雅","tag":"高频","root":"graceful adj.优雅的","exampleEN":"The ballerina danced with such grace that the audience was completely captivated.","exampleCN":"芭蕾舞女演员舞姿优美，让观众完全着了迷。","extra":""},{"chapter":11,"key":"11:32","id":32,"word":"elegance","phonetic":"/ˈelɪɡəns/","pos":"n.","meaningCN":"文雅，典雅","tag":"高频","root":"elegant adj.优雅的","exampleEN":"The simplicity and elegance of her black dress impressed all the guests.","exampleCN":"她那条黑裙的简洁与典雅给所有宾客留下了深刻印象。","extra":""},{"chapter":11,"key":"11:33","id":33,"word":"perfect","phonetic":"/ˈpɜːfɪkt/","pos":"adj.","meaningCN":"完美的","tag":"核心","root":"perfection n.完美","exampleEN":"She spent hours looking for the perfect pair of shoes to match her new suit.","exampleCN":"她花了数小时寻找配她新套装的那双完美鞋子。","extra":""},{"chapter":11,"key":"11:34","id":34,"word":"appearance","phonetic":"/əˈpɪərəns/","pos":"n.","meaningCN":"外貌；出现","tag":"核心","root":"appear v.出现","exampleEN":"Although we should not judge by appearance, first impressions do matter in fashion.","exampleCN":"虽然不应以貌取人，但在时尚界第一印象确实很重要。","extra":""},{"chapter":11,"key":"11:35","id":35,"word":"cosmetics","phonetic":"/kɒzˈmetɪks/","pos":"n.","meaningCN":"化妆品","tag":"高频","root":"cosm(o)来自希腊语kosmos，意为“装饰”或“世界”","exampleEN":"The store sells a wide range of cosmetics, from lipstick to foundation.","exampleCN":"这家商店出售从口红到粉底的各式化妆品。","extra":""},{"chapter":11,"key":"11:36","id":36,"word":"make-up","phonetic":"/ˈmeɪkʌp/","pos":"n.","meaningCN":"化妆品；组成成分；性格","tag":"核心","root":"","exampleEN":"She wears very little make-up, preferring a more natural look.","exampleCN":"她几乎不化妆，更喜欢更自然的样子。","extra":""},{"chapter":11,"key":"11:37","id":37,"word":"handsome","phonetic":"/ˈhænsəm/","pos":"adj.","meaningCN":"数量大的；英俊的","tag":"核心","root":"","exampleEN":"The actor looked exceptionally handsome in his tailored suit at the premiere.","exampleCN":"这位演员在首映式上穿着定制西装，显得格外英俊。","extra":""},{"chapter":11,"key":"11:38","id":38,"word":"charming","phonetic":"/ˈtʃɑːmɪŋ/","pos":"adj.","meaningCN":"迷人的","tag":"高频","root":"","exampleEN":"She has a charming smile that lights up any room she enters.","exampleCN":"她有着迷人的微笑，走进任何房间都能让房间一亮。","extra":"搭配：Prince Charming 白马王子。"},{"chapter":11,"key":"11:39","id":39,"word":"pretty","phonetic":"/ˈprɪti/","pos":"adj.","meaningCN":"漂亮的 adv. 相当地","tag":"核心","root":"","exampleEN":"She wore a pretty floral dress to the garden party.","exampleCN":"她穿了一条漂亮的碎花连衣裙去参加花园聚会。","extra":""},{"chapter":11,"key":"11:40","id":40,"word":"beautiful","phonetic":"/ˈbjuːtɪfəl/","pos":"adj.","meaningCN":"美丽的","tag":"核心","root":"","exampleEN":"The sunset created a beautiful backdrop for the outdoor fashion show.","exampleCN":"落日为户外时装秀提供了一个美丽的背景。","extra":""},{"chapter":11,"key":"11:41","id":41,"word":"ugly","phonetic":"/ˈʌɡli/","pos":"adj.","meaningCN":"丑陋的","tag":"核心","root":"","exampleEN":"She thought the oversized jacket looked ugly, but it became a surprising trend.","exampleCN":"她认为那件超大号夹克很难看，但它却出人意料地成了一种潮流。","extra":""},{"chapter":11,"key":"11:42","id":42,"word":"dress","phonetic":"/dres/","pos":"n.","meaningCN":"衣服；连衣裙","tag":"核心","root":"","exampleEN":"She bought a long silk dress for the formal dinner party.","exampleCN":"她为正式的晚宴买了一条丝绸长裙。","extra":""},{"chapter":11,"key":"11:43","id":43,"word":"clothe","phonetic":"/kləʊð/","pos":"v.","meaningCN":"给......穿衣；为......提供衣服","tag":"低频","root":"clothes n.衣服；clothing n.衣服","exampleEN":"Parents work hard to feed and clothe their children and give them a good education.","exampleCN":"父母努力工作，为孩子们提供衣食和良好的教育。","extra":""},{"chapter":11,"key":"11:44","id":44,"word":"uniform","phonetic":"/ˈjuːnɪfɔːm/","pos":"n.","meaningCN":"制服 adj. 一致的","tag":"核心","root":"uni（单一）+ form（形状）","exampleEN":"The students wear a blue and white uniform to school every day.","exampleCN":"学生们每天穿着蓝白相间的校服上学。","extra":""},{"chapter":11,"key":"11:45","id":45,"word":"purse","phonetic":"/pɜːs/","pos":"n.","meaningCN":"[尤英]钱包；[美]小手提包","tag":"核心","root":"","exampleEN":"She took a lipstick and a small mirror out of her purse.","exampleCN":"她从手提包里拿出一支口红和一面小镜子。","extra":""},{"chapter":11,"key":"11:46","id":46,"word":"wallet","phonetic":"/ˈwɒlɪt/","pos":"n.","meaningCN":"钱包，皮夹子","tag":"核心","root":"","exampleEN":"He keeps his credit cards and cash in a brown leather wallet.","exampleCN":"他把信用卡和现金放在一个棕色皮夹子里。","extra":""},{"chapter":11,"key":"11:47","id":47,"word":"vest","phonetic":"/vest/","pos":"n.","meaningCN":"[英]汗衫；[美]西装背心","tag":"低频","root":"","exampleEN":"He wore a grey vest under his jacket for extra warmth.","exampleCN":"他在夹克里面穿了一件灰色汗衫以保暖。","extra":""},{"chapter":11,"key":"11:48","id":48,"word":"wrap","phonetic":"/ræp/","pos":"n.","meaningCN":"披肩","tag":"低频","root":"","exampleEN":"She draped a soft wool wrap around her shoulders on the cool evening.","exampleCN":"在凉爽的夜晚，她把一条柔软的羊毛披肩披在肩上。","extra":""},{"chapter":11,"key":"11:49","id":49,"word":"cloak","phonetic":"/kləʊk/","pos":"n.","meaningCN":"斗篷；覆盖物","tag":"低频","root":"","exampleEN":"The mysterious figure wore a long black cloak that hid his face.","exampleCN":"那个神秘人物穿着一件长长的黑斗篷，遮住了脸。","extra":""},{"chapter":11,"key":"11:50","id":50,"word":"collar","phonetic":"/ˈkɒlə/","pos":"n.","meaningCN":"衣领；项圈","tag":"高频","root":"","exampleEN":"He turned up his coat collar to protect his neck from the cold wind.","exampleCN":"他把衣领竖起来，保护脖子不受寒风侵袭。","extra":""},{"chapter":11,"key":"11:51","id":51,"word":"sleeve","phonetic":"/sliːv/","pos":"n.","meaningCN":"袖子","tag":"高频","root":"","exampleEN":"She rolled up her sleeves and began to wash the dishes.","exampleCN":"她卷起袖子，开始洗碗。","extra":""},{"chapter":11,"key":"11:52","id":52,"word":"sock","phonetic":"/sɒk/","pos":"n.","meaningCN":"短袜","tag":"核心","root":"","exampleEN":"He found a hole in his sock and quickly changed into a new pair.","exampleCN":"他发现袜子上有个洞，赶紧换了一双新的。","extra":""},{"chapter":11,"key":"11:53","id":53,"word":"stocking","phonetic":"/ˈstɒkɪŋ/","pos":"n.","meaningCN":"（女式）长筒袜","tag":"低频","root":"","exampleEN":"She wore a pair of black stockings to complete her elegant outfit.","exampleCN":"她穿了一双黑色长筒袜来搭配她的优雅装扮。","extra":""},{"chapter":11,"key":"11:54","id":54,"word":"slipper","phonetic":"/ˈslɪpə/","pos":"n.","meaningCN":"拖鞋","tag":"核心","root":"","exampleEN":"After a long day, she put on her cosy slippers and relaxed on the sofa.","exampleCN":"漫长的一天过后，她穿上舒适的拖鞋，在沙发上放松。","extra":""},{"chapter":11,"key":"11:55","id":55,"word":"boot","phonetic":"/buːt/","pos":"n.","meaningCN":"靴子","tag":"核心","root":"","exampleEN":"She wore a pair of brown leather boots that reached just below her knees.","exampleCN":"她穿了一双刚到膝盖下方的棕色皮靴。","extra":""},{"chapter":11,"key":"11:56","id":56,"word":"lace","phonetic":"/leɪs/","pos":"n.","meaningCN":"鞋带；花边","tag":"高频","root":"","exampleEN":"The wedding dress was trimmed with delicate white lace.","exampleCN":"婚纱上镶着精致的白色花边。","extra":""},{"chapter":11,"key":"11:57","id":57,"word":"tailor","phonetic":"/ˈteɪlə/","pos":"n.","meaningCN":"裁缝 v. 专门制作","tag":"高频","root":"","exampleEN":"The tailor measured his chest and arms carefully to make the suit fit perfectly.","exampleCN":"裁缝仔细量了他的胸围和臂长，以使西装完美合身。","extra":""},{"chapter":11,"key":"11:58","id":58,"word":"sew","phonetic":"/səʊ/","pos":"v.","meaningCN":"缝制，缝补","tag":"高频","root":"","exampleEN":"She learned to sew buttons and mend small tears in her clothing.","exampleCN":"她学会了缝扣子和修补衣服上的小裂口。","extra":""},{"chapter":11,"key":"11:59","id":59,"word":"spin","phonetic":"/spɪn/","pos":"v.","meaningCN":"纺；（使）旋转 n. 高速旋转；（乘车）兜风","tag":"低频","root":"","exampleEN":"In the past, women would spin wool into thread to make clothes for the family.","exampleCN":"过去，妇女把羊毛纺成线，为家人做衣服。","extra":""},{"chapter":11,"key":"11:60","id":60,"word":"stitch","phonetic":"/stɪtʃ/","pos":"n.","meaningCN":"针脚 v. 缝","tag":"低频","root":"","exampleEN":"She carefully made small stitches to repair the tear in her favourite skirt.","exampleCN":"她小心翼翼地用细密的针脚修补她最喜欢的那条裙子上的裂口。","extra":""},{"chapter":11,"key":"11:61","id":61,"word":"needle","phonetic":"/ˈniːdl/","pos":"n.","meaningCN":"针","tag":"高频","root":"","exampleEN":"Threading a needle requires steady hands and good eyesight.","exampleCN":"穿针需要手稳和好眼力。","extra":"搭配：thread a needle 穿针。"},{"chapter":11,"key":"11:62","id":62,"word":"pin","phonetic":"/pɪn/","pos":"n.","meaningCN":"别针，大头针 v. 别住，钉住","tag":"高频","root":"","exampleEN":"She used a decorative pin to fasten the scarf around her neck.","exampleCN":"她用一枚装饰别针把围巾别在脖子上。","extra":""},{"chapter":11,"key":"11:63","id":63,"word":"string","phonetic":"/strɪŋ/","pos":"n.","meaningCN":"线；一串","tag":"核心","root":"","exampleEN":"She tied the package with a piece of red string and added a small card.","exampleCN":"她用一根红线系好包裹，并附了一张小卡片。","extra":""},{"chapter":11,"key":"11:64","id":64,"word":"thread","phonetic":"/θred/","pos":"n.","meaningCN":"线；螺纹","tag":"高频","root":"","exampleEN":"The tailor matched the thread exactly to the colour of the fabric.","exampleCN":"裁缝把线和布料的颜色配得完全一致。","extra":""},{"chapter":11,"key":"11:65","id":65,"word":"strap","phonetic":"/stræp/","pos":"n.","meaningCN":"带子 v. 用带子系（或捆、扎）","tag":"高频","root":"","exampleEN":"She adjusted the strap of her handbag so it hung comfortably over her shoulder.","exampleCN":"她调了调手提包的带子，让它舒适地挂在肩上。","extra":""},{"chapter":11,"key":"11:66","id":66,"word":"stripe","phonetic":"/straɪp/","pos":"n.","meaningCN":"条纹","tag":"高频","root":"","exampleEN":"He wore a navy blue suit with fine white stripes on his wedding day.","exampleCN":"他在婚礼上穿了一套带有白色细条纹的海军蓝西装。","extra":""},{"chapter":11,"key":"11:67","id":67,"word":"ribbon","phonetic":"/ˈrɪbən/","pos":"n.","meaningCN":"缎带，丝带","tag":"低频","root":"","exampleEN":"She tied a pink ribbon around the gift box to make it look more festive.","exampleCN":"她在礼盒上系了一条粉色丝带，使它看起来更有节日气氛。","extra":""},{"chapter":11,"key":"11:68","id":68,"word":"belt","phonetic":"/belt/","pos":"n.","meaningCN":"腰带，皮带；地带，地区","tag":"核心","root":"","exampleEN":"He tightened his belt a notch after losing weight.","exampleCN":"他减肥后把腰带收紧了一个扣眼。","extra":"搭配：fasten/loosen a belt。"},{"chapter":11,"key":"11:69","id":69,"word":"chain","phonetic":"/tʃeɪn/","pos":"n.","meaningCN":"链子，链条","tag":"高频","root":"","exampleEN":"She wore a delicate gold chain with a small heart pendant.","exampleCN":"她戴了一条精致的金链子，配有一个心形小吊坠。","extra":""},{"chapter":11,"key":"11:70","id":70,"word":"bracelet","phonetic":"/ˈbreɪslɪt/","pos":"n.","meaningCN":"手镯","tag":"高频","root":"","exampleEN":"Her bracelet is made of silver and decorated with tiny turquoise stones.","exampleCN":"她的手镯是银制的，装饰着小颗绿松石。","extra":""},{"chapter":11,"key":"11:71","id":71,"word":"necklace","phonetic":"/ˈneklɪs/","pos":"n.","meaningCN":"项链","tag":"高频","root":"","exampleEN":"The pearl necklace she wore added a touch of classic elegance to her look.","exampleCN":"她戴的珍珠项链为她的装扮增添了一丝经典优雅。","extra":""},{"chapter":11,"key":"11:72","id":72,"word":"bead","phonetic":"/biːd/","pos":"n.","meaningCN":"珠子；（液体的）小滴 v. 形成珠状","tag":"低频","root":"词源：来自古英语“祈祷”，后演变为“念珠”","exampleEN":"She threaded colourful beads onto a string to make a handmade bracelet.","exampleCN":"她把彩色珠子穿到绳子上，做成一串手工手链。","extra":""},{"chapter":11,"key":"11:73","id":73,"word":"textile","phonetic":"/ˈtekstaɪl/","pos":"n.","meaningCN":"纺织品 adj. 纺织的","tag":"高频","root":"","exampleEN":"The region is famous for producing high-quality textiles such as silk and wool.","exampleCN":"该地区以生产丝绸和羊毛等优质纺织品而闻名。","extra":""},{"chapter":11,"key":"11:74","id":74,"word":"velvet","phonetic":"/ˈvelvɪt/","pos":"n.","meaningCN":"丝绒，天鹅绒","tag":"低频","root":"","exampleEN":"She chose a dark red velvet cushion to match the curtains.","exampleCN":"她选了一个深红色的天鹅绒靠垫来搭配窗帘。","extra":""},{"chapter":11,"key":"11:75","id":75,"word":"wool","phonetic":"/wʊl/","pos":"n.","meaningCN":"（羊等的）毛；毛线","tag":"高频","root":"woollen adj.羊毛的","exampleEN":"This sweater is made of pure wool and is very warm in winter.","exampleCN":"这件毛衣是纯羊毛制成的，冬天穿起来非常暖和。","extra":""},{"chapter":11,"key":"11:76","id":76,"word":"patch","phonetic":"/pætʃ/","pos":"n.","meaningCN":"补丁；（与周围不同的）小片 v. 补缀","tag":"低频","root":"patchwork n.拼布工艺；混杂物","exampleEN":"She sewed a decorative patch onto her jeans to cover the worn-out area.","exampleCN":"她在牛仔裤上缝了一个装饰补丁来遮盖磨损的地方。","extra":""},{"chapter":11,"key":"11:77","id":77,"word":"rag","phonetic":"/ræɡ/","pos":"n.","meaningCN":"破布","tag":"低频","root":"ragged adj.破旧的","exampleEN":"He wiped his hands on an old rag after fixing the bicycle chain.","exampleCN":"他修完自行车链后，在一块旧破布上擦了擦手。","extra":""},{"chapter":11,"key":"11:78","id":78,"word":"shabby","phonetic":"/ˈʃæbi/","pos":"adj.","meaningCN":"破旧的；衣衫褴褛的","tag":"低频","root":"","exampleEN":"Despite his shabby coat, he walked into the job interview with great confidence.","exampleCN":"尽管外套破旧，他仍满怀信心地走进了求职面试。","extra":""},{"chapter":11,"key":"11:79","id":79,"word":"tight","phonetic":"/taɪt/","pos":"adj.","meaningCN":"紧的","tag":"核心","root":"tighten v.（使）变紧","exampleEN":"The jeans were too tight around the waist, so she exchanged them for a larger size.","exampleCN":"这条牛仔裤腰部太紧，所以她换了条大一号的。","extra":""},{"chapter":11,"key":"11:80","id":80,"word":"colour","phonetic":"/ˈkʌlə/","pos":"n.","meaningCN":"颜色；颜料","tag":"核心","root":"colourful adj.富于色彩的","exampleEN":"The designer used bright colours to create a joyful and youthful collection.","exampleCN":"设计师用明亮的色彩创造了一个充满欢乐和年轻气息的系列。","extra":"美式拼写 color。"},{"chapter":11,"key":"11:81","id":81,"word":"white","phonetic":"/waɪt/","pos":"adj.","meaningCN":"白的 n. 白色","tag":"核心","root":"whitewash v.粉刷","exampleEN":"She wore a simple white shirt with blue jeans for a casual look.","exampleCN":"她穿了一件简单的白衬衫搭配蓝色牛仔裤，打造休闲风。","extra":""},{"chapter":11,"key":"11:82","id":82,"word":"yellow","phonetic":"/ˈjeləʊ/","pos":"adj.","meaningCN":"黄的 n. 黄色","tag":"核心","root":"","exampleEN":"The bright yellow scarf added a pop of colour to her dark winter coat.","exampleCN":"亮黄色的围巾给她深色的冬装增添了一抹亮色。","extra":""},{"chapter":11,"key":"11:83","id":83,"word":"brown","phonetic":"/braʊn/","pos":"adj.","meaningCN":"褐色的 n. 褐色","tag":"核心","root":"","exampleEN":"He prefers brown shoes over black ones for a more casual style.","exampleCN":"他更喜欢棕色鞋子而不是黑色，以打造更休闲的风格。","extra":""},{"chapter":11,"key":"11:84","id":84,"word":"grey","phonetic":"/ɡreɪ/","pos":"adj.","meaningCN":"灰色的 n. 灰色","tag":"核心","root":"","exampleEN":"Grey suits are a popular choice for business attire because they look professional.","exampleCN":"灰色西装是商务装的热门选择，因为看起来专业。","extra":"美式拼写 gray。"},{"chapter":11,"key":"11:85","id":85,"word":"pink","phonetic":"/pɪŋk/","pos":"adj.","meaningCN":"粉红色的 n. 粉红色","tag":"核心","root":"","exampleEN":"The baby girl wore a cute pink dress with small white flowers.","exampleCN":"小女婴穿着一件带有白色小花的可爱粉红连衣裙。","extra":"搭配：in the pink 容光焕发。"},{"chapter":11,"key":"11:86","id":86,"word":"purple","phonetic":"/ˈpɜːpəl/","pos":"adj.","meaningCN":"紫的 n. 紫色","tag":"核心","root":"","exampleEN":"In ancient times, purple dye was precious and only worn by royalty.","exampleCN":"在古代，紫色染料十分珍贵，只有皇室才能穿着。","extra":""},{"chapter":11,"key":"11:87","id":87,"word":"tan","phonetic":"/tæn/","pos":"adj.","meaningCN":"棕黄色的 n. 棕黄色；晒成的棕褐色","tag":"低频","root":"","exampleEN":"After the summer holiday, she returned with a healthy tan.","exampleCN":"暑假过后，她带着健康的棕褐色皮肤回来了。","extra":""},{"chapter":11,"key":"11:88","id":88,"word":"fade","phonetic":"/feɪd/","pos":"v.","meaningCN":"逐渐消失；（使）褪色","tag":"高频","root":"","exampleEN":"If you wash dark clothes in hot water, the colour may fade quickly.","exampleCN":"如果用热水洗深色衣服，颜色可能会很快褪去。","extra":"搭配：fade away 衰弱；病重死亡。"},{"chapter":11,"key":"11:89","id":89,"word":"stain","phonetic":"/steɪn/","pos":"v.","meaningCN":"染污 n. 污渍","tag":"高频","root":"stainless adj.无瑕疵的；不锈钢制的","exampleEN":"Red wine spilled on the tablecloth and left a deep red stain.","exampleCN":"红酒洒在桌布上，留下了一块深红色的污渍。","extra":""},{"chapter":11,"key":"11:90","id":90,"word":"blot","phonetic":"/blɒt/","pos":"n.","meaningCN":"污点","tag":"识记","root":"","exampleEN":"An ink blot on the white shirt was impossible to remove completely.","exampleCN":"白衬衫上的墨水污点几乎不可能完全清除。","extra":""},{"chapter":11,"key":"11:91","id":91,"word":"figure","phonetic":"/ˈfɪɡə/","pos":"n.","meaningCN":"身材；身影；重要人物；数字 v. 认为","tag":"核心","root":"","exampleEN":"Regular exercise helps her maintain a slim and healthy figure.","exampleCN":"经常锻炼帮助她保持苗条健康的身材。","extra":"搭配：figure out 理解，弄明白。描述身材：slender/slim figure 苗条；hourglass figure 沙漏身材。"}],"12":[{"chapter":12,"key":"12:1","id":1,"word":"food","phonetic":"","pos":"n.","meaningCN":"食物","tag":"核心","root":"","exampleEN":"A balanced diet includes food from all the major groups.","exampleCN":"均衡的饮食包括所有主要类别的食物。","extra":"foodie n. 美食家，吃货"},{"chapter":12,"key":"12:2","id":2,"word":"diet","phonetic":"/daiot/","pos":"n.","meaningCN":"日常饮食；（医生指定的）特别饮食；节食","tag":"核心","root":"","exampleEN":"She decided to go on a diet to improve her overall health.","exampleCN":"她决定进行节食以改善整体健康状况。","extra":"dietary adj. 饮食的；搭配：on a diet 进行节食"},{"chapter":12,"key":"12:3","id":3,"word":"appetite","phonetic":"/'eptat/","pos":"n.","meaningCN":"食欲；强烈欲望","tag":"核心","root":"pet = 寻求 → appetite 食欲, appetiser 开胃小吃, compete 竞争","exampleEN":"The long hike gave everyone a healthy appetite for dinner.","exampleCN":"长途徒步让大家晚餐时胃口大开。","extra":"搭配：have a bad appetite 没有食欲"},{"chapter":12,"key":"12:4","id":4,"word":"treat","phonetic":"/tri:t/","pos":"v.","meaningCN":"请（客）；对待；治疗 n. 款待","tag":"核心","root":"","exampleEN":"He offered to treat his friends to a meal at a new restaurant.","exampleCN":"他主动请朋友们去一家新餐馆吃饭。","extra":"treatment n. 对待；处理；治疗"},{"chapter":12,"key":"12:5","id":5,"word":"cater","phonetic":"/ket/","pos":"v.","meaningCN":"为......提供饮食；满足......的需要","tag":"高频","root":"","exampleEN":"The hotel caters for weddings and corporate events throughout the year.","exampleCN":"这家酒店全年为婚礼和公司活动提供餐饮服务。","extra":"搭配：cater to/for 满足……的需要，迎合"},{"chapter":12,"key":"12:6","id":6,"word":"provision","phonetic":"/pra'visn/","pos":"n.","meaningCN":"供应；预备；[~s] 食品供应","tag":"高频","root":"","exampleEN":"The government is responsible for the provision of clean drinking water.","exampleCN":"政府负责提供清洁的饮用水。","extra":""},{"chapter":12,"key":"12:7","id":7,"word":"edible","phonetic":"/edbl/","pos":"adj.","meaningCN":"可以吃的","tag":"高频","root":"","exampleEN":"Not all wild mushrooms are edible; some can be poisonous.","exampleCN":"并非所有野生蘑菇都可以食用，有些可能有毒。","extra":"inedible adj. 不宜食用的；后缀 -ible 表示“能……的”"},{"chapter":12,"key":"12:8","id":8,"word":"recipe","phonetic":"/resipi/","pos":"n.","meaningCN":"食谱；秘诀","tag":"核心","root":"","exampleEN":"She followed the recipe carefully to bake her first cake.","exampleCN":"她仔细按照食谱烘烤了她的第一个蛋糕。","extra":""},{"chapter":12,"key":"12:9","id":9,"word":"restaurant","phonetic":"/restornt/","pos":"n.","meaningCN":"餐馆","tag":"核心","root":"","exampleEN":"They chose a small Italian restaurant for their anniversary dinner.","exampleCN":"他们选了一家小小的意大利餐馆庆祝周年晚餐。","extra":""},{"chapter":12,"key":"12:10","id":10,"word":"refectory","phonetic":"/ri'fektari/","pos":"n.","meaningCN":"（学校或其他机构的）食堂，餐厅","tag":"低频","root":"","exampleEN":"Students gathered in the refectory for a hot lunch during the break.","exampleCN":"休息时学生们聚集在食堂吃热腾腾的午餐。","extra":""},{"chapter":12,"key":"12:11","id":11,"word":"bar","phonetic":"/ba:/","pos":"n.","meaningCN":"酒吧；吧台","tag":"核心","root":"","exampleEN":"They sat at the bar and ordered a couple of cocktails.","exampleCN":"他们坐在吧台边，点了两杯鸡尾酒。","extra":""},{"chapter":12,"key":"12:12","id":12,"word":"cafeteria","phonetic":"/kefs'torai/","pos":"n.","meaningCN":"自助餐厅","tag":"核心","root":"","exampleEN":"The office cafeteria offers a good selection of salads and hot meals.","exampleCN":"办公室的自助餐厅提供多种沙拉和热餐供选择。","extra":""},{"chapter":12,"key":"12:13","id":13,"word":"buffet","phonetic":"/bufet/","pos":"n.","meaningCN":"自助餐","tag":"高频","root":"","exampleEN":"The hotel breakfast buffet includes both Asian and Western options.","exampleCN":"酒店的自助早餐包括亚洲和西式两种选择。","extra":""},{"chapter":12,"key":"12:14","id":14,"word":"barbecue","phonetic":"/ba:bi:ku:/","pos":"n.","meaningCN":"烧烤野餐；烤架 v. 烧烤","tag":"高频","root":"","exampleEN":"We invited a few friends over for a barbecue in the backyard.","exampleCN":"我们邀请了几个朋友来后院烧烤。","extra":"也可写作 barbeque 或 BBQ"},{"chapter":12,"key":"12:15","id":15,"word":"supper","phonetic":"/'sapə/","pos":"n.","meaningCN":"晚餐","tag":"核心","root":"","exampleEN":"After the long walk, a light supper of soup and bread was perfect.","exampleCN":"长途步行后，喝点汤吃点面包的简单晚餐简直完美。","extra":"breakfast 早餐；lunch 午餐；brunch 早午餐；dinner 正餐"},{"chapter":12,"key":"12:16","id":16,"word":"banquet","phonetic":"/baenkwi/","pos":"n.","meaningCN":"宴会","tag":"低频","root":"","exampleEN":"The wedding banquet featured a ten-course meal for over 300 guests.","exampleCN":"婚宴为300多位宾客提供了十道菜的宴席。","extra":""},{"chapter":12,"key":"12:17","id":17,"word":"refreshment","phonetic":"/ri'frejmant/","pos":"n.","meaningCN":"[~s] 茶点，点心","tag":"高频","root":"","exampleEN":"Light refreshments will be served during the meeting at three o'clock.","exampleCN":"会议期间的三点钟将提供简单的茶点。","extra":""},{"chapter":12,"key":"12:18","id":18,"word":"snack","phonetic":"/snak/","pos":"n.","meaningCN":"快餐，小吃，零食","tag":"核心","root":"","exampleEN":"I always keep some healthy snacks in my bag for emergencies.","exampleCN":"我总是在包里放一些健康零食以备不时之需。","extra":""},{"chapter":12,"key":"12:19","id":19,"word":"appetiser","phonetic":"/'æpɪtɪzə/","pos":"n.","meaningCN":"开胃饮料，开胃小吃","tag":"高频","root":"pet = 寻求 → 刺激食欲的食物","exampleEN":"We ordered a selection of appetisers to share before the main course.","exampleCN":"我们点了几样开胃小吃在主菜前一起分享。","extra":"也作 appetizer"},{"chapter":12,"key":"12:20","id":20,"word":"cuisine","phonetic":"/kwi'zi:n/","pos":"n.","meaningCN":"菜肴；烹饪","tag":"核心","root":"","exampleEN":"French cuisine is famous for its rich sauces and elegant presentation.","exampleCN":"法国菜以浓郁的酱汁和精致的摆盘而闻名。","extra":""},{"chapter":12,"key":"12:21","id":21,"word":"menu","phonetic":"/menju/","pos":"n.","meaningCN":"菜单","tag":"核心","root":"","exampleEN":"The waiter handed us the menu and recommended the local specialities.","exampleCN":"服务员递给我们菜单，并推荐了当地特色菜。","extra":""},{"chapter":12,"key":"12:22","id":22,"word":"order","phonetic":"/o:də/","pos":"n.","meaningCN":"订单；点的餐 v. 点（酒菜等）","tag":"核心","root":"","exampleEN":"He looked at the menu for a long time before placing his order.","exampleCN":"他看着菜单看了很久才下单点菜。","extra":""},{"chapter":12,"key":"12:23","id":23,"word":"takeaway","phonetic":"/'teikəwe/","pos":"n.","meaningCN":"[英] 外卖餐馆，外卖食物","tag":"高频","root":"","exampleEN":"I don't feel like cooking tonight; let's get a takeaway instead.","exampleCN":"今晚我不想做饭，我们叫份外卖吧。","extra":"Eat-in or takeaway? 店内吃或带走？"},{"chapter":12,"key":"12:24","id":24,"word":"chef","phonetic":"/fe/","pos":"n.","meaningCN":"厨师","tag":"核心","root":"","exampleEN":"The chef prepared a special dish for the guests celebrating their anniversary.","exampleCN":"厨师为庆祝结婚纪念日的客人准备了一道特别的菜肴。","extra":"chief n. 首领，头目 adj. 主要的"},{"chapter":12,"key":"12:25","id":25,"word":"gourmet","phonetic":"/'goumei/","pos":"n.","meaningCN":"美食家 adj. 美味佳肴的","tag":"低频","root":"","exampleEN":"As a true gourmet, he travels the world searching for new culinary experiences.","exampleCN":"作为一名真正的美食家，他周游世界寻找新的美食体验。","extra":"搭配：gourmet food 美味佳肴"},{"chapter":12,"key":"12:26","id":26,"word":"vegetarian","phonetic":"/vedʒ'tearian/","pos":"n.","meaningCN":"素食者 adj. 素食的；无肉的","tag":"核心","root":"vegetable + arian → 素食主义者","exampleEN":"Many restaurants now offer a wide range of vegetarian dishes on the menu.","exampleCN":"现在许多餐馆的菜单上都提供多种素食菜肴。","extra":""},{"chapter":12,"key":"12:27","id":27,"word":"cutlery","phonetic":"/kʌtɪləri/","pos":"n.","meaningCN":"餐具；刀具","tag":"高频","root":"","exampleEN":"Please set the table with plates, glasses, and cutlery for four people.","exampleCN":"请在桌上摆上四人份的盘子、杯子和餐具。","extra":""},{"chapter":12,"key":"12:28","id":28,"word":"silver","phonetic":"/'silva/","pos":"n.","meaningCN":"银；银器 adj. 银的；银色的","tag":"核心","root":"","exampleEN":"She wore a beautiful silver bracelet that matched her necklace.","exampleCN":"她戴着一个漂亮的银手镯，和项链很相配。","extra":""},{"chapter":12,"key":"12:29","id":29,"word":"ceramic","phonetic":"/sə'kraemik/","pos":"adj.","meaningCN":"陶瓷的 n. 陶瓷制品","tag":"低频","root":"","exampleEN":"The museum has a special exhibition of ancient Chinese ceramic art.","exampleCN":"博物馆有一个中国古代陶瓷艺术的特展。","extra":""},{"chapter":12,"key":"12:30","id":30,"word":"porcelain","phonetic":"/'pə:slən/","pos":"n.","meaningCN":"瓷器；瓷","tag":"低频","root":"","exampleEN":"This delicate porcelain cup was made by hand over a hundred years ago.","exampleCN":"这只精致的瓷杯是一百多年前手工制作的。","extra":""},{"chapter":12,"key":"12:31","id":31,"word":"bowl","phonetic":"/bəul/","pos":"n.","meaningCN":"碗","tag":"核心","root":"","exampleEN":"He ate a bowl of steaming noodles for a quick and satisfying lunch.","exampleCN":"他吃了一碗热气腾腾的面条，作为简单又满足的午餐。","extra":"搭配：a fish bowl 鱼缸"},{"chapter":12,"key":"12:32","id":32,"word":"dish","phonetic":"/dɪʃ/","pos":"n.","meaningCN":"碟；菜肴","tag":"核心","root":"","exampleEN":"The chef's signature dish is a grilled fish with lemon and herbs.","exampleCN":"厨师的招牌菜是一道配柠檬和香草的烤鱼。","extra":""},{"chapter":12,"key":"12:33","id":33,"word":"saucer","phonetic":"/'sə:sə/","pos":"n.","meaningCN":"茶托，茶碟","tag":"高频","root":"","exampleEN":"Please place the cup carefully on the saucer to avoid spilling.","exampleCN":"请小心地把杯子放在茶托上，以免弄洒。","extra":""},{"chapter":12,"key":"12:34","id":34,"word":"tray","phonetic":"/treɪ/","pos":"n.","meaningCN":"盘，托盘","tag":"核心","root":"","exampleEN":"The flight attendant came down the aisle with a tray of drinks.","exampleCN":"乘务员端着一托盘的饮料沿着通道走了过来。","extra":""},{"chapter":12,"key":"12:35","id":35,"word":"fork","phonetic":"/fɔk/","pos":"n.","meaningCN":"餐叉；分岔处","tag":"核心","root":"","exampleEN":"In Western dining, the fork is typically held in the left hand.","exampleCN":"在西餐中，餐叉通常用左手拿。","extra":""},{"chapter":12,"key":"12:36","id":36,"word":"knife","phonetic":"/naɪf/","pos":"n.","meaningCN":"刀","tag":"核心","root":"","exampleEN":"She used a sharp knife to cut the vegetables into thin slices.","exampleCN":"她用一把锋利的刀把蔬菜切成薄片。","extra":""},{"chapter":12,"key":"12:37","id":37,"word":"spoon","phonetic":"/spuːn/","pos":"n.","meaningCN":"匙，调羹","tag":"核心","root":"","exampleEN":"Stir the soup slowly with a wooden spoon to mix the ingredients well.","exampleCN":"用木勺慢慢搅动汤，让各种食材混合均匀。","extra":"spoonful n. 一匙（的量）"},{"chapter":12,"key":"12:38","id":38,"word":"glass","phonetic":"/glas/","pos":"n.","meaningCN":"玻璃；玻璃杯","tag":"核心","root":"","exampleEN":"He poured himself a glass of cold water from the jug.","exampleCN":"他从水罐里给自己倒了一杯凉水。","extra":""},{"chapter":12,"key":"12:39","id":39,"word":"mug","phonetic":"/mʌɡ/","pos":"n.","meaningCN":"大杯，马克杯","tag":"核心","root":"","exampleEN":"She started each day with a hot mug of coffee and a newspaper.","exampleCN":"她用一大杯热咖啡和一份报纸开启每一天。","extra":""},{"chapter":12,"key":"12:40","id":40,"word":"kettle","phonetic":"/'kɛtl/","pos":"n.","meaningCN":"水壶；[美]锅","tag":"核心","root":"","exampleEN":"The electric kettle automatically switches off when the water boils.","exampleCN":"电水壶在水烧开时会自动关闭。","extra":"搭配：a different kettle of fish 截然不同的人；另一码事"},{"chapter":12,"key":"12:41","id":41,"word":"pan","phonetic":"/pæn/","pos":"n.","meaningCN":"平底锅；[美]烤盘","tag":"核心","root":"","exampleEN":"Heat a little oil in a frying pan before adding the eggs.","exampleCN":"在煎锅里热一点油，然后再打入鸡蛋。","extra":"pancake n. 烙饼，薄饼"},{"chapter":12,"key":"12:42","id":42,"word":"pot","phonetic":"/pɒt/","pos":"n.","meaningCN":"锅；壶","tag":"核心","root":"","exampleEN":"She put a large pot of water on the stove to cook the pasta.","exampleCN":"她把一大锅水放在炉子上来煮意大利面。","extra":""},{"chapter":12,"key":"12:43","id":43,"word":"stove","phonetic":"/stəʊv/","pos":"n.","meaningCN":"炉子","tag":"核心","root":"","exampleEN":"The kitchen is equipped with a gas stove and a large refrigerator.","exampleCN":"厨房配有一个燃气炉和一个大冰箱。","extra":""},{"chapter":12,"key":"12:44","id":44,"word":"oven","phonetic":"/'ʌvən/","pos":"n.","meaningCN":"烤炉，烤箱","tag":"核心","root":"","exampleEN":"Bake the bread in a preheated oven for about twenty minutes.","exampleCN":"在预热好的烤箱里把面包烤大约二十分钟。","extra":"搭配：a microwave oven 微波炉"},{"chapter":12,"key":"12:45","id":45,"word":"tin","phonetic":"/tin/","pos":"n.","meaningCN":"锡；罐头","tag":"核心","root":"","exampleEN":"He opened a tin of beans and heated them up in a small pan.","exampleCN":"他开了一罐豆子，放到一个小平底锅里加热。","extra":""},{"chapter":12,"key":"12:46","id":46,"word":"lid","phonetic":"/lid/","pos":"n.","meaningCN":"盖子","tag":"核心","root":"","exampleEN":"Put the lid on the pot to keep the soup warm while you set the table.","exampleCN":"给锅盖上盖子以保持汤温热，同时你去摆桌子。","extra":""},{"chapter":12,"key":"12:47","id":47,"word":"drink","phonetic":"/drink/","pos":"v.","meaningCN":"饮，喝；喝酒 n. 饮料","tag":"核心","root":"","exampleEN":"It is important to drink plenty of water during hot summer days.","exampleCN":"在炎热的夏天，多喝水很重要。","extra":""},{"chapter":12,"key":"12:48","id":48,"word":"beverage","phonetic":"/bevərdʒ/","pos":"n.","meaningCN":"（水以外的）饮料","tag":"高频","root":"","exampleEN":"The conference fee includes lunch and two non-alcoholic beverages.","exampleCN":"会议费包括午餐和两杯无酒精饮料。","extra":"搭配：alcoholic beverage 酒精饮料"},{"chapter":12,"key":"12:49","id":49,"word":"juice","phonetic":"/dʒu:s/","pos":"n.","meaningCN":"果汁，菜汁","tag":"核心","root":"","exampleEN":"A glass of freshly squeezed orange juice is an excellent way to start the day.","exampleCN":"一杯鲜榨橙汁是开启新一天的绝佳方式。","extra":""},{"chapter":12,"key":"12:50","id":50,"word":"soda","phonetic":"/səudə/","pos":"n.","meaningCN":"无水碳酸钠；苏打水；[美]汽水","tag":"高频","root":"","exampleEN":"She asked for a soda with ice and a slice of lemon.","exampleCN":"她要了一杯加冰和一片柠檬的苏打水。","extra":""},{"chapter":12,"key":"12:51","id":51,"word":"coffee","phonetic":"/kəfi/","pos":"n.","meaningCN":"咖啡","tag":"核心","root":"","exampleEN":"He can't start working in the morning without a cup of strong coffee.","exampleCN":"他早上不喝一杯浓咖啡就无法开始工作。","extra":""},{"chapter":12,"key":"12:52","id":52,"word":"alcohol","phonetic":"/'ælkəhɔl/","pos":"n.","meaningCN":"酒精，乙醇；酒","tag":"核心","root":"","exampleEN":"Doctors warn that too much alcohol can seriously damage the liver.","exampleCN":"医生警告说，过量饮酒会严重损害肝脏。","extra":"alcoholic adj. 酒精的 n. 酗酒者"},{"chapter":12,"key":"12:53","id":53,"word":"liquor","phonetic":"/'likə/","pos":"n.","meaningCN":"烈性酒","tag":"高频","root":"","exampleEN":"The shop is licensed to sell beer and liquor to customers over 18.","exampleCN":"这家店获准向18岁以上的顾客出售啤酒和烈酒。","extra":""},{"chapter":12,"key":"12:54","id":54,"word":"whisky","phonetic":"/'wisk/","pos":"n.","meaningCN":"威士忌酒","tag":"高频","root":"","exampleEN":"He ordered a glass of whisky on the rocks while waiting for his friend.","exampleCN":"他在等朋友时点了一杯加冰的威士忌。","extra":"也作 whiskey"},{"chapter":12,"key":"12:55","id":55,"word":"brandy","phonetic":"/'brændi/","pos":"n.","meaningCN":"白兰地酒","tag":"低频","root":"","exampleEN":"After dinner, they enjoyed a small glass of brandy in the lounge.","exampleCN":"晚餐后，他们在休息室里享用了一小杯白兰地。","extra":""},{"chapter":12,"key":"12:56","id":56,"word":"drunk","phonetic":"/drʌŋk/","pos":"adj.","meaningCN":"醉的","tag":"核心","root":"","exampleEN":"It is illegal to drive a vehicle while drunk in most countries.","exampleCN":"在大多数国家，醉酒驾驶车辆是违法的。","extra":""},{"chapter":12,"key":"12:57","id":57,"word":"bean","phonetic":"/bi:n/","pos":"n.","meaningCN":"豆","tag":"核心","root":"","exampleEN":"Beans are an excellent source of protein for people on a vegetarian diet.","exampleCN":"豆类是素食者获取蛋白质的极佳来源。","extra":""},{"chapter":12,"key":"12:58","id":58,"word":"cucumber","phonetic":"/kju:kAmba/","pos":"n.","meaningCN":"黄瓜","tag":"核心","root":"","exampleEN":"Sliced cucumber with a little salt makes a refreshing summer snack.","exampleCN":"黄瓜片加少许盐便是一份清爽的夏日小吃。","extra":""},{"chapter":12,"key":"12:59","id":59,"word":"tobacco","phonetic":"/ta'bakau/","pos":"n.","meaningCN":"烟草","tag":"高频","root":"","exampleEN":"The use of tobacco products is banned in many public places worldwide.","exampleCN":"世界范围内许多公共场所禁止使用烟草制品。","extra":""},{"chapter":12,"key":"12:60","id":60,"word":"cigarette","phonetic":"/sigaret/","pos":"n.","meaningCN":"香烟","tag":"核心","root":"","exampleEN":"He decided to quit smoking cigarettes after his doctor's warning.","exampleCN":"在医生的警告后，他决定戒烟。","extra":"cigar n. 雪茄烟"},{"chapter":12,"key":"12:61","id":61,"word":"sober","phonetic":"/sauba/","pos":"adj.","meaningCN":"清醒的；头脑清醒的 v.（使）醒酒","tag":"高频","root":"","exampleEN":"After the accident, he remained sober and calmly called for help.","exampleCN":"事故发生后，他保持清醒并冷静地呼救。","extra":"搭配：sober up（使）醒酒"},{"chapter":12,"key":"12:62","id":62,"word":"vegetable","phonetic":"/vedstabl/","pos":"n.","meaningCN":"蔬菜","tag":"核心","root":"","exampleEN":"Children are often encouraged to eat more green vegetables from an early age.","exampleCN":"人们常常鼓励儿童从小就多吃绿色蔬菜。","extra":""},{"chapter":12,"key":"12:63","id":63,"word":"tomato","phonetic":"/ta'mato/","pos":"n.","meaningCN":"番茄","tag":"核心","root":"","exampleEN":"This sauce is made from fresh tomatoes, basil, and olive oil.","exampleCN":"这种酱汁是由新鲜番茄、罗勒和橄榄油制成的。","extra":""},{"chapter":12,"key":"12:64","id":64,"word":"potato","phonetic":"/pa'letau/","pos":"n.","meaningCN":"马铃薯","tag":"核心","root":"","exampleEN":"Baked potato with butter and herbs is a simple but delicious side dish.","exampleCN":"配黄油和香草的烤土豆是一道简单却美味的配菜。","extra":""},{"chapter":12,"key":"12:65","id":65,"word":"pea","phonetic":"/pi:/","pos":"n.","meaningCN":"豌豆","tag":"核心","root":"","exampleEN":"Stir the peas into the rice just before serving for a touch of colour.","exampleCN":"上桌前把豌豆拌入米饭中，增添一点色彩。","extra":""},{"chapter":12,"key":"12:66","id":66,"word":"cabbage","phonetic":"/kabrdʒ/","pos":"n.","meaningCN":"洋白菜，卷心菜，甘蓝","tag":"高频","root":"cap = 头 → cabbage 卷成一个头（球）","exampleEN":"Cabbage soup is a common dish in many Eastern European countries.","exampleCN":"卷心菜汤在许多东欧国家是一道常见的菜肴。","extra":""},{"chapter":12,"key":"12:67","id":67,"word":"onion","phonetic":"/Anjon/","pos":"n.","meaningCN":"洋葱","tag":"核心","root":"","exampleEN":"Chopping onions often brings tears to the eyes of even experienced cooks.","exampleCN":"切洋葱常常让经验丰富的厨师也泪流满面。","extra":""},{"chapter":12,"key":"12:68","id":68,"word":"mushroom","phonetic":"/ma'frum/","pos":"n.","meaningCN":"蘑菇 v. 呈蘑菇状扩散","tag":"核心","root":"","exampleEN":"The small business mushroomed into a nationwide chain within five years.","exampleCN":"这家小企业五年内迅速发展成为一家全国连锁店。","extra":""},{"chapter":12,"key":"12:69","id":69,"word":"eggplant","phonetic":"/egplant/","pos":"n.","meaningCN":"茄子","tag":"高频","root":"","exampleEN":"Grilled eggplant with garlic is a popular summer dish in Mediterranean cuisine.","exampleCN":"蒜香烤茄子是地中海美食中一道受欢迎的夏日菜肴。","extra":""},{"chapter":12,"key":"12:70","id":70,"word":"carrot","phonetic":"/kærət/","pos":"n.","meaningCN":"胡萝卜","tag":"核心","root":"","exampleEN":"She chopped the carrots into small cubes and added them to the stew.","exampleCN":"她把胡萝卜切成小丁，然后放入炖菜中。","extra":""},{"chapter":12,"key":"12:71","id":71,"word":"turnip","phonetic":"/tɜːnʃp/","pos":"n.","meaningCN":"芜菁","tag":"识记","root":"","exampleEN":"Turnip is a root vegetable that can be roasted or added to soups.","exampleCN":"芜菁是一种根茎类蔬菜，可以烤着吃或加到汤里。","extra":""},{"chapter":12,"key":"12:72","id":72,"word":"radish","phonetic":"/rædɪʃ/","pos":"n.","meaningCN":"樱桃萝卜","tag":"低频","root":"","exampleEN":"She sliced the radish thinly to add a crunchy texture to the salad.","exampleCN":"她把樱桃萝卜切成薄片，为沙拉增添清脆的口感。","extra":""},{"chapter":12,"key":"12:73","id":73,"word":"fruit","phonetic":"/fruːt/","pos":"n.","meaningCN":"水果；成果","tag":"核心","root":"","exampleEN":"Eating a variety of fresh fruit every day provides essential vitamins.","exampleCN":"每天吃各种各样的新鲜水果可以提供必需的维生素。","extra":""},{"chapter":12,"key":"12:74","id":74,"word":"peel","phonetic":"/piːl/","pos":"v.","meaningCN":"剥（水果、蔬菜等的）皮 n.（水果）皮","tag":"核心","root":"","exampleEN":"Could you help me peel the potatoes while I prepare the other vegetables?","exampleCN":"我准备其他蔬菜时，你能帮我削一下土豆皮吗？","extra":""},{"chapter":12,"key":"12:75","id":75,"word":"strip","phonetic":"/strɪp/","pos":"v.","meaningCN":"剥去，除去 n. 条，带","tag":"核心","root":"","exampleEN":"First, strip the bark from the branch before carving it into shape.","exampleCN":"先把树枝的皮剥去，再把它雕刻成形。","extra":""},{"chapter":12,"key":"12:76","id":76,"word":"core","phonetic":"/kɔː/","pos":"n.","meaningCN":"果核","tag":"核心","root":"","exampleEN":"After eating the apple, she threw the core into the compost bin.","exampleCN":"吃完苹果后，她把果核扔进了堆肥箱。","extra":""},{"chapter":12,"key":"12:77","id":77,"word":"hull","phonetic":"/hʌl/","pos":"n.","meaningCN":"（果实等的）外壳；船体 v. 剥去（果实等的）外壳","tag":"低频","root":"","exampleEN":"The hull of the ship was damaged when it hit the rocks near the shore.","exampleCN":"船体在触碰到近岸的礁石时受损了。","extra":""},{"chapter":12,"key":"12:78","id":78,"word":"cherry","phonetic":"/ˈtʃerɪ/","pos":"n.","meaningCN":"樱桃；樱桃树","tag":"核心","root":"","exampleEN":"Japan is famous for its cherry blossoms, which attract tourists every spring.","exampleCN":"日本以樱花闻名，每年春天都吸引众多游客。","extra":""},{"chapter":12,"key":"12:79","id":79,"word":"berry","phonetic":"/'beri/","pos":"n.","meaningCN":"浆果","tag":"核心","root":"","exampleEN":"He picked a handful of wild berries while walking through the forest.","exampleCN":"他穿行森林时采摘了一把野生浆果。","extra":"strawberry n. 草莓；blueberry n. 蓝莓"},{"chapter":12,"key":"12:80","id":80,"word":"grape","phonetic":"/graɪp/","pos":"n.","meaningCN":"葡萄","tag":"核心","root":"","exampleEN":"Wine is made by fermenting the juice of crushed grapes over time.","exampleCN":"葡萄酒是通过将压碎的葡萄汁长时间发酵制成的。","extra":""},{"chapter":12,"key":"12:81","id":81,"word":"papaya","phonetic":"/pə'paɪə/","pos":"n.","meaningCN":"番木瓜","tag":"低频","root":"","exampleEN":"Papaya is rich in vitamin C and is often used in tropical fruit salads.","exampleCN":"木瓜富含维生素C，常用于热带水果沙拉中。","extra":""},{"chapter":12,"key":"12:82","id":82,"word":"peach","phonetic":"/piːt/","pos":"n.","meaningCN":"桃子","tag":"核心","root":"","exampleEN":"A ripe peach should feel slightly soft and have a strong sweet smell.","exampleCN":"成熟的桃子摸起来应该有点软，闻起来有浓郁的甜香。","extra":""},{"chapter":12,"key":"12:83","id":83,"word":"pear","phonetic":"/peə/","pos":"n.","meaningCN":"梨","tag":"核心","root":"","exampleEN":"She packed an apple and a pear in her lunch bag for a healthy snack.","exampleCN":"她在午餐袋里装了一个苹果和一个梨，当作健康零食。","extra":""},{"chapter":12,"key":"12:84","id":84,"word":"plum","phonetic":"/plʌm/","pos":"n.","meaningCN":"李子；梅子","tag":"核心","root":"","exampleEN":"The plum tree in the garden produces a large harvest every summer.","exampleCN":"花园里的那棵李子树每年夏天都大获丰收。","extra":""},{"chapter":12,"key":"12:85","id":85,"word":"orange","phonetic":"/ˈɔːrɪndʒ/","pos":"n.","meaningCN":"橙子","tag":"核心","root":"","exampleEN":"The orange is one of the most widely grown citrus fruits in the world.","exampleCN":"橙子是世界上种植最广泛的柑橘类水果之一。","extra":""},{"chapter":12,"key":"12:86","id":86,"word":"melon","phonetic":"/'melən/","pos":"n.","meaningCN":"瓜，甜瓜","tag":"高频","root":"","exampleEN":"On a hot afternoon, nothing is more refreshing than a slice of cold melon.","exampleCN":"在炎热的午后，没有什么比一片冰凉的甜瓜更提神的了。","extra":"watermelon n. 西瓜"},{"chapter":12,"key":"12:87","id":87,"word":"lemon","phonetic":"/'lemən/","pos":"n.","meaningCN":"柠檬","tag":"核心","root":"","exampleEN":"Adding a few drops of lemon juice can greatly enhance the flavor of fish.","exampleCN":"加几滴柠檬汁可以大大提升鱼肉的风味。","extra":"lemonade n. 柠檬饮料"},{"chapter":12,"key":"12:88","id":88,"word":"kiwi","phonetic":"/kiwi:/","pos":"n.","meaningCN":"猕猴桃，奇异果","tag":"高频","root":"","exampleEN":"Kiwi fruit is not only tasty but also packed with vitamin C and fibre.","exampleCN":"猕猴桃不仅美味，而且富含维生素C和纤维。","extra":""},{"chapter":12,"key":"12:89","id":89,"word":"crop","phonetic":"/krop/","pos":"n.","meaningCN":"庄稼；收成，产量","tag":"核心","root":"","exampleEN":"Heavy rain in the spring can damage the crops and reduce the harvest.","exampleCN":"春天的大雨会损害庄稼并减少收成。","extra":"搭配：reap crops 收割庄稼"},{"chapter":12,"key":"12:90","id":90,"word":"corn","phonetic":"/kɔːn/","pos":"n.","meaningCN":"[英]（小麦等）谷物；[美]玉米","tag":"核心","root":"","exampleEN":"Farmers in the region grow corn primarily for animal feed and biofuel.","exampleCN":"该地区的农民种植玉米主要用于动物饲料和生物燃料。","extra":"popcorn n. 爆米花"},{"chapter":12,"key":"12:91","id":91,"word":"grain","phonetic":"/grain/","pos":"n.","meaningCN":"谷物；颗粒","tag":"核心","root":"","exampleEN":"Countries like China and India produce huge quantities of grain each year.","exampleCN":"像中国和印度这样的国家每年生产大量的谷物。","extra":"搭配：a grain of 一点，些微；一粒"},{"chapter":12,"key":"12:92","id":92,"word":"wheat","phonetic":"/wit/","pos":"n.","meaningCN":"小麦","tag":"核心","root":"","exampleEN":"Bread, pasta, and many cereals are all made from wheat flour.","exampleCN":"面包、意大利面和许多麦片都是用小麦粉制成的。","extra":""},{"chapter":12,"key":"12:93","id":93,"word":"reap","phonetic":"/rip/","pos":"v.","meaningCN":"收割；收获","tag":"高频","root":"","exampleEN":"Farmers reap their wheat fields in early summer when the crop turns golden.","exampleCN":"农民在初夏庄稼变成金黄色时收割小麦。","extra":""},{"chapter":12,"key":"12:94","id":94,"word":"flour","phonetic":"/flau/","pos":"n.","meaningCN":"面粉；粉状物质","tag":"核心","root":"","exampleEN":"To make the cake, first sift the flour and sugar together in a bowl.","exampleCN":"要做蛋糕，首先把面粉和糖一起过筛放入碗中。","extra":""},{"chapter":12,"key":"12:95","id":95,"word":"porridge","phonetic":"/ˈpɔrɪdʒ/","pos":"n.","meaningCN":"麦片粥","tag":"高频","root":"","exampleEN":"In many countries, porridge is a traditional breakfast meal during winter.","exampleCN":"在许多国家，麦片粥是冬季传统的早餐食品。","extra":""},{"chapter":12,"key":"12:96","id":96,"word":"paste","phonetic":"/pest/","pos":"n.","meaningCN":"糨糊；面团","tag":"低频","root":"","exampleEN":"Mix the flour and water into a smooth paste before adding it to the soup.","exampleCN":"先把面粉和水混合成光滑的面团，再把它加入汤中。","extra":"搭配：make/mix a paste 和面"},{"chapter":12,"key":"12:97","id":97,"word":"livestock","phonetic":"/laivstok/","pos":"n.","meaningCN":"家畜","tag":"高频","root":"","exampleEN":"Raising livestock is the main source of income for many rural families.","exampleCN":"饲养家畜是许多农村家庭的主要收入来源。","extra":"搭配：livestock sector 牲畜饲牧业"},{"chapter":12,"key":"12:98","id":98,"word":"chicken","phonetic":"/tʃikən/","pos":"n.","meaningCN":"鸡","tag":"核心","root":"","exampleEN":"They keep a few chickens in the yard to provide fresh eggs every day.","exampleCN":"他们在院子里养了几只鸡，每天提供新鲜鸡蛋。","extra":""},{"chapter":12,"key":"12:99","id":99,"word":"turkey","phonetic":"/tʃuki/","pos":"n.","meaningCN":"火鸡","tag":"高频","root":"","exampleEN":"Roast turkey is the centrepiece of Thanksgiving dinner in many American homes.","exampleCN":"烤火鸡是许多美国家庭感恩节晚餐的主菜。","extra":""},{"chapter":12,"key":"12:100","id":100,"word":"beef","phonetic":"/bi:/","pos":"n.","meaningCN":"牛肉","tag":"核心","root":"","exampleEN":"He ordered a steak made from the finest local beef in the restaurant.","exampleCN":"他在餐厅点了一份用当地最好的牛肉制成的牛排。","extra":"beefy adj. 强壮的；肥胖的；搭配：braise beef 炖牛肉"},{"chapter":12,"key":"12:101","id":101,"word":"dairy","phonetic":"/'deari/","pos":"n.","meaningCN":"乳制品；乳品店 adj. 乳制的","tag":"核心","root":"","exampleEN":"Dairy products such as milk and cheese are rich in calcium and protein.","exampleCN":"牛奶和奶酪等乳制品富含钙和蛋白质。","extra":"diary n. 日记；搭配：dairy products 乳制品"},{"chapter":12,"key":"12:102","id":102,"word":"pork","phonetic":"/pɔ:k/","pos":"n.","meaningCN":"猪肉","tag":"核心","root":"","exampleEN":"Sweet and sour pork is a classic dish in Chinese restaurants worldwide.","exampleCN":"酸甜咕咾肉是世界各地中餐馆的一道经典菜肴。","extra":""},{"chapter":12,"key":"12:103","id":103,"word":"mutton","phonetic":"/mʌtn/","pos":"n.","meaningCN":"羊肉","tag":"高频","root":"","exampleEN":"Mutton stew is a hearty winter meal popular in many mountainous regions.","exampleCN":"炖羊肉是一道丰盛的冬季菜肴，在许多山区很受欢迎。","extra":""},{"chapter":12,"key":"12:104","id":104,"word":"sausage","phonetic":"/'spsidʒ/","pos":"n.","meaningCN":"香肠","tag":"核心","root":"","exampleEN":"Grilled sausage with fried onions makes a simple but delicious street food.","exampleCN":"烤香肠配煎洋葱是一种简单又美味的街头小吃。","extra":""},{"chapter":12,"key":"12:105","id":105,"word":"milk","phonetic":"/mɪlk/","pos":"n.","meaningCN":"奶 v. 挤奶","tag":"核心","root":"","exampleEN":"She drinks a glass of warm milk almost every night before going to bed.","exampleCN":"她几乎每天晚上睡觉前都喝一杯温牛奶。","extra":""},{"chapter":12,"key":"12:106","id":106,"word":"yogurt","phonetic":"/'jɒɡət/","pos":"n.","meaningCN":"酸奶","tag":"核心","root":"","exampleEN":"Plain yogurt with fresh berries makes a healthy and convenient breakfast.","exampleCN":"原味酸奶搭配新鲜浆果是一份健康又方便的早餐。","extra":""},{"chapter":12,"key":"12:107","id":107,"word":"cream","phonetic":"/kri:m/","pos":"n.","meaningCN":"奶油","tag":"核心","root":"","exampleEN":"She added a spoonful of thick cream to the soup to make it richer.","exampleCN":"她往汤里加了一勺浓奶油，让味道更香浓。","extra":"creamy adj. 含乳脂的；奶油色的"},{"chapter":12,"key":"12:108","id":108,"word":"fish","phonetic":"/fɪʃ/","pos":"n.","meaningCN":"鱼 v. 钓鱼","tag":"核心","root":"","exampleEN":"Eating fish twice a week is recommended for a healthy heart.","exampleCN":"每周吃两次鱼对心脏健康有益。","extra":"搭配：an odd fish 古怪的人"},{"chapter":12,"key":"12:109","id":109,"word":"cheese","phonetic":"/tʃiːz/","pos":"n.","meaningCN":"奶酪","tag":"核心","root":"","exampleEN":"A simple cheese sandwich can be a satisfying lunch when you are in a hurry.","exampleCN":"赶时间的时候，一个简单的奶酪三明治就是一顿令人满足的午餐。","extra":"搭配：a big cheese 要员，大人物"},{"chapter":12,"key":"12:110","id":110,"word":"pond","phonetic":"/pɒnd/","pos":"n.","meaningCN":"池塘","tag":"核心","root":"","exampleEN":"The children fed the ducks swimming in the small pond near the park.","exampleCN":"孩子们投喂了在公园附近小池塘里游泳的鸭子。","extra":""},{"chapter":12,"key":"12:111","id":111,"word":"butter","phonetic":"/'bʌtə/","pos":"n.","meaningCN":"黄油 v. 涂黄油","tag":"核心","root":"","exampleEN":"She spread a thick layer of butter on the warm toast.","exampleCN":"她在热乎乎的烤面包片上涂了厚厚一层黄油。","extra":""},{"chapter":12,"key":"12:112","id":112,"word":"rod","phonetic":"/rɒd/","pos":"n.","meaningCN":"杆，竿","tag":"高频","root":"","exampleEN":"He took his fishing rod and walked to the riverside early in the morning.","exampleCN":"他一大早就拿着钓鱼竿走到了河边。","extra":"搭配：a fishing rod 钓鱼竿"},{"chapter":12,"key":"12:113","id":113,"word":"salad","phonetic":"/'sæləd/","pos":"n.","meaningCN":"色拉","tag":"核心","root":"sal = 盐 → salad 意为“被加过盐的”","exampleEN":"A fresh green salad with a light dressing is perfect with any main dish.","exampleCN":"一份配有清淡调料的鲜蔬色拉与任何主菜都是绝配。","extra":""},{"chapter":12,"key":"12:114","id":114,"word":"pie","phonetic":"/pai/","pos":"n.","meaningCN":"馅饼，派","tag":"核心","root":"","exampleEN":"She baked an apple pie for the family gathering, and it was finished in minutes.","exampleCN":"她为家庭聚会烤了一个苹果派，几分钟就被吃光了。","extra":"搭配：a pie chart 饼状图"},{"chapter":12,"key":"12:115","id":115,"word":"pizza","phonetic":"/'pitsa/","pos":"n.","meaningCN":"比萨饼","tag":"核心","root":"","exampleEN":"They decided to order a large pizza with extra cheese and mushrooms.","exampleCN":"他们决定点一个大号的比萨，加额外奶酪和蘑菇。","extra":""},{"chapter":12,"key":"12:116","id":116,"word":"pasta","phonetic":"/'pasta/","pos":"n.","meaningCN":"意大利面食","tag":"核心","root":"","exampleEN":"Pasta is incredibly versatile and can be served with a huge variety of sauces.","exampleCN":"意大利面食用途广泛，可以搭配各种各样的酱汁。","extra":""},{"chapter":12,"key":"12:117","id":117,"word":"sandwich","phonetic":"/'sanwridʒ/","pos":"v.","meaningCN":"把......夹入 n. 三明治","tag":"核心","root":"","exampleEN":"He was sandwiched between two tall man on the crowded underground train.","exampleCN":"在拥挤的地铁上，他被夹在两个高个子男人之间。","extra":""},{"chapter":12,"key":"12:118","id":118,"word":"hamburger","phonetic":"/'hamb3:ga/","pos":"n.","meaningCN":"汉堡包；汉堡牛肉饼","tag":"核心","root":"","exampleEN":"The children wanted hamburgers and fries for lunch after the movie.","exampleCN":"看完电影后，孩子们午餐想吃汉堡和薯条。","extra":""},{"chapter":12,"key":"12:119","id":119,"word":"spaghetti","phonetic":"/spa'geti/","pos":"n.","meaningCN":"意大利细面条","tag":"核心","root":"","exampleEN":"She twirled the spaghetti around her fork and took a big bite.","exampleCN":"她把意大利面绕在叉子上，然后咬了一大口。","extra":""},{"chapter":12,"key":"12:120","id":120,"word":"soup","phonetic":"/'su:p/","pos":"n.","meaningCN":"汤","tag":"核心","root":"","exampleEN":"A bowl of hot chicken soup is often just what you need on a cold day.","exampleCN":"大冷天里，一碗热鸡汤往往正是你所需要的。","extra":""},{"chapter":12,"key":"12:121","id":121,"word":"pudding","phonetic":"/'pudin/","pos":"n.","meaningCN":"[尤美]冷布丁；[尤英]热布丁糕","tag":"高频","root":"","exampleEN":"After the main course, they served a rich chocolate pudding for dessert.","exampleCN":"主菜过后，他们端上了浓郁的巧克力布丁作为甜点。","extra":""},{"chapter":12,"key":"12:122","id":122,"word":"loaf","phonetic":"/ləʊt/","pos":"n.","meaningCN":"一条（面包） v. 游荡，闲逛","tag":"高频","root":"","exampleEN":"He bought a fresh loaf of wholemeal bread from the bakery on the corner.","exampleCN":"他从街角的面包店买了一条新鲜的全麦面包。","extra":""},{"chapter":12,"key":"12:123","id":123,"word":"biscuit","phonetic":"/'biskit/","pos":"n.","meaningCN":"[英]饼干；[美]烤饼，小圆面包","tag":"核心","root":"","exampleEN":"She offered us tea and a plate of biscuits when we arrived at her home.","exampleCN":"我们到她家时，她招待我们喝茶，还端上一盘饼干。","extra":""},{"chapter":12,"key":"12:124","id":124,"word":"jam","phonetic":"/dʒæm/","pos":"n.","meaningCN":"果酱","tag":"核心","root":"","exampleEN":"He spread strawberry jam generously on his toast every morning.","exampleCN":"他每天早上都在烤面包上涂上厚厚的草莓酱。","extra":""},{"chapter":12,"key":"12:125","id":125,"word":"nut","phonetic":"/nʌt/","pos":"n.","meaningCN":"坚果；螺母","tag":"核心","root":"","exampleEN":"A handful of mixed nuts makes a nutritious snack between meals.","exampleCN":"一把混合坚果是两餐之间富有营养的零食。","extra":""},{"chapter":12,"key":"12:126","id":126,"word":"chocolate","phonetic":"/tʃɒklɪt/","pos":"n.","meaningCN":"巧克力","tag":"核心","root":"","exampleEN":"Dark chocolate with a high cocoa content is believed to have health benefits.","exampleCN":"可可含量高的黑巧克力被认为有益健康。","extra":""},{"chapter":12,"key":"12:127","id":127,"word":"ice cream","phonetic":"/aɪs'kɪm/","pos":"n.","meaningCN":"冰激凌","tag":"核心","root":"","exampleEN":"On hot summer days, children love to buy ice cream from the truck in the park.","exampleCN":"在炎热的夏天，孩子们喜欢从公园里的冰激凌车上买冰激凌。","extra":""},{"chapter":12,"key":"12:128","id":128,"word":"vanilla","phonetic":"/və'nɪlə/","pos":"n.","meaningCN":"香草 adj. 香草味的","tag":"高频","root":"","exampleEN":"Vanilla is one of the most popular ice cream flavours around the world.","exampleCN":"香草是全球最受欢迎的冰激凌口味之一。","extra":"vanilla ice cream / ice-cream cone / ice candy / milkshake / sundae"},{"chapter":12,"key":"12:129","id":129,"word":"mustard","phonetic":"/mʌstəd/","pos":"n.","meaningCN":"芥末；芥菜","tag":"高频","root":"","exampleEN":"He added a little mustard to the sandwich to give it extra flavour.","exampleCN":"他往三明治里加了一点芥末来增添风味。","extra":""},{"chapter":12,"key":"12:130","id":130,"word":"wasabi","phonetic":"/wə'saːbi/","pos":"n.","meaningCN":"山葵；山葵根","tag":"低频","root":"","exampleEN":"Sushi is often eaten with a small amount of wasabi mixed into the soy sauce.","exampleCN":"寿司常常蘸着混入少量山葵的酱油食用。","extra":""},{"chapter":12,"key":"12:131","id":131,"word":"pepper","phonetic":"/'pepə/","pos":"n.","meaningCN":"胡椒粉；柿子椒","tag":"核心","root":"","exampleEN":"Season the steak with salt and freshly ground black pepper before cooking.","exampleCN":"烹饪前用盐和现磨的黑胡椒粉给牛排调味。","extra":""},{"chapter":12,"key":"12:132","id":132,"word":"ginger","phonetic":"/dʒɪndʒə/","pos":"n.","meaningCN":"姜","tag":"核心","root":"","exampleEN":"Ginger tea is a traditional remedy for a sore throat and a cold.","exampleCN":"姜茶是治疗喉咙痛和感冒的传统方法。","extra":""},{"chapter":12,"key":"12:133","id":133,"word":"garlic","phonetic":"/'ɡɑːlɪk/","pos":"n.","meaningCN":"蒜","tag":"核心","root":"","exampleEN":"He fried the garlic in olive oil until it turned golden brown.","exampleCN":"他用橄榄油把蒜煸炒至金黄色。","extra":""},{"chapter":12,"key":"12:134","id":134,"word":"scallion","phonetic":"/'skælɪən/","pos":"n.","meaningCN":"大葱","tag":"低频","root":"","exampleEN":"Chop the scallion finely and sprinkle it on top of the dish before serving.","exampleCN":"把大葱切碎，在上菜前撒在菜肴上。","extra":""},{"chapter":12,"key":"12:135","id":135,"word":"vinegar","phonetic":"/'vɪnɪɡə/","pos":"n.","meaningCN":"醋","tag":"核心","root":"","exampleEN":"A mixture of oil and vinegar makes a simple but tasty salad dressing.","exampleCN":"油和醋的混合物可以制成简单又美味的色拉调料。","extra":""},{"chapter":12,"key":"12:136","id":136,"word":"salt","phonetic":"/sɔːlt/","pos":"n.","meaningCN":"盐","tag":"核心","root":"","exampleEN":"Too much salt in your diet can lead to high blood pressure over time.","exampleCN":"饮食中盐分过多久而久之会导致高血压。","extra":"salty adj. 咸的；含盐的"},{"chapter":12,"key":"12:137","id":137,"word":"sugar","phonetic":"/'sʊɡə/","pos":"n.","meaningCN":"糖","tag":"核心","root":"","exampleEN":"She reduced the amount of sugar in the recipe to make the cake healthier.","exampleCN":"她减少了食谱中糖的用量，让蛋糕更健康。","extra":""},{"chapter":12,"key":"12:138","id":138,"word":"candy","phonetic":"/'kændi/","pos":"n.","meaningCN":"糖果","tag":"核心","root":"","exampleEN":"Children should avoid eating too much candy because it can damage their teeth.","exampleCN":"儿童应该避免吃太多糖果，因为会损害牙齿。","extra":""},{"chapter":12,"key":"12:139","id":139,"word":"honey","phonetic":"/'hʌni/","pos":"n.","meaningCN":"蜂蜜","tag":"核心","root":"","exampleEN":"A spoonful of honey in warm water can soothe a sore throat effectively.","exampleCN":"一勺蜂蜜加入温水中能有效缓解喉咙痛。","extra":""},{"chapter":12,"key":"12:140","id":140,"word":"flavour","phonetic":"/ˈflævər/","pos":"n.","meaningCN":"味道；口味；特色，风格","tag":"核心","root":"","exampleEN":"This ice cream comes in twelve different flavours, from vanilla to mango.","exampleCN":"这款冰淇淋有从香草到芒果的十二种不同口味。","extra":"美式拼写：flavor；形容词：flavourful（美味的）"},{"chapter":12,"key":"12:141","id":141,"word":"sour","phonetic":"/sɔːr/","pos":"adj.","meaningCN":"酸的；闷闷不乐的","tag":"核心","root":"","exampleEN":"The lemonade tasted too sour, so I added a spoonful of sugar.","exampleCN":"柠檬水尝起来太酸了，所以我加了一勺糖。","extra":"搭配：look sour（满脸不高兴）；反义词：sweet"},{"chapter":12,"key":"12:142","id":142,"word":"sweet","phonetic":"/swiːt/","pos":"adj.","meaningCN":"甜的；愉快的","tag":"核心","root":"","exampleEN":"The sweet aroma of freshly baked cookies filled the entire kitchen.","exampleCN":"新鲜出炉的饼干甜蜜的香气充满了整个厨房。","extra":"动词：sweeten（使变甜）；名词：sweetness"},{"chapter":12,"key":"12:143","id":143,"word":"bitter","phonetic":"/ˈbɪtə/","pos":"adj.","meaningCN":"苦的；痛苦的；严寒的","tag":"核心","root":"","exampleEN":"Black coffee has a bitter taste, but many people enjoy it without sugar.","exampleCN":"黑咖啡有苦味，但很多人喜欢不加糖饮用。","extra":"名词：bitterness；反义词：sweet"},{"chapter":12,"key":"12:144","id":144,"word":"spicy","phonetic":"/ˈspaɪsɪ/","pos":"adj.","meaningCN":"辣的","tag":"核心","root":"","exampleEN":"The spicy curry made my mouth burn, but I couldn't stop eating it.","exampleCN":"辛辣的咖喱让我的嘴里火辣辣的，但我还是忍不住一直吃。","extra":"名词：spice（香料）；比较级：spicier"},{"chapter":12,"key":"12:145","id":145,"word":"delicious","phonetic":"/dɪˈlɪʃəs/","pos":"adj.","meaningCN":"美味的","tag":"核心","root":"","exampleEN":"My grandmother's homemade apple pie is absolutely delicious.","exampleCN":"我祖母自制的苹果派非常美味。","extra":"副词：deliciously；同义词：tasty"},{"chapter":12,"key":"12:146","id":146,"word":"yummy","phonetic":"/ˈjʌmi/","pos":"adj.","meaningCN":"美味的","tag":"高频","root":"","exampleEN":"The chocolate cake was so yummy that I asked for a second slice.","exampleCN":"巧克力蛋糕太好吃了，我又要了一块。","extra":"常用于儿童口语；比较级：yummier"},{"chapter":12,"key":"12:147","id":147,"word":"tasty","phonetic":"/ˈteɪstɪ/","pos":"adj.","meaningCN":"美味的，可口的","tag":"核心","root":"","exampleEN":"The chef prepared a tasty meal using only fresh local ingredients.","exampleCN":"厨师只用当地新鲜的食材就做出了一顿可口的饭菜。","extra":"名词：taste；比较级：tastier"},{"chapter":12,"key":"12:148","id":148,"word":"hunger","phonetic":"/ˈhʌŋɡər/","pos":"n.","meaningCN":"饥饿；饥饿感；渴望","tag":"核心","root":"","exampleEN":"After hiking for six hours, we felt a sharp hunger and stopped for a meal.","exampleCN":"徒步六小时后，我们感到强烈的饥饿，停下来吃了一顿饭。","extra":"形容词：hungry（饥饿的）；搭配：hunger for（渴望）"},{"chapter":12,"key":"12:149","id":149,"word":"thirsty","phonetic":"/ˈθɜːrstɪ/","pos":"adj.","meaningCN":"渴的；渴望的","tag":"核心","root":"","exampleEN":"The players were thirsty after running on the field under the hot sun.","exampleCN":"球员们在烈日下奔跑后感到口渴。","extra":"名词：thirst；搭配：thirsty for（渴望）"},{"chapter":12,"key":"12:150","id":150,"word":"spice","phonetic":"/spaɪs/","pos":"n.","meaningCN":"(调味)香料；给生活增添情趣的事","tag":"核心","root":"","exampleEN":"Cinnamon and cumin are common spices used in many cuisines around the world.","exampleCN":"肉桂和小茴香是世界各地许多菜肴中常用的香料。","extra":"形容词：spicy（辛辣的）；习语：Variety is the spice of life."},{"chapter":12,"key":"12:151","id":151,"word":"sauce","phonetic":"/seɪs/","pos":"n.","meaningCN":"酱汁","tag":"核心","root":"","exampleEN":"The spaghetti was delicious with a rich tomato and basil sauce.","exampleCN":"浓郁的番茄罗勒酱让意大利面非常美味。","extra":"搭配：soy sauce（酱油）；on the sauce（经常喝酒）"},{"chapter":12,"key":"12:152","id":152,"word":"ketchup","phonetic":"/ˈketʃup/","pos":"n.","meaningCN":"番茄酱","tag":"高频","root":"","exampleEN":"He always adds extra ketchup to his fries, even though it's unhealthy.","exampleCN":"他总是在薯条上加很多番茄酱，即使这不健康。","extra":"也拼作catsup；常见搭配：tomato ketchup"},{"chapter":12,"key":"12:153","id":153,"word":"perfume","phonetic":"/ˈpɜːrfjuːm/","pos":"n.","meaningCN":"香味，芳香；香水","tag":"高频","root":"","exampleEN":"The perfume of roses in the garden attracted many butterflies.","exampleCN":"花园里玫瑰的芳香吸引了许多蝴蝶。","extra":"动词：perfume（使充满香气）；形容词：perfumed"},{"chapter":12,"key":"12:154","id":154,"word":"ingredient","phonetic":"/ɪnˈɡriːdiənt/","pos":"n.","meaningCN":"成分；(烹调用的)原料；因素","tag":"核心","root":"","exampleEN":"Fresh ingredients are the key to making a healthy and tasty salad.","exampleCN":"新鲜的食材是制作健康美味沙拉的关键。","extra":"同义词：component, element"},{"chapter":12,"key":"12:155","id":155,"word":"supplement","phonetic":"/ˈsʌpləmənt/","pos":"n.","meaningCN":"营养补充剂；补贴","tag":"高频","root":"","exampleEN":"Many athletes take vitamin supplements to improve their performance.","exampleCN":"许多运动员服用维生素补充剂来提高表现。","extra":"动词义：增补，补充（/ˈsʌpləment/）"},{"chapter":12,"key":"12:156","id":156,"word":"digest","phonetic":"/ˈdaɪdʒest/","pos":"v.","meaningCN":"消化；理解，领悟","tag":"核心","root":"","exampleEN":"It takes time to digest a large meal, so don't exercise immediately after eating.","exampleCN":"消化一顿大餐需要时间，所以饭后不要马上运动。","extra":"名词：digestion（消化）；形容词：digestive"},{"chapter":12,"key":"12:157","id":157,"word":"cook","phonetic":"/kʊk/","pos":"v.","meaningCN":"烹调，烧，煮 n. 厨师","tag":"核心","root":"","exampleEN":"My father loves to cook Italian dishes for the whole family on weekends.","exampleCN":"我父亲喜欢在周末为全家人做意大利菜。","extra":"名词：cooker（炊具）；形容词：cooked（煮熟的）"},{"chapter":12,"key":"12:158","id":158,"word":"bake","phonetic":"/beɪk/","pos":"v.","meaningCN":"烘烤；烤熟","tag":"核心","root":"","exampleEN":"We decided to bake fresh bread for our neighbors as a friendly gesture.","exampleCN":"我们决定烘焙新鲜面包送给邻居，以示友好。","extra":"名词：baker（面包师）；bakery（面包店）"},{"chapter":12,"key":"12:159","id":159,"word":"fry","phonetic":"/fraɪ/","pos":"v.","meaningCN":"油煎","tag":"核心","root":"","exampleEN":"She likes to fry eggs in olive oil for a healthier breakfast.","exampleCN":"她喜欢用橄榄油煎鸡蛋，使早餐更健康。","extra":"名词：frying pan（煎锅）；过去式：fried"},{"chapter":12,"key":"12:160","id":160,"word":"roast","phonetic":"/rəʊst/","pos":"v.","meaningCN":"烤 n. 烤肉","tag":"核心","root":"","exampleEN":"We roasted a chicken in the oven for Sunday lunch with the family.","exampleCN":"我们在烤箱里烤了一只鸡，供周日家庭午餐。","extra":"形容词：roasted；常见搭配：roast beef"},{"chapter":12,"key":"12:161","id":161,"word":"toast","phonetic":"/təʊst/","pos":"v.","meaningCN":"向......祝酒，为......干杯；烤 n. 烤面包片","tag":"高频","root":"","exampleEN":"Let's toast to the happy couple and their future together.","exampleCN":"让我们为这对幸福的夫妇和他们的未来干杯。","extra":"名词：toaster（烤面包机）；文化来源：17世纪英国饮酒习俗"},{"chapter":12,"key":"12:162","id":162,"word":"suck","phonetic":"/sʌk/","pos":"v.","meaningCN":"吮吸","tag":"高频","root":"","exampleEN":"The baby sucked milk from the bottle contentedly before falling asleep.","exampleCN":"婴儿满足地吮吸奶瓶里的牛奶，然后睡着了。","extra":"搭配：suck up（吸起；奉承）"},{"chapter":12,"key":"12:163","id":163,"word":"swallow","phonetic":"/ˈswɒləʊ/","pos":"v.","meaningCN":"咽下，吞下","tag":"核心","root":"","exampleEN":"It's dangerous to swallow chewing gum, as it may cause digestive problems.","exampleCN":"吞下口香糖很危险，可能会引起消化问题。","extra":"名词：swallow（吞咽；燕子）"},{"chapter":12,"key":"12:164","id":164,"word":"lick","phonetic":"/lɪk/","pos":"v.","meaningCN":"舔","tag":"高频","root":"","exampleEN":"The dog licked its owner's hand to show affection and gratitude.","exampleCN":"狗舔主人的手以示喜爱和感激。","extra":"名词：lick（舔；少量）；习语：lick one's lips（垂涎欲滴）"},{"chapter":12,"key":"12:165","id":165,"word":"chew","phonetic":"/tʃuː/","pos":"v.","meaningCN":"咀嚼","tag":"核心","root":"","exampleEN":"You should chew each bite thoroughly to help your stomach digest easily.","exampleCN":"你应该彻底咀嚼每一口食物，帮助胃更容易消化。","extra":"名词：chewing gum（口香糖）；搭配：chew over（仔细考虑）"},{"chapter":12,"key":"12:166","id":166,"word":"gum","phonetic":"/ɡʌm/","pos":"n.","meaningCN":"口香糖；树胶","tag":"高频","root":"","exampleEN":"Chewing gum after meals can help freshen your breath and clean your teeth.","exampleCN":"饭后嚼口香糖有助于清新口气和清洁牙齿。","extra":"组合词：chewing gum；注意：gums（牙龈）"},{"chapter":12,"key":"12:167","id":167,"word":"soak","phonetic":"/səʊk/","pos":"v.","meaningCN":"浸泡；使湿透","tag":"核心","root":"","exampleEN":"You need to soak the dried beans overnight before cooking them.","exampleCN":"你需要在煮干豆之前将其浸泡一夜。","extra":"名词：soak（浸泡）；形容词：soaking（湿透的）"},{"chapter":12,"key":"12:168","id":168,"word":"dip","phonetic":"/dɪp/","pos":"v.","meaningCN":"蘸，浸","tag":"高频","root":"","exampleEN":"She dipped the strawberry into melted chocolate and then let it cool.","exampleCN":"她把草莓蘸入融化的巧克力中，然后让它冷却。","extra":"名词：dip（蘸料；下降）"},{"chapter":12,"key":"12:169","id":169,"word":"squeeze","phonetic":"/ˈskwiːz/","pos":"v.","meaningCN":"挤压","tag":"核心","root":"","exampleEN":"Squeeze the lemon gently to get the juice without releasing seeds.","exampleCN":"轻轻挤压柠檬以榨出汁液，同时避免籽掉出来。","extra":"搭配：squeeze something out of something（从某物中榨出某物）"},{"chapter":12,"key":"12:170","id":170,"word":"stir","phonetic":"/stɜː/","pos":"v.","meaningCN":"搅动；（使）行动","tag":"核心","root":"","exampleEN":"Stir the soup occasionally to prevent it from sticking to the bottom of the pot.","exampleCN":"不时搅动汤，防止它粘在锅底。","extra":"名词：stir（搅动；轰动）；搭配：stir up（激起）"},{"chapter":12,"key":"12:171","id":171,"word":"grind","phonetic":"/ɡrɪnd/","pos":"v.","meaningCN":"碾碎 n. 枯燥乏味的事","tag":"高频","root":"","exampleEN":"I use a coffee grinder to grind fresh beans every morning.","exampleCN":"我每天早上去用咖啡研磨机磨新鲜的咖啡豆。","extra":"习语：grind down（欺压）；名词：grinder（研磨机）"},{"chapter":12,"key":"12:172","id":172,"word":"slice","phonetic":"/slaɪs/","pos":"n./v.","meaningCN":"薄片；切片；切下","tag":"核心","root":"","exampleEN":"Could you slice the bread into thin pieces for the sandwiches?","exampleCN":"你能把面包切成薄片做三明治吗？","extra":"常见搭配：a slice of cake（一块蛋糕）；slice off（切下）"}],"13":[{"chapter":13,"key":"13:1","id":1,"word":"locate","phonetic":"/ləʊˈkeɪt/","pos":"v.","meaningCN":"放置，建立；找到","tag":"核心","root":"","exampleEN":"The new hospital will be located near the college campus for easy access.","exampleCN":"新医院将设在大学校园附近，以方便就医。","extra":"location n. 地点；搭配：be located in/on/at 位于，坐落于"},{"chapter":13,"key":"13:2","id":2,"word":"reside","phonetic":"/rɪˈzaɪd/","pos":"v.","meaningCN":"居住","tag":"高频","root":"","exampleEN":"Many retired people choose to reside in peaceful coastal towns.","exampleCN":"许多退休的人选择居住在宁静的沿海城镇。","extra":"residence n. 居住；住处；residential adj. 住宅的，适合居住的"},{"chapter":13,"key":"13:3","id":3,"word":"inhabit","phonetic":"/ɪnˈhæbɪt/","pos":"v.","meaningCN":"居住于","tag":"高频","root":"","exampleEN":"Several rare species of birds inhabit this remote forest area.","exampleCN":"数种稀有鸟类栖息于这片偏远的森林区域。","extra":"habitable adj. 适合居住的"},{"chapter":13,"key":"13:4","id":4,"word":"migrate","phonetic":"/maɪˈɡreɪt/","pos":"v.","meaningCN":"迁徙；移居","tag":"核心","root":"","exampleEN":"Some animals migrate thousands of kilometres each year to find food.","exampleCN":"有些动物每年迁徙数千公里以寻找食物。","extra":"migration n. 迁徙；移居；immigrate v. 移入；emigrate v. 移居国外"},{"chapter":13,"key":"13:5","id":5,"word":"settle","phonetic":"/ˈsetl/","pos":"v.","meaningCN":"解决；在......定居，使定居","tag":"核心","root":"","exampleEN":"After years of travelling, they finally decided to settle in a small village.","exampleCN":"多年漂泊之后，他们最终决定在一个小村庄定居下来。","extra":"settlement n. 解决；定居点；搭配：settle down 定居下来；平静下来"},{"chapter":13,"key":"13:6","id":6,"word":"dwelling","phonetic":"/ˈdwelɪŋ/","pos":"n.","meaningCN":"住所","tag":"高频","root":"","exampleEN":"The government is building affordable dwellings for low-income families.","exampleCN":"政府正在为低收入家庭建造负担得起的住所。","extra":""},{"chapter":13,"key":"13:7","id":7,"word":"skyscraper","phonetic":"/ˈskaɪˌskreɪpə/","pos":"n.","meaningCN":"摩天大楼","tag":"核心","root":"","exampleEN":"The new skyscraper will offer stunning views over the entire city.","exampleCN":"这栋新摩天大楼将能俯瞰到整个城市的壮丽景色。","extra":""},{"chapter":13,"key":"13:8","id":8,"word":"villa","phonetic":"/ˈvɪlə/","pos":"n.","meaningCN":"乡间别墅；[英]度假别墅","tag":"高频","root":"","exampleEN":"They spent the summer in a beautiful villa surrounded by olive trees.","exampleCN":"他们在一栋被橄榄树环绕的漂亮别墅里度过了夏天。","extra":""},{"chapter":13,"key":"13:9","id":9,"word":"mansion","phonetic":"/ˈmænʃən/","pos":"n.","meaningCN":"宅第，公馆","tag":"高频","root":"","exampleEN":"The historic mansion has been turned into a public museum for everyone to visit.","exampleCN":"这座历史悠久的宅第已被改造成公共博物馆供大家参观。","extra":""},{"chapter":13,"key":"13:10","id":10,"word":"apartment","phonetic":"/əˈpɑːtmənt/","pos":"n.","meaningCN":"[尤美]公寓套房","tag":"核心","root":"","exampleEN":"She rented a small apartment close to the university to save commuting time.","exampleCN":"她在大学附近租了一套小公寓，以节省通勤时间。","extra":"搭配：a suite of apartment 一套公寓"},{"chapter":13,"key":"13:11","id":11,"word":"flat","phonetic":"/flæt/","pos":"n.","meaningCN":"[尤英]单元房，公寓","tag":"核心","root":"","exampleEN":"They bought a ground-floor flat with a lovely little garden at the back.","exampleCN":"他们买了一套底层公寓，后面带一个可爱的小花园。","extra":""},{"chapter":13,"key":"13:12","id":12,"word":"hostel","phonetic":"/ˈhɒstl/","pos":"n.","meaningCN":"廉价招待所","tag":"高频","root":"","exampleEN":"Backpackers often choose to stay in a hostel to meet other travellers.","exampleCN":"背包客经常选择住在青年旅舍，好与其他旅行者交流。","extra":""},{"chapter":13,"key":"13:13","id":13,"word":"lodge","phonetic":"/lɒdʒ/","pos":"v.","meaningCN":"租住； n. 小屋；度假屋","tag":"高频","root":"","exampleEN":"During the ski trip, we lodged at a cosy cabin near the slopes.","exampleCN":"滑雪旅行期间，我们租住在雪道附近一间舒适的小屋里。","extra":""},{"chapter":13,"key":"13:14","id":14,"word":"hut","phonetic":"/hʌt/","pos":"n.","meaningCN":"小屋，棚屋","tag":"低频","root":"","exampleEN":"The fishermen built a small wooden hut near the river to store their nets.","exampleCN":"渔民们在河边建了一间小木屋来存放渔网。","extra":""},{"chapter":13,"key":"13:15","id":15,"word":"cabin","phonetic":"/ˈkæbɪn/","pos":"n.","meaningCN":"小木屋；（船上的）小舱","tag":"高频","root":"","exampleEN":"We booked a log cabin in the forest for a quiet weekend getaway.","exampleCN":"我们在森林里预订了一间原木小屋，去安静地度个周末。","extra":""},{"chapter":13,"key":"13:16","id":16,"word":"block","phonetic":"/blɒk/","pos":"n.","meaningCN":"街区；障碍；一块","tag":"核心","root":"","exampleEN":"There is a small supermarket just a few blocks away from my house.","exampleCN":"离我家几个街区之外就有一家小超市。","extra":"搭配：a block of 一块"},{"chapter":13,"key":"13:17","id":17,"word":"grid","phonetic":"/ɡrɪd/","pos":"n.","meaningCN":"栅栏；网格；输电网","tag":"低频","root":"","exampleEN":"The streets in the centre of the city are laid out in a grid pattern.","exampleCN":"市中心的街道呈网格状布局。","extra":""},{"chapter":13,"key":"13:18","id":18,"word":"aisle","phonetic":"/aɪl/","pos":"n.","meaningCN":"走廊，过道","tag":"高频","root":"","exampleEN":"The bride walked gracefully down the aisle with her father by her side.","exampleCN":"新娘在父亲的陪伴下优雅地走过教堂的过道。","extra":""},{"chapter":13,"key":"13:19","id":19,"word":"cellar","phonetic":"/ˈselə/","pos":"n.","meaningCN":"地窖，地下室","tag":"低频","root":"","exampleEN":"They stored boxes of old books in the cool and dark cellar.","exampleCN":"他们把一箱箱旧书存放在阴凉黑暗的地下室里。","extra":""},{"chapter":13,"key":"13:20","id":20,"word":"shed","phonetic":"/ʃed/","pos":"n.","meaningCN":"简易房，棚； v. 流，洒；摆脱","tag":"低频","root":"","exampleEN":"He keeps his gardening tools in a small wooden shed behind the house.","exampleCN":"他把园艺工具放在屋后一间小木棚里。","extra":""},{"chapter":13,"key":"13:21","id":21,"word":"porch","phonetic":"/pɔːtʃ/","pos":"n.","meaningCN":"门廊","tag":"低频","root":"","exampleEN":"On summer evenings, they often sit on the porch enjoying the cool breeze.","exampleCN":"夏天的傍晚，他们经常坐在门廊上享受凉爽的微风。","extra":""},{"chapter":13,"key":"13:22","id":22,"word":"corridor","phonetic":"/ˈkɒrɪdɔː/","pos":"n.","meaningCN":"走廊，通道","tag":"核心","root":"","exampleEN":"Students quietly walked along the corridor while others were taking exams.","exampleCN":"其他学生在考试时，学生们沿着走廊安静地行走。","extra":""},{"chapter":13,"key":"13:23","id":23,"word":"cottage","phonetic":"/ˈkɒtɪdʒ/","pos":"n.","meaningCN":"村舍，小屋","tag":"高频","root":"","exampleEN":"They rented a charming stone cottage in the countryside for the holiday.","exampleCN":"他们在乡间租了一间迷人的石头村舍度假。","extra":"搭配：a summer cottage 避暑别墅"},{"chapter":13,"key":"13:24","id":24,"word":"stair","phonetic":"/steə/","pos":"n.","meaningCN":"楼梯","tag":"核心","root":"","exampleEN":"He sat on the bottom stair to tie his shoelaces before leaving the house.","exampleCN":"他出门前坐在最下面一级楼梯上系鞋带。","extra":"upstairs / downstairs"},{"chapter":13,"key":"13:25","id":25,"word":"nursery","phonetic":"/ˈnɜːsəri/","pos":"n.","meaningCN":"托儿所； adj. 托儿所的","tag":"核心","root":"","exampleEN":"Many working parents send their toddlers to a nursery during the day.","exampleCN":"许多在职父母白天把幼儿送到托儿所。","extra":""},{"chapter":13,"key":"13:26","id":26,"word":"cradle","phonetic":"/ˈkreɪdl/","pos":"n.","meaningCN":"摇篮；发源地","tag":"高频","root":"","exampleEN":"Ancient China is often called the cradle of one of the world's oldest civilisations.","exampleCN":"古代中国常被称为世界上最古老文明之一的发源地。","extra":"搭配：from the cradle to the grave 从生到死；a cradle song 摇篮曲"},{"chapter":13,"key":"13:27","id":27,"word":"shelter","phonetic":"/ˈʃeltə/","pos":"n.","meaningCN":"庇护处；掩蔽； v. 庇护；遮蔽","tag":"核心","root":"","exampleEN":"Many volunteers helped build shelters for families who lost their homes in the flood.","exampleCN":"许多志愿者帮助为洪水中失去家园的家庭建造庇护所。","extra":"搭配：shelter from the rain 避雨"},{"chapter":13,"key":"13:28","id":28,"word":"staircase","phonetic":"/ˈsteəkeɪs/","pos":"n.","meaningCN":"（建筑内的）楼梯","tag":"高频","root":"","exampleEN":"The main staircase of the old library is made of beautifully carved wood.","exampleCN":"老图书馆的主楼梯由雕刻精美的木头制成。","extra":""},{"chapter":13,"key":"13:29","id":29,"word":"storey","phonetic":"/ˈstɔːri/","pos":"n.","meaningCN":"楼层","tag":"高频","root":"","exampleEN":"The office building has twelve storeys and offers great views of the park.","exampleCN":"这栋办公楼有十二层，能俯瞰公园的美丽景色。","extra":"也作 story"},{"chapter":13,"key":"13:30","id":30,"word":"layer","phonetic":"/ˈleɪə/","pos":"n.","meaningCN":"层","tag":"核心","root":"","exampleEN":"A thin layer of ice covered the road, making driving extremely dangerous.","exampleCN":"道路上覆盖着一层薄冰，使驾驶变得极其危险。","extra":""},{"chapter":13,"key":"13:31","id":31,"word":"elevator","phonetic":"/ˈelɪveɪtə/","pos":"n.","meaningCN":"[美]电梯","tag":"核心","root":"","exampleEN":"Please use the elevator if you are going to the fifth floor or above.","exampleCN":"如果要上五楼或更高楼层，请搭乘电梯。","extra":"lift n. [英]电梯；搭配：a freight elevator 货梯"},{"chapter":13,"key":"13:32","id":32,"word":"escalator","phonetic":"/ˈeskəleɪtə/","pos":"n.","meaningCN":"自动扶梯，滚梯","tag":"高频","root":"","exampleEN":"The shopping centre has both lifts and escalators for customers with different needs.","exampleCN":"购物中心既有电梯又有自动扶梯，满足不同顾客的需求。","extra":""},{"chapter":13,"key":"13:33","id":33,"word":"handrail","phonetic":"/ˈhændreɪl/","pos":"n.","meaningCN":"扶手，栏杆","tag":"低频","root":"","exampleEN":"When walking down steep stairs, it is safer to hold the handrail firmly.","exampleCN":"走下陡峭的楼梯时，牢牢抓住扶手会更安全。","extra":""},{"chapter":13,"key":"13:34","id":34,"word":"pillar","phonetic":"/ˈpɪlə/","pos":"n.","meaningCN":"柱子；中坚，栋梁","tag":"高频","root":"","exampleEN":"The roof of the ancient temple is supported by massive stone pillars.","exampleCN":"古庙的屋顶由巨大的石柱支撑。","extra":"搭配：a pillar of society 社会栋梁"},{"chapter":13,"key":"13:35","id":35,"word":"column","phonetic":"/ˈkɒləm/","pos":"n.","meaningCN":"柱；（书、报纸等）栏；专栏","tag":"核心","root":"","exampleEN":"She writes a weekly column for the local newspaper about environmental issues.","exampleCN":"她为当地报纸每周撰写一篇关于环境问题的专栏文章。","extra":"columnist n. 专栏作家"},{"chapter":13,"key":"13:36","id":36,"word":"beam","phonetic":"/biːm/","pos":"n.","meaningCN":"（能量、放射线或粒子的）束，柱","tag":"高频","root":"","exampleEN":"A narrow beam of sunlight came through the small gap in the curtains.","exampleCN":"一束狭窄的阳光透过窗帘的小缝隙照了进来。","extra":"搭配：a laser beam 激光束"},{"chapter":13,"key":"13:37","id":37,"word":"vault","phonetic":"/vɔːlt/","pos":"n.","meaningCN":"拱顶；金库，保险库","tag":"低频","root":"","exampleEN":"The bank keeps its most valuable items in a secure underground vault.","exampleCN":"银行把最贵重的物品存放在一个安全的地下金库中。","extra":"vaulted adj. 有拱顶的，拱形的"},{"chapter":13,"key":"13:38","id":38,"word":"arch","phonetic":"/ɑːtʃ/","pos":"n.","meaningCN":"拱门； v.（使）弯成弓形","tag":"高频","root":"","exampleEN":"The old stone arch bridge has stood over the river for more than 200 years.","exampleCN":"那座古老的石拱桥已经在河上矗立了200多年。","extra":"arched adj. 拱形的，弧形的；搭配：a triumphal arch 凯旋门"},{"chapter":13,"key":"13:39","id":39,"word":"ceiling","phonetic":"/ˈsiːlɪŋ/","pos":"n.","meaningCN":"天花板，顶棚","tag":"核心","root":"","exampleEN":"The ceiling of the concert hall was painted with beautiful clouds and stars.","exampleCN":"音乐厅的天花板上画着美丽的云朵和星星。","extra":""},{"chapter":13,"key":"13:40","id":40,"word":"eaves","phonetic":"/iːvz/","pos":"n.","meaningCN":"屋檐","tag":"低频","root":"","exampleEN":"A family of swallows built their nest under the eaves of the old barn.","exampleCN":"一窝燕子在老谷仓的屋檐下筑了巢。","extra":""},{"chapter":13,"key":"13:41","id":41,"word":"chimney","phonetic":"/ˈtʃɪmni/","pos":"n.","meaningCN":"烟囱","tag":"高频","root":"","exampleEN":"In the story, Santa Claus comes down the chimney to deliver presents to children.","exampleCN":"故事里，圣诞老人从烟囱下来给孩子们送礼物。","extra":""},{"chapter":13,"key":"13:42","id":42,"word":"reception","phonetic":"/rɪˈsepʃn/","pos":"n.","meaningCN":"接待处","tag":"核心","root":"","exampleEN":"Please sign your name at the reception desk before entering the building.","exampleCN":"请在进入大楼前到接待处签名。","extra":"receptionist n. 接待员"},{"chapter":13,"key":"13:43","id":43,"word":"lobby","phonetic":"/ˈlɒbi/","pos":"n.","meaningCN":"大厅，前厅；游说； v. 游说","tag":"核心","root":"","exampleEN":"We agreed to meet in the hotel lobby at seven o'clock before going out for dinner.","exampleCN":"我们约好七点在酒店大厅见面，然后出去吃晚饭。","extra":"lobbyist n. 说客"},{"chapter":13,"key":"13:44","id":44,"word":"bench","phonetic":"/bentʃ/","pos":"n.","meaningCN":"长凳；[the-] 法官职位","tag":"核心","root":"","exampleEN":"Two elderly men were playing chess on a park bench in the afternoon sun.","exampleCN":"两位老人在午后的阳光下坐在公园长凳上下棋。","extra":""},{"chapter":13,"key":"13:45","id":45,"word":"parlour","phonetic":"/ˈpɑːlə/","pos":"n.","meaningCN":"客厅","tag":"低频","root":"","exampleEN":"The guests were invited into the front parlour, where tea and biscuits were served.","exampleCN":"客人们被请进前客厅，那里备好了茶和饼干。","extra":"也作 parlor"},{"chapter":13,"key":"13:46","id":46,"word":"fireplace","phonetic":"/ˈfaɪəpleɪs/","pos":"n.","meaningCN":"壁炉","tag":"高频","root":"","exampleEN":"On cold winter nights, the family gathers around the fireplace to tell stories.","exampleCN":"寒冷的冬夜里，一家人围坐在壁炉旁讲故事。","extra":""},{"chapter":13,"key":"13:47","id":47,"word":"radiator","phonetic":"/ˈreɪdieɪtə/","pos":"n.","meaningCN":"暖气设备","tag":"高频","root":"","exampleEN":"The radiator in the classroom keeps the students warm during the winter months.","exampleCN":"教室里的暖气片在冬季为学生们保暖。","extra":"radiate v. 散发（热）；发射（光）"},{"chapter":13,"key":"13:48","id":48,"word":"living room","phonetic":"/ˈlɪvɪŋ ruːm/","pos":"n.","meaningCN":"客厅，起居室","tag":"核心","root":"","exampleEN":"The family spends most evenings together in the living room watching television.","exampleCN":"这家人大多数晚上都一起在客厅里看电视。","extra":""},{"chapter":13,"key":"13:49","id":49,"word":"cabinet","phonetic":"/ˈkæbɪnət/","pos":"n.","meaningCN":"储藏柜；内阁","tag":"核心","root":"","exampleEN":"The files are kept in a metal filing cabinet in the corner of the office.","exampleCN":"文件存放在办公室角落的一个金属文件柜里。","extra":"搭配：a cabinet meeting 内阁会议"},{"chapter":13,"key":"13:50","id":50,"word":"balcony","phonetic":"/ˈbælkəni/","pos":"n.","meaningCN":"阳台；（剧院的）楼座","tag":"核心","root":"","exampleEN":"Their new apartment has a large balcony with a wonderful sea view.","exampleCN":"他们的新公寓有一个带绝美海景的大阳台。","extra":""},{"chapter":13,"key":"13:51","id":51,"word":"terrace","phonetic":"/ˈterəs/","pos":"n.","meaningCN":"大阳台，露天平台","tag":"高频","root":"","exampleEN":"We enjoyed lunch on the sunny terrace overlooking the hotel garden.","exampleCN":"我们在洒满阳光的露天平台上享用了午餐，俯瞰酒店的花园。","extra":""},{"chapter":13,"key":"13:52","id":52,"word":"kitchen","phonetic":"/ˈkɪtʃɪn/","pos":"n.","meaningCN":"厨房，灶间","tag":"核心","root":"","exampleEN":"The kitchen is fully equipped with a modern oven, microwave, and dishwasher.","exampleCN":"厨房配备了现代化的烤箱、微波炉和洗碗机。","extra":""},{"chapter":13,"key":"13:53","id":53,"word":"lavatory","phonetic":"/ˈlævətri/","pos":"n.","meaningCN":"盥洗室，厕所","tag":"低频","root":"","exampleEN":"The public lavatory at the park is cleaned twice a day by the staff.","exampleCN":"公园里的公共厕所由工作人员每天清洁两次。","extra":""},{"chapter":13,"key":"13:54","id":54,"word":"toilet","phonetic":"/ˈtɔɪlət/","pos":"n.","meaningCN":"抽水马桶；[英]厕所","tag":"核心","root":"","exampleEN":"Remember to flush the toilet and wash your hands after using it.","exampleCN":"用完厕所后记得冲水并洗手。","extra":"搭配：flush the toilet 冲厕所"},{"chapter":13,"key":"13:55","id":55,"word":"bath","phonetic":"/bɑːθ/","pos":"n.","meaningCN":"洗澡；[英]浴缸","tag":"核心","root":"","exampleEN":"After a long day of hiking, a hot bath helped relax her tired muscles.","exampleCN":"长途徒步一天后，洗了个热水澡帮助她放松了疲惫的肌肉。","extra":"bathe v. 用水清洗"},{"chapter":13,"key":"13:56","id":56,"word":"basin","phonetic":"/ˈbeɪsn/","pos":"n.","meaningCN":"盆；盆地","tag":"核心","root":"","exampleEN":"She filled the basin with warm water and began to wash the fresh fruit.","exampleCN":"她往盆里倒满温水，开始清洗新鲜水果。","extra":"washbowl n. 洗脸盆"},{"chapter":13,"key":"13:57","id":57,"word":"reserve","phonetic":"/rɪˈzɜːv/","pos":"n.","meaningCN":"储备（量）；自然保护区； v. 预订","tag":"核心","root":"","exampleEN":"It is advisable to reserve a table at the restaurant in advance on weekends.","exampleCN":"周末最好提前在餐厅预订桌位。","extra":""},{"chapter":13,"key":"13:58","id":58,"word":"store","phonetic":"/stɔː/","pos":"n.","meaningCN":"商店；贮存物 v. 贮存","tag":"核心","root":"","exampleEN":"I need to store my winter clothes in a box during the summer months.","exampleCN":"夏天的时候我需要把冬装存放在箱子里。","extra":"搭配：a department store（百货商场）"},{"chapter":13,"key":"13:59","id":59,"word":"mall","phonetic":"/mɔːl/","pos":"n.","meaningCN":"[尤美]购物中心","tag":"高频","root":"","exampleEN":"On rainy days, families often spend their afternoons walking around the local mall.","exampleCN":"下雨天，家人常常在当地的购物中心里逛上一下午。","extra":"同义词：shopping center"},{"chapter":13,"key":"13:60","id":60,"word":"complex","phonetic":"/ˈkɒmpleks/","pos":"n.","meaningCN":"综合建筑群","tag":"核心","root":"","exampleEN":"The new sports complex includes a swimming pool, a gym, and several tennis courts.","exampleCN":"新的综合体育中心包括游泳池、健身房和几个网球场。","extra":"形容词义：复杂的"},{"chapter":13,"key":"13:61","id":61,"word":"supermarket","phonetic":"/ˌsuːpəˈmɑːkɪt/","pos":"n.","meaningCN":"超市","tag":"核心","root":"","exampleEN":"You can find almost everything you need for daily life in a large supermarket.","exampleCN":"在大型超市里，你几乎可以找到日常生活所需的一切。","extra":"常见品牌：Tesco, Walmart, Carrefour"},{"chapter":13,"key":"13:62","id":62,"word":"booth","phonetic":"/buːθ/","pos":"n.","meaningCN":"售货摊；电话亭；小隔间","tag":"高频","root":"","exampleEN":"The voting booth was set up in the corner of the community hall.","exampleCN":"投票亭设在社区大厅的角落里。","extra":"搭配：a telephone booth（电话亭）；a photo booth（自助快照亭）"},{"chapter":13,"key":"13:63","id":63,"word":"casino","phonetic":"/kaˈsiːnoʊ/","pos":"n.","meaningCN":"赌场","tag":"低频","root":"","exampleEN":"The city decided to build a casino to attract more tourists, but many residents opposed the plan.","exampleCN":"该市决定建造赌场以吸引更多游客，但许多居民反对这一计划。","extra":"词源：意大利语'小房舍'"},{"chapter":13,"key":"13:64","id":64,"word":"studio","phonetic":"/ˈstiːjuːdiə/","pos":"n.","meaningCN":"演播室；工作室；单间公寓","tag":"核心","root":"","exampleEN":"She rents a small studio downtown where she paints and teaches art classes.","exampleCN":"她在市中心租了一间小工作室，在那里画画并教艺术课。","extra":"搭配：a movie studio（电影制片厂）；a TV studio（电视演播室）"},{"chapter":13,"key":"13:65","id":65,"word":"downtown","phonetic":"/ˌdaʊnˈtaʊn/","pos":"n./adj.","meaningCN":"市中心 adj. 市中心的","tag":"核心","root":"","exampleEN":"The downtown area is always busy with office workers and shoppers during weekdays.","exampleCN":"工作日的市中心总是挤满了上班族和购物者。","extra":"反义词：uptown（住宅区）"},{"chapter":13,"key":"13:66","id":66,"word":"urban","phonetic":"/ˈɜːbən/","pos":"adj.","meaningCN":"城市的","tag":"核心","root":"","exampleEN":"Urban populations are growing rapidly as more people move to cities for better job opportunities.","exampleCN":"随着越来越多的人为了更好的工作机会搬到城市，城市人口正在迅速增长。","extra":"动词：urbanise（使城市化）；名词：urbanisation（城市化）"},{"chapter":13,"key":"13:67","id":67,"word":"peripheral","phonetic":"/pəˈrɪfərəl/","pos":"adj.","meaningCN":"外围的 n. 外围设备","tag":"高频","root":"","exampleEN":"The peripheral areas of the city often lack public transportation and other services.","exampleCN":"城市的外围地区常常缺乏公共交通和其他服务。","extra":"名词：periphery（外围，边缘）"},{"chapter":13,"key":"13:68","id":68,"word":"vicinity","phonetic":"/ˈvɪsɪnɪti/","pos":"n.","meaningCN":"附近，邻近地区","tag":"高频","root":"","exampleEN":"There are several good restaurants in the vicinity of the hotel.","exampleCN":"酒店附近有几家不错的餐厅。","extra":"搭配：in the vicinity of（在……附近）"},{"chapter":13,"key":"13:69","id":69,"word":"room","phonetic":"/ruːm/","pos":"n.","meaningCN":"房间；空间","tag":"核心","root":"","exampleEN":"Is there enough room in your car for all our luggage?","exampleCN":"你车里有足够的空间放我们所有的行李吗？","extra":"注意：room 作'空间'讲时不可数"},{"chapter":13,"key":"13:70","id":70,"word":"void","phonetic":"/ˈvɔːd/","pos":"n.","meaningCN":"空间；空白；空虚 adj. 空的","tag":"高频","root":"","exampleEN":"After her children moved out, she felt a void in her daily life.","exampleCN":"孩子们搬出去后，她在日常生活中感到一种空虚。","extra":"法律用语：null and void（无效）"},{"chapter":13,"key":"13:71","id":71,"word":"spacious","phonetic":"/ˈspeɪʃəs/","pos":"adj.","meaningCN":"宽敞的","tag":"核心","root":"","exampleEN":"The new office is spacious enough to accommodate all the employees comfortably.","exampleCN":"新办公室很宽敞，足以舒适地容纳所有员工。","extra":"名词：space（空间）"},{"chapter":13,"key":"13:72","id":72,"word":"airtight","phonetic":"/ˈeətaɪt/","pos":"adj.","meaningCN":"密封的，不透气的","tag":"高频","root":"","exampleEN":"Store the coffee beans in an airtight container to keep them fresh for longer.","exampleCN":"将咖啡豆存放在密封容器中以保持更长时间的新鲜。","extra":"搭配：an airtight alibi（无懈可击的不在场证明）"},{"chapter":13,"key":"13:73","id":73,"word":"expanse","phonetic":"/ɪkˈspæns/","pos":"n.","meaningCN":"广阔，辽阔","tag":"高频","root":"","exampleEN":"Looking out over the vast expanse of the ocean made him feel peaceful.","exampleCN":"眺望广阔的海洋让他感到平静。","extra":"相关：expand（膨胀），expansion（扩张）"},{"chapter":13,"key":"13:74","id":74,"word":"plaza","phonetic":"/ˈplɑːzə/","pos":"n.","meaningCN":"广场；购物中心","tag":"高频","root":"","exampleEN":"The city's main plaza is often used for concerts and public festivals.","exampleCN":"城市的主广场常用于音乐会和公众节日活动。","extra":"搭配：a travel plaza（公路服务区）"},{"chapter":13,"key":"13:75","id":75,"word":"castle","phonetic":"/ˈkɑːsəl/","pos":"n.","meaningCN":"城堡","tag":"核心","root":"","exampleEN":"The medieval castle has been turned into a museum that attracts thousands of visitors each year.","exampleCN":"这座中世纪城堡已被改造成博物馆，每年吸引成千上万的游客。","extra":"习语：castle in the air（空中楼阁）"},{"chapter":13,"key":"13:76","id":76,"word":"carpenters","phonetic":"/ˈkɑːpəntərz/","pos":"n.","meaningCN":"木匠","tag":"高频","root":"","exampleEN":"The carpenters built custom bookshelves for the library using oak wood.","exampleCN":"木匠们用橡木为图书馆定制了书架。","extra":"词源：原指'制作马车的人'"},{"chapter":13,"key":"13:77","id":77,"word":"mason","phonetic":"/ˈmæzn/","pos":"n.","meaningCN":"石匠，泥瓦匠","tag":"低频","root":"","exampleEN":"The mason carefully chiseled the stone to fit perfectly into the wall.","exampleCN":"石匠小心地凿刻石头，使其完美地嵌入墙壁。","extra":"名词：masonry（砖石建筑）"},{"chapter":13,"key":"13:78","id":78,"word":"tile","phonetic":"/taɪl/","pos":"n.","meaningCN":"瓦；瓷砖","tag":"高频","root":"","exampleEN":"We chose blue tiles for the bathroom floor to match the walls.","exampleCN":"我们为浴室地板选择了蓝色瓷砖以匹配墙面。","extra":"动词：tile（铺瓷砖）"},{"chapter":13,"key":"13:79","id":79,"word":"brickwork","phonetic":"/ˈbrɪkwɜːk/","pos":"n.","meaningCN":"砖结构","tag":"低频","root":"","exampleEN":"The old brickwork on the factory chimney is starting to crumble.","exampleCN":"工厂烟囱上的旧砖结构开始剥落。","extra":"名词：brick（砖）"},{"chapter":13,"key":"13:80","id":80,"word":"suspension","phonetic":"/səˈspenʃən/","pos":"n.","meaningCN":"暂缓；暂停（或停赛等）","tag":"核心","root":"","exampleEN":"The player received a two-game suspension for unsportsmanlike conduct.","exampleCN":"该球员因违反体育道德行为被禁赛两场。","extra":"动词：suspend（暂停；悬挂）"},{"chapter":13,"key":"13:81","id":81,"word":"hook","phonetic":"/hʊk/","pos":"n.","meaningCN":"钩，钩状物；勾拳","tag":"核心","root":"","exampleEN":"Hang your coat on the hook behind the door before you sit down.","exampleCN":"坐下之前把你的外套挂在门后的钩子上。","extra":"文化：Captain Hook（虎克船长）"},{"chapter":13,"key":"13:82","id":82,"word":"lever","phonetic":"/ˈliːvər/","pos":"n.","meaningCN":"杠杆；操纵杆","tag":"核心","root":"","exampleEN":"Pushing the lever forward will increase the speed of the machine.","exampleCN":"向前推动操纵杆会提高机器的速度。","extra":"动词：lever（撬动）"},{"chapter":13,"key":"13:83","id":83,"word":"pole","phonetic":"/pəʊl/","pos":"n.","meaningCN":"竿，杆","tag":"核心","root":"","exampleEN":"The telephone poles along the road were damaged in the storm.","exampleCN":"路边的电线杆在暴风雨中损坏了。","extra":"对比：North Pole / South Pole（北极/南极）"},{"chapter":13,"key":"13:84","id":84,"word":"scaffold","phonetic":"/ˈskæfəld/","pos":"n.","meaningCN":"脚手架；绞刑架","tag":"低频","root":"","exampleEN":"Workers erected a scaffold around the old building to repair the facade.","exampleCN":"工人们在大楼周围搭起脚手架来修复外立面。","extra":"动词：scaffold（搭脚手架）"},{"chapter":13,"key":"13:85","id":85,"word":"infrastructure","phonetic":"/ˈɪnfrəˌstrʌktʃə/","pos":"n.","meaningCN":"基础设施","tag":"核心","root":"","exampleEN":"The government is investing billions in improving the country's aging infrastructure.","exampleCN":"政府正投入数十亿资金改善国家老化的基础设施。","extra":"包括 roads, bridges, power grids 等"},{"chapter":13,"key":"13:86","id":86,"word":"apparatus","phonetic":"/əˈpærətəs/","pos":"n.","meaningCN":"器械，装置","tag":"高频","root":"","exampleEN":"The laboratory is equipped with sophisticated apparatus for chemical analysis.","exampleCN":"实验室配备了用于化学分析的精密器械。","extra":"复数：apparatuses 或 apparatus"},{"chapter":13,"key":"13:87","id":87,"word":"crane","phonetic":"/kreɪn/","pos":"n.","meaningCN":"起重机；鹤","tag":"高频","root":"","exampleEN":"A giant crane was used to lift the steel beams into place.","exampleCN":"用了一台巨大的起重机将钢梁吊装到位。","extra":"动词：crane（伸长脖子）"},{"chapter":13,"key":"13:88","id":88,"word":"malfunction","phonetic":"/ˈmælfʌŋkʃən/","pos":"v.","meaningCN":"发生故障","tag":"高频","root":"mal-（坏的）+ function","exampleEN":"The elevator malfunctioned, trapping several people inside for an hour.","exampleCN":"电梯发生故障，将几个人困在里面一小时。","extra":"名词：malfunction（故障）"},{"chapter":13,"key":"13:89","id":89,"word":"maintain","phonetic":"/meɪnˈteɪn/","pos":"v.","meaningCN":"维持；维修；坚称","tag":"核心","root":"","exampleEN":"You need to maintain your car regularly to keep it running smoothly.","exampleCN":"你需要定期保养汽车以使其平稳运行。","extra":"名词：maintenance（维护）"},{"chapter":13,"key":"13:90","id":90,"word":"fix","phonetic":"/fɪks/","pos":"v.","meaningCN":"修理；使固定","tag":"核心","root":"","exampleEN":"The plumber came to fix the leaking pipe under the sink.","exampleCN":"水管工来修理水槽下面漏水的管子。","extra":"名词：fix（补救；确定）"},{"chapter":13,"key":"13:91","id":91,"word":"weld","phonetic":"/weld/","pos":"v.","meaningCN":"焊接；使紧密结合","tag":"高频","root":"","exampleEN":"The mechanic welded the broken frame back together.","exampleCN":"机械师将断裂的框架焊接在一起。","extra":"名词：weld（焊接点）"},{"chapter":13,"key":"13:92","id":92,"word":"saw","phonetic":"/sɔː/","pos":"n.","meaningCN":"锯","tag":"核心","root":"","exampleEN":"He used a handsaw to cut the wooden board into smaller pieces.","exampleCN":"他用一把手锯将木板切割成更小的块。","extra":"动词：saw（锯开）；过去式：sawed，过去分词：sawn"},{"chapter":13,"key":"13:93","id":93,"word":"screw","phonetic":"/skruː/","pos":"n.","meaningCN":"螺丝钉；螺旋桨","tag":"核心","root":"","exampleEN":"You need a screwdriver to tighten the screws on this hinge.","exampleCN":"你需要一把螺丝刀来拧紧这个铰链上的螺丝钉。","extra":"动词：screw（拧紧）"},{"chapter":13,"key":"13:94","id":94,"word":"drill","phonetic":"/drɪl/","pos":"n./v.","meaningCN":"钻机；反复练习 v. 钻（孔）；训练","tag":"核心","root":"","exampleEN":"The workers used a powerful drill to make holes in the concrete wall.","exampleCN":"工人们用强力钻机在混凝土墙上打孔。","extra":"搭配：fire drill（消防演习）"},{"chapter":13,"key":"13:95","id":95,"word":"plumb","phonetic":"/plʌm/","pos":"n./v.","meaningCN":"(表示垂直度等的)铅锤 v. 用铅垂线校正","tag":"识记","root":"","exampleEN":"The carpenter used a plumb line to ensure the wall was perfectly vertical.","exampleCN":"木匠用铅垂线确保墙壁完全垂直。","extra":"形容词：plumb（垂直的）"},{"chapter":13,"key":"13:96","id":96,"word":"viaduct","phonetic":"/ˌvaɪəˈdʌkt/","pos":"n.","meaningCN":"高架桥","tag":"识记","root":"","exampleEN":"The train crossed the valley on a long stone viaduct built in the 19th century.","exampleCN":"火车行驶在19世纪建造的长石高架桥上穿过山谷。","extra":"对比：aqueduct（渡槽）"},{"chapter":13,"key":"13:97","id":97,"word":"span","phonetic":"/spæn/","pos":"n.","meaningCN":"跨距，跨度；持续时间","tag":"核心","root":"","exampleEN":"The bridge has a main span of over 800 meters, making it one of the longest in the region.","exampleCN":"这座桥的主跨超过800米，是该地区最长的桥梁之一。","extra":"搭配：attention span（注意力持续时间）"},{"chapter":13,"key":"13:98","id":98,"word":"dam","phonetic":"/dæm/","pos":"n.","meaningCN":"水坝 v. 控制，抑制","tag":"核心","root":"","exampleEN":"The dam was built to provide hydroelectric power and control flooding.","exampleCN":"修建水坝是为了提供水力发电并控制洪水。","extra":"动词：dam up（筑坝拦住）"},{"chapter":13,"key":"13:99","id":99,"word":"trim","phonetic":"/trɪm/","pos":"v./adj.","meaningCN":"修剪；装饰 adj. 整齐的，整洁的","tag":"高频","root":"","exampleEN":"He trimmed the hedge into neat shapes with a pair of garden shears.","exampleCN":"他用一把园艺剪把树篱修剪成整齐的形状。","extra":"名词：trim（修剪；装饰）"},{"chapter":13,"key":"13:100","id":100,"word":"assembly","phonetic":"/əˈsembəl/","pos":"v.","meaningCN":"组装；装配","tag":"核心","root":"","exampleEN":"Workers at the factory are responsible for the assembly of electronic components.","exampleCN":"工厂的工人负责电子元件的组装。","extra":"注意：原文词性标为 v.，实际动词是 assemble，此处按原文处理但建议修正"},{"chapter":13,"key":"13:101","id":101,"word":"install","phonetic":"/ɪnˈstɔːl/","pos":"v.","meaningCN":"安装","tag":"核心","root":"","exampleEN":"We hired a professional to install the air conditioning unit before summer.","exampleCN":"我们雇了一位专业人士在夏天到来前安装空调。","extra":"名词：installation"},{"chapter":13,"key":"13:102","id":102,"word":"furnish","phonetic":"/ˈfɜːnɪʃ/","pos":"v.","meaningCN":"为......配备家具陈设","tag":"高频","root":"","exampleEN":"It costs a lot of money to furnish a new apartment with quality furniture.","exampleCN":"为新房配备优质家具要花很多钱。","extra":"名词：furniture（家具）"},{"chapter":13,"key":"13:103","id":103,"word":"placement","phonetic":"/ˈpleɪsmənt/","pos":"n.","meaningCN":"放置，布置","tag":"高频","root":"","exampleEN":"The placement of furniture in a small room requires careful planning.","exampleCN":"小房间里的家具布置需要精心规划。","extra":"动词：place（放置）"},{"chapter":13,"key":"13:104","id":104,"word":"layout","phonetic":"/ˈləʊtaɪ/","pos":"n.","meaningCN":"设计，布置","tag":"核心","root":"","exampleEN":"The layout of the website is intuitive, making it easy for visitors to find information.","exampleCN":"网站的布局很直观，方便访问者查找信息。","extra":"动词：lay out（布置）"},{"chapter":13,"key":"13:105","id":105,"word":"design","phonetic":"/dɪˈzaɪn/","pos":"v./n.","meaningCN":"设计；计划 n. 设计","tag":"核心","root":"","exampleEN":"She designed a beautiful logo for the company's new brand identity.","exampleCN":"她为公司的新品牌形象设计了一个漂亮的标志。","extra":"名词：designer（设计师）"},{"chapter":13,"key":"13:106","id":106,"word":"entrance","phonetic":"/ˈentrəns/","pos":"n.","meaningCN":"入口；进入权","tag":"核心","root":"","exampleEN":"The main entrance to the museum is on the south side of the building.","exampleCN":"博物馆的主入口在大楼的南侧。","extra":"动词：entrance（使入迷）发音不同"},{"chapter":13,"key":"13:107","id":107,"word":"entry","phonetic":"/ˈentri/","pos":"n.","meaningCN":"进入；进入权","tag":"核心","root":"","exampleEN":"Entry to the exhibition is free for children under twelve.","exampleCN":"十二岁以下儿童免费进入展览。","extra":"搭配：entry visa（入境签证）"},{"chapter":13,"key":"13:108","id":108,"word":"enter","phonetic":"/ˈentə/","pos":"v.","meaningCN":"进入","tag":"核心","root":"","exampleEN":"Please enter the building through the side door while the main entrance is being repaired.","exampleCN":"主入口正在维修，请从侧门进入大楼。","extra":"名词：entrance, entry"},{"chapter":13,"key":"13:109","id":109,"word":"exit","phonetic":"/ˈeksɪt/","pos":"n./v.","meaningCN":"出口；退场；离去 v. 离去","tag":"核心","root":"","exampleEN":"In case of fire, use the emergency exit located at the back of the room.","exampleCN":"如遇火灾，请使用房间后部的紧急出口。","extra":"反义词：entrance"},{"chapter":13,"key":"13:110","id":110,"word":"outside","phonetic":"/ˈaʊtsaɪd/","pos":"adj./n.","meaningCN":"外部的 n. 外表","tag":"核心","root":"","exampleEN":"The outside of the house needs a fresh coat of paint.","exampleCN":"房子的外部需要重新刷漆。","extra":"反义词：inside"},{"chapter":13,"key":"13:111","id":111,"word":"outward","phonetic":"/ˈaʊtwəd/","pos":"adj./adv.","meaningCN":"向外的 adv. 向外","tag":"核心","root":"","exampleEN":"The outward appearance of the building is modern, but the interior retains its original character.","exampleCN":"建筑的外观很现代，但内部保留了原有的特色。","extra":"反义词：inward"},{"chapter":13,"key":"13:112","id":112,"word":"exterior","phonetic":"/ɪkˈstɪəri/","pos":"n./adj.","meaningCN":"外部，外观 adj. 外部的","tag":"高频","root":"","exampleEN":"The exterior of the car was covered in dust after the long desert drive.","exampleCN":"长时间的沙漠行驶后，汽车的外壳布满了灰尘。","extra":"反义词：interior"},{"chapter":13,"key":"13:113","id":113,"word":"external","phonetic":"/ɪkˈstɜːnəl/","pos":"adj.","meaningCN":"外来的；外面的；对外的","tag":"核心","root":"","exampleEN":"The company hired an external consultant to review its business strategy.","exampleCN":"公司聘请了一位外部顾问来审查其商业战略。","extra":"反义词：internal"},{"chapter":13,"key":"13:114","id":114,"word":"inner","phonetic":"/ˈɪnə/","pos":"adj.","meaningCN":"内部的；内心的","tag":"核心","root":"","exampleEN":"Meditation helps her connect with her inner self and reduce stress.","exampleCN":"冥想帮助她与内在自我连接并减轻压力。","extra":"搭配：inner peace（内心的平静）"},{"chapter":13,"key":"13:115","id":115,"word":"interior","phonetic":"/ˈɪntrɪərɪə/","pos":"n./adj.","meaningCN":"内部 adj. 内部的","tag":"核心","root":"","exampleEN":"The interior of the church was decorated with beautiful frescoes.","exampleCN":"教堂的内部装饰着美丽的壁画。","extra":"搭配：interior design（室内设计）"},{"chapter":13,"key":"13:116","id":116,"word":"inward","phonetic":"/ˈɪnwəd/","pos":"adj./adv.","meaningCN":"向内的；内心的 adv. 向内","tag":"核心","root":"","exampleEN":"She took an inward breath before stepping onto the stage.","exampleCN":"她踏上舞台前向内深吸了一口气。","extra":"反义词：outward"},{"chapter":13,"key":"13:117","id":117,"word":"internal","phonetic":"/ɪnˈtɜːnl/","pos":"adj.","meaningCN":"内部的；自身的；国内的","tag":"核心","root":"","exampleEN":"The company is facing internal conflicts between the sales and marketing departments.","exampleCN":"公司正面临销售和市场部门之间的内部冲突。","extra":"反义词：external"},{"chapter":13,"key":"13:118","id":118,"word":"architecture","phonetic":"/ˈɑːkɪstektʃə/","pos":"n.","meaningCN":"建筑风格；建筑学","tag":"核心","root":"","exampleEN":"The architecture of the ancient Roman aqueducts still impresses modern engineers.","exampleCN":"古罗马渡槽的建筑风格至今仍令现代工程师赞叹。","extra":"派生词：architect（建筑师）"},{"chapter":13,"key":"13:119","id":119,"word":"erection","phonetic":"/ɪˈrekʃən/","pos":"n.","meaningCN":"建筑，建造","tag":"高频","root":"","exampleEN":"The erection of the new library was completed ahead of schedule.","exampleCN":"新图书馆的建造提前完工了。","extra":"动词：erect（建造；竖立）"},{"chapter":13,"key":"13:120","id":120,"word":"structure","phonetic":"/ˈstrʌktʃə/","pos":"n.","meaningCN":"建筑物；结构","tag":"核心","root":"struct（建立）","exampleEN":"The steel structure of the bridge can withstand strong earthquakes.","exampleCN":"这座桥的钢结构能够抵御强震。","extra":"形容词：structural"},{"chapter":13,"key":"13:121","id":121,"word":"construct","phonetic":"/kənˈstrʌkt/","pos":"v.","meaningCN":"建造","tag":"核心","root":"struct（建立）","exampleEN":"The company plans to construct 500 new houses in the area by next year.","exampleCN":"该公司计划明年之前在该地区建造500套新房。","extra":"名词：construction；形容词：constructive"},{"chapter":13,"key":"13:122","id":122,"word":"obstruct","phonetic":"/əbˈstrʌkt/","pos":"v.","meaningCN":"阻塞；妨碍","tag":"高频","root":"struct（建立）","exampleEN":"A parked car was obstructing the entrance to the garage.","exampleCN":"一辆停着的汽车阻塞了车库入口。","extra":"名词：obstruction；同义词：block"},{"chapter":13,"key":"13:123","id":123,"word":"establish","phonetic":"/ɪˈstæblɪʃ/","pos":"v.","meaningCN":"建立，设立","tag":"核心","root":"","exampleEN":"The university was established in 1885 and has a long history of academic excellence.","exampleCN":"这所大学成立于1885年，拥有悠久的学术卓越历史。","extra":"名词：establishment；形容词：established"},{"chapter":13,"key":"13:124","id":124,"word":"build","phonetic":"/bɪld/","pos":"v.","meaningCN":"建造；开发","tag":"核心","root":"","exampleEN":"They are building a new school in the neighborhood to accommodate more students.","exampleCN":"他们正在社区里建造一所新学校以容纳更多学生。","extra":"名词：building"},{"chapter":13,"key":"13:125","id":125,"word":"found","phonetic":"/faʊnd/","pos":"v.","meaningCN":"创建，创办","tag":"核心","root":"","exampleEN":"The city was founded by settlers from Europe over 300 years ago.","exampleCN":"这座城市是300多年前由欧洲定居者创建的。","extra":"名词：foundation（基础；基金会）；founder（创始人）"},{"chapter":13,"key":"13:126","id":126,"word":"concrete","phonetic":"/ˈkɒŋkrɪt/","pos":"n./adj.","meaningCN":"混凝土 adj. 具体的；混凝土制的","tag":"核心","root":"","exampleEN":"The workers poured concrete into the molds to create the foundation.","exampleCN":"工人们将混凝土倒入模具中以制作地基。","extra":"副词：concretely（具体地）"},{"chapter":13,"key":"13:127","id":127,"word":"steel","phonetic":"/stiːl/","pos":"n.","meaningCN":"钢铁","tag":"核心","root":"","exampleEN":"The skyscraper's frame is made of steel to ensure its strength and durability.","exampleCN":"摩天大楼的框架由钢铁制成，以确保其强度和耐久性。","extra":"形容词：steely（钢铁般的；强硬的）"},{"chapter":13,"key":"13:128","id":128,"word":"stability","phonetic":"/ˈstaɪblɪti/","pos":"n.","meaningCN":"稳定（性）","tag":"核心","root":"","exampleEN":"The bridge's stability depends on regular maintenance and inspections.","exampleCN":"桥梁的稳定性取决于定期维护和检查。","extra":"形容词：stable（稳定的）；反义词：instability"},{"chapter":13,"key":"13:129","id":129,"word":"site","phonetic":"/saɪt/","pos":"n.","meaningCN":"地点","tag":"核心","root":"","exampleEN":"The construction site was closed after the safety inspection failed.","exampleCN":"安全检查未通过后，施工现场被关闭了。","extra":"搭配：building site（建筑工地）"},{"chapter":13,"key":"13:130","id":130,"word":"venue","phonetic":"/ˈvenjuː/","pos":"n.","meaningCN":"发生地点，举行场所","tag":"核心","root":"","exampleEN":"The concert venue can hold up to 20,000 people.","exampleCN":"音乐会场地最多可容纳两万人。","extra":"常见搭配：wedding venue（婚礼场地）"},{"chapter":13,"key":"13:131","id":131,"word":"landmark","phonetic":"/ˈlændmɑːk/","pos":"n.","meaningCN":"地标；里程碑","tag":"核心","root":"","exampleEN":"The Eiffel Tower is one of the most famous landmarks in the world.","exampleCN":"埃菲尔铁塔是世界上最著名的地标之一。","extra":"搭配：a landmark in sth.（某事的里程碑）"},{"chapter":13,"key":"13:132","id":132,"word":"situated","phonetic":"/ˈsɪtʃuˌeɪtɪd/","pos":"adj.","meaningCN":"位于......的","tag":"核心","root":"","exampleEN":"The hotel is situated in a quiet street close to the city center.","exampleCN":"这家酒店位于靠近市中心的一条安静街道上。","extra":"动词：situate（位于；使处于）"}],"14":[{"chapter":14,"key":"14:1","id":1,"word":"navigate","phonetic":"/naveɪsɡeɪt/","pos":"v.","meaningCN":"航行；横渡","tag":"高频","root":"nav/nau = 船","exampleEN":"Sailors once used the stars to navigate across vast and empty oceans.","exampleCN":"水手们曾利用星星在浩瀚无人的大海上航行。","extra":"navigation n. 航行；navigator n. 领航员"},{"chapter":14,"key":"14:2","id":2,"word":"voyage","phonetic":"/vəɪ-ɪd3/","pos":"n.","meaningCN":"航海，航天；航行","tag":"高频","root":"","exampleEN":"The voyage across the Atlantic took the small ship nearly three weeks.","exampleCN":"横渡大西洋的航程花了这艘小船将近三周的时间。","extra":"\"Bon voyage!\" 来自法语，意为\"一路顺风！\""},{"chapter":14,"key":"14:3","id":3,"word":"aviation","phonetic":"/eɪviˈeɪʃən/","pos":"n.","meaningCN":"航空；航空学；航空工业","tag":"低频","root":"avi = 鸟 → aviation 航空","exampleEN":"Commercial aviation has made international travel accessible to millions of people.","exampleCN":"商业航空使得数百万人能够进行国际旅行。","extra":""},{"chapter":14,"key":"14:4","id":4,"word":"journey","phonetic":"/dʒ3sn/","pos":"n.","meaningCN":"旅行；历程","tag":"核心","root":"","exampleEN":"The journey from Beijing to Shanghai takes just over four hours by high-speed rail.","exampleCN":"从北京到上海的旅程乘坐高铁只需四个多小时。","extra":""},{"chapter":14,"key":"14:5","id":5,"word":"travel","phonetic":"/'traevəl/","pos":"n./v.","meaningCN":"旅行","tag":"核心","root":"","exampleEN":"She plans to travel around Southeast Asia after graduation.","exampleCN":"她计划毕业后环游东南亚。","extra":"搭配：travel abroad 出国旅行"},{"chapter":14,"key":"14:6","id":6,"word":"safari","phonetic":"/sa'færi/","pos":"n.","meaningCN":"（尤指在东非的）观兽旅行","tag":"低频","root":"","exampleEN":"During their safari in Kenya, they saw lions, elephants and giraffes up close.","exampleCN":"在肯尼亚的观兽旅行中，他们近距离看到了狮子、大象和长颈鹿。","extra":"搭配：be/go on safari 进行观兽旅行"},{"chapter":14,"key":"14:7","id":7,"word":"parade","phonetic":"/pə'reid/","pos":"v.","meaningCN":"游行；炫耀 n. 庆祝游行；列队行进；炫耀","tag":"高频","root":"","exampleEN":"Thousands of people lined the streets to watch the Spring Festival parade.","exampleCN":"成千上万的人站在街道两旁观看春节庆祝游行。","extra":""},{"chapter":14,"key":"14:8","id":8,"word":"haunt","phonetic":"/hənt/","pos":"v.","meaningCN":"（鬼魂等）常出没于 n. 常去的地方","tag":"低频","root":"","exampleEN":"According to local legend, the spirit of an old sailor still haunts that lighthouse.","exampleCN":"根据当地传说，一名老水手的鬼魂仍时常出没于那座灯塔。","extra":"搭配：a haunted house 鬼屋"},{"chapter":14,"key":"14:9","id":9,"word":"attraction","phonetic":"/a'trækʃən/","pos":"n.","meaningCN":"吸引；具有吸引力的事物","tag":"核心","root":"","exampleEN":"The Great Wall is one of the most popular tourist attractions in the world.","exampleCN":"长城是世界上最受欢迎的旅游景点之一。","extra":"attractive adj. 吸引人的"},{"chapter":14,"key":"14:10","id":10,"word":"memorial","phonetic":"/mə'sɪməriəl/","pos":"n.","meaningCN":"纪念碑 adj. 纪念的，悼念的","tag":"高频","root":"","exampleEN":"The stone memorial was built to honour the soldiers who lost their lives in the war.","exampleCN":"这座石碑是为纪念在战争中牺牲的士兵而建。","extra":"memory n. 记忆；commemorate v. 纪念"},{"chapter":14,"key":"14:11","id":11,"word":"pyramid","phonetic":"/'pɪrəmd/","pos":"n.","meaningCN":"金字塔；棱锥体","tag":"核心","root":"","exampleEN":"The ancient pyramids of Egypt continue to amaze scientists and tourists alike.","exampleCN":"古埃及金字塔至今仍同样令科学家和游客惊叹。","extra":"pharaoh n. 法老；mummy n. 木乃伊"},{"chapter":14,"key":"14:12","id":12,"word":"port","phonetic":"/pɔ:t/","pos":"n.","meaningCN":"港口；左舷","tag":"核心","root":"","exampleEN":"The fishing boats return to the port every evening at sunset.","exampleCN":"渔船每天傍晚日落时返回港口。","extra":"porter, import, export, seaport, airport, transport, report, passport"},{"chapter":14,"key":"14:13","id":13,"word":"visa","phonetic":"/vi:za/","pos":"n.","meaningCN":"签证","tag":"核心","root":"vis = 看见","exampleEN":"You must apply for a visa at least one month before travelling to that country.","exampleCN":"你必须至少在前往该国前一个月申请签证。","extra":""},{"chapter":14,"key":"14:14","id":14,"word":"traffic","phonetic":"/traefik/","pos":"n.","meaningCN":"交通，车流","tag":"核心","root":"","exampleEN":"Heavy traffic in the city centre can double the usual travel time.","exampleCN":"市中心的繁忙交通可能使路上耗时比平时多出一倍。","extra":"traffic regulations 交通规则；a traffic jam 交通堵塞"},{"chapter":14,"key":"14:15","id":15,"word":"airline","phonetic":"/ealm/","pos":"n.","meaningCN":"航空公司","tag":"核心","root":"","exampleEN":"Several major airlines now offer direct flights from London to that island.","exampleCN":"现在好几家主要航空公司都提供从伦敦直飞那个岛屿的航班。","extra":""},{"chapter":14,"key":"14:16","id":16,"word":"airplane","phonetic":"/eaplem/","pos":"n.","meaningCN":"飞机","tag":"核心","root":"","exampleEN":"The airplane climbed smoothly through the low clouds and into the bright sunlight.","exampleCN":"飞机平稳地爬升穿过低云，进入明亮的阳光之中。","extra":"aeroplane n. 飞机；aircraft n. 飞机"},{"chapter":14,"key":"14:17","id":17,"word":"helicopter","phonetic":"/helkopt/","pos":"n.","meaningCN":"直升机 v. 用直升机载送；乘直升机旅行","tag":"高频","root":"","exampleEN":"A rescue helicopter arrived quickly and lifted the injured hiker to safety.","exampleCN":"一架救援直升机迅速赶到，把受伤的徒步者空运至安全地带。","extra":""},{"chapter":14,"key":"14:18","id":18,"word":"jet","phonetic":"/d3et/","pos":"n.","meaningCN":"喷气式飞机；喷射口","tag":"高频","root":"","exampleEN":"The private jet landed smoothly on the small runway near the resort.","exampleCN":"那架私人喷气式飞机在度假村附近的小跑道上平稳着陆。","extra":""},{"chapter":14,"key":"14:19","id":19,"word":"parachute","phonetic":"/parajut/","pos":"n.","meaningCN":"降落伞","tag":"低频","root":"","exampleEN":"Before the jump, the instructor carefully checked each skydiver's parachute.","exampleCN":"跳伞前，教练仔细检查了每位跳伞者的降落伞。","extra":""},{"chapter":14,"key":"14:20","id":20,"word":"flight","phonetic":"/flat/","pos":"n.","meaningCN":"飞行；航班","tag":"核心","root":"","exampleEN":"Due to the heavy snow, all flights out of the city were cancelled.","exampleCN":"由于大雪，所有离开该市的航班都取消了。","extra":""},{"chapter":14,"key":"14:21","id":21,"word":"pilot","phonetic":"/paiot/","pos":"n.","meaningCN":"飞行员","tag":"核心","root":"","exampleEN":"The pilot made an announcement that we would be landing in about twenty minutes.","exampleCN":"飞行员广播通知我们大约二十分钟后着陆。","extra":""},{"chapter":14,"key":"14:22","id":22,"word":"passenger","phonetic":"/pasind3/","pos":"n.","meaningCN":"乘客","tag":"核心","root":"","exampleEN":"All passengers are required to fasten their seat belts during take-off and landing.","exampleCN":"所有乘客在起飞和降落期间都必须系好安全带。","extra":""},{"chapter":14,"key":"14:23","id":23,"word":"baggage","phonetic":"/baqid3/","pos":"n.","meaningCN":"[尤美]行李","tag":"核心","root":"","exampleEN":"We waited by the carousel for our baggage to come out after the long flight.","exampleCN":"长途飞行后，我们在行李传送带旁等待行李出来。","extra":"搭配：check in one's baggage 托运某人的行李"},{"chapter":14,"key":"14:24","id":24,"word":"luggage","phonetic":"/lAgid3/","pos":"n.","meaningCN":"行李","tag":"核心","root":"","exampleEN":"His luggage was so heavy that he could hardly lift it onto the train.","exampleCN":"他的行李太重了，几乎提不上火车。","extra":""},{"chapter":14,"key":"14:25","id":25,"word":"suitcase","phonetic":"/sutkes/","pos":"n.","meaningCN":"手提箱","tag":"核心","root":"","exampleEN":"She packed all her summer clothes into a colourful suitcase and headed to the airport.","exampleCN":"她把所有夏装都塞进一个彩色手提箱，然后赶往机场。","extra":""},{"chapter":14,"key":"14:26","id":26,"word":"carry-on","phonetic":"/'kæri pn/","pos":"n.","meaningCN":"[美]（可随身携带上飞机的）小包 adj. 随身携带上飞机的","tag":"高频","root":"","exampleEN":"I only travel with a carry-on so I don't have to wait for checked luggage.","exampleCN":"我只带一件随身行李旅行，这样就不用等托运行李了。","extra":"carry v. 携带"},{"chapter":14,"key":"14:27","id":27,"word":"itinerary","phonetic":"/a'itnari/","pos":"n.","meaningCN":"行程，路线","tag":"高频","root":"","exampleEN":"The travel agency sent us a detailed itinerary for the week-long tour.","exampleCN":"旅行社给我们发了一份为期一周的详细行程单。","extra":""},{"chapter":14,"key":"14:28","id":28,"word":"rack","phonetic":"/ræk/","pos":"n.","meaningCN":"搁物架，挂物架","tag":"高频","root":"","exampleEN":"He put his backpack on the overhead luggage rack and took his seat by the window.","exampleCN":"他把背包放在头顶的行李架上，然后坐到了靠窗的座位上。","extra":""},{"chapter":14,"key":"14:29","id":29,"word":"freight","phonetic":"/freit/","pos":"n.","meaningCN":"货运；货物 v. 运送（货物）","tag":"高频","root":"","exampleEN":"Most of the fresh fruit is sent to Europe by air freight to keep it from spoiling.","exampleCN":"大部分新鲜水果都通过空运发往欧洲，以免变质。","extra":"freighter n. 货船，运输飞机"},{"chapter":14,"key":"14:30","id":30,"word":"fare","phonetic":"/fea/","pos":"n.","meaningCN":"车费，路费","tag":"核心","root":"","exampleEN":"Public transport fares in the city went up by 10% this year.","exampleCN":"今年该市的公共交通票价上涨了10%。","extra":""},{"chapter":14,"key":"14:31","id":31,"word":"passage","phonetic":"/pasid3/","pos":"n.","meaningCN":"通过；通道，走廊","tag":"高频","root":"","exampleEN":"The narrow passage between the buildings led us to a tiny hidden square.","exampleCN":"楼房之间那条狭窄的通道把我们引向一个隐蔽的小广场。","extra":"搭配：block passage of information 封锁消息"},{"chapter":14,"key":"14:32","id":32,"word":"intersection","phonetic":"/int'sekf/","pos":"n.","meaningCN":"十字路口，交叉路口","tag":"高频","root":"","exampleEN":"You will see the bank on your left just before the busy intersection.","exampleCN":"在繁忙的十字路口之前，你会看到银行就在左手边。","extra":""},{"chapter":14,"key":"14:33","id":33,"word":"cross","phonetic":"/kros/","pos":"n.","meaningCN":"十字形；十字架 v. 穿过","tag":"核心","root":"","exampleEN":"It's safer to cross the road at the pedestrian crossing near the traffic lights.","exampleCN":"在交通灯附近的人行横道过马路更安全。","extra":""},{"chapter":14,"key":"14:34","id":34,"word":"atlas","phonetic":"/'ætlas/","pos":"n.","meaningCN":"地图册，地图集","tag":"低频","root":"","exampleEN":"She bought a world atlas to help her children learn the names of different countries.","exampleCN":"她买了一本世界地图册，帮助孩子们学习各个国家的名称。","extra":"Atlas 是希腊神话中的提坦巨人，后用于指地图册。"},{"chapter":14,"key":"14:35","id":35,"word":"way","phonetic":"/we/","pos":"n.","meaningCN":"路；方式","tag":"核心","root":"","exampleEN":"Can you tell me the quickest way to get to the railway station from here?","exampleCN":"你能告诉我从这儿去火车站最快的路吗？","extra":"搭配：on one's way to 在某人去……的路上"},{"chapter":14,"key":"14:36","id":36,"word":"path","phonetic":"/pa:0/","pos":"n.","meaningCN":"小路","tag":"核心","root":"","exampleEN":"A narrow path led through the woods to a small, calm lake.","exampleCN":"一条狭窄的小路穿过树林通向一个小而平静的湖泊。","extra":""},{"chapter":14,"key":"14:37","id":37,"word":"route","phonetic":"/ru:t/","pos":"n.","meaningCN":"路线","tag":"核心","root":"","exampleEN":"The coastal route takes longer, but the views are absolutely worth it.","exampleCN":"沿海路线耗时更长，但沿途的风景绝对值得。","extra":""},{"chapter":14,"key":"14:38","id":38,"word":"lane","phonetic":"/len/","pos":"n.","meaningCN":"小巷；车道","tag":"核心","root":"","exampleEN":"Cycling is safer when there is a separate cycle lane on busy roads.","exampleCN":"繁忙的马路如果有单独的自行车道，骑车会更安全。","extra":""},{"chapter":14,"key":"14:39","id":39,"word":"avenue","phonetic":"/'av3nju/","pos":"n.","meaningCN":"大街；途径","tag":"高频","root":"ven = 来","exampleEN":"The wide avenue is lined with tall palm trees on both sides.","exampleCN":"宽阔的大街两旁种着高大的棕榈树。","extra":""},{"chapter":14,"key":"14:40","id":40,"word":"highway","phonetic":"/haivw/","pos":"n.","meaningCN":"[尤美]公路","tag":"核心","root":"","exampleEN":"A new highway has been built to connect the two major cities more directly.","exampleCN":"一条新的公路已经建成，把这两座主要城市更直接地连接起来。","extra":""},{"chapter":14,"key":"14:41","id":41,"word":"curb","phonetic":"/k3b/","pos":"n.","meaningCN":"路缘；起控制作用的事物","tag":"低频","root":"","exampleEN":"She stepped off the curb just as a bus passed by, which gave her a real fright.","exampleCN":"她走下路缘时刚好一辆公交车经过，把她吓了一大跳。","extra":""},{"chapter":14,"key":"14:42","id":42,"word":"signpost","phonetic":"/sainpoust/","pos":"n.","meaningCN":"路标","tag":"低频","root":"","exampleEN":"The signpost at the crossroads pointed to the village that was five miles away.","exampleCN":"十字路口的路标指向五英里外的村庄。","extra":""},{"chapter":14,"key":"14:43","id":43,"word":"pave","phonetic":"/perv/","pos":"v.","meaningCN":"铺（路或地面）","tag":"高频","root":"","exampleEN":"The road was paved with smooth stones, making it pleasant to walk on.","exampleCN":"这条路用光滑的石头铺成，走在上面很舒服。","extra":"pavement n.（硬化）路面"},{"chapter":14,"key":"14:44","id":44,"word":"vehicle","phonetic":"/vi:kl/","pos":"n.","meaningCN":"车辆，交通工具；工具，手段","tag":"核心","root":"","exampleEN":"Electric vehicles are becoming more common on the streets of large cities.","exampleCN":"在大城市的街道上，电动汽车正变得越来越常见。","extra":"搭配：load a vehicle 把东西装入车中"},{"chapter":14,"key":"14:45","id":45,"word":"auto","phonetic":"/a:to/","pos":"n.","meaningCN":"汽车","tag":"核心","root":"","exampleEN":"The auto industry is investing heavily in battery technology and self-driving cars.","exampleCN":"汽车工业正在电池技术和自动驾驶汽车上大量投资。","extra":"automobile n. 汽车"},{"chapter":14,"key":"14:46","id":46,"word":"express","phonetic":"/ik'spres/","pos":"n.","meaningCN":"特快列车；快递服务 v. 表示 adj. 特快的","tag":"核心","root":"","exampleEN":"We took the airport express train and arrived in the centre within thirty minutes.","exampleCN":"我们乘坐机场特快列车，不到三十分钟就到了市中心。","extra":"搭配：express mail 特快邮件"},{"chapter":14,"key":"14:47","id":47,"word":"tram","phonetic":"/tram/","pos":"n.","meaningCN":"[尤英]有轨电车","tag":"低频","root":"","exampleEN":"The old-fashioned tram moves slowly through the historic streets of the city centre.","exampleCN":"那辆老式有轨电车缓慢地穿过市中心历史悠久的街道。","extra":""},{"chapter":14,"key":"14:48","id":48,"word":"coach","phonetic":"/kaut/","pos":"n.","meaningCN":"[英]长途汽车；教练；[英]私人教师 v. 训练","tag":"核心","root":"","exampleEN":"The overnight coach from Edinburgh to London takes around nine hours.","exampleCN":"从爱丁堡到伦敦的夜间长途汽车大约需要九个小时。","extra":""},{"chapter":14,"key":"14:49","id":49,"word":"ambulance","phonetic":"/ambjslans/","pos":"n.","meaningCN":"救护车","tag":"核心","root":"","exampleEN":"The ambulance arrived within minutes and rushed the injured man to hospital.","exampleCN":"救护车几分钟内就到了，把受伤的男子紧急送往医院。","extra":""},{"chapter":14,"key":"14:50","id":50,"word":"truck","phonetic":"/trA/","pos":"n.","meaningCN":"卡车；散篷货运火车","tag":"核心","root":"","exampleEN":"A huge truck carrying fresh vegetables overturned on the icy road.","exampleCN":"一辆运载新鲜蔬菜的大卡车在结冰的道路上翻倒了。","extra":""},{"chapter":14,"key":"14:51","id":51,"word":"lorry","phonetic":"/lori/","pos":"n.","meaningCN":"[英]卡车","tag":"核心","root":"","exampleEN":"The old stone bridge cannot support the weight of a heavy lorry.","exampleCN":"那座古老的石桥承受不住重型卡车的重量。","extra":""},{"chapter":14,"key":"14:52","id":52,"word":"van","phonetic":"/van/","pos":"n.","meaningCN":"厢式货车；客货车","tag":"高频","root":"","exampleEN":"He rented a van to move all the furniture to his new flat.","exampleCN":"他租了一辆厢式货车，把所有家具搬到了新公寓。","extra":""},{"chapter":14,"key":"14:53","id":53,"word":"wagon","phonetic":"/wagon/","pos":"n.","meaningCN":"四轮运货马车（或牛车）；[英]（火车的）货车车厢","tag":"低频","root":"","exampleEN":"The children laughed as the farmer gave them a ride on his hay wagon.","exampleCN":"农夫让这些孩子搭他的运草车，孩子们哈哈大笑。","extra":""},{"chapter":14,"key":"14:54","id":54,"word":"carriage","phonetic":"/karrds/","pos":"n.","meaningCN":"四轮马车；[英]（客运火车的）车厢","tag":"低频","root":"","exampleEN":"In the old days, people travelled across the country in a horse-drawn carriage.","exampleCN":"从前，人们乘坐马车在全国各地旅行。","extra":""},{"chapter":14,"key":"14:55","id":55,"word":"tractor","phonetic":"/'traektə/","pos":"n.","meaningCN":"拖拉机；牵引车","tag":"高频","root":"","exampleEN":"Modern tractors are equipped with GPS to help farmers plant crops more efficiently.","exampleCN":"现代拖拉机装上了GPS，帮助农民更高效地种植庄稼。","extra":""},{"chapter":14,"key":"14:56","id":56,"word":"cart","phonetic":"/kAt/","pos":"n.","meaningCN":"运货马车；[美]（超市等提供的）手推车，购物车","tag":"高频","root":"","exampleEN":"She pushed a shopping cart through the supermarket, picking up fresh vegetables and bread.","exampleCN":"她推着购物车穿过超市，挑选新鲜蔬菜和面包。","extra":""},{"chapter":14,"key":"14:57","id":57,"word":"pedicab","phonetic":"/pedikab/","pos":"n.","meaningCN":"（人力）三轮车","tag":"识记","root":"","exampleEN":"In some tourist areas, you can hire a pedicab for a relaxed ride around the old town.","exampleCN":"在一些旅游区，你可以租一辆三轮车，悠闲地逛一逛老城区。","extra":""},{"chapter":14,"key":"14:58","id":58,"word":"cycle","phonetic":"/sakəl/","pos":"v.","meaningCN":"骑（自行车）n. 周期；自行车","tag":"核心","root":"cycl = 圆、轮","exampleEN":"Many city residents choose to cycle to work instead of driving.","exampleCN":"许多城市居民选择骑自行车上班而不是开车。","extra":"cyclist n. 骑自行车的人；recycle v. 回收利用"},{"chapter":14,"key":"14:59","id":59,"word":"garage","phonetic":"/'gæridʒ/","pos":"n.","meaningCN":"汽车修理厂；车库","tag":"核心","root":"","exampleEN":"The car started making strange noises, so we took it to the nearest garage.","exampleCN":"那辆车开始发出奇怪的声音，于是我们把它送到了最近的修理厂。","extra":""},{"chapter":14,"key":"14:60","id":60,"word":"motor","phonetic":"/'məutə/","pos":"n.","meaningCN":"发动机 adj. 机动的","tag":"核心","root":"mov/mob/mot = 移动","exampleEN":"The electric motor is much quieter than a traditional petrol engine.","exampleCN":"电动机比传统的汽油发动机安静得多。","extra":"motorist n. 汽车驾驶人；motor vehicles 机动车辆"},{"chapter":14,"key":"14:61","id":61,"word":"horsepower","phonetic":"/'hɔ:s,pauə/","pos":"n.","meaningCN":"马力","tag":"高频","root":"","exampleEN":"The new sports car has a powerful engine with over 400 horsepower.","exampleCN":"这辆新跑车配有超过400马力的强大引擎。","extra":""},{"chapter":14,"key":"14:62","id":62,"word":"wheel","phonetic":"/wi:l/","pos":"n.","meaningCN":"方向盘；车轮","tag":"核心","root":"","exampleEN":"He gripped the steering wheel tightly as the car approached the sharp bend.","exampleCN":"汽车驶近急弯时，他紧紧握住方向盘。","extra":""},{"chapter":14,"key":"14:63","id":63,"word":"brake","phonetic":"/bri:k/","pos":"n.","meaningCN":"车间；刹车 v. 刹车","tag":"核心","root":"","exampleEN":"The driver pressed the brake suddenly when a dog ran into the road.","exampleCN":"一只狗冲上马路时，司机突然踩下了刹车。","extra":""},{"chapter":14,"key":"14:64","id":64,"word":"tyre","phonetic":"/taiə/","pos":"n.","meaningCN":"轮胎","tag":"核心","root":"","exampleEN":"He had to change the front tyre after it went flat on the rough mountain road.","exampleCN":"在崎岖的山路上前轮瘪了之后，他不得不更换轮胎。","extra":"也作 tire"},{"chapter":14,"key":"14:65","id":65,"word":"honk","phonetic":"/hɔŋk/","pos":"n.","meaningCN":"汽车喇叭声；鹅叫声 v. 按（汽车喇叭）","tag":"高频","root":"","exampleEN":"The taxi driver behind us started to honk impatiently when the light turned green.","exampleCN":"绿灯亮起时，我们后面的出租车司机开始不耐烦地按喇叭。","extra":""},{"chapter":14,"key":"14:66","id":66,"word":"crew","phonetic":"/kru:/","pos":"n.","meaningCN":"（轮船、飞机等上的）全体工作人员；（有专门技术的）一组工作人员","tag":"核心","root":"","exampleEN":"The cabin crew served drinks and snacks shortly after the plane took off.","exampleCN":"飞机起飞后不久，客舱乘务员就送上了饮料和小吃。","extra":"搭配：a film crew 电影摄制组"},{"chapter":14,"key":"14:67","id":67,"word":"captain","phonetic":"/ˈkæptʃən/","pos":"n.","meaningCN":"船长；队长","tag":"核心","root":"","exampleEN":"The captain gave clear orders to the crew before the ship departed.","exampleCN":"船长在船出发前向船员下达了清晰的命令。","extra":"联想：cap（帽子）+ tain（领头人）"},{"chapter":14,"key":"14:68","id":68,"word":"steward","phonetic":"/ˈstiːwəd/","pos":"n.","meaningCN":"男乘务员；管家","tag":"高频","root":"","exampleEN":"The steward helped passengers find their seats and store their luggage.","exampleCN":"乘务员帮助乘客找到座位并存放行李。","extra":"对应词：stewardess（女乘务员）"},{"chapter":14,"key":"14:69","id":69,"word":"emergency","phonetic":"/ɪˈmɜːdʒənsɪ/","pos":"n.","meaningCN":"紧急事件 adj. 应急的","tag":"核心","root":"","exampleEN":"In an emergency, call the police or fire department immediately.","exampleCN":"遇到紧急情况时，请立即报警或呼叫消防部门。","extra":"搭配：emergency exit（紧急出口）"},{"chapter":14,"key":"14:70","id":70,"word":"wreck","phonetic":"/rek/","pos":"v./n.","meaningCN":"使失事；破坏 n. 失事的船只（或汽车、飞机等）；残破的东西","tag":"高频","root":"","exampleEN":"The storm wrecked several boats along the rocky coastline.","exampleCN":"暴风雨使岩石海岸线上的几艘船失事。","extra":"名词：wreckage（残骸）"},{"chapter":14,"key":"14:71","id":71,"word":"crash","phonetic":"/kræʃ/","pos":"v.","meaningCN":"撞击；崩溃；破产","tag":"核心","root":"","exampleEN":"The driver lost control and the car crashed into a tree.","exampleCN":"司机失去控制，汽车撞到了一棵树上。","extra":"搭配：car crash（车祸）；stock market crash（股市崩盘）"},{"chapter":14,"key":"14:72","id":72,"word":"crush","phonetic":"/krʌʃ/","pos":"v./n.","meaningCN":"压碎，压坏 n. 拥挤的人群；迷恋；迷恋对象","tag":"核心","root":"","exampleEN":"The machine crushes rocks into small pieces for road construction.","exampleCN":"这台机器把岩石压碎成小块用于道路建设。","extra":"表达迷恋：have a crush on sb.（迷恋某人）"},{"chapter":14,"key":"14:73","id":73,"word":"dash","phonetic":"/dæʃ/","pos":"v.","meaningCN":"猛冲；猛摔","tag":"高频","root":"","exampleEN":"She dashed across the street to catch the bus before it left.","exampleCN":"她猛冲过马路，赶在公交车离开前上车。","extra":"名词：dash（破折号；短跑）"},{"chapter":14,"key":"14:74","id":74,"word":"vanish","phonetic":"/ˈvænɪʃ/","pos":"v.","meaningCN":"突然消失；绝迹","tag":"高频","root":"","exampleEN":"The magician made the rabbit vanish from the hat in seconds.","exampleCN":"魔术师让兔子在几秒钟内从帽子里消失了。","extra":"同义词：disappear；习语：vanish into thin air（消失得无影无踪）"},{"chapter":14,"key":"14:75","id":75,"word":"disappear","phonetic":"/ˌdɪsəˈpɪə/","pos":"v.","meaningCN":"失踪；消失","tag":"核心","root":"","exampleEN":"The sun disappeared behind the clouds, and it started to rain.","exampleCN":"太阳消失在云层后面，开始下雨了。","extra":"反义词：appear；搭配：disappear from"},{"chapter":14,"key":"14:76","id":76,"word":"hazard","phonetic":"/ˈhæzəd/","pos":"n./v.","meaningCN":"危险 v. 使冒风险","tag":"核心","root":"","exampleEN":"Fog is a serious hazard for drivers on mountain roads.","exampleCN":"雾对在山路上行驶的司机来说是一个严重的危险。","extra":"形容词：hazardous；搭配：at all hazards（不顾一切地）"},{"chapter":14,"key":"14:77","id":77,"word":"alibi","phonetic":"","pos":"n.","meaningCN":"（法律上的）不在犯罪现场的证明，借口","tag":"低频","root":"","exampleEN":"The suspect had a strong alibi, as witnesses saw him in another city at the time.","exampleCN":"嫌疑人有强有力的不在场证明，当时有目击者看到他在另一个城市。","extra":"常见于法律语境"},{"chapter":14,"key":"14:78","id":78,"word":"wreck","phonetic":"/rek/","pos":"v./n.","meaningCN":"使失事；破坏 n. 失事的船只（或汽车、飞机等）；残破的东西","tag":"高频","root":"","exampleEN":"The old house became a wreck after years of neglect.","exampleCN":"老房子年久失修，成了一片废墟。","extra":"注意与前一条目重复"},{"chapter":14,"key":"14:79","id":79,"word":"crash","phonetic":"/kræʃ/","pos":"v.","meaningCN":"撞击；崩溃；破产","tag":"核心","root":"","exampleEN":"My computer crashed in the middle of saving my important file.","exampleCN":"我的电脑在保存重要文件的中途崩溃了。","extra":"计算机术语：系统崩溃"},{"chapter":14,"key":"14:80","id":80,"word":"crush","phonetic":"/krʌʃ/","pos":"v./n.","meaningCN":"压碎，压坏 n. 拥挤的人群；迷恋；迷恋对象","tag":"核心","root":"","exampleEN":"She had a secret crush on her classmate for two years.","exampleCN":"她暗恋她的同学两年了。","extra":"名词 crush 常用于青少年语境"},{"chapter":14,"key":"14:81","id":81,"word":"anchor","phonetic":"/ˈæŋkər/","pos":"n.","meaningCN":"锚","tag":"高频","root":"","exampleEN":"The sailors dropped the anchor to stop the boat near the shore.","exampleCN":"水手们抛锚，让船停靠在岸边附近。","extra":"动词：anchor（抛锚；使固定）"},{"chapter":14,"key":"14:82","id":82,"word":"submerge","phonetic":"/səb'mə:d3/","pos":"v.","meaningCN":"（使）浸没；掩盖","tag":"高频","root":"","exampleEN":"The heavy rain caused the river to rise and submerge several low-lying roads.","exampleCN":"大雨使河水上涨，淹没了若干低洼路段。","extra":""},{"chapter":14,"key":"14:83","id":83,"word":"sailor","phonetic":"/'seilə/","pos":"n.","meaningCN":"海员，水手","tag":"核心","root":"","exampleEN":"My grandfather was a sailor who crossed the Pacific many times during his career.","exampleCN":"我祖父是一名水手，他的职业生涯中多次横渡太平洋。","extra":""},{"chapter":14,"key":"14:84","id":84,"word":"seaman","phonetic":"/'si:man/","pos":"n.","meaningCN":"海员，水手","tag":"高频","root":"","exampleEN":"The rescue boat was operated by a group of experienced seamen who knew the coast well.","exampleCN":"那艘救援艇由一群经验丰富、熟悉海岸的海员操作。","extra":""},{"chapter":14,"key":"14:85","id":85,"word":"carrier","phonetic":"/'kæriə/","pos":"n.","meaningCN":"航空母舰；运输工具","tag":"低频","root":"","exampleEN":"An aircraft carrier can launch dozens of planes at sea within a short time.","exampleCN":"一艘航空母舰可以在短时间内从海上起飞几十架飞机。","extra":""},{"chapter":14,"key":"14:86","id":86,"word":"steamer","phonetic":"/'sti:ma/","pos":"n.","meaningCN":"汽船，轮船","tag":"低频","root":"","exampleEN":"In the 19th century, steamers carried both goods and passengers across the oceans.","exampleCN":"19世纪，蒸汽轮船载着货物和乘客穿越大洋。","extra":""},{"chapter":14,"key":"14:87","id":87,"word":"liner","phonetic":"/'lana/","pos":"n.","meaningCN":"邮轮，客轮","tag":"高频","root":"","exampleEN":"The luxury liner can accommodate over 3,000 passengers on a single trip.","exampleCN":"这艘豪华邮轮一次可容纳3000多名乘客。","extra":""},{"chapter":14,"key":"14:88","id":88,"word":"vessel","phonetic":"/'vesəl/","pos":"n.","meaningCN":"大船，舰；容器，器皿","tag":"核心","root":"","exampleEN":"The coast guard sent out several vessels to search for the missing fishing boat.","exampleCN":"海岸警卫队派出多艘船只搜寻失踪的渔船。","extra":""},{"chapter":14,"key":"14:89","id":89,"word":"ferry","phonetic":"/'feri/","pos":"n.","meaningCN":"渡船 v. 渡运","tag":"核心","root":"","exampleEN":"The ferry takes about an hour to cross from the island back to the mainland.","exampleCN":"乘坐渡船从那个岛回到大陆大约需要一个小时。","extra":"搭配：a steam ferry 蒸汽渡船"},{"chapter":14,"key":"14:90","id":90,"word":"sail","phonetic":"/'sel/","pos":"v.","meaningCN":"航行；驾驶（帆船）","tag":"核心","root":"","exampleEN":"They plan to sail around the island on their own small yacht this summer.","exampleCN":"他们计划今年夏天驾着自己的小帆船环岛航行。","extra":""},{"chapter":14,"key":"14:91","id":91,"word":"raft","phonetic":"/ra:ft/","pos":"n.","meaningCN":"木筏，木排","tag":"低频","root":"","exampleEN":"The children built a small raft from branches and floated it on the pond.","exampleCN":"孩子们用树枝做了一个小木筏，放在池塘里让它漂。","extra":""},{"chapter":14,"key":"14:92","id":92,"word":"canoe","phonetic":"/'ka'nue/","pos":"n.","meaningCN":"独木舟","tag":"低频","root":"","exampleEN":"They paddled the canoe slowly across the misty lake at dawn.","exampleCN":"黎明时分，他们划着独木舟缓缓地穿过雾气弥漫的湖面。","extra":""},{"chapter":14,"key":"14:93","id":93,"word":"oar","phonetic":"/o:/","pos":"n.","meaningCN":"桨 v. 用桨划（船）","tag":"低频","root":"","exampleEN":"If we all pull the oars together, the boat moves faster and straighter.","exampleCN":"如果我们一起划桨，船会走得更快更直。","extra":""},{"chapter":14,"key":"14:94","id":94,"word":"deck","phonetic":"/dek/","pos":"n.","meaningCN":"甲板 v. 装饰","tag":"核心","root":"","exampleEN":"We stood on the deck and watched the sun sink slowly below the horizon.","exampleCN":"我们站在甲板上，望着太阳慢慢沉入地平线以下。","extra":"搭配：deck sth. out 装饰某处"},{"chapter":14,"key":"14:95","id":95,"word":"turbine","phonetic":"/'t3:ban/","pos":"n.","meaningCN":"涡轮机","tag":"低频","root":"","exampleEN":"Wind turbines are an important source of renewable energy in many countries.","exampleCN":"风力涡轮机在许多国家是可再生能源的重要来源。","extra":""},{"chapter":14,"key":"14:96","id":96,"word":"propeller","phonetic":"/pro'pelə/","pos":"n.","meaningCN":"螺旋桨，推进器","tag":"低频","root":"","exampleEN":"The sound of the propeller grew louder as the small plane prepared for take-off.","exampleCN":"随着小飞机准备起飞，螺旋桨的声音越来越响。","extra":""},{"chapter":14,"key":"14:97","id":97,"word":"stern","phonetic":"/st3n/","pos":"n.","meaningCN":"船尾","tag":"低频","root":"","exampleEN":"He stood at the stern of the boat and watched the island get smaller in the distance.","exampleCN":"他站在船尾，看着那个海岛在远处越变越小。","extra":"bow n. 船头 v. 鞠躬"},{"chapter":14,"key":"14:98","id":98,"word":"aboard","phonetic":"/a'bad/","pos":"adv.","meaningCN":"在（船、飞机等）上","tag":"高频","root":"","exampleEN":"Once all passengers were aboard, the bus driver closed the door and drove off.","exampleCN":"所有乘客上车后，公交车司机关上门开走了。","extra":""},{"chapter":14,"key":"14:99","id":99,"word":"embark","phonetic":"/'m'ba:k/","pos":"v.","meaningCN":"上船（或飞机等）；开始做","tag":"高频","root":"","exampleEN":"They are about to embark on a challenging journey through the mountains.","exampleCN":"他们即将开始一段穿越山区的艰难旅程。","extra":"board 木板 → aboard 在船上；bark 树皮 → embark 上船"},{"chapter":14,"key":"14:100","id":100,"word":"channel","phonetic":"/'tʃæn/","pos":"n.","meaningCN":"航道；电视频道；海峡","tag":"核心","root":"","exampleEN":"The English Channel separates the United Kingdom from the rest of Europe.","exampleCN":"英吉利海峡将英国与欧洲其他地区分隔开来。","extra":""},{"chapter":14,"key":"14:101","id":101,"word":"canal","phonetic":"/kən'neɪl/","pos":"n.","meaningCN":"运河；（人体内输送食物、空气等的）管","tag":"高频","root":"","exampleEN":"The Panama Canal provides a vital shortcut for ships between the two oceans.","exampleCN":"巴拿马运河为船只提供了横跨两大洋的重要捷径。","extra":""},{"chapter":14,"key":"14:102","id":102,"word":"ditch","phonetic":"/dɪtʃ/","pos":"n.","meaningCN":"沟，渠 v. 抛弃","tag":"低频","root":"","exampleEN":"He fell into a muddy ditch while walking along the dark country road.","exampleCN":"他在漆黑的乡间小路上行走时掉进了一条泥泞的水沟里。","extra":""},{"chapter":14,"key":"14:103","id":103,"word":"railroad","phonetic":"/'reɪlɪəʊd/","pos":"n.","meaningCN":"[美]铁路，铁路公司","tag":"核心","root":"","exampleEN":"The transcontinental railroad played a key role in the development of the American West.","exampleCN":"横贯大陆的铁路在美国西部开发中起了关键作用。","extra":""},{"chapter":14,"key":"14:104","id":104,"word":"railway","phonetic":"/'reɪlɪəʊ/","pos":"n.","meaningCN":"[英]铁路，铁路系统","tag":"核心","root":"","exampleEN":"The national railway network connects almost every major city in the country.","exampleCN":"全国铁路网连接了该国几乎每一座主要城市。","extra":"搭配：a railway station 火车站"},{"chapter":14,"key":"14:105","id":105,"word":"locomotive","phonetic":"/lɑʊkə'məʊtɪv/","pos":"n.","meaningCN":"火车头，机车","tag":"低频","root":"","exampleEN":"An old steam locomotive was displayed at the entrance of the railway museum.","exampleCN":"铁路博物馆的入口处展出了一辆老式的蒸汽机车。","extra":""},{"chapter":14,"key":"14:106","id":106,"word":"subway","phonetic":"/'sʌbweɪ/","pos":"n.","meaningCN":"[英]地下通道；[美]地铁","tag":"核心","root":"","exampleEN":"Many commuters prefer the subway to avoid heavy traffic in the city centre.","exampleCN":"许多通勤者宁愿坐地铁以避开市中心繁忙的交通。","extra":""},{"chapter":14,"key":"14:107","id":107,"word":"underground","phonetic":"/'ʌndəgraʊnd/","pos":"adj.","meaningCN":"地下的；秘密的 n. [英]地铁","tag":"核心","root":"","exampleEN":"London is famous for its extensive underground system, known as the Tube.","exampleCN":"伦敦以其庞大的地铁系统而闻名，通常称为 the Tube。","extra":""},{"chapter":14,"key":"14:108","id":108,"word":"tunnel","phonetic":"/'tʌn/","pos":"n.","meaningCN":"隧道，地道","tag":"核心","root":"","exampleEN":"The train entered a long tunnel, and the carriage was suddenly filled with darkness.","exampleCN":"火车驶入一条长长的隧道，车厢里顿时一片漆黑。","extra":""},{"chapter":14,"key":"14:109","id":109,"word":"rail","phonetic":"/reɪl/","pos":"n.","meaningCN":"栏杆；铁路路轨","tag":"核心","root":"","exampleEN":"Please hold the handrail while walking up and down the steep stairs.","exampleCN":"上下陡峭的楼梯时，请抓紧扶手。","extra":""},{"chapter":14,"key":"14:110","id":110,"word":"depart","phonetic":"/dɪ'pɑːt/","pos":"v.","meaningCN":"离开，启程","tag":"核心","root":"","exampleEN":"The first train departs at six in the morning, so you'll have to get up very early.","exampleCN":"第一班列车早上六点发车，所以你必须非常早就起床。","extra":"departure n. 离开；搭配：depart from 离开，从……出发"},{"chapter":14,"key":"14:111","id":111,"word":"arrive","phonetic":"/ə'raɪv/","pos":"v.","meaningCN":"到达；取得成功","tag":"核心","root":"","exampleEN":"The flight is expected to arrive at its destination around noon if there are no delays.","exampleCN":"如果没有延误，航班预计中午前后抵达目的地。","extra":"arrival n. 到达"},{"chapter":14,"key":"14:112","id":112,"word":"destination","phonetic":"/destɪ'neɪn/","pos":"n.","meaningCN":"目的地，终点","tag":"核心","root":"","exampleEN":"After more than ten hours of driving, they finally reached their destination.","exampleCN":"开了十多个小时的车后，他们终于到达了目的地。","extra":""},{"chapter":14,"key":"14:113","id":113,"word":"delay","phonetic":"/dɪ'leɪ/","pos":"n.","meaningCN":"耽搁；延期 v. 使耽搁；使延期","tag":"核心","root":"","exampleEN":"Our flight was delayed by two hours due to heavy fog at the airport.","exampleCN":"由于机场的大雾，我们的航班延误了两个小时。","extra":""},{"chapter":14,"key":"14:114","id":114,"word":"postpone","phonetic":"/'pəʊs'pəʊn/","pos":"v.","meaningCN":"推迟，使延期","tag":"核心","root":"","exampleEN":"The outdoor concert has been postponed until next Saturday because of the storm.","exampleCN":"由于暴风雨，户外音乐会已推迟到下周六。","extra":""},{"chapter":14,"key":"14:115","id":115,"word":"defer","phonetic":"/dɪ'fɜː/","pos":"v.","meaningCN":"推迟，拖延","tag":"低频","root":"","exampleEN":"The students asked if they could defer their final exam due to medical reasons.","exampleCN":"学生们询问是否可以因健康原因推迟期末考试。","extra":"搭配：defer payment 拖延付款"},{"chapter":14,"key":"14:116","id":116,"word":"lull","phonetic":"/lʌl/","pos":"n.","meaningCN":"暂停，暂时平静期 v. 使昏昏欲睡","tag":"低频","root":"","exampleEN":"After the noisy afternoon, a sudden lull fell over the playground.","exampleCN":"喧嚣的下午过后，操场突然安静了下来。","extra":""},{"chapter":14,"key":"14:117","id":117,"word":"expire","phonetic":"/ɪk'spaɪə/","pos":"v.","meaningCN":"期满；气绝，死亡","tag":"高频","root":"","exampleEN":"You should check whether your passport is going to expire before booking your trip.","exampleCN":"你预订行程前应该检查一下护照是否快到期了。","extra":"expiration n. 截止，期满"},{"chapter":14,"key":"14:118","id":118,"word":"due","phonetic":"/dju:/","pos":"adj.","meaningCN":"到期的，预期的","tag":"高频","root":"","exampleEN":"The assignment is due next Monday, so you still have a few days to finish it.","exampleCN":"作业下周一交，所以你还有几天时间完成。","extra":"overdue adj. 过期未完成的"},{"chapter":14,"key":"14:119","id":119,"word":"postage","phonetic":"/'poustid3/","pos":"n.","meaningCN":"邮费，邮资","tag":"高频","root":"","exampleEN":"The postage for a standard letter has gone up by just a few pence this year.","exampleCN":"今年标准信件的邮资只涨了几便士。","extra":"post n. 邮件；postman n. 邮递员；postcode n. 邮政编码"},{"chapter":14,"key":"14:120","id":120,"word":"stamp","phonetic":"/stamp/","pos":"n.","meaningCN":"邮票；印章 v. 在......上贴邮票；盖（章）","tag":"核心","root":"","exampleEN":"She carefully peeled a stamp off the sheet and stuck it on the envelope.","exampleCN":"她小心地从邮票版上撕下一张邮票，贴在信封上。","extra":""},{"chapter":14,"key":"14:121","id":121,"word":"envelope","phonetic":"/'envalop/","pos":"n.","meaningCN":"信封","tag":"核心","root":"","exampleEN":"He sealed the envelope and wrote the sender's address on the back of it.","exampleCN":"他封好信封，在背面写上了寄件人地址。","extra":"搭配：an airmail envelope 航空信封"},{"chapter":14,"key":"14:122","id":122,"word":"mail","phonetic":"/meil/","pos":"n.","meaningCN":"邮件，邮包；邮政 v. 邮寄","tag":"核心","root":"","exampleEN":"I'll mail you the documents tomorrow, and they should reach you by Friday.","exampleCN":"我明天把文件邮寄给你，周五前你应该就能收到。","extra":"e-mail n. 电子邮件"},{"chapter":14,"key":"14:123","id":123,"word":"packet","phonetic":"/'pakt/","pos":"n.","meaningCN":"[英]包装盒；[尤英]小件包裹","tag":"高频","root":"","exampleEN":"She opened a packet of biscuits and shared them with her classmates.","exampleCN":"她打开一包饼干，分给班上的同学。","extra":""},{"chapter":14,"key":"14:124","id":124,"word":"package","phonetic":"/'pakid3/","pos":"n.","meaningCN":"包裹；[美]盒，包 v. 包装","tag":"核心","root":"","exampleEN":"A large package arrived at the office with our name written on the outside.","exampleCN":"一个写有我们名字的大包裹送到了办公室。","extra":"pack n. 包；背包 v. 打点（行装）"},{"chapter":14,"key":"14:125","id":125,"word":"bind","phonetic":"/band/","pos":"v.","meaningCN":"捆，绑","tag":"高频","root":"","exampleEN":"They bound the heavy boxes together with thick rope to make them easier to carry.","exampleCN":"他们用粗绳子把沉重的箱子捆在一起，以便搬运。","extra":"搭配：bind up 包扎"},{"chapter":14,"key":"14:126","id":126,"word":"parcel","phonetic":"/'pasal/","pos":"v.","meaningCN":"打包，包 n.（土地的）一块；[尤英]包裹","tag":"高频","root":"","exampleEN":"She parcelled up the books and took them to the post office to send to her friend.","exampleCN":"她把书包好带到邮局寄给朋友。","extra":""},{"chapter":14,"key":"14:127","id":127,"word":"load","phonetic":"/loud/","pos":"v.","meaningCN":"装载，装满 n. 负荷；大量","tag":"核心","root":"","exampleEN":"The workers loaded the truck with boxes of fresh fruit for the morning market.","exampleCN":"工人们把一箱箱新鲜水果装上卡车，准备运往早市。","extra":"unload v. 从……卸货；搭配：a load of 大量的"},{"chapter":14,"key":"14:128","id":128,"word":"burden","phonetic":"/'bsdn/","pos":"v.","meaningCN":"（使）担负 n. 重担，负担","tag":"核心","root":"","exampleEN":"High rent can be a serious financial burden for students living in big cities.","exampleCN":"高昂的房租对住在大城市的学生来说可能是一个沉重的经济负担。","extra":"搭配：bear the burden of 背负着……的重担"},{"chapter":14,"key":"14:129","id":129,"word":"transfer","phonetic":"/'træns'f3/","pos":"v.","meaningCN":"（使）迁移，（使）转移；（使）调动","tag":"核心","root":"","exampleEN":"You will need to transfer to another bus at the central station to reach the museum.","exampleCN":"你需要在中央车站换乘另一辆公交车才能到达博物馆。","extra":"搭配：transfer to 转移到；转学到"},{"chapter":14,"key":"14:130","id":130,"word":"transmit","phonetic":"/'trænz'mit/","pos":"v.","meaningCN":"传送；传播，传染；传输","tag":"核心","root":"","exampleEN":"Some diseases can be transmitted simply through a handshake or shared surfaces.","exampleCN":"有些疾病仅仅通过握手或共用的表面就能传播。","extra":"transmission n. 传送；变速器"},{"chapter":14,"key":"14:131","id":131,"word":"transit","phonetic":"/ˈtrænsɪt/","pos":"v./n.","meaningCN":"通过；运送 n. 运输；通行；过境，中转","tag":"核心","root":"","exampleEN":"The damaged goods were lost in transit during shipping.","exampleCN":"损坏的货物在运输过程中丢失了。","extra":"搭配：in transit（在运输中）；a transit visa（过境签证）"},{"chapter":14,"key":"14:132","id":132,"word":"deliver","phonetic":"/dɪˈlɪvə/","pos":"v.","meaningCN":"传送，递送","tag":"核心","root":"","exampleEN":"The postman delivers mail to our neighborhood every afternoon.","exampleCN":"邮递员每天下午往我们社区递送邮件。","extra":"名词：delivery；搭配：deliver a speech（发表演讲）"},{"chapter":14,"key":"14:133","id":133,"word":"convey","phonetic":"/kənˈveɪ/","pos":"v.","meaningCN":"运送，输送；表达，传递","tag":"核心","root":"","exampleEN":"The pipeline conveys natural gas from the coast to inland cities.","exampleCN":"管道将天然气从海岸输送到内陆城市。","extra":"同义词：transport（运送）；express（表达）"},{"chapter":14,"key":"14:134","id":134,"word":"speed","phonetic":"/spiːd/","pos":"n.","meaningCN":"速度；迅速","tag":"核心","root":"","exampleEN":"The new train reaches speeds of over 300 kilometers per hour.","exampleCN":"新型列车的时速超过300公里。","extra":"动词：speed（加速）；搭配：speed limit（限速）"},{"chapter":14,"key":"14:135","id":135,"word":"velocity","phonetic":"/vɪˈzlɪti/","pos":"n.","meaningCN":"速度","tag":"高频","root":"","exampleEN":"The velocity of the wind increased as the storm approached the island.","exampleCN":"随着风暴逼近岛屿，风速增大了。","extra":"物理学术语，常指方向速度"},{"chapter":14,"key":"14:136","id":136,"word":"swift","phonetic":"/swɪft/","pos":"adj.","meaningCN":"迅速的；敏捷的","tag":"核心","root":"","exampleEN":"The company took swift action to fix the software bug.","exampleCN":"公司迅速采取行动修复了软件漏洞。","extra":"名词：swiftness；同义词：quick, rapid"},{"chapter":14,"key":"14:137","id":137,"word":"harbour","phonetic":"/ˈhɑːbə/","pos":"n.","meaningCN":"港口，海港","tag":"核心","root":"","exampleEN":"The fishing boats returned to the harbour before the storm hit.","exampleCN":"暴风雨来临前，渔船返回了港口。","extra":"美式拼写：harbor；形容词：harbourless"},{"chapter":14,"key":"14:138","id":138,"word":"dock","phonetic":"/dɒk/","pos":"n.","meaningCN":"码头，船坞","tag":"核心","root":"","exampleEN":"The ship was in the dock for repairs after its long voyage.","exampleCN":"长途航行后，这艘船在船坞进行维修。","extra":"动词：dock（停靠码头；扣除）；搭配：dry dock（干船坞）"},{"chapter":14,"key":"14:139","id":139,"word":"anchor","phonetic":"/ˈæŋkə/","pos":"n.","meaningCN":"锚","tag":"核心","root":"","exampleEN":"The crew dropped the anchor as soon as they reached the safe bay.","exampleCN":"船员们一到达安全海湾就抛下了锚。","extra":"动词：anchor（抛锚；使固定）；搭配：anchor chain（锚链）"}],"15":[{"chapter":15,"key":"15:1","id":1,"word":"republic","phonetic":"/rɪˈpʌblɪk/","pos":"n.","meaningCN":"共和国，共和政体","tag":"核心","root":"","exampleEN":"The country became a republic after the revolution ended the monarchy.","exampleCN":"革命结束了君主制后，那个国家变成了一个共和国。","extra":"republican adj. 共和国的；搭配：the People's Republic of China 中华人民共和国；establish a republic 建立共和国"},{"chapter":15,"key":"15:2","id":2,"word":"Marxism","phonetic":"/'ma:ksizəm/","pos":"n.","meaningCN":"马克思主义","tag":"低频","root":"Marx（马克思）+ ism（主义）","exampleEN":"The professor gave a lecture on the basic principles of Marxism.","exampleCN":"教授做了一场关于马克思主义基本原理的讲座。","extra":""},{"chapter":15,"key":"15:3","id":3,"word":"socialism","phonetic":"/'səuʃəl-izəm/","pos":"n.","meaningCN":"社会主义","tag":"核心","root":"","exampleEN":"The government is committed to building socialism with local characteristics.","exampleCN":"政府致力于建设具有当地特色的社会主义。","extra":"socialist adj. 社会主义的；social adj. 社会的；society n. 社会；搭配：serve socialism 为社会主义服务"},{"chapter":15,"key":"15:4","id":4,"word":"communism","phonetic":"/'komjənizəm/","pos":"n.","meaningCN":"共产主义","tag":"低频","root":"","exampleEN":"The idea of communism has influenced many political movements around the world.","exampleCN":"共产主义思想影响了世界上许多政治运动。","extra":"communist n. 共产主义者；common adj. 普通的；communal adj. 公共的"},{"chapter":15,"key":"15:5","id":5,"word":"regime","phonetic":"/reɪ'ʃiəm/","pos":"n.","meaningCN":"统治制度，政权，政体","tag":"高频","root":"reg = 统治，管理","exampleEN":"The new regime introduced a series of economic reforms to boost growth.","exampleCN":"新政权推出了一系列经济改革以促进增长。","extra":""},{"chapter":15,"key":"15:6","id":6,"word":"government","phonetic":"/'gʌvərmənt/","pos":"n.","meaningCN":"政府；政体；统治","tag":"核心","root":"","exampleEN":"The government has announced new measures to reduce air pollution.","exampleCN":"政府宣布了减少空气污染的新措施。","extra":"govern v. 统治，治理；governor n. 统治者；主管"},{"chapter":15,"key":"15:7","id":7,"word":"authority","phonetic":"/'ɔːθəriːti/","pos":"n.","meaningCN":"权力；权威人士；行政管理机构；[the authorities] 当局","tag":"核心","root":"","exampleEN":"The local authority decided to build a new library for the community.","exampleCN":"地方当局决定为社区修建一座新图书馆。","extra":"authorise (= authorize) v. 授权，批准；搭配：abuse authority 滥用职权"},{"chapter":15,"key":"15:8","id":8,"word":"political","phonetic":"/pə'litikl/","pos":"adj.","meaningCN":"政治的；政党的","tag":"核心","root":"","exampleEN":"She has been active in political circles since her university days.","exampleCN":"她从大学时代起就一直活跃于政界。","extra":"policy n. 政策；politics n. 政治；politician n. 政治家；搭配：a political party 政党"},{"chapter":15,"key":"15:9","id":9,"word":"hierarchy","phonetic":"/'haiərɑːki/","pos":"n.","meaningCN":"等级制度；统治集团","tag":"高频","root":"","exampleEN":"In a strict hierarchy, every person knows exactly who they report to.","exampleCN":"在严格的等级制度中，每个人都很清楚自己向谁汇报。","extra":""},{"chapter":15,"key":"15:10","id":10,"word":"democracy","phonetic":"/dɪˈmɒkrəsi/","pos":"n.","meaningCN":"民主，民主制度；民主国家","tag":"核心","root":"demo（人民）+ cracy（统治）→ 由人民统治","exampleEN":"Free and fair elections are an essential part of any healthy democracy.","exampleCN":"自由公正的选举是任何健康民主制度的重要组成部分。","extra":"democratise v. 使民主；democrat n. 民主主义者；democratic adj. 民主的"},{"chapter":15,"key":"15:11","id":11,"word":"bureaucracy","phonetic":"/bjuə'rɒkrəsi/","pos":"n.","meaningCN":"官僚制度；官僚作风","tag":"高频","root":"","exampleEN":"The complex bureaucracy often slows down the process of starting a business.","exampleCN":"复杂的官僚制度常常拖慢了创业的进程。","extra":"bureaucratism n. 官僚主义"},{"chapter":15,"key":"15:12","id":12,"word":"egalitarian","phonetic":"/ɪ,ɡælɪ'teəriən/","pos":"adj.","meaningCN":"平等主义的 n. 平等主义者","tag":"低频","root":"","exampleEN":"The ideal of an egalitarian society has inspired many social reforms.","exampleCN":"平等主义社会的理想激发了许多社会改革。","extra":""},{"chapter":15,"key":"15:13","id":13,"word":"materialism","phonetic":"/mə'tɪəriəlɪzəm/","pos":"n.","meaningCN":"唯物主义；唯物论","tag":"低频","root":"","exampleEN":"Dialectical materialism is a fundamental theory in Marxist philosophy.","exampleCN":"辩证唯物主义是马克思主义哲学的基本理论。","extra":"material n. 物质；素材；材料"},{"chapter":15,"key":"15:14","id":14,"word":"revolution","phonetic":"/ˌrevə'luːʃən/","pos":"n.","meaningCN":"革命；巨大变化","tag":"核心","root":"","exampleEN":"The digital revolution has changed the way people communicate and work.","exampleCN":"数字革命改变了人们交流和工作的方式。","extra":"revolutionary adj. 革命的 n. 革命者"},{"chapter":15,"key":"15:15","id":15,"word":"neutral","phonetic":"/'nju:trəl/","pos":"adj.","meaningCN":"中立的；中性的","tag":"高频","root":"","exampleEN":"The mediator must remain neutral and not take either side in the dispute.","exampleCN":"调解人必须保持中立，不在争端中偏袒任何一方。","extra":"neutrally adv. 中立地；搭配：remain neutral 保持中立"},{"chapter":15,"key":"15:16","id":16,"word":"bilateral","phonetic":"/'bai'lætərəl/","pos":"adj.","meaningCN":"双边的","tag":"高频","root":"","exampleEN":"The two leaders signed a bilateral trade agreement to reduce tariffs.","exampleCN":"两国领导人签署了一项双边贸易协定以降低关税。","extra":"搭配：a bilateral agreement 双边协定；bilateral negotiations 双边谈判"},{"chapter":15,"key":"15:17","id":17,"word":"reform","phonetic":"/rɪ'fɔːm/","pos":"n.","meaningCN":"改革，改良 v. 改革，改良；（使）改过自新","tag":"核心","root":"","exampleEN":"Many experts believe that educational reform is necessary for economic development.","exampleCN":"许多专家认为教育改革对经济发展是必要的。","extra":"搭配：reform and opening up 改革开放"},{"chapter":15,"key":"15:18","id":18,"word":"arena","phonetic":"/ə'ri:nə/","pos":"n.","meaningCN":"竞技场，运动场；舞台，活动领域","tag":"高频","root":"","exampleEN":"The company entered the international arena with its new smartphone last year.","exampleCN":"去年，这家公司凭借新款智能手机进入了国际舞台。","extra":"拉丁语原指“沙；沙地”，古罗马角斗场"},{"chapter":15,"key":"15:19","id":19,"word":"flag","phonetic":"/flæɡ/","pos":"n.","meaningCN":"旗，旗帜","tag":"核心","root":"","exampleEN":"During the ceremony, the national flag was raised slowly as everyone stood in silence.","exampleCN":"仪式上，国旗缓缓升起，所有人都肃立着。","extra":"搭配：a national flag 国旗"},{"chapter":15,"key":"15:20","id":20,"word":"conservative","phonetic":"/kən'sɜːvətɪv/","pos":"adj.","meaningCN":"保守的 n. 保守党员","tag":"核心","root":"","exampleEN":"The conservative approach to investment focuses on low risk and steady growth.","exampleCN":"保守的投资方式注重低风险和稳定增长。","extra":"英国保守党 Conservative Party"},{"chapter":15,"key":"15:21","id":21,"word":"banner","phonetic":"/'bænə/","pos":"n.","meaningCN":"横幅，标语","tag":"高频","root":"","exampleEN":"Protesters carried banners demanding action on climate change through the streets.","exampleCN":"抗议者举着要求就气候变化采取行动的横幅穿过了街道。","extra":"搭配：under the banner of 以……的名义，在……的旗帜下"},{"chapter":15,"key":"15:22","id":22,"word":"meltdown","phonetic":"/'meltdaʊn/","pos":"n.","meaningCN":"（核反应堆的）堆芯熔毁；崩溃","tag":"低频","root":"","exampleEN":"The financial meltdown of 2008 had serious consequences for the global economy.","exampleCN":"2008年的金融崩溃对全球经济产生了严重后果。","extra":""},{"chapter":15,"key":"15:23","id":23,"word":"municipal","phonetic":"/mjuː'nɪsɪpəl/","pos":"adj.","meaningCN":"市政的，地方政府的","tag":"高频","root":"","exampleEN":"The municipal council voted to improve public transport in the city centre.","exampleCN":"市议会投票决定改善市中心的公共交通。","extra":"搭配：a municipal government 市政府"},{"chapter":15,"key":"15:24","id":24,"word":"process","phonetic":"n. /'prəʊses/ v. /prə'ses/","pos":"n.","meaningCN":"过程，进程 v. 处理；加工；列队前进","tag":"核心","root":"","exampleEN":"Learning a new language is a slow process that requires time and patience.","exampleCN":"学习一门新语言是一个需要时间和耐心的缓慢过程。","extra":"procession n. 队伍，行列；搭配：in the process of 在……过程中；in process 在进行中"},{"chapter":15,"key":"15:25","id":25,"word":"president","phonetic":"/'prezidənt/","pos":"n.","meaningCN":"总统；校长；董事长","tag":"核心","root":"","exampleEN":"The university president gave an inspiring speech at the graduation ceremony.","exampleCN":"大学校长在毕业典礼上发表了一场鼓舞人心的演讲。","extra":"搭配：elect sb. (as) president 选举某人为总统"},{"chapter":15,"key":"15:26","id":26,"word":"premier","phonetic":"/'premiə/","pos":"n.","meaningCN":"总理，首相 adj. 首要的，第一的","tag":"高频","root":"","exampleEN":"The Italian premier is scheduled to meet the French president next Tuesday.","exampleCN":"意大利总理定于下周二与法国总统会面。","extra":"premiership n. 总理（或首相）职位（或任期）；搭配：of the premier importance 头等重要的"},{"chapter":15,"key":"15:27","id":27,"word":"minister","phonetic":"/'ministə/","pos":"n.","meaningCN":"部长，大臣；公使","tag":"核心","root":"","exampleEN":"The education minister proposed a new plan to reduce the number of dropouts.","exampleCN":"教育部长提出了一项减少辍学人数的新计划。","extra":"搭配：foreign minister 外交部部长"},{"chapter":15,"key":"15:28","id":28,"word":"secretary","phonetic":"/'sekrətəri/","pos":"n.","meaningCN":"秘书；书记员；大臣","tag":"核心","root":"","exampleEN":"The secretary of the committee took careful notes during the entire meeting.","exampleCN":"委员会的秘书在整个会议期间都认真做了笔记。","extra":"搭配：employ a new secretary 雇用新秘书"},{"chapter":15,"key":"15:29","id":29,"word":"parliament","phonetic":"/'pɑːləmənt/","pos":"n.","meaningCN":"议会，国会；[P-]（英国）议会","tag":"核心","root":"","exampleEN":"The bill was passed by parliament and became law the following month.","exampleCN":"该法案由议会通过，并于次月成为法律。","extra":""},{"chapter":15,"key":"15:30","id":30,"word":"senate","phonetic":"/'senət/","pos":"n.","meaningCN":"大学理事会；[the S-]（美国等国家的）参议院","tag":"高频","root":"","exampleEN":"The United States Senate has 100 members, two from each state.","exampleCN":"美国参议院有100名议员，每个州两名。","extra":"搭配：disband a senate 解散理事会"},{"chapter":15,"key":"15:31","id":31,"word":"conference","phonetic":"/'kɒnfərəns/","pos":"n.","meaningCN":"（常持续数日的大型正式）会议；正式商谈","tag":"核心","root":"","exampleEN":"More than 200 scientists from around the world attended the climate conference.","exampleCN":"来自世界各地的200多位科学家出席了这次气候大会。","extra":"搭配：attend a conference 出席大会"},{"chapter":15,"key":"15:32","id":32,"word":"meeting","phonetic":"/'miːtɪŋ/","pos":"n.","meaningCN":"会议；会面","tag":"核心","root":"","exampleEN":"The team holds a short meeting every Monday morning to set weekly goals.","exampleCN":"团队每周一早上开短会，设定本周目标。","extra":"搭配：address a meeting 在会上发言；hold a meeting 开会"},{"chapter":15,"key":"15:33","id":33,"word":"headquarters","phonetic":"/ˌhed'kwɔːtəz/","pos":"n.","meaningCN":"总部，总公司；司令部","tag":"核心","root":"head（头）+ quarters（营房）→ 头儿的营房 → 司令部","exampleEN":"The international company moved its European headquarters to Amsterdam.","exampleCN":"这家跨国公司把欧洲总部搬到了阿姆斯特丹。","extra":""},{"chapter":15,"key":"15:34","id":34,"word":"delegation","phonetic":"/ˌdelɪ'ɡeɪʃən/","pos":"n.","meaningCN":"代表团；委派","tag":"高频","root":"","exampleEN":"A delegation of business leaders visited the factory to discuss future cooperation.","exampleCN":"一个商业领袖代表团参观了工厂，讨论未来的合作。","extra":"delegate v. 委派"},{"chapter":15,"key":"15:35","id":35,"word":"behalf","phonetic":"/bɪ'hɑːf/","pos":"n.","meaningCN":"[on behalf of sb.] 代表某人","tag":"高频","root":"","exampleEN":"I would like to thank everyone on behalf of the entire management team.","exampleCN":"我谨代表整个管理团队感谢大家。","extra":"搭配：on behalf of sb. / on sb.'s behalf 代表某人"},{"chapter":15,"key":"15:36","id":36,"word":"police","phonetic":"/pə'liːs/","pos":"n.","meaningCN":"警察；[the-]警方","tag":"核心","root":"","exampleEN":"The police arrived at the scene within minutes and began their investigation.","exampleCN":"警察几分钟内就赶到了现场并开始调查。","extra":"搭配：call the police 叫警察"},{"chapter":15,"key":"15:37","id":37,"word":"statesman","phonetic":"/'steɪtsmən/","pos":"n.","meaningCN":"政治家","tag":"高频","root":"","exampleEN":"He is remembered as a wise statesman who brought peace to the region.","exampleCN":"他被人们铭记为一位给该地区带来和平的睿智政治家。","extra":""},{"chapter":15,"key":"15:38","id":38,"word":"mayor","phonetic":"/meə/","pos":"n.","meaningCN":"市长","tag":"核心","root":"","exampleEN":"The mayor promised to create more green spaces in the city over the next five years.","exampleCN":"市长承诺在未来五年内为城市增加更多的绿地。","extra":""},{"chapter":15,"key":"15:39","id":39,"word":"service","phonetic":"/'sɜːvɪs/","pos":"n.","meaningCN":"服务；公共服务事业；公共事业机构","tag":"核心","root":"","exampleEN":"The quality of customer service greatly affects whether shoppers will return.","exampleCN":"客户服务的质量极大地影响着购物者是否还会再来。","extra":"搭配：at sb.'s service 可供某人使用"},{"chapter":15,"key":"15:40","id":40,"word":"office","phonetic":"/'ɒfɪs/","pos":"n.","meaningCN":"办公室；要职，官职；[O-]部，局，厅","tag":"核心","root":"","exampleEN":"He decided to run for public office after years of community work.","exampleCN":"在多年的社区工作之后，他决定竞选公职。","extra":"officer n. 官员；军官；搭配：come into office 上任，就职"},{"chapter":15,"key":"15:41","id":41,"word":"bureau","phonetic":"/'bjʊərəʊ/","pos":"n.","meaningCN":"局，处，科；办事处","tag":"高频","root":"","exampleEN":"The weather bureau warned that heavy rain would continue throughout the weekend.","exampleCN":"气象局警告称，强降雨将持续整个周末。","extra":"bureaucracy n. 官僚制度；官僚作风"},{"chapter":15,"key":"15:42","id":42,"word":"department","phonetic":"/dɪ'pɑːtmənt/","pos":"n.","meaningCN":"（政府、企业等机构的）部门；（大学的）系，所","tag":"核心","root":"","exampleEN":"She works in the human resources department of a large technology firm.","exampleCN":"她在一家大型科技公司的人力资源部工作。","extra":""},{"chapter":15,"key":"15:43","id":43,"word":"harness","phonetic":"/'hɑːnɪs/","pos":"v.","meaningCN":"控制，利用","tag":"高频","root":"","exampleEN":"Scientists are looking for new ways to harness solar energy more efficiently.","exampleCN":"科学家们正在寻找更高效利用太阳能的新方法。","extra":""},{"chapter":15,"key":"15:44","id":44,"word":"administration","phonetic":"/ədˌmɪnɪ'streɪʃən/","pos":"n.","meaningCN":"管理，行政","tag":"核心","root":"administer（管理），minister（部长，大臣）","exampleEN":"Good administration is the foundation of any successful organisation.","exampleCN":"良好的行政管理是任何成功组织的基础。","extra":""},{"chapter":15,"key":"15:45","id":45,"word":"dominate","phonetic":"/'dɒmɪneɪt/","pos":"v.","meaningCN":"支配，控制；占优势","tag":"核心","root":"","exampleEN":"The company dominates the smartphone market with a share of over 40%.","exampleCN":"该公司以超过40%的市场份额主导着智能手机市场。","extra":"domination n. 控制，统治；predominate v. 占主导地位；搭配：dominate the weaker 支配弱者"},{"chapter":15,"key":"15:46","id":46,"word":"power","phonetic":"/'paʊə/","pos":"n.","meaningCN":"能力；权力；政权；能源","tag":"核心","root":"","exampleEN":"Solar power is becoming cheaper and more accessible to ordinary households.","exampleCN":"太阳能正变得越来越便宜，普通家庭也越来越容易用上。","extra":"powerful adj. 强有力的；搭配：come into power 上台，开始执政"},{"chapter":15,"key":"15:47","id":47,"word":"influence","phonetic":"/'ɪnflʊəns/","pos":"n.","meaningCN":"影响，作用 v. 影响","tag":"核心","root":"","exampleEN":"Parents have a strong influence on the development of their children's values.","exampleCN":"父母对子女价值观的发展有着很强的影响。","extra":"influential adj. 有影响力的；搭配：have an influence on 对……产生影响"},{"chapter":15,"key":"15:48","id":48,"word":"affect","phonetic":"/ə'fekt/","pos":"v.","meaningCN":"影响；（感情上）打动，使悲伤","tag":"核心","root":"","exampleEN":"Lack of sleep can seriously affect your concentration and decision-making.","exampleCN":"缺乏睡眠会严重影响你的注意力和决策能力。","extra":"effect n. 影响，作用"},{"chapter":15,"key":"15:49","id":49,"word":"importance","phonetic":"/ɪm'pɔːtəns/","pos":"n.","meaningCN":"重要，重要性","tag":"核心","root":"","exampleEN":"Education is of great importance to the long-term development of any society.","exampleCN":"教育对任何社会的长远发展都具有重要意义。","extra":"important adj. 重要的；搭配：realise the importance 意识到重要性"},{"chapter":15,"key":"15:50","id":50,"word":"significance","phonetic":"/sɪg'nɪfɪkəns/","pos":"n.","meaningCN":"重要性，意义","tag":"核心","root":"","exampleEN":"The discovery holds great significance for our understanding of ancient cultures.","exampleCN":"这一发现对我们理解古代文化具有重大意义。","extra":"significant adj. 有意义的；搭配：a matter of significance 有重大意义的事情"},{"chapter":15,"key":"15:51","id":51,"word":"organisation","phonetic":"/ˌɔːɡənaɪ'zeɪʃən/","pos":"n.","meaningCN":"组织，团体，机构","tag":"核心","root":"","exampleEN":"The charity organisation provides food and shelter for homeless people.","exampleCN":"这个慈善组织为无家可归者提供食物和住所。","extra":"organise v. 组织；安排；也作 organization"},{"chapter":15,"key":"15:52","id":52,"word":"association","phonetic":"/əˌsəʊsi'eɪʃən/","pos":"n.","meaningCN":"协会，团体；关联","tag":"核心","root":"","exampleEN":"The bar association sets professional standards for lawyers in the country.","exampleCN":"律师协会为该国律师制定了专业标准。","extra":"associate v. 联想，联系"},{"chapter":15,"key":"15:53","id":53,"word":"union","phonetic":"/'juːnjən/","pos":"n.","meaningCN":"联合；联盟；工会","tag":"核心","root":"unio（联合），onion（洋葱）同源","exampleEN":"The students' union organises social events and provides support for new students.","exampleCN":"学生会组织社交活动并为新生提供支持。","extra":"搭配：a trade union [英] 工会；a labor union [美] 工会"},{"chapter":15,"key":"15:54","id":54,"word":"community","phonetic":"/kə'mjuːnəti/","pos":"n.","meaningCN":"社区；群体；（生物的）群落","tag":"核心","root":"","exampleEN":"The local community came together to clean up the park after the storm.","exampleCN":"暴风雨过后，当地社区齐心协力清理了公园。","extra":"搭配：a community centre 社区活动中心"},{"chapter":15,"key":"15:55","id":55,"word":"consortium","phonetic":"/kən'sɔːtiəm/","pos":"n.","meaningCN":"财团，联营企业","tag":"低频","root":"","exampleEN":"A consortium of international banks funded the massive construction project.","exampleCN":"一个由国际银行组成的财团为这个庞大的建设工程提供了资金。","extra":""},{"chapter":15,"key":"15:56","id":56,"word":"league","phonetic":"/liːɡ/","pos":"n.","meaningCN":"联赛；联盟，同盟","tag":"高频","root":"","exampleEN":"The two teams are at the top of the league, separated by just one point.","exampleCN":"这两支球队排在联赛榜首，彼此只差一分。","extra":"搭配：form a league 结成联盟"},{"chapter":15,"key":"15:57","id":57,"word":"institution","phonetic":"/ˌɪnstɪ'tjuːʃən/","pos":"n.","meaningCN":"社会福利机构；（大学、银行等大型）机构","tag":"核心","root":"","exampleEN":"The university is the oldest educational institution in the entire region.","exampleCN":"这所大学是整个地区历史最悠久的教育机构。","extra":"institute n. 研究所，学院；搭配：an educational institution 教育机构"},{"chapter":15,"key":"15:58","id":58,"word":"unite","phonetic":"/juː'naɪt/","pos":"v.","meaningCN":"（使）联合，（使）团结","tag":"高频","root":"","exampleEN":"The crisis helped unite the community, and neighbours began helping one another.","exampleCN":"这场危机帮助团结了社区，邻居们开始互相帮助。","extra":"united adj. 联合的；unity n. 统一；搭配：unite closely 紧密团结"},{"chapter":15,"key":"15:59","id":59,"word":"unique","phonetic":"/juː'niːk/","pos":"adj.","meaningCN":"独一无二的，唯一的；独特的","tag":"核心","root":"","exampleEN":"Each island in the group has its own unique culture and natural beauty.","exampleCN":"该群岛的每个岛屿都有自己独特的文化和自然美景。","extra":"搭配：unique ability 独特的才能"},{"chapter":15,"key":"15:60","id":60,"word":"nation","phonetic":"/'neɪʃən/","pos":"n.","meaningCN":"国家；民族；国民","tag":"核心","root":"","exampleEN":"The small island nation depends heavily on tourism for its national income.","exampleCN":"这个小小的岛国严重依赖旅游业来获取国家收入。","extra":"national adj. 民族的；国家的；nationality n. 国籍；international adj. 国际的"},{"chapter":15,"key":"15:61","id":61,"word":"global","phonetic":"/'ɡləʊbəl/","pos":"adj.","meaningCN":"全球的，全世界的","tag":"核心","root":"","exampleEN":"Climate change is a global problem that requires cooperation from all countries.","exampleCN":"气候变化是一个全球性问题，需要所有国家合作。","extra":"搭配：global warming 全球气候变暖"},{"chapter":15,"key":"15:62","id":62,"word":"worldwide","phonetic":"/ˌwɜːld'waɪd/","pos":"adj.","meaningCN":"世界范围的，遍及全球的","tag":"核心","root":"","exampleEN":"The movie became a worldwide hit, earning over a billion dollars.","exampleCN":"那部电影在全球引起轰动，票房收入超过十亿美元。","extra":""},{"chapter":15,"key":"15:63","id":63,"word":"federal","phonetic":"/'fedərəl/","pos":"adj.","meaningCN":"联邦的，联合的","tag":"核心","root":"","exampleEN":"Federal law overrides state law in matters of national security.","exampleCN":"在国家安全问题上，联邦法律优先于州法律。","extra":"federation n. 联邦制国家；FBI = Federal Bureau of Investigation"},{"chapter":15,"key":"15:64","id":64,"word":"foreign","phonetic":"/'fɒrɪn/","pos":"adj.","meaningCN":"外国的；外来的；外交的","tag":"核心","root":"","exampleEN":"Learning a foreign language opens up new opportunities for travel and work.","exampleCN":"学习一门外语能带来新的旅行和工作机会。","extra":"foreigner n. 外国人；搭配：a foreign policy 外交政策"},{"chapter":15,"key":"15:65","id":65,"word":"overseas","phonetic":"adj. /'əʊvəˌsiːz/ adv. /ˌəʊvəˌsiːz/","pos":"adj.","meaningCN":"海外的，国外的 adv. 向海外；在国外","tag":"核心","root":"","exampleEN":"She has been working overseas for three years and plans to return home soon.","exampleCN":"她已在海外工作了三年，并计划不久后回国。","extra":"搭配：overseas trade 海外贸易；an overseas student 留学生"},{"chapter":15,"key":"15:66","id":66,"word":"abroad","phonetic":"/ə'brɔːd/","pos":"adv.","meaningCN":"到国外，在国外；广为流传","tag":"核心","root":"","exampleEN":"Studying abroad gives students a chance to experience different cultures firsthand.","exampleCN":"到国外学习让学生有机会亲身体验不同的文化。","extra":"搭配：travel abroad 到国外旅行"},{"chapter":15,"key":"15:67","id":67,"word":"throne","phonetic":"/θrəʊn/","pos":"n.","meaningCN":"王位；（君王的）宝座","tag":"低频","root":"","exampleEN":"The young prince is next in line for the throne after his father.","exampleCN":"年轻的王子是仅次于其父的王位继承人。","extra":"搭配：come to the throne 即位，登基"},{"chapter":15,"key":"15:68","id":68,"word":"crown","phonetic":"/kraʊn/","pos":"n.","meaningCN":"王冠 v. 为......加冕","tag":"高频","root":"","exampleEN":"The queen's crown is decorated with diamonds, pearls, and other precious stones.","exampleCN":"女王的王冠上装饰着钻石、珍珠和其他宝石。","extra":"搭配：succeed to the crown 继承王位"},{"chapter":15,"key":"15:69","id":69,"word":"civil","phonetic":"/'sɪvəl/","pos":"adj.","meaningCN":"公民的，国内的；民用的；斯文的","tag":"核心","root":"","exampleEN":"Civil rights activists fought for equal treatment under the law.","exampleCN":"民权活动家为法律之下的平等待遇而斗争。","extra":"civilise v. 使文明；civilisation n. 文明；搭配：civil rights 公民权利；a civil war 内战"},{"chapter":15,"key":"15:70","id":70,"word":"emigrate","phonetic":"/'emɪɡreɪt/","pos":"v.","meaningCN":"移居国外","tag":"高频","root":"","exampleEN":"During the famine, many people were forced to emigrate in search of food.","exampleCN":"饥荒期间，许多人被迫移居国外以寻找食物。","extra":"emigration n. 移居国外"},{"chapter":15,"key":"15:71","id":71,"word":"immigrate","phonetic":"/'ɪmɪɡreɪt/","pos":"v.","meaningCN":"（从外地）移居，移入","tag":"高频","root":"","exampleEN":"Thousands of skilled workers immigrate to the country every year to fill job shortages.","exampleCN":"每年有成千上万的技术工人移居该国，以填补劳动力短缺。","extra":"immigration n. 移居（入境）；immigrant n. 移民"},{"chapter":15,"key":"15:72","id":72,"word":"reign","phonetic":"/reɪn/","pos":"n.","meaningCN":"君主统治时期 v. 统治","tag":"低频","root":"","exampleEN":"The period of Queen Elizabeth I's reign is seen as a golden age in English history.","exampleCN":"伊丽莎白一世女王统治时期被视为英国历史上的黄金时代。","extra":""},{"chapter":15,"key":"15:73","id":73,"word":"puppet","phonetic":"/'pʌpɪt/","pos":"n.","meaningCN":"玩偶；傀儡","tag":"高频","root":"","exampleEN":"The new leader was accused of being a mere puppet controlled by the military.","exampleCN":"那位新领导人被指责不过是军队控制的傀儡。","extra":"搭配：a puppet government 傀儡政府"},{"chapter":15,"key":"15:74","id":74,"word":"wreath","phonetic":"/riːθ/","pos":"n.","meaningCN":"花环，花冠；（祭奠用的）花圈","tag":"低频","root":"","exampleEN":"On Remembrance Day, people lay wreaths at the monument to honour fallen soldiers.","exampleCN":"在阵亡将士纪念日，人们在纪念碑前敬献花圈以缅怀牺牲的士兵。","extra":"搭配：a laurel wreath 桂冠"},{"chapter":15,"key":"15:75","id":75,"word":"colony","phonetic":"/'kɒləni/","pos":"n.","meaningCN":"殖民地","tag":"高频","root":"","exampleEN":"The country gained independence from its former colony in the early 1960s.","exampleCN":"该国在20世纪60年代初脱离原殖民地统治获得独立。","extra":"colonial n. 殖民地居民 adj. 殖民地的"},{"chapter":15,"key":"15:76","id":76,"word":"liberty","phonetic":"/'lɪbəti/","pos":"n.","meaningCN":"自由","tag":"核心","root":"","exampleEN":"The Statue of Liberty has welcomed millions of immigrants to the United States.","exampleCN":"自由女神像已迎接了数百万移民来到美国。","extra":"liberate v. 解放；liberation n. 解放；搭配：the Statue of Liberty 自由女神像"},{"chapter":15,"key":"15:77","id":77,"word":"independence","phonetic":"/ˌɪndɪ'pendəns/","pos":"n.","meaningCN":"独立；自立","tag":"核心","root":"","exampleEN":"Financial independence is an important goal for many young professionals today.","exampleCN":"经济独立是当今许多年轻专业人士的重要目标。","extra":"independent adj. 独立的；搭配：fight for independence 为独立而斗争"},{"chapter":15,"key":"15:78","id":78,"word":"slum","phonetic":"/slʌm/","pos":"n.","meaningCN":"贫民窟","tag":"高频","root":"","exampleEN":"The charity is working to improve living conditions in the city's largest slum.","exampleCN":"该慈善机构正在努力改善该市最大贫民窟的生活条件。","extra":"搭配：a slum area 贫民区"},{"chapter":15,"key":"15:79","id":79,"word":"refuge","phonetic":"/'refjuːdʒ/","pos":"n.","meaningCN":"避难，庇护；避难所","tag":"高频","root":"","exampleEN":"Thousands of people sought refuge in neighbouring countries during the conflict.","exampleCN":"冲突期间，成千上万的人在邻国寻求庇护。","extra":"搭配：seek refuge 寻求庇护"},{"chapter":15,"key":"15:80","id":80,"word":"asylum","phonetic":"/ə'saɪləm/","pos":"n.","meaningCN":"庇护；精神病院","tag":"高频","root":"","exampleEN":"The refugee applied for political asylum after fleeing violence in his home country.","exampleCN":"那位难民在逃离祖国的暴力后申请了政治庇护。","extra":"搭配：an asylum seeker 寻求庇护的人"},{"chapter":15,"key":"15:81","id":81,"word":"population","phonetic":"/ˌpɒpju'leɪʃən/","pos":"n.","meaningCN":"人口，人口数量","tag":"核心","root":"","exampleEN":"The population of the city has doubled in the last twenty years due to migration.","exampleCN":"由于人口迁移，这座城市的人口在过去二十年里翻了一番。","extra":"populate v. 居住于；搭配：control population 控制人口"},{"chapter":15,"key":"15:82","id":82,"word":"demographic","phonetic":"/ˌdemə'ɡræfɪk/","pos":"adj.","meaningCN":"人口（学）的，人口统计（学）的","tag":"低频","root":"demo（人民）+ graph（写）+ ic → 写关于人民的情况","exampleEN":"The demographic data shows that the average age of the population is rising.","exampleCN":"人口统计数据显示，人口的平均年龄正在上升。","extra":"demography n. 人口统计学"},{"chapter":15,"key":"15:83","id":83,"word":"citizen","phonetic":"/'sɪtɪzən/","pos":"n.","meaningCN":"公民；市民","tag":"核心","root":"","exampleEN":"Every citizen has the right to vote in a democratic election.","exampleCN":"每个公民都有在民主选举中投票的权利。","extra":"搭配：an ordinary citizen 普通公民"},{"chapter":15,"key":"15:84","id":84,"word":"resident","phonetic":"/'rezɪdənt/","pos":"n.","meaningCN":"居民 adj. 居住的","tag":"核心","root":"","exampleEN":"Local residents are invited to attend the public hearing on the new road project.","exampleCN":"当地居民被邀请参加关于新建道路项目的公众听证会。","extra":"residential adj. 住宅的，适合居住的"},{"chapter":15,"key":"15:85","id":85,"word":"ethnic","phonetic":"/'eθnɪk/","pos":"adj.","meaningCN":"民族的，种族的","tag":"高频","root":"","exampleEN":"The city is known for its rich ethnic diversity and multicultural festivals.","exampleCN":"这座城市以丰富的民族多样性和多元文化节日而闻名。","extra":"搭配：an ethnic minority 少数民族"},{"chapter":15,"key":"15:86","id":86,"word":"racial","phonetic":"/'reɪʃəl/","pos":"adj.","meaningCN":"种族的，人种的","tag":"核心","root":"","exampleEN":"Laws have been passed to prevent racial discrimination in the workplace.","exampleCN":"已经通过了法律来防止工作场所的种族歧视。","extra":"race n. 人种，种族；搭配：racial equality 种族平等"},{"chapter":15,"key":"15:87","id":87,"word":"clan","phonetic":"/klæn/","pos":"n.","meaningCN":"宗族，家族；帮派","tag":"低频","root":"","exampleEN":"In some rural areas, the whole clan still lives together in large family compounds.","exampleCN":"在一些农村地区，整个宗族仍然一起居住在大宅院里。","extra":"搭配：rival clans 敌对的家族"},{"chapter":15,"key":"15:88","id":88,"word":"franchise","phonetic":"/'fræntʃaɪz/","pos":"v.","meaningCN":"出售......的特许经营权 n. 特许权；[the～] 选举权","tag":"低频","root":"","exampleEN":"The restaurant chain is expanding rapidly by franchising its brand across the country.","exampleCN":"这家连锁餐厅通过在全国范围内出售特许经营权迅速扩张。","extra":"franchiser n. 授予特许经营权者"},{"chapter":15,"key":"15:89","id":89,"word":"entitle","phonetic":"/ɪn'taɪtəl/","pos":"v.","meaningCN":"给......权利（或资格）；给......题名","tag":"高频","root":"","exampleEN":"This membership card entitles you to a 20% discount at all partner stores.","exampleCN":"凭此会员卡，你可享受所有合作商店八折的优惠。","extra":"搭配：be entitled to sth. / to do sth. 有获得某物/做某事的权利"},{"chapter":15,"key":"15:90","id":90,"word":"preference","phonetic":"/'prefərəns/","pos":"n.","meaningCN":"偏爱；优先权","tag":"核心","root":"","exampleEN":"When applying for the job, preference will be given to those with work experience.","exampleCN":"申请该工作时，有工作经验者将获得优先考虑。","extra":"prefer v. 偏好"},{"chapter":15,"key":"15:91","id":91,"word":"vote","phonetic":"/vəʊt/","pos":"n.","meaningCN":"选举权；投票 v. 表决，投票","tag":"核心","root":"","exampleEN":"Citizens over the age of 18 are eligible to vote in the general election.","exampleCN":"年满18岁的公民有资格在大选中投票。","extra":"搭配：vote against 投票反对"},{"chapter":15,"key":"15:92","id":92,"word":"poll","phonetic":"/pəʊl/","pos":"n.","meaningCN":"民意调查；选举投票；投票数","tag":"核心","root":"poll 原指“人头税”","exampleEN":"The latest opinion poll suggests that the two parties are almost tied.","exampleCN":"最新的民意调查显示两党的支持率几乎不相上下。","extra":"搭配：carry out / conduct a poll 进行民意调查"},{"chapter":15,"key":"15:93","id":93,"word":"respondent","phonetic":"/rɪ'spɒndənt/","pos":"n.","meaningCN":"（民意测验等的）调查对象","tag":"低频","root":"","exampleEN":"More than 80% of respondents said they were satisfied with the local health services.","exampleCN":"超过八成的调查对象表示，他们对当地的卫生服务感到满意。","extra":""},{"chapter":15,"key":"15:94","id":94,"word":"election","phonetic":"/ɪ'lekʃən/","pos":"n.","meaningCN":"选举；当选","tag":"核心","root":"","exampleEN":"The election will be held on the first Sunday of November as usual.","exampleCN":"选举将像往年一样在十一月的第一个星期日举行。","extra":"elective adj. 选任的 n. 选修课"},{"chapter":15,"key":"15:95","id":95,"word":"ambition","phonetic":"/æm'bɪʃən/","pos":"n.","meaningCN":"雄心，抱负","tag":"核心","root":"ambit（到处走动）→ 古罗马政治家四处演讲拉选票","exampleEN":"Her ambition to become a doctor came from watching her father treat patients.","exampleCN":"她想成为医生的抱负源于看到父亲为病人诊治。","extra":"ambitious adj. 有雄心的；有野心的"},{"chapter":15,"key":"15:96","id":96,"word":"nominate","phonetic":"/'nɒmɪneɪt/","pos":"v.","meaningCN":"提名；任命","tag":"高频","root":"","exampleEN":"He was nominated for the best actor award for his role in the war film.","exampleCN":"他因在那部战争片中的角色被提名最佳男演员奖。","extra":"nomination n. 提名；任命；搭配：nominate sb. for 提名某人为……的候选人"},{"chapter":15,"key":"15:97","id":97,"word":"checklist","phonetic":"/'tʃeklɪst/","pos":"n.","meaningCN":"清单；选民花名册","tag":"高频","root":"","exampleEN":"Before travelling, she made a checklist of everything she needed to pack.","exampleCN":"旅行前，她列了一份需要打包的所有物品的清单。","extra":""},{"chapter":15,"key":"15:98","id":98,"word":"succession","phonetic":"/sək'seʃən/","pos":"n.","meaningCN":"连续；继承权，继位","tag":"高频","root":"","exampleEN":"The company has won the industry award for three years in succession.","exampleCN":"该公司已连续三年获得行业大奖。","extra":"successive adj. 连续的；搭配：claim the succession 要求拥有继承权"},{"chapter":15,"key":"15:99","id":99,"word":"safety","phonetic":"/'seɪfti/","pos":"n.","meaningCN":"安全；安全场所","tag":"核心","root":"","exampleEN":"Wearing a seat belt is one of the simplest ways to improve road safety.","exampleCN":"系安全带是提高道路安全最简单的方法之一。","extra":"搭配：personal safety 个人安全"},{"chapter":15,"key":"15:100","id":100,"word":"welfare","phonetic":"/'welfeə/","pos":"n.","meaningCN":"健康，幸福","tag":"核心","root":"","exampleEN":"The government spends a large part of its budget on health and social welfare.","exampleCN":"政府把预算的一大部分花在了医疗和社会福利上。","extra":"搭配：social welfare 社会福利"},{"chapter":15,"key":"15:101","id":101,"word":"well-being","phonetic":"/ˌwel'biːɪŋ/","pos":"n.","meaningCN":"康乐，安宁","tag":"高频","root":"","exampleEN":"Spending time outdoors has been shown to improve both physical and mental well-being.","exampleCN":"花时间在户外已被证实能改善身心健康。","extra":""},{"chapter":15,"key":"15:102","id":102,"word":"hint","phonetic":"/hɪnt/","pos":"v./n.","meaningCN":"暗示，提示","tag":"高频","root":"","exampleEN":"She dropped a few hints about what she wanted for her birthday.","exampleCN":"她对自己想要什么生日礼物给出了一些暗示。","extra":"搭配：give a hint 暗示，示意；take a hint 领会，明白"},{"chapter":15,"key":"15:103","id":103,"word":"declare","phonetic":"/dɪ'kleə/","pos":"v.","meaningCN":"宣布，宣告；宣称，声称","tag":"核心","root":"","exampleEN":"The country declared its independence from colonial rule in 1947.","exampleCN":"该国于1947年宣布脱离殖民统治而独立。","extra":"declaration n. 宣言；宣布；搭配：declare for 声明赞成"},{"chapter":15,"key":"15:104","id":104,"word":"affirm","phonetic":"/ə'fɜːm/","pos":"v.","meaningCN":"断言，坚持声称；证实","tag":"高频","root":"","exampleEN":"The court affirmed the earlier decision and refused the appeal.","exampleCN":"法院维持了早先的判决，驳回了上诉。","extra":"affirmative adj. 肯定的，同意的；搭配：affirm a view 证实某个观点"},{"chapter":15,"key":"15:105","id":105,"word":"claim","phonetic":"/kleɪm/","pos":"n.","meaningCN":"声称；主张；索赔 v. 声称；要求（拥有）","tag":"核心","root":"","exampleEN":"The insurance company will process your claim within two weeks of receiving the form.","exampleCN":"保险公司将在收到表格后的两周内处理你的索赔。","extra":"搭配：make a claim for 提出索取……的要求"},{"chapter":15,"key":"15:106","id":106,"word":"proclaim","phonetic":"/prə'kleɪm/","pos":"v.","meaningCN":"声明；清楚地表明","tag":"高频","root":"","exampleEN":"The president proclaimed a national day of celebration after the peace agreement.","exampleCN":"和平协议达成后，总统宣布了一个全国庆祝日。","extra":""},{"chapter":15,"key":"15:107","id":107,"word":"state","phonetic":"/steɪt/","pos":"v.","meaningCN":"陈述，说明 n. 国家；州；状况","tag":"核心","root":"","exampleEN":"The report clearly states that more research is needed before a decision can be made.","exampleCN":"报告清楚地说明，在做决定之前需要进行更多的研究。","extra":"statement n. 声明，陈述；搭配：state one's view 陈述某人的观点"},{"chapter":15,"key":"15:108","id":108,"word":"announce","phonetic":"/ə'naʊns/","pos":"v.","meaningCN":"宣布；通知","tag":"核心","root":"","exampleEN":"The company announced plans to open 20 new stores across the country next year.","exampleCN":"公司宣布了明年在全国开设20家新门店的计划。","extra":"搭配：announce sth. to sb. 对某人宣布某事"},{"chapter":15,"key":"15:109","id":109,"word":"clarify","phonetic":"/'klærɪfaɪ/","pos":"v.","meaningCN":"澄清，阐明","tag":"核心","root":"","exampleEN":"The spokesperson held a press conference to clarify the government's new policy.","exampleCN":"发言人举行了一场新闻发布会来阐明政府的新政策。","extra":"clarification n. 净化；澄清；搭配：clarify a situation 澄清情况"},{"chapter":15,"key":"15:110","id":110,"word":"assist","phonetic":"/ə'sɪst/","pos":"v.","meaningCN":"帮助，协助","tag":"核心","root":"","exampleEN":"Volunteers were sent to the disaster area to assist with the rescue efforts.","exampleCN":"志愿者被派往灾区协助救援工作。","extra":"assistant n. 助手，助理；搭配：assist mutually 相互帮助"},{"chapter":15,"key":"15:111","id":111,"word":"aid","phonetic":"/eɪd/","pos":"n.","meaningCN":"救援物资；辅助物；救助","tag":"核心","root":"","exampleEN":"International aid organisations quickly responded to the earthquake emergency.","exampleCN":"国际援助组织对这次地震紧急情况作出了快速反应。","extra":"搭配：first aid 急救；live on government aid 靠政府救济生活"},{"chapter":15,"key":"15:112","id":112,"word":"encourage","phonetic":"/ɪn'kʌrɪdʒ/","pos":"v.","meaningCN":"鼓励，激励；怂恿","tag":"核心","root":"","exampleEN":"Parents should encourage their children to try new things and not fear failure.","exampleCN":"父母应该鼓励孩子们尝试新事物，不要害怕失败。","extra":"courage n. 勇气；搭配：encourage sb. to do sth. 鼓励某人做某事"},{"chapter":15,"key":"15:113","id":113,"word":"implement","phonetic":"v. /'ɪmplɪment/ n. /'ɪmplɪmənt/","pos":"v.","meaningCN":"实施，执行 n. 工具，器具","tag":"核心","root":"","exampleEN":"The new manager implemented a series of changes to improve team efficiency.","exampleCN":"新经理实施了一系列变革以提高团队效率。","extra":"implementation n. 执行；搭配：implement a plan 执行计划"},{"chapter":15,"key":"15:114","id":114,"word":"monitor","phonetic":"/'mɒnɪtə/","pos":"v.","meaningCN":"监视；监听 n. 监控器；监视器；班长","tag":"核心","root":"","exampleEN":"The doctor will monitor the patient's condition for any signs of improvement.","exampleCN":"医生将密切监测病人的状况，看是否有任何好转的迹象。","extra":"搭配：monitor closely 严密监视"},{"chapter":15,"key":"15:115","id":115,"word":"admit","phonetic":"/əd'mɪt/","pos":"v.","meaningCN":"供认，承认","tag":"核心","root":"","exampleEN":"He finally admitted that he had made a mistake and apologised to the team.","exampleCN":"他终于承认自己犯了错误，并向团队道歉。","extra":"admission n. 承认；入场费；准许进入"},{"chapter":15,"key":"15:116","id":116,"word":"African","phonetic":"/'æfrɪkən/","pos":"adj.","meaningCN":"非洲的 n. 非洲人","tag":"核心","root":"","exampleEN":"She is studying African literature and hopes to visit Nigeria next year.","exampleCN":"她正在研究非洲文学，并希望明年去尼日利亚。","extra":"Africa n. 非洲；搭配：an African American 非裔美国人"},{"chapter":15,"key":"15:117","id":117,"word":"European","phonetic":"/ˌjʊərə'piːən/","pos":"adj.","meaningCN":"欧洲的 n. 欧洲人","tag":"核心","root":"","exampleEN":"Many European countries use the euro as their official currency.","exampleCN":"许多欧洲国家都把欧元用作官方货币。","extra":"Europe n. 欧洲；euro n. 欧元"},{"chapter":15,"key":"15:118","id":118,"word":"Latin","phonetic":"/'lætɪn/","pos":"adj.","meaningCN":"拉丁语的；拉丁人的 n. 拉丁语；拉丁人","tag":"低频","root":"","exampleEN":"A large number of English words are derived from Latin roots.","exampleCN":"大量的英语单词都源自拉丁语词根。","extra":""},{"chapter":15,"key":"15:119","id":119,"word":"Jewish","phonetic":"/'dʒuːɪʃ/","pos":"adj.","meaningCN":"犹太教的；犹太人的","tag":"高频","root":"","exampleEN":"They visited the Jewish quarter to learn more about the city's cultural history.","exampleCN":"他们参观了犹太区，以了解更多这座城市的文化历史。","extra":""},{"chapter":15,"key":"15:120","id":120,"word":"Arabian","phonetic":"/ə'reɪbiən/","pos":"adj.","meaningCN":"阿拉伯的","tag":"低频","root":"","exampleEN":"The stories of the Arabian Nights have been translated into dozens of languages.","exampleCN":"《一千零一夜》的故事已被翻译成数十种语言。","extra":""},{"chapter":15,"key":"15:121","id":121,"word":"Portuguese","phonetic":"/ˌpɔːtʃʊ'ɡiːz/","pos":"adj.","meaningCN":"葡萄牙的 n. 葡萄牙语；葡萄牙人","tag":"低频","root":"","exampleEN":"Portuguese is the official language of both Portugal and Brazil.","exampleCN":"葡萄牙语是葡萄牙和巴西两国的官方语言。","extra":""},{"chapter":15,"key":"15:122","id":122,"word":"Roman","phonetic":"/'rəʊmən/","pos":"adj.","meaningCN":"罗马的；古罗马帝国的 n. 古罗马人；（现代）罗马市民","tag":"高频","root":"","exampleEN":"The Roman Empire once stretched from Britain to parts of Africa and Asia.","exampleCN":"罗马帝国曾经从不列颠延伸到非洲和亚洲的部分地区。","extra":""},{"chapter":15,"key":"15:123","id":123,"word":"Russian","phonetic":"/'rʌʃən/","pos":"adj.","meaningCN":"俄罗斯的 n. 俄罗斯人；俄语","tag":"核心","root":"","exampleEN":"He is taking Russian lessons because he plans to work in Moscow next year.","exampleCN":"他正在上俄语课，因为他明年计划去莫斯科工作。","extra":"Russia n. 俄罗斯"},{"chapter":15,"key":"15:124","id":124,"word":"Spanish","phonetic":"/'spænɪʃ/","pos":"adj.","meaningCN":"西班牙的 n. 西班牙语；西班牙人","tag":"核心","root":"","exampleEN":"Spanish is the second most spoken language in the world by native speakers.","exampleCN":"以母语使用者人数计，西班牙语是世界上第二大语言。","extra":"Spain n. 西班牙"},{"chapter":15,"key":"15:125","id":125,"word":"Swiss","phonetic":"/swɪs/","pos":"adj.","meaningCN":"瑞士的 n. 瑞士人","tag":"高频","root":"","exampleEN":"Swiss watches are famous around the world for their accuracy and fine design.","exampleCN":"瑞士手表以其精准和精美设计而闻名于世。","extra":"Switzerland n. 瑞士"},{"chapter":15,"key":"15:126","id":126,"word":"Greek","phonetic":"/ɡriːk/","pos":"adj.","meaningCN":"希腊的 n. 希腊人；古希腊人；希腊语；古希腊语","tag":"高频","root":"","exampleEN":"Greek myths, such as the story of Pandora, still influence modern culture.","exampleCN":"如潘多拉的故事等希腊神话仍然影响着现代文化。","extra":"Greece n. 希腊"},{"chapter":15,"key":"15:127","id":127,"word":"Italian","phonetic":"/ɪ'tæliən/","pos":"adj.","meaningCN":"意大利的 n. 意大利人；意大利语","tag":"核心","root":"","exampleEN":"Italian cuisine is much more than just pizza and pasta; it varies by region.","exampleCN":"意大利美食远不止比萨和意大利面，不同地区各有特色。","extra":"Italy n. 意大利"},{"chapter":15,"key":"15:128","id":128,"word":"soviet","phonetic":"/'səʊviət/","pos":"adj.","meaningCN":"[S-] 苏联的 n. 苏维埃","tag":"低频","root":"","exampleEN":"The Soviet Union played a major part in the history of the 20th century.","exampleCN":"苏联在20世纪的历史中扮演了重要角色。","extra":""},{"chapter":15,"key":"15:129","id":129,"word":"Indian","phonetic":"/'ɪndiən/","pos":"adj.","meaningCN":"印度的 n. 印度人","tag":"核心","root":"","exampleEN":"Indian films, especially those from Bollywood, have a large international audience.","exampleCN":"印度电影，尤其是宝莱坞影片，拥有广大的国际观众。","extra":"India n. 印度"},{"chapter":15,"key":"15:130","id":130,"word":"Australia","phonetic":"/ɒ'streɪliə/","pos":"n.","meaningCN":"澳大利亚","tag":"核心","root":"","exampleEN":"Australia is known for its unique wildlife, including kangaroos and koalas.","exampleCN":"澳大利亚以其独特的野生动物闻名，包括袋鼠和考拉。","extra":"Australian adj. 澳大利亚的 n. 澳大利亚人"},{"chapter":15,"key":"15:131","id":131,"word":"New Zealand","phonetic":"/njuː 'ziːlənd/","pos":"n.","meaningCN":"新西兰","tag":"核心","root":"","exampleEN":"New Zealand attracts many tourists each year because of its amazing natural landscapes.","exampleCN":"新西兰因其令人惊叹的自然风光每年吸引众多游客。","extra":""},{"chapter":15,"key":"15:132","id":132,"word":"Canada","phonetic":"/'kænədə/","pos":"n.","meaningCN":"加拿大","tag":"核心","root":"","exampleEN":"Canada is officially a bilingual country, with English and French as national languages.","exampleCN":"加拿大是官方双语国家，英语和法语均为国家语言。","extra":"Canadian adj. 加拿大的 n. 加拿大人"},{"chapter":15,"key":"15:133","id":133,"word":"Britain","phonetic":"/'brɪtən/","pos":"n.","meaningCN":"不列颠","tag":"核心","root":"","exampleEN":"Industrialisation first began in Britain in the late 18th century.","exampleCN":"工业化在18世纪末最早始于英国。","extra":"British adj. 英国的 n. 英国人"},{"chapter":15,"key":"15:134","id":134,"word":"France","phonetic":"/frɑːns/","pos":"n.","meaningCN":"法国","tag":"核心","root":"","exampleEN":"France is visited by more tourists than any other country in the world.","exampleCN":"法国接待的游客数量超过世界上任何其他国家。","extra":"French n. 法语 adj. 法国的"},{"chapter":15,"key":"15:135","id":135,"word":"Germany","phonetic":"/'dʒɜːməni/","pos":"n.","meaningCN":"德国","tag":"核心","root":"","exampleEN":"Germany has the largest economy in Europe and is a leading exporter.","exampleCN":"德国拥有欧洲最大的经济体，是一个主要的出口国。","extra":"German n. 德国人；德语 adj. 德国的"}],"16":[{"chapter":16,"key":"16:1","id":1,"word":"economy","phonetic":"/iˈkɒnəmi/","pos":"n.","meaningCN":"经济；节约","tag":"核心","root":"","exampleEN":"The global economy has been recovering slowly since the recent crisis.","exampleCN":"自最近的危机以来，全球经济一直在缓慢复苏。","extra":"economic adj. 经济的；economical adj. 节约的；economics n. 经济学"},{"chapter":16,"key":"16:2","id":2,"word":"trade","phonetic":"/treɪd/","pos":"n.","meaningCN":"贸易 v. 交换","tag":"核心","root":"","exampleEN":"International trade plays a crucial role in the development of many countries.","exampleCN":"国际贸易在许多国家的发展中起着至关重要的作用。","extra":"搭配：develop trade, encourage trade, global trade"},{"chapter":16,"key":"16:3","id":3,"word":"market","phonetic":"/ˈmɑːkɪt/","pos":"n.","meaningCN":"市场；市场需求","tag":"核心","root":"","exampleEN":"The housing market in this city has become increasingly competitive.","exampleCN":"这个城市的住房市场竞争变得越来越激烈。","extra":""},{"chapter":16,"key":"16:4","id":4,"word":"industry","phonetic":"/ˈɪndəstri/","pos":"n.","meaningCN":"工业；产业；勤劳","tag":"核心","root":"","exampleEN":"The tourism industry provides millions of jobs around the world.","exampleCN":"旅游业在全球提供了数百万个就业岗位。","extra":"industrialise/industrialize v. 使工业化；industrial adj. 工业的；搭配：heavy industry"},{"chapter":16,"key":"16:5","id":5,"word":"merchant","phonetic":"/ˈmɜːtʃənt/","pos":"n.","meaningCN":"商人 adj. 商业的","tag":"高频","root":"","exampleEN":"The merchant travelled from town to town selling spices and fabrics.","exampleCN":"那个商人从一个城镇走到另一个城镇，出售香料和布料。","extra":"搭配：a retail merchant"},{"chapter":16,"key":"16:6","id":6,"word":"financial","phonetic":"/faɪˈnænʃəl/","pos":"adj.","meaningCN":"财政的；金融的","tag":"核心","root":"","exampleEN":"Many families faced serious financial difficulties during the recession.","exampleCN":"许多家庭在经济衰退期间面临严重的经济困难。","extra":"finance n. 金融；财政"},{"chapter":16,"key":"16:7","id":7,"word":"fund","phonetic":"/fʌnd/","pos":"v.","meaningCN":"资助 n. 基金；[-s] 资金","tag":"核心","root":"","exampleEN":"The project is fully funded by private donations and government grants.","exampleCN":"该项目完全由私人捐款和政府拨款资助。","extra":"搭配：raise funds"},{"chapter":16,"key":"16:8","id":8,"word":"donate","phonetic":"/dəʊˈneɪt/","pos":"v.","meaningCN":"捐赠，捐献","tag":"高频","root":"","exampleEN":"After the earthquake, people from all over the world donated clothes and food.","exampleCN":"地震过后，世界各地的人们捐赠了衣物和食品。","extra":"donation n. 捐赠"},{"chapter":16,"key":"16:9","id":9,"word":"endow","phonetic":"/ɪnˈdaʊ/","pos":"v.","meaningCN":"捐赠；赋予","tag":"低频","root":"","exampleEN":"Nature has endowed this region with rich mineral resources.","exampleCN":"大自然赋予了该地区丰富的矿产资源。","extra":"endowment n. 捐赠，捐款；天赋"},{"chapter":16,"key":"16:10","id":10,"word":"commercial","phonetic":"/kəˈmɜːʃəl/","pos":"adj.","meaningCN":"商业的 n. 商业广告","tag":"核心","root":"","exampleEN":"The commercial area of the city is always busy during the daytime.","exampleCN":"市区的商业地段白天总是很繁忙。","extra":"commercialise/commercialize v. 使商业化"},{"chapter":16,"key":"16:11","id":11,"word":"advertise","phonetic":"/ˈædvətaɪz/","pos":"v.","meaningCN":"做广告","tag":"高频","root":"","exampleEN":"They decided to advertise the new product on social media to reach more people.","exampleCN":"他们决定在社交媒体上为新产品的投放广告，以触达更多人。","extra":"advertisement/ad n. 广告；advertising n. 广告业"},{"chapter":16,"key":"16:12","id":12,"word":"slogan","phonetic":"/ˈsləʊɡən/","pos":"n.","meaningCN":"标语，口号","tag":"高频","root":"","exampleEN":"The campaign’s slogan was “Yes We Can,” which inspired many voters.","exampleCN":"那场竞选的口号是“是的，我们能做到”，鼓舞了许多选民。","extra":"搭配：shout slogans"},{"chapter":16,"key":"16:13","id":13,"word":"purchase","phonetic":"/ˈpɜːtʃɪs/","pos":"n./v.","meaningCN":"购买","tag":"核心","root":"","exampleEN":"Online shopping makes it easy to purchase goods from all over the world.","exampleCN":"网上购物使从世界各地购买商品变得容易。","extra":"搭配：purchase by"},{"chapter":16,"key":"16:14","id":14,"word":"lease","phonetic":"/liːs/","pos":"n.","meaningCN":"租约 v. 出租；租用","tag":"高频","root":"","exampleEN":"They signed a two-year lease on the office space in the city centre.","exampleCN":"他们签了一份为期两年的市中心办公场所租约。","extra":"leaseholder n. 租赁人"},{"chapter":16,"key":"16:15","id":15,"word":"afford","phonetic":"/əˈfɔːd/","pos":"v.","meaningCN":"负担得起；提供，给予","tag":"核心","root":"","exampleEN":"With the rising cost of living, many young people cannot afford to buy a house.","exampleCN":"随着生活成本的上升，许多年轻人买不起房子。","extra":"affordable adj. 买得起的"},{"chapter":16,"key":"16:16","id":16,"word":"retail","phonetic":"/ˈriːteɪl/","pos":"n.","meaningCN":"零售 v. 零售；以......价格零售","tag":"核心","root":"","exampleEN":"The retail sector has been transformed by the growth of e-commerce.","exampleCN":"电子商务的增长改变了零售业。","extra":"retailing n. 零售业；retailer n. 零售商；搭配：a retail outlet"},{"chapter":16,"key":"16:17","id":17,"word":"chain","phonetic":"/tʃeɪn/","pos":"n.","meaningCN":"连锁店；一连串","tag":"核心","root":"","exampleEN":"This fast-food chain has restaurants in over fifty countries.","exampleCN":"这家快餐连锁店在五十多个国家设有餐厅。","extra":"a chain reaction 连锁反应"},{"chapter":16,"key":"16:18","id":18,"word":"grocery","phonetic":"/ˈɡrəʊsəri/","pos":"n.","meaningCN":"食品杂货店","tag":"高频","root":"","exampleEN":"She stopped at the grocery on her way home to buy some bread and milk.","exampleCN":"她在回家的路上顺便去了杂货店，买了些面包和牛奶。","extra":""},{"chapter":16,"key":"16:19","id":19,"word":"discount","phonetic":"/ˈdɪskaʊnt/ n. /dɪsˈkaʊnt/ v.","pos":"n.","meaningCN":"折扣","tag":"核心","root":"dis（不）+ count（数）→ 没有计算在内的 → 折扣","exampleEN":"Students can get a 15% discount on tickets by showing their ID card.","exampleCN":"学生出示身份证买票可以享受15%的折扣。","extra":"discounter n. 折扣商店；搭配：a 20% discount"},{"chapter":16,"key":"16:20","id":20,"word":"promotion","phonetic":"/prəˈməʊʃən/","pos":"n.","meaningCN":"促销活动；晋升","tag":"核心","root":"","exampleEN":"After years of hard work, she finally got the promotion she deserved.","exampleCN":"经过多年的努力工作，她终于得到了应有的晋升。","extra":"promote v. 促销；晋升；促进"},{"chapter":16,"key":"16:21","id":21,"word":"voucher","phonetic":"/ˈvaʊtʃə/","pos":"n.","meaningCN":"代金券","tag":"高频","root":"","exampleEN":"The travel agency gave each customer a voucher worth fifty dollars.","exampleCN":"旅行社给了每位顾客一张价值五十美元的代金券。","extra":""},{"chapter":16,"key":"16:22","id":22,"word":"coupon","phonetic":"/ˈkuːpɒn/","pos":"n.","meaningCN":"优惠券","tag":"高频","root":"","exampleEN":"I used a 30%-off coupon to buy this pair of shoes at a much lower price.","exampleCN":"我用了一张七折优惠券，以低得多的价格买下了这双鞋。","extra":""},{"chapter":16,"key":"16:23","id":23,"word":"currency","phonetic":"/ˈkʌrənsi/","pos":"n.","meaningCN":"货币；通用，流行","tag":"核心","root":"","exampleEN":"The euro is the official currency in many European countries.","exampleCN":"欧元是许多欧洲国家的官方货币。","extra":"搭配：change foreign currency, issue currency"},{"chapter":16,"key":"16:24","id":24,"word":"exchange","phonetic":"/ɪksˈtʃeɪndʒ/","pos":"n.","meaningCN":"交换；兑换","tag":"核心","root":"","exampleEN":"Cultural exchange programmes help students learn about different lifestyles.","exampleCN":"文化交流项目帮助学生了解不同的生活方式。","extra":"搭配：foreign exchange, academic/athletic/cultural exchange"},{"chapter":16,"key":"16:25","id":25,"word":"swap","phonetic":"/swɒp/","pos":"v./n.","meaningCN":"交换","tag":"高频","root":"","exampleEN":"Let's swap our lunch boxes so we can try something different.","exampleCN":"我们交换一下午餐盒吧，这样就能尝尝不同的东西。","extra":"也作 swop"},{"chapter":16,"key":"16:26","id":26,"word":"receipt","phonetic":"/rɪˈsiːt/","pos":"n.","meaningCN":"收据；收到","tag":"核心","root":"","exampleEN":"Always keep the receipt in case you need to return the product later.","exampleCN":"务必保留收据，以备日后需要退货。","extra":"receive v. 接收；搭配：make out a receipt"},{"chapter":16,"key":"16:27","id":27,"word":"invoice","phonetic":"/ˈɪnvɔɪs/","pos":"n.","meaningCN":"发票 v. 开发票给","tag":"高频","root":"","exampleEN":"The supplier sent us an invoice for the office equipment we ordered.","exampleCN":"供应商给我们发来了所订购办公设备的发票。","extra":""},{"chapter":16,"key":"16:28","id":28,"word":"tax","phonetic":"/tæks/","pos":"n.","meaningCN":"税 v. 对......征税","tag":"核心","root":"","exampleEN":"The government plans to raise taxes on luxury goods next year.","exampleCN":"政府计划明年对奢侈品增税。","extra":"taxation n. 征税；税；搭配：tax heavily"},{"chapter":16,"key":"16:29","id":29,"word":"levy","phonetic":"/ˈlevi/","pos":"n.","meaningCN":"税款 v. 征收，征（税）","tag":"低频","root":"","exampleEN":"A new levy on sugary drinks was introduced to improve public health.","exampleCN":"为了改善公共健康，对含糖饮料征收了一项新税。","extra":"搭配：impose a levy on sth."},{"chapter":16,"key":"16:30","id":30,"word":"tariff","phonetic":"/ˈtærɪf/","pos":"n.","meaningCN":"关税；（公共服务的）收费","tag":"高频","root":"","exampleEN":"Import tariffs on steel have been reduced to encourage international trade.","exampleCN":"钢铁的进口关税已被降低以鼓励国际贸易。","extra":""},{"chapter":16,"key":"16:31","id":31,"word":"duty","phonetic":"/ˈdjuːti/","pos":"n.","meaningCN":"职责；义务；关税","tag":"核心","root":"","exampleEN":"It is every citizen's duty to follow the laws of the country.","exampleCN":"遵守国家法律是每个公民的义务。","extra":"dutiable adj. 应纳税的；搭配：be exempt from duty"},{"chapter":16,"key":"16:32","id":32,"word":"impose","phonetic":"/ɪmˈpəʊz/","pos":"v.","meaningCN":"强加；征收（税款）","tag":"高频","root":"pose = 放置 → impose = 放在上面 → 强加","exampleEN":"The new rule will impose additional pressure on small businesses.","exampleCN":"新规定将给小企业带来额外的压力。","extra":"搭配：impose a penalty, impose a tax"},{"chapter":16,"key":"16:33","id":33,"word":"consume","phonetic":"/kənˈsjuːm/","pos":"v.","meaningCN":"消耗；吃，喝","tag":"核心","root":"","exampleEN":"Homes consume almost half of all electricity produced in the country.","exampleCN":"家庭消耗了该国生产的近一半的电力。","extra":"consumption n. 消费；消耗量"},{"chapter":16,"key":"16:34","id":34,"word":"spend","phonetic":"/spend/","pos":"v.","meaningCN":"花费 n. 开支","tag":"核心","root":"","exampleEN":"She prefers to spend her weekends reading at home rather than going out.","exampleCN":"她周末宁可在家看书也不愿外出。","extra":"搭配：spend time/money on sth., spend time/money (in) doing sth."},{"chapter":16,"key":"16:35","id":35,"word":"cost","phonetic":"/kɒst/","pos":"v.","meaningCN":"需付费 n. 费用；代价；[-s] 成本","tag":"核心","root":"","exampleEN":"The new software cost the company far less than expected.","exampleCN":"新软件的花费比公司预期的少得多。","extra":"costly adj. 昂贵的；cost-effective adj. 划算的；搭配：at a cost of, the cost of living"},{"chapter":16,"key":"16:36","id":36,"word":"expense","phonetic":"/ɪkˈspens/","pos":"n.","meaningCN":"费用，花费","tag":"核心","root":"","exampleEN":"Studying abroad can be a huge expense, but many believe it is worth it.","exampleCN":"出国留学可能是一笔很大的开销，但许多人认为这是值得的。","extra":"expensive adj. 昂贵的"},{"chapter":16,"key":"16:37","id":37,"word":"revenue","phonetic":"/ˈrevənjuː/","pos":"n.","meaningCN":"（公司、组织的）收入；（政府的）税收","tag":"核心","root":"","exampleEN":"Advertising is the main source of revenue for many free websites.","exampleCN":"广告是许多免费网站的主要收入来源。","extra":"搭配：a revenue officer, tax revenue"},{"chapter":16,"key":"16:38","id":38,"word":"gross","phonetic":"/ɡrəʊs/","pos":"adj.","meaningCN":"总的，毛的","tag":"高频","root":"","exampleEN":"GDP, or Gross Domestic Product, measures the total value of goods produced.","exampleCN":"GDP，即国内生产总值，衡量所生产商品的总价值。","extra":"搭配：Gross National Product (GNP)"},{"chapter":16,"key":"16:39","id":39,"word":"recession","phonetic":"/rɪˈseʃən/","pos":"n.","meaningCN":"经济衰退","tag":"核心","root":"re（往回）+ cess（走）+ ion → 往回走 → 衰退","exampleEN":"Thousands of people lost their jobs during the severe economic recession.","exampleCN":"在严重的经济衰退期间，成千上万的人失去了工作。","extra":"recess v. 暂停，休会"},{"chapter":16,"key":"16:40","id":40,"word":"depression","phonetic":"/dɪˈpreʃən/","pos":"n.","meaningCN":"沮丧；萧条期","tag":"核心","root":"","exampleEN":"The Great Depression of the 1930s had a profound impact on the world economy.","exampleCN":"20世纪30年代的大萧条对世界经济产生了深远影响。","extra":"depress v. 使沮丧；使萧条"},{"chapter":16,"key":"16:41","id":41,"word":"crisis","phonetic":"/ˈkraɪsɪs/","pos":"n.","meaningCN":"危机","tag":"核心","root":"","exampleEN":"Effective leadership is crucial when a company faces a major crisis.","exampleCN":"公司面临重大危机时，有效的领导力至关重要。","extra":"搭配：aggravate/avert/cause/ease/face/overcome a crisis"},{"chapter":16,"key":"16:42","id":42,"word":"security","phonetic":"/sɪˈkjʊərəti/","pos":"n.","meaningCN":"安全工作；安全；[securities] 证券","tag":"核心","root":"","exampleEN":"Airport security checks have become much stricter in recent years.","exampleCN":"近年来机场安检变得严格多了。","extra":"搭配：the Security Council"},{"chapter":16,"key":"16:43","id":43,"word":"bond","phonetic":"/bɒnd/","pos":"n.","meaningCN":"债券","tag":"低频","root":"","exampleEN":"Government bonds are generally considered a relatively safe investment.","exampleCN":"政府债券通常被认为是一种相对安全的投资。","extra":""},{"chapter":16,"key":"16:44","id":44,"word":"debt","phonetic":"/det/","pos":"n.","meaningCN":"债务","tag":"核心","root":"","exampleEN":"The company had to borrow money and is now deep in debt.","exampleCN":"那家公司不得不借钱，现在已经债台高筑。","extra":"搭配：clear a debt, owe sb. a debt"},{"chapter":16,"key":"16:45","id":45,"word":"deficit","phonetic":"/ˈdefɪsɪt/","pos":"n.","meaningCN":"赤字，逆差","tag":"高频","root":"","exampleEN":"The country's trade deficit has widened because imports have increased sharply.","exampleCN":"由于进口大幅增加，该国的贸易逆差扩大了。","extra":""},{"chapter":16,"key":"16:46","id":46,"word":"inflation","phonetic":"/ɪnˈfleɪʃən/","pos":"n.","meaningCN":"通货膨胀","tag":"核心","root":"","exampleEN":"High inflation reduces the real value of people's savings.","exampleCN":"高通货膨胀会降低人们储蓄的实际价值。","extra":""},{"chapter":16,"key":"16:47","id":47,"word":"deflation","phonetic":"/diːˈfleɪʃən/","pos":"n.","meaningCN":"通货紧缩","tag":"低频","root":"","exampleEN":"Central banks often fear deflation because it can lead to a slowdown in the economy.","exampleCN":"央行常常担心通货紧缩，因为它可能导致经济放缓。","extra":""},{"chapter":16,"key":"16:48","id":48,"word":"dwindle","phonetic":"/ˈdwɪndl/","pos":"v.","meaningCN":"缩小，减少","tag":"高频","root":"","exampleEN":"The freshwater supply on the island is dwindling due to the long drought.","exampleCN":"由于长期干旱，岛上的淡水供应正逐渐减少。","extra":"搭配：dwindle away"},{"chapter":16,"key":"16:49","id":49,"word":"decrease","phonetic":"/ˈdiːkriːs/ n. /dɪˈkriːs/ v.","pos":"n.","meaningCN":"减少","tag":"核心","root":"","exampleEN":"Regular exercise can significantly decrease the risk of heart disease.","exampleCN":"经常锻炼可以显著降低患心脏病的风险。","extra":""},{"chapter":16,"key":"16:50","id":50,"word":"downsize","phonetic":"/ˈdaʊnsaɪz/","pos":"v.","meaningCN":"使精简；裁员","tag":"低频","root":"","exampleEN":"The automobile factory had to downsize its workforce due to falling sales.","exampleCN":"由于销量下降，那家汽车厂不得不裁员。","extra":""},{"chapter":16,"key":"16:51","id":51,"word":"decline","phonetic":"/dɪˈklaɪn/","pos":"v./n.","meaningCN":"下降","tag":"核心","root":"","exampleEN":"The population of the village has been in steady decline as young people move away.","exampleCN":"随着年轻人纷纷搬走，这个村庄的人口持续下降。","extra":"declination n. 倾斜；谢绝；搭配：decline steadily, moral decline"},{"chapter":16,"key":"16:52","id":52,"word":"diminish","phonetic":"/dɪˈmɪnɪʃ/","pos":"v.","meaningCN":"（使）减少；贬低","tag":"高频","root":"","exampleEN":"The pain in his knee gradually diminished after several days of rest.","exampleCN":"休息了几天之后，他膝盖的疼痛逐渐减轻了。","extra":"diminution n. 减少"},{"chapter":16,"key":"16:53","id":53,"word":"reduce","phonetic":"/rɪˈdjuːs/","pos":"v.","meaningCN":"减少，减小","tag":"核心","root":"","exampleEN":"We need to reduce the amount of sugar we consume on a daily basis.","exampleCN":"我们需要减少日常糖的摄入量。","extra":"reduction n. 减少"},{"chapter":16,"key":"16:54","id":54,"word":"increase","phonetic":"/ˈɪnkriːs/ n. /ɪnˈkriːs/ v.","pos":"n.","meaningCN":"增加","tag":"核心","root":"","exampleEN":"There has been a sharp increase in demand for electric cars recently.","exampleCN":"最近对电动汽车的需求急剧增加。","extra":"increasing adj. 日益增加的"},{"chapter":16,"key":"16:55","id":55,"word":"increment","phonetic":"/ˈɪnkrɪmənt/","pos":"n.","meaningCN":"增加量；定期的加薪","tag":"低频","root":"","exampleEN":"The salary is £25,000, with annual increments of £600 for the first five years.","exampleCN":"起薪为25000英镑，前五年每年加薪600英镑。","extra":"搭配：yearly/annual increment"},{"chapter":16,"key":"16:56","id":56,"word":"growth","phonetic":"/ɡrəʊθ/","pos":"n.","meaningCN":"增长；生长","tag":"核心","root":"","exampleEN":"Economic growth in the region is expected to reach 4% next year.","exampleCN":"预计该地区明年的经济增长将达到4%。","extra":"搭配：considerable growth, gradual growth"},{"chapter":16,"key":"16:57","id":57,"word":"escalate","phonetic":"/ˈeskəleɪt/","pos":"v.","meaningCN":"（使）逐步升级，（使）不断恶化","tag":"高频","root":"","exampleEN":"The dispute between the two countries escalated into a full-scale war.","exampleCN":"两国之间的争端逐步升级为一场全面战争。","extra":""},{"chapter":16,"key":"16:58","id":58,"word":"expand","phonetic":"/ɪkˈspænd/","pos":"v.","meaningCN":"扩充，扩大；扩展","tag":"核心","root":"","exampleEN":"The university plans to expand its library to make room for more students.","exampleCN":"大学计划扩建图书馆，以便容纳更多学生。","extra":"expansive adj. 广阔的；扩张的；搭配：expand contact, expand influence"},{"chapter":16,"key":"16:59","id":59,"word":"influx","phonetic":"/ˈɪnflʌks/","pos":"n.","meaningCN":"流入，涌进","tag":"低频","root":"","exampleEN":"The town experienced a sudden influx of tourists during the music festival.","exampleCN":"音乐节期间，小镇突然涌入了大量游客。","extra":"搭配：influx of capital"},{"chapter":16,"key":"16:60","id":60,"word":"affluent","phonetic":"/ˈæfluənt/","pos":"adj.","meaningCN":"富裕的，富足的","tag":"高频","root":"字根flu = 流 → affluent = 流向 → 富裕的","exampleEN":"She grew up in an affluent family and never had to worry about money.","exampleCN":"她在一个富裕的家庭长大，从不需要为钱发愁。","extra":""},{"chapter":16,"key":"16:61","id":61,"word":"enrich","phonetic":"/ɪnˈrɪtʃ/","pos":"v.","meaningCN":"使富有；充实","tag":"高频","root":"","exampleEN":"Reading can greatly enrich your knowledge and understanding of the world.","exampleCN":"阅读可以极大地丰富你的知识和对世界的理解。","extra":"enrichment n. 丰富；搭配：enrich the brain/mind"},{"chapter":16,"key":"16:62","id":62,"word":"sufficient","phonetic":"/səˈfɪʃənt/","pos":"adj.","meaningCN":"足够的","tag":"核心","root":"","exampleEN":"Make sure you get sufficient sleep before the exam to perform well.","exampleCN":"考试前要保证充足的睡眠，这样才会考出好成绩。","extra":"insufficient adj. 不足的"},{"chapter":16,"key":"16:63","id":63,"word":"adequate","phonetic":"/ˈædɪkwət/","pos":"adj.","meaningCN":"足够的；合格的","tag":"核心","root":"","exampleEN":"The company failed to provide adequate safety training for its employees.","exampleCN":"该公司未能为员工提供足够的安全培训。","extra":"inadequate adj. 不够格的"},{"chapter":16,"key":"16:64","id":64,"word":"spare","phonetic":"/speə/","pos":"adj.","meaningCN":"多余的，空闲的 v. 剩余","tag":"核心","root":"","exampleEN":"In his spare time, he enjoys playing the guitar and painting.","exampleCN":"空闲时间他喜欢弹吉他和画画。","extra":"搭配：spare no effort, spare time"},{"chapter":16,"key":"16:65","id":65,"word":"saving","phonetic":"/ˈseɪvɪŋ/","pos":"n.","meaningCN":"节约，节省","tag":"核心","root":"","exampleEN":"Buying in bulk can lead to significant savings over time.","exampleCN":"批量购买久而久之可以节省不少钱。","extra":"save v. 拯救；节约；保存"},{"chapter":16,"key":"16:66","id":66,"word":"redundant","phonetic":"/rɪˈdʌndənt/","pos":"adj.","meaningCN":"多余的；被裁减的","tag":"高频","root":"","exampleEN":"Several positions in the company became redundant after the merger.","exampleCN":"合并后，公司里有几个职位变得多余了。","extra":"redundancy n. 裁员；搭配：a redundant worker"},{"chapter":16,"key":"16:67","id":67,"word":"lack","phonetic":"/læk/","pos":"n.","meaningCN":"缺乏，不足 v. 缺少","tag":"核心","root":"","exampleEN":"A lack of communication is often the root cause of many relationship problems.","exampleCN":"缺乏沟通往往是许多关系问题的根源。","extra":"搭配：lack of"},{"chapter":16,"key":"16:68","id":68,"word":"company","phonetic":"/ˈkʌmpəni/","pos":"n.","meaningCN":"公司；陪伴；剧团","tag":"核心","root":"","exampleEN":"She enjoys working for a multinational company with offices all over the world.","exampleCN":"她喜欢在一家全球各地都设有办事处的跨国公司工作。","extra":"accompany v. 陪伴；搭配：keep sb. company"},{"chapter":16,"key":"16:69","id":69,"word":"firm","phonetic":"/fɜːm/","pos":"n.","meaningCN":"公司 adj. 坚定的；坚固的","tag":"核心","root":"","exampleEN":"After graduating, he joined a law firm in the city centre.","exampleCN":"毕业后，他加入了市中心的一家律师事务所。","extra":"搭配：firm faith"},{"chapter":16,"key":"16:70","id":70,"word":"enterprise","phonetic":"/ˈentəpraɪz/","pos":"n.","meaningCN":"企业；事业","tag":"核心","root":"","exampleEN":"She started her own enterprise at the age of 25 and it grew rapidly.","exampleCN":"她25岁时创办了自己的企业，企业发展很迅速。","extra":"entrepreneur n. 企业家；搭配：build/manage/run an enterprise"},{"chapter":16,"key":"16:71","id":71,"word":"agent","phonetic":"/ˈeɪdʒənt/","pos":"n.","meaningCN":"代理人，代理商","tag":"高频","root":"","exampleEN":"A real estate agent can help you find a suitable house more quickly.","exampleCN":"房地产经纪人能帮你更快地找到合适的房子。","extra":"搭配：sole agent"},{"chapter":16,"key":"16:72","id":72,"word":"entity","phonetic":"/ˈentəti/","pos":"n.","meaningCN":"实体，独立存在物","tag":"低频","root":"","exampleEN":"After the restructuring, the two departments became a single legal entity.","exampleCN":"重组后，这两个部门成为了一个独立的法人实体。","extra":"搭配：a business entity, an economic entity"},{"chapter":16,"key":"16:73","id":73,"word":"invest","phonetic":"/ɪnˈvest/","pos":"v.","meaningCN":"投资；投入","tag":"核心","root":"","exampleEN":"The government decided to invest heavily in renewable energy projects.","exampleCN":"政府决定大举投资可再生能源项目。","extra":"investment n. 投资；investor n. 投资者；搭配：invest in sth."},{"chapter":16,"key":"16:74","id":74,"word":"input","phonetic":"/ˈɪnpʊt/","pos":"n.","meaningCN":"输入信息；投入物","tag":"核心","root":"","exampleEN":"The teacher asked the students for their input on the new project topic.","exampleCN":"老师向学生征求他们对新课题的意见。","extra":"output n. 输出量，产量"},{"chapter":16,"key":"16:75","id":75,"word":"product","phonetic":"/ˈprɒdʌkt/","pos":"n.","meaningCN":"产品；产物","tag":"核心","root":"","exampleEN":"The company launched a new product aimed at the younger generation.","exampleCN":"公司推出了一款面向年轻一代的新产品。","extra":"production, productive, produce"},{"chapter":16,"key":"16:76","id":76,"word":"acquisition","phonetic":"/ˌækwɪˈzɪʃən/","pos":"n.","meaningCN":"获得；（对公司的）并购","tag":"高频","root":"","exampleEN":"The acquisition of language skills requires both practice and patience.","exampleCN":"语言技能的获得需要练习和耐心。","extra":"搭配：the acquisition of a fortune"},{"chapter":16,"key":"16:77","id":77,"word":"goods","phonetic":"/ɡʊdz/","pos":"n.","meaningCN":"商品，货物","tag":"核心","root":"","exampleEN":"The shop sells a wide range of goods, from clothing to electronics.","exampleCN":"这家商店出售从服装到电子产品的各种商品。","extra":""},{"chapter":16,"key":"16:78","id":78,"word":"cargo","phonetic":"/ˈkɑːɡəʊ/","pos":"n.","meaningCN":"货物","tag":"高频","root":"","exampleEN":"A large cargo ship unloaded its containers at the port early this morning.","exampleCN":"一艘大型货船今天一早在港口卸下了集装箱。","extra":""},{"chapter":16,"key":"16:79","id":79,"word":"insure","phonetic":"/ɪnˈʃʊə/","pos":"v.","meaningCN":"确保；给......上保险","tag":"核心","root":"","exampleEN":"It is wise to insure your house against fire and flood damage.","exampleCN":"给房屋投保火灾和洪水险是明智的做法。","extra":"insurance n. 保险"},{"chapter":16,"key":"16:80","id":80,"word":"guarantee","phonetic":"/ˌɡærənˈtiː/","pos":"v.","meaningCN":"担保；确保 n. 保证；保修单","tag":"核心","root":"","exampleEN":"The washing machine comes with a three-year guarantee covering all parts and labour.","exampleCN":"这台洗衣机有三年的保修期，涵盖所有部件和人工。","extra":"搭配：a bank guarantee, a credit guarantee"},{"chapter":16,"key":"16:81","id":81,"word":"reliable","phonetic":"/rɪˈlaɪəbl/","pos":"adj.","meaningCN":"可靠的，可信赖的","tag":"核心","root":"","exampleEN":"We need someone who is reliable to handle this important task.","exampleCN":"我们需要一个可靠的人来处理这项重要任务。","extra":""},{"chapter":16,"key":"16:82","id":82,"word":"negotiation","phonetic":"/nɪˌɡəʊʃiˈeɪʃən/","pos":"n.","meaningCN":"谈判，协商","tag":"核心","root":"","exampleEN":"After several rounds of negotiation, the two sides finally reached an agreement.","exampleCN":"经过几轮谈判，双方最终达成了协议。","extra":"negotiate v."},{"chapter":16,"key":"16:83","id":83,"word":"attend","phonetic":"/əˈtend/","pos":"v.","meaningCN":"参加，出席","tag":"核心","root":"","exampleEN":"Over 200 guests attended the wedding ceremony at the city hall.","exampleCN":"超过200位宾客参加了在市政厅举行的婚礼。","extra":"attendance n."},{"chapter":16,"key":"16:84","id":84,"word":"absent","phonetic":"/ˈæbsənt/","pos":"adj.","meaningCN":"不在场的，缺席的；心不在焉的","tag":"核心","root":"","exampleEN":"He was absent from work for three days due to a high fever.","exampleCN":"他因发高烧三天没有上班。","extra":"absence n.；absent-minded adj.；搭配：be absent from"},{"chapter":16,"key":"16:85","id":85,"word":"sale","phonetic":"/seɪl/","pos":"n.","meaningCN":"卖，销售；销售额","tag":"核心","root":"","exampleEN":"The store is having a big summer sale with discounts of up to 50%.","exampleCN":"这家商店正在进行夏季大减价，折扣高达五折。","extra":"salesman, sell, seller"},{"chapter":16,"key":"16:86","id":86,"word":"wholesale","phonetic":"/ˈhəʊlseɪl/","pos":"n.","meaningCN":"批发","tag":"高频","root":"","exampleEN":"They buy fresh vegetables at wholesale prices and sell them at the local market.","exampleCN":"他们以批发价购入新鲜蔬菜，然后在当地市场出售。","extra":""},{"chapter":16,"key":"16:87","id":87,"word":"auction","phonetic":"/ˈɔːkʃən/","pos":"v./n.","meaningCN":"拍卖","tag":"高频","root":"","exampleEN":"The famous painting was sold at an auction for over ten million dollars.","exampleCN":"那幅名画在一次拍卖中以超过一千万美元的价格成交。","extra":"搭配：auction price, put sth. up for auction"},{"chapter":16,"key":"16:88","id":88,"word":"bid","phonetic":"/bɪd/","pos":"v./n.","meaningCN":"出价；投标","tag":"高频","root":"","exampleEN":"Several companies have made bids to construct the new bridge.","exampleCN":"好几家公司已投标承建这座新桥。","extra":"bidder n."},{"chapter":16,"key":"16:89","id":89,"word":"deal","phonetic":"/diːl/","pos":"v.","meaningCN":"买卖；[～with] 处理 n. 协议；大量","tag":"核心","root":"","exampleEN":"We made a deal with the supplier that lowered our production costs.","exampleCN":"我们和供应商达成了协议，降低了生产成本。","extra":"搭配：make a deal with, a good/great deal of"},{"chapter":16,"key":"16:90","id":90,"word":"transaction","phonetic":"/trænˈzækʃən/","pos":"n.","meaningCN":"（一笔）交易，业务","tag":"核心","root":"trans（跨越）+ action → 交易","exampleEN":"Online transactions have become a common way to do business.","exampleCN":"线上交易已成为常见的商业方式。","extra":""},{"chapter":16,"key":"16:91","id":91,"word":"turnover","phonetic":"/ˈtɜːnˌəʊvə/","pos":"n.","meaningCN":"（人员）流动率；营业额","tag":"高频","root":"","exampleEN":"The company has a high staff turnover because of poor working conditions.","exampleCN":"由于工作条件差，这家公司的员工流动率很高。","extra":""},{"chapter":16,"key":"16:92","id":92,"word":"dump","phonetic":"/dʌmp/","pos":"v.","meaningCN":"丢弃，倾倒；倾销","tag":"高频","root":"","exampleEN":"It is illegal to dump industrial waste into the river.","exampleCN":"向河里倾倒工业废料是违法的。","extra":"搭配：dump into"},{"chapter":16,"key":"16:93","id":93,"word":"export","phonetic":"/ɪkˈspɔːt/ v. /ˈekspɔːt/ n.","pos":"v.","meaningCN":"出口 n. 出口；出口商品","tag":"核心","root":"","exampleEN":"This country exports a large volume of coffee beans to Europe each year.","exampleCN":"这个国家每年向欧洲出口大量的咖啡豆。","extra":"搭配：export from, export to, bulk exports"},{"chapter":16,"key":"16:94","id":94,"word":"import","phonetic":"/ɪmˈpɔːt/ v. /ˈɪmpɔːt/ n.","pos":"v.","meaningCN":"进口 n. 进口；进口商品","tag":"核心","root":"","exampleEN":"The country imports most of its oil from neighbouring regions.","exampleCN":"该国大部分石油是从邻近地区进口的。","extra":"搭配：import from, import duty"},{"chapter":16,"key":"16:95","id":95,"word":"quota","phonetic":"/ˈkwəʊtə/","pos":"n.","meaningCN":"限额，配额；定额","tag":"高频","root":"","exampleEN":"The government has set a quota on the number of immigrants allowed each year.","exampleCN":"政府对每年允许的移民人数设定了配额。","extra":"搭配：above quota, an export/import quota"},{"chapter":16,"key":"16:96","id":96,"word":"share","phonetic":"/ʃeə/","pos":"n.","meaningCN":"股份，股票；一份 v. 分享；分担","tag":"核心","root":"","exampleEN":"He bought some shares in a technology company that has been growing fast.","exampleCN":"他买了一家一直快速增长的科技公司的一些股票。","extra":"搭配：buy/hold shares, market share"},{"chapter":16,"key":"16:97","id":97,"word":"benefit","phonetic":"/ˈbenɪfɪt/","pos":"n.","meaningCN":"益处 v. 有利于；获益","tag":"核心","root":"","exampleEN":"Regular exercise benefits not only the body but also the mind.","exampleCN":"经常锻炼不仅对身体有益，对心智也有好处。","extra":"beneficial adj.；搭配：benefit from"},{"chapter":16,"key":"16:98","id":98,"word":"interest","phonetic":"/ˈɪntrɪst/","pos":"n.","meaningCN":"兴趣；利益；利息 v. 使感兴趣","tag":"核心","root":"","exampleEN":"The bank offers a higher interest rate for long-term savings accounts.","exampleCN":"银行对长期储蓄账户提供更高的利率。","extra":""},{"chapter":16,"key":"16:99","id":99,"word":"dividend","phonetic":"/ˈdɪvɪdend/","pos":"n.","meaningCN":"股息，红利","tag":"低频","root":"","exampleEN":"The company paid its shareholders a generous dividend this year.","exampleCN":"今年公司向股东支付了丰厚的红利。","extra":"搭配：pay dividends"},{"chapter":16,"key":"16:100","id":100,"word":"stock","phonetic":"/stɒk/","pos":"n.","meaningCN":"股本；股票；库存","tag":"核心","root":"","exampleEN":"Investors closely monitor the stock market for any signs of change.","exampleCN":"投资者密切监视股市，留意任何变化的迹象。","extra":"stockbroker, stockholder"},{"chapter":16,"key":"16:101","id":101,"word":"account","phonetic":"/əˈkaʊnt/","pos":"n.","meaningCN":"账户；解释","tag":"核心","root":"","exampleEN":"She opened a savings account at the bank to put aside money for a holiday.","exampleCN":"她在银行开了一个储蓄账户，为度假存钱。","extra":"accountable, accounting；搭配：account balance, on account"},{"chapter":16,"key":"16:102","id":102,"word":"deposit","phonetic":"/dɪˈpɒzɪt/","pos":"n.","meaningCN":"存款；押金","tag":"核心","root":"","exampleEN":"They paid a 20% deposit and will pay the rest when the work is completed.","exampleCN":"他们支付了20%的押金，其余部分等完工后再付。","extra":"搭配：bank deposits"},{"chapter":16,"key":"16:103","id":103,"word":"instalment","phonetic":"/ɪnˈstɔːlmənt/","pos":"n.","meaningCN":"（分期付款的）一期付款","tag":"高频","root":"","exampleEN":"She bought the sofa in monthly instalments so it wouldn't break the bank.","exampleCN":"她按月分期付款买了沙发，这样就不会花太多钱。","extra":"也作 installment"},{"chapter":16,"key":"16:104","id":104,"word":"cheque","phonetic":"/tʃek/","pos":"n.","meaningCN":"支票","tag":"高频","root":"","exampleEN":"He wrote a cheque for the full amount and handed it to the cashier.","exampleCN":"他开了一张全额支票交给收银员。","extra":"也作 check；搭配：cash/write/sign a cheque, dishonour a cheque, a bad cheque"},{"chapter":16,"key":"16:105","id":105,"word":"cash","phonetic":"/kæʃ/","pos":"n.","meaningCN":"现金 v. 兑现（支票）","tag":"核心","root":"","exampleEN":"The small shop only accepts cash, so we had to find an ATM nearby.","exampleCN":"那家小店只收现金，所以我们不得不在附近找一台自动取款机。","extra":"搭配：pay cash"},{"chapter":16,"key":"16:106","id":106,"word":"coin","phonetic":"/kɔɪn/","pos":"n.","meaningCN":"硬币 v. 铸币；创造（新词语）","tag":"核心","root":"","exampleEN":"The term \"selfie\" was coined in the early 2000s and quickly became popular.","exampleCN":"“自拍”这个词在21世纪初被创造出来并迅速流行起来。","extra":"coiner n."},{"chapter":16,"key":"16:107","id":107,"word":"shilling","phonetic":"/ˈʃɪlɪŋ/","pos":"n.","meaningCN":"先令","tag":"识记","root":"","exampleEN":"In the past, a shilling was a unit of currency used in Britain and several other countries.","exampleCN":"过去，先令是英国及其他几个国家使用的一种货币单位。","extra":""},{"chapter":16,"key":"16:108","id":108,"word":"copper","phonetic":"/ˈkɒpə/","pos":"n.","meaningCN":"铜；[~s] 铜币；警察","tag":"低频","root":"","exampleEN":"Old copper coins discovered on the site provided clues about ancient trade.","exampleCN":"在现场发现的老铜币为研究古代贸易提供了线索。","extra":"cop n. 警察"},{"chapter":16,"key":"16:109","id":109,"word":"treasure","phonetic":"/ˈtreʒə/","pos":"n.","meaningCN":"金银财宝；宝物","tag":"高频","root":"","exampleEN":"The pirates hid their treasure on a remote island in the Pacific Ocean.","exampleCN":"海盗们把他们的财宝藏在了太平洋一个偏远的岛上。","extra":"treasury n. 财政部；搭配：a national treasure"},{"chapter":16,"key":"16:110","id":110,"word":"wealth","phonetic":"/welθ/","pos":"n.","meaningCN":"财富；丰富","tag":"核心","root":"","exampleEN":"The country's wealth is mainly based on its rich natural resources.","exampleCN":"该国的财富主要来自其丰富的自然资源。","extra":"wealthy adj. 富有的；搭配：accumulate wealth"},{"chapter":16,"key":"16:111","id":111,"word":"estate","phonetic":"/ɪˈsteɪt/","pos":"n.","meaningCN":"地产；遗产","tag":"高频","root":"","exampleEN":"He inherited a large estate in the countryside from his grandfather.","exampleCN":"他从祖父那里继承了乡下的一大片地产。","extra":"real estate"},{"chapter":16,"key":"16:112","id":112,"word":"possess","phonetic":"/pəˈzes/","pos":"v.","meaningCN":"占用，拥有；影响，控制","tag":"核心","root":"sed/sess = 坐","exampleEN":"To succeed in this role, you need to possess both patience and creativity.","exampleCN":"要胜任这个职位，你需要兼具耐心和创造力。","extra":"possessive, possession, possessor"},{"chapter":16,"key":"16:113","id":113,"word":"legacy","phonetic":"/ˈleɡəsi/","pos":"n.","meaningCN":"遗赠，遗产","tag":"高频","root":"","exampleEN":"The artist left a lasting legacy through her beautiful paintings.","exampleCN":"这位艺术家通过她美丽的画作留下了永恒的遗产。","extra":""},{"chapter":16,"key":"16:114","id":114,"word":"descend","phonetic":"/dɪˈsend/","pos":"v.","meaningCN":"下降，下来","tag":"高频","root":"","exampleEN":"As the plane began to descend, the passengers fastened their seat belts.","exampleCN":"飞机开始下降时，乘客们系好了安全带。","extra":""},{"chapter":16,"key":"16:115","id":115,"word":"worthy","phonetic":"/ˈwɜːði/","pos":"adj.","meaningCN":"有价值的；值得","tag":"核心","root":"","exampleEN":"This documentary is definitely worthy of your time; it is both informative and moving.","exampleCN":"这部纪录片绝对值得你花时间看，既长知识又感人。","extra":"worthless adj."},{"chapter":16,"key":"16:116","id":116,"word":"valuable","phonetic":"/ˈvæljuəbl/","pos":"adj.","meaningCN":"很值钱的，贵重的；很重要的","tag":"核心","root":"","exampleEN":"The experience you gain from volunteering abroad can be incredibly valuable.","exampleCN":"从海外志愿服务中获得的经验可能非常宝贵。","extra":"value, valuation"},{"chapter":16,"key":"16:117","id":117,"word":"cheap","phonetic":"/tʃiːp/","pos":"adj.","meaningCN":"廉价的；质劣价低的","tag":"核心","root":"","exampleEN":"Cheap food is not always unhealthy, just as expensive food is not always good for you.","exampleCN":"便宜的食物不一定不健康，昂贵的食物也不一定就对你身体好。","extra":""},{"chapter":16,"key":"16:118","id":118,"word":"incentive","phonetic":"/ɪnˈsentɪv/","pos":"n.","meaningCN":"刺激，激励","tag":"高频","root":"","exampleEN":"The company offers financial incentives to employees who exceed their targets.","exampleCN":"公司向超额完成目标的员工提供经济奖励。","extra":"搭配：an incentive to, chief/main incentive"},{"chapter":16,"key":"16:119","id":119,"word":"accelerate","phonetic":"/əkˈseləreɪt/","pos":"v.","meaningCN":"（使）加速","tag":"核心","root":"","exampleEN":"The new high-speed railway will accelerate travel between the two cities.","exampleCN":"新的高速铁路将缩短这两座城市之间的旅行时间。","extra":"decelerate v."},{"chapter":16,"key":"16:120","id":120,"word":"prompt","phonetic":"/prɒmpt/","pos":"v.","meaningCN":"促使 adj. 迅速的","tag":"核心","root":"","exampleEN":"Rising prices prompted many consumers to look for cheaper alternatives.","exampleCN":"价格上涨促使许多消费者寻找更便宜的替代品。","extra":"promptly adv."},{"chapter":16,"key":"16:121","id":121,"word":"salary","phonetic":"/ˈsæləri/","pos":"n.","meaningCN":"工资，（尤指按月领的）薪水","tag":"核心","root":"","exampleEN":"The job offers a starting salary of £30,000 plus excellent benefits.","exampleCN":"这份工作的起薪为3万英镑，外加优厚的福利。","extra":"搭配：get/receive a salary"},{"chapter":16,"key":"16:122","id":122,"word":"income","phonetic":"/ˈɪnkʌm/","pos":"n.","meaningCN":"收入","tag":"核心","root":"","exampleEN":"Many farmers rely on tourism as a second source of income.","exampleCN":"许多农民依靠旅游业作为第二收入来源。","extra":"搭配：earn income"},{"chapter":16,"key":"16:123","id":123,"word":"wage","phonetic":"/weɪdʒ/","pos":"n.","meaningCN":"（通常指按周领的）工钱","tag":"核心","root":"","exampleEN":"The union demanded a minimum wage increase for all part-time workers.","exampleCN":"工会要求为所有兼职工人提高最低工资。","extra":""},{"chapter":16,"key":"16:124","id":124,"word":"payment","phonetic":"/ˈpeɪmənt/","pos":"n.","meaningCN":"支付；支付的款项","tag":"核心","root":"","exampleEN":"You can make the payment by credit card or through the online banking system.","exampleCN":"你可以通过信用卡或网上银行系统付款。","extra":"pay v.；搭配：demand prompt payment"},{"chapter":16,"key":"16:125","id":125,"word":"refund","phonetic":"/ˈriːfʌnd/ n. /rɪˈfʌnd/ v.","pos":"n.","meaningCN":"退款","tag":"核心","root":"","exampleEN":"We were given a full refund because the service did not meet our expectations.","exampleCN":"因为服务没有达到预期，我们获得了全额退款。","extra":"搭配：claim a refund"},{"chapter":16,"key":"16:126","id":126,"word":"reimburse","phonetic":"/ˌriːɪmˈbɜːs/","pos":"v.","meaningCN":"赔偿，补偿","tag":"低频","root":"","exampleEN":"The company will reimburse all employees for work-related travel expenses.","exampleCN":"公司将报销所有员工因公出差的费用。","extra":"reimbursement n.；搭配：reimburse sb. for sth."},{"chapter":16,"key":"16:127","id":127,"word":"payroll","phonetic":"/ˈpeɪrəʊl/","pos":"n.","meaningCN":"工资名单","tag":"低频","root":"","exampleEN":"The company has 35 employees on the payroll, which is twice as many as last year.","exampleCN":"公司在册员工有35人，是去年的两倍。","extra":"搭配：payroll tax"},{"chapter":16,"key":"16:128","id":128,"word":"remuneration","phonetic":"/rɪˌmjuːnəˈreɪʃən/","pos":"n.","meaningCN":"报酬","tag":"低频","root":"","exampleEN":"The position offers a competitive remuneration package that includes health insurance.","exampleCN":"该职位提供有竞争力的薪酬待遇，包括健康保险。","extra":"remunerate v.；搭配：overall/average/net remuneration"},{"chapter":16,"key":"16:129","id":129,"word":"subsidy","phonetic":"/ˈsʌbsɪdi/","pos":"n.","meaningCN":"津贴，补贴","tag":"高频","root":"","exampleEN":"The government provides subsidies to farmers to help them survive difficult times.","exampleCN":"政府向农民提供补贴，帮助他们渡过难关。","extra":"subsidise/subsidize v."},{"chapter":16,"key":"16:130","id":130,"word":"earn","phonetic":"/ɜːn/","pos":"v.","meaningCN":"赚得；赢得；获得","tag":"核心","root":"","exampleEN":"After years of hard work, she finally earned the respect of her colleagues.","exampleCN":"经过多年的努力，她终于赢得了同事们的尊重。","extra":"搭配：earn a living, earn admiration, earn fame"},{"chapter":16,"key":"16:131","id":131,"word":"undertaking","phonetic":"/ˌʌndəˈteɪkɪŋ/","pos":"n.","meaningCN":"任务，事业；许诺","tag":"低频","root":"","exampleEN":"Building the new stadium was a huge financial undertaking for the city.","exampleCN":"建造新体育馆对这座城市来说是一项巨大的财政任务。","extra":"搭配：a written undertaking"},{"chapter":16,"key":"16:132","id":132,"word":"career","phonetic":"/kəˈrɪə/","pos":"n.","meaningCN":"职业，事业；职业生涯","tag":"核心","root":"","exampleEN":"She had a successful career as a lawyer before becoming a writer.","exampleCN":"在成为作家之前，她当过律师，事业很成功。","extra":""},{"chapter":16,"key":"16:133","id":133,"word":"profession","phonetic":"/prəˈfeʃən/","pos":"n.","meaningCN":"职业","tag":"核心","root":"","exampleEN":"Teaching is a profession that requires a great deal of patience and dedication.","exampleCN":"教书育人是一项需要极大耐心和奉献精神的职业。","extra":"professional, professor"},{"chapter":16,"key":"16:134","id":134,"word":"occupation","phonetic":"/ˌɒkjʊˈpeɪʃən/","pos":"n.","meaningCN":"占领；职业","tag":"核心","root":"","exampleEN":"Please write your name, age, and current occupation on the application form.","exampleCN":"请在申请表上填写你的姓名、年龄和目前职业。","extra":"occupy, occupational；搭配：an occupation certificate"},{"chapter":16,"key":"16:135","id":135,"word":"job","phonetic":"/dʒɒb/","pos":"n.","meaningCN":"职业，工作","tag":"核心","root":"","exampleEN":"He is looking for a part-time job to earn some extra money for the summer.","exampleCN":"他正在找兼职，以便夏天多挣点钱。","extra":"搭配：a routine job, a second job"},{"chapter":16,"key":"16:136","id":136,"word":"vocation","phonetic":"/vəʊˈkeɪʃən/","pos":"n.","meaningCN":"（认为特别适合自己的）职业；使命感","tag":"低频","root":"","exampleEN":"She found her true vocation in caring for the elderly at the community centre.","exampleCN":"她在社区中心照料老人的工作里找到了自己真正的使命。","extra":"career（长期）；occupation（谋生）；job（普通）；vocation（天职）"},{"chapter":16,"key":"16:137","id":137,"word":"labour","phonetic":"/ˈleɪbə/","pos":"n.","meaningCN":"劳动，体力劳动","tag":"核心","root":"","exampleEN":"Farm workers often do heavy physical labour under the hot sun.","exampleCN":"农场工人常常在烈日下从事繁重的体力劳动。","extra":"也作 labor"},{"chapter":16,"key":"16:138","id":138,"word":"workforce","phonetic":"/ˈwɜːkfɔːs/","pos":"n.","meaningCN":"劳动力；全体员工","tag":"高频","root":"","exampleEN":"The company plans to expand its workforce by 10% over the next three years.","exampleCN":"公司计划在未来三年内将员工人数增加10%。","extra":""},{"chapter":16,"key":"16:139","id":139,"word":"workaholic","phonetic":"/ˌwɜːkəˈhɒlɪk/","pos":"n.","meaningCN":"工作狂","tag":"低频","root":"","exampleEN":"He is a workaholic who often stays in the office until late at night.","exampleCN":"他是个工作狂，常常在办公室待到深夜。","extra":""},{"chapter":16,"key":"16:140","id":140,"word":"personnel","phonetic":"/ˌpɜːsəˈnel/","pos":"n.","meaningCN":"人员，职员；人事部门","tag":"高频","root":"","exampleEN":"All personnel are required to attend the safety training on Friday morning.","exampleCN":"要求所有人员在周五上午参加安全培训。","extra":"搭配：personnel department"},{"chapter":16,"key":"16:141","id":141,"word":"clerk","phonetic":"/klɑːk/","pos":"n.","meaningCN":"店员；办事员；接待员","tag":"高频","root":"","exampleEN":"He started his career as a bank clerk and later became the branch manager.","exampleCN":"他从银行职员做起，后来成为了分行经理。","extra":"搭配：an accounting clerk, an auditing clerk"},{"chapter":16,"key":"16:142","id":142,"word":"interview","phonetic":"/ˈɪntəvjuː/","pos":"n.","meaningCN":"面试；采访 v. 对......进行面试；采访","tag":"核心","root":"","exampleEN":"She prepared carefully for the job interview by researching the company in advance.","exampleCN":"她为求职面试做了精心准备，提前研究了那家公司。","extra":"interviewer, interviewee"},{"chapter":16,"key":"16:143","id":143,"word":"resume","phonetic":"/ˈrezjʊmeɪ/","pos":"n.","meaningCN":"（求职用的）履历，简历；摘要","tag":"核心","root":"","exampleEN":"Before the interview, make sure your resume is up to date and error-free.","exampleCN":"面试前，要确保简历是最新的且没有错误。","extra":""},{"chapter":16,"key":"16:144","id":144,"word":"recommend","phonetic":"/ˌrekəˈmend/","pos":"v.","meaningCN":"推荐，介绍；劝告，建议","tag":"核心","root":"","exampleEN":"I highly recommend this restaurant for anyone who loves authentic Chinese food.","exampleCN":"我强烈向喜欢地道中餐的人推荐这家餐厅。","extra":"recommendation n."},{"chapter":16,"key":"16:145","id":145,"word":"employ","phonetic":"/ɪmˈplɔɪ/","pos":"v.","meaningCN":"雇用；采用","tag":"核心","root":"","exampleEN":"The hotel employs over 200 staff during the busy summer months.","exampleCN":"在繁忙的夏季，这家酒店雇佣了200多名员工。","extra":"employer, employee, employment, unemployment, employed, unemployed；搭配：be employed in"},{"chapter":16,"key":"16:146","id":146,"word":"hire","phonetic":"/ˈhaɪə/","pos":"v.","meaningCN":"雇用；租用 n. 租赁（业）","tag":"核心","root":"","exampleEN":"We decided to hire a car for the weekend so we could explore the countryside.","exampleCN":"我们决定周末租一辆车，好去乡间游玩。","extra":"hireling"},{"chapter":16,"key":"16:147","id":147,"word":"fire","phonetic":"/ˈfaɪə/","pos":"v.","meaningCN":"解雇 n. 火","tag":"核心","root":"","exampleEN":"He was fired after repeatedly failing to meet his monthly sales targets.","exampleCN":"他因为多次未完成月度销售目标被解雇了。","extra":""},{"chapter":16,"key":"16:148","id":148,"word":"lay-off","phonetic":"/ˈleɪɒf/","pos":"n.","meaningCN":"（因岗位不足的）解雇，裁员；歇工期","tag":"高频","root":"","exampleEN":"There were several lay-offs at the factory when demand for the product decreased.","exampleCN":"产品需求下降时，工厂裁掉了部分员工。","extra":""},{"chapter":16,"key":"16:149","id":149,"word":"dismiss","phonetic":"/dɪsˈmɪs/","pos":"v.","meaningCN":"解雇；解散；（法官）驳回","tag":"高频","root":"","exampleEN":"The manager was forced to dismiss an employee who had been stealing company property.","exampleCN":"经理不得不解雇了一名一直偷窃公司财物的员工。","extra":"dismission, dismissible, dismissal；搭配：dismiss the case, dismissal the court"},{"chapter":16,"key":"16:150","id":150,"word":"discharge","phonetic":"/dɪsˈtʃɑːdʒ/ v. /ˈdɪstʃɑːdʒ/ n.","pos":"v.","meaningCN":"解雇","tag":"低频","root":"","exampleEN":"He was discharged from the army for medical reasons after the training accident.","exampleCN":"在训练事故之后，他因健康原因被军队除役了。","extra":""},{"chapter":16,"key":"16:151","id":151,"word":"resign","phonetic":"/rɪˈzaɪn/","pos":"v.","meaningCN":"辞去，辞职","tag":"核心","root":"","exampleEN":"After ten years with the company, she decided to resign and travel around the world.","exampleCN":"在那家公司工作了十年后，她决定辞职去环游世界。","extra":"resignation n.；搭配：resign from"},{"chapter":16,"key":"16:152","id":152,"word":"sack","phonetic":"/sæk/","pos":"n.","meaningCN":"大口袋 v. 开除","tag":"高频","root":"","exampleEN":"He got the sack after a serious argument with his supervisor.","exampleCN":"与主管发生激烈争吵之后，他被开除了。","extra":""},{"chapter":16,"key":"16:153","id":153,"word":"retire","phonetic":"/rɪˈtaɪə/","pos":"v.","meaningCN":"（使）退休","tag":"核心","root":"","exampleEN":"My grandfather plans to retire next year and spend more time in his garden.","exampleCN":"我祖父计划明年退休，多花点时间在他的花园里。","extra":"retired, retirement"},{"chapter":16,"key":"16:154","id":154,"word":"result","phonetic":"/rɪˈzʌlt/","pos":"n.","meaningCN":"后果，结果 v. 导致","tag":"核心","root":"","exampleEN":"The fire resulted in the destruction of the entire building.","exampleCN":"火灾导致了整幢大楼的毁坏。","extra":"搭配：as a result of, result from, result in"},{"chapter":16,"key":"16:155","id":155,"word":"failure","phonetic":"/ˈfeɪljə/","pos":"n.","meaningCN":"失败；失败的人/事","tag":"核心","root":"","exampleEN":"His first attempt at starting a business ended in failure, but he learned a lot.","exampleCN":"他第一次创业以失败告终，但他学到了很多东西。","extra":"fail v.；搭配：end in failure"},{"chapter":16,"key":"16:156","id":156,"word":"abortion","phonetic":"/əˈbɔːʃən/","pos":"n.","meaningCN":"人工流产；（计划等）中途失败","tag":"低频","root":"","exampleEN":"The whole project proved to be an abortion and was stopped after six months.","exampleCN":"整个项目中途失败了，六个月后就被叫停了。","extra":"搭配：have an abortion"},{"chapter":16,"key":"16:157","id":157,"word":"loss","phonetic":"/lɒs/","pos":"n.","meaningCN":"遗失；损失；亏损","tag":"核心","root":"","exampleEN":"The company reported a significant financial loss for the third quarter.","exampleCN":"该公司报告称第三季度出现重大财务亏损。","extra":"lossless, loser；搭配：make up a loss, suffer a loss"},{"chapter":16,"key":"16:158","id":158,"word":"opportunity","phonetic":"/ˌɒpəˈtjuːnəti/","pos":"n.","meaningCN":"机会，时机","tag":"核心","root":"","exampleEN":"Studying abroad is a wonderful opportunity to experience a different culture.","exampleCN":"出国留学是体验不同文化的绝佳机会。","extra":""},{"chapter":16,"key":"16:159","id":159,"word":"chance","phonetic":"/tʃɑːns/","pos":"n.","meaningCN":"机会；可能性","tag":"核心","root":"","exampleEN":"There is still a small chance that the weather will clear up before the match.","exampleCN":"仍然有一线希望在比赛前天气会放晴。","extra":"搭配：by chance, take a chance"},{"chapter":16,"key":"16:160","id":160,"word":"choose","phonetic":"/tʃuːz/","pos":"v.","meaningCN":"选择","tag":"核心","root":"","exampleEN":"You are free to choose whichever course of study you are most interested in.","exampleCN":"你可以自由选择你最感兴趣的课程。","extra":"choice n.；搭配：as you choose"},{"chapter":16,"key":"16:161","id":161,"word":"change","phonetic":"/tʃeɪndʒ/","pos":"n.","meaningCN":"改变","tag":"核心","root":"","exampleEN":"Moving to a new city was a big change, but she adapted quickly.","exampleCN":"搬到新城市是一个巨大的改变，但她很快就适应了。","extra":"changeable adj."},{"chapter":16,"key":"16:162","id":162,"word":"solve","phonetic":"/sɒlv/","pos":"v.","meaningCN":"解答；解决","tag":"核心","root":"","exampleEN":"Scientists are working hard to solve some of the world's biggest problems.","exampleCN":"科学家们正在努力解决世界上一些最重大的问题。","extra":"solution n.；搭配：solve a puzzle"},{"chapter":16,"key":"16:163","id":163,"word":"develop","phonetic":"/dɪˈveləp/","pos":"v.","meaningCN":"发展；开发","tag":"核心","root":"","exampleEN":"The city has developed rapidly over the past twenty years.","exampleCN":"过去二十年里，这座城市发展得很迅速。","extra":"development, developed, developing；搭配：a developing/developed country"},{"chapter":16,"key":"16:164","id":164,"word":"sustainable","phonetic":"/səˈsteɪnəbl/","pos":"adj.","meaningCN":"可持续的","tag":"核心","root":"","exampleEN":"Many companies are now trying to use more sustainable methods of production.","exampleCN":"许多公司现今正在尝试使用更可持续的生产方法。","extra":"搭配：sustainable development"},{"chapter":16,"key":"16:165","id":165,"word":"improve","phonetic":"/ɪmˈpruːv/","pos":"v.","meaningCN":"改善，改进","tag":"核心","root":"","exampleEN":"Taking notes during lectures can significantly improve your memory of the material.","exampleCN":"听课时记笔记可以显著提高你对材料的记忆。","extra":"improvement n."},{"chapter":16,"key":"16:166","id":166,"word":"manage","phonetic":"/ˈmænɪdʒ/","pos":"v.","meaningCN":"管理；设法做到","tag":"核心","root":"","exampleEN":"She manages a team of 20 people in the marketing department.","exampleCN":"她管理着市场营销部一个20人的团队。","extra":"management, manager"},{"chapter":16,"key":"16:167","id":167,"word":"regulate","phonetic":"/ˈreɡjʊleɪt/","pos":"v.","meaningCN":"管理；调整","tag":"高频","root":"","exampleEN":"New laws have been passed to regulate the use of personal data online.","exampleCN":"已通过新的法律来规范网上个人数据的使用。","extra":""},{"chapter":16,"key":"16:168","id":168,"word":"sanction","phonetic":"/ˈsæŋkʃən/","pos":"n.","meaningCN":"批准；制裁 v. 批准；对......实施制裁","tag":"高频","root":"","exampleEN":"The UN imposed economic sanctions on the country to force a change of policy.","exampleCN":"联合国对该国实施经济制裁，以迫使其改变政策。","extra":"搭配：apply/impose a sanction"},{"chapter":16,"key":"16:169","id":169,"word":"coordinate","phonetic":"/kəʊˈɔːdɪneɪt/ v. /kəʊˈɔːdɪnət/ n.","pos":"v.","meaningCN":"调和，协调","tag":"核心","root":"","exampleEN":"Our team leader coordinates the efforts of all departments to meet tight deadlines.","exampleCN":"我们组长协调所有部门的努力，以赶上紧迫的截止日期。","extra":"coordinator n."},{"chapter":16,"key":"16:170","id":170,"word":"cooperate","phonetic":"/kəʊˈɒpəreɪt/","pos":"v.","meaningCN":"合作，协作","tag":"核心","root":"","exampleEN":"If everyone cooperates, we can finish cleaning the park before noon.","exampleCN":"如果大家齐心协力，我们中午前就能把公园打扫干净。","extra":"cooperation n.；搭配：cooperate with"},{"chapter":16,"key":"16:171","id":171,"word":"collaborate","phonetic":"/kəˈlæbəreɪt/","pos":"v.","meaningCN":"合作","tag":"高频","root":"col（一起）+ laborate（工作）→ 合作","exampleEN":"The two universities have been collaborating on medical research since 2008.","exampleCN":"这两所大学自2008年以来一直在医学研究上开展合作。","extra":""}],"17":[{"chapter":17,"key":"17:1","id":1,"word":"law","phonetic":"/lɔː/","pos":"n.","meaningCN":"法律；规律；定理","tag":"核心","root":"","exampleEN":"Every citizen is expected to obey the law and respect the rights of others.","exampleCN":"每个公民都应遵守法律并尊重他人的权利。","extra":"lawyer n. 律师；搭配：enact a law 通过法律"},{"chapter":17,"key":"17:2","id":2,"word":"legal","phonetic":"/lɪɡəl/","pos":"adj.","meaningCN":"法律的；合法的","tag":"核心","root":"","exampleEN":"It is not legal to drive a car without a valid licence.","exampleCN":"没有有效驾照开车是不合法的。","extra":"反义词：illegal"},{"chapter":17,"key":"17:3","id":3,"word":"rule","phonetic":"/ruːl/","pos":"n.","meaningCN":"规则 v. 统治","tag":"核心","root":"","exampleEN":"One basic rule of the library is to keep quiet at all times.","exampleCN":"图书馆的一条基本规则是随时保持安静。","extra":""},{"chapter":17,"key":"17:4","id":4,"word":"regulation","phonetic":"/ˌreɡjɪˈleɪʃən/","pos":"n.","meaningCN":"规则，规定；管理","tag":"核心","root":"","exampleEN":"New safety regulations were introduced after the accident at the factory.","exampleCN":"工厂发生事故后，出台了新的安全规定。","extra":"regulate v. 管理；调整；regular adj. 有规律的"},{"chapter":17,"key":"17:5","id":5,"word":"item","phonetic":"/ˈaɪtəm/","pos":"n.","meaningCN":"一项项目，条目","tag":"核心","root":"","exampleEN":"Please check each item on the list before you hand in the form.","exampleCN":"交表之前请核对清单上的每一个项目。","extra":""},{"chapter":17,"key":"17:6","id":6,"word":"treaty","phonetic":"/ˈtrɪti/","pos":"n.","meaningCN":"条约；协议","tag":"高频","root":"","exampleEN":"The two countries signed a peace treaty to end the long conflict.","exampleCN":"两国签署了一项和平条约以结束长期冲突。","extra":""},{"chapter":17,"key":"17:7","id":7,"word":"agreement","phonetic":"/əˈɡriːmənt/","pos":"n.","meaningCN":"协定；同意","tag":"核心","root":"","exampleEN":"After hours of discussion, they finally reached an agreement on the budget.","exampleCN":"经过数小时的讨论，他们终于就预算达成了协议。","extra":"agree v."},{"chapter":17,"key":"17:8","id":8,"word":"charter","phonetic":"/ˈtʃɑːtə/","pos":"n.","meaningCN":"宪章 v. 租，包（船、车、飞机等）","tag":"低频","root":"","exampleEN":"The organisation's charter clearly states its purpose and core values.","exampleCN":"该组织的宪章明确阐述了其宗旨和核心价值观。","extra":"搭配：draft a charter 起草宪章"},{"chapter":17,"key":"17:9","id":9,"word":"protocol","phonetic":"/ˈprəʊtəkl/","pos":"n.","meaningCN":"议定书，协议；礼仪","tag":"低频","root":"","exampleEN":"Diplomatic protocol requires that the host greets the visiting leaders first.","exampleCN":"外交礼仪要求主人先向来访的领导人致意。","extra":""},{"chapter":17,"key":"17:10","id":10,"word":"norm","phonetic":"/nɔːm/","pos":"n.","meaningCN":"标准；[-s] 行为准则，规范","tag":"高频","root":"","exampleEN":"Wearing a suit to a job interview is considered the norm in many industries.","exampleCN":"在许多行业，穿西装参加求职面试被视为常规做法。","extra":"normal, abnormal；搭配：social norms 社会规范"},{"chapter":17,"key":"17:11","id":11,"word":"benchmark","phonetic":"/ˈbentʃmɑːk/","pos":"n.","meaningCN":"基准，水准点","tag":"低频","root":"bench（长凳）+ mark（标记）","exampleEN":"This company's customer service sets the benchmark for the entire industry.","exampleCN":"这家公司的客户服务为整个行业树立了标杆。","extra":""},{"chapter":17,"key":"17:12","id":12,"word":"criteria","phonetic":"/kraɪˈtɪəriə/","pos":"n.","meaningCN":"（复数）标准，准则","tag":"核心","root":"","exampleEN":"To qualify for the scholarship, students must meet three main criteria.","exampleCN":"要获得奖学金资格，学生必须满足三个主要标准。","extra":""},{"chapter":17,"key":"17:13","id":13,"word":"standard","phonetic":"/ˈstændɪd/","pos":"n.","meaningCN":"标准","tag":"核心","root":"","exampleEN":"All products are tested to ensure they meet international safety standards.","exampleCN":"所有产品都经过测试，以确保符合国际安全标准。","extra":"standardised, standardisation"},{"chapter":17,"key":"17:14","id":14,"word":"permit","phonetic":"/pəˈmɪt/","pos":"v.","meaningCN":"允许，准许","tag":"核心","root":"","exampleEN":"The museum does not permit visitors to take photographs inside the galleries.","exampleCN":"博物馆不允许参观者在展厅内拍照。","extra":"permission, permissible"},{"chapter":17,"key":"17:15","id":15,"word":"allow","phonetic":"/əˈlaʊ/","pos":"v.","meaningCN":"允许，准许","tag":"核心","root":"","exampleEN":"The new timetable allows students more time for independent study.","exampleCN":"新的课程表让学生有更多时间自学。","extra":"allowance；搭配：allow for 考虑到；allow sb. to do sth."},{"chapter":17,"key":"17:16","id":16,"word":"admission","phonetic":"/ədˈmɪʃən/","pos":"n.","meaningCN":"承认；入场费；准许进入","tag":"核心","root":"","exampleEN":"Admission to the exhibition is free for children under 12 years old.","exampleCN":"12岁以下儿童可免费参观该展览。","extra":""},{"chapter":17,"key":"17:17","id":17,"word":"perform","phonetic":"/pəˈfɔːm/","pos":"v.","meaningCN":"履行，执行","tag":"核心","root":"","exampleEN":"The team performed all the necessary tests before launching the software.","exampleCN":"该团队在发布软件前执行了所有必要的测试。","extra":"performance"},{"chapter":17,"key":"17:18","id":18,"word":"enforce","phonetic":"/ɪnˈfɔːs/","pos":"v.","meaningCN":"强制执行，强行实施；迫使","tag":"高频","root":"","exampleEN":"Police officers are responsible for enforcing traffic laws on the roads.","exampleCN":"警察负责在道路上执行交通法律。","extra":"enforcement；搭配：enforce sth. on sb."},{"chapter":17,"key":"17:19","id":19,"word":"default","phonetic":"/dɪˈfɔːlt/","pos":"v.","meaningCN":"不支付，不履行； n. 违约；默认值","tag":"高频","root":"","exampleEN":"If you default on your loan payments, the bank may take legal action.","exampleCN":"如果你拖欠贷款，银行可能会采取法律行动。","extra":"搭配：in default of 因缺少……"},{"chapter":17,"key":"17:20","id":20,"word":"reject","phonetic":"/rɪˈdʒekt/","pos":"v.","meaningCN":"拒绝接受；摒弃","tag":"核心","root":"","exampleEN":"The committee rejected the proposal because it lacked sufficient detail.","exampleCN":"委员会否决了该提案，因为提案缺乏足够的细节。","extra":"rejection"},{"chapter":17,"key":"17:21","id":21,"word":"constraint","phonetic":"/kənˈstreɪnt/","pos":"n.","meaningCN":"约束，限制；克制","tag":"高频","root":"","exampleEN":"Budget constraints forced the school to cut some after-school programmes.","exampleCN":"预算限制迫使学校削减了一些课外活动。","extra":""},{"chapter":17,"key":"17:22","id":22,"word":"official","phonetic":"/əˈfɪʃəl/","pos":"adj.","meaningCN":"正式的，官方的","tag":"核心","root":"","exampleEN":"We are still waiting for an official statement from the government.","exampleCN":"我们仍在等待政府的官方声明。","extra":""},{"chapter":17,"key":"17:23","id":23,"word":"mandatory","phonetic":"/ˈmændətəri/","pos":"adj.","meaningCN":"法定的，强制的","tag":"高频","root":"mand = 命令","exampleEN":"Wearing a helmet is mandatory for all cyclists in this city.","exampleCN":"在这座城市，所有骑自行车的人都必须佩戴头盔。","extra":"mandate n./v. 授权，命令"},{"chapter":17,"key":"17:24","id":24,"word":"potent","phonetic":"/ˈpəʊtənt/","pos":"adj.","meaningCN":"很有效的，强有力的","tag":"高频","root":"","exampleEN":"This is a potent drug that should only be given under medical supervision.","exampleCN":"这是一种强效药物，只能在医生监督下使用。","extra":"反义词：impotent"},{"chapter":17,"key":"17:25","id":25,"word":"bound","phonetic":"/baʊnd/","pos":"adj.","meaningCN":"[be ~ to] 一定会，很可能，有义务","tag":"核心","root":"","exampleEN":"You are bound by the agreement to complete the work by the end of the month.","exampleCN":"根据协议，你有义务在月底前完成这项工作。","extra":""},{"chapter":17,"key":"17:26","id":26,"word":"obligation","phonetic":"/ˌɒblɪˈɡeɪʃən/","pos":"n.","meaningCN":"义务，责任","tag":"核心","root":"","exampleEN":"Parents have a legal obligation to ensure their children receive an education.","exampleCN":"父母有法律义务确保子女接受教育。","extra":"oblige v. 迫使；帮忙"},{"chapter":17,"key":"17:27","id":27,"word":"court","phonetic":"/kɔːt/","pos":"n.","meaningCN":"法院；庭院","tag":"核心","root":"","exampleEN":"The witness was asked to appear in court to give evidence next week.","exampleCN":"证人被要求下周出庭作证。","extra":"搭配：take sb. to court 将某人告上法庭"},{"chapter":17,"key":"17:28","id":28,"word":"supreme","phonetic":"/suːˈpriːm/","pos":"adj.","meaningCN":"最高的；最大的","tag":"高频","root":"","exampleEN":"The Supreme Court has the final authority to interpret the constitution.","exampleCN":"最高法院拥有解释宪法的最终权力。","extra":"supremacy n. 至高无上；搭配：a supreme court 最高法院"},{"chapter":17,"key":"17:29","id":29,"word":"enact","phonetic":"/ɪˈnækt/","pos":"v.","meaningCN":"通过（法律）；表演","tag":"高频","root":"","exampleEN":"The parliament voted to enact a new environmental protection law.","exampleCN":"议会投票通过了一项新的环境保护法。","extra":""},{"chapter":17,"key":"17:30","id":30,"word":"legislate","phonetic":"/ˈledʒɪsleɪt/","pos":"v.","meaningCN":"立法，制定法律","tag":"高频","root":"","exampleEN":"It is the responsibility of the congress to legislate on matters of national security.","exampleCN":"就国家安全事务立法是国会的职责。","extra":"legislation n. 法律，法规"},{"chapter":17,"key":"17:31","id":31,"word":"equity","phonetic":"/ˈekwəti/","pos":"n.","meaningCN":"公平","tag":"高频","root":"","exampleEN":"The new policies aim to achieve greater equity in access to healthcare.","exampleCN":"新政策旨在使医疗保健的获取更加公平。","extra":"equal adj. 平等的"},{"chapter":17,"key":"17:32","id":32,"word":"fair","phonetic":"/feə/","pos":"adj.","meaningCN":"公平的，公正的","tag":"核心","root":"","exampleEN":"The judge made sure that the trial was fair to both sides.","exampleCN":"法官确保审判对双方都是公平的。","extra":"反义词：unfair"},{"chapter":17,"key":"17:33","id":33,"word":"just","phonetic":"/dʒʌst/","pos":"adj.","meaningCN":"公正的；正义的","tag":"核心","root":"","exampleEN":"A just society is one in which all people are treated equally under the law.","exampleCN":"一个公正的社会是法律面前人人平等的社会。","extra":"unjust, justice, justify"},{"chapter":17,"key":"17:34","id":34,"word":"prejudice","phonetic":"/ˈpredʒʊdɪs/","pos":"n.","meaningCN":"偏见，成见","tag":"核心","root":"","exampleEN":"The campaign aims to fight prejudice and promote cultural understanding.","exampleCN":"这场运动旨在消除偏见并促进文化理解。","extra":"搭配：prejudice against 对……的偏见"},{"chapter":17,"key":"17:35","id":35,"word":"discrimination","phonetic":"/dɪˌskrɪmɪˈneɪʃən/","pos":"n.","meaningCN":"歧视","tag":"核心","root":"","exampleEN":"Laws against gender discrimination have been in place for decades.","exampleCN":"禁止性别歧视的法律已经存在几十年了。","extra":""},{"chapter":17,"key":"17:36","id":36,"word":"accuse","phonetic":"/əˈkjuːz/","pos":"v.","meaningCN":"控告，指责","tag":"核心","root":"","exampleEN":"She accused her neighbour of stealing her bicycle from the yard.","exampleCN":"她指控邻居从院子里偷了她的自行车。","extra":"搭配：accuse sb. of sth. 指控某人做某事"},{"chapter":17,"key":"17:37","id":37,"word":"sue","phonetic":"/sjuː/","pos":"v.","meaningCN":"控告，提起诉讼","tag":"核心","root":"","exampleEN":"The actor decided to sue the magazine for publishing false stories about him.","exampleCN":"那位演员决定控告那家杂志散布关于他的不实报道。","extra":"搭配：sue sb. for 因……起诉某人"},{"chapter":17,"key":"17:38","id":38,"word":"prosecute","phonetic":"/ˈprɒsɪkjuːt/","pos":"v.","meaningCN":"检举，起诉","tag":"高频","root":"","exampleEN":"The district attorney decided to prosecute the company for fraud.","exampleCN":"地区检察官决定以欺诈罪起诉该公司。","extra":"prosecution n. 起诉；prosecutor n. 检察官；注意：persecute 迫害"},{"chapter":17,"key":"17:39","id":39,"word":"condemn","phonetic":"/kənˈdem/","pos":"v.","meaningCN":"谴责，指责","tag":"高频","root":"","exampleEN":"The international community strongly condemned the use of chemical weapons.","exampleCN":"国际社会强烈谴责使用化学武器的行为。","extra":""},{"chapter":17,"key":"17:40","id":40,"word":"complain","phonetic":"/kəmˈpleɪn/","pos":"v.","meaningCN":"抱怨；投诉","tag":"核心","root":"","exampleEN":"Several customers complained about the slow service at the restaurant.","exampleCN":"几位顾客投诉了那家餐厅上菜速度慢。","extra":"complaint n.；搭配：complain about, complain to"},{"chapter":17,"key":"17:41","id":41,"word":"boycott","phonetic":"/ˈbɔɪkɒt/","pos":"n./v.","meaningCN":"抵制，拒绝购买","tag":"高频","root":"","exampleEN":"Many consumers decided to boycott the company's products over environmental concerns.","exampleCN":"出于对环境的担忧，许多消费者决定抵制该公司的产品。","extra":"词源：来自人名Boycott"},{"chapter":17,"key":"17:42","id":42,"word":"session","phonetic":"/ˈseʃən/","pos":"n.","meaningCN":"会议；会期","tag":"核心","root":"","exampleEN":"The court is now in session and will hear the first case of the day.","exampleCN":"法庭现在开庭，将审理今天的第一个案件。","extra":""},{"chapter":17,"key":"17:43","id":43,"word":"mediate","phonetic":"/ˈmiːdieɪt/","pos":"v.","meaningCN":"斡旋，调解","tag":"高频","root":"","exampleEN":"A neutral third party was brought in to mediate between the two companies.","exampleCN":"一个中立的第三方被请来调解两家公司之间的矛盾。","extra":"搭配：mediate between 在……之间调解"},{"chapter":17,"key":"17:44","id":44,"word":"plea","phonetic":"/pliː/","pos":"n.","meaningCN":"辩解理由，借口；请求","tag":"低频","root":"","exampleEN":"The defendant entered a plea of not guilty at the beginning of the trial.","exampleCN":"审判开始时，被告提出了无罪抗辩。","extra":"搭配：make a plea for 为……恳求"},{"chapter":17,"key":"17:45","id":45,"word":"appeal","phonetic":"/əˈpiːl/","pos":"v./n.","meaningCN":"呼吁；申诉","tag":"核心","root":"","exampleEN":"The charity launched an appeal to raise money for the flood victims.","exampleCN":"该慈善机构发起呼吁，为水灾灾民筹集资金。","extra":"搭配：lodge an appeal 提出上诉"},{"chapter":17,"key":"17:46","id":46,"word":"contradict","phonetic":"/ˌkɒntrəˈdɪkt/","pos":"v.","meaningCN":"反驳；与......矛盾","tag":"高频","root":"","exampleEN":"His later statement appeared to contradict what he had told the police earlier.","exampleCN":"他后来的陈述似乎与他早前告诉警方的话相矛盾。","extra":"contradiction n. 矛盾"},{"chapter":17,"key":"17:47","id":47,"word":"persuade","phonetic":"/pəˈsweɪd/","pos":"v.","meaningCN":"说服；使相信","tag":"核心","root":"","exampleEN":"She managed to persuade her parents to let her study abroad for a year.","exampleCN":"她成功说服了父母让她出国学习一年。","extra":"搭配：persuade sb. to do sth. 说服某人做某事"},{"chapter":17,"key":"17:48","id":48,"word":"controversy","phonetic":"/ˈkɒntrəvɜːsi/","pos":"n.","meaningCN":"争议；辩论","tag":"核心","root":"","exampleEN":"The new education policy has caused a lot of controversy among teachers and parents.","exampleCN":"新教育政策在教师和家长中引起了很多争议。","extra":"controversial adj. 有争议的"},{"chapter":17,"key":"17:49","id":49,"word":"whisper","phonetic":"/ˈwɪspə/","pos":"v.","meaningCN":"低声说；私下谈论","tag":"核心","root":"","exampleEN":"They had to whisper in the library so as not to disturb other readers.","exampleCN":"他们在图书馆不得不小声说话，以免打扰其他读者。","extra":""},{"chapter":17,"key":"17:50","id":50,"word":"mutter","phonetic":"/ˈmʌtə/","pos":"v.","meaningCN":"轻声低语；小声抱怨","tag":"高频","root":"","exampleEN":"He was muttering something under his breath as he walked away angrily.","exampleCN":"他生气地走开时，嘴里小声嘀咕着什么。","extra":""},{"chapter":17,"key":"17:51","id":51,"word":"murmur","phonetic":"/ˈmɜːmə/","pos":"v.","meaningCN":"低声说 n. 咕哝，低语","tag":"高频","root":"","exampleEN":"A soft murmur of conversation filled the room before the speaker began.","exampleCN":"演讲者开始讲话前，房间里充满了低低的交谈声。","extra":""},{"chapter":17,"key":"17:52","id":52,"word":"silent","phonetic":"/ˈsaɪlənt/","pos":"adj.","meaningCN":"沉默的；寂静无声的","tag":"核心","root":"","exampleEN":"The room fell silent as the judge entered and took her seat.","exampleCN":"法官走进来就座时，整个房间瞬间安静了下来。","extra":"silence n. 沉默"},{"chapter":17,"key":"17:53","id":53,"word":"mute","phonetic":"/mjuːt/","pos":"adj.","meaningCN":"缄默的；哑的；无声的 n. 哑巴","tag":"高频","root":"","exampleEN":"He remained mute throughout the interview and refused to answer any questions.","exampleCN":"整个采访过程中他一言不发，拒绝回答任何问题。","extra":""},{"chapter":17,"key":"17:54","id":54,"word":"investigate","phonetic":"/ɪnˈvestɪɡeɪt/","pos":"v.","meaningCN":"调查","tag":"核心","root":"","exampleEN":"The police are investigating the cause of the fire that destroyed the warehouse.","exampleCN":"警方正在调查烧毁仓库的那场火灾的原因。","extra":"investigation n.；搭配：investigate into 调查"},{"chapter":17,"key":"17:55","id":55,"word":"witness","phonetic":"/ˈwɪtnəs/","pos":"n.","meaningCN":"目击者，见证人 v. 目击","tag":"核心","root":"","exampleEN":"A witness told the police that she had seen a man running from the scene.","exampleCN":"一名目击者告诉警方，她看到一名男子从现场逃跑。","extra":"搭配：bear witness to 为……作证"},{"chapter":17,"key":"17:56","id":56,"word":"commit","phonetic":"/kəˈmɪt/","pos":"v.","meaningCN":"犯（罪），做（坏事）","tag":"核心","root":"","exampleEN":"He was sent to prison after being found guilty of committing a serious crime.","exampleCN":"他被判犯有严重罪行后入狱服刑。","extra":"commitment n.；搭配：commit a crime 犯罪；commit suicide 自杀"},{"chapter":17,"key":"17:57","id":57,"word":"sin","phonetic":"/sɪn/","pos":"n.","meaningCN":"罪孽 v. 犯戒律","tag":"高频","root":"","exampleEN":"In many religions, stealing is considered a sin against the community.","exampleCN":"在许多宗教中，偷窃被认为是一种对群体的罪过。","extra":""},{"chapter":17,"key":"17:58","id":58,"word":"crime","phonetic":"/kraɪm/","pos":"n.","meaningCN":"罪行；犯罪活动","tag":"核心","root":"","exampleEN":"The police are using new technology to fight crime in the city centre.","exampleCN":"警方正在运用新技术打击市中心的犯罪活动。","extra":"criminal n. 罪犯 adj. 犯罪的；搭配：commit a crime"},{"chapter":17,"key":"17:59","id":59,"word":"vice","phonetic":"/vaɪs/","pos":"n.","meaningCN":"恶行；缺点","tag":"低频","root":"","exampleEN":"The novel explores the theme of virtue versus vice in modern society.","exampleCN":"这部小说探讨了现代社会中美德与恶行的主题。","extra":"搭配：vice versa 反之亦然"},{"chapter":17,"key":"17:60","id":60,"word":"bribe","phonetic":"/braɪb/","pos":"n.","meaningCN":"贿赂 v. 向......行贿","tag":"高频","root":"","exampleEN":"The judge was arrested after he was caught accepting a bribe from a businessman.","exampleCN":"那名法官因收受一名商人的贿赂被当场抓获后被捕。","extra":"bribery n. 贿赂行为"},{"chapter":17,"key":"17:61","id":61,"word":"rob","phonetic":"/rɒb/","pos":"v.","meaningCN":"抢劫；夺走","tag":"核心","root":"","exampleEN":"Two masked men attempted to rob the bank but were stopped by the security guards.","exampleCN":"两名蒙面男子企图抢劫银行，但被保安人员拦住了。","extra":"robber n. 强盗；robbery n. 抢劫；搭配：rob sb. of sth. 抢走某人某物"},{"chapter":17,"key":"17:62","id":62,"word":"pirate","phonetic":"/paɪˈreɪt/","pos":"n.","meaningCN":"海盗；盗版者 v. 盗印，窃用","tag":"高频","root":"","exampleEN":"The film industry loses millions of dollars each year because of pirate copies.","exampleCN":"电影业每年因盗版损失数百万美元。","extra":""},{"chapter":17,"key":"17:63","id":63,"word":"steal","phonetic":"/stiːl/","pos":"v.","meaningCN":"偷，窃取；剽窃","tag":"核心","root":"","exampleEN":"Someone broke into their house and stole all their electronic devices.","exampleCN":"有人闯进了他们家，偷走了所有的电子设备。","extra":""},{"chapter":17,"key":"17:64","id":64,"word":"thief","phonetic":"/θiːf/","pos":"n.","meaningCN":"窃贼，偷窃犯","tag":"核心","root":"","exampleEN":"The thief was caught on camera taking a wallet from a customer's bag.","exampleCN":"摄像头拍到了小偷从一位顾客的包里取走钱包。","extra":""},{"chapter":17,"key":"17:65","id":65,"word":"murder","phonetic":"/ˈmɜːdə/","pos":"n./v.","meaningCN":"谋杀","tag":"核心","root":"","exampleEN":"The detective has spent months trying to solve the murder of the wealthy businessman.","exampleCN":"侦探花了几个月的时间试图侦破那起富商谋杀案。","extra":"murderer n. 谋杀犯"},{"chapter":17,"key":"17:66","id":66,"word":"suicide","phonetic":"/ˈsuːɪsaɪd/","pos":"n.","meaningCN":"自杀","tag":"高频","root":"","exampleEN":"The hotline provides support for anyone experiencing thoughts of suicide.","exampleCN":"这条热线为任何有轻生念头的人提供支持。","extra":""},{"chapter":17,"key":"17:67","id":67,"word":"deceive","phonetic":"/dɪˈsiːv/","pos":"v.","meaningCN":"欺骗；蒙蔽，误导","tag":"高频","root":"","exampleEN":"He tried to deceive the elderly couple into giving him their bank details.","exampleCN":"他试图欺骗那对老夫妇，让他们提供银行信息。","extra":"deceit n. 欺骗；搭配：deceive sb. into doing sth. 欺骗某人做某事"},{"chapter":17,"key":"17:68","id":68,"word":"cheat","phonetic":"/tʃiːt/","pos":"v.","meaningCN":"欺骗；作弊 n. 作弊者","tag":"核心","root":"","exampleEN":"Students who cheat in the exam will be disqualified from the course.","exampleCN":"考试作弊的学生将被取消课程资格。","extra":"cheater n.；搭配：cheat on sb. 对某人不忠"},{"chapter":17,"key":"17:69","id":69,"word":"fraud","phonetic":"/frɔːd/","pos":"n.","meaningCN":"骗子；赝品；欺诈","tag":"高频","root":"","exampleEN":"The man was sentenced to prison for committing credit card fraud.","exampleCN":"那名男子因实施信用卡欺诈被判入狱。","extra":""},{"chapter":17,"key":"17:70","id":70,"word":"liar","phonetic":"/ˈlaɪə/","pos":"n.","meaningCN":"说谎的人","tag":"高频","root":"","exampleEN":"Nobody believed him anymore because they had discovered he was a liar.","exampleCN":"再也没有人相信他了，因为他们发现他是个说谎的人。","extra":"lie v. 说谎"},{"chapter":17,"key":"17:71","id":71,"word":"trap","phonetic":"/træp/","pos":"n.","meaningCN":"陷阱；诡计 v. 诱骗","tag":"高频","root":"","exampleEN":"The salesman used a clever trap to make customers pay more than they should.","exampleCN":"那个推销员用了一个巧妙的圈套，让顾客花了比应花更多的钱。","extra":""},{"chapter":17,"key":"17:72","id":72,"word":"trick","phonetic":"/trɪk/","pos":"n.","meaningCN":"诡计 v. 哄骗","tag":"核心","root":"","exampleEN":"The children played a harmless trick on their teacher on April Fools' Day.","exampleCN":"愚人节那天，孩子们对老师搞了一个无伤大雅的恶作剧。","extra":"tricky adj. 棘手的；搭配：play a trick on sb. 捉弄某人"},{"chapter":17,"key":"17:73","id":73,"word":"pretend","phonetic":"/prɪˈtend/","pos":"v.","meaningCN":"假装；假扮","tag":"核心","root":"","exampleEN":"She pretended to be interested in the lecture, but her mind was wandering.","exampleCN":"她假装对讲座很感兴趣，但其实思绪已经飘远了。","extra":"搭配：pretend to do sth., pretend sickness 装病"},{"chapter":17,"key":"17:74","id":74,"word":"fool","phonetic":"/fuːl/","pos":"n.","meaningCN":"蠢人，傻子 v. 欺骗","tag":"核心","root":"","exampleEN":"He was fooled by a fake investment scheme and lost his entire savings.","exampleCN":"他被一个虚假的投资计划欺骗，失去了全部积蓄。","extra":"foolish adj. 愚蠢的；搭配：make a fool of sb. 愚弄某人"},{"chapter":17,"key":"17:75","id":75,"word":"stigma","phonetic":"/ˈstɪɡmə/","pos":"n.","meaningCN":"耻辱，污名","tag":"低频","root":"","exampleEN":"In some cultures, there is still a stigma attached to mental health problems.","exampleCN":"在一些文化中，心理健康问题仍然带有污名。","extra":""},{"chapter":17,"key":"17:76","id":76,"word":"confess","phonetic":"/kənˈfes/","pos":"v.","meaningCN":"供认；忏悔","tag":"高频","root":"","exampleEN":"After hours of questioning, the suspect finally confessed to the theft.","exampleCN":"经过数小时的审问，嫌疑人终于供认了盗窃行为。","extra":"confession n. 供认，忏悔"},{"chapter":17,"key":"17:77","id":77,"word":"conform","phonetic":"/kənˈfɔːm/","pos":"v.","meaningCN":"遵守；顺从；相符合","tag":"高频","root":"","exampleEN":"All new buildings must conform to the latest fire safety standards.","exampleCN":"所有新建筑都必须符合最新的消防安全标准。","extra":"搭配：conform to/with 遵守，符合"},{"chapter":17,"key":"17:78","id":78,"word":"reconcile","phonetic":"/ˈrekənsaɪl/","pos":"v.","meaningCN":"使和解；调和","tag":"高频","root":"","exampleEN":"It was difficult to reconcile his version of the story with the facts.","exampleCN":"很难把他对事情的说法和事实调和起来。","extra":"搭配：be reconciled with sb. 与某人和解"},{"chapter":17,"key":"17:79","id":79,"word":"obey","phonetic":"/əʊˈbeɪ/","pos":"v.","meaningCN":"服从，顺从","tag":"核心","root":"","exampleEN":"Drivers are expected to obey all traffic signs and speed limits.","exampleCN":"司机应当遵守所有交通标志和车速限制。","extra":"obedient adj. 顺从的"},{"chapter":17,"key":"17:80","id":80,"word":"succumb","phonetic":"/səˈkʌm/","pos":"v.","meaningCN":"屈服，屈从","tag":"低频","root":"","exampleEN":"He finally succumbed to the pressure from his colleagues and changed his decision.","exampleCN":"他最终屈服于同事的压力，改变了自己的决定。","extra":"搭配：succumb to 屈服于……"},{"chapter":17,"key":"17:81","id":81,"word":"penalty","phonetic":"/ˈpenlti/","pos":"n.","meaningCN":"惩罚，处罚","tag":"核心","root":"","exampleEN":"The penalty for driving without insurance can be a heavy fine or even imprisonment.","exampleCN":"无保险驾驶的处罚可能是巨额罚款甚至监禁。","extra":"搭配：on penalty of 否则受……之罚"},{"chapter":17,"key":"17:82","id":82,"word":"fine","phonetic":"/faɪn/","pos":"n.","meaningCN":"罚款 adj. 美好的","tag":"核心","root":"","exampleEN":"He had to pay a fine of fifty dollars for parking in a restricted area.","exampleCN":"他因为在禁停区停车，不得不缴纳50美元罚款。","extra":""},{"chapter":17,"key":"17:83","id":83,"word":"mortgage","phonetic":"/ˈmɔːɡɪdʒ/","pos":"v.","meaningCN":"抵押（房屋、土地）借款 n. 房屋抵押贷款","tag":"高频","root":"","exampleEN":"They took out a 25-year mortgage to buy their first home.","exampleCN":"他们申请了一笔25年期的抵押贷款来购买第一套住房。","extra":""},{"chapter":17,"key":"17:84","id":84,"word":"ownership","phonetic":"/ˈəʊnəʃɪp/","pos":"n.","meaningCN":"所有权，物主身份","tag":"核心","root":"","exampleEN":"The company transferred the ownership of the land to the local council.","exampleCN":"公司把这块土地的所有权转让给了地方议会。","extra":"own v. 拥有；owner n. 主人"},{"chapter":17,"key":"17:85","id":85,"word":"copyright","phonetic":"/ˈkɒpiraɪt/","pos":"n.","meaningCN":"版权","tag":"高频","root":"","exampleEN":"You need permission from the author because the book is protected by copyright.","exampleCN":"你需要获得作者的许可，因为这本书受版权保护。","extra":""},{"chapter":17,"key":"17:86","id":86,"word":"privilege","phonetic":"/ˈprɪvəlɪdʒ/","pos":"n.","meaningCN":"特权","tag":"高频","root":"","exampleEN":"Having access to clean water should not be a privilege; it is a basic human right.","exampleCN":"获得干净饮用水不应该是一种特权，而是一项基本人权。","extra":""},{"chapter":17,"key":"17:87","id":87,"word":"accredit","phonetic":"/əˈkredɪt/","pos":"v.","meaningCN":"把......归于；委任","tag":"低频","root":"","exampleEN":"The discovery of the new species was accredited to a team of Chinese researchers.","exampleCN":"这个新物种的发现被归功于一个中国研究团队。","extra":""},{"chapter":17,"key":"17:88","id":88,"word":"clue","phonetic":"/kluː/","pos":"n.","meaningCN":"线索；提示","tag":"核心","root":"","exampleEN":"The detective searched the apartment carefully for any clue that might solve the case.","exampleCN":"侦探仔细搜查了那间公寓，寻找任何可能破案的线索。","extra":"词源：clew（线团）"},{"chapter":17,"key":"17:89","id":89,"word":"access","phonetic":"/ˈækses/","pos":"n.","meaningCN":"通路，入径；使用机会","tag":"核心","root":"","exampleEN":"The new ramp provides easy access for people in wheelchairs.","exampleCN":"新建的坡道为坐轮椅的人提供了方便的通道。","extra":"accessible adj. 可进入的；搭配：have/gain/get access to 可以使用或进入"},{"chapter":17,"key":"17:90","id":90,"word":"anonymous","phonetic":"/əˈnɒnɪməs/","pos":"adj.","meaningCN":"匿名的","tag":"高频","root":"onym = 名字","exampleEN":"The charity received an anonymous donation of one million dollars last week.","exampleCN":"上周该慈善机构收到了一笔一百万美元的匿名捐款。","extra":""},{"chapter":17,"key":"17:91","id":91,"word":"false","phonetic":"/fɔːls/","pos":"adj.","meaningCN":"不正确的；虚假的；伪造的","tag":"核心","root":"","exampleEN":"He was arrested for using a false passport to enter the country.","exampleCN":"他因为使用假护照入境而被逮捕。","extra":"falsehood n. 虚假；谎言"},{"chapter":17,"key":"17:92","id":92,"word":"genuine","phonetic":"/ˈdʒenjuːɪn/","pos":"adj.","meaningCN":"真诚的；真正的","tag":"核心","root":"","exampleEN":"The expert confirmed that the painting was a genuine work by Van Gogh.","exampleCN":"专家证实了这幅画是梵高的真迹。","extra":""},{"chapter":17,"key":"17:93","id":93,"word":"procedure","phonetic":"/prəˈsiːdʒə/","pos":"n.","meaningCN":"手续；程序","tag":"核心","root":"","exampleEN":"The staff will explain the procedure for applying for a visa.","exampleCN":"工作人员会说明申请签证的程序。","extra":""},{"chapter":17,"key":"17:94","id":94,"word":"routine","phonetic":"/ruːˈtiːn/","pos":"n.","meaningCN":"例行公事；常规 adj. 惯例的","tag":"核心","root":"","exampleEN":"Checking emails first thing in the morning has become part of his daily routine.","exampleCN":"早上第一件事就是查看邮件，这已成为他日常惯例的一部分。","extra":""},{"chapter":17,"key":"17:95","id":95,"word":"consequence","phonetic":"/ˈkɒnsɪkwəns/","pos":"n.","meaningCN":"后果","tag":"核心","root":"","exampleEN":"The company ignored safety warnings, and now it is facing serious financial consequences.","exampleCN":"那家公司忽视了安全警告，现在正面临严重的经济后果。","extra":"consequent adj. 随之发生的；搭配：in consequence 结果"},{"chapter":17,"key":"17:96","id":96,"word":"demand","phonetic":"/dɪˈmænd/","pos":"v.","meaningCN":"要求；需要 n. 需求","tag":"核心","root":"","exampleEN":"Consumers are demanding more environmentally friendly products from manufacturers.","exampleCN":"消费者正要求制造商提供更环保的产品。","extra":"demanding adj. 要求高的；搭配：demand for 对……的需求"},{"chapter":17,"key":"17:97","id":97,"word":"request","phonetic":"/rɪˈkwest/","pos":"n./v.","meaningCN":"要求，请求","tag":"核心","root":"","exampleEN":"They sent a request to the library to extend the borrowing period for another week.","exampleCN":"他们向图书馆发出请求，把借阅期限再延长一周。","extra":""},{"chapter":17,"key":"17:98","id":98,"word":"require","phonetic":"/rɪˈkwaɪə/","pos":"v.","meaningCN":"需要；命令，规定","tag":"核心","root":"","exampleEN":"The job requires excellent communication skills and the ability to work in a team.","exampleCN":"这份工作要求出色的沟通技巧和团队合作能力。","extra":"requirement n. 要求"},{"chapter":17,"key":"17:99","id":99,"word":"petition","phonetic":"/pɪˈtɪʃn/","pos":"v.","meaningCN":"请求 n. 请愿书；上诉","tag":"高频","root":"pet = 寻求","exampleEN":"Over 10,000 people signed the petition calling for the recycling centre to stay open.","exampleCN":"超过一万人签署了请愿书，要求回收中心继续开放。","extra":""},{"chapter":17,"key":"17:100","id":100,"word":"command","phonetic":"/kəˈmænd/","pos":"v.","meaningCN":"命令；指挥 n. 命令；控制；运用能力","tag":"核心","root":"","exampleEN":"The officer commanded the soldiers to stand still and wait for further orders.","exampleCN":"军官命令士兵们站在原地不动，等待下一步命令。","extra":"commander n. 指挥官；搭配：have a good command of 精通……"},{"chapter":17,"key":"17:101","id":101,"word":"instruct","phonetic":"/ɪnˈstrʌkt/","pos":"v.","meaningCN":"指导，讲授；通知；命令","tag":"核心","root":"","exampleEN":"The safety guide instructs passengers on what to do in case of an emergency.","exampleCN":"安全指南指导乘客在紧急情况下应该怎么做。","extra":"instruction n. 指示，教导"}],"18":[{"chapter":18,"key":"18:1","id":1,"word":"violence","phonetic":"/ˈvaɪələns/","pos":"n.","meaningCN":"暴力","tag":"核心","root":"","exampleEN":"The government called for an end to the violence after days of street clashes.","exampleCN":"在持续数日的街头冲突后，政府呼吁结束暴力行为。","extra":"violent adj. 猛烈的；暴力的"},{"chapter":18,"key":"18:2","id":2,"word":"conflict","phonetic":"/ˈkɒnflɪkt/","pos":"n.","meaningCN":"斗争，冲突 / v. 冲突","tag":"核心","root":"","exampleEN":"There is often a conflict between the desire for freedom and the need for security.","exampleCN":"对自由的渴望与对安全的需求之间常常存在冲突。","extra":"搭配：a conflict of interest 利益冲突"},{"chapter":18,"key":"18:3","id":3,"word":"raid","phonetic":"/reɪd/","pos":"n./v.","meaningCN":"突袭；突然搜查","tag":"高频","root":"","exampleEN":"The police carried out a dawn raid on the suspected drug house.","exampleCN":"警方对那处可疑的毒窝进行了一次拂晓突袭。","extra":"搭配：carry out a raid 实施突然袭击"},{"chapter":18,"key":"18:4","id":4,"word":"enormity","phonetic":"/ɪˈnɔːməti/","pos":"n.","meaningCN":"巨大；滔天大罪","tag":"低频","root":"","exampleEN":"The enormity of the task ahead felt overwhelming to the small team.","exampleCN":"前方任务的艰巨性让这个小团队感到难以招架。","extra":"搭配：the enormity of the task 任务的艰巨性"},{"chapter":18,"key":"18:5","id":5,"word":"campaign","phonetic":"/kæmˈpeɪn/","pos":"n.","meaningCN":"战役；（社会、政治）运动 v. 参加（或领导）运动","tag":"核心","root":"","exampleEN":"They launched a national campaign to raise awareness of mental health issues.","exampleCN":"他们发起了一场全国性的运动，以提高人们对心理健康问题的认识。","extra":"搭配：organise a campaign 组织一场运动"},{"chapter":18,"key":"18:6","id":6,"word":"battle","phonetic":"/ˈbætl/","pos":"n.","meaningCN":"战斗，战役 v. 与......战斗","tag":"核心","root":"","exampleEN":"The soldiers fought a fierce battle to defend the city from the invaders.","exampleCN":"士兵们为保卫城市免遭入侵者攻击而进行了一场激烈的战斗。","extra":""},{"chapter":18,"key":"18:7","id":7,"word":"struggle","phonetic":"/ˈstrʌɡl/","pos":"v./n.","meaningCN":"挣扎；奋力；奋斗","tag":"核心","root":"","exampleEN":"Many families in the region still struggle to get enough food each day.","exampleCN":"该地区的许多家庭每天仍难以获得足够的食物。","extra":"搭配：struggle against 与......抗争"},{"chapter":18,"key":"18:8","id":8,"word":"explosion","phonetic":"/ɪkˈspləʊʒn/","pos":"n.","meaningCN":"爆发；迸发；爆炸；激增","tag":"核心","root":"","exampleEN":"The explosion at the chemical plant could be heard several miles away.","exampleCN":"化工厂的爆炸声在几英里外都能听到。","extra":"explode v. 爆炸；explosive adj. 爆炸性的；搭配：a population explosion 人口激增"},{"chapter":18,"key":"18:9","id":9,"word":"bombard","phonetic":"/bɒmˈbɑːd/","pos":"v.","meaningCN":"轰击，轰炸；连珠炮般质问（或批评）","tag":"高频","root":"","exampleEN":"Reporters bombarded the spokesperson with questions about the scandal.","exampleCN":"记者们连珠炮般地向发言人提出了有关该丑闻的问题。","extra":""},{"chapter":18,"key":"18:10","id":10,"word":"bomb","phonetic":"/bɒm/","pos":"n.","meaningCN":"炸弹 v. 轰炸","tag":"核心","root":"","exampleEN":"The bomb threat forced the evacuation of the entire shopping centre.","exampleCN":"炸弹威胁迫使整个购物中心的人员疏散。","extra":"搭配：set off a bomb 引爆炸弹"},{"chapter":18,"key":"18:11","id":11,"word":"blast","phonetic":"/blɑːst/","pos":"n.","meaningCN":"爆炸 v. 炸毁","tag":"核心","root":"","exampleEN":"The builders used explosives to blast a tunnel through the solid rock.","exampleCN":"建筑工人用炸药在坚硬的岩石中炸出了一条隧道。","extra":""},{"chapter":18,"key":"18:12","id":12,"word":"burst","phonetic":"/bɜːst/","pos":"v.","meaningCN":"(使)爆裂；（使）胀开 n. 迸发；爆裂","tag":"核心","root":"","exampleEN":"The children burst into laughter when the clown tripped over his own feet.","exampleCN":"当小丑被自己的脚绊倒时，孩子们爆发出一阵大笑。","extra":"搭配：go burst 破产；burst on 突然在......出现"},{"chapter":18,"key":"18:13","id":13,"word":"spark","phonetic":"/spɑːk/","pos":"n.","meaningCN":"火花，火星","tag":"高频","root":"","exampleEN":"A single spark from the campfire flew into the dry grass and started a wildfire.","exampleCN":"篝火的一个小火花溅入干草丛，引发了一场野火。","extra":"sparkle v. 闪闪发光，闪耀；聪明活泼"},{"chapter":18,"key":"18:14","id":14,"word":"twinkle","phonetic":"/ˈtwɪŋkl/","pos":"n./v.","meaningCN":"闪烁，闪耀","tag":"高频","root":"","exampleEN":"We could see the lights of the harbour twinkling in the distance.","exampleCN":"我们可以看见港湾的灯光在远处闪烁。","extra":""},{"chapter":18,"key":"18:15","id":15,"word":"glitter","phonetic":"/ˈɡlɪtə(r)/","pos":"v.","meaningCN":"闪闪发光，闪烁","tag":"高频","root":"","exampleEN":"Her diamond ring glittered under the bright lights of the ballroom.","exampleCN":"她的钻石戒指在舞厅明亮的灯光下闪闪发光。","extra":"glittery adj. 闪闪发亮的"},{"chapter":18,"key":"18:16","id":16,"word":"glow","phonetic":"/ɡləʊ/","pos":"v.","meaningCN":"发出微弱稳定的光 n. 微弱稳定的光","tag":"高频","root":"","exampleEN":"The red maple leaves seemed to glow in the golden afternoon sunlight.","exampleCN":"红色的枫叶在金色的午后阳光里闪耀着光芒。","extra":""},{"chapter":18,"key":"18:17","id":17,"word":"blade","phonetic":"/bleɪd/","pos":"n.","meaningCN":"刃，锋；（螺旋桨的）叶片","tag":"高频","root":"","exampleEN":"Be careful not to cut your fingers on the sharp blade of the kitchen knife.","exampleCN":"小心别被菜刀的利刃割伤手指。","extra":""},{"chapter":18,"key":"18:18","id":18,"word":"sword","phonetic":"/sɔːd/","pos":"n.","meaningCN":"刀，剑","tag":"高频","root":"","exampleEN":"Fame can be a double-edged sword that brings both admiration and criticism.","exampleCN":"名声可能是一把双刃剑，既带来仰慕也带来批评。","extra":"搭配：draw a sword 拔剑"},{"chapter":18,"key":"18:19","id":19,"word":"ax","phonetic":"/æks/","pos":"n.","meaningCN":"斧子","tag":"高频","root":"","exampleEN":"He used a sharp ax to chop firewood for the winter stove.","exampleCN":"他用一把锋利的斧子为冬天的炉子劈柴火。","extra":""},{"chapter":18,"key":"18:20","id":20,"word":"hammer","phonetic":"/ˈhæmə(r)/","pos":"n.","meaningCN":"锤，榔头 v. 用锤击","tag":"高频","root":"","exampleEN":"She used a hammer to drive the nail firmly into the wooden board.","exampleCN":"她用一把锤子把钉子牢牢地钉进木板里。","extra":"搭配：hammer sth. into sb. 向某人反复强调某种思想观点等"},{"chapter":18,"key":"18:21","id":21,"word":"bow","phonetic":"/bəʊ/","pos":"n.","meaningCN":"弓；蝴蝶结","tag":"高频","root":"","exampleEN":"In the past, hunters relied on a bow and arrows to catch wild animals.","exampleCN":"在过去，猎人依靠弓箭来捕捉野生动物。","extra":""},{"chapter":18,"key":"18:22","id":22,"word":"arrow","phonetic":"/ˈærəʊ/","pos":"n.","meaningCN":"箭；箭头","tag":"高频","root":"","exampleEN":"The archer aimed an arrow carefully at the target in the centre of the field.","exampleCN":"弓箭手小心地把箭瞄准场地中央的靶子。","extra":"搭配：aim an arrow at 把箭瞄准"},{"chapter":18,"key":"18:23","id":23,"word":"spear","phonetic":"/spɪə(r)/","pos":"n.","meaningCN":"矛；标枪 v. 用尖物刺穿","tag":"高频","root":"","exampleEN":"The museum displays a beautifully decorated spear from the ancient tribe.","exampleCN":"博物馆展出了一支来自古老部落的装饰精美的长矛。","extra":""},{"chapter":18,"key":"18:24","id":24,"word":"helmet","phonetic":"/ˈhelmɪt/","pos":"n.","meaningCN":"头盔，防护帽","tag":"核心","root":"","exampleEN":"It is essential to wear a helmet when riding a motorcycle for your own safety.","exampleCN":"骑摩托车时为了自身安全，必须佩戴头盔。","extra":""},{"chapter":18,"key":"18:25","id":25,"word":"shield","phonetic":"/ʃiːld/","pos":"n.","meaningCN":"盾；防护物 v. 保护","tag":"高频","root":"","exampleEN":"The thick ozone layer acts as a natural shield against harmful ultraviolet rays.","exampleCN":"厚厚的臭氧层充挡有害紫外线的天然防护物。","extra":"搭配：a shield against 抵挡......的防护物"},{"chapter":18,"key":"18:26","id":26,"word":"equip","phonetic":"/ɪˈkwɪp/","pos":"v.","meaningCN":"配备，装备","tag":"核心","root":"","exampleEN":"The laboratory is now fully equipped with the latest research instruments.","exampleCN":"该实验室现在配备了最新的研究仪器。","extra":"equipment n. 设备；搭配：be equipped with 装备有"},{"chapter":18,"key":"18:27","id":27,"word":"prepare","phonetic":"/prɪˈpeə(r)/","pos":"v.","meaningCN":"使预备好；为......做准备","tag":"核心","root":"","exampleEN":"Students should start to prepare for the final examination several weeks in advance.","exampleCN":"学生应该提前几周就开始为期末考试做准备。","extra":"preparation n. 准备；搭配：prepare for 为......做准备"},{"chapter":18,"key":"18:28","id":28,"word":"provide","phonetic":"/prəˈvaɪd/","pos":"v.","meaningCN":"供给，提供","tag":"核心","root":"","exampleEN":"This program provides young people with valuable skills for the job market.","exampleCN":"这个项目为年轻人提供了对就业市场很有价值的技能。","extra":"provision n. 供应；搭配：provide sb. with sth. 为某人提供某物"},{"chapter":18,"key":"18:29","id":29,"word":"deploy","phonetic":"/dɪˈplɔɪ/","pos":"v.","meaningCN":"部署","tag":"高频","root":"","exampleEN":"The government decided to deploy additional police officers to the troubled area.","exampleCN":"政府决定向动乱地区增派警察。","extra":"deployment n. 部署"},{"chapter":18,"key":"18:30","id":30,"word":"hit","phonetic":"/hɪt/","pos":"v.","meaningCN":"击，打；碰撞；打击 n. 击，打；击中","tag":"核心","root":"","exampleEN":"The small car was seriously damaged when it was hit by a speeding truck.","exampleCN":"那辆小轿车被一辆超速的卡车撞上，受损严重。","extra":"搭配：hit a level 达到一个水平"},{"chapter":18,"key":"18:31","id":31,"word":"beat","phonetic":"/biːt/","pos":"v.","meaningCN":"打；打败；（心脏等）跳动 n. 节拍；击鼓声","tag":"核心","root":"","exampleEN":"She managed to beat her biggest rival in the final and won the gold medal.","exampleCN":"她在决赛中击败了最大的对手，赢得了金牌。","extra":"搭配：beat a record 打破纪录"},{"chapter":18,"key":"18:32","id":32,"word":"strike","phonetic":"/straɪk/","pos":"v.","meaningCN":"打，击；突击；罢工 n. 罢工；打击","tag":"核心","root":"","exampleEN":"The workers decided to go on strike to demand higher pay and better conditions.","exampleCN":"工人们决定举行罢工，要求提高工资和改善条件。","extra":"搭配：strike against 为反对而罢工"},{"chapter":18,"key":"18:33","id":33,"word":"punch","phonetic":"/pʌntʃ/","pos":"n.","meaningCN":"打孔机；重拳击打 v. 给......打孔；拳打","tag":"核心","root":"","exampleEN":"He punched the bag hard with his right hand during the boxing training session.","exampleCN":"在拳击训练课上，他右手猛击沙袋。","extra":"搭配：punch in/out 上/下班打卡"},{"chapter":18,"key":"18:34","id":34,"word":"chop","phonetic":"/tʃɒp/","pos":"v.","meaningCN":"切碎（食物）；劈（木头）","tag":"核心","root":"","exampleEN":"She chopped the carrots into small pieces before adding them to the soup.","exampleCN":"她把胡萝卜切成小块，然后加到汤里。","extra":"搭配：chop away 砍掉，切掉"},{"chapter":18,"key":"18:35","id":35,"word":"stab","phonetic":"/stæb/","pos":"v./n.","meaningCN":"（用刀等）刺，戳","tag":"高频","root":"","exampleEN":"He felt a sudden sharp pain as if a needle had stabbed his finger.","exampleCN":"他突然感到一阵剧痛，仿佛有根针扎了他的手指。","extra":"搭配：stab at（用刀等）刺"},{"chapter":18,"key":"18:36","id":36,"word":"dilemma","phonetic":"/dɪˈlemə/","pos":"n.","meaningCN":"（进退两难的）困境","tag":"高频","root":"","exampleEN":"She faced a real dilemma when both job offers arrived on the same day.","exampleCN":"当两份工作机会在同一天到来时，她陷入了真正的两难境地。","extra":""},{"chapter":18,"key":"18:37","id":37,"word":"plight","phonetic":"/plaɪt/","pos":"n.","meaningCN":"困境；誓约","tag":"低频","root":"","exampleEN":"The news report focused on the plight of families who lost their homes in the flood.","exampleCN":"这则新闻报道聚焦于那些在洪水中失去家园的家庭的困境。","extra":""},{"chapter":18,"key":"18:38","id":38,"word":"pitfall","phonetic":"/ˈpɪtfɔːl/","pos":"n.","meaningCN":"陷阱；危险，困难","tag":"低频","root":"","exampleEN":"One common pitfall of learning a new language is giving up too quickly.","exampleCN":"学习一门新语言的一个常见陷阱就是太快放弃。","extra":""},{"chapter":18,"key":"18:39","id":39,"word":"conspiracy","phonetic":"/kənˈspɪrəsi/","pos":"n.","meaningCN":"阴谋，密谋，合谋","tag":"高频","root":"","exampleEN":"The group was arrested for their conspiracy to overthrow the government.","exampleCN":"这群人因密谋推翻政府而被捕。","extra":"conspire v. 密谋"},{"chapter":18,"key":"18:40","id":40,"word":"destitute","phonetic":"/ˈdestɪtjuːt/","pos":"adj.","meaningCN":"赤贫的，一无所有的；缺乏的","tag":"低频","root":"","exampleEN":"The charity provides shelter for destitute families who have nowhere else to go.","exampleCN":"这家慈善机构为无处可去的赤贫家庭提供住宿。","extra":"搭配：be destitute of 缺乏"},{"chapter":18,"key":"18:41","id":41,"word":"famine","phonetic":"/ˈfæmɪn/","pos":"n.","meaningCN":"饥荒","tag":"核心","root":"","exampleEN":"Crop failures and conflict led to a severe famine in the region.","exampleCN":"粮食歉收和冲突导致该地区发生了严重的饥荒。","extra":""},{"chapter":18,"key":"18:42","id":42,"word":"starve","phonetic":"/stɑːv/","pos":"v.","meaningCN":"（使）挨饿，饿死","tag":"核心","root":"","exampleEN":"Millions of people were at risk of starving because of the prolonged drought.","exampleCN":"由于长期干旱，数百万人面临饿死的危险。","extra":"starvation n. 饿死，极度饥饿"},{"chapter":18,"key":"18:43","id":43,"word":"deprive","phonetic":"/dɪˈpraɪv/","pos":"v.","meaningCN":"剥夺","tag":"高频","root":"","exampleEN":"Nobody should be deprived of the opportunity to receive a basic education.","exampleCN":"任何人都不应被剥夺接受基础教育的机会。","extra":"deprivation n. 剥夺；搭配：deprive sb. of sth. 剥夺某人的某事物"},{"chapter":18,"key":"18:44","id":44,"word":"seize","phonetic":"/siːz/","pos":"v.","meaningCN":"抓住；夺取","tag":"核心","root":"","exampleEN":"He seized the chance to study abroad when the scholarship was offered to him.","exampleCN":"当获得奖学金的机会来临时，他抓住了这个出国学习的机会。","extra":"搭配：seize a moment 抓住时机"},{"chapter":18,"key":"18:45","id":45,"word":"pursue","phonetic":"/pəˈsjuː/","pos":"v.","meaningCN":"追赶；追查；追求","tag":"核心","root":"","exampleEN":"After university, she decided to pursue a career in environmental science.","exampleCN":"大学毕业后，她决定从事环境科学方面的工作。","extra":"pursuit n. 追赶；追求"},{"chapter":18,"key":"18:46","id":46,"word":"attack","phonetic":"/əˈtæk/","pos":"v./n.","meaningCN":"攻击，进攻","tag":"核心","root":"","exampleEN":"The soldiers launched a surprise attack on the enemy camp at dawn.","exampleCN":"士兵们在拂晓时分对敌营发动了突然袭击。","extra":""},{"chapter":18,"key":"18:47","id":47,"word":"offend","phonetic":"/əˈfend/","pos":"v.","meaningCN":"冒犯；犯罪；违反","tag":"高频","root":"","exampleEN":"I hope my words did not offend you; I was only trying to be honest.","exampleCN":"我希望我的话没有冒犯到你，我只是想坦诚一些。","extra":"offender n. 罪犯；搭配：offend against 违反"},{"chapter":18,"key":"18:48","id":48,"word":"aggressive","phonetic":"/əˈɡresɪv/","pos":"adj.","meaningCN":"侵略的；好斗的；积极进取的","tag":"核心","root":"","exampleEN":"An aggressive marketing strategy helped the new brand become popular quickly.","exampleCN":"一个积极进取的营销策略帮助这个新品牌迅速流行起来。","extra":"aggressiveness n. 好斗；aggress v. 挑衅"},{"chapter":18,"key":"18:49","id":49,"word":"invade","phonetic":"/ɪnˈveɪd/","pos":"v.","meaningCN":"入侵，侵略；侵扰","tag":"核心","root":"","exampleEN":"The virus can invade healthy cells and cause serious illness.","exampleCN":"这种病毒可以侵入健康细胞并导致严重疾病。","extra":"invasion n. 侵犯；invader n. 侵略者；搭配：invade privacy 侵犯隐私"},{"chapter":18,"key":"18:50","id":50,"word":"trespass","phonetic":"/ˈtrespəs/","pos":"v.","meaningCN":"非法侵入 n. 罪过；非法侵入","tag":"低频","root":"","exampleEN":"The sign on the gate clearly warned people not to trespass on private property.","exampleCN":"大门上的牌子明确警告人们不得擅自进入私人领地。","extra":""},{"chapter":18,"key":"18:51","id":51,"word":"threat","phonetic":"/θret/","pos":"n.","meaningCN":"威胁，恐吓","tag":"核心","root":"","exampleEN":"The rising sea level poses a serious threat to many coastal communities.","exampleCN":"不断上升的海平面对许多沿海社区构成了严重威胁。","extra":"threaten v. 威胁，恐吓"},{"chapter":18,"key":"18:52","id":52,"word":"intrude","phonetic":"/ɪnˈtruːd/","pos":"v.","meaningCN":"闯入，侵入；侵扰","tag":"高频","root":"","exampleEN":"I felt I was intruding on their private conversation and decided to leave the room.","exampleCN":"我觉得自己打扰了他们的私人谈话，于是决定离开房间。","extra":""},{"chapter":18,"key":"18:53","id":53,"word":"violate","phonetic":"/ˈvaɪəleɪt/","pos":"v.","meaningCN":"违反，违背；侵犯；搅扰","tag":"核心","root":"","exampleEN":"The company was heavily fined for violating environmental protection laws.","exampleCN":"那家公司因违反环境保护法被处以巨额罚款。","extra":"violation n. 违反；搭配：violate a law 犯法"},{"chapter":18,"key":"18:54","id":54,"word":"assault","phonetic":"/əˈsɔːlt/","pos":"n.","meaningCN":"猛攻；（身体）侵犯 v. 袭击","tag":"高频","root":"","exampleEN":"He was charged with assault after the fight outside the nightclub.","exampleCN":"夜总会外的斗殴事件后，他被控犯有人身侵犯。","extra":"搭配：an assault on/against 对......的（人身）侵犯"},{"chapter":18,"key":"18:55","id":55,"word":"challenge","phonetic":"/ˈtʃælɪndʒ/","pos":"n.","meaningCN":"挑战 v. 向......挑战","tag":"核心","root":"","exampleEN":"Moving to a new city was a big challenge, but she adapted quickly.","exampleCN":"搬到新城市是一个巨大的挑战，但她很快就适应了。","extra":"challenging adj. 有挑战性的；搭配：face a challenge 面对挑战"},{"chapter":18,"key":"18:56","id":56,"word":"siege","phonetic":"/siːdʒ/","pos":"n.","meaningCN":"包围，围攻","tag":"高频","root":"","exampleEN":"The castle was under siege for several months before the defenders finally surrendered.","exampleCN":"城堡被围困了几个月，守军才最终投降。","extra":""},{"chapter":18,"key":"18:57","id":57,"word":"surround","phonetic":"/səˈraʊnd/","pos":"v.","meaningCN":"包围；环绕","tag":"核心","root":"","exampleEN":"The beautiful garden is surrounded by a tall wooden fence for privacy.","exampleCN":"那座美丽的花园被一道高高的木篱笆围着，以保护隐私。","extra":"surroundings n. 环境；搭配：be surrounded by 被......包围"},{"chapter":18,"key":"18:58","id":58,"word":"enclose","phonetic":"/ɪnˈkləʊz/","pos":"v.","meaningCN":"围住，包围；把......封入信封","tag":"高频","root":"","exampleEN":"Please remember to enclose a recent photograph with your application form.","exampleCN":"请记住在申请表里附上一张近照。","extra":"搭配：enclose sth. with a letter 随信附上某物"},{"chapter":18,"key":"18:59","id":59,"word":"pause","phonetic":"/pɔːz/","pos":"n./v.","meaningCN":"暂停，停顿","tag":"核心","root":"","exampleEN":"He paused at the top of the hill to enjoy the wonderful view of the valley.","exampleCN":"他在山顶停下来欣赏山谷的美景。","extra":"搭配：come to a pause 暂停"},{"chapter":18,"key":"18:60","id":60,"word":"halt","phonetic":"/hɔːlt/","pos":"v.","meaningCN":"（使）停止，（使）停住 n. 停止，停住","tag":"核心","root":"","exampleEN":"All construction work was halted because of the heavy snowstorm.","exampleCN":"由于特大暴风雪，所有施工都停止了。","extra":""},{"chapter":18,"key":"18:61","id":61,"word":"cease","phonetic":"/siːs/","pos":"v.","meaningCN":"终止，停止","tag":"核心","root":"","exampleEN":"The two sides agreed to cease all military operations with immediate effect.","exampleCN":"双方同意立即停止一切军事行动。","extra":"搭配：cease fire 停火"},{"chapter":18,"key":"18:62","id":62,"word":"oppose","phonetic":"/əˈpəʊz/","pos":"v.","meaningCN":"反对，抵制","tag":"核心","root":"","exampleEN":"Many local residents strongly oppose the building of a new factory near the river.","exampleCN":"许多当地居民强烈反对在河边建一座新工厂。","extra":"opponent n. 对手；opposite adj. 相反的"},{"chapter":18,"key":"18:63","id":63,"word":"oppress","phonetic":"/əˈpres/","pos":"v.","meaningCN":"压迫，压制；使压抑","tag":"高频","root":"","exampleEN":"The people were oppressed by the military rule for many years.","exampleCN":"人民被军事统治压迫了许多年。","extra":"oppressive adj. 压制的"},{"chapter":18,"key":"18:64","id":64,"word":"counter","phonetic":"/ˈkaʊntə(r)/","pos":"v.","meaningCN":"抵消；反击，反驳 adv. 相反地 n. 柜台","tag":"核心","root":"","exampleEN":"She countered every argument he made with strong evidence from her research.","exampleCN":"她用自己研究的有力证据反驳了他提出的每一个论点。","extra":""},{"chapter":18,"key":"18:65","id":65,"word":"deter","phonetic":"/dɪˈtɜː(r)/","pos":"v.","meaningCN":"阻止，威慑住","tag":"高频","root":"","exampleEN":"Strict punishment may deter some people from committing minor crimes.","exampleCN":"严厉的惩罚可能会阻止一些人犯轻罪。","extra":"搭配：deter sb. from doing sth. 阻止某人做某事"},{"chapter":18,"key":"18:66","id":66,"word":"forbid","phonetic":"/fəˈbɪd/","pos":"v.","meaningCN":"禁止；阻止","tag":"核心","root":"","exampleEN":"The school forbids students from using mobile phones during class hours.","exampleCN":"学校禁止学生在课堂时间使用手机。","extra":"搭配：forbid sb. from doing sth. 禁止某人做某事"},{"chapter":18,"key":"18:67","id":67,"word":"prohibit","phonetic":"/prəˈhɪbɪt/","pos":"v.","meaningCN":"禁止，不允许","tag":"核心","root":"","exampleEN":"International law prohibits the use of chemical weapons under any circumstances.","exampleCN":"国际法禁止在任何情况下使用化学武器。","extra":"prohibition n. 禁止；搭配：prohibit sb. from doing sth. 禁止某人做某事"},{"chapter":18,"key":"18:68","id":68,"word":"prevent","phonetic":"/prɪˈvent/","pos":"v.","meaningCN":"预防，防止；阻止，阻碍","tag":"核心","root":"","exampleEN":"Regular exercise and a healthy diet can help prevent many common diseases.","exampleCN":"经常锻炼和健康饮食有助于预防许多常见疾病。","extra":"prevention n. 预防"},{"chapter":18,"key":"18:69","id":69,"word":"revolt","phonetic":"/rɪˈvəʊlt/","pos":"n./v.","meaningCN":"叛乱；反抗","tag":"高频","root":"","exampleEN":"The harsh treatment of the workers eventually led to a widespread revolt.","exampleCN":"对工人的残酷对待最终引发了一场广泛的起义。","extra":"搭配：rise in revolt 发生叛乱"},{"chapter":18,"key":"18:70","id":70,"word":"betray","phonetic":"/bɪˈtreɪ/","pos":"v.","meaningCN":"背叛，出卖；（无意中）泄露","tag":"核心","root":"","exampleEN":"He felt deeply hurt when he realised his best friend had betrayed his trust.","exampleCN":"当他意识到最好的朋友背叛了他的信任时，他感到深受伤害。","extra":"betrayal n. 背叛；搭配：betray one's country 背叛祖国"},{"chapter":18,"key":"18:71","id":71,"word":"treason","phonetic":"/ˈtriːzn/","pos":"n.","meaningCN":"叛国罪，通敌罪","tag":"低频","root":"","exampleEN":"The general was found guilty of treason for passing sensitive information to the enemy.","exampleCN":"那名将军因向敌方传递敏感情报而被判叛国罪。","extra":""},{"chapter":18,"key":"18:72","id":72,"word":"rebel","phonetic":"/ˈrebl/","pos":"n.","meaningCN":"反叛者 / v. 造反；反抗","tag":"高频","root":"","exampleEN":"A group of rebels took control of the radio station and broadcast their demands.","exampleCN":"一伙反叛者控制了广播电台，播报了他们的要求。","extra":"rebellion n. 造反；搭配：rebel against sth. 反对某事"},{"chapter":18,"key":"18:73","id":73,"word":"traitor","phonetic":"/ˈtreɪtə(r)/","pos":"n.","meaningCN":"叛徒，卖国贼","tag":"高频","root":"","exampleEN":"During the war, anyone caught working with the enemy was labelled a traitor.","exampleCN":"战争期间，任何被发现为敌方效力的人都被称为卖国贼。","extra":""},{"chapter":18,"key":"18:74","id":74,"word":"patriot","phonetic":"/ˈpætriət/","pos":"n.","meaningCN":"爱国者","tag":"高频","root":"","exampleEN":"He is remembered as a true patriot who devoted his life to his country.","exampleCN":"他被人们铭记为一位真正的爱国者，将一生奉献给了祖国。","extra":"patriotism n. 爱国主义"},{"chapter":18,"key":"18:75","id":75,"word":"blame","phonetic":"/bleɪm/","pos":"v.","meaningCN":"责备，指责 n. 责任","tag":"核心","root":"","exampleEN":"It is not fair to blame the entire team for the mistake of one person.","exampleCN":"把一个人的错误归咎于整个团队是不公平的。","extra":"搭配：blame sth. on sb. 把某事归咎于某人"},{"chapter":18,"key":"18:76","id":76,"word":"reproach","phonetic":"/rɪˈprəʊtʃ/","pos":"n.","meaningCN":"责备，指责","tag":"低频","root":"","exampleEN":"His behaviour during the ceremony was beyond reproach and earned him much respect.","exampleCN":"他在典礼上的举止无可挑剔，为他赢得了许多尊重。","extra":"搭配：bring reproach on oneself 让自己丢脸"},{"chapter":18,"key":"18:77","id":77,"word":"evidence","phonetic":"/ˈevɪdəns/","pos":"n.","meaningCN":"证据；根据","tag":"核心","root":"","exampleEN":"There is not enough evidence to prove that he was at the crime scene.","exampleCN":"没有足够的证据证明他当时在犯罪现场。","extra":"evident adj. 明显的；搭配：written evidence 书面证据"},{"chapter":18,"key":"18:78","id":78,"word":"proof","phonetic":"/pruːf/","pos":"n.","meaningCN":"证明，证据","tag":"核心","root":"","exampleEN":"Can you show me any proof that this handbag really belongs to you?","exampleCN":"你能给我出示任何证明这个手提包是你的的证据吗？","extra":"prove v. 证明"},{"chapter":18,"key":"18:79","id":79,"word":"terror","phonetic":"/ˈterə(r)/","pos":"n.","meaningCN":"恐惧，恐慌","tag":"核心","root":"","exampleEN":"The sound of the explosion filled the crowd with shock and terror.","exampleCN":"爆炸声让众人充满了震惊和恐惧。","extra":"terrorist n. 恐怖分子；搭配：in terror 惊慌地"},{"chapter":18,"key":"18:80","id":80,"word":"terrible","phonetic":"/ˈterəbl/","pos":"adj.","meaningCN":"可怕的，糟糕的；极严重的","tag":"核心","root":"","exampleEN":"That earthquake was a terrible disaster and destroyed thousands of homes.","exampleCN":"那场地震是一个可怕的灾难，摧毁了成千上万座房屋。","extra":""},{"chapter":18,"key":"18:81","id":81,"word":"terrific","phonetic":"/təˈrɪfɪk/","pos":"adj.","meaningCN":"极好的；很大的，很强的","tag":"高频","root":"","exampleEN":"You did a terrific job on the presentation; everyone was very impressed.","exampleCN":"你的演示做得非常出色，每个人都很佩服。","extra":""},{"chapter":18,"key":"18:82","id":82,"word":"horrible","phonetic":"/ˈhɒrəbl/","pos":"adj.","meaningCN":"可怕的，恐怖的","tag":"核心","root":"","exampleEN":"A horrible accident happened here yesterday and the road is still closed.","exampleCN":"昨天这里发生了一起可怕的事故，道路仍然封闭。","extra":"horror n. 恐怖"},{"chapter":18,"key":"18:83","id":83,"word":"alarm","phonetic":"/əˈlɑːm/","pos":"n.","meaningCN":"惊恐，忧虑；警报；警报器","tag":"核心","root":"","exampleEN":"As soon as they heard the fire alarm, they calmly left the building.","exampleCN":"他们一听到火警，就冷静地离开了大楼。","extra":"搭配：raise an alarm 发出警报"},{"chapter":18,"key":"18:84","id":84,"word":"tension","phonetic":"/ˈtenʃn/","pos":"n.","meaningCN":"紧张；拉紧状态","tag":"核心","root":"","exampleEN":"International tension increased after the two countries recalled their ambassadors.","exampleCN":"两国互相召回大使后，国际紧张局势加剧了。","extra":"tense adj. 绷紧的；搭配：ease the tension 缓和紧张局势"},{"chapter":18,"key":"18:85","id":85,"word":"turbulent","phonetic":"/ˈtɜːbjələnt/","pos":"adj.","meaningCN":"动荡的，混乱的；汹涌的","tag":"高频","root":"","exampleEN":"The country went through a turbulent period of social change in the early 1960s.","exampleCN":"该国在20世纪60年代初经历了一个动荡的社会变革时期。","extra":"turbulence n. 骚乱；搭配：a turbulent period 动荡的时期"},{"chapter":18,"key":"18:86","id":86,"word":"turmoil","phonetic":"/ˈtɜːmɔɪl/","pos":"n.","meaningCN":"混乱，骚乱","tag":"高频","root":"","exampleEN":"The sudden resignation of the prime minister threw the country into political turmoil.","exampleCN":"总理的突然辞职使该国陷入了政治混乱。","extra":""},{"chapter":18,"key":"18:87","id":87,"word":"scenario","phonetic":"/sɪˈnɑːriəʊ/","pos":"n.","meaningCN":"可能发生的情况；剧情梗概","tag":"高频","root":"","exampleEN":"Let's imagine a worst-case scenario where the project fails completely.","exampleCN":"让我们设想一下项目彻底失败的最坏情况。","extra":""},{"chapter":18,"key":"18:88","id":88,"word":"occasion","phonetic":"/əˈkeɪʒn/","pos":"n.","meaningCN":"场合；时机，机会","tag":"核心","root":"","exampleEN":"I only wear this suit on special occasions like weddings and graduations.","exampleCN":"我只在像婚礼和毕业典礼这样的特殊场合穿这套西装。","extra":"occasionally adv. 偶尔；搭配：on occasion 有时"},{"chapter":18,"key":"18:89","id":89,"word":"dread","phonetic":"/dred/","pos":"v.","meaningCN":"极为害怕，非常担心 n. 恐惧","tag":"高频","root":"","exampleEN":"She dreads going to the dentist because of a bad experience she had as a child.","exampleCN":"她非常害怕看牙医，因为她小时候有过一次糟糕的经历。","extra":"dreadful adj. 可怕的"},{"chapter":18,"key":"18:90","id":90,"word":"frighten","phonetic":"/ˈfraɪtn/","pos":"v.","meaningCN":"使害怕，使惊恐","tag":"核心","root":"","exampleEN":"The loud thunder frightened the little girl and she hid under the blanket.","exampleCN":"巨大的雷声吓坏了小女孩，她躲到了毯子底下。","extra":"fright n. 惊骇；搭配：be frightened at 害怕"},{"chapter":18,"key":"18:91","id":91,"word":"limit","phonetic":"/ˈlɪmɪt/","pos":"n.","meaningCN":"限度；界限 v. 限制","tag":"核心","root":"","exampleEN":"We need to limit the amount of sugar we eat every day for better health.","exampleCN":"为了改善健康，我们需要限制每天的糖摄入量。","extra":"limited adj. 有限的；limitation n. 限制"},{"chapter":18,"key":"18:92","id":92,"word":"boundary","phonetic":"/ˈbaʊndri/","pos":"n.","meaningCN":"分界线，边界；界限","tag":"核心","root":"","exampleEN":"A narrow river forms the natural boundary between the two countries.","exampleCN":"一条狭窄的河流构成了两国之间的天然分界线。","extra":"搭配：within the boundary of 在......范围内"},{"chapter":18,"key":"18:93","id":93,"word":"compete","phonetic":"/kəmˈpiːt/","pos":"v.","meaningCN":"竞争；参加（比赛）","tag":"核心","root":"","exampleEN":"Athletes from over 40 nations will compete for medals at the championship.","exampleCN":"来自40多个国家的运动员将在锦标赛上争夺奖牌。","extra":"competition n. 竞争；competent adj. 有能力的"},{"chapter":18,"key":"18:94","id":94,"word":"contest","phonetic":"/ˈkɒntest/","pos":"v.","meaningCN":"争取赢得；争辩 / n. 竞争；比赛","tag":"高频","root":"","exampleEN":"Ten outstanding writers are now contesting the first prize in the short story competition.","exampleCN":"十位优秀作家正在角逐短篇小说比赛的一等奖。","extra":"contestant n. 参赛者"},{"chapter":18,"key":"18:95","id":95,"word":"contend","phonetic":"/kənˈtend/","pos":"v.","meaningCN":"竞争；争辩，主张","tag":"高频","root":"","exampleEN":"The lawyer contended that his client was innocent and should be released immediately.","exampleCN":"律师主张他的当事人是清白的，应立即获释。","extra":""},{"chapter":18,"key":"18:96","id":96,"word":"rival","phonetic":"/ˈraɪvl/","pos":"n.","meaningCN":"竞争者，对手 v. 与......匹敌","tag":"核心","root":"","exampleEN":"The two football teams have been fierce rivals for more than twenty years.","exampleCN":"两支足球队二十多年来一直是彼此的劲敌。","extra":"rivalry n. 竞争；搭配：defeat one's rival 击败某人的对手"},{"chapter":18,"key":"18:97","id":97,"word":"competitor","phonetic":"/kəmˈpetɪtə(r)/","pos":"n.","meaningCN":"竞争者，对手","tag":"核心","root":"","exampleEN":"In the smartphone market, the company's main competitor has just released a new product.","exampleCN":"在智能手机市场，该公司的主要竞争对手刚刚发布了一款新产品。","extra":"compete v. 竞争"},{"chapter":18,"key":"18:98","id":98,"word":"enemy","phonetic":"/ˈenəmi/","pos":"n.","meaningCN":"敌人，仇敌；敌兵，敌军","tag":"核心","root":"","exampleEN":"During the war, it was difficult to tell who was a friend and who was an enemy.","exampleCN":"战争期间，很难分辨谁是朋友，谁是敌人。","extra":""},{"chapter":18,"key":"18:99","id":99,"word":"strategy","phonetic":"/ˈstrætədʒi/","pos":"n.","meaningCN":"策略；战略","tag":"核心","root":"","exampleEN":"The company will need to develop a new marketing strategy to reach younger customers.","exampleCN":"该公司需要制定新的营销策略来吸引年轻客户。","extra":"strategic adj. 战略上的；strategist n. 战略家"},{"chapter":18,"key":"18:100","id":100,"word":"tactic","phonetic":"/ˈtæktɪk/","pos":"n.","meaningCN":"策略，战术","tag":"高频","root":"","exampleEN":"Lowering prices is a common sales tactic used by many large supermarkets.","exampleCN":"降价是许多大型超市常用的销售策略。","extra":"搭配：win by surprise tactics 出奇制胜"},{"chapter":18,"key":"18:101","id":101,"word":"manoeuvre","phonetic":"/məˈnuːvə(r)/","pos":"n.","meaningCN":"策略，巧计；军事演习","tag":"低频","root":"","exampleEN":"The army is conducting military manoeuvres on the plain this week.","exampleCN":"本周军队正在那片平原上进行军事演习。","extra":""},{"chapter":18,"key":"18:102","id":102,"word":"blueprint","phonetic":"/ˈbluːprɪnt/","pos":"n.","meaningCN":"蓝图；行动计划","tag":"高频","root":"","exampleEN":"The engineers carefully studied the blueprint before beginning construction.","exampleCN":"工程师们在开始施工前仔细研究了蓝图。","extra":""},{"chapter":18,"key":"18:103","id":103,"word":"refute","phonetic":"/rɪˈfjuːt/","pos":"v.","meaningCN":"反驳，驳斥；否认","tag":"高频","root":"","exampleEN":"The scientist was able to refute the old theory with new experimental data.","exampleCN":"这位科学家用新的实验数据驳斥了旧理论。","extra":"搭配：refute sb.'s argument 驳斥某人的论点"},{"chapter":18,"key":"18:104","id":104,"word":"warn","phonetic":"/wɔːn/","pos":"v.","meaningCN":"警告；告诫","tag":"核心","root":"","exampleEN":"The weather station has warned local residents about the coming typhoon.","exampleCN":"气象站已经警告当地居民即将有台风来袭。","extra":"warning n. 警告；搭配：warn sb. of the danger 警告某人有危险"},{"chapter":18,"key":"18:105","id":105,"word":"might","phonetic":"/maɪt/","pos":"n.","meaningCN":"力量，威力","tag":"高频","root":"","exampleEN":"The old castle was built to show the military might of the ancient empire.","exampleCN":"这座古堡是为了展示古老帝国的军事威力而建造的。","extra":""},{"chapter":18,"key":"18:106","id":106,"word":"force","phonetic":"/fɔːs/","pos":"n.","meaningCN":"力量；武力 v. 强迫，迫使","tag":"核心","root":"","exampleEN":"The new safety regulation will come into force at the beginning of next month.","exampleCN":"新的安全法规将于下月初开始生效。","extra":"搭配：come into force 开始生效"},{"chapter":18,"key":"18:107","id":107,"word":"reinforce","phonetic":"/ˌriːɪnˈfɔːs/","pos":"v.","meaningCN":"增援；增强，加强；加固","tag":"核心","root":"","exampleEN":"This new study reinforces the belief that regular exercise improves mental health.","exampleCN":"这项新研究进一步证实了经常锻炼能改善心理健康的观点。","extra":"搭配：reinforce supply 增加供应"},{"chapter":18,"key":"18:108","id":108,"word":"compel","phonetic":"/kəmˈpel/","pos":"v.","meaningCN":"强迫，迫使","tag":"高频","root":"","exampleEN":"The heavy rain compelled us to cancel the picnic and stay at home.","exampleCN":"大雨迫使我们取消了野餐，待在家里。","extra":""},{"chapter":18,"key":"18:109","id":109,"word":"impair","phonetic":"/ɪmˈpeə(r)/","pos":"v.","meaningCN":"削弱；妨碍","tag":"高频","root":"","exampleEN":"Lack of sleep can seriously impair a driver's ability to react quickly.","exampleCN":"缺乏睡眠会严重削弱司机快速反应的能力。","extra":""},{"chapter":18,"key":"18:110","id":110,"word":"oblige","phonetic":"/əˈblaɪdʒ/","pos":"v.","meaningCN":"迫使，强迫；帮忙","tag":"高频","root":"","exampleEN":"The law obliges companies to provide a safe working environment for employees.","exampleCN":"法律强制公司为员工提供安全的工作环境。","extra":"obligation n. 义务，责任"},{"chapter":18,"key":"18:111","id":111,"word":"mitigate","phonetic":"/ˈmɪtɪɡeɪt/","pos":"v.","meaningCN":"减轻，缓和","tag":"高频","root":"","exampleEN":"The government took steps to mitigate the impact of the drought on farmers.","exampleCN":"政府采取措施减轻干旱对农民的影响。","extra":"mitigation n. 缓和"},{"chapter":18,"key":"18:112","id":112,"word":"order","phonetic":"/ˈɔːdə(r)/","pos":"n.","meaningCN":"次序；整齐 v. 命令","tag":"核心","root":"","exampleEN":"The officer ordered the soldiers to stand in a straight line at attention.","exampleCN":"军官命令士兵们站成一条直线立正。","extra":"disorder n. 混乱；orderly adj. 整洁的"},{"chapter":18,"key":"18:113","id":113,"word":"protest","phonetic":"/ˈprəʊtest/","pos":"n.","meaningCN":"抗议；申明 v. 抗议；申辩","tag":"核心","root":"","exampleEN":"Hundreds of students gathered in the square to protest against the tuition increase.","exampleCN":"数百名学生聚集在广场上抗议学费上涨。","extra":"搭配：protest against 抗议，反对"},{"chapter":18,"key":"18:114","id":114,"word":"comfort","phonetic":"/ˈkʌmfət/","pos":"n.","meaningCN":"安慰；舒适 v. 安慰，抚慰","tag":"核心","root":"","exampleEN":"After the sad news, she sought comfort by talking with her closest friend.","exampleCN":"听到那个悲伤的消息后，她通过与最好的朋友交谈来寻求安慰。","extra":"comfortable adj. 舒适的；搭配：seek comfort 寻求安慰"},{"chapter":18,"key":"18:115","id":115,"word":"event","phonetic":"/ɪˈvent/","pos":"n.","meaningCN":"事件，大事；公开活动","tag":"核心","root":"","exampleEN":"The charity event at the park raised thousands of dollars for children in need.","exampleCN":"公园里举办的慈善活动为有需要的儿童筹集了数千美元。","extra":"搭配：celebrate an event 庆祝某一个事件"},{"chapter":18,"key":"18:116","id":116,"word":"casualty","phonetic":"/ˈkæʒuəlti/","pos":"n.","meaningCN":"伤亡人员","tag":"高频","root":"","exampleEN":"The hospital received dozens of casualties after the terrible train crash.","exampleCN":"在发生可怕的火车相撞事故后，医院接收了数十名伤病员。","extra":""},{"chapter":18,"key":"18:117","id":117,"word":"bury","phonetic":"/ˈberi/","pos":"v.","meaningCN":"埋葬","tag":"高频","root":"","exampleEN":"She buried herself in her work to forget the pain of losing her brother.","exampleCN":"她埋头工作以忘记失去兄弟的痛苦。","extra":"搭配：bury oneself in 专心致志于"},{"chapter":18,"key":"18:118","id":118,"word":"funeral","phonetic":"/ˈfjuːnərəl/","pos":"n.","meaningCN":"葬礼","tag":"核心","root":"","exampleEN":"Many friends and relatives attended the funeral to pay their last respects.","exampleCN":"许多亲友参加了葬礼，致以最后的敬意。","extra":""},{"chapter":18,"key":"18:119","id":119,"word":"grave","phonetic":"/ɡreɪv/","pos":"n.","meaningCN":"坟墓","tag":"核心","root":"","exampleEN":"Every year, people place flowers on the grave of the unknown soldier.","exampleCN":"每年，人们都会在无名战士的墓前献上鲜花。","extra":""},{"chapter":18,"key":"18:120","id":120,"word":"tomb","phonetic":"/tuːm/","pos":"n.","meaningCN":"坟墓","tag":"高频","root":"","exampleEN":"Archaeologists discovered many ancient treasures inside the pharaoh's tomb.","exampleCN":"考古学家在法老墓里发现了许多古代珍宝。","extra":""},{"chapter":18,"key":"18:121","id":121,"word":"hell","phonetic":"/hel/","pos":"n.","meaningCN":"地狱","tag":"核心","root":"","exampleEN":"Survivors described the earthquake zone as a living hell with no water or electricity.","exampleCN":"幸存者把地震区描述为一个既没有水也没有电的人间地狱。","extra":"搭配：go to hell 下地狱"},{"chapter":18,"key":"18:122","id":122,"word":"maritime","phonetic":"/ˈmærɪtaɪm/","pos":"adj.","meaningCN":"海事的，海的","tag":"低频","root":"","exampleEN":"The country has a long maritime history and one of the biggest ports in the world.","exampleCN":"这个国家有着悠久的海洋历史和一个世界最大的港口。","extra":"搭配：maritime court 海事法庭"},{"chapter":18,"key":"18:123","id":123,"word":"naval","phonetic":"/ˈneɪvl/","pos":"adj.","meaningCN":"海军的","tag":"核心","root":"","exampleEN":"He joined the naval forces when he was eighteen and spent ten years at sea.","exampleCN":"他十八岁加入海军，在海上度过了十年。","extra":"navy n. 海军"},{"chapter":18,"key":"18:124","id":124,"word":"fleet","phonetic":"/fliːt/","pos":"n.","meaningCN":"舰队","tag":"高频","root":"","exampleEN":"The company owns a fleet of delivery trucks that operate across the entire region.","exampleCN":"该公司拥有一支覆盖整个地区的送货车队。","extra":""},{"chapter":18,"key":"18:125","id":125,"word":"troop","phonetic":"/truːp/","pos":"n.","meaningCN":"部队","tag":"核心","root":"","exampleEN":"The troops marched through the city centre during the National Day parade.","exampleCN":"国庆阅兵时，部队列队穿过市中心。","extra":""},{"chapter":18,"key":"18:126","id":126,"word":"landing","phonetic":"/ˈlændɪŋ/","pos":"n.","meaningCN":"着陆","tag":"高频","root":"","exampleEN":"The pilot made a smooth landing despite the strong wind and heavy rain.","exampleCN":"尽管风雨很大，驾驶员还是进行了一次平稳的着陆。","extra":"搭配：a landing field 降落场"},{"chapter":18,"key":"18:127","id":127,"word":"hover","phonetic":"/ˈhɒvə(r)/","pos":"v.","meaningCN":"悬停","tag":"高频","root":"","exampleEN":"The seagull hovered in the air for a moment before diving to catch a fish.","exampleCN":"那只海鸥在空中悬停了一会儿，然后俯冲去捕鱼。","extra":""},{"chapter":18,"key":"18:128","id":128,"word":"proceed","phonetic":"/prəˈsiːd/","pos":"v.","meaningCN":"继续进行","tag":"核心","root":"","exampleEN":"After a short break, the meeting proceeded as planned and lasted another hour.","exampleCN":"短暂休息后，会议按计划继续进行，又持续了一个小时。","extra":"搭配：proceed with 继续进行"},{"chapter":18,"key":"18:129","id":129,"word":"progress","phonetic":"/ˈprəʊɡres/","pos":"n./v.","meaningCN":"前进；进步","tag":"核心","root":"","exampleEN":"The construction of the new bridge is finally making good progress after some delays.","exampleCN":"经过一些延误后，新桥的建设终于进展顺利。","extra":"progressive adj. 进步的；搭配：make progress 取得进步"},{"chapter":18,"key":"18:130","id":130,"word":"military","phonetic":"/ˈmɪlətri/","pos":"adj.","meaningCN":"军事的，军用的","tag":"核心","root":"","exampleEN":"All young men in the country must complete one year of military service.","exampleCN":"该国所有年轻男子都必须完成一年的兵役。","extra":"搭配：military service 兵役"},{"chapter":18,"key":"18:131","id":131,"word":"nuclear","phonetic":"/ˈnjuːkliə(r)/","pos":"adj.","meaningCN":"原子核的；核能的；核武器的","tag":"核心","root":"","exampleEN":"Many people prefer to live in a nuclear family rather than a large extended one.","exampleCN":"许多人更喜欢生活在核心家庭里，而不是一个大家庭。","extra":"搭配：a nuclear family 核心家庭；nuclear energy 核能"},{"chapter":18,"key":"18:132","id":132,"word":"poison","phonetic":"/ˈpɔɪzn/","pos":"n.","meaningCN":"毒物，毒药 v. 毒害","tag":"核心","root":"","exampleEN":"The leaves of this plant contain a strong poison that can be deadly if swallowed.","exampleCN":"这种植物的叶子含有剧毒，吞食可能致命。","extra":"poisonous adj. 有毒的"},{"chapter":18,"key":"18:133","id":133,"word":"devastate","phonetic":"/ˈdevəsteɪt/","pos":"v.","meaningCN":"毁坏，摧毁","tag":"高频","root":"","exampleEN":"The whole village was devastated by the flood, and rebuilding will take years.","exampleCN":"整个村庄都被洪水摧毁了，重建将需要好几年。","extra":"devastation n. 破坏；devastating adj. 毁灭性的"},{"chapter":18,"key":"18:134","id":134,"word":"risk","phonetic":"/rɪsk/","pos":"n.","meaningCN":"危险，风险 v. 冒着......的危险","tag":"核心","root":"","exampleEN":"If you invest all your money in one company, you run the risk of losing everything.","exampleCN":"如果你把所有的钱都投到一家公司，你就有失去一切的风险。","extra":"搭配：at risk 有危险"},{"chapter":18,"key":"18:135","id":135,"word":"adventure","phonetic":"/ədˈventʃə(r)/","pos":"n.","meaningCN":"冒险，冒险经历","tag":"核心","root":"","exampleEN":"Their journey through the Amazon rainforest was the greatest adventure of their lives.","exampleCN":"他们穿越亚马逊雨林的旅程是他们一生中最伟大的冒险。","extra":""},{"chapter":18,"key":"18:136","id":136,"word":"peril","phonetic":"/ˈperəl/","pos":"n.","meaningCN":"重大危险；险情","tag":"低频","root":"","exampleEN":"The explorers faced great perils, from freezing temperatures to attacks by wild animals.","exampleCN":"探险者们面临了巨大的危险，从冰点以下的气温到野兽的袭击。","extra":"搭配：at one's (own) peril 自担风险"},{"chapter":18,"key":"18:137","id":137,"word":"catastrophe","phonetic":"/kəˈtæstrəfi/","pos":"n.","meaningCN":"重大灾难，大祸","tag":"高频","root":"","exampleEN":"The oil spill was an environmental catastrophe that killed thousands of seabirds.","exampleCN":"那场石油泄漏是一次环境灾难，导致数以千计的海鸟死亡。","extra":""},{"chapter":18,"key":"18:138","id":138,"word":"collapse","phonetic":"/kəˈlæps/","pos":"n./v.","meaningCN":"倒塌；崩溃","tag":"核心","root":"","exampleEN":"The roof collapsed under the weight of the heavy snow, trapping several people inside.","exampleCN":"屋顶在大雪的重压下坍塌了，有好几个人被困在里面。","extra":""},{"chapter":18,"key":"18:139","id":139,"word":"torture","phonetic":"/ˈtɔːtʃə(r)/","pos":"n.","meaningCN":"拷问；痛苦，折磨 v. 拷问；使痛苦","tag":"核心","root":"","exampleEN":"She was in complete torture with a severe toothache and could not sleep at all.","exampleCN":"她因严重的牙痛而饱受折磨，完全睡不着。","extra":"搭配：severe torture 严刑拷打"},{"chapter":18,"key":"18:140","id":140,"word":"humiliate","phonetic":"/hjuːˈmɪlieɪt/","pos":"v.","meaningCN":"羞辱，使蒙羞","tag":"高频","root":"","exampleEN":"He felt humiliated when the boss criticised him sharply in front of his colleagues.","exampleCN":"当老板在同事面前严厉批评他时，他感到非常羞辱。","extra":""},{"chapter":18,"key":"18:141","id":141,"word":"damage","phonetic":"/ˈdæmɪdʒ/","pos":"n./v.","meaningCN":"损害；伤害","tag":"核心","root":"","exampleEN":"The storm caused serious damage to the crops and many trees were blown down.","exampleCN":"暴风雨给庄稼造成了严重损害，许多树被吹倒了。","extra":"搭配：do damage to 损害"},{"chapter":18,"key":"18:142","id":142,"word":"harmful","phonetic":"/ˈhɑːmfl/","pos":"adj.","meaningCN":"有害的","tag":"核心","root":"","exampleEN":"Too much direct sunlight can be harmful to your skin, especially at midday.","exampleCN":"过多的阳光直射对你的皮肤有害，尤其是在正午时分。","extra":"harm n. 害处"},{"chapter":18,"key":"18:143","id":143,"word":"mislead","phonetic":"/ˌmɪsˈliːd/","pos":"v.","meaningCN":"误导，欺骗，使误入歧途","tag":"核心","root":"","exampleEN":"The advertisement was found to mislead consumers about the health benefits of the drink.","exampleCN":"这则广告被发现就这款饮料的健康益处误导了消费者。","extra":"搭配：mislead sb. into doing sth. 误导某人做某事"},{"chapter":18,"key":"18:144","id":144,"word":"disturb","phonetic":"/dɪˈstɜːb/","pos":"v.","meaningCN":"打扰；使焦虑；弄乱","tag":"核心","root":"","exampleEN":"Please do not disturb the baby; she has just fallen asleep after a long cry.","exampleCN":"请别打扰宝宝，她大哭一场后刚刚睡着了。","extra":"disturbance n. 干扰；骚乱"},{"chapter":18,"key":"18:145","id":145,"word":"interfere","phonetic":"/ˌɪntəˈfɪə(r)/","pos":"v.","meaningCN":"干涉；妨碍","tag":"核心","root":"","exampleEN":"No country has the right to interfere in the internal affairs of another country.","exampleCN":"任何国家都无权干涉他国内政。","extra":"interference n. 干涉；搭配：interfere in 干涉；interfere with 干扰"},{"chapter":18,"key":"18:146","id":146,"word":"interrupt","phonetic":"/ˌɪntəˈrʌpt/","pos":"v.","meaningCN":"打断；中断","tag":"核心","root":"","exampleEN":"I'm sorry to interrupt your conversation, but we need to leave immediately.","exampleCN":"很抱歉打断你们的谈话，但我们需要马上离开。","extra":"interruption n. 中断"},{"chapter":18,"key":"18:147","id":147,"word":"retreat","phonetic":"/rɪˈtriːt/","pos":"n./v.","meaningCN":"撤退；退避","tag":"核心","root":"","exampleEN":"When the enemy forces advanced, the general ordered his troops to retreat safely.","exampleCN":"当敌军推进时，将军命令部队安全撤退。","extra":""},{"chapter":18,"key":"18:148","id":148,"word":"shrink","phonetic":"/ʃrɪŋk/","pos":"v.","meaningCN":"退缩；收缩，缩水；（使）减少","tag":"核心","root":"","exampleEN":"This wool sweater will shrink if you wash it in hot water.","exampleCN":"这件羊毛衫若用热水洗会缩水。","extra":"搭配：shrink back 退缩，畏缩"},{"chapter":18,"key":"18:149","id":149,"word":"withdraw","phonetic":"/wɪðˈdrɔː/","pos":"v.","meaningCN":"收回；（使）撤退；提（款）","tag":"核心","root":"","exampleEN":"She went to the bank to withdraw some cash before her trip.","exampleCN":"她在旅行前去银行取了一些现金。","extra":""},{"chapter":18,"key":"18:150","id":150,"word":"withstand","phonetic":"/wɪðˈstænd/","pos":"v.","meaningCN":"承受，顶住，经受住","tag":"核心","root":"","exampleEN":"The bridge is designed to withstand strong winds and powerful earthquakes.","exampleCN":"这座桥的设计能承受强风和强烈地震。","extra":"搭配：withstand severe tests 经得住严峻的考验"},{"chapter":18,"key":"18:151","id":151,"word":"compromise","phonetic":"/ˈkɒmprəmaɪz/","pos":"v.","meaningCN":"妥协","tag":"核心","root":"","exampleEN":"In any healthy relationship, both partners need to learn to compromise sometimes.","exampleCN":"在任何健康的关系中，双方有时都需要学会妥协。","extra":"搭配：compromise with sb. on sth. 在某方面与某人妥协"},{"chapter":18,"key":"18:152","id":152,"word":"surrender","phonetic":"/səˈrendə(r)/","pos":"n./v.","meaningCN":"投降；（被迫）放弃","tag":"核心","root":"","exampleEN":"After three days without food and water, the trapped soldiers decided to surrender.","exampleCN":"在三天没有食物和水之后，被困的士兵们决定投降。","extra":"搭配：surrender oneself to 向......投降"},{"chapter":18,"key":"18:153","id":153,"word":"escape","phonetic":"/ɪˈskeɪp/","pos":"n./v.","meaningCN":"逃跑；逃脱；逃避","tag":"核心","root":"","exampleEN":"The deer somehow managed to escape from the cage and ran back into the forest.","exampleCN":"那头鹿不知怎的设法从笼子里逃了出来，跑回了森林。","extra":"搭配：escape danger 避免危险"},{"chapter":18,"key":"18:154","id":154,"word":"avoid","phonetic":"/əˈvɔɪd/","pos":"v.","meaningCN":"避免；躲开","tag":"核心","root":"","exampleEN":"To avoid catching a cold, wash your hands often and dress warmly in winter.","exampleCN":"为了避免感冒，冬天要勤洗手并穿得暖和。","extra":"搭配：avoid punishment 逃避惩罚"},{"chapter":18,"key":"18:155","id":155,"word":"quit","phonetic":"/kwɪt/","pos":"v.","meaningCN":"放弃，停止；辞去；离开","tag":"核心","root":"","exampleEN":"He decided to quit his job and go back to university to study law.","exampleCN":"他决定辞掉工作，回到大学去学习法律。","extra":"搭配：quit office 离职"},{"chapter":18,"key":"18:156","id":156,"word":"abandon","phonetic":"/əˈbændən/","pos":"v.","meaningCN":"放弃；抛弃，丢弃","tag":"核心","root":"","exampleEN":"They had to abandon their car on the highway when it ran out of petrol.","exampleCN":"当车子的汽油用光时，他们不得不把车弃置在高速公路上。","extra":"搭配：abandon oneself to 沉湎于"},{"chapter":18,"key":"18:157","id":157,"word":"forgo","phonetic":"/fɔːˈɡəʊ/","pos":"v.","meaningCN":"放弃","tag":"低频","root":"","exampleEN":"He decided to forgo a holiday this year so he could save enough money for a new car.","exampleCN":"他决定今年放弃度假，以便攒够钱买一辆新车。","extra":""},{"chapter":18,"key":"18:158","id":158,"word":"discard","phonetic":"/dɪsˈkɑːd/","pos":"v.","meaningCN":"丢弃，抛弃","tag":"高频","root":"","exampleEN":"Before starting the experiment, make sure to discard all old and expired materials.","exampleCN":"实验开始前，务必丢弃所有旧的和过期的材料。","extra":""},{"chapter":18,"key":"18:159","id":159,"word":"rid","phonetic":"/rɪd/","pos":"adj.","meaningCN":"摆脱，丢弃","tag":"高频","root":"","exampleEN":"Regular cleaning will help you get rid of dust and keep the room fresh.","exampleCN":"定期清洁将有助于你摆脱灰尘，保持房间清新。","extra":""},{"chapter":18,"key":"18:160","id":160,"word":"defend","phonetic":"/dɪˈfend/","pos":"v.","meaningCN":"防御，保护；为......辩护","tag":"核心","root":"","exampleEN":"The soldiers fought bravely to defend their homeland from the invading army.","exampleCN":"士兵们英勇作战，保卫祖国免受侵略军的侵犯。","extra":"defence/defense n. 防御；defendant n. 被告；搭配：defend against 防御"},{"chapter":18,"key":"18:161","id":161,"word":"safeguard","phonetic":"/ˈseɪfɡɑːd/","pos":"v.","meaningCN":"保护，保卫 n. 保护措施","tag":"高频","root":"","exampleEN":"New technologies are being developed to safeguard personal data from hackers.","exampleCN":"正在开发新技术，以保护个人数据免受黑客攻击。","extra":"搭配：safeguard sb.'s interests 保护某人的利益"},{"chapter":18,"key":"18:162","id":162,"word":"defeat","phonetic":"/dɪˈfiːt/","pos":"v.","meaningCN":"战胜，击败 n. 失败","tag":"核心","root":"","exampleEN":"Although they played well, the basketball team was finally defeated by a narrow margin.","exampleCN":"尽管表现不错，但篮球队最终还是以微弱比分落败。","extra":""},{"chapter":18,"key":"18:163","id":163,"word":"resist","phonetic":"/rɪˈzɪst/","pos":"v.","meaningCN":"抵制，反对；抵御；忍住","tag":"核心","root":"","exampleEN":"It was difficult to resist the temptation to eat the entire box of chocolates.","exampleCN":"很难忍住一下子吃掉整盒巧克力的诱惑。","extra":"resistance n. 反对；resistant adj. 反对的"},{"chapter":18,"key":"18:164","id":164,"word":"capture","phonetic":"/ˈkæptʃə(r)/","pos":"n.","meaningCN":"战利品 v. 捕获；夺得","tag":"核心","root":"","exampleEN":"The police finally managed to capture the escaped prisoner after a three-day search.","exampleCN":"经过三天的追捕，警方终于捕获了那名逃犯。","extra":"搭配：capture sb.'s heart 捕获某人的芳心"},{"chapter":18,"key":"18:165","id":165,"word":"victory","phonetic":"/ˈvɪktəri/","pos":"n.","meaningCN":"胜利，成功","tag":"核心","root":"","exampleEN":"After months of hard training, the team celebrated their amazing victory.","exampleCN":"经过数月的艰苦训练，这支队伍庆祝了他们非凡的胜利。","extra":"victorious adj. 胜利的"},{"chapter":18,"key":"18:166","id":166,"word":"triumph","phonetic":"/ˈtraɪʌmf/","pos":"n.","meaningCN":"伟大胜利，非凡的成功 v. 获得胜利","tag":"高频","root":"","exampleEN":"The agreement was a major triumph for international diplomacy and peace efforts.","exampleCN":"这项协议是国际外交与和平努力的一次重大胜利。","extra":"搭配：achieve great triumphs 取得巨大的成就"},{"chapter":18,"key":"18:167","id":167,"word":"conquer","phonetic":"/ˈkɒŋkə(r)/","pos":"v.","meaningCN":"征服；克服，战胜","tag":"核心","root":"","exampleEN":"With years of practice, she finally managed to conquer her fear of public speaking.","exampleCN":"经过多年的练习，她终于克服了对公开演讲的恐惧。","extra":"conquest n. 占领；搭配：conquer shyness 克服羞怯心理"},{"chapter":18,"key":"18:168","id":168,"word":"monument","phonetic":"/ˈmɒnjumənt/","pos":"n.","meaningCN":"纪念碑；历史遗迹；典范","tag":"核心","root":"","exampleEN":"A monument was built in the square to honour those who lost their lives in the war.","exampleCN":"广场上矗立着一座纪念碑，以纪念在战争中丧生的人们。","extra":"搭配：the Monument to the People's Heroes 人民英雄纪念碑"},{"chapter":18,"key":"18:169","id":169,"word":"tablet","phonetic":"/ˈtæblət/","pos":"n.","meaningCN":"碑，匾；药片","tag":"高频","root":"","exampleEN":"The doctor told him to take one tablet twice a day after meals for a week.","exampleCN":"医生告诉他一天两次，每次一片，饭后服用，持续一周。","extra":"搭配：a memorial tablet 纪念碑（或匾）"},{"chapter":18,"key":"18:170","id":170,"word":"statue","phonetic":"/ˈstætʃuː/","pos":"n.","meaningCN":"雕像，塑像","tag":"核心","root":"","exampleEN":"The Statue of Liberty was a gift from France to the United States in the 19th century.","exampleCN":"自由女神像是法国在19世纪送给美国的礼物。","extra":""},{"chapter":18,"key":"18:171","id":171,"word":"medal","phonetic":"/ˈmedl/","pos":"n.","meaningCN":"勋章，奖章","tag":"核心","root":"","exampleEN":"She was awarded a gold medal for her outstanding performance in the swimming competition.","exampleCN":"她因在游泳比赛中的出色表现被授予了一枚金牌。","extra":"搭配：award sb. a medal 授予某人奖章"},{"chapter":18,"key":"18:172","id":172,"word":"honour","phonetic":"/ˈɒnə(r)/","pos":"n.","meaningCN":"尊敬，敬意；荣誉 v. 尊敬","tag":"核心","root":"","exampleEN":"It is a great honour to be invited to speak at this important international conference.","exampleCN":"受邀在这次重要的国际会议上发言是一个极大的荣誉。","extra":"honourable adj. 可敬的"},{"chapter":18,"key":"18:173","id":173,"word":"glorious","phonetic":"/ˈɡlɔːriəs/","pos":"adj.","meaningCN":"光荣的，荣耀的","tag":"核心","root":"","exampleEN":"The soldiers were welcomed home with a glorious celebration after their safe return.","exampleCN":"士兵们平安归来后，受到了光荣和隆重的欢迎。","extra":"glory n. 光荣"},{"chapter":18,"key":"18:174","id":174,"word":"contribute","phonetic":"/kənˈtrɪbjuːt/","pos":"v.","meaningCN":"捐献；（为......）作贡献；撰稿","tag":"核心","root":"","exampleEN":"Everyone should contribute what they can to help protect the natural environment.","exampleCN":"每个人都应尽自己的一份力，为保护自然环境作出贡献。","extra":"contribution n. 贡献；搭配：contribute to 为......作贡献"},{"chapter":18,"key":"18:175","id":175,"word":"devote","phonetic":"/dɪˈvəʊt/","pos":"v.","meaningCN":"献身；投入","tag":"核心","root":"","exampleEN":"She devoted herself completely to the care of sick and injured animals.","exampleCN":"她全身心地投入到照顾生病和受伤的动物的工作中。","extra":"devotion n. 献身；搭配：devote sth. to 把时间、精力等用于"},{"chapter":18,"key":"18:176","id":176,"word":"owe","phonetic":"/əʊ/","pos":"v.","meaningCN":"欠；应把......归功于；欠（情），感激","tag":"核心","root":"","exampleEN":"I owe my success largely to the support and encouragement of my family.","exampleCN":"我的成功很大程度上要归功于家人的支持和鼓励。","extra":""},{"chapter":18,"key":"18:177","id":177,"word":"patrol","phonetic":"/pəˈtrəʊl/","pos":"n./v.","meaningCN":"巡逻，巡查","tag":"核心","root":"","exampleEN":"Security guards patrol inside the museum every hour during the night.","exampleCN":"夜间保安每小时在博物馆内巡逻一次。","extra":"搭配：on patrol 在巡逻的"},{"chapter":18,"key":"18:178","id":178,"word":"guard","phonetic":"/ɡɑːd/","pos":"n.","meaningCN":"卫兵，警卫员 v. 看守；守卫","tag":"核心","root":"","exampleEN":"Two armed guards stood at the palace gate and checked every visitor carefully.","exampleCN":"两名武装警卫站在宫殿门口，仔细检查每一位来访者。","extra":"guardian n. 保卫者；监护人"},{"chapter":18,"key":"18:179","id":179,"word":"camouflage","phonetic":"/ˈkæməflɑːʒ/","pos":"v./n.","meaningCN":"伪装","tag":"高频","root":"","exampleEN":"The soldiers used branches and leaves to camouflage their vehicle in the forest.","exampleCN":"士兵们用树枝和树叶伪装森林里的车辆。","extra":"搭配：protection camouflage 防护伪装"},{"chapter":18,"key":"18:180","id":180,"word":"obstacle","phonetic":"/ˈɒbstəkl/","pos":"n.","meaningCN":"障碍；障碍物","tag":"核心","root":"","exampleEN":"Lack of confidence is often the biggest obstacle to achieving your dreams.","exampleCN":"缺乏信心往往是实现梦想的最大障碍。","extra":"搭配：clear away obstacles 排除障碍"},{"chapter":18,"key":"18:181","id":181,"word":"burrow","phonetic":"/ˈbʌrəʊ/","pos":"n.","meaningCN":"地洞，地道 v. 掘地洞","tag":"低频","root":"","exampleEN":"The rabbit quickly disappeared into a burrow it had dug in the soft ground.","exampleCN":"那只兔子迅速地消失在它松软土地里挖的一个地洞里。","extra":""},{"chapter":18,"key":"18:182","id":182,"word":"spy","phonetic":"/spaɪ/","pos":"n.","meaningCN":"同谋，特务 v. 搜集情报，从事间谍活动","tag":"核心","root":"","exampleEN":"They caught a foreign spy who had been stealing military secrets for months.","exampleCN":"他们抓获了一名数月来一直在窃取军事机密的外国间谍。","extra":"搭配：spy on 窥探，暗中监视"},{"chapter":18,"key":"18:183","id":183,"word":"general","phonetic":"/ˈdʒenrəl/","pos":"n.","meaningCN":"将军 adj. 总的；一般性的","tag":"核心","root":"","exampleEN":"In general, people tend to feel happier when they spend time outdoors in nature.","exampleCN":"一般来说，人们在户外与大自然相处时往往感觉更快乐。","extra":"generally adv. 一般地；搭配：in general 大体上"},{"chapter":18,"key":"18:184","id":184,"word":"soldier","phonetic":"/ˈsəʊldʒə(r)/","pos":"n.","meaningCN":"战士，士兵","tag":"核心","root":"","exampleEN":"The young soldier was awarded a medal for his bravery in the battle.","exampleCN":"那名年轻士兵因在战斗中的英勇表现被授予了一枚奖章。","extra":"搭配：command soldiers 指挥士兵"},{"chapter":18,"key":"18:185","id":185,"word":"veteran","phonetic":"/ˈvetərən/","pos":"n.","meaningCN":"老兵；老手","tag":"高频","root":"","exampleEN":"The veteran teacher was respected by everyone for her 30 years of experience.","exampleCN":"那位资深教师因三十年的教学经验而受到所有人的尊敬。","extra":""},{"chapter":18,"key":"18:186","id":186,"word":"scout","phonetic":"/skaʊt/","pos":"n.","meaningCN":"侦察员，侦察机 v. 侦察，搜寻","tag":"高频","root":"","exampleEN":"Their mission was to scout the area ahead and report any sign of the enemy.","exampleCN":"他们的任务是侦察前方区域，报告敌人的任何行踪。","extra":"搭配：scout about for 到处寻找"}],"19":[{"chapter":19,"key":"19:1","id":1,"word":"pioneer","phonetic":"","pos":"n.","meaningCN":"先驱，开创者","tag":"核心","root":"","exampleEN":"She is considered a pioneer in the field of modern nursing.","exampleCN":"她被认为是现代护理领域的先驱。","extra":"搭配：a pioneer of ......的先驱"},{"chapter":19,"key":"19:2","id":2,"word":"prophet","phonetic":"","pos":"n.","meaningCN":"先知；预言家","tag":"高频","root":"","exampleEN":"The prophet predicted that there would be seven years of terrible drought.","exampleCN":"那位先知预言将会有七年的大旱。","extra":""},{"chapter":19,"key":"19:3","id":3,"word":"herald","phonetic":"","pos":"n.","meaningCN":"使者，传令官；先驱，预兆 / v. 预告；宣布","tag":"低频","root":"","exampleEN":"The first swallow is often seen as a herald of spring.","exampleCN":"第一只燕子常被看作春天的使者。","extra":"报纸名称：The New York Herald, The Sydney Morning Herald"},{"chapter":19,"key":"19:4","id":4,"word":"heir","phonetic":"","pos":"n.","meaningCN":"后嗣；继承人","tag":"高频","root":"","exampleEN":"He is the only heir to the family's vast fortune.","exampleCN":"他是家族庞大财产的唯一继承人。","extra":"heritage, inherit, inheritance"},{"chapter":19,"key":"19:5","id":5,"word":"successor","phonetic":"","pos":"n.","meaningCN":"接替者，继任者","tag":"高频","root":"","exampleEN":"The board is still looking for a suitable successor to the managing director.","exampleCN":"董事会仍在物色一位合适的总经理继任者。","extra":"successive"},{"chapter":19,"key":"19:6","id":6,"word":"generation","phonetic":"","pos":"n.","meaningCN":"一代；一代人","tag":"核心","root":"gen = 生","exampleEN":"This tradition has been passed down from generation to generation.","exampleCN":"这个传统是一代一代传下来的。","extra":"genius, gene, regenerate"},{"chapter":19,"key":"19:7","id":7,"word":"surname","phonetic":"","pos":"n.","meaningCN":"姓 / v. 给......起别名","tag":"核心","root":"","exampleEN":"Write your surname in capital letters in the first box.","exampleCN":"将你的姓用大写字母写在第一个方框内。","extra":"family name, last name, given name"},{"chapter":19,"key":"19:8","id":8,"word":"gender","phonetic":"","pos":"n.","meaningCN":"性别","tag":"核心","root":"","exampleEN":"The application form asks for your name, date of birth and gender.","exampleCN":"申请表要求填写姓名、出生日期和性别。","extra":""},{"chapter":19,"key":"19:9","id":9,"word":"sex","phonetic":"","pos":"n.","meaningCN":"性别；性行为","tag":"核心","root":"","exampleEN":"The school is open to all students regardless of sex, race or religion.","exampleCN":"这所学校对所有学生开放，不论性别、种族或宗教信仰。","extra":"sexy, sexual"},{"chapter":19,"key":"19:10","id":10,"word":"female","phonetic":"","pos":"adj.","meaningCN":"女子的；雌性的","tag":"核心","root":"","exampleEN":"We have three dogs, two females and one male.","exampleCN":"我们有三只狗，两只母的，一只公的。","extra":""},{"chapter":19,"key":"19:11","id":11,"word":"male","phonetic":"","pos":"adj.","meaningCN":"男子的；雄性的","tag":"核心","root":"","exampleEN":"A male voice called out her name from the back of the crowd.","exampleCN":"一个男子的声音从人群后面喊了她的名字。","extra":""},{"chapter":19,"key":"19:12","id":12,"word":"couple","phonetic":"","pos":"n.","meaningCN":"夫妻，情侣；两个，几个","tag":"核心","root":"","exampleEN":"I saw a young couple walking hand in hand along the beach.","exampleCN":"我看到一对年轻情侣手牵手走在沙滩上。","extra":"搭配：a couple of 几个；go in couples 结伴而行"},{"chapter":19,"key":"19:13","id":13,"word":"spouse","phonetic":"","pos":"n.","meaningCN":"配偶","tag":"高频","root":"","exampleEN":"This invitation allows you to bring your spouse or a close friend.","exampleCN":"凭此请柬你可以携带配偶或一位密友。","extra":"词源：spendo → sponsalia → spouse"},{"chapter":19,"key":"19:14","id":14,"word":"husband","phonetic":"","pos":"n.","meaningCN":"丈夫","tag":"核心","root":"","exampleEN":"She and her husband have been running a small café for twenty years.","exampleCN":"她和丈夫经营一家小咖啡馆已经有二十年了。","extra":""},{"chapter":19,"key":"19:15","id":15,"word":"wife","phonetic":"","pos":"n.","meaningCN":"妻子","tag":"核心","root":"","exampleEN":"He bought a beautiful ring for his wife on their wedding anniversary.","exampleCN":"结婚纪念日他给妻子买了一枚漂亮的戒指。","extra":""},{"chapter":19,"key":"19:16","id":16,"word":"gay","phonetic":"","pos":"adj.","meaningCN":"同性恋者（尤指男性）；快乐的；艳丽的","tag":"核心","root":"","exampleEN":"The children felt gay and excited when they saw the colourful balloons.","exampleCN":"孩子们看到五颜六色的气球时感到又快乐又兴奋。","extra":""},{"chapter":19,"key":"19:17","id":17,"word":"lesbian","phonetic":"","pos":"n.","meaningCN":"同性恋者（女性）","tag":"高频","root":"","exampleEN":"The film tells a moving love story between two young lesbian women.","exampleCN":"这部电影讲述了两个年轻女同性恋者之间感人的爱情故事。","extra":""},{"chapter":19,"key":"19:18","id":18,"word":"niece","phonetic":"","pos":"n.","meaningCN":"侄女；外甥女","tag":"核心","root":"","exampleEN":"My niece is coming to stay with us during the school holidays.","exampleCN":"我的侄女要在学校假期期间来和我们住。","extra":""},{"chapter":19,"key":"19:19","id":19,"word":"nephew","phonetic":"","pos":"n.","meaningCN":"侄子；外甥","tag":"核心","root":"","exampleEN":"He bought a toy train as a birthday gift for his little nephew.","exampleCN":"他买了一个玩具火车作为送给小侄子的生日礼物。","extra":""},{"chapter":19,"key":"19:20","id":20,"word":"twin","phonetic":"","pos":"n.","meaningCN":"双胞胎之一","tag":"核心","root":"twi- = 二","exampleEN":"It is difficult to tell the twin sisters apart because they look exactly the same.","exampleCN":"很难把这对双胞胎姐妹区分开，因为她们长得一模一样。","extra":"twice, twist, twig"},{"chapter":19,"key":"19:21","id":21,"word":"grandfather","phonetic":"","pos":"n.","meaningCN":"祖父；外祖父","tag":"核心","root":"","exampleEN":"My grandfather fought in the navy during the Second World War.","exampleCN":"我的祖父在第二次世界大战期间在海军服役。","extra":""},{"chapter":19,"key":"19:22","id":22,"word":"grandmother","phonetic":"","pos":"n.","meaningCN":"祖母；外祖母","tag":"核心","root":"","exampleEN":"Every Sunday, we visit our grandmother and she cooks us a wonderful meal.","exampleCN":"每个星期天我们都去看望祖母，她会给我们做一顿丰盛的饭菜。","extra":""},{"chapter":19,"key":"19:23","id":23,"word":"grandchild","phonetic":"","pos":"n.","meaningCN":"孙子女；外孙子女","tag":"高频","root":"","exampleEN":"The old lady has five grandchildren and she loves them all equally.","exampleCN":"那位老太太有五个孙辈，她对他们一视同仁地疼爱。","extra":""},{"chapter":19,"key":"19:24","id":24,"word":"grandson","phonetic":"","pos":"n.","meaningCN":"孙子；外孙","tag":"高频","root":"","exampleEN":"He taught his grandson how to play chess when the boy was only six.","exampleCN":"他在孙子才六岁时就教他下棋。","extra":""},{"chapter":19,"key":"19:25","id":25,"word":"granddaughter","phonetic":"","pos":"n.","meaningCN":"孙女；外孙女","tag":"高频","root":"","exampleEN":"Her granddaughter gave her a handmade card on her 80th birthday.","exampleCN":"她80岁生日时孙女送了她一张手工制作的贺卡。","extra":""},{"chapter":19,"key":"19:26","id":26,"word":"father-in-law","phonetic":"","pos":"n.","meaningCN":"岳父；公公","tag":"高频","root":"","exampleEN":"He gets along very well with his father-in-law and they often go fishing together.","exampleCN":"他和岳父相处得很好，两人经常一起去钓鱼。","extra":""},{"chapter":19,"key":"19:27","id":27,"word":"mother-in-law","phonetic":"","pos":"n.","meaningCN":"岳母；婆婆","tag":"高频","root":"","exampleEN":"She was nervous about meeting her future mother-in-law for the first time.","exampleCN":"她第一次见未来的婆婆时感到很紧张。","extra":""},{"chapter":19,"key":"19:28","id":28,"word":"sister-in-law","phonetic":"","pos":"n.","meaningCN":"嫂子；弟媳；大/小姑子；大/小姨子","tag":"高频","root":"","exampleEN":"My sister-in-law is a great cook and she often invites us over for dinner.","exampleCN":"我的嫂子是个很棒的厨师，她经常邀请我们去吃饭。","extra":""},{"chapter":19,"key":"19:29","id":29,"word":"brother-in-law","phonetic":"","pos":"n.","meaningCN":"姐夫；妹夫；大伯/小叔；大/小舅子","tag":"高频","root":"","exampleEN":"He and his brother-in-law are planning to start a small business together.","exampleCN":"他和姐夫正计划一起做点小生意。","extra":""},{"chapter":19,"key":"19:30","id":30,"word":"sibling","phonetic":"","pos":"n.","meaningCN":"兄、弟、姐、妹","tag":"核心","root":"","exampleEN":"She has three siblings: an older brother and two younger sisters.","exampleCN":"她有三个兄弟姐妹：一个哥哥和两个妹妹。","extra":""},{"chapter":19,"key":"19:31","id":31,"word":"cousin","phonetic":"","pos":"n.","meaningCN":"堂（表）兄/弟/姐/妹","tag":"核心","root":"","exampleEN":"Every summer we used to spend a month at the seaside with our cousins.","exampleCN":"从前每个夏天我们都和堂兄妹们到海边度过一个月。","extra":""},{"chapter":19,"key":"19:32","id":32,"word":"embryo","phonetic":"","pos":"n.","meaningCN":"胚胎 / adj. 胚胎的；初期的","tag":"低频","root":"","exampleEN":"The project is still in its embryo stage and needs much more development.","exampleCN":"该项目仍处于初期阶段，还需要更多的开发。","extra":""},{"chapter":19,"key":"19:33","id":33,"word":"infant","phonetic":"","pos":"n.","meaningCN":"婴儿 / adj. 供婴儿用的","tag":"高频","root":"","exampleEN":"The infant was sleeping peacefully in its mother's arms.","exampleCN":"婴儿在母亲的怀里安静地睡着。","extra":""},{"chapter":19,"key":"19:34","id":34,"word":"orphan","phonetic":"","pos":"n.","meaningCN":"孤儿 / v. 使成为孤儿","tag":"高频","root":"","exampleEN":"The earthquake left many children orphaned and in urgent need of care.","exampleCN":"地震使许多儿童成为孤儿，急需照料。","extra":""},{"chapter":19,"key":"19:35","id":35,"word":"juvenile","phonetic":"","pos":"adj.","meaningCN":"少年的 / n. 少年","tag":"高频","root":"","exampleEN":"The government is taking steps to deal with the rise in juvenile crime.","exampleCN":"政府正采取措施应对青少年犯罪上升的问题。","extra":"搭配：juvenile delinquency 青少年犯罪"},{"chapter":19,"key":"19:36","id":36,"word":"youngster","phonetic":"","pos":"n.","meaningCN":"年轻人；少年","tag":"高频","root":"","exampleEN":"A group of youngsters were playing basketball in the park after school.","exampleCN":"一群年轻人放学后在公园里打篮球。","extra":""},{"chapter":19,"key":"19:37","id":37,"word":"youth","phonetic":"","pos":"n.","meaningCN":"青年时期；青春；青年","tag":"核心","root":"","exampleEN":"She spent her youth travelling around Europe and Asia.","exampleCN":"她的青年时期是在欧洲和亚洲旅行度过的。","extra":"youthful"},{"chapter":19,"key":"19:38","id":38,"word":"adolescence","phonetic":"","pos":"n.","meaningCN":"青春期","tag":"核心","root":"","exampleEN":"Adolescence is a period of rapid physical and emotional change.","exampleCN":"青春期是一段身体和情绪都迅速变化的时期。","extra":"搭配：reach one's adolescence 进入青春期"},{"chapter":19,"key":"19:39","id":39,"word":"teenager","phonetic":"","pos":"n.","meaningCN":"13至19岁的青少年","tag":"核心","root":"","exampleEN":"Most teenagers enjoy spending time with their friends and listening to music.","exampleCN":"大多数青少年喜欢和朋友在一起、听音乐。","extra":""},{"chapter":19,"key":"19:40","id":40,"word":"gang","phonetic":"","pos":"n.","meaningCN":"一帮，一伙（常指闹事青年）","tag":"高频","root":"","exampleEN":"The police finally arrested the gang that had been stealing cars in the area.","exampleCN":"警方终于逮捕了在该地区偷车的那一伙人。","extra":"扩展：gangster 匪徒"},{"chapter":19,"key":"19:41","id":41,"word":"kin","phonetic":"","pos":"n.","meaningCN":"家属，亲戚","tag":"低频","root":"","exampleEN":"All her kin gathered at the old family house for the reunion dinner.","exampleCN":"她所有的亲戚都聚集在老宅里吃团圆饭。","extra":""},{"chapter":19,"key":"19:42","id":42,"word":"folk","phonetic":"","pos":"n.","meaningCN":"人们；家属","tag":"核心","root":"","exampleEN":"The folk in this small village are known for their friendliness and hospitality.","exampleCN":"这个小村庄里的人以友善好客闻名。","extra":""},{"chapter":19,"key":"19:43","id":43,"word":"relative","phonetic":"","pos":"n.","meaningCN":"亲戚","tag":"核心","root":"","exampleEN":"She has many relatives living in Canada whom she visits every few years.","exampleCN":"她有很多亲戚住在加拿大，她每过几年就会去探望他们。","extra":""},{"chapter":19,"key":"19:44","id":44,"word":"relation","phonetic":"","pos":"n.","meaningCN":"亲戚","tag":"核心","root":"","exampleEN":"He is a distant relation of mine; we share the same great-grandparents.","exampleCN":"他是我的一个远房亲戚，我们有共同的曾祖父母。","extra":"搭配：a close relative 近亲"},{"chapter":19,"key":"19:45","id":45,"word":"intimate","phonetic":"","pos":"adj.","meaningCN":"亲密的；个人隐私的 / n. 密友，至交","tag":"高频","root":"inti（内部）+ mate（伙伴）","exampleEN":"They have been intimate friends since they were in primary school.","exampleCN":"他们从上小学起就是亲密的朋友。","extra":""},{"chapter":19,"key":"19:46","id":46,"word":"dear","phonetic":"","pos":"adj.","meaningCN":"亲爱的","tag":"核心","root":"","exampleEN":"Dear friends, thank you for coming to celebrate this special day with us.","exampleCN":"亲爱的朋友们，感谢你们来和我们一起庆祝这个特别的日子。","extra":""},{"chapter":19,"key":"19:47","id":47,"word":"darling","phonetic":"","pos":"n.","meaningCN":"亲爱的（人）","tag":"核心","root":"","exampleEN":"She hugged her little daughter and said, \"You are my darling.\"","exampleCN":"她抱着小女儿说：“你是我的宝贝。”","extra":""},{"chapter":19,"key":"19:48","id":48,"word":"lover","phonetic":"","pos":"n.","meaningCN":"爱好者；（婚外的）情人","tag":"核心","root":"","exampleEN":"He is a great lover of classical music and goes to concerts every month.","exampleCN":"他是古典音乐的狂热爱好者，每个月都去听音乐会。","extra":"搭配：dream lover 梦中情人"},{"chapter":19,"key":"19:49","id":49,"word":"beloved","phonetic":"","pos":"adj.","meaningCN":"深受喜爱的 / n. 爱人","tag":"高频","root":"","exampleEN":"The old teacher was much beloved by all his students for his kindness.","exampleCN":"那位老教师因和蔼可亲而深受所有学生的爱戴。","extra":""},{"chapter":19,"key":"19:50","id":50,"word":"madam","phonetic":"","pos":"n.","meaningCN":"夫人，女士","tag":"高频","root":"","exampleEN":"Can I help you with your luggage, madam?","exampleCN":"夫人，需要我帮您拿行李吗？","extra":""},{"chapter":19,"key":"19:51","id":51,"word":"hostess","phonetic":"","pos":"n.","meaningCN":"女主人","tag":"高频","root":"","exampleEN":"The hostess welcomed each guest warmly at the door of the party.","exampleCN":"女主人在聚会门口热情地欢迎每一位客人。","extra":"搭配：an air hostess 空姐"},{"chapter":19,"key":"19:52","id":52,"word":"landlady","phonetic":"","pos":"n.","meaningCN":"女房东；女地主","tag":"高频","root":"","exampleEN":"The landlady comes to collect the rent on the first day of each month.","exampleCN":"女房东每个月的第一天来收房租。","extra":""},{"chapter":19,"key":"19:53","id":53,"word":"mistress","phonetic":"","pos":"n.","meaningCN":"女主人；情妇","tag":"低频","root":"","exampleEN":"The dog immediately obeyed the voice of its mistress and sat down.","exampleCN":"那条狗一听到女主人的声音就立刻坐下来。","extra":""},{"chapter":19,"key":"19:54","id":54,"word":"housewife","phonetic":"","pos":"n.","meaningCN":"家庭主妇","tag":"核心","root":"","exampleEN":"Being a housewife is a full-time job that requires many different skills.","exampleCN":"当家庭主妇是一份需要多种不同技能的全职工作。","extra":""},{"chapter":19,"key":"19:55","id":55,"word":"widow","phonetic":"","pos":"n.","meaningCN":"寡妇","tag":"高频","root":"","exampleEN":"The widow continued to run the farm after her husband passed away.","exampleCN":"丈夫去世后，那位寡妇继续经营着农场。","extra":"window（联想记忆）"},{"chapter":19,"key":"19:56","id":56,"word":"maid","phonetic":"","pos":"n.","meaningCN":"女佣；少女","tag":"高频","root":"","exampleEN":"The maid was polishing the silver cutlery in the dining room.","exampleCN":"女佣正在餐厅里擦拭银质餐具。","extra":""},{"chapter":19,"key":"19:57","id":57,"word":"maiden","phonetic":"","pos":"n.","meaningCN":"少女","tag":"低频","root":"","exampleEN":"The young maiden walked through the forest singing a soft melody.","exampleCN":"那位少女哼着轻柔的曲子穿过了森林。","extra":""},{"chapter":19,"key":"19:58","id":58,"word":"household","phonetic":"","pos":"n.","meaningCN":"家庭，一户；家务","tag":"核心","root":"","exampleEN":"In the average household, electricity is used mainly for heating and cooking.","exampleCN":"在普通家庭中，电主要用于取暖和做饭。","extra":"搭配：a low-income household 低收入家庭"},{"chapter":19,"key":"19:59","id":59,"word":"chore","phonetic":"","pos":"n.","meaningCN":"家庭杂务；乏味的工作","tag":"高频","root":"","exampleEN":"Washing the dishes is easily her least favourite chore in the house.","exampleCN":"洗碗很可能是她最不喜欢的家务活。","extra":"搭配：do the domestic chores 做家务"},{"chapter":19,"key":"19:60","id":60,"word":"host","phonetic":"","pos":"n.","meaningCN":"主人","tag":"核心","root":"","exampleEN":"The host greeted us at the door and led us into the living room.","exampleCN":"主人在门口招呼我们，然后带我们进了客厅。","extra":""},{"chapter":19,"key":"19:61","id":61,"word":"landlord","phonetic":"","pos":"n.","meaningCN":"房东；地主","tag":"核心","root":"","exampleEN":"The landlord agreed to fix the broken water pipe by the end of the week.","exampleCN":"房东答应在周末之前修好破裂的水管。","extra":""},{"chapter":19,"key":"19:62","id":62,"word":"guest","phonetic":"","pos":"n.","meaningCN":"客人","tag":"核心","root":"","exampleEN":"The hotel welcomes guests from all over the world with warm service.","exampleCN":"这家酒店以热情的服务欢迎来自世界各地的客人。","extra":""},{"chapter":19,"key":"19:63","id":63,"word":"customer","phonetic":"","pos":"n.","meaningCN":"顾客","tag":"核心","root":"","exampleEN":"The shop assistant always smiles and says hello to every customer.","exampleCN":"那个店员总是微笑着向每一位顾客问好。","extra":""},{"chapter":19,"key":"19:64","id":64,"word":"client","phonetic":"","pos":"n.","meaningCN":"客户，委托人","tag":"核心","root":"","exampleEN":"The lawyer spent the morning preparing documents for a very important client.","exampleCN":"律师花了一个上午为一位非常重要的客户准备文件。","extra":""},{"chapter":19,"key":"19:65","id":65,"word":"tenant","phonetic":"","pos":"n.","meaningCN":"房客；租户","tag":"高频","root":"","exampleEN":"The tenants have to pay the electricity bill in addition to the monthly rent.","exampleCN":"除了月租以外，房客还得付电费。","extra":""},{"chapter":19,"key":"19:66","id":66,"word":"encounter","phonetic":"","pos":"v./n.","meaningCN":"遭遇；偶遇","tag":"核心","root":"","exampleEN":"During her trip she had a chance encounter with an old school friend.","exampleCN":"旅途中她与一位老同学不期而遇。","extra":"搭配：a chance encounter 偶遇"},{"chapter":19,"key":"19:67","id":67,"word":"chase","phonetic":"","pos":"v./n.","meaningCN":"追逐；追求","tag":"核心","root":"","exampleEN":"The police car was chasing the stolen vehicle down the highway.","exampleCN":"警车正在高速公路上追赶那辆被盗车辆。","extra":""},{"chapter":19,"key":"19:68","id":68,"word":"appointment","phonetic":"","pos":"n.","meaningCN":"约会；指派","tag":"核心","root":"","exampleEN":"I have a dentist appointment at 3 p.m. so I need to leave early.","exampleCN":"我下午三点约了牙医，所以得早走。","extra":"搭配：make an appointment 预约"},{"chapter":19,"key":"19:69","id":69,"word":"accompany","phonetic":"","pos":"v.","meaningCN":"陪伴；伴随","tag":"核心","root":"pan = 面包","exampleEN":"She asked her brother to accompany her to the important job interview.","exampleCN":"她请哥哥陪她去那场重要的求职面试。","extra":"companion n. 同伴；搭配：accompany sb. on the trip 陪某人旅行"},{"chapter":19,"key":"19:70","id":70,"word":"dependent","phonetic":"","pos":"adj.","meaningCN":"依靠的，依赖的","tag":"核心","root":"","exampleEN":"The country's economy is heavily dependent on the export of oil.","exampleCN":"该国经济严重依赖石油出口。","extra":"independent, interdependent；搭配：be dependent on 依赖于"},{"chapter":19,"key":"19:71","id":71,"word":"propose","phonetic":"","pos":"v.","meaningCN":"提议；求婚","tag":"核心","root":"","exampleEN":"He planned to propose marriage to his girlfriend on top of the mountain at sunset.","exampleCN":"他打算在日落时分在山顶上向女友求婚。","extra":"搭配：propose marriage 求婚"},{"chapter":19,"key":"19:72","id":72,"word":"engagement","phonetic":"","pos":"n.","meaningCN":"婚约；约定","tag":"高频","root":"","exampleEN":"They announced their engagement at a family dinner last Sunday.","exampleCN":"上周日，他们在家宴上宣布了订婚的消息。","extra":""},{"chapter":19,"key":"19:73","id":73,"word":"marry","phonetic":"","pos":"v.","meaningCN":"结婚","tag":"核心","root":"","exampleEN":"They fell in love at university and decided to marry soon after graduation.","exampleCN":"他们在大学里相爱，毕业后很快就决定结婚。","extra":""},{"chapter":19,"key":"19:74","id":74,"word":"marriage","phonetic":"","pos":"n.","meaningCN":"婚姻","tag":"核心","root":"","exampleEN":"Their marriage was based on love, trust and respect for each other.","exampleCN":"他们的婚姻建立在相爱、信任和相互尊重的基础上。","extra":""},{"chapter":19,"key":"19:75","id":75,"word":"married","phonetic":"","pos":"adj.","meaningCN":"已婚的","tag":"核心","root":"","exampleEN":"She is married and has two young children who keep her very busy.","exampleCN":"她已经结婚，有两个年幼的孩子，让她忙得不可开交。","extra":""},{"chapter":19,"key":"19:76","id":76,"word":"wedding","phonetic":"","pos":"n.","meaningCN":"婚礼","tag":"核心","root":"","exampleEN":"More than 200 guests were invited to attend the grand wedding ceremony.","exampleCN":"200多位宾客受邀参加了这场盛大的婚礼。","extra":"搭配：wedding anniversary 结婚纪念日；golden wedding 金婚"},{"chapter":19,"key":"19:77","id":77,"word":"honeymoon","phonetic":"","pos":"n.","meaningCN":"蜜月","tag":"高频","root":"","exampleEN":"They spent their honeymoon on a small Greek island with white sandy beaches.","exampleCN":"他们在一个有着白色沙滩的希腊小岛上度过了蜜月。","extra":"搭配：honeymoon suite 蜜月套房"},{"chapter":19,"key":"19:78","id":78,"word":"respective","phonetic":"","pos":"adj.","meaningCN":"各自的，分别的","tag":"高频","root":"","exampleEN":"After the meeting, they all went back to their respective offices.","exampleCN":"会后，他们都回到了各自的办公室。","extra":"respectively adv. 分别地"},{"chapter":19,"key":"19:79","id":79,"word":"each","phonetic":"","pos":"det./pron.","meaningCN":"每个，各自","tag":"核心","root":"","exampleEN":"Each student was given a certificate for completing the course.","exampleCN":"每个学生都收到了一张完成课程的证书。","extra":""},{"chapter":19,"key":"19:80","id":80,"word":"individual","phonetic":"","pos":"n.","meaningCN":"个人，个体","tag":"核心","root":"","exampleEN":"The needs of the individual should not be ignored for the sake of the group.","exampleCN":"不应该为了集体而忽视个人的需求。","extra":""},{"chapter":19,"key":"19:81","id":81,"word":"single","phonetic":"","pos":"adj.","meaningCN":"单一的；单身的","tag":"核心","root":"","exampleEN":"Are you still single, or have you found a boyfriend yet?","exampleCN":"你还是单身吗，还是已经找到男朋友了？","extra":""},{"chapter":19,"key":"19:82","id":82,"word":"sole","phonetic":"","pos":"adj.","meaningCN":"仅有的，唯一的","tag":"高频","root":"","exampleEN":"He is the sole survivor of the plane crash that killed over forty people.","exampleCN":"他是那起造成40多人遇难的飞机坠毁事故中唯一的幸存者。","extra":""},{"chapter":19,"key":"19:83","id":83,"word":"divorce","phonetic":"","pos":"v./n.","meaningCN":"离婚；脱离","tag":"核心","root":"","exampleEN":"The couple divorced after just two years of marriage.","exampleCN":"那对夫妻仅仅结婚两年就离婚了。","extra":"搭配：be divorced from 与......脱离"},{"chapter":19,"key":"19:84","id":84,"word":"separate","phonetic":"","pos":"adj.","meaningCN":"分开的 / v. 分离","tag":"核心","root":"","exampleEN":"We have booked two separate rooms in the hotel for the weekend.","exampleCN":"我们周末在酒店预订了两间分开的房间。","extra":"搭配：separate from 与......分离"},{"chapter":19,"key":"19:85","id":85,"word":"neighbourhood","phonetic":"","pos":"n.","meaningCN":"街坊；居住区","tag":"核心","root":"","exampleEN":"There is a very friendly atmosphere in this neighbourhood; everyone says hello.","exampleCN":"这个街区气氛非常友好，大家见面都互相打招呼。","extra":""},{"chapter":19,"key":"19:86","id":86,"word":"member","phonetic":"","pos":"n.","meaningCN":"成员","tag":"核心","root":"","exampleEN":"She has been a member of the local history society for more than ten years.","exampleCN":"她加入当地历史学会已经超过十年了。","extra":""},{"chapter":19,"key":"19:87","id":87,"word":"membership","phonetic":"","pos":"n.","meaningCN":"成员资格","tag":"核心","root":"","exampleEN":"His membership in the club was cancelled because he broke the rules.","exampleCN":"他因违反规定被取消了俱乐部会员资格。","extra":""},{"chapter":19,"key":"19:88","id":88,"word":"boss","phonetic":"","pos":"n.","meaningCN":"老板","tag":"核心","root":"","exampleEN":"His boss praised him for finishing the difficult project ahead of time.","exampleCN":"老板表扬了他提前完成了那个困难的项目。","extra":""},{"chapter":19,"key":"19:89","id":89,"word":"manager","phonetic":"","pos":"n.","meaningCN":"经理","tag":"核心","root":"","exampleEN":"The new manager introduced several changes that greatly improved efficiency.","exampleCN":"新经理引入了几项变革，大大提高了效率。","extra":""},{"chapter":19,"key":"19:90","id":90,"word":"supervisor","phonetic":"","pos":"n.","meaningCN":"主管，监督人","tag":"高频","root":"","exampleEN":"Your supervisor will check the final report before it is sent to the client.","exampleCN":"你的主管会在最终报告发给客户之前检查一遍。","extra":""},{"chapter":19,"key":"19:91","id":91,"word":"subordinate","phonetic":"","pos":"n.","meaningCN":"下级，下属","tag":"高频","root":"","exampleEN":"A good manager always listens to the suggestions of his or her subordinates.","exampleCN":"一名好经理总是会倾听下属的建议。","extra":""},{"chapter":19,"key":"19:92","id":92,"word":"partner","phonetic":"","pos":"n.","meaningCN":"伙伴，搭档","tag":"核心","root":"","exampleEN":"She has been a loyal business partner for many years and I trust her completely.","exampleCN":"她是我多年来忠实的业务伙伴，我完全信任她。","extra":""},{"chapter":19,"key":"19:93","id":93,"word":"mate","phonetic":"","pos":"n.","meaningCN":"伙伴；伴侣","tag":"核心","root":"","exampleEN":"He and his mates go to the football match every Saturday afternoon.","exampleCN":"他和他的伙伴们每周六下午都去看足球赛。","extra":""},{"chapter":19,"key":"19:94","id":94,"word":"colleague","phonetic":"","pos":"n.","meaningCN":"同事","tag":"核心","root":"","exampleEN":"My colleague and I are working together on a sales report for the meeting.","exampleCN":"我和同事正在合作为会议准备一份销售报告。","extra":""},{"chapter":19,"key":"19:95","id":95,"word":"comrade","phonetic":"","pos":"n.","meaningCN":"同志；同事，伙伴","tag":"高频","root":"","exampleEN":"The old soldier often told stories about his brave comrades during the war.","exampleCN":"那位老兵经常讲起他战争中勇敢的战友们的故事。","extra":""},{"chapter":19,"key":"19:96","id":96,"word":"acquaintance","phonetic":"","pos":"n.","meaningCN":"相识的人；了解","tag":"高频","root":"","exampleEN":"He is not a close friend, just a business acquaintance I met at a conference.","exampleCN":"他不是密友，只是我在一次会议上认识的一个生意上的熟人。","extra":""},{"chapter":19,"key":"19:97","id":97,"word":"friendship","phonetic":"","pos":"n.","meaningCN":"友谊","tag":"核心","root":"","exampleEN":"True friendship is about supporting each other through both good and bad times.","exampleCN":"真正的友谊在于无论顺境逆境都互相支持。","extra":""},{"chapter":19,"key":"19:98","id":98,"word":"affection","phonetic":"","pos":"n.","meaningCN":"喜爱，感情","tag":"核心","root":"","exampleEN":"She shows great affection for her grandparents and visits them every week.","exampleCN":"她对祖父母感情很深，每星期都去看望他们。","extra":""},{"chapter":19,"key":"19:99","id":99,"word":"stranger","phonetic":"","pos":"n.","meaningCN":"陌生人","tag":"核心","root":"","exampleEN":"The little girl was told never to accept sweets from strangers.","exampleCN":"那个小女孩被教导永远不要接受陌生人的糖果。","extra":"搭配：a stranger in a strange land 异乡异客"},{"chapter":19,"key":"19:100","id":100,"word":"apprentice","phonetic":"","pos":"n.","meaningCN":"学徒","tag":"高频","root":"","exampleEN":"He started his career as an apprentice in a small garage before becoming a chief mechanic.","exampleCN":"他职业生涯之初是在一家小修理厂当学徒，后来成了首席技师。","extra":""},{"chapter":19,"key":"19:101","id":101,"word":"deputy","phonetic":"","pos":"n.","meaningCN":"代理人，副手","tag":"高频","root":"","exampleEN":"The deputy manager will take charge of the office while the manager is on leave.","exampleCN":"经理休假期间，副经理将负责办公室事务。","extra":""},{"chapter":19,"key":"19:102","id":102,"word":"hero","phonetic":"","pos":"n.","meaningCN":"男主角；英雄","tag":"核心","root":"","exampleEN":"The young man was considered a hero after he saved the child from the river.","exampleCN":"那个年轻人从河里救出了孩子后，被人们视为英雄。","extra":""},{"chapter":19,"key":"19:103","id":103,"word":"heroine","phonetic":"","pos":"n.","meaningCN":"女主角；女英雄","tag":"核心","root":"","exampleEN":"The heroine of the novel is a brave young woman who fights against social injustice.","exampleCN":"小说的女主角是一个勇敢的年轻女子，她与社会的种种不公作斗争。","extra":""},{"chapter":19,"key":"19:104","id":104,"word":"proponent","phonetic":"","pos":"n.","meaningCN":"拥护者","tag":"低频","root":"","exampleEN":"He is a leading proponent of free trade and economic globalisation.","exampleCN":"他是自由贸易和经济全球化的主要倡导者。","extra":""},{"chapter":19,"key":"19:105","id":105,"word":"opponent","phonetic":"","pos":"n.","meaningCN":"反对者","tag":"核心","root":"","exampleEN":"His opponent in the debate argued strongly against the new tax proposal.","exampleCN":"对方在辩论中强烈反对新的税收提案。","extra":""},{"chapter":19,"key":"19:106","id":106,"word":"committee","phonetic":"","pos":"n.","meaningCN":"委员会","tag":"核心","root":"","exampleEN":"The committee will meet next Monday to make a final decision on the project.","exampleCN":"委员会将于下周一开会，就该项目作出最终决定。","extra":""},{"chapter":19,"key":"19:107","id":107,"word":"council","phonetic":"","pos":"n.","meaningCN":"委员会；议会","tag":"核心","root":"","exampleEN":"The city council is responsible for maintaining public parks and roads.","exampleCN":"市议会负责维护公园和道路。","extra":""},{"chapter":19,"key":"19:108","id":108,"word":"actor","phonetic":"","pos":"n.","meaningCN":"演员","tag":"核心","root":"","exampleEN":"He dreamed of becoming an actor and finally made his first film at the age of 30.","exampleCN":"他梦想成为一名演员，终于在30岁时出演了他的第一部电影。","extra":""},{"chapter":19,"key":"19:109","id":109,"word":"actress","phonetic":"","pos":"n.","meaningCN":"女演员","tag":"核心","root":"","exampleEN":"The actress played the role of a strict but fair teacher in the movie.","exampleCN":"那位女演员在电影中扮演了一个严格又公正的教师。","extra":""},{"chapter":19,"key":"19:110","id":110,"word":"delegate","phonetic":"","pos":"n.","meaningCN":"代表 / v. 授权，委派","tag":"高频","root":"leg = 送；委派","exampleEN":"Each country sent two delegates to the international trade conference.","exampleCN":"每个国家派出了两名代表参加国际贸易会议。","extra":""},{"chapter":19,"key":"19:111","id":111,"word":"chancellor","phonetic":"","pos":"n.","meaningCN":"总理；财政大臣","tag":"低频","root":"","exampleEN":"The German chancellor gave a speech about European cooperation at the summit.","exampleCN":"德国总理在峰会上就欧洲合作发表了演讲。","extra":"词源：cancelli（斜格）"},{"chapter":19,"key":"19:112","id":112,"word":"specialist","phonetic":"","pos":"n.","meaningCN":"专家；专科医生","tag":"核心","root":"","exampleEN":"If the pain continues, you should see a specialist for further examination.","exampleCN":"如果疼痛持续，你应该去看专科医生做进一步检查。","extra":""},{"chapter":19,"key":"19:113","id":113,"word":"commander","phonetic":"","pos":"n.","meaningCN":"指挥官","tag":"高频","root":"","exampleEN":"The commander ordered his troops to move forward and secure the bridge.","exampleCN":"指挥官命令部队前进并确保桥梁安全。","extra":""},{"chapter":19,"key":"19:114","id":114,"word":"director","phonetic":"","pos":"n.","meaningCN":"董事；导演；主任","tag":"核心","root":"","exampleEN":"The film director spent three years making this documentary about ocean life.","exampleCN":"这位电影导演花了三年时间拍摄这部关于海洋生命的纪录片。","extra":""},{"chapter":19,"key":"19:115","id":115,"word":"consultant","phonetic":"","pos":"n.","meaningCN":"顾问","tag":"核心","root":"","exampleEN":"The company hired a management consultant to improve its business strategy.","exampleCN":"公司聘请了一位管理顾问来改进其业务策略。","extra":""},{"chapter":19,"key":"19:116","id":116,"word":"butcher","phonetic":"","pos":"n.","meaningCN":"屠夫","tag":"高频","root":"","exampleEN":"The butcher recommended the best cut of beef for a Sunday roast.","exampleCN":"屠夫推荐了最适合周日烧烤的一块上好牛肉。","extra":"搭配：a butcher's 肉铺"},{"chapter":19,"key":"19:117","id":117,"word":"groom","phonetic":"","pos":"n.","meaningCN":"马夫；新郎","tag":"高频","root":"","exampleEN":"The groom looked extremely happy as he waited for his bride at the altar.","exampleCN":"新郎在圣坛前等待新娘时，显得无比幸福。","extra":""},{"chapter":19,"key":"19:118","id":118,"word":"bridegroom","phonetic":"","pos":"n.","meaningCN":"新郎","tag":"低频","root":"","exampleEN":"The bridegroom made a touching speech thanking both families for their support.","exampleCN":"新郎发表了一段感人的讲话，感谢双方家庭的支持。","extra":""},{"chapter":19,"key":"19:119","id":119,"word":"bride","phonetic":"","pos":"n.","meaningCN":"新娘","tag":"高频","root":"","exampleEN":"The bride wore a beautiful long white dress decorated with tiny flowers.","exampleCN":"新娘穿着一件装饰着小花的漂亮白色长裙。","extra":""},{"chapter":19,"key":"19:120","id":120,"word":"hostage","phonetic":"","pos":"n.","meaningCN":"人质","tag":"核心","root":"","exampleEN":"The kidnappers took the driver hostage and demanded a large sum of money.","exampleCN":"绑匪劫持了司机，索要一大笔赎金。","extra":""},{"chapter":19,"key":"19:121","id":121,"word":"toil","phonetic":"","pos":"n.","meaningCN":"苦工；辛勤劳作","tag":"低频","root":"","exampleEN":"After years of hard toil, the farmer finally turned the dry land into a green garden.","exampleCN":"经过多年的辛苦劳作，这位农民终于把旱地变成了一座绿色园子。","extra":""},{"chapter":19,"key":"19:122","id":122,"word":"beggar","phonetic":"","pos":"n.","meaningCN":"乞丐","tag":"高频","root":"","exampleEN":"There used to be many beggars on the streets, but now the city provides shelters for them.","exampleCN":"过去街上有许多乞丐，但现在城市为他们提供了收容所。","extra":""},{"chapter":19,"key":"19:123","id":123,"word":"slave","phonetic":"","pos":"n.","meaningCN":"奴隶","tag":"核心","root":"","exampleEN":"In many parts of the world, people fought hard to put an end to the slave trade.","exampleCN":"在世界许多地方，人们进行了艰苦的斗争来结束奴隶贸易。","extra":""},{"chapter":19,"key":"19:124","id":124,"word":"coward","phonetic":"","pos":"n.","meaningCN":"懦夫，胆小鬼","tag":"高频","root":"","exampleEN":"He called me a coward just because I refused to climb the high bridge.","exampleCN":"仅仅因为我拒绝爬上那座高桥，他就说我是胆小鬼。","extra":""}],"20":[{"chapter":20,"key":"20:1","id":1,"word":"act","phonetic":"/ækt/","pos":"v./n.","meaningCN":"行动；行为","tag":"核心","root":"","exampleEN":"To make a difference, you need to act instead of just talking about your plans.","exampleCN":"要做出改变，你需要付诸行动，而不仅仅是空谈计划。","extra":"activity n. 活动；active adj. 活跃的；action n. 行动；interact v. 互相影响"},{"chapter":20,"key":"20:2","id":2,"word":"behave","phonetic":"/bɪˈheɪv/","pos":"v.","meaningCN":"表现；（机器等）运转","tag":"核心","root":"","exampleEN":"Children are expected to behave politely when visiting their grandparents.","exampleCN":"看望祖父母时，孩子们应当表现得有礼貌。","extra":"behaviour n. 行为"},{"chapter":20,"key":"20:3","id":3,"word":"deed","phonetic":"/diːd/","pos":"n.","meaningCN":"行为；功绩；契约","tag":"高频","root":"","exampleEN":"His brave deed during the flood saved several lives and made him a local hero.","exampleCN":"他在洪水中的英勇行为救了好几条人命，使他成了当地的英雄。","extra":""},{"chapter":20,"key":"20:4","id":4,"word":"accustom","phonetic":"/əˈkʌstəm/","pos":"v.","meaningCN":"使习惯（于）","tag":"高频","root":"","exampleEN":"It took her several months to accustom herself to the fast pace of city life.","exampleCN":"她花了好几个月才习惯城市生活的快节奏。","extra":""},{"chapter":20,"key":"20:5","id":5,"word":"react","phonetic":"/riˈækt/","pos":"v.","meaningCN":"作出反应，反应","tag":"核心","root":"","exampleEN":"The public reacted angrily to the news of the planned tax increase.","exampleCN":"公众对计划增税的消息反应愤怒。","extra":"reaction n. 反应；搭配：react to 对……作出反应"},{"chapter":20,"key":"20:6","id":6,"word":"respond","phonetic":"/rɪˈspɒnd/","pos":"v.","meaningCN":"回答；响应，作出反应","tag":"核心","root":"","exampleEN":"The company responded quickly to customer complaints and improved the service.","exampleCN":"公司迅速回应了客户投诉并改善了服务。","extra":"response n. 反应，回应"},{"chapter":20,"key":"20:7","id":7,"word":"reflect","phonetic":"/rɪˈflekt/","pos":"v.","meaningCN":"反映；反射","tag":"核心","root":"flect/flex = 弯曲","exampleEN":"The calm surface of the lake reflected the surrounding mountains like a mirror.","exampleCN":"平静的湖面如镜子般倒映出周围的群山。","extra":"reflection n. 反射；倒影"},{"chapter":20,"key":"20:8","id":8,"word":"bear","phonetic":"/beə/","pos":"v.","meaningCN":"生（孩子）；容忍；承担（责任）","tag":"核心","root":"","exampleEN":"As a manager, you must be ready to bear the responsibility for your team's mistakes.","exampleCN":"作为经理，你必须准备好为团队的错误承担责任。","extra":"搭配：bear responsibility for 对……负有责任"},{"chapter":20,"key":"20:9","id":9,"word":"adopt","phonetic":"/əˈdɒpt/","pos":"v.","meaningCN":"收养；采取，采用","tag":"核心","root":"","exampleEN":"Many companies are now adopting more flexible working policies for their staff.","exampleCN":"许多公司现在都在为员工采取更灵活的工作政策。","extra":"adapt v. 适应"},{"chapter":20,"key":"20:10","id":10,"word":"nourish","phonetic":"/ˈnʌrɪʃ/","pos":"v.","meaningCN":"滋养，给……提供营养","tag":"高频","root":"","exampleEN":"A good breakfast can nourish your body and give you energy for the whole morning.","exampleCN":"一顿营养丰富的早餐能滋养身体，为你提供一整个上午的能量。","extra":"nourishment n. 营养品；nourishing adj. 有营养的"},{"chapter":20,"key":"20:11","id":11,"word":"mow","phonetic":"/məʊ/","pos":"v.","meaningCN":"割，修剪 n. 干草堆","tag":"低频","root":"","exampleEN":"He spends every Saturday morning mowing the lawn and trimming the hedges.","exampleCN":"他每个星期六早上都修剪草坪和树篱。","extra":"搭配：mow the lawn 修剪草坪"},{"chapter":20,"key":"20:12","id":12,"word":"support","phonetic":"/səˈpɔːt/","pos":"v.","meaningCN":"支撑；支持；供养 n. 支持；帮助","tag":"核心","root":"","exampleEN":"Friends and family should support each other through difficult times.","exampleCN":"朋友和家人应该在困难时期互相支持。","extra":""},{"chapter":20,"key":"20:13","id":13,"word":"exhale","phonetic":"/eksˈheɪl/","pos":"v.","meaningCN":"呼气，呼出","tag":"高频","root":"","exampleEN":"Take a deep breath, hold it for a moment, and then exhale slowly.","exampleCN":"深吸一口气，屏住片刻，然后慢慢呼出。","extra":"inhale v. 吸气"},{"chapter":20,"key":"20:14","id":14,"word":"intake","phonetic":"/ˈɪnteɪk/","pos":"n.","meaningCN":"吸入；摄取量；新招收者","tag":"高频","root":"","exampleEN":"Reducing your daily calorie intake can help you lose weight gradually.","exampleCN":"减少每日的热量摄取有助于逐步减轻体重。","extra":"搭配：dietary intake 饮食摄取量"},{"chapter":20,"key":"20:15","id":15,"word":"revive","phonetic":"/rɪˈvaɪv/","pos":"v.","meaningCN":"（使）苏醒；（使）复兴，（使）复活","tag":"高频","root":"viv = 活","exampleEN":"The heavy rain helped revive the dying plants in the garden.","exampleCN":"那场大雨帮助花园里快要枯死的植物恢复了生机。","extra":"survive v. 幸存；vivid adj. 生动的"},{"chapter":20,"key":"20:16","id":16,"word":"survive","phonetic":"/səˈvaɪv/","pos":"v.","meaningCN":"幸存；生存","tag":"核心","root":"","exampleEN":"Only a few passengers survived the terrible plane crash in the mountains.","exampleCN":"只有少数乘客在那场可怕的山区空难中幸存。","extra":""},{"chapter":20,"key":"20:17","id":17,"word":"glare","phonetic":"/ɡleə/","pos":"v.","meaningCN":"怒目而视；发出强光 n. 刺眼的光；怒视","tag":"高频","root":"","exampleEN":"She glared at the driver who had almost hit her at the crossing.","exampleCN":"她怒视着那个几乎在十字路口撞到她的司机。","extra":""},{"chapter":20,"key":"20:18","id":18,"word":"glimpse","phonetic":"/ɡlɪmps/","pos":"v.","meaningCN":"瞥见 n. 一瞥","tag":"核心","root":"","exampleEN":"We caught a brief glimpse of the rare bird before it flew into the trees.","exampleCN":"我们瞥见那只稀有的鸟一眼，它就飞进了树林。","extra":"搭配：get a glimpse of 瞥见"},{"chapter":20,"key":"20:19","id":19,"word":"glance","phonetic":"/ɡlɑːns/","pos":"v.","meaningCN":"瞥，迅速看一眼 n. 一瞥","tag":"核心","root":"","exampleEN":"She glanced at her watch and realised she was already ten minutes late.","exampleCN":"她瞥了一眼手表，意识到自己已经迟到了十分钟。","extra":"搭配：at first glance 乍一看"},{"chapter":20,"key":"20:20","id":20,"word":"peep","phonetic":"/piːp/","pos":"v.","meaningCN":"窥视，偷看 n. 偷偷一瞥","tag":"高频","root":"","exampleEN":"The curious child peeped through the keyhole to see the birthday surprise.","exampleCN":"好奇的孩子通过钥匙孔偷看，想看看生日惊喜。","extra":"peephole n. 窥视孔；文化：Peeping Tom 偷窥狂"},{"chapter":20,"key":"20:21","id":21,"word":"gaze","phonetic":"/ɡeɪz/","pos":"v.","meaningCN":"凝视，注视","tag":"核心","root":"","exampleEN":"They stood on the hilltop, gazing at the sunset spreading across the horizon.","exampleCN":"他们站在山顶上，凝视着地平线上铺展开的落日。","extra":""},{"chapter":20,"key":"20:22","id":22,"word":"peer","phonetic":"/pɪə/","pos":"v.","meaningCN":"凝视，盯着看 n. 同等地位的人，同辈","tag":"高频","root":"","exampleEN":"She peered into the dark room but could not see anyone inside.","exampleCN":"她朝漆黑的房间里仔细张望，但看不见里面有人。","extra":""},{"chapter":20,"key":"20:23","id":23,"word":"stare","phonetic":"/steə/","pos":"v.","meaningCN":"凝视，盯着看","tag":"核心","root":"sta = 站立","exampleEN":"It is impolite to stare at strangers for too long.","exampleCN":"长时间盯着陌生人看是不礼貌的。","extra":"搭配：stare at 凝视"},{"chapter":20,"key":"20:24","id":24,"word":"contemplate","phonetic":"/ˈkɒntəmpleɪt/","pos":"v.","meaningCN":"凝视；沉思；考虑","tag":"高频","root":"","exampleEN":"She sat in the park, contemplating whether to accept the job offer overseas.","exampleCN":"她坐在公园里，反复考虑是否要接受那份海外工作。","extra":""},{"chapter":20,"key":"20:25","id":25,"word":"vow","phonetic":"/vaʊ/","pos":"n.","meaningCN":"誓约 v. 发誓","tag":"高频","root":"","exampleEN":"The couple exchanged vows in a beautiful ceremony by the sea.","exampleCN":"那对新人在海边一场美丽的仪式上互换了誓约。","extra":""},{"chapter":20,"key":"20:26","id":26,"word":"oath","phonetic":"/əʊθ/","pos":"n.","meaningCN":"誓言；宣誓","tag":"高频","root":"","exampleEN":"All witnesses must take an oath before giving evidence in court.","exampleCN":"所有证人在法庭上作证前都必须宣誓。","extra":"搭配：take/swear an oath 宣誓"},{"chapter":20,"key":"20:27","id":27,"word":"pledge","phonetic":"/pledʒ/","pos":"v.","meaningCN":"保证 n. 保证，誓言","tag":"核心","root":"","exampleEN":"The new leader pledged to reduce taxes and create more jobs for young people.","exampleCN":"新领导人保证要减税并为年轻人创造更多工作岗位。","extra":""},{"chapter":20,"key":"20:28","id":28,"word":"whistle","phonetic":"/ˈwɪsəl/","pos":"n.","meaningCN":"口哨；哨子；汽笛声 v. 吹口哨；吹哨子","tag":"核心","root":"","exampleEN":"The referee blew the whistle to signal the end of the football match.","exampleCN":"裁判吹响了哨子，示意足球比赛结束。","extra":""},{"chapter":20,"key":"20:29","id":29,"word":"reply","phonetic":"/rɪˈplaɪ/","pos":"v./n.","meaningCN":"回答，答复","tag":"核心","root":"","exampleEN":"I sent her a message yesterday, but she has not replied yet.","exampleCN":"我昨天给她发了消息，但她还没有回复。","extra":""},{"chapter":20,"key":"20:30","id":30,"word":"notify","phonetic":"/ˈnəʊtɪfaɪ/","pos":"v.","meaningCN":"通知，告知","tag":"核心","root":"","exampleEN":"Please notify the office if your contact details have changed recently.","exampleCN":"如果你的联系方式最近有变，请通知办公室。","extra":"notice n. 通知"},{"chapter":20,"key":"20:31","id":31,"word":"assert","phonetic":"/əˈsɜːt/","pos":"v.","meaningCN":"断言，坚称；坚持（自己）的主张","tag":"高频","root":"","exampleEN":"He continued to assert that he was innocent, despite the strong evidence against him.","exampleCN":"尽管有强有力的证据对他不利，他仍坚称自己是清白的。","extra":""},{"chapter":20,"key":"20:32","id":32,"word":"explain","phonetic":"/ɪkˈspleɪn/","pos":"v.","meaningCN":"说明，解释","tag":"核心","root":"","exampleEN":"The teacher explained the difficult concept again until everyone understood.","exampleCN":"老师又把那个难懂的概念解释了一遍，直到所有人都明白了。","extra":"explanation n. 解释"},{"chapter":20,"key":"20:33","id":33,"word":"quarrel","phonetic":"/ˈkwɒrəl/","pos":"v./n.","meaningCN":"吵架，争论","tag":"核心","root":"","exampleEN":"They had a minor quarrel about which film to watch, but soon made up.","exampleCN":"他们为看哪部电影而小吵了一架，但很快就和好了。","extra":"搭配：quarrel with 跟……吵架"},{"chapter":20,"key":"20:34","id":34,"word":"dispute","phonetic":"/dɪˈspjuːt/","pos":"v./n.","meaningCN":"争论，辩论","tag":"核心","root":"","exampleEN":"The two companies are involved in a legal dispute over the patent.","exampleCN":"这两家公司因专利问题卷入了一场法律纠纷。","extra":"搭配：a dispute against 与……的争议"},{"chapter":20,"key":"20:35","id":35,"word":"argument","phonetic":"/ˈɑːɡjʊmənt/","pos":"n.","meaningCN":"辩论，争论；论点，论据","tag":"核心","root":"","exampleEN":"She made a strong argument for starting the meeting earlier in the morning.","exampleCN":"她提出了一个强有力的论点，主张早上早些开会。","extra":"argue v. 争论"},{"chapter":20,"key":"20:36","id":36,"word":"mention","phonetic":"/ˈmenʃən/","pos":"v./n.","meaningCN":"提及，说起","tag":"核心","root":"","exampleEN":"He mentioned your name during the conversation and said he admired your work.","exampleCN":"他在谈话中提起了你的名字，并说他很钦佩你的工作。","extra":"搭配：at the mention of 一提起"},{"chapter":20,"key":"20:37","id":37,"word":"hurry","phonetic":"/ˈhʌri/","pos":"v.","meaningCN":"赶紧；催促 n. 匆忙","tag":"核心","root":"","exampleEN":"We need to hurry if we want to catch the last train home.","exampleCN":"如果我们想赶上回家的末班车，就得赶紧了。","extra":""},{"chapter":20,"key":"20:38","id":38,"word":"hasten","phonetic":"/ˈheɪsən/","pos":"v.","meaningCN":"赶紧；促进","tag":"高频","root":"","exampleEN":"The bad weather hastened our decision to leave the campsite early.","exampleCN":"恶劣的天气促使我们决定提早离开营地。","extra":"hasty adj. 匆忙的；haste n. 匆忙"},{"chapter":20,"key":"20:39","id":39,"word":"urge","phonetic":"/ɜːdʒ/","pos":"v.","meaningCN":"催促，敦促 n. 冲动","tag":"核心","root":"","exampleEN":"Doctors urge people to stop smoking in order to protect their lungs.","exampleCN":"医生敦促人们戒烟以保护肺部健康。","extra":"urgent adj. 紧急的；搭配：urge sb. to do sth."},{"chapter":20,"key":"20:40","id":40,"word":"scold","phonetic":"/skəʊld/","pos":"v.","meaningCN":"责骂，斥责","tag":"高频","root":"","exampleEN":"She gently scolded the child for drawing on the wall with crayons.","exampleCN":"她轻声责备孩子在墙上乱画蜡笔。","extra":""},{"chapter":20,"key":"20:41","id":41,"word":"curse","phonetic":"/kɜːs/","pos":"v.","meaningCN":"诅咒；咒骂 n. 咒语；咒骂话","tag":"高频","root":"","exampleEN":"He cursed loudly when he dropped the heavy box on his foot.","exampleCN":"当沉重的箱子砸到脚上时，他大声咒骂了一句。","extra":"搭配：be under a curse 被诅咒"},{"chapter":20,"key":"20:42","id":42,"word":"swear","phonetic":"/sweə/","pos":"v.","meaningCN":"诅咒，咒骂；发誓，保证","tag":"核心","root":"","exampleEN":"I swear that I will return the book to you by the end of the week.","exampleCN":"我保证这个周末之前把书还给你。","extra":""},{"chapter":20,"key":"20:43","id":43,"word":"provoke","phonetic":"/prəˈvəʊk/","pos":"v.","meaningCN":"激怒，挑拨；引起","tag":"高频","root":"","exampleEN":"His rude comments provoked an angry reaction from the audience.","exampleCN":"他粗鲁的评论引起了观众的愤怒反应。","extra":"thought-provoking adj. 发人深省的"},{"chapter":20,"key":"20:44","id":44,"word":"preach","phonetic":"/priːtʃ/","pos":"v.","meaningCN":"宣扬","tag":"高频","root":"","exampleEN":"He is always preaching the benefits of a simple and healthy lifestyle.","exampleCN":"他总是宣扬简单健康生活方式的好处。","extra":"搭配：preach at/to sb. 对某人说教"},{"chapter":20,"key":"20:45","id":45,"word":"boast","phonetic":"/bəʊst/","pos":"v./n.","meaningCN":"自夸，吹嘘","tag":"核心","root":"","exampleEN":"He often boasts about his achievements, which makes his colleagues uncomfortable.","exampleCN":"他经常吹嘘自己的成就，这让同事们感到不舒服。","extra":"boastful adj. 自夸的；搭配：boast about/of 夸耀"},{"chapter":20,"key":"20:46","id":46,"word":"tease","phonetic":"/tiːz/","pos":"v.","meaningCN":"取笑，嘲弄","tag":"高频","root":"","exampleEN":"The older students used to tease him about his small size, but he never minded.","exampleCN":"以前高年级的学生常拿他的小个子开玩笑，但他从来不在意。","extra":""},{"chapter":20,"key":"20:47","id":47,"word":"mock","phonetic":"/mɒk/","pos":"v.","meaningCN":"嘲笑，嘲弄 adj. 模拟的；假装的","tag":"高频","root":"","exampleEN":"They mocked his accent, not realising how much it hurt his feelings.","exampleCN":"他们嘲笑他的口音，没有意识到这有多伤他的感情。","extra":"搭配：a mock exam 模拟考试"},{"chapter":20,"key":"20:48","id":48,"word":"touch","phonetic":"/tʌtʃ/","pos":"v.","meaningCN":"触摸；触动 n. 触觉；接触","tag":"核心","root":"","exampleEN":"The story about the homeless dog deeply touched the hearts of the readers.","exampleCN":"关于那条流浪狗的故事深深触动了读者的心。","extra":"搭配：get in touch with 与……取得联系"},{"chapter":20,"key":"20:49","id":49,"word":"hug","phonetic":"/hʌɡ/","pos":"v./n.","meaningCN":"拥抱","tag":"核心","root":"","exampleEN":"She ran to her father and gave him a warm hug after not seeing him for a year.","exampleCN":"一年没见之后，她跑向父亲，给了他一个温暖的拥抱。","extra":""},{"chapter":20,"key":"20:50","id":50,"word":"tap","phonetic":"/tæp/","pos":"v.","meaningCN":"轻拍，轻叩；开发","tag":"核心","root":"","exampleEN":"He tapped me on the shoulder to get my attention during the lecture.","exampleCN":"课堂上他轻轻拍了拍我的肩膀，想引起我的注意。","extra":""},{"chapter":20,"key":"20:51","id":51,"word":"clap","phonetic":"/klæp/","pos":"v.","meaningCN":"拍手；轻拍 n. 鼓掌","tag":"核心","root":"","exampleEN":"The audience clapped enthusiastically after the wonderful performance.","exampleCN":"精彩的表演结束后，观众热烈地鼓掌。","extra":"搭配：clap hands 拍手"},{"chapter":20,"key":"20:52","id":52,"word":"applaud","phonetic":"/əˈplɔːd/","pos":"v.","meaningCN":"鼓掌；称赞，赞许","tag":"核心","root":"","exampleEN":"We all applaud the government's decision to invest more in clean energy.","exampleCN":"我们所有人都对政府加大清洁能源投资的决定表示赞许。","extra":""},{"chapter":20,"key":"20:53","id":53,"word":"kneel","phonetic":"/niːl/","pos":"v.","meaningCN":"跪，跪下","tag":"高频","root":"","exampleEN":"He knelt down to tie the little girl's shoelaces so she wouldn't trip.","exampleCN":"他跪下来给小女孩系好鞋带，以免她绊倒。","extra":""},{"chapter":20,"key":"20:54","id":54,"word":"catch","phonetic":"/kætʃ/","pos":"v.","meaningCN":"捉住；赶上；领会","tag":"核心","root":"","exampleEN":"I need to run to catch the bus; otherwise I'll be late for work.","exampleCN":"我得跑着去赶公交车，否则上班要迟到了。","extra":""},{"chapter":20,"key":"20:55","id":55,"word":"overtake","phonetic":"/ˌəʊvəˈteɪk/","pos":"v.","meaningCN":"追上，超过；（情感等）压倒","tag":"核心","root":"","exampleEN":"It is dangerous to overtake another car on a narrow, winding road.","exampleCN":"在狭窄蜿蜒的路上超车很危险。","extra":""},{"chapter":20,"key":"20:56","id":56,"word":"follow","phonetic":"/ˈfɒləʊ/","pos":"v.","meaningCN":"跟随；是……的必然结果；遵循","tag":"核心","root":"","exampleEN":"Please follow the safety instructions carefully while inside the factory.","exampleCN":"在工厂内请仔细遵守安全指示。","extra":"搭配：follow suit 跟着做"},{"chapter":20,"key":"20:57","id":57,"word":"grip","phonetic":"/ɡrɪp/","pos":"v.","meaningCN":"紧握，抓牢 n. 紧握；理解","tag":"高频","root":"","exampleEN":"She gripped the railing tightly as she walked down the icy steps.","exampleCN":"她走下结冰的台阶时紧紧抓住栏杆。","extra":"搭配：in the grip of 受……严重影响"},{"chapter":20,"key":"20:58","id":58,"word":"mess","phonetic":"/mes/","pos":"n.","meaningCN":"混乱，脏乱 v. 弄乱","tag":"核心","root":"","exampleEN":"The children left the playroom in a terrible mess before dinner.","exampleCN":"晚饭前孩子们把游戏室弄得乱七八糟。","extra":"messy adj. 凌乱的；搭配：mess up 弄乱"},{"chapter":20,"key":"20:59","id":59,"word":"twist","phonetic":"/twɪst/","pos":"v.","meaningCN":"拧，扭；使缠绕 n. 拧，扭动","tag":"核心","root":"","exampleEN":"She twisted the wet towel to squeeze out the water before hanging it up.","exampleCN":"她把湿毛巾拧干水，然后挂起来。","extra":""},{"chapter":20,"key":"20:60","id":60,"word":"scatter","phonetic":"/ˈskætə/","pos":"v.","meaningCN":"撒；（使）散开","tag":"核心","root":"","exampleEN":"The wind blew and scattered the dry leaves all over the garden.","exampleCN":"风一吹，干树叶散落得满花园都是。","extra":""},{"chapter":20,"key":"20:61","id":61,"word":"snatch","phonetic":"/snætʃ/","pos":"v.","meaningCN":"一把抓住，迅速夺取","tag":"高频","root":"","exampleEN":"A thief on a motorcycle snatched her handbag and rode away at top speed.","exampleCN":"一个骑摩托车的贼一把抢走她的手提包，飞快地逃走了。","extra":""},{"chapter":20,"key":"20:62","id":62,"word":"grab","phonetic":"/ɡræb/","pos":"v.","meaningCN":"抓住，攫取；（匆忙地）取","tag":"核心","root":"","exampleEN":"Before leaving, she grabbed a banana from the kitchen for a quick snack.","exampleCN":"出门前，她匆忙从厨房拿了一根香蕉当零食。","extra":""},{"chapter":20,"key":"20:63","id":63,"word":"grasp","phonetic":"/ɡrɑːsp/","pos":"v.","meaningCN":"抓牢，握紧；完全理解，全面领会","tag":"核心","root":"","exampleEN":"It took her a while to grasp the complex rules of chess.","exampleCN":"她花了一段时间才完全领会国际象棋复杂的规则。","extra":""},{"chapter":20,"key":"20:64","id":64,"word":"fold","phonetic":"/fəʊld/","pos":"v.","meaningCN":"折叠，对折","tag":"核心","root":"","exampleEN":"He folded the map carefully and put it back into his backpack.","exampleCN":"他把地图小心折好，放回背包里。","extra":"foldable adj. 可折叠的；unfold v. 展开"},{"chapter":20,"key":"20:65","id":65,"word":"fasten","phonetic":"/ˈfæsən/","pos":"v.","meaningCN":"扣牢，系牢，缚紧","tag":"核心","root":"","exampleEN":"Please fasten your seat belt before the car starts moving.","exampleCN":"在汽车开动前请系好你的安全带。","extra":""},{"chapter":20,"key":"20:66","id":66,"word":"loosen","phonetic":"/ˈluːsən/","pos":"v.","meaningCN":"解开，松开；放宽（限制等）","tag":"核心","root":"","exampleEN":"He loosened his tie after the long and tiring business meeting.","exampleCN":"那场漫长而累人的商务会议后，他松开了领带。","extra":""},{"chapter":20,"key":"20:67","id":67,"word":"smash","phonetic":"/smæʃ/","pos":"v.","meaningCN":"打碎；（使）猛烈撞击；（打球时）扣球","tag":"高频","root":"","exampleEN":"The angry man picked up the vase and smashed it against the wall.","exampleCN":"那个愤怒的男人拿起花瓶，把它朝墙上摔得粉碎。","extra":""},{"chapter":20,"key":"20:68","id":68,"word":"scratch","phonetic":"/skrætʃ/","pos":"v.","meaningCN":"擦破，刮坏；搔 n. 乱涂；划痕，擦伤","tag":"核心","root":"","exampleEN":"The kitten tried to scratch me, but its tiny claws did not hurt at all.","exampleCN":"那只小猫想抓我，但它细小的爪子一点也不疼。","extra":""},{"chapter":20,"key":"20:69","id":69,"word":"wipe","phonetic":"/waɪp/","pos":"v.","meaningCN":"擦，擦净","tag":"核心","root":"","exampleEN":"She wiped the table with a clean cloth before setting the dishes.","exampleCN":"她在摆放碗盘前用一块干净的布擦了擦桌子。","extra":"搭配：wipe away 擦掉"},{"chapter":20,"key":"20:70","id":70,"word":"scrape","phonetic":"/skreɪp/","pos":"v.","meaningCN":"刮掉；擦坏；勉强获得 n. 刮；擦伤","tag":"高频","root":"","exampleEN":"He had to scrape the ice off the car window on that freezing morning.","exampleCN":"在那个寒冷的早晨，他不得不刮掉车窗上的冰。","extra":""},{"chapter":20,"key":"20:71","id":71,"word":"polish","phonetic":"/ˈpɒlɪʃ/","pos":"v.","meaningCN":"擦光，擦亮；使完美，改进","tag":"高频","root":"","exampleEN":"She spent the weekend polishing her essay until every word was perfect.","exampleCN":"她花了整个周末润色她的论文，直到每个词都无可挑剔。","extra":""},{"chapter":20,"key":"20:72","id":72,"word":"peel","phonetic":"/piːl/","pos":"v.","meaningCN":"剥落；掉漆；脱皮","tag":"核心","root":"","exampleEN":"The paint on the old wooden windows is starting to peel off after years of rain.","exampleCN":"经过多年的风吹雨打，旧木窗上的油漆开始剥落了。","extra":""},{"chapter":20,"key":"20:73","id":73,"word":"split","phonetic":"/splɪt/","pos":"v.","meaningCN":"（使）开裂；（使）分裂；（使）分开","tag":"核心","root":"","exampleEN":"The log split in half when he hit it hard with the heavy axe.","exampleCN":"他用重斧猛劈，那根圆木裂成了两半。","extra":""},{"chapter":20,"key":"20:74","id":74,"word":"sway","phonetic":"/sweɪ/","pos":"v.","meaningCN":"（使）摇摆，（使）摆动，（使）摇晃","tag":"高频","root":"","exampleEN":"The tall trees swayed violently in the strong wind during the storm.","exampleCN":"暴风雨中，高大的树木在狂风中剧烈地摇晃。","extra":""},{"chapter":20,"key":"20:75","id":75,"word":"shake","phonetic":"/ʃeɪk/","pos":"v.","meaningCN":"摇动，（使）颤动 n. 摇动，颤动","tag":"核心","root":"","exampleEN":"She shook the bottle of juice well before opening it.","exampleCN":"她打开果汁瓶之前先好好摇了摇。","extra":"搭配：shake hands with 与……握手"},{"chapter":20,"key":"20:76","id":76,"word":"vibrate","phonetic":"/vaɪˈbreɪt/","pos":"v.","meaningCN":"（使）振动，（使）摇摆","tag":"高频","root":"","exampleEN":"The whole building began to vibrate as the heavy trucks rolled past outside.","exampleCN":"当重型卡车从外面驶过时，整座大楼开始振动起来。","extra":"vibration n. 振动"},{"chapter":20,"key":"20:77","id":77,"word":"whirl","phonetic":"/wɜːl/","pos":"v.","meaningCN":"（使）回旋 n. 回旋","tag":"低频","root":"","exampleEN":"The autumn leaves were picked up by the wind and whirled through the air.","exampleCN":"秋叶被风卷起，在空中回旋飞舞。","extra":""},{"chapter":20,"key":"20:78","id":78,"word":"rotate","phonetic":"/rəʊˈteɪt/","pos":"v.","meaningCN":"（使）旋转，（使）转动","tag":"核心","root":"","exampleEN":"The wheels of the bicycle rotate smoothly after I oiled the chain.","exampleCN":"我给链条上了油之后，自行车的轮子转得很顺畅。","extra":""},{"chapter":20,"key":"20:79","id":79,"word":"reel","phonetic":"/riːl/","pos":"v.","meaningCN":"眩晕，混乱","tag":"低频","root":"","exampleEN":"After the accident, his mind reeled and he couldn't remember what had happened.","exampleCN":"事故过后，他感到天旋地转，记不起发生了什么。","extra":""},{"chapter":20,"key":"20:80","id":80,"word":"shuffle","phonetic":"/ˈʃʌfəl/","pos":"v.","meaningCN":"洗（牌）；拖着脚走；搅乱……的次序 n. 洗牌","tag":"高频","root":"","exampleEN":"The old man shuffled slowly across the room with the help of a walking stick.","exampleCN":"老人拄着手杖，拖着脚缓缓穿过房间。","extra":"reshuffle n. 改组"},{"chapter":20,"key":"20:81","id":81,"word":"collide","phonetic":"/kəˈlaɪd/","pos":"v.","meaningCN":"碰撞；抵触","tag":"高频","root":"","exampleEN":"The two cars collided at the intersection because one driver ignored the red light.","exampleCN":"由于一名司机闯了红灯，两辆车在十字路口相撞了。","extra":"搭配：collide with 与……相撞"},{"chapter":20,"key":"20:82","id":82,"word":"contact","phonetic":"/ˈkɒntækt/","pos":"n./v.","meaningCN":"接触，联系","tag":"核心","root":"","exampleEN":"I have lost contact with most of my childhood friends over the years.","exampleCN":"这些年来，我已经与大多数儿时朋友失去了联系。","extra":"搭配：be in contact with 与……有联系"},{"chapter":20,"key":"20:83","id":83,"word":"connect","phonetic":"/kəˈnekt/","pos":"v.","meaningCN":"（使）连接；（使）接通（电源等）","tag":"核心","root":"","exampleEN":"This road connects the two villages, making travel between them much easier.","exampleCN":"这条路连接了两个村庄，使之间的往来方便了许多。","extra":"搭配：connect A to/with B"},{"chapter":20,"key":"20:84","id":84,"word":"combine","phonetic":"/kəmˈbaɪn/","pos":"v.","meaningCN":"（使）联合，（使）结合","tag":"核心","root":"","exampleEN":"If you combine red and blue paint, you will get a shade of purple.","exampleCN":"如果你把红色和蓝色颜料混合，就会得到一种紫色。","extra":"combination n. 联合"},{"chapter":20,"key":"20:85","id":85,"word":"bond","phonetic":"/bɒnd/","pos":"v.","meaningCN":"与……黏合（或连接） n. 黏合；（感情的）纽带","tag":"核心","root":"","exampleEN":"Sharing difficult experiences can help people bond much more quickly.","exampleCN":"共同经历困难可以让人与人之间更快地建立紧密的感情纽带。","extra":""},{"chapter":20,"key":"20:86","id":86,"word":"integrate","phonetic":"/ˈɪntɪɡreɪt/","pos":"v.","meaningCN":"（使）成为一体，（使）合并","tag":"核心","root":"","exampleEN":"The new students were quickly integrated into the school community.","exampleCN":"新生很快融入了学校社区。","extra":"integration n. 整合；搭配：integrate A into/with B"},{"chapter":20,"key":"20:87","id":87,"word":"wrap","phonetic":"/ræp/","pos":"v.","meaningCN":"裹，包；用……缠绕","tag":"核心","root":"","exampleEN":"She wrapped a warm scarf around her neck before stepping out into the cold wind.","exampleCN":"她走进寒风中之前，用一条暖和的围巾裹住了脖子。","extra":""},{"chapter":20,"key":"20:88","id":88,"word":"penetrate","phonetic":"/ˈpenɪtreɪt/","pos":"v.","meaningCN":"刺入，穿透；渗透；洞察","tag":"高频","root":"","exampleEN":"Sunlight could hardly penetrate the thick curtains in the old library.","exampleCN":"阳光几乎无法穿透老图书馆里那些厚厚的窗帘。","extra":""},{"chapter":20,"key":"20:89","id":89,"word":"pierce","phonetic":"/pɪəs/","pos":"v.","meaningCN":"刺穿，刺破，穿透；使心如刀割","tag":"高频","root":"","exampleEN":"A sharp cry pierced the silence of the night and woke everyone up.","exampleCN":"一声尖锐的喊叫划破了夜的寂静，把所有人都惊醒了。","extra":""},{"chapter":20,"key":"20:90","id":90,"word":"insert","phonetic":"v. /ɪnˈsɜːt/ n. /ˈɪnsɜːt/","pos":"v.","meaningCN":"插入，嵌入 n. 插入物","tag":"核心","root":"","exampleEN":"Insert your credit card into the machine and enter your password.","exampleCN":"把你的信用卡插入机器并输入密码。","extra":"搭配：insert A in/into B"},{"chapter":20,"key":"20:91","id":91,"word":"tilt","phonetic":"/tɪlt/","pos":"v.","meaningCN":"（使）倾斜，（使）歪斜","tag":"高频","root":"","exampleEN":"She tilted her head to the side, listening carefully to the soft music.","exampleCN":"她把头歪向一边，仔细聆听着柔和的音乐。","extra":"tile n. 瓦片"},{"chapter":20,"key":"20:92","id":92,"word":"tow","phonetic":"/təʊ/","pos":"v.","meaningCN":"拖，拉，牵引 n. 牵引","tag":"高频","root":"","exampleEN":"The broken-down truck was towed to the nearest repair shop.","exampleCN":"那辆报废的卡车被拖到了最近的修理厂。","extra":""},{"chapter":20,"key":"20:93","id":93,"word":"trail","phonetic":"/treɪl/","pos":"v.","meaningCN":"（使）拖在后面；跟踪 n. 踪迹","tag":"核心","root":"","exampleEN":"The children trailed behind their teacher through the busy museum.","exampleCN":"孩子们跟在老师后面，慢吞吞地穿过繁忙的博物馆。","extra":""},{"chapter":20,"key":"20:94","id":94,"word":"arrange","phonetic":"/əˈreɪndʒ/","pos":"v.","meaningCN":"安排，整理，使有条理","tag":"核心","root":"","exampleEN":"The travel agency arranged all the hotels and flights for our trip.","exampleCN":"旅行社为我们的旅行安排了所有的酒店和航班。","extra":"arrangement n. 安排"},{"chapter":20,"key":"20:95","id":95,"word":"manipulate","phonetic":"/məˈnɪpjʊleɪt/","pos":"v.","meaningCN":"（熟练地）操作；操纵","tag":"高频","root":"","exampleEN":"He can skillfully manipulate various photo editing software to create amazing images.","exampleCN":"他可以熟练操作多种照片编辑软件，创作出令人惊叹的图像。","extra":"manipulation n. 操作；操纵"},{"chapter":20,"key":"20:96","id":96,"word":"steer","phonetic":"/stɪə/","pos":"v.","meaningCN":"为（船）操舵，驾驶（船、车等）；操纵","tag":"核心","root":"","exampleEN":"She steered the car smoothly around the sharp bend in the road.","exampleCN":"她驾驶汽车平稳地绕过了路上的一个急弯。","extra":"steering n. 转向装置"},{"chapter":20,"key":"20:97","id":97,"word":"baptise","phonetic":"/bæpˈtaɪz/","pos":"v.","meaningCN":"给……施行洗礼（或浸礼）","tag":"低频","root":"","exampleEN":"The baby was baptised in the small village church surrounded by family and friends.","exampleCN":"婴儿在那座乡村小教堂里接受了洗礼，家人和朋友都围在身旁。","extra":"baptism n. 洗礼；也作 baptize"},{"chapter":20,"key":"20:98","id":98,"word":"bet","phonetic":"/bet/","pos":"v.","meaningCN":"下注，打赌；敢说 n. 打赌；赌注","tag":"核心","root":"","exampleEN":"I bet you can't finish that whole pizza by yourself in ten minutes.","exampleCN":"我敢说你没法在十分钟内自己一个人吃完整个比萨。","extra":"搭配：You bet! 当然！"},{"chapter":20,"key":"20:99","id":99,"word":"stake","phonetic":"/steɪk/","pos":"n.","meaningCN":"赌注；桩 v. 以……打赌","tag":"高频","root":"","exampleEN":"There is a lot at stake in this project, and we cannot afford any mistakes.","exampleCN":"这个项目事关重大，我们经不起任何差错。","extra":"搭配：at stake 有风险"},{"chapter":20,"key":"20:100","id":100,"word":"gamble","phonetic":"/ˈɡæmbəl/","pos":"v./n.","meaningCN":"赌博；冒险","tag":"高频","root":"","exampleEN":"He gambled all his savings on a single business deal and unfortunately lost everything.","exampleCN":"他把所有积蓄都押在一笔生意上，结果不幸血本无归。","extra":"gambler n. 赌徒；搭配：take a gamble on sth."},{"chapter":20,"key":"20:101","id":101,"word":"promise","phonetic":"/ˈprɒmɪs/","pos":"n.","meaningCN":"诺言 v. 承诺","tag":"核心","root":"","exampleEN":"You should not make a promise that you cannot keep.","exampleCN":"你不该许下自己无法遵守的诺言。","extra":"promising adj. 有前途的；搭配：break/keep a promise"},{"chapter":20,"key":"20:102","id":102,"word":"attract","phonetic":"/əˈtrækt/","pos":"v.","meaningCN":"吸引；引起","tag":"核心","root":"tract = 拉","exampleEN":"The new museum has attracted thousands of visitors since it opened last month.","exampleCN":"新博物馆自上个月开放以来已经吸引了成千上万的参观者。","extra":"attraction n. 吸引；搭配：attract sb.'s attention"},{"chapter":20,"key":"20:103","id":103,"word":"obsess","phonetic":"/əbˈses/","pos":"v.","meaningCN":"（使）痴迷，（使）心神不宁","tag":"高频","root":"","exampleEN":"She became completely obsessed with the idea of travelling to space one day.","exampleCN":"她变得一门心思全痴迷于有朝一日去太空旅行的念头。","extra":"搭配：be obsessed by/with 被……迷住"},{"chapter":20,"key":"20:104","id":104,"word":"mesmerise","phonetic":"/ˈmezməraɪz/","pos":"v.","meaningCN":"吸引，迷住","tag":"低频","root":"","exampleEN":"The children were mesmerised by the magician's incredible card tricks.","exampleCN":"孩子们被魔术师不可思议的纸牌戏法给迷住了。","extra":"也作 mesmerize"},{"chapter":20,"key":"20:105","id":105,"word":"nightmare","phonetic":"/ˈnaɪtmeə/","pos":"n.","meaningCN":"噩梦，梦魇","tag":"核心","root":"","exampleEN":"Traffic in the city centre during rush hour is an absolute nightmare.","exampleCN":"高峰时段市中心的交通简直就是一场噩梦。","extra":""},{"chapter":20,"key":"20:106","id":106,"word":"amaze","phonetic":"/əˈmeɪz/","pos":"v.","meaningCN":"使惊奇，使惊愣","tag":"核心","root":"","exampleEN":"The young pianist's performance amazed the audience, who gave her a standing ovation.","exampleCN":"那位年轻钢琴家的演奏令观众惊叹不已，他们纷纷站起来鼓掌。","extra":"maze n. 迷宫"},{"chapter":20,"key":"20:107","id":107,"word":"marvel","phonetic":"/ˈmɑːvəl/","pos":"v.","meaningCN":"感到惊讶，大为赞叹 n. 奇迹","tag":"高频","root":"","exampleEN":"We stood on the Great Wall and marvelled at the breathtaking view.","exampleCN":"我们站在长城上，对着那令人叹为观止的景色赞叹不已。","extra":"marvelous adj. 不可思议的"},{"chapter":20,"key":"20:108","id":108,"word":"astonish","phonetic":"/əˈstɒnɪʃ/","pos":"v.","meaningCN":"使惊讶","tag":"核心","root":"","exampleEN":"The news of their sudden engagement astonished even their closest friends.","exampleCN":"他们突然订婚的消息甚至让最亲密的朋友也大吃一惊。","extra":"astound v. 使大吃一惊"},{"chapter":20,"key":"20:109","id":109,"word":"involve","phonetic":"/ɪnˈvɒlv/","pos":"v.","meaningCN":"（使）参加；牵涉","tag":"核心","root":"","exampleEN":"Please don't involve me in your personal argument; I want to stay neutral.","exampleCN":"请不要把我卷入你们的私人争吵，我想保持中立。","extra":"搭配：be/get involved in sth. 参与某事"},{"chapter":20,"key":"20:110","id":110,"word":"annoy","phonetic":"/əˈnɔɪ/","pos":"v.","meaningCN":"使恼怒；打扰","tag":"核心","root":"","exampleEN":"The constant noise from the construction site really annoys the residents nearby.","exampleCN":"建筑工地持续不断的噪音真的令附近居民十分恼怒。","extra":"annoyance n. 恼怒"},{"chapter":20,"key":"20:111","id":111,"word":"upset","phonetic":"/ʌpˈset/","pos":"v.","meaningCN":"使心烦意乱，使生气；搅乱；打翻","tag":"核心","root":"","exampleEN":"She was deeply upset by the cruel remarks her colleague made about her work.","exampleCN":"同事对她工作的刻薄评论让她心情非常低落。","extra":""},{"chapter":20,"key":"20:112","id":112,"word":"bewilder","phonetic":"/bɪˈwɪldə/","pos":"v.","meaningCN":"使迷惑，使不知所措","tag":"高频","root":"","exampleEN":"The complicated course instructions bewildered the new students on their first day.","exampleCN":"复杂的课程说明让新生们在第一天感到不知所措。","extra":""},{"chapter":20,"key":"20:113","id":113,"word":"irony","phonetic":"/ˈaɪrəni/","pos":"n.","meaningCN":"反话；有讽刺意味的情形","tag":"高频","root":"","exampleEN":"The irony of the situation is that the fire station itself burned down last night.","exampleCN":"具有讽刺意味的是，消防站自己昨晚竟然被烧毁了。","extra":"ironic adj. 讽刺的"},{"chapter":20,"key":"20:114","id":114,"word":"indignity","phonetic":"/ɪnˈdɪɡnəti/","pos":"n.","meaningCN":"侮辱，轻蔑","tag":"低频","root":"","exampleEN":"Being forced to wait outside in the rain was an indignity he would not quickly forget.","exampleCN":"被迫在雨中等候是对他的一种侮辱，他不会很快忘记。","extra":""},{"chapter":20,"key":"20:115","id":115,"word":"contempt","phonetic":"/kənˈtempt/","pos":"n.","meaningCN":"轻视，藐视","tag":"高频","root":"","exampleEN":"He has nothing but contempt for people who are cruel to animals.","exampleCN":"他对虐待动物的人只有鄙视。","extra":"搭配：in contempt of 不把……放在眼里"},{"chapter":20,"key":"20:116","id":116,"word":"neglect","phonetic":"/nɪˈɡlekt/","pos":"v./n.","meaningCN":"忽视，忽略","tag":"核心","root":"","exampleEN":"He was so busy with work that he began to neglect his own health.","exampleCN":"他工作太忙了，以至于开始忽视自己的健康。","extra":"overlook v. 忽视；搭配：neglect of 忽视"},{"chapter":20,"key":"20:117","id":117,"word":"disregard","phonetic":"/ˌdɪsrɪˈɡɑːd/","pos":"v.","meaningCN":"不顾，漠视 n. 忽视，漠视","tag":"高频","root":"","exampleEN":"The driver was fined for completely disregarding the traffic signals.","exampleCN":"那名司机因完全无视交通信号而被罚款。","extra":"搭配：in disregard of 不顾"},{"chapter":20,"key":"20:118","id":118,"word":"ignorance","phonetic":"/ˈɪɡnərəns/","pos":"n.","meaningCN":"无知，愚昧","tag":"核心","root":"","exampleEN":"Prejudice is often the product of ignorance and fear.","exampleCN":"偏见往往是无知和恐惧的产物。","extra":"搭配：be in ignorance of 对……全然不知"},{"chapter":20,"key":"20:119","id":119,"word":"bias","phonetic":"/ˈbaɪəs/","pos":"v.","meaningCN":"使有偏见，使偏心 n. 偏见，偏心","tag":"核心","root":"","exampleEN":"The newspaper article showed a clear bias against the new political party.","exampleCN":"那篇报纸文章对新政党表现出了明显的偏见。","extra":"搭配：have a bias against 对……有偏见"},{"chapter":20,"key":"20:120","id":120,"word":"deviate","phonetic":"/ˈdiːvieɪt/","pos":"v.","meaningCN":"偏离，背离","tag":"高频","root":"","exampleEN":"We must not deviate from the original plan unless it is absolutely necessary.","exampleCN":"除非万不得已，我们绝不能偏离最初的计划。","extra":"deviation n. 偏离"},{"chapter":20,"key":"20:121","id":121,"word":"expel","phonetic":"/ɪkˈspel/","pos":"v.","meaningCN":"驱逐；开除；排出","tag":"高频","root":"","exampleEN":"The student was expelled from the school for repeatedly breaking the rules.","exampleCN":"那个学生因屡次违反校规被学校开除了。","extra":""},{"chapter":20,"key":"20:122","id":122,"word":"flee","phonetic":"/fliː/","pos":"v.","meaningCN":"逃避，逃离","tag":"核心","root":"","exampleEN":"When the fire alarm went off, everyone fled the building quickly and safely.","exampleCN":"火警响起时，每个人都迅速而安全地逃离了大楼。","extra":""},{"chapter":20,"key":"20:123","id":123,"word":"bully","phonetic":"/ˈbʊli/","pos":"v.","meaningCN":"恐吓，欺凌 n. 恃强凌弱者","tag":"核心","root":"","exampleEN":"Schools should take strong measures to prevent older students from bullying the younger ones.","exampleCN":"学校应采取有力措施防止高年级学生欺凌低年级同学。","extra":""},{"chapter":20,"key":"20:124","id":124,"word":"panic","phonetic":"/ˈpænɪk/","pos":"n.","meaningCN":"惊恐，惊慌 v.（使）惊恐，（使）惊慌","tag":"核心","root":"希腊神话中的潘（Pan）","exampleEN":"She felt a moment of panic when she couldn't find her passport in her bag.","exampleCN":"当她在包里找不到护照时，她感到一阵惊慌。","extra":""},{"chapter":20,"key":"20:125","id":125,"word":"terrify","phonetic":"/ˈterɪfaɪ/","pos":"v.","meaningCN":"使恐惧，使非常害怕","tag":"核心","root":"","exampleEN":"The idea of walking alone through the dark forest terrified the young boy.","exampleCN":"要独自一人穿过那片漆黑的森林，这个念头让小男孩非常害怕。","extra":"terrifying adj. 可怕的"},{"chapter":20,"key":"20:126","id":126,"word":"revenge","phonetic":"/rɪˈvendʒ/","pos":"n.","meaningCN":"报仇，复仇 v. 向……报仇","tag":"高频","root":"","exampleEN":"He swore to take revenge on the people who had ruined his family business.","exampleCN":"他发誓要向那些毁掉他家族生意的人报仇。","extra":"搭配：revenge oneself on sb. 向某人报仇"},{"chapter":20,"key":"20:127","id":127,"word":"kidnap","phonetic":"/ˈkɪdnæp/","pos":"v.","meaningCN":"绑架，劫持","tag":"高频","root":"","exampleEN":"The wealthy businessman was kidnapped and held for three days before being rescued.","exampleCN":"那位富商被绑架并关押了三天才获救。","extra":""},{"chapter":20,"key":"20:128","id":128,"word":"hijack","phonetic":"/ˈhaɪdʒæk/","pos":"v.","meaningCN":"劫持（飞机或其他交通工具）","tag":"高频","root":"","exampleEN":"The criminals planned to hijack a truck loaded with valuable goods.","exampleCN":"犯罪分子计划劫持一辆装满贵重货物的卡车。","extra":""},{"chapter":20,"key":"20:129","id":129,"word":"smuggle","phonetic":"/ˈsmʌɡl/","pos":"v.","meaningCN":"走私，偷运","tag":"高频","root":"","exampleEN":"He was arrested at the airport for trying to smuggle rare animals into the country.","exampleCN":"他因试图向国内走私珍稀动物而在机场被捕。","extra":"smuggler n. 走私者"},{"chapter":20,"key":"20:130","id":130,"word":"convict","phonetic":"v. /kənˈvɪkt/ n. /ˈkɒnvɪkt/","pos":"v.","meaningCN":"定罪，宣判……有罪 n. 已决犯","tag":"高频","root":"vict/vinc = 征服","exampleEN":"After a long trial, he was finally convicted of the crime and sent to prison.","exampleCN":"经过漫长的审判，他终于被判有罪并送入监狱。","extra":""},{"chapter":20,"key":"20:131","id":131,"word":"strangle","phonetic":"/ˈstræŋɡəl/","pos":"v.","meaningCN":"扼杀，压制；勒死，扼死","tag":"低频","root":"","exampleEN":"Too many regulations may strangle small businesses and prevent them from growing.","exampleCN":"过多的规章制度可能会扼杀小企业，阻止它们发展。","extra":""},{"chapter":20,"key":"20:132","id":132,"word":"massacre","phonetic":"/ˈmæsəkə/","pos":"n./v.","meaningCN":"残杀，屠杀","tag":"高频","root":"","exampleEN":"The history book described the terrible massacre that took place during the war.","exampleCN":"历史书描述了那场战争中发生的可怕大屠杀。","extra":""},{"chapter":20,"key":"20:133","id":133,"word":"decimation","phonetic":"/ˌdesɪˈmeɪʃən/","pos":"n.","meaningCN":"大批杀死，大量毁灭；大大削弱","tag":"低频","root":"","exampleEN":"The disease caused a decimation of the local livestock, ruining many farmers.","exampleCN":"这场疫病导致当地牲畜大批死亡，毁了许多农民的生计。","extra":""},{"chapter":20,"key":"20:134","id":134,"word":"intervene","phonetic":"/ˌɪntəˈviːn/","pos":"v.","meaningCN":"插话；干扰；干涉","tag":"高频","root":"","exampleEN":"The teacher had to intervene when the argument between the two students got out of control.","exampleCN":"两名学生的争论失去控制时，老师不得不出面干预。","extra":""},{"chapter":20,"key":"20:135","id":135,"word":"impede","phonetic":"/ɪmˈpiːd/","pos":"v.","meaningCN":"妨碍，阻止","tag":"高频","root":"ped = 足","exampleEN":"Heavy snowfall impeded the rescue team's progress through the mountains.","exampleCN":"大雪阻碍了救援队在山中前进的进度。","extra":"impair v. 削弱；妨碍"},{"chapter":20,"key":"20:136","id":136,"word":"allure","phonetic":"/əˈljʊə/","pos":"v.","meaningCN":"吸引，引诱","tag":"低频","root":"","exampleEN":"The bright lights of the big city allure many young people from rural villages.","exampleCN":"大城市的霓虹灯火吸引了许多来自农村的年轻人。","extra":"lure v. 引诱"},{"chapter":20,"key":"20:137","id":137,"word":"bait","phonetic":"/beɪt/","pos":"v.","meaningCN":"使上当发火 n. 诱饵；诱惑物","tag":"低频","root":"","exampleEN":"They used a piece of cheese as bait to catch the mouse.","exampleCN":"他们用一小块奶酪作诱饵来捉老鼠。","extra":""},{"chapter":20,"key":"20:138","id":138,"word":"induce","phonetic":"/ɪnˈdjuːs/","pos":"v.","meaningCN":"引诱，劝说","tag":"高频","root":"","exampleEN":"Nothing could induce him to betray his close friend's secret.","exampleCN":"什么都不能引诱他出卖密友的秘密。","extra":"inducement n. 引诱；搭配：induce sb. to do sth."},{"chapter":20,"key":"20:139","id":139,"word":"tempt","phonetic":"/tempt/","pos":"v.","meaningCN":"引诱，诱惑；怂恿","tag":"核心","root":"","exampleEN":"The smell of freshly baked bread tempted her to go into the bakery.","exampleCN":"新鲜出炉面包的香味引诱她走进了面包店。","extra":"temptation n. 诱惑；搭配：resist temptation 抵制诱惑"},{"chapter":20,"key":"20:140","id":140,"word":"designate","phonetic":"/ˈdezɪɡneɪt/","pos":"v.","meaningCN":"指明；选派，指派","tag":"高频","root":"","exampleEN":"The manager designated John to be in charge of the weekly team meeting.","exampleCN":"经理指派约翰负责每周的团队会议。","extra":"appoint v. 指派"},{"chapter":20,"key":"20:141","id":141,"word":"assign","phonetic":"/əˈsaɪn/","pos":"v.","meaningCN":"布置；分配；指定；确定","tag":"核心","root":"","exampleEN":"The professor assigned a difficult essay to the students over the weekend.","exampleCN":"教授在周末给学生布置了一篇很难的论文。","extra":"搭配：assign sth. to sb."},{"chapter":20,"key":"20:142","id":142,"word":"distribute","phonetic":"/dɪˈstrɪbjuːt/","pos":"v.","meaningCN":"分发，分配","tag":"核心","root":"","exampleEN":"Volunteers helped to distribute food and water to the families after the flood.","exampleCN":"洪水过后，志愿者帮助将食物和水分发给各家各户。","extra":"distribution n. 分发；搭配：distribute sth. among"},{"chapter":20,"key":"20:143","id":143,"word":"despatch","phonetic":"/dɪˈspætʃ/","pos":"v.","meaningCN":"派遣，调派；迅速处理","tag":"低频","root":"","exampleEN":"The headquarters despatched a team of experts to handle the emergency.","exampleCN":"总部派遣了一个专家组去处理那起紧急事件。","extra":"也作 dispatch"},{"chapter":20,"key":"20:144","id":144,"word":"detach","phonetic":"/dɪˈtætʃ/","pos":"v.","meaningCN":"（使）分开，（使）分离；派遣","tag":"高频","root":"","exampleEN":"You can detach the hood from the jacket when the weather gets warmer.","exampleCN":"天气转暖时，你可以把兜帽从夹克上拆下来。","extra":""},{"chapter":20,"key":"20:145","id":145,"word":"undo","phonetic":"/ʌnˈduː/","pos":"v.","meaningCN":"解开，打开；取消","tag":"核心","root":"","exampleEN":"He tried to undo the complicated knot in the rope, but it was too tight.","exampleCN":"他努力去解绳子上那个复杂的结，但结太紧了。","extra":""},{"chapter":20,"key":"20:146","id":146,"word":"disguise","phonetic":"/dɪsˈɡaɪz/","pos":"v.","meaningCN":"掩饰；假扮，伪装 n. 假扮；伪装物","tag":"高频","root":"","exampleEN":"She disguised her voice on the phone to sound like an old woman.","exampleCN":"她在电话里伪装了自己的声音，让自己听上去像个老太太。","extra":"搭配：in disguise 伪装的"},{"chapter":20,"key":"20:147","id":147,"word":"conceal","phonetic":"/kənˈsiːl/","pos":"v.","meaningCN":"隐藏，掩盖","tag":"高频","root":"","exampleEN":"He tried to conceal his disappointment when he didn't get the job.","exampleCN":"当没有得到那份工作时，他努力掩饰自己的失望。","extra":""},{"chapter":20,"key":"20:148","id":148,"word":"refuse","phonetic":"/rɪˈfjuːz/","pos":"v.","meaningCN":"拒绝；回绝","tag":"核心","root":"fuse = 倾倒","exampleEN":"She flatly refused to lend him any more money after he failed to repay her.","exampleCN":"在他上次没有还钱之后，她断然拒绝再借给他任何钱。","extra":"refusal n. 拒绝"},{"chapter":20,"key":"20:149","id":149,"word":"exclude","phonetic":"/ɪkˈskluːd/","pos":"v.","meaningCN":"把……排除在外；拒绝","tag":"核心","root":"clud/clus = 关闭","exampleEN":"The price of the holiday excludes the cost of travel insurance.","exampleCN":"度假的价格不含旅行保险费。","extra":"exclusive adj. 独有的"},{"chapter":20,"key":"20:150","id":150,"word":"reverse","phonetic":"/rɪˈvɜːs/","pos":"v.","meaningCN":"颠倒，彻底改变；撤销 n. 相反的情况；反面 adj. 相反的","tag":"核心","root":"","exampleEN":"The president's new decision completely reversed the previous policy.","exampleCN":"总统的新决定完全颠覆了之前的政策。","extra":"reversal n. 颠倒"},{"chapter":20,"key":"20:151","id":151,"word":"assure","phonetic":"/əˈʃʊə/","pos":"v.","meaningCN":"向……保证；保证；保险","tag":"核心","root":"","exampleEN":"I can assure you that the product will be delivered before Friday.","exampleCN":"我可以向你保证，产品一定在星期五之前送到。","extra":"assurance n. 保证"},{"chapter":20,"key":"20:152","id":152,"word":"undertake","phonetic":"/ˌʌndəˈteɪk/","pos":"v.","meaningCN":"承担；许诺，保证","tag":"核心","root":"","exampleEN":"The construction company undertook to complete the bridge within two years.","exampleCN":"那家建筑公司承诺在两年内建成那座桥。","extra":""},{"chapter":20,"key":"20:153","id":153,"word":"stipulate","phonetic":"/ˈstɪpjʊleɪt/","pos":"v.","meaningCN":"规定，明确要求；保证","tag":"低频","root":"","exampleEN":"The contract stipulates that the rent must be paid by the fifth of each month.","exampleCN":"合同规定，房租必须在每月5号之前支付。","extra":"stipulation n. 规定"},{"chapter":20,"key":"20:154","id":154,"word":"convince","phonetic":"/kənˈvɪns/","pos":"v.","meaningCN":"使确信，使信服；说服","tag":"核心","root":"","exampleEN":"It took a long time to convince her parents that studying art was a good choice.","exampleCN":"花了很长时间才说服她父母相信学艺术是个好选择。","extra":"convincing adj. 令人信服的；搭配：convince sb. of sth."},{"chapter":20,"key":"20:155","id":155,"word":"reassure","phonetic":"/ˌriːəˈʃʊə/","pos":"v.","meaningCN":"使安心，使放心","tag":"高频","root":"","exampleEN":"The doctor reassured the patient that the operation was very simple and safe.","exampleCN":"医生安慰病人说手术非常简单、安全。","extra":""},{"chapter":20,"key":"20:156","id":156,"word":"wish","phonetic":"/wɪʃ/","pos":"v.","meaningCN":"想要（某事发生） n. 希望","tag":"核心","root":"","exampleEN":"I wish you all the best in your future studies and career.","exampleCN":"我祝你在未来的学习和事业中一切顺利。","extra":"搭配：make a wish 许愿"},{"chapter":20,"key":"20:157","id":157,"word":"aspire","phonetic":"/əˈspaɪə/","pos":"v.","meaningCN":"有志于，渴望","tag":"高频","root":"spir = 呼吸","exampleEN":"Many young writers aspire to publish their first novel before the age of thirty.","exampleCN":"许多年轻作家渴望在30岁之前出版自己的第一部小说。","extra":"搭配：aspire to do sth."},{"chapter":20,"key":"20:158","id":158,"word":"desire","phonetic":"/dɪˈzaɪə/","pos":"n.","meaningCN":"愿望，欲望 v. 渴望，期望","tag":"核心","root":"","exampleEN":"His desire to learn foreign languages led him to travel to many different countries.","exampleCN":"他学习外语的渴望促使他去了许多不同的国家旅行。","extra":""},{"chapter":20,"key":"20:159","id":159,"word":"yearn","phonetic":"/jɜːn/","pos":"v.","meaningCN":"渴望，向往","tag":"高频","root":"","exampleEN":"After months of living abroad, she began to yearn for her mother's home cooking.","exampleCN":"在国外生活了几个月后，她开始向往母亲做的家常菜。","extra":"搭配：yearn for 渴望"},{"chapter":20,"key":"20:160","id":160,"word":"invoke","phonetic":"/ɪnˈvəʊk/","pos":"v.","meaningCN":"唤起（感情等）；向……祈求帮助；恳求","tag":"低频","root":"","exampleEN":"The speaker invoked the memory of the great leader to inspire the crowd.","exampleCN":"演讲者唤起人们对于那位伟大领袖的回忆，以鼓舞人群。","extra":""},{"chapter":20,"key":"20:161","id":161,"word":"itch","phonetic":"/ɪtʃ/","pos":"v.","meaningCN":"发痒；渴望 n. 痒；渴望","tag":"高频","root":"","exampleEN":"He has been itching to try out his new mountain bike since he bought it.","exampleCN":"自买回来起，他就一直心痒难耐地想试试他的新山地车。","extra":"搭配：itch for 渴望"},{"chapter":20,"key":"20:162","id":162,"word":"attempt","phonetic":"/əˈtempt/","pos":"v.","meaningCN":"尝试，试图 n. 尝试，企图","tag":"核心","root":"","exampleEN":"He made no attempt to hide his anger when he saw the mess in the kitchen.","exampleCN":"当他看到厨房一片狼藉时，他丝毫不试图掩饰自己的怒气。","extra":"搭配：attempt to do sth."},{"chapter":20,"key":"20:163","id":163,"word":"strive","phonetic":"/straɪv/","pos":"v.","meaningCN":"努力，奋斗","tag":"核心","root":"","exampleEN":"We must continue to strive for a more equal and peaceful world.","exampleCN":"我们必须继续为一个更平等、更和平的世界而奋斗。","extra":"搭配：strive after/for 为……奋斗"},{"chapter":20,"key":"20:164","id":164,"word":"effort","phonetic":"/ˈefət/","pos":"n.","meaningCN":"努力；努力的成果","tag":"核心","root":"","exampleEN":"Your effort and determination are what really led to your success.","exampleCN":"你的努力和决心才是真正导致你成功的原因。","extra":"搭配：make great efforts to do sth."},{"chapter":20,"key":"20:165","id":165,"word":"fulfil","phonetic":"/fʊlˈfɪl/","pos":"v.","meaningCN":"履行，实现；完成；满足","tag":"核心","root":"","exampleEN":"He worked extremely hard to fulfil his dream of becoming a professional musician.","exampleCN":"他极其努力地工作，以实现成为一名职业音乐家的梦想。","extra":"也作 fulfill"},{"chapter":20,"key":"20:166","id":166,"word":"range","phonetic":"/reɪndʒ/","pos":"v.","meaningCN":"（在一定幅度内）变动","tag":"核心","root":"","exampleEN":"Ticket prices range from 30 to 150 dollars, depending on the seat location.","exampleCN":"票价根据座位位置从30美元到150美元不等。","extra":"ranger n. 护林员"},{"chapter":20,"key":"20:167","id":167,"word":"sort","phonetic":"/sɔːt/","pos":"n.","meaningCN":"种类，类别 v. 把……分类","tag":"核心","root":"","exampleEN":"What sort of music do you usually listen to when you are studying?","exampleCN":"你学习时通常听哪种音乐？","extra":"搭配：sort of 有几分"},{"chapter":20,"key":"20:168","id":168,"word":"loom","phonetic":"/luːm/","pos":"v.","meaningCN":"（庞然大物或形状模糊之物）隐现；逼近 n. 织布机","tag":"高频","root":"","exampleEN":"A dark shape loomed out of the thick fog and turned out to be a large tree.","exampleCN":"一个黑影在浓雾中隐约出现，原来是一棵大树。","extra":""},{"chapter":20,"key":"20:169","id":169,"word":"launch","phonetic":"/lɔːntʃ/","pos":"v.","meaningCN":"发射；发布，推出；发起（运动等）","tag":"核心","root":"","exampleEN":"The technology company is planning to launch its latest smartphone next month.","exampleCN":"那家科技公司计划下个月发布其最新款的智能手机。","extra":""},{"chapter":20,"key":"20:170","id":170,"word":"commence","phonetic":"/kəˈmens/","pos":"v.","meaningCN":"开始，着手","tag":"高频","root":"","exampleEN":"The graduation ceremony will commence at nine o'clock sharp in the main hall.","exampleCN":"毕业典礼将于九点整在主大厅开始。","extra":"commencement n. 开始"},{"chapter":20,"key":"20:171","id":171,"word":"dispose","phonetic":"/dɪˈspəʊz/","pos":"v.","meaningCN":"布置，安排","tag":"高频","root":"pos = 放","exampleEN":"We need to dispose of these old newspapers and magazines properly.","exampleCN":"我们需要把这些旧报纸和杂志妥善处理掉。","extra":"disposal n. 处理；搭配：dispose of sth. 处理某物"},{"chapter":20,"key":"20:172","id":172,"word":"exploit","phonetic":"/ɪkˈsplɔɪt/","pos":"v.","meaningCN":"开发，开采，开拓","tag":"核心","root":"","exampleEN":"The company plans to exploit the vast natural resources in the northern region.","exampleCN":"该公司计划开发北部地区丰富的自然资源。","extra":"exploitation n. 开发"},{"chapter":20,"key":"20:173","id":173,"word":"conduct","phonetic":"v. /kənˈdʌkt/ n. /ˈkɒndʌkt/","pos":"v.","meaningCN":"进行，实施 n. 举止，行为","tag":"核心","root":"","exampleEN":"The scientists conducted a series of experiments to test the new medicine.","exampleCN":"科学家们进行了一系列实验来测试这种新药。","extra":"conductive adj. 有传导性的"},{"chapter":20,"key":"20:174","id":174,"word":"explore","phonetic":"/ɪkˈsplɔː/","pos":"v.","meaningCN":"勘查，考察；探讨","tag":"核心","root":"","exampleEN":"We spent the afternoon exploring the narrow streets of the ancient town.","exampleCN":"我们整个下午都在探索那座古镇狭窄的街道。","extra":"exploration n. 勘探"},{"chapter":20,"key":"20:175","id":175,"word":"omit","phonetic":"/əʊˈmɪt/","pos":"v.","meaningCN":"遗漏；省略；删去","tag":"高频","root":"","exampleEN":"Be careful not to omit any important details when you write the report.","exampleCN":"写报告时小心别遗漏任何重要细节。","extra":"omission n. 遗漏"},{"chapter":20,"key":"20:176","id":176,"word":"exert","phonetic":"/ɪɡˈzɜːt/","pos":"v.","meaningCN":"运用，行使；施加","tag":"高频","root":"","exampleEN":"Parents often exert a strong influence on their children's eating habits.","exampleCN":"父母常常对子女的饮食习惯施加很强的影响。","extra":"搭配：exert an influence on 对……施加影响"},{"chapter":20,"key":"20:177","id":177,"word":"delete","phonetic":"/dɪˈliːt/","pos":"v.","meaningCN":"删除，删掉","tag":"核心","root":"","exampleEN":"I accidentally deleted an important file and had to ask IT to restore it.","exampleCN":"我不小心删除了一个重要文件，只得请信息技术部门帮忙恢复。","extra":"搭配：delete sth. from 从……中删去"},{"chapter":20,"key":"20:178","id":178,"word":"cancel","phonetic":"/ˈkænsəl/","pos":"v.","meaningCN":"取消；废除","tag":"核心","root":"","exampleEN":"All flights were cancelled because of the heavy snowstorm approaching the city.","exampleCN":"由于特大暴风雪逼近，所有航班都被取消了。","extra":"搭配：cancel an appointment"},{"chapter":20,"key":"20:179","id":179,"word":"tackle","phonetic":"/ˈtækəl/","pos":"v.","meaningCN":"处理，应对，解决 n. 用具，器材","tag":"核心","root":"","exampleEN":"The new government must tackle the growing problem of air pollution immediately.","exampleCN":"新政府必须立即着手解决日益严重的空气污染问题。","extra":"搭配：tackle the problem"},{"chapter":20,"key":"20:180","id":180,"word":"cope","phonetic":"/kəʊp/","pos":"v.","meaningCN":"应付，处理","tag":"核心","root":"","exampleEN":"She is learning how to cope with stress through exercise and meditation.","exampleCN":"她正在学习如何通过锻炼和冥想来应对压力。","extra":"搭配：cope with 应付"},{"chapter":20,"key":"20:181","id":181,"word":"clear","phonetic":"/klɪə/","pos":"adj.","meaningCN":"清晰的；明显的 v. 清除","tag":"核心","root":"","exampleEN":"After the storm, the workers worked hard to clear the roads of fallen trees.","exampleCN":"暴风雨过后，工人们努力清除道路上的倒树。","extra":"clearly adv.；搭配：clear up 清理"},{"chapter":20,"key":"20:182","id":182,"word":"erase","phonetic":"/ɪˈreɪz/","pos":"v.","meaningCN":"清除；抹去","tag":"高频","root":"","exampleEN":"She tried to erase the painful memory from her mind, but it wasn't easy.","exampleCN":"她试图从脑海中抹去那段痛苦的记忆，但这并不容易。","extra":""},{"chapter":20,"key":"20:183","id":183,"word":"rescue","phonetic":"/ˈreskjuː/","pos":"v./n.","meaningCN":"营救，救援","tag":"核心","root":"","exampleEN":"The coast guard rescued the sailors from the sinking ship just in time.","exampleCN":"海岸警卫队及时把水手们从正在下沉的船上救了出来。","extra":""},{"chapter":20,"key":"20:184","id":184,"word":"resort","phonetic":"/rɪˈzɔːt/","pos":"v.","meaningCN":"求助于，采取，诉诸 n.（度假）胜地","tag":"高频","root":"","exampleEN":"We should only resort to legal action if all other methods have failed.","exampleCN":"我们只有在所有其他方法都失败后才应诉诸法律手段。","extra":""},{"chapter":20,"key":"20:185","id":185,"word":"recover","phonetic":"/rɪˈkʌvə/","pos":"v.","meaningCN":"重新拿回；恢复健康；（从不愉快的经历中）复原","tag":"核心","root":"","exampleEN":"It took her several months to fully recover her strength after the illness.","exampleCN":"她病后花了好几个月才完全恢复了体力。","extra":"recovery n. 恢复"},{"chapter":20,"key":"20:186","id":186,"word":"restore","phonetic":"/rɪˈstɔː/","pos":"v.","meaningCN":"恢复；归还；修复","tag":"核心","root":"","exampleEN":"The old temple was carefully restored to its original beauty by skilled workers.","exampleCN":"那座古庙被能工巧匠小心翼翼地修复回了原有的美丽面貌。","extra":""},{"chapter":20,"key":"20:187","id":187,"word":"rectify","phonetic":"/ˈrektɪfaɪ/","pos":"v.","meaningCN":"纠正，矫正，改正","tag":"高频","root":"","exampleEN":"The company promised to rectify the mistake in the customer's bill immediately.","exampleCN":"公司承诺立即纠正客户账单中的错误。","extra":"correct v. 改正"},{"chapter":20,"key":"20:188","id":188,"word":"redeem","phonetic":"/rɪˈdiːm/","pos":"v.","meaningCN":"赎回；挽回，补偿；兑现","tag":"低频","root":"","exampleEN":"He tried to redeem himself by working extra hard on the next project.","exampleCN":"他试图通过在下一个项目上格外卖力来挽回自己的声誉。","extra":"搭配：redeem one's promise"},{"chapter":20,"key":"20:189","id":189,"word":"offset","phonetic":"/ˈɒfset/","pos":"v./n.","meaningCN":"补偿；抵消","tag":"高频","root":"","exampleEN":"The increased cost of materials was offset by a reduction in labour expenses.","exampleCN":"材料成本的增加被人工费用的减少抵消了。","extra":"搭配：offset sth. by (doing) sth."},{"chapter":20,"key":"20:190","id":190,"word":"replenish","phonetic":"/rɪˈplenɪʃ/","pos":"v.","meaningCN":"重新装满，补充","tag":"低频","root":"plen = 满","exampleEN":"After the long workout, you need to drink water to replenish the lost fluids.","exampleCN":"长时间锻炼之后，你需要喝水来补充流失的水分。","extra":""},{"chapter":20,"key":"20:191","id":191,"word":"obtain","phonetic":"/əbˈteɪn/","pos":"v.","meaningCN":"获得，得到","tag":"核心","root":"","exampleEN":"You need to obtain permission from the manager before taking any photos inside.","exampleCN":"你在里面拍照之前需要先得到经理的许可。","extra":""},{"chapter":20,"key":"20:192","id":192,"word":"gain","phonetic":"/ɡeɪn/","pos":"v.","meaningCN":"获得；增加 n. 增加；改进","tag":"核心","root":"","exampleEN":"Through this volunteering experience, he gained a deeper understanding of social issues.","exampleCN":"通过这次志愿服务经历，他对社会问题有了更深刻的理解。","extra":""},{"chapter":20,"key":"20:193","id":193,"word":"supply","phonetic":"/səˈplaɪ/","pos":"v.","meaningCN":"供给，供应，提供 n. 供应量；[supplies] 补给品","tag":"核心","root":"","exampleEN":"The Red Cross supplied blankets and drinking water to the earthquake victims.","exampleCN":"红十字会向地震灾民提供了毯子和饮用水。","extra":"搭配：in short supply 短缺"},{"chapter":20,"key":"20:194","id":194,"word":"offer","phonetic":"/ˈɒfə/","pos":"n.","meaningCN":"给予（物）；提议 v. 提供；出（价）","tag":"核心","root":"","exampleEN":"She decided to accept the job offer after thinking about it very carefully.","exampleCN":"她经过仔细考虑后决定接受这份工作。","extra":""},{"chapter":20,"key":"20:195","id":195,"word":"render","phonetic":"/ˈrendə/","pos":"v.","meaningCN":"给予，提供；翻译","tag":"高频","root":"","exampleEN":"The heavy fall rendered him unable to walk for several weeks.","exampleCN":"那次严重摔伤使他好几个星期都不能走路。","extra":""},{"chapter":20,"key":"20:196","id":196,"word":"enlarge","phonetic":"/ɪnˈlɑːdʒ/","pos":"v.","meaningCN":"扩大，扩展；放大（照片或文件）","tag":"核心","root":"","exampleEN":"Can you enlarge this photo so I can see the details more clearly?","exampleCN":"你能把这张照片放大一些，让我看得更清楚吗？","extra":""},{"chapter":20,"key":"20:197","id":197,"word":"augment","phonetic":"/ɔːɡˈment/","pos":"v.","meaningCN":"扩大，增加，加强，提高","tag":"低频","root":"","exampleEN":"He took on a second job to augment his income and support his family.","exampleCN":"他找了第二份工作来增加收入，以供养家庭。","extra":"augmentation n. 扩大"},{"chapter":20,"key":"20:198","id":198,"word":"magnify","phonetic":"/ˈmæɡnɪfaɪ/","pos":"v.","meaningCN":"放大；夸大","tag":"高频","root":"magn/maj/max = 大","exampleEN":"A microscope is used to magnify objects that are too small to see with the naked eye.","exampleCN":"显微镜用于放大那些肉眼无法看清的微小物体。","extra":""},{"chapter":20,"key":"20:199","id":199,"word":"amplify","phonetic":"/ˈæmplɪfaɪ/","pos":"v.","meaningCN":"增强；扩大（声音）；充实（陈述等）","tag":"高频","root":"","exampleEN":"The microphone helped to amplify the speaker's voice so everyone could hear.","exampleCN":"麦克风帮助放大了演讲者的声音，使每个人都能听到。","extra":"amplifier n. 扩音器"},{"chapter":20,"key":"20:200","id":200,"word":"exaggerate","phonetic":"/ɪɡˈzædʒəreɪt/","pos":"v.","meaningCN":"夸张，夸大","tag":"核心","root":"","exampleEN":"He tends to exaggerate the difficulties he faces, making them sound worse than they are.","exampleCN":"他往往夸大他所面临的困难，把它们说得比实际情况更糟。","extra":""},{"chapter":20,"key":"20:201","id":201,"word":"prolong","phonetic":"/prəˈlɒŋ/","pos":"v.","meaningCN":"延长","tag":"高频","root":"","exampleEN":"They decided to prolong their stay in Paris by another three days.","exampleCN":"他们决定把在巴黎停留的时间再延长三天。","extra":""},{"chapter":20,"key":"20:202","id":202,"word":"uphold","phonetic":"/ʌpˈhəʊld/","pos":"v.","meaningCN":"支持，维护；维持","tag":"高频","root":"","exampleEN":"The judge has a duty to uphold the law and treat every case fairly.","exampleCN":"法官有责任维护法律并公正地审理每一个案件。","extra":"搭配：uphold the law 维护法律"},{"chapter":20,"key":"20:203","id":203,"word":"backup","phonetic":"/ˈbækʌp/","pos":"n.","meaningCN":"后援，支持；（文件等的）备份 adj. 备用的","tag":"核心","root":"","exampleEN":"Always keep a backup of your important documents on a separate hard drive.","exampleCN":"重要文件一定要在另一块硬盘上留一份备份。","extra":""},{"chapter":20,"key":"20:204","id":204,"word":"propel","phonetic":"/prəˈpel/","pos":"v.","meaningCN":"推动，驱使；推进","tag":"高频","root":"","exampleEN":"The strong wind propelled the little sailing boat swiftly across the lake.","exampleCN":"大风推动那只小帆船飞速地掠过湖面。","extra":"propeller n. 螺旋桨"},{"chapter":20,"key":"20:205","id":205,"word":"update","phonetic":"/ʌpˈdeɪt/","pos":"v.","meaningCN":"更新；使现代化","tag":"核心","root":"","exampleEN":"The software automatically updates to the latest version every few weeks.","exampleCN":"该软件每隔几周便会自动更新至最新版本。","extra":""},{"chapter":20,"key":"20:206","id":206,"word":"raise","phonetic":"/reɪz/","pos":"v.","meaningCN":"举起；引起；抚养；提高；筹募","tag":"核心","root":"","exampleEN":"The school concert managed to raise over 5,000 dollars for the children's hospital.","exampleCN":"学校音乐会成功为儿童医院筹到了5000多美元。","extra":"搭配：raise a price 涨价；raise capital 筹集资本"},{"chapter":20,"key":"20:207","id":207,"word":"leak","phonetic":"/liːk/","pos":"v.","meaningCN":"泄漏 n. 漏洞，裂缝","tag":"核心","root":"","exampleEN":"Confidential information about the new product had leaked to the press.","exampleCN":"关于新产品的机密信息已泄露给了新闻界。","extra":""},{"chapter":20,"key":"20:208","id":208,"word":"spill","phonetic":"/spɪl/","pos":"v.","meaningCN":"（使）溢出","tag":"核心","root":"","exampleEN":"Be careful not to spill any coffee on the new white carpet.","exampleCN":"小心别把咖啡洒到新换的白色地毯上。","extra":"搭配：spill over 溢出"},{"chapter":20,"key":"20:209","id":209,"word":"seep","phonetic":"/siːp/","pos":"v.","meaningCN":"渗出，渗漏","tag":"低频","root":"","exampleEN":"Water was seeping slowly through the cracks in the old stone wall.","exampleCN":"水正慢慢地从旧石墙的裂缝中渗出来。","extra":""},{"chapter":20,"key":"20:210","id":210,"word":"ooze","phonetic":"/uːz/","pos":"v.","meaningCN":"渗出；洋溢着","tag":"低频","root":"","exampleEN":"She simply oozes confidence when she walks into a room full of people.","exampleCN":"当她走进一间满是人的屋子时，浑身都洋溢着自信。","extra":""},{"chapter":20,"key":"20:211","id":211,"word":"evacuate","phonetic":"/ɪˈvækjueɪt/","pos":"v.","meaningCN":"疏散，撤离","tag":"核心","root":"vac(u) = 空","exampleEN":"The entire building was evacuated immediately when the fire alarm sounded.","exampleCN":"火警一响，整栋大楼的人都被立即疏散了。","extra":"evacuation n. 疏散"},{"chapter":20,"key":"20:212","id":212,"word":"trench","phonetic":"/trentʃ/","pos":"v.","meaningCN":"掘沟于；砍除 n. 沟，渠，壕沟","tag":"低频","root":"","exampleEN":"The soldiers dug deep trenches around the camp for protection.","exampleCN":"士兵们在营地周围挖了深深的壕沟作为防护。","extra":""},{"chapter":20,"key":"20:213","id":213,"word":"saturate","phonetic":"/ˈsætʃəreɪt/","pos":"v.","meaningCN":"使饱和，使充满；浸透","tag":"低频","root":"","exampleEN":"The heavy, continuous rain had completely saturated the soil in the garden.","exampleCN":"持续的暴雨已完全浸透了花园里的土壤。","extra":"搭配：saturate oneself (in) 埋头在……中"},{"chapter":20,"key":"20:214","id":214,"word":"excuse","phonetic":"v. /ɪkˈskjuːz/ n. /ɪkˈskjuːs/","pos":"v.","meaningCN":"原谅；同意免除 n. 理由；借口","tag":"核心","root":"","exampleEN":"There is no excuse for being so rude to your grandmother.","exampleCN":"没有任何借口可以对祖母如此无礼。","extra":""},{"chapter":20,"key":"20:215","id":215,"word":"forgive","phonetic":"/fəˈɡɪv/","pos":"v.","meaningCN":"原谅，宽恕，饶恕","tag":"核心","root":"for- 表示否定","exampleEN":"She has finally found it in her heart to forgive him for his past mistakes.","exampleCN":"她终于打心底里原谅了他过去犯下的错误。","extra":""},{"chapter":20,"key":"20:216","id":216,"word":"contain","phonetic":"/kənˈteɪn/","pos":"v.","meaningCN":"包含，容纳；抑制（感情）","tag":"核心","root":"","exampleEN":"This box contains all the letters she wrote to her family during the war.","exampleCN":"这个盒子里装着她战争期间写给家人的所有信件。","extra":""},{"chapter":20,"key":"20:217","id":217,"word":"regard","phonetic":"/rɪˈɡɑːd/","pos":"n.","meaningCN":"尊重；问候 v. 看待","tag":"核心","root":"","exampleEN":"He is highly regarded by his students for his deep knowledge and patience.","exampleCN":"他因渊博的学识和耐心而深受学生们的尊敬。","extra":"regarding prep. 关于；搭配：in/with regard to 关于"},{"chapter":20,"key":"20:218","id":218,"word":"flatter","phonetic":"/ˈflætə/","pos":"v.","meaningCN":"奉承，讨好，向……谄媚","tag":"高频","root":"","exampleEN":"He was just trying to flatter you because he wants a favour in return.","exampleCN":"他只是在奉承你，因为他想请你帮个忙。","extra":""},{"chapter":20,"key":"20:219","id":219,"word":"worship","phonetic":"/ˈwɜːʃɪp/","pos":"n.","meaningCN":"（对上帝或神的）崇拜，礼拜；爱慕 v. 做礼拜","tag":"核心","root":"","exampleEN":"The church was filled with people who had gathered for morning worship.","exampleCN":"教堂里挤满了来做晨间礼拜的人。","extra":""},{"chapter":20,"key":"20:220","id":220,"word":"cause","phonetic":"/kɔːz/","pos":"n.","meaningCN":"原因，理由；事业 v. 引起，导致","tag":"核心","root":"","exampleEN":"The investigation aims to find out the exact cause of the plane crash.","exampleCN":"这次调查旨在查明飞机坠毁的确切原因。","extra":""},{"chapter":20,"key":"20:221","id":221,"word":"sake","phonetic":"/seɪk/","pos":"n.","meaningCN":"理由，目的","tag":"核心","root":"","exampleEN":"For the sake of your health, you should cut down on sugar and fatty foods.","exampleCN":"为了你的健康着想，你应该减少糖和油腻食物的摄入。","extra":"搭配：for the sake of 为了……起见"},{"chapter":20,"key":"20:222","id":222,"word":"purpose","phonetic":"/ˈpɜːpəs/","pos":"n.","meaningCN":"目的","tag":"核心","root":"","exampleEN":"The main purpose of this letter is to thank you for your generous support.","exampleCN":"这封信的主要目的是感谢您的慷慨支持。","extra":"purposefully adv. 故意地；搭配：on purpose 故意地"},{"chapter":20,"key":"20:223","id":223,"word":"objective","phonetic":"/əbˈdʒektɪv/","pos":"n.","meaningCN":"宗旨；目标 adj. 客观的","tag":"核心","root":"","exampleEN":"Our primary objective this quarter is to increase sales by 15 percent.","exampleCN":"我们本季度的首要目标是把销售额提高15%。","extra":"subjective adj. 主观的"},{"chapter":20,"key":"20:224","id":224,"word":"arouse","phonetic":"/əˈraʊz/","pos":"v.","meaningCN":"唤起，激起，引起","tag":"高频","root":"","exampleEN":"The strange sound outside the window aroused the guard's suspicion.","exampleCN":"窗外奇怪的声音引起了警卫的怀疑。","extra":"搭配：arouse sb.'s interest/curiosity"},{"chapter":20,"key":"20:225","id":225,"word":"trigger","phonetic":"/ˈtrɪɡə/","pos":"v.","meaningCN":"引发，触发 n.（枪等的）扳机","tag":"核心","root":"","exampleEN":"Certain foods can trigger allergies in some children, such as milk and nuts.","exampleCN":"某些食物，如牛奶和坚果，可能引发一些儿童的过敏反应。","extra":""},{"chapter":20,"key":"20:226","id":226,"word":"seek","phonetic":"/siːk/","pos":"v.","meaningCN":"寻找；寻求","tag":"核心","root":"","exampleEN":"More and more young people seek to achieve a balance between work and life.","exampleCN":"越来越多的年轻人寻求在工作与生活之间取得平衡。","extra":"搭配：seek after 追求"},{"chapter":20,"key":"20:227","id":227,"word":"retrieve","phonetic":"/rɪˈtriːv/","pos":"v.","meaningCN":"取回；挽回","tag":"高频","root":"","exampleEN":"I need to go back to the cafe to retrieve the umbrella I left there.","exampleCN":"我得回那家咖啡馆取回我落在那里的伞。","extra":""},{"chapter":20,"key":"20:228","id":228,"word":"testify","phonetic":"/ˈtestɪfaɪ/","pos":"v.","meaningCN":"作证；证明","tag":"高频","root":"","exampleEN":"The witness agreed to testify in court about what she saw that night.","exampleCN":"证人同意在法庭上就她那天晚上所看到的情况作证。","extra":"搭配：testify against 作不利证明"},{"chapter":20,"key":"20:229","id":229,"word":"verify","phonetic":"/ˈverɪfaɪ/","pos":"v.","meaningCN":"证实；核实，查清","tag":"核心","root":"","exampleEN":"We must verify the information before publishing the news article.","exampleCN":"我们必须在发布那篇新闻报道之前核实信息。","extra":""},{"chapter":20,"key":"20:230","id":230,"word":"specify","phonetic":"/ˈspesɪfaɪ/","pos":"v.","meaningCN":"具体指定，详细说明","tag":"核心","root":"","exampleEN":"The contract clearly specifies the payment terms and delivery date.","exampleCN":"合同明确规定了付款条件和交货日期。","extra":"specific adj. 具体的"},{"chapter":20,"key":"20:231","id":231,"word":"enlighten","phonetic":"/ɪnˈlaɪtən/","pos":"v.","meaningCN":"启发，开导，启迪","tag":"低频","root":"en（里面）+ light（光）+ en → 启迪","exampleEN":"Could you enlighten me on how this complicated machine actually works?","exampleCN":"你能不能跟我讲一讲这台复杂的机器究竟是如何运作的？","extra":""},{"chapter":20,"key":"20:232","id":232,"word":"impart","phonetic":"/ɪmˈpɑːt/","pos":"v.","meaningCN":"传授；透露","tag":"高频","root":"","exampleEN":"Good teachers do not just impart knowledge but also inspire a love of learning.","exampleCN":"好的老师不仅传授知识，还激发学生对学习的热爱。","extra":""},{"chapter":20,"key":"20:233","id":233,"word":"deserve","phonetic":"/dɪˈzɜːv/","pos":"v.","meaningCN":"应得；应受","tag":"核心","root":"","exampleEN":"You have worked so hard this year and you truly deserve this promotion.","exampleCN":"你今年工作非常努力，这次晋升是你应得的。","extra":""},{"chapter":20,"key":"20:234","id":234,"word":"drop","phonetic":"/drɒp/","pos":"v.","meaningCN":"（使）落下；（使）降低；和……断绝联系 n. 滴","tag":"核心","root":"","exampleEN":"Share prices dropped sharply after the company reported heavy losses.","exampleCN":"在公司公布巨额亏损后，股价急剧下跌。","extra":"搭配：a drop in the bucket 沧海一粟"},{"chapter":20,"key":"20:235","id":235,"word":"sink","phonetic":"/sɪŋk/","pos":"v.","meaningCN":"（使）下沉；下降","tag":"核心","root":"","exampleEN":"He watched the heavy stone sink to the bottom of the clear pond.","exampleCN":"他看着那块沉重的石头沉到清澈的池塘底部。","extra":""},{"chapter":20,"key":"20:236","id":236,"word":"plummet","phonetic":"/ˈplʌmɪt/","pos":"v.","meaningCN":"垂直掉下；（价格、水平等）骤然下跌","tag":"高频","root":"","exampleEN":"Temperatures are expected to plummet tonight, so bring in your plants.","exampleCN":"预计今晚气温会骤降，所以把植物搬进屋里吧。","extra":""},{"chapter":20,"key":"20:237","id":237,"word":"muffle","phonetic":"/ˈmʌfəl/","pos":"v.","meaningCN":"使（声音）减弱","tag":"低频","root":"","exampleEN":"She used a thick scarf to muffle the sound of her cough during the concert.","exampleCN":"音乐会上她用一条厚围巾捂住嘴，以减弱咳嗽的声音。","extra":""},{"chapter":20,"key":"20:238","id":238,"word":"overshadow","phonetic":"/ˌəʊvəˈʃædəʊ/","pos":"v.","meaningCN":"遮蔽；使黯然失色","tag":"低频","root":"","exampleEN":"The young tennis player's success was overshadowed by a recent injury.","exampleCN":"那位年轻网球选手的成功因近期的伤病而蒙上了阴影。","extra":""},{"chapter":20,"key":"20:239","id":239,"word":"invite","phonetic":"/ɪnˈvaɪt/","pos":"v.","meaningCN":"邀请","tag":"核心","root":"","exampleEN":"We would like to invite you to our annual company dinner next Friday.","exampleCN":"我们想邀请您参加下周五的公司年度晚宴。","extra":"invitation n. 邀请"},{"chapter":20,"key":"20:240","id":240,"word":"welcome","phonetic":"/ˈwelkəm/","pos":"int./n./v.","meaningCN":"欢迎","tag":"核心","root":"","exampleEN":"The family warmly welcomed their relatives who had travelled from overseas.","exampleCN":"这家人热情地欢迎了从海外远道而来的亲戚。","extra":"搭配：welcome to 欢迎来到"},{"chapter":20,"key":"20:241","id":241,"word":"greet","phonetic":"/ɡriːt/","pos":"v.","meaningCN":"向……问好，迎接；对……作出反应","tag":"核心","root":"","exampleEN":"She greeted the guests at the door with a big smile and a handshake.","exampleCN":"她满脸笑容地在门口与客人握手问好。","extra":"greeting n. 问候"},{"chapter":20,"key":"20:242","id":242,"word":"salute","phonetic":"/səˈluːt/","pos":"v.","meaningCN":"（向……）行礼；致敬 n. 行礼；致敬","tag":"高频","root":"","exampleEN":"The soldiers stood and saluted as the national flag was raised.","exampleCN":"国旗升起时，士兵们立正敬礼。","extra":""},{"chapter":20,"key":"20:243","id":243,"word":"celebrate","phonetic":"/ˈselɪbreɪt/","pos":"v.","meaningCN":"庆祝（节日、事件等）","tag":"核心","root":"","exampleEN":"They are planning a big party to celebrate their parents' 50th wedding anniversary.","exampleCN":"他们正在筹划一场大型聚会来庆祝父母的金婚纪念日。","extra":"celebration n. 庆祝；celebrated adj. 著名的"},{"chapter":20,"key":"20:244","id":244,"word":"congratulate","phonetic":"/kənˈɡrætʃʊleɪt/","pos":"v.","meaningCN":"祝贺，向……道贺","tag":"核心","root":"","exampleEN":"I just want to congratulate you on passing the driving test on your first try.","exampleCN":"恭喜你一次性通过了驾照考试。","extra":"congratulation n. 恭喜"},{"chapter":20,"key":"20:245","id":245,"word":"bless","phonetic":"/bles/","pos":"v.","meaningCN":"祝福，为……祈求上帝保佑","tag":"核心","root":"","exampleEN":"The priest blessed the newly married couple and wished them a happy life.","exampleCN":"牧师为那对新婚夫妇祈福，祝他们生活幸福。","extra":"搭配：Bless you! 长命百岁！（打喷嚏时）"},{"chapter":20,"key":"20:246","id":246,"word":"participate","phonetic":"/pɑːˈtɪsɪpeɪt/","pos":"v.","meaningCN":"参加，参与","tag":"核心","root":"","exampleEN":"Over 100 runners participated in the city marathon despite the rainy weather.","exampleCN":"尽管天气下雨，仍有100多名跑步者参加了城市马拉松。","extra":"participant n. 参与者；搭配：participate in"},{"chapter":20,"key":"20:247","id":247,"word":"farewell","phonetic":"/ˌfeəˈwel/","pos":"int.","meaningCN":"再会 n. 告别","tag":"高频","root":"","exampleEN":"The whole class came to say farewell to the exchange student returning home.","exampleCN":"全班同学都来向要回国的交换生告别。","extra":"搭配：a farewell address 告别演说"},{"chapter":20,"key":"20:248","id":248,"word":"assort","phonetic":"/əˈsɔːt/","pos":"v.","meaningCN":"把……分类；相配，协调","tag":"低频","root":"","exampleEN":"The socks in this drawer need to be assorted by colour and size.","exampleCN":"这个抽屉里的袜子需要按颜色和大小分类。","extra":""},{"chapter":20,"key":"20:249","id":249,"word":"correspond","phonetic":"/ˌkɒrɪˈspɒnd/","pos":"v.","meaningCN":"符合，相一致；通信","tag":"核心","root":"","exampleEN":"The names on the list must correspond exactly with those on your passport.","exampleCN":"名单上的名字必须与你护照上的名字完全一致。","extra":"搭配：correspond with sb. 与某人通信"},{"chapter":20,"key":"20:250","id":250,"word":"accord","phonetic":"/əˈkɔːd/","pos":"v.","meaningCN":"（与……）一致；给予 n. 协议","tag":"高频","root":"","exampleEN":"His account of the accident does not accord with the facts provided by the police.","exampleCN":"他对事故的叙述与警方提供的事实不符。","extra":"accordance n. 一致；accordingly adv. 因此"},{"chapter":20,"key":"20:251","id":251,"word":"attribute","phonetic":"v. /əˈtrɪbjuːt/ n. /ˈætrɪbjuːt/","pos":"v.","meaningCN":"把……归因于 n. 属性，特性","tag":"核心","root":"","exampleEN":"She attributes her excellent health to a balanced diet and daily exercise.","exampleCN":"她把自己极好的健康归因于均衡的饮食和每天锻炼。","extra":"attribution n. 归因；搭配：attribute sth. to"},{"chapter":20,"key":"20:252","id":252,"word":"recall","phonetic":"/rɪˈkɔːl/","pos":"v.","meaningCN":"回忆，回想起","tag":"核心","root":"","exampleEN":"I can still vividly recall the first day I walked into this university.","exampleCN":"我仍然清晰地记得我走进这所大学的第一天。","extra":""},{"chapter":20,"key":"20:253","id":253,"word":"recollect","phonetic":"/ˌrekəˈlekt/","pos":"v.","meaningCN":"记起，想起","tag":"高频","root":"lect = 选；搜集","exampleEN":"Can you recollect where you put the spare house key a few days ago?","exampleCN":"你能想起来几天前你把备用家门钥匙放哪了吗？","extra":""},{"chapter":20,"key":"20:254","id":254,"word":"remind","phonetic":"/rɪˈmaɪnd/","pos":"v.","meaningCN":"提醒，使想起","tag":"核心","root":"","exampleEN":"Please remind me to call the dentist tomorrow morning, or I might forget.","exampleCN":"请提醒我明天早上给牙医打电话，不然我可能会忘记。","extra":"搭配：remind sb. of 使某人想起"},{"chapter":20,"key":"20:255","id":255,"word":"retell","phonetic":"/riːˈtel/","pos":"v.","meaningCN":"重新讲述，复述","tag":"高频","root":"","exampleEN":"The children were asked to retell the story in their own simple words.","exampleCN":"孩子们被要求用自己的简单语言复述那个故事。","extra":""},{"chapter":20,"key":"20:256","id":256,"word":"repeat","phonetic":"/rɪˈpiːt/","pos":"v.","meaningCN":"重复 adj. 再次光顾的","tag":"核心","root":"peat/pet = 寻求","exampleEN":"Could you please repeat the last sentence? I didn't quite catch it.","exampleCN":"你能把最后一句话重复一遍吗？我没太听清。","extra":"repetition n. 重复"},{"chapter":20,"key":"20:257","id":257,"word":"retrospect","phonetic":"/ˌretrəspekt/","pos":"n.","meaningCN":"[in ~] 回顾","tag":"高频","root":"","exampleEN":"In retrospect, leaving that job was the best decision I could have made.","exampleCN":"回过头看，辞去那份工作是我能做的最好的决定。","extra":"retrospective adj. 回顾的"},{"chapter":20,"key":"20:258","id":258,"word":"impress","phonetic":"/ɪmˈpres/","pos":"v.","meaningCN":"给……深刻印象；使铭记","tag":"核心","root":"","exampleEN":"The young pianist's technical skill deeply impressed the judges at the competition.","exampleCN":"那位年轻钢琴家的技术技巧给比赛评委留下了深刻印象。","extra":"impression n. 印象；impressive adj. 印象深刻的"},{"chapter":20,"key":"20:259","id":259,"word":"surmount","phonetic":"/səˈmaʊnt/","pos":"v.","meaningCN":"克服；置于……顶端","tag":"低频","root":"sur = 在……上","exampleEN":"With courage and patience, you can surmount almost any obstacle in your life.","exampleCN":"有了勇气和耐心，你几乎可以克服人生中的任何障碍。","extra":"surpass v. 胜过"},{"chapter":20,"key":"20:260","id":260,"word":"mortify","phonetic":"/ˈmɔːtɪfaɪ/","pos":"v.","meaningCN":"使难堪，使羞愧","tag":"低频","root":"","exampleEN":"She felt utterly mortified when she tripped and fell in front of the entire audience.","exampleCN":"当她在全场观众面前绊倒时，她感到无比难堪。","extra":""},{"chapter":20,"key":"20:261","id":261,"word":"pervade","phonetic":"/pəˈveɪd/","pos":"v.","meaningCN":"弥漫，渗透，遍及","tag":"低频","root":"vade = 走","exampleEN":"A wonderful smell of fresh baking pervaded the whole house.","exampleCN":"一股新鲜烘焙的香味弥漫了整个房子。","extra":"pervasive adj. 遍布的"},{"chapter":20,"key":"20:262","id":262,"word":"replace","phonetic":"/rɪˈpleɪs/","pos":"v.","meaningCN":"代替，取代","tag":"核心","root":"","exampleEN":"Many workers fear that robots will eventually replace them in factories.","exampleCN":"许多工人害怕机器人终将在工厂里取代他们。","extra":"搭配：replace A with B 用 B 替换 A"},{"chapter":20,"key":"20:263","id":263,"word":"distinguish","phonetic":"/dɪˈstɪŋɡwɪʃ/","pos":"v.","meaningCN":"区别，辨别；使出众，使著名","tag":"核心","root":"","exampleEN":"A tiny birthmark on her cheek distinguishes her from her twin sister.","exampleCN":"脸颊上一小块胎记令她和双胞胎姐姐得以区分。","extra":"distinguished adj. 卓越的；distinction n. 区分"},{"chapter":20,"key":"20:264","id":264,"word":"differentiate","phonetic":"/ˌdɪfəˈrenʃieɪt/","pos":"v.","meaningCN":"区分，区别；差别对待","tag":"高频","root":"","exampleEN":"Colour blindness makes it hard for some people to differentiate between red and green.","exampleCN":"色盲使一些人难以区分红色和绿色。","extra":""},{"chapter":20,"key":"20:265","id":265,"word":"substitute","phonetic":"/ˈsʌbstɪtjuːt/","pos":"v.","meaningCN":"替换 n. 代用品；代替者；替补（运动员）","tag":"核心","root":"","exampleEN":"In this recipe, you can substitute honey for sugar to make it healthier.","exampleCN":"在这份食谱中，你可以用蜂蜜代替糖，让成品更健康。","extra":"substitution n. 替换；搭配：substitute A for B"},{"chapter":20,"key":"20:266","id":266,"word":"incline","phonetic":"v. /ɪnˈklaɪn/ n. /ˈɪnklaɪn/","pos":"v.","meaningCN":"（使）倾向于；（使）倾斜 n. 斜坡；倾斜","tag":"高频","root":"","exampleEN":"His arguments incline me to believe that the new plan is much better than the old one.","exampleCN":"他的论据使我倾向于相信新方案比旧的好得多。","extra":""},{"chapter":20,"key":"20:267","id":267,"word":"lean","phonetic":"/liːn/","pos":"v.","meaningCN":"（使）倚靠；倾斜 adj. 瘦的；贫乏的","tag":"核心","root":"","exampleEN":"The old bicycle leans against the wall, covered with dust and mud.","exampleCN":"那辆旧自行车斜靠在墙上，沾满了灰尘和泥土。","extra":"搭配：lean on 依靠；lean toward 倾向于"},{"chapter":20,"key":"20:268","id":268,"word":"sideways","phonetic":"/ˈsaɪdweɪz/","pos":"adv.","meaningCN":"向（或从、往）一侧","tag":"高频","root":"","exampleEN":"The strong wind was so powerful that it blew the rain sideways.","exampleCN":"强风吹得非常猛，把雨都吹得横着飞。","extra":""}],"21":[{"chapter":21,"key":"21:1","id":1,"word":"feel","phonetic":"/fiːl/","pos":"v.","meaningCN":"感觉，感知；触碰","tag":"核心","root":"","exampleEN":"You can feel the soft breeze coming through the open window.","exampleCN":"你能感觉到微风从敞开的窗户吹进来。","extra":"feeling n. 感情；感觉"},{"chapter":21,"key":"21:2","id":2,"word":"mood","phonetic":"/muːd/","pos":"n.","meaningCN":"心情，情绪；气氛","tag":"核心","root":"","exampleEN":"Her cheerful mood spread to everyone in the room.","exampleCN":"她愉快的心情感染了房间里的每个人。","extra":"moody adj. 易怒的，喜怒无常的"},{"chapter":21,"key":"21:3","id":3,"word":"emotion","phonetic":"/ɪˈməʊʃən/","pos":"n.","meaningCN":"情绪，情感，感情","tag":"核心","root":"e (=ex 外面) + motion (运动) → 移到外面 → 激动 → 感情","exampleEN":"He tried to hide his emotions when he heard the news.","exampleCN":"他听到消息时试图掩饰自己的情绪。","extra":"emotional adj. 感情（上）的，情绪（上）的"},{"chapter":21,"key":"21:4","id":4,"word":"temper","phonetic":"/ˈtempə/","pos":"n.","meaningCN":"坏脾气；情绪，心情 v. 使缓和","tag":"高频","root":"","exampleEN":"She found it hard to keep her temper during the heated debate.","exampleCN":"她发现在激烈的辩论中很难忍住不发火。","extra":"lose one's temper 发脾气；keep one's temper 忍住不发火"},{"chapter":21,"key":"21:5","id":5,"word":"manner","phonetic":"/ˈmænə/","pos":"n.","meaningCN":"举止；礼貌；方式；风俗","tag":"高频","root":"","exampleEN":"His friendly manner made a good impression on the interviewers.","exampleCN":"他友善的举止给面试官留下了良好的印象。","extra":""},{"chapter":21,"key":"21:6","id":6,"word":"attitude","phonetic":"/ˈætɪtjuːd/","pos":"n.","meaningCN":"态度，看法","tag":"核心","root":"","exampleEN":"A positive attitude is essential when learning a new language.","exampleCN":"学习一门新语言时，积极的态度至关重要。","extra":"keep a firm attitude"},{"chapter":21,"key":"21:7","id":7,"word":"character","phonetic":"/ˈkærɪktə/","pos":"n.","meaningCN":"性格；特征；人物，角色","tag":"核心","root":"","exampleEN":"The main character in the novel overcomes many difficulties.","exampleCN":"小说中的主角克服了许多困难。","extra":"characteristic n. 特征，特点"},{"chapter":21,"key":"21:8","id":8,"word":"personality","phonetic":"/ˌpɜːsəˈnælɪti/","pos":"n.","meaningCN":"个性，人格","tag":"核心","root":"","exampleEN":"Her outgoing personality makes it easy for her to make friends.","exampleCN":"她外向的性格使她很容易交到朋友。","extra":""},{"chapter":21,"key":"21:9","id":9,"word":"trait","phonetic":"/treɪt/","pos":"n.","meaningCN":"特性，特点","tag":"高频","root":"","exampleEN":"Curiosity is a common trait among successful scientists.","exampleCN":"好奇心是成功科学家的一个共同特点。","extra":""},{"chapter":21,"key":"21:10","id":10,"word":"virtue","phonetic":"/ˈvɜːtʃuː/","pos":"n.","meaningCN":"美德，德行；优点","tag":"高频","root":"","exampleEN":"Patience is a virtue that few people truly master.","exampleCN":"耐心是一种很少有人能真正掌握的美德。","extra":""},{"chapter":21,"key":"21:11","id":11,"word":"feature","phonetic":"/ˈfiːtʃə/","pos":"n.","meaningCN":"特征；面容的一部分 v. 以......为特色","tag":"核心","root":"","exampleEN":"The new smartphone features an advanced camera system.","exampleCN":"这款新智能手机以先进的摄像系统为特色。","extra":""},{"chapter":21,"key":"21:12","id":12,"word":"stature","phonetic":"/ˈstætʃə/","pos":"n.","meaningCN":"身高，身材；（精神、道德等的）高度","tag":"低频","root":"","exampleEN":"Despite his small stature, he was a powerful leader.","exampleCN":"尽管他身材矮小，却是一位强有力的领导者。","extra":""},{"chapter":21,"key":"21:13","id":13,"word":"flesh","phonetic":"/fleʃ/","pos":"n.","meaningCN":"肉；人类","tag":"低频","root":"","exampleEN":"The thorn pierced the flesh of his hand.","exampleCN":"那根刺扎进了他手上的肉里。","extra":""},{"chapter":21,"key":"21:14","id":14,"word":"mankind","phonetic":"/mænˈkaɪnd/","pos":"n.","meaningCN":"人类；男人","tag":"高频","root":"","exampleEN":"Exploring space has always been a dream of mankind.","exampleCN":"探索太空一直是人类的梦想。","extra":""},{"chapter":21,"key":"21:15","id":15,"word":"human","phonetic":"/ˈhjuːmən/","pos":"adj.","meaningCN":"人类的；有人性的 n. 人类","tag":"核心","root":"","exampleEN":"There is a limit to human strength, but not to human creativity.","exampleCN":"人的力量有限，但创造力无限。","extra":""},{"chapter":21,"key":"21:16","id":16,"word":"bone","phonetic":"/bəʊn/","pos":"n.","meaningCN":"骨；骨骼","tag":"核心","root":"","exampleEN":"Calcium helps to keep bones strong and healthy.","exampleCN":"钙有助于保持骨骼强壮和健康。","extra":""},{"chapter":21,"key":"21:17","id":17,"word":"backbone","phonetic":"/ˈbækbəʊn/","pos":"n.","meaningCN":"脊柱；骨干，中坚；骨气","tag":"高频","root":"","exampleEN":"Small businesses are often considered the backbone of the local economy.","exampleCN":"小企业通常被认为是地方经济的支柱。","extra":""},{"chapter":21,"key":"21:18","id":18,"word":"skeleton","phonetic":"/ˈskelɪtən/","pos":"n.","meaningCN":"骨骼，骨架；框架，梗概","tag":"低频","root":"","exampleEN":"The archaeologists discovered a complete dinosaur skeleton in the desert.","exampleCN":"考古学家在沙漠中发现了一具完整的恐龙骨架。","extra":"skeleton at the feast 扫兴的人或事物"},{"chapter":21,"key":"21:19","id":19,"word":"brain","phonetic":"/breɪn/","pos":"n.","meaningCN":"脑；[~s]智慧，智力","tag":"核心","root":"","exampleEN":"Regular exercise is good for both the body and the brain.","exampleCN":"经常锻炼对身体和大脑都有好处。","extra":""},{"chapter":21,"key":"21:20","id":20,"word":"mind","phonetic":"/maɪnd/","pos":"n.","meaningCN":"头脑；思考能力；思维；意见；记忆力","tag":"核心","root":"","exampleEN":"Try to keep an open mind when listening to different opinions.","exampleCN":"在听取不同意见时，尽量保持开放的思维。","extra":"absence of mind 心不在焉"},{"chapter":21,"key":"21:21","id":21,"word":"physical","phonetic":"/ˈfɪzɪkəl/","pos":"adj.","meaningCN":"身体的；物质的；物理的","tag":"核心","root":"","exampleEN":"Physical activity can reduce the risk of many chronic diseases.","exampleCN":"体育活动可以降低许多慢性病的风险。","extra":"physiology n. 生理学；physics n. 物理学"},{"chapter":21,"key":"21:22","id":22,"word":"mental","phonetic":"/ˈmentl/","pos":"adj.","meaningCN":"精神的，思想上的；智力的","tag":"核心","root":"","exampleEN":"Meditation can improve mental clarity and reduce stress.","exampleCN":"冥想可以提高头脑清晰度并减轻压力。","extra":""},{"chapter":21,"key":"21:23","id":23,"word":"cheek","phonetic":"/tʃiːk/","pos":"n.","meaningCN":"面颊，颊","tag":"核心","root":"","exampleEN":"The child had red cheeks after playing in the cold wind.","exampleCN":"孩子在寒风中玩耍后脸颊通红。","extra":"cheek to cheek"},{"chapter":21,"key":"21:24","id":24,"word":"forehead","phonetic":"/ˈfɔːhed/","pos":"n.","meaningCN":"额","tag":"核心","root":"","exampleEN":"He wiped the sweat from his forehead after the long run.","exampleCN":"长跑之后他擦去额头上的汗水。","extra":""},{"chapter":21,"key":"21:25","id":25,"word":"brow","phonetic":"/braʊ/","pos":"n.","meaningCN":"额；眉，眉毛","tag":"低频","root":"","exampleEN":"She raised her brows in surprise at the unexpected news.","exampleCN":"听到这个意外的消息，她惊讶地扬起了眉毛。","extra":""},{"chapter":21,"key":"21:26","id":26,"word":"eyelash","phonetic":"/ˈaɪlæʃ/","pos":"n.","meaningCN":"眼睫毛","tag":"高频","root":"","exampleEN":"An eyelash fell into her eye and caused a lot of discomfort.","exampleCN":"一根眼睫毛掉进她的眼睛里，引起了很多不适。","extra":"eyelid n. 眼皮，眼睑"},{"chapter":21,"key":"21:27","id":27,"word":"skull","phonetic":"/skʌl/","pos":"n.","meaningCN":"头脑；头骨","tag":"高频","root":"","exampleEN":"The helmet is designed to protect the skull from injury.","exampleCN":"这种头盔的设计目的是保护头骨免受伤害。","extra":"Skull and Bones 骷髅会"},{"chapter":21,"key":"21:28","id":28,"word":"lip","phonetic":"/lɪp/","pos":"n.","meaningCN":"嘴唇；（洞口、伤口等的）边缘","tag":"核心","root":"","exampleEN":"She bit her lower lip nervously while waiting for the result.","exampleCN":"等待结果时，她紧张地咬着下嘴唇。","extra":"lipstick n. 口红，唇膏"},{"chapter":21,"key":"21:29","id":29,"word":"mouth","phonetic":"/maʊθ/","pos":"n.","meaningCN":"口，嘴；河口","tag":"核心","root":"","exampleEN":"The story spread quickly from mouth to mouth in the small town.","exampleCN":"这个故事在小镇上口口相传，很快传开了。","extra":"mouthful n. 一口；by word of mouth；spread from mouth to mouth"},{"chapter":21,"key":"21:30","id":30,"word":"tongue","phonetic":"/tʌŋ/","pos":"n.","meaningCN":"舌头；语言","tag":"核心","root":"","exampleEN":"Laughing out loud is a good exercise for your tongue and throat.","exampleCN":"大声笑是锻炼舌头和喉咙的好方法。","extra":"a slip of the tongue；a tongue-twister"},{"chapter":21,"key":"21:31","id":31,"word":"throat","phonetic":"/θrəʊt/","pos":"n.","meaningCN":"喉咙；窄路；嗓子，嗓音","tag":"核心","root":"","exampleEN":"Drinking warm water with honey helped soothe her sore throat.","exampleCN":"喝温热的蜂蜜水帮她缓解了喉咙痛。","extra":""},{"chapter":21,"key":"21:32","id":32,"word":"gorge","phonetic":"/ɡɔːdʒ/","pos":"n.","meaningCN":"咽喉；暴食；山峡，峡谷 v. 狼吞虎咽","tag":"低频","root":"","exampleEN":"The Three Gorges Dam is one of the largest engineering projects in the world.","exampleCN":"三峡大坝是世界上最大的工程项目之一。","extra":""},{"chapter":21,"key":"21:33","id":33,"word":"chin","phonetic":"/tʃɪn/","pos":"n.","meaningCN":"（指人的）颊，下巴","tag":"核心","root":"","exampleEN":"He rested his chin on his hand while thinking deeply.","exampleCN":"他深思时用手托着下巴。","extra":""},{"chapter":21,"key":"21:34","id":34,"word":"jaw","phonetic":"/dʒɔː/","pos":"n.","meaningCN":"颌；下巴；狭窄入口；唠叨","tag":"高频","root":"","exampleEN":"The doctor asked him to open his jaw to examine his teeth.","exampleCN":"医生让他张开下巴检查牙齿。","extra":""},{"chapter":21,"key":"21:35","id":35,"word":"neck","phonetic":"/nek/","pos":"n.","meaningCN":"脖子；衣领；海峡","tag":"核心","root":"","exampleEN":"The candidates are neck and neck in the latest opinion poll.","exampleCN":"在最新的民意调查中，几位候选人难分高下。","extra":""},{"chapter":21,"key":"21:36","id":36,"word":"beard","phonetic":"/bɪəd/","pos":"n.","meaningCN":"胡须","tag":"核心","root":"","exampleEN":"He decided to grow a beard during the winter holiday.","exampleCN":"他决定在寒假期间留胡须。","extra":"wear a beard"},{"chapter":21,"key":"21:37","id":37,"word":"shoulder","phonetic":"/ˈʃəʊldə/","pos":"n.","meaningCN":"肩，肩膀","tag":"核心","root":"","exampleEN":"Employees are expected to shoulder more responsibility as they gain experience.","exampleCN":"随着经验的积累，员工需要承担更多的责任。","extra":"shoulder responsibility"},{"chapter":21,"key":"21:38","id":38,"word":"limb","phonetic":"/lɪm/","pos":"n.","meaningCN":"肢；树枝","tag":"高频","root":"","exampleEN":"After the accident, the patient needed an artificial limb to walk again.","exampleCN":"事故过后，那位患者需要安装假肢才能再次行走。","extra":"an artificial limb"},{"chapter":21,"key":"21:39","id":39,"word":"elbow","phonetic":"/ˈelbəʊ/","pos":"n.","meaningCN":"肘部；弯头；扶手 v. 用肘挤","tag":"高频","root":"","exampleEN":"He accidentally hit his elbow against the door and felt a sharp pain.","exampleCN":"他不小心把肘部撞到了门上，感到一阵剧痛。","extra":""},{"chapter":21,"key":"21:40","id":40,"word":"wrist","phonetic":"/rɪst/","pos":"n.","meaningCN":"腕，腕关节","tag":"核心","root":"","exampleEN":"She wore a silver watch on her left wrist.","exampleCN":"她左手腕上戴着一块银色的手表。","extra":"waist n. 腰，腰部"},{"chapter":21,"key":"21:41","id":41,"word":"thumb","phonetic":"/θʌm/","pos":"n.","meaningCN":"拇指","tag":"核心","root":"","exampleEN":"The manager gave the proposal a thumbs-up after reading it.","exampleCN":"经理读完后对提案竖起了大拇指。","extra":""},{"chapter":21,"key":"21:42","id":42,"word":"palm","phonetic":"/pɑːm/","pos":"n.","meaningCN":"手掌","tag":"高频","root":"","exampleEN":"She placed the small bird gently on the palm of her hand.","exampleCN":"她轻轻地把小鸟放在自己的手掌上。","extra":"read sb.'s palm 看手相"},{"chapter":21,"key":"21:43","id":43,"word":"finger","phonetic":"/ˈfɪŋɡə/","pos":"n.","meaningCN":"手指","tag":"核心","root":"","exampleEN":"Each person has unique fingerprints that can be used for identification.","exampleCN":"每个人都有独一无二的指纹，可用于身份识别。","extra":"fingerprint n. 指纹"},{"chapter":21,"key":"21:44","id":44,"word":"fist","phonetic":"/fɪst/","pos":"n.","meaningCN":"拳头","tag":"核心","root":"","exampleEN":"She clenched her fist in determination before walking onto the stage.","exampleCN":"她在走上舞台前坚定地握紧拳头。","extra":""},{"chapter":21,"key":"21:45","id":45,"word":"chest","phonetic":"/tʃest/","pos":"n.","meaningCN":"胸膛","tag":"核心","root":"","exampleEN":"The doctor listened to his chest with a stethoscope.","exampleCN":"医生用听诊器听了他的胸腔。","extra":""},{"chapter":21,"key":"21:46","id":46,"word":"abdomen","phonetic":"/ˈæbdəmən/","pos":"n.","meaningCN":"腹部","tag":"低频","root":"","exampleEN":"The surgeon made a small incision in the patient's lower abdomen.","exampleCN":"外科医生在病人的下腹部切了一个小口。","extra":"six-pack 腹肌"},{"chapter":21,"key":"21:47","id":47,"word":"rib","phonetic":"/rɪb/","pos":"n.","meaningCN":"肋骨","tag":"高频","root":"","exampleEN":"He felt a sharp pain in his ribs after tackling his opponent.","exampleCN":"他在拦截对手后感到肋骨一阵剧痛。","extra":""},{"chapter":21,"key":"21:48","id":48,"word":"waist","phonetic":"/weɪst/","pos":"n.","meaningCN":"腰，腰部","tag":"核心","root":"","exampleEN":"This dress is a bit tight around the waist; I need a larger size.","exampleCN":"这条裙子腰围有点紧，我需要大一号的。","extra":"a waist belt"},{"chapter":21,"key":"21:49","id":49,"word":"organ","phonetic":"/ˈɔːɡən/","pos":"n.","meaningCN":"器官","tag":"核心","root":"","exampleEN":"The skin is actually the largest organ of the human body.","exampleCN":"皮肤实际上是人体最大的器官。","extra":"organic, organism"},{"chapter":21,"key":"21:50","id":50,"word":"liver","phonetic":"/ˈlɪvə/","pos":"n.","meaningCN":"肝脏","tag":"高频","root":"","exampleEN":"Eating too much fatty food can damage your liver over time.","exampleCN":"长期吃太多油腻的食物会损害肝脏。","extra":""},{"chapter":21,"key":"21:51","id":51,"word":"stomach","phonetic":"/ˈstʌmək/","pos":"n.","meaningCN":"胃","tag":"核心","root":"","exampleEN":"He had a stomach ache because he ate too quickly.","exampleCN":"他因为吃得太快而胃疼。","extra":""},{"chapter":21,"key":"21:52","id":52,"word":"womb","phonetic":"/wuːm/","pos":"n.","meaningCN":"子宫","tag":"低频","root":"","exampleEN":"The bond between mother and child begins from the womb.","exampleCN":"母亲与孩子之间的纽带从子宫里就开始了。","extra":"from the womb to the tomb"},{"chapter":21,"key":"21:53","id":53,"word":"kidney","phonetic":"/ˈkɪdni/","pos":"n.","meaningCN":"肾脏","tag":"高频","root":"","exampleEN":"Drinking plenty of water helps the kidneys function properly.","exampleCN":"多喝水有助于肾脏正常运作。","extra":""},{"chapter":21,"key":"21:54","id":54,"word":"lung","phonetic":"/lʌŋ/","pos":"n.","meaningCN":"肺","tag":"核心","root":"","exampleEN":"Smoking can cause serious damage to the lungs.","exampleCN":"吸烟会对肺部造成严重损害。","extra":""},{"chapter":21,"key":"21:55","id":55,"word":"gland","phonetic":"/ɡlænd/","pos":"n.","meaningCN":"腺","tag":"低频","root":"","exampleEN":"The thyroid gland plays an important role in regulating metabolism.","exampleCN":"甲状腺在调节新陈代谢中发挥着重要作用。","extra":""},{"chapter":21,"key":"21:56","id":56,"word":"chamber","phonetic":"/ˈtʃeɪmbə/","pos":"n.","meaningCN":"（人体内、动植物体内或机器中的）室，腔；议院","tag":"低频","root":"","exampleEN":"The human heart consists of four separate chambers.","exampleCN":"人的心脏由四个独立的腔室组成。","extra":""},{"chapter":21,"key":"21:57","id":57,"word":"intestine","phonetic":"/ɪnˈtestɪn/","pos":"n.","meaningCN":"肠","tag":"低频","root":"","exampleEN":"Fiber helps food move smoothly through the small intestine.","exampleCN":"纤维有助于食物顺利通过小肠。","extra":""},{"chapter":21,"key":"21:58","id":58,"word":"muscle","phonetic":"/ˈmʌsəl/","pos":"n.","meaningCN":"肌肉","tag":"核心","root":"","exampleEN":"He trained hard to build muscle and improve his endurance.","exampleCN":"他刻苦训练以增强肌肉并提高耐力。","extra":"muscular adj. 肌肉发达的；muscle 与 mouse 同源"},{"chapter":21,"key":"21:59","id":59,"word":"thigh","phonetic":"/θaɪ/","pos":"n.","meaningCN":"大腿，股","tag":"高频","root":"","exampleEN":"She felt a sudden cramp in her thigh while running.","exampleCN":"她跑步时大腿突然抽筋了。","extra":""},{"chapter":21,"key":"21:60","id":60,"word":"joint","phonetic":"/dʒɔɪnt/","pos":"n.","meaningCN":"接合处；关节 adj. 共同的，联合的","tag":"核心","root":"","exampleEN":"The two companies launched a joint marketing campaign last month.","exampleCN":"上个月这两家公司联合发起了一场营销活动。","extra":""},{"chapter":21,"key":"21:61","id":61,"word":"knee","phonetic":"/niː/","pos":"n.","meaningCN":"膝盖，膝","tag":"核心","root":"","exampleEN":"The athlete injured his knee during the match and had to leave the field.","exampleCN":"那位运动员在比赛中伤了膝盖，不得不离开赛场。","extra":"a knee bend"},{"chapter":21,"key":"21:62","id":62,"word":"lap","phonetic":"/læp/","pos":"n.","meaningCN":"（人坐着时的）大腿部；下摆；环节；一圈","tag":"高频","root":"","exampleEN":"The cat curled up on her lap and fell asleep.","exampleCN":"小猫蜷缩在她的大腿上睡着了。","extra":""},{"chapter":21,"key":"21:63","id":63,"word":"ankle","phonetic":"/ˈæŋkəl/","pos":"n.","meaningCN":"踝关节，踝","tag":"高频","root":"","exampleEN":"She twisted her ankle while walking downstairs and needed an X-ray.","exampleCN":"她下楼时扭伤了脚踝，需要拍X光片。","extra":"ankle joint, ankle socks"},{"chapter":21,"key":"21:64","id":64,"word":"heel","phonetic":"/hiːl/","pos":"n.","meaningCN":"足跟","tag":"核心","root":"","exampleEN":"She prefers flat shoes because high heels hurt her feet.","exampleCN":"她更喜欢平底鞋，因为高跟鞋会让她的脚疼。","extra":"high-heel n. 高跟鞋"},{"chapter":21,"key":"21:65","id":65,"word":"toe","phonetic":"/təʊ/","pos":"n.","meaningCN":"脚趾，足尖","tag":"核心","root":"","exampleEN":"The ballet dancer stood on the tips of her toes with perfect balance.","exampleCN":"那位芭蕾舞演员用足尖完美地保持着平衡。","extra":"from tip to toe"},{"chapter":21,"key":"21:66","id":66,"word":"pore","phonetic":"/pɔː/","pos":"n.","meaningCN":"毛孔；小孔，气孔 v. 凝视；沉思","tag":"高频","root":"","exampleEN":"Steam from the hot shower can help open your skin pores.","exampleCN":"热水淋浴产生的蒸汽有助于打开皮肤毛孔。","extra":""},{"chapter":21,"key":"21:67","id":67,"word":"pulse","phonetic":"/pʌls/","pos":"n.","meaningCN":"脉搏；脉冲","tag":"高频","root":"","exampleEN":"The nurse checked the patient's pulse to see if it was normal.","exampleCN":"护士检查了病人的脉搏，看是否正常。","extra":"impulse n. 冲动"},{"chapter":21,"key":"21:68","id":68,"word":"artery","phonetic":"/ˈɑːtəri/","pos":"n.","meaningCN":"动脉；干线","tag":"低频","root":"","exampleEN":"A blocked artery can lead to a heart attack.","exampleCN":"动脉阻塞可能导致心脏病发作。","extra":"vein n. 静脉"},{"chapter":21,"key":"21:69","id":69,"word":"nerve","phonetic":"/nɜːv/","pos":"n.","meaningCN":"神经；紧张，焦虑","tag":"高频","root":"","exampleEN":"She tried to calm her nerves before giving the speech.","exampleCN":"她在演讲前努力让自己冷静下来。","extra":""},{"chapter":21,"key":"21:70","id":70,"word":"hormone","phonetic":"/ˈhɔːməʊn/","pos":"n.","meaningCN":"荷尔蒙，激素","tag":"低频","root":"","exampleEN":"Lack of sleep can disrupt the body's natural hormone balance.","exampleCN":"睡眠不足会打乱身体天然的荷尔蒙平衡。","extra":""},{"chapter":21,"key":"21:71","id":71,"word":"immune","phonetic":"/ɪˈmjuːn/","pos":"adj.","meaningCN":"免疫的；不受影响的；免除的","tag":"核心","root":"mun(i) = service","exampleEN":"Regular exercise can strengthen your immune system.","exampleCN":"经常锻炼可以增强免疫系统。","extra":"immunise, immunity；immune to, immune system"},{"chapter":21,"key":"21:72","id":72,"word":"stimulus","phonetic":"/ˈstɪmjələs/","pos":"n.","meaningCN":"刺激（物）；促进因素","tag":"高频","root":"","exampleEN":"The tax cuts provided a strong stimulus to the economy.","exampleCN":"减税为经济提供了强有力的刺激。","extra":"复数 stimuli"},{"chapter":21,"key":"21:73","id":73,"word":"biorhythm","phonetic":"/ˈbaɪəʊˌrɪðəm/","pos":"n.","meaningCN":"生物节律","tag":"识记","root":"","exampleEN":"Travelling across time zones can disrupt your biorhythm for several days.","exampleCN":"跨越时区旅行可能会扰乱你好几天的生物节律。","extra":"rhythm n. 韵律；biorhythm upset"},{"chapter":21,"key":"21:74","id":74,"word":"lifestyle","phonetic":"/ˈlaɪfstaɪl/","pos":"n.","meaningCN":"生活方式","tag":"核心","root":"","exampleEN":"Adopting a healthy lifestyle can help prevent many chronic diseases.","exampleCN":"养成健康的生活方式有助于预防许多慢性病。","extra":""},{"chapter":21,"key":"21:75","id":75,"word":"habit","phonetic":"/ˈhæbɪt/","pos":"n.","meaningCN":"习惯","tag":"核心","root":"","exampleEN":"Getting up early became a daily habit for her over the years.","exampleCN":"多年来，早起成了她的一种日常习惯。","extra":"acquire a habit of"},{"chapter":21,"key":"21:76","id":76,"word":"sense","phonetic":"/sens/","pos":"n.","meaningCN":"感官；感觉","tag":"核心","root":"","exampleEN":"Humans have five basic senses: sight, hearing, smell, taste, and touch.","exampleCN":"人类有五种基本感官：视觉、听觉、嗅觉、味觉和触觉。","extra":"sensible, sensational, sensation, nonsense"},{"chapter":21,"key":"21:77","id":77,"word":"sight","phonetic":"/saɪt/","pos":"n.","meaningCN":"视力；看见；景物","tag":"核心","root":"","exampleEN":"The sunset over the ocean was the most beautiful sight she had ever seen.","exampleCN":"海上日落是她见过的最美丽的景象。","extra":"short-sighted"},{"chapter":21,"key":"21:78","id":78,"word":"eyesight","phonetic":"/ˈaɪsaɪt/","pos":"n.","meaningCN":"视力","tag":"核心","root":"","exampleEN":"Reading in dim light can strain your eyesight over time.","exampleCN":"在昏暗的光线下阅读久而久之会损害视力。","extra":""},{"chapter":21,"key":"21:79","id":79,"word":"view","phonetic":"/vjuː/","pos":"n.","meaningCN":"视野；见解；风景；察看","tag":"核心","root":"","exampleEN":"In my view, teamwork is the key to the success of this project.","exampleCN":"在我看来，团队合作是这一项目成功的关键。","extra":""},{"chapter":21,"key":"21:80","id":80,"word":"visual","phonetic":"/ˈvɪʒuəl/","pos":"adj.","meaningCN":"视力的，视觉的","tag":"核心","root":"","exampleEN":"The presentation included many visual aids to help explain the topic.","exampleCN":"演示中包含许多视觉教具来帮助解释主题。","extra":""},{"chapter":21,"key":"21:81","id":81,"word":"visible","phonetic":"/ˈvɪzəbl/","pos":"adj.","meaningCN":"看得见的，可见的","tag":"核心","root":"","exampleEN":"The satellite is sometimes visible to the naked eye on clear nights.","exampleCN":"在晴朗的夜晚，这颗卫星有时肉眼可见。","extra":"invisible"},{"chapter":21,"key":"21:82","id":82,"word":"vague","phonetic":"/veɪɡ/","pos":"adj.","meaningCN":"含糊的；不清楚的，模糊的","tag":"高频","root":"","exampleEN":"He could only give a vague description of the man he saw.","exampleCN":"他只能模糊地描述他所见到的那个人。","extra":""},{"chapter":21,"key":"21:83","id":83,"word":"blind","phonetic":"/blaɪnd/","pos":"adj.","meaningCN":"盲目的；瞎的；未察觉的","tag":"核心","root":"","exampleEN":"The dog became blind in one eye after the accident.","exampleCN":"那条狗在事故后一只眼睛失明了。","extra":""},{"chapter":21,"key":"21:84","id":84,"word":"dumb","phonetic":"/dʌm/","pos":"adj.","meaningCN":"哑的；不肯开口的","tag":"高频","root":"","exampleEN":"She remained dumb throughout the interview, too nervous to speak.","exampleCN":"她在整个采访中一声不吭，紧张得说不出话来。","extra":"dumb-bell n. 哑铃"},{"chapter":21,"key":"21:85","id":85,"word":"aural","phonetic":"/ˈɔːrəl/","pos":"adj.","meaningCN":"耳的；听觉的","tag":"低频","root":"","exampleEN":"Musicians usually develop excellent aural skills through years of training.","exampleCN":"音乐家通过多年训练通常会培养出极好的听觉能力。","extra":"acoustic"},{"chapter":21,"key":"21:86","id":86,"word":"dental","phonetic":"/ˈdentl/","pos":"adj.","meaningCN":"牙的，牙科的","tag":"高频","root":"dent = tooth","exampleEN":"Regular dental check-ups can help prevent cavities and gum disease.","exampleCN":"定期检查牙齿有助于预防蛀牙和牙龈疾病。","extra":"dentist"},{"chapter":21,"key":"21:87","id":87,"word":"awake","phonetic":"/əˈweɪk/","pos":"adj.","meaningCN":"醒着的；警觉的","tag":"核心","root":"","exampleEN":"Lying awake at night, she thought about the challenges of the next day.","exampleCN":"夜里醒着躺在床上，她思考着第二天的挑战。","extra":""},{"chapter":21,"key":"21:88","id":88,"word":"yawn","phonetic":"/jɔːn/","pos":"v.","meaningCN":"打呵欠；裂开 n. 呵欠","tag":"高频","root":"","exampleEN":"He tried to stifle a yawn during the long and boring meeting.","exampleCN":"在冗长无聊的会议上，他努力忍住了一个哈欠。","extra":"snore, sneeze"},{"chapter":21,"key":"21:89","id":89,"word":"nap","phonetic":"/næp/","pos":"n.","meaningCN":"小睡；绒毛","tag":"核心","root":"","exampleEN":"Taking a short nap in the afternoon can increase your productivity.","exampleCN":"下午小睡片刻可以提高你的工作效率。","extra":""},{"chapter":21,"key":"21:90","id":90,"word":"doze","phonetic":"/dəʊz/","pos":"v.","meaningCN":"小睡，打盹儿","tag":"高频","root":"","exampleEN":"The warm sunshine made me doze off in the armchair.","exampleCN":"暖暖的阳光让我在扶手椅上打起盹来。","extra":"dose"},{"chapter":21,"key":"21:91","id":91,"word":"quiet","phonetic":"/ˈkwaɪət/","pos":"adj.","meaningCN":"安静的；寂静的；平静的","tag":"核心","root":"","exampleEN":"The library should be a quiet place for students to study.","exampleCN":"图书馆应该是学生学习的安静场所。","extra":""},{"chapter":21,"key":"21:92","id":92,"word":"asleep","phonetic":"/əˈsliːp/","pos":"adj.","meaningCN":"睡着的；不活跃的；麻木的","tag":"核心","root":"","exampleEN":"The mother gently covered the child with a blanket when she fell asleep.","exampleCN":"孩子睡着后，母亲轻轻地给她盖上了毯子。","extra":"fall asleep"},{"chapter":21,"key":"21:93","id":93,"word":"cripple","phonetic":"/ˈkrɪpl/","pos":"n.","meaningCN":"跛子；残疾人 v. 使跛","tag":"低频","root":"","exampleEN":"The economic crisis threatened to cripple the country's financial system.","exampleCN":"经济危机有可能使该国的金融系统陷于瘫痪。","extra":""},{"chapter":21,"key":"21:94","id":94,"word":"lame","phonetic":"/leɪm/","pos":"adj.","meaningCN":"病的，跛的；（解释或借口）无说服力的","tag":"高频","root":"","exampleEN":"He offered a very lame excuse for not finishing the work on time.","exampleCN":"他没按时完成工作，给出的借口十分站不住脚。","extra":""},{"chapter":21,"key":"21:95","id":95,"word":"dwarf","phonetic":"/dwɔːf/","pos":"n.","meaningCN":"（童话中的）小矮人；侏儒 adj. 矮小的","tag":"低频","root":"","exampleEN":"In the story, Snow White lived with seven dwarfs in a small cottage.","exampleCN":"故事中，白雪公主与七个小矮人住在一间小木屋里。","extra":"Snow White and the Seven Dwarfs"},{"chapter":21,"key":"21:96","id":96,"word":"pregnancy","phonetic":"/ˈpreɡnənsi/","pos":"n.","meaningCN":"怀孕，妊娠","tag":"高频","root":"","exampleEN":"She decided to take a pregnancy test after missing her period.","exampleCN":"月经没有来之后，她决定做一次怀孕检测。","extra":"pregnant；a pregnancy test"},{"chapter":21,"key":"21:97","id":97,"word":"moan","phonetic":"/məʊn/","pos":"n./v.","meaningCN":"呻吟；哀悼","tag":"高频","root":"","exampleEN":"The injured hiker let out a low moan when rescuers finally found him.","exampleCN":"当救援人员最终找到受伤的徒步者时，他发出了一声低沉的呻吟。","extra":""},{"chapter":21,"key":"21:98","id":98,"word":"born","phonetic":"/bɔːn/","pos":"adj.","meaningCN":"天生的；与生俱来的 v. [be-]出生","tag":"核心","root":"","exampleEN":"She is a born musician and started playing the piano at the age of four.","exampleCN":"她天生是音乐家，四岁就开始弹钢琴了。","extra":"be born of"},{"chapter":21,"key":"21:99","id":99,"word":"condom","phonetic":"/ˈkɒndəm/","pos":"n.","meaningCN":"避孕套","tag":"识记","root":"","exampleEN":"Health organisations often promote the use of condoms to prevent infections.","exampleCN":"卫生组织经常提倡使用避孕套来预防感染。","extra":"French letter"},{"chapter":21,"key":"21:100","id":100,"word":"infection","phonetic":"/ɪnˈfekʃən/","pos":"n.","meaningCN":"传染；传染病；影响","tag":"核心","root":"","exampleEN":"Wash your hands regularly to reduce the risk of bacterial infection.","exampleCN":"勤洗手以降低细菌感染的风险。","extra":"infect, infectious；a bacterial infection"},{"chapter":21,"key":"21:101","id":101,"word":"clone","phonetic":"/kləʊn/","pos":"v.","meaningCN":"克隆 n. 克隆动物（或植物）","tag":"低频","root":"","exampleEN":"Scientists have been debating the ethics of cloning humans for decades.","exampleCN":"几十年来，科学家们一直在争论克隆人的伦理问题。","extra":""},{"chapter":21,"key":"21:102","id":102,"word":"detriment","phonetic":"/ˈdetrɪmənt/","pos":"n.","meaningCN":"损害；损害物","tag":"低频","root":"","exampleEN":"Excessive screen time can be a detriment to young children's development.","exampleCN":"过多的屏幕时间可能对幼儿的发育造成损害。","extra":""},{"chapter":21,"key":"21:103","id":103,"word":"symptom","phonetic":"/ˈsɪmptəm/","pos":"n.","meaningCN":"征兆；症状","tag":"核心","root":"","exampleEN":"A high fever and a cough are common symptoms of the flu.","exampleCN":"高烧和咳嗽是流感的常见症状。","extra":""},{"chapter":21,"key":"21:104","id":104,"word":"disease","phonetic":"/dɪˈziːz/","pos":"n.","meaningCN":"疾病","tag":"核心","root":"","exampleEN":"Heart disease remains one of the leading causes of death worldwide.","exampleCN":"心脏病仍然是全球主要的死亡原因之一。","extra":"cause a disease"},{"chapter":21,"key":"21:105","id":105,"word":"illness","phonetic":"/ˈɪlnəs/","pos":"n.","meaningCN":"病，疾病","tag":"核心","root":"","exampleEN":"It took him nearly a month to recover from his illness.","exampleCN":"他花了将近一个月才从疾病中康复。","extra":"recover from illness"},{"chapter":21,"key":"21:106","id":106,"word":"broken","phonetic":"/ˈbrəʊkən/","pos":"adj.","meaningCN":"弄坏的；破碎的","tag":"核心","root":"","exampleEN":"The microwave is broken, so we'll have to heat the food on the stove.","exampleCN":"微波炉坏了，所以我们只能在炉子上热饭菜。","extra":"a broken talk"},{"chapter":21,"key":"21:107","id":107,"word":"disable","phonetic":"/dɪsˈeɪbəl/","pos":"v.","meaningCN":"使丧失能力，使伤残","tag":"高频","root":"","exampleEN":"The explosion disabled the ship's main engine, leaving it stranded at sea.","exampleCN":"爆炸使船的主引擎失灵，船被困在了海上。","extra":"disabled"},{"chapter":21,"key":"21:108","id":108,"word":"invalid","phonetic":"/ˈɪnvəlɪd/","pos":"n.","meaningCN":"病弱者，伤残者 adj. 病弱的，伤残的","tag":"低频","root":"","exampleEN":"She took care of her invalid father for many years without complaint.","exampleCN":"她毫无怨言地照顾生病的父亲很多年。","extra":"invalidate"},{"chapter":21,"key":"21:109","id":109,"word":"patient","phonetic":"/ˈpeɪʃənt/","pos":"n.","meaningCN":"病人 adj. 有耐心的，能忍耐的","tag":"核心","root":"pati, pathy = to suffer, to endure","exampleEN":"You need to be patient when learning a new skill; progress takes time.","exampleCN":"学习新技能时你需要有耐心，进步需要时间。","extra":"patience"},{"chapter":21,"key":"21:110","id":110,"word":"dysfunction","phonetic":"/dɪsˈfʌŋkʃən/","pos":"n.","meaningCN":"（身体）功能障碍","tag":"低频","root":"dys- = bad, abnormal","exampleEN":"The disease caused severe kidney dysfunction in many patients.","exampleCN":"这种疾病导致许多病人出现严重的肾功能障碍。","extra":""},{"chapter":21,"key":"21:111","id":111,"word":"diabetes","phonetic":"/ˌdaɪəˈbiːtiːz/","pos":"n.","meaningCN":"糖尿病","tag":"高频","root":"","exampleEN":"People with diabetes need to monitor their blood sugar levels regularly.","exampleCN":"糖尿病患者需要定期监测自己的血糖水平。","extra":""},{"chapter":21,"key":"21:112","id":112,"word":"obesity","phonetic":"/əʊˈbiːsəti/","pos":"n.","meaningCN":"（过度）肥胖；肥胖症","tag":"高频","root":"","exampleEN":"Childhood obesity has become a serious public health issue in many countries.","exampleCN":"儿童肥胖已成为许多国家一个严重的公共卫生问题。","extra":"obese；obesity index"},{"chapter":21,"key":"21:113","id":113,"word":"overweight","phonetic":"/ˌəʊvəˈweɪt/","pos":"adj.","meaningCN":"超重的，过胖的 n. 超重 v. 使超重；过于重视","tag":"核心","root":"","exampleEN":"The doctor advised him to exercise more because he was slightly overweight.","exampleCN":"医生建议他多运动，因为他略微超重了。","extra":"weigh, weight"},{"chapter":21,"key":"21:114","id":114,"word":"hypertension","phonetic":"/ˌhaɪpəˈtenʃən/","pos":"n.","meaningCN":"高血压","tag":"低频","root":"","exampleEN":"Hypertension is often called the silent killer because it has few symptoms.","exampleCN":"高血压常被称为沉默的杀手，因为它几乎没有症状。","extra":""},{"chapter":21,"key":"21:115","id":115,"word":"paralyse","phonetic":"/ˈpærəlaɪz/","pos":"v.","meaningCN":"使麻痹；使瘫痪；使无助","tag":"高频","root":"","exampleEN":"Heavy snowfall paralysed the city's transport system for several days.","exampleCN":"大雪使城市的交通系统瘫痪了好几天。","extra":"paralysis, paralysed"},{"chapter":21,"key":"21:116","id":116,"word":"dizzy","phonetic":"/ˈdɪzi/","pos":"adj.","meaningCN":"头晕目眩的，眩晕的 v. 使眩晕","tag":"核心","root":"","exampleEN":"Standing up too fast can sometimes make you feel dizzy.","exampleCN":"站起来太快有时会让你感到头晕。","extra":""},{"chapter":21,"key":"21:117","id":117,"word":"insane","phonetic":"/ɪnˈseɪn/","pos":"adj.","meaningCN":"患精神病的；疯狂的","tag":"高频","root":"san = healthy","exampleEN":"It would be insane to go hiking in the mountains during a storm.","exampleCN":"在暴风雨中去山里徒步简直是疯了。","extra":"an insane asylum"},{"chapter":21,"key":"21:118","id":118,"word":"insomnia","phonetic":"/ɪnˈsɒmniə/","pos":"n.","meaningCN":"失眠，失眠症","tag":"高频","root":"","exampleEN":"Chronic stress and anxiety can often lead to severe insomnia.","exampleCN":"长期的压力和焦虑常常会导致严重失眠。","extra":"Hypnos, Somnus, Thanatos"},{"chapter":21,"key":"21:119","id":119,"word":"allergy","phonetic":"/ˈælədʒi/","pos":"n.","meaningCN":"敏感症；过敏性","tag":"高频","root":"","exampleEN":"She has a severe allergy to peanuts and must check all food labels carefully.","exampleCN":"她对花生严重过敏，必须仔细检查所有食品标签。","extra":""},{"chapter":21,"key":"21:120","id":120,"word":"heart attack","phonetic":"/hɑːt əˈtæk/","pos":"n.","meaningCN":"心脏病发作","tag":"核心","root":"","exampleEN":"Knowing the early signs of a heart attack can save someone's life.","exampleCN":"了解心脏病发作的早期征兆可以挽救别人的生命。","extra":""},{"chapter":21,"key":"21:121","id":121,"word":"cancer","phonetic":"/ˈkænsə/","pos":"n.","meaningCN":"癌","tag":"核心","root":"","exampleEN":"Early detection greatly increases the chance of surviving cancer.","exampleCN":"早期发现大大增加了癌症的存活几率。","extra":""},{"chapter":21,"key":"21:122","id":122,"word":"arthritis","phonetic":"/ɑːˈθraɪtɪs/","pos":"n.","meaningCN":"关节炎","tag":"低频","root":"","exampleEN":"Cold weather tends to make the pain from arthritis worse.","exampleCN":"寒冷的天气往往会使关节炎的疼痛加剧。","extra":""},{"chapter":21,"key":"21:123","id":123,"word":"pimple","phonetic":"/ˈpɪmpəl/","pos":"n.","meaningCN":"粉刺，丘疹","tag":"高频","root":"","exampleEN":"Hormonal changes during adolescence can cause pimples to appear.","exampleCN":"青春期的荷尔蒙变化会导致粉刺出现。","extra":"dimple, mole, freckle, wrinkle"},{"chapter":21,"key":"21:124","id":124,"word":"stroke","phonetic":"/strəʊk/","pos":"n.","meaningCN":"中风；击打；一笔（画）","tag":"高频","root":"","exampleEN":"High blood pressure significantly increases the risk of having a stroke.","exampleCN":"高血压会显著增加中风的风险。","extra":""},{"chapter":21,"key":"21:125","id":125,"word":"plague","phonetic":"/pleɪɡ/","pos":"n.","meaningCN":"瘟疫","tag":"低频","root":"","exampleEN":"The plague caused a sharp decline in the population of Europe in the 14th century.","exampleCN":"14世纪的瘟疫导致欧洲人口急剧下降。","extra":""},{"chapter":21,"key":"21:126","id":126,"word":"flu","phonetic":"/fluː/","pos":"n.","meaningCN":"流行性感冒","tag":"核心","root":"","exampleEN":"Millions of people get the seasonal flu shot every year to stay healthy.","exampleCN":"每年有数百万人接种季节性流感疫苗以保持健康。","extra":"fluent, fluency；influenza 源自意大利语"},{"chapter":21,"key":"21:127","id":127,"word":"fever","phonetic":"/ˈfiːvə/","pos":"n.","meaningCN":"狂热；发烧，发热 v. （使）发烧；（使）狂热","tag":"核心","root":"","exampleEN":"She stayed home from work because she had a high fever and a headache.","exampleCN":"她因为发高烧和头疼而待在家里没去上班。","extra":"catch a fever"},{"chapter":21,"key":"21:128","id":128,"word":"headache","phonetic":"/ˈhedeɪk/","pos":"n.","meaningCN":"头痛","tag":"核心","root":"","exampleEN":"Spending too much time in front of a screen can give you a headache.","exampleCN":"花太多时间盯着屏幕会让你头痛。","extra":""},{"chapter":21,"key":"21:129","id":129,"word":"swell","phonetic":"/swel/","pos":"v.","meaningCN":"肿胀，膨胀；（使）增加","tag":"高频","root":"","exampleEN":"Her ankle began to swell shortly after she twisted it during the game.","exampleCN":"她在比赛中扭伤脚踝后不久，脚踝就开始肿了。","extra":""},{"chapter":21,"key":"21:130","id":130,"word":"choke","phonetic":"/tʃəʊk/","pos":"v.","meaningCN":"（使）窒息；阻塞；说不出话","tag":"高频","root":"","exampleEN":"A piece of food got stuck in his throat and he started to choke.","exampleCN":"一块食物卡在他的喉咙里，他开始窒息了。","extra":""},{"chapter":21,"key":"21:131","id":131,"word":"injure","phonetic":"/ˈɪndʒə/","pos":"v.","meaningCN":"伤害，使遭受损伤；损害","tag":"核心","root":"","exampleEN":"Several passengers were slightly injured in the bus accident.","exampleCN":"在这起公交车事故中，有数名乘客受了轻伤。","extra":"injure sb.'s self-esteem"},{"chapter":21,"key":"21:132","id":132,"word":"injury","phonetic":"/ˈɪndʒəri/","pos":"n.","meaningCN":"伤害；损害","tag":"核心","root":"","exampleEN":"He missed the final match due to a serious knee injury.","exampleCN":"由于严重的膝伤，他错过了决赛。","extra":""},{"chapter":21,"key":"21:133","id":133,"word":"hurt","phonetic":"/hɜːt/","pos":"v.","meaningCN":"损害；伤害；（使）疼痛","tag":"核心","root":"","exampleEN":"It really hurts when someone you trust betrays you.","exampleCN":"当你信任的人背叛你时，真的很受伤。","extra":"hurt sb.'s reputation"},{"chapter":21,"key":"21:134","id":134,"word":"bleed","phonetic":"/bliːd/","pos":"v.","meaningCN":"流血；榨取；给......放血；放掉（水或气体）","tag":"核心","root":"","exampleEN":"Apply pressure to the wound to stop it from bleeding.","exampleCN":"按压伤口以阻止其流血。","extra":"blood, cold-blooded"},{"chapter":21,"key":"21:135","id":135,"word":"bruise","phonetic":"/bruːz/","pos":"n.","meaningCN":"淤伤；伤痕 v. 擦伤","tag":"高频","root":"","exampleEN":"He had a dark bruise on his arm from the fall during football practice.","exampleCN":"他在足球训练中摔了一跤，手臂上留下了一块深色的淤青。","extra":""},{"chapter":21,"key":"21:136","id":136,"word":"scar","phonetic":"/skɑː/","pos":"n.","meaningCN":"疤痕，伤疤","tag":"高频","root":"","exampleEN":"The surgery left a small scar, but it faded over time.","exampleCN":"手术留下了一个小伤疤，但随着时间的推移慢慢变淡了。","extra":""},{"chapter":21,"key":"21:137","id":137,"word":"wound","phonetic":"/wuːnd/","pos":"n.","meaningCN":"创伤，伤害；伤口","tag":"核心","root":"","exampleEN":"The soldier's wound healed slowly but eventually he recovered fully.","exampleCN":"那位士兵的伤口愈合得很慢，但最终完全康复了。","extra":""},{"chapter":21,"key":"21:138","id":138,"word":"trauma","phonetic":"/ˈtrɔːmə/","pos":"n.","meaningCN":"外伤，身体上的伤；精神创伤；痛苦经历","tag":"低频","root":"","exampleEN":"Many children who experienced the disaster are still dealing with the emotional trauma.","exampleCN":"许多经历过那场灾难的儿童仍在应对心理创伤。","extra":"traumatic, psychotrauma"},{"chapter":21,"key":"21:139","id":139,"word":"lump","phonetic":"/lʌmp/","pos":"n.","meaningCN":"块；肿块 v. 使成块状","tag":"高频","root":"","exampleEN":"She found a small lump on her neck and decided to consult a doctor.","exampleCN":"她在脖子上发现一个小肿块，决定去看医生。","extra":""},{"chapter":21,"key":"21:140","id":140,"word":"pain","phonetic":"/peɪn/","pos":"n.","meaningCN":"痛苦；疼痛 v. 使痛苦","tag":"核心","root":"","exampleEN":"The medication helped ease the sharp pain in his lower back.","exampleCN":"药物帮助缓解了他腰部的剧痛。","extra":"painful"},{"chapter":21,"key":"21:141","id":141,"word":"death","phonetic":"/deθ/","pos":"n.","meaningCN":"死，死亡；毁灭","tag":"核心","root":"","exampleEN":"The sudden death of the leader left the community in shock.","exampleCN":"领导人的突然离世让社区陷入了震惊。","extra":"deadly, dying"},{"chapter":21,"key":"21:142","id":142,"word":"mortal","phonetic":"/ˈmɔːtl/","pos":"adj.","meaningCN":"必死的；致命的 n. 凡人，人类","tag":"低频","root":"","exampleEN":"The myth tells the story of a mortal man who challenged the gods.","exampleCN":"这个神话讲述了一个凡人挑战众神的故事。","extra":"immortal, mortality；a mortal wound, mortal combat"},{"chapter":21,"key":"21:143","id":143,"word":"demise","phonetic":"/dɪˈmaɪz/","pos":"n.","meaningCN":"死亡；君权的转移或授予，禅让 v. 遗赠；转让","tag":"识记","root":"","exampleEN":"The demise of the old political system paved the way for democratic reforms.","exampleCN":"旧政治制度的消亡为民主改革铺平了道路。","extra":"deadliness"},{"chapter":21,"key":"21:144","id":144,"word":"doom","phonetic":"/duːm/","pos":"n.","meaningCN":"厄运；毁灭 v. 使注定失败（或死亡等）","tag":"高频","root":"","exampleEN":"Without proper funding, the project was doomed to fail from the start.","exampleCN":"没有足够的资金，这个项目从一开始就注定会失败。","extra":"doom sth. to, meet one's doom；mood 反过来 → doom"},{"chapter":21,"key":"21:145","id":145,"word":"fatal","phonetic":"/ˈfeɪtl/","pos":"adj.","meaningCN":"致命的；毁灭性的；决定性的","tag":"高频","root":"","exampleEN":"The driver suffered fatal injuries in the high-speed crash.","exampleCN":"在高速撞车事故中，司机受到了致命伤。","extra":""},{"chapter":21,"key":"21:146","id":146,"word":"lethal","phonetic":"/ˈliːθəl/","pos":"adj.","meaningCN":"致命的","tag":"低频","root":"","exampleEN":"Certain chemicals can be lethal to fish and other aquatic life.","exampleCN":"某些化学物质对鱼类和其他水生生物可能是致命的。","extra":""},{"chapter":21,"key":"21:147","id":147,"word":"corpus","phonetic":"/ˈkɔːpəs/","pos":"n.","meaningCN":"尸体；文集；本金","tag":"识记","root":"corp = body","exampleEN":"Linguists use a large corpus of texts to study how language is actually used.","exampleCN":"语言学家使用大型语料库来研究语言的实际使用方式。","extra":""},{"chapter":21,"key":"21:148","id":148,"word":"overwork","phonetic":"/ˌəʊvəˈwɜːk/","pos":"n.","meaningCN":"过度操劳；过度工作 v. （使）过度工作","tag":"高频","root":"","exampleEN":"Many employees suffer from burnout because of chronic overwork.","exampleCN":"许多员工由于长期过度工作而心力交瘁。","extra":""},{"chapter":21,"key":"21:149","id":149,"word":"tire","phonetic":"/ˈtaɪə/","pos":"v.","meaningCN":"（使）感到疲劳；厌烦","tag":"核心","root":"","exampleEN":"Long study sessions tire the brain, so short breaks are essential.","exampleCN":"长时间学习会使大脑疲倦，所以短暂的休息十分必要。","extra":"tired"},{"chapter":21,"key":"21:150","id":150,"word":"exhaust","phonetic":"/ɪɡˈzɔːst/","pos":"v.","meaningCN":"使精疲力竭；用完，耗尽","tag":"核心","root":"","exampleEN":"The long journey exhausted all his energy, and he fell asleep immediately.","exampleCN":"长途旅行耗尽了他所有的精力，他立刻就睡着了。","extra":"exhausted"},{"chapter":21,"key":"21:151","id":151,"word":"fatigue","phonetic":"/fəˈtiːɡ/","pos":"n.","meaningCN":"疲劳 v. （使）疲劳","tag":"高频","root":"","exampleEN":"Driver fatigue is a major cause of road accidents.","exampleCN":"驾驶疲劳是道路交通事故的一个主要原因。","extra":""},{"chapter":21,"key":"21:152","id":152,"word":"faint","phonetic":"/feɪnt/","pos":"adj.","meaningCN":"模糊的；微弱的；虚弱的 v. 晕倒","tag":"高频","root":"","exampleEN":"There is still a faint hope that the missing hiker will be found alive.","exampleCN":"失踪的徒步者仍然有一线希望被活着找到。","extra":""},{"chapter":21,"key":"21:153","id":153,"word":"feeble","phonetic":"/ˈfiːbəl/","pos":"adj.","meaningCN":"虚弱的，无力的；微弱的","tag":"低频","root":"","exampleEN":"His voice was so feeble that we could barely hear him at the back of the room.","exampleCN":"他的声音非常微弱，我们在房间后面几乎听不到他说话。","extra":""},{"chapter":21,"key":"21:154","id":154,"word":"weary","phonetic":"/ˈwɪəri/","pos":"adj.","meaningCN":"疲倦的；厌烦的","tag":"低频","root":"","exampleEN":"She was weary of the endless meetings that seemed to have no purpose.","exampleCN":"她厌倦了那些似乎毫无目的的没完没了的会议。","extra":"be weary of"},{"chapter":21,"key":"21:155","id":155,"word":"weaken","phonetic":"/ˈwiːkən/","pos":"v.","meaningCN":"减弱，削弱；变软弱","tag":"核心","root":"","exampleEN":"The constant criticism began to weaken her confidence and motivation.","exampleCN":"持续不断的批评开始削弱她的信心和动力。","extra":"weak, weakly, weakness"},{"chapter":21,"key":"21:156","id":156,"word":"uncomfortable","phonetic":"/ʌnˈkʌmftəbəl/","pos":"adj.","meaningCN":"不舒服的；不自在的","tag":"核心","root":"","exampleEN":"These shoes are too tight and make my feet very uncomfortable.","exampleCN":"这双鞋太紧了，让我的脚非常不舒服。","extra":"comfortable, comfort"},{"chapter":21,"key":"21:157","id":157,"word":"unconscious","phonetic":"/ʌnˈkɒnʃəs/","pos":"adj.","meaningCN":"失去知觉的；无意识的","tag":"高频","root":"","exampleEN":"The boxer was knocked unconscious for a few seconds after the heavy punch.","exampleCN":"那位拳击手受到重击后昏迷了几秒钟。","extra":"conscious, consciousness, conscience"},{"chapter":21,"key":"21:158","id":158,"word":"chronic","phonetic":"/ˈkrɒnɪk/","pos":"adj.","meaningCN":"慢性的；长期的","tag":"高频","root":"chron = time","exampleEN":"Chronic back pain forced him to change his lifestyle and work habits.","exampleCN":"慢性背痛迫使他改变了生活方式和工作习惯。","extra":"a chronic disease"},{"chapter":21,"key":"21:159","id":159,"word":"acute","phonetic":"/əˈkjuːt/","pos":"adj.","meaningCN":"（疾病）急性的；敏锐的，深刻的","tag":"高频","root":"","exampleEN":"There is an acute shortage of clean water in the disaster-affected area.","exampleCN":"受灾害影响的地区清洁水严重短缺。","extra":""},{"chapter":21,"key":"21:160","id":160,"word":"sore","phonetic":"/sɔː/","pos":"adj.","meaningCN":"疼痛的；恼火的；严重的","tag":"核心","root":"","exampleEN":"After the long hike, his legs were sore and he could barely walk.","exampleCN":"长途徒步后，他的双腿酸痛，几乎走不动路。","extra":""},{"chapter":21,"key":"21:161","id":161,"word":"sorrow","phonetic":"/ˈsɒrəʊ/","pos":"n.","meaningCN":"悲伤，悲痛","tag":"高频","root":"","exampleEN":"She poured out her sorrow in a long letter to her best friend.","exampleCN":"她在一封给最好朋友的长信中倾诉了自己的悲伤。","extra":""},{"chapter":21,"key":"21:162","id":162,"word":"suffering","phonetic":"/ˈsʌfərɪŋ/","pos":"n.","meaningCN":"苦难，折磨","tag":"核心","root":"","exampleEN":"The charity works to reduce the suffering of people affected by famine.","exampleCN":"该慈善机构致力于减轻受饥荒影响的人们的苦难。","extra":""},{"chapter":21,"key":"21:163","id":163,"word":"lament","phonetic":"/ləˈment/","pos":"n.","meaningCN":"悲伤，哀悼 v. 哀悼；对......感到悔恨","tag":"低频","root":"","exampleEN":"Many poets have lamented the loss of natural beauty in their works.","exampleCN":"许多诗人在作品中哀叹自然美的丧失。","extra":""},{"chapter":21,"key":"21:164","id":164,"word":"fitness","phonetic":"/ˈfɪtnəs/","pos":"n.","meaningCN":"健康；适合","tag":"核心","root":"","exampleEN":"Regular running and a balanced diet are essential for maintaining good fitness.","exampleCN":"经常跑步和均衡饮食对于保持良好的健康至关重要。","extra":"fit；a fitness centre"},{"chapter":21,"key":"21:165","id":165,"word":"hospital","phonetic":"/ˈhɒspɪtl/","pos":"n.","meaningCN":"医院","tag":"核心","root":"","exampleEN":"The new hospital will provide better medical services for the local residents.","exampleCN":"新医院将为当地居民提供更好的医疗服务。","extra":"host, hospital, hostel, hotel, hospitality"},{"chapter":21,"key":"21:166","id":166,"word":"therapy","phonetic":"/ˈθerəpi/","pos":"n.","meaningCN":"治疗","tag":"核心","root":"","exampleEN":"She goes to physical therapy twice a week to recover from the knee surgery.","exampleCN":"她每周进行两次物理治疗，以便从膝关节手术中恢复。","extra":"therapist"},{"chapter":21,"key":"21:167","id":167,"word":"health care","phonetic":"/helθ keə/","pos":"n.","meaningCN":"医疗保健","tag":"核心","root":"","exampleEN":"Access to affordable health care is a basic human right in many countries.","exampleCN":"在许多国家，获得负担得起的医疗保健是一项基本人权。","extra":""},{"chapter":21,"key":"21:168","id":168,"word":"sanitary","phonetic":"/ˈsænətəri/","pos":"adj.","meaningCN":"卫生的；清洁的","tag":"高频","root":"","exampleEN":"Poor sanitary conditions can lead to the rapid spread of diseases.","exampleCN":"恶劣的卫生条件会导致疾病的迅速传播。","extra":""},{"chapter":21,"key":"21:169","id":169,"word":"medical","phonetic":"/ˈmedɪkəl/","pos":"adj.","meaningCN":"医学的，医疗的","tag":"核心","root":"","exampleEN":"The medical team worked around the clock to treat the injured patients.","exampleCN":"医疗小组夜以继日地救治受伤的病人。","extra":""},{"chapter":21,"key":"21:170","id":170,"word":"curative","phonetic":"/ˈkjʊərətɪv/","pos":"adj.","meaningCN":"治疗的 n. 药品","tag":"低频","root":"","exampleEN":"Some traditional herbs are believed to have strong curative properties.","exampleCN":"一些传统草药被认为具有很好的治疗功效。","extra":""},{"chapter":21,"key":"21:171","id":171,"word":"hygiene","phonetic":"/ˈhaɪdʒiːn/","pos":"n.","meaningCN":"卫生（学）；保健（学）","tag":"高频","root":"","exampleEN":"Good hand hygiene is one of the simplest ways to prevent infection.","exampleCN":"保持良好的手部卫生是预防感染最简单的方法之一。","extra":"Hygieia"},{"chapter":21,"key":"21:172","id":172,"word":"clinic","phonetic":"/ˈklɪnɪk/","pos":"n.","meaningCN":"诊所；门诊部","tag":"核心","root":"","exampleEN":"The dental clinic opens at 8 a.m. on weekdays for routine check-ups.","exampleCN":"牙科诊所工作日早上八点开门，提供常规检查。","extra":"clinical；a school clinic"},{"chapter":21,"key":"21:173","id":173,"word":"physician","phonetic":"/fɪˈzɪʃən/","pos":"n.","meaningCN":"内科医生","tag":"高频","root":"","exampleEN":"The physician carefully examined the patient's symptoms before making a diagnosis.","exampleCN":"内科医生在下诊断之前仔细检查了病人的症状。","extra":""},{"chapter":21,"key":"21:174","id":174,"word":"surgeon","phonetic":"/ˈsɜːdʒən/","pos":"n.","meaningCN":"外科医生","tag":"高频","root":"","exampleEN":"The heart surgeon completed the complex operation in just under six hours.","exampleCN":"这位心脏外科医生用了不到六个小时就完成了那台复杂的手术。","extra":"surgery"},{"chapter":21,"key":"21:175","id":175,"word":"operation","phonetic":"/ˌɒpəˈreɪʃən/","pos":"n.","meaningCN":"手术；操作；运转，经营","tag":"核心","root":"","exampleEN":"The rescue operation involved helicopters, boats, and dozens of volunteers.","exampleCN":"这场救援行动出动了直升机、船只和数十名志愿者。","extra":"operator；perform an operation"},{"chapter":21,"key":"21:176","id":176,"word":"cure","phonetic":"/kjʊə/","pos":"v.","meaningCN":"治好，治愈 n. 疗法；治疗","tag":"核心","root":"","exampleEN":"Scientists are still trying to find a cure for the common cold.","exampleCN":"科学家们仍在试图找到治疗普通感冒的方法。","extra":""},{"chapter":21,"key":"21:177","id":177,"word":"heal","phonetic":"/hiːl/","pos":"v.","meaningCN":"治愈；愈合","tag":"核心","root":"","exampleEN":"Time can heal emotional wounds, but support from loved ones helps a lot.","exampleCN":"时间可以治愈情感创伤，但来自亲人的支持也有很大帮助。","extra":"heal-all"},{"chapter":21,"key":"21:178","id":178,"word":"treatment","phonetic":"/ˈtriːtmənt/","pos":"n.","meaningCN":"治疗，疗法；待遇","tag":"核心","root":"","exampleEN":"The new treatment has shown promising results in clinical trials.","exampleCN":"这种新疗法在临床试验中显示出了很好的效果。","extra":"treat"},{"chapter":21,"key":"21:179","id":179,"word":"check","phonetic":"/tʃek/","pos":"v.","meaningCN":"检查，核对 n. [美] 账单","tag":"核心","root":"","exampleEN":"Remember to check your passport expiry date before booking a flight.","exampleCN":"预订航班之前记得检查一下护照的有效期。","extra":""},{"chapter":21,"key":"21:180","id":180,"word":"prescription","phonetic":"/prɪˈskrɪpʃən/","pos":"n.","meaningCN":"处方，药方；秘诀","tag":"高频","root":"","exampleEN":"This medicine is only available with a prescription from your doctor.","exampleCN":"这种药只有凭医生处方才能买到。","extra":"prescribe；prescription drug, over-the-counter (OTC)"},{"chapter":21,"key":"21:181","id":181,"word":"transplant","phonetic":"/trænsˈplɑːnt/","pos":"v.","meaningCN":"移植","tag":"低频","root":"","exampleEN":"The doctors successfully transplanted a kidney from the donor to the patient.","exampleCN":"医生们成功地将捐赠者的肾脏移植到了病人体内。","extra":""},{"chapter":21,"key":"21:182","id":182,"word":"X-ray","phonetic":"/ˈeks reɪ/","pos":"n.","meaningCN":"X 射线；用 X 射线进行的临床检查 v. 用 X 射线检查","tag":"高频","root":"","exampleEN":"The doctor took an X-ray of his chest to check for any signs of infection.","exampleCN":"医生给他的胸部拍了X光片，检查是否有任何感染的迹象。","extra":""},{"chapter":21,"key":"21:183","id":183,"word":"injection","phonetic":"/ɪnˈdʒekʃən/","pos":"n.","meaningCN":"注射；注射物；单射（函数）","tag":"高频","root":"","exampleEN":"The nurse prepared the injection carefully before giving it to the child.","exampleCN":"护士在给小孩注射之前仔细地准备好了注射剂。","extra":"inject；give sb. an injection"},{"chapter":21,"key":"21:184","id":184,"word":"precaution","phonetic":"/prɪˈkɔːʃən/","pos":"n.","meaningCN":"预防，警惕；预防措施","tag":"高频","root":"","exampleEN":"As a precaution, the school was closed when the storm warning was issued.","exampleCN":"作为预防措施，暴风雨警报发布后学校就关闭了。","extra":""},{"chapter":21,"key":"21:185","id":185,"word":"vaccinate","phonetic":"/ˈvæksɪneɪt/","pos":"v.","meaningCN":"给......接种疫苗，预防接种","tag":"高频","root":"","exampleEN":"Many health experts encourage parents to vaccinate their children against measles.","exampleCN":"许多健康专家鼓励父母给孩子接种麻疹疫苗。","extra":""},{"chapter":21,"key":"21:186","id":186,"word":"quarantine","phonetic":"/ˈkwɒrəntiːn/","pos":"v.","meaningCN":"对......进行隔离检疫 n. 检疫；隔离检疫期","tag":"低频","root":"","exampleEN":"The passengers were put in quarantine for fourteen days to prevent the spread of the disease.","exampleCN":"为了防止疾病传播，乘客们被隔离检疫了十四天。","extra":""},{"chapter":21,"key":"21:187","id":187,"word":"segregate","phonetic":"/ˈseɡrɪɡeɪt/","pos":"v.","meaningCN":"隔离","tag":"低频","root":"","exampleEN":"The hospital decided to segregate patients with the virus from the general wards.","exampleCN":"医院决定将感染该病毒的患者与普通病房隔离开来。","extra":"separate"},{"chapter":21,"key":"21:188","id":188,"word":"isolate","phonetic":"/ˈaɪsəleɪt/","pos":"v.","meaningCN":"使隔离，使孤立，使脱离","tag":"核心","root":"","exampleEN":"The remote village was isolated from the rest of the country during the heavy snow.","exampleCN":"大雪期间，那个偏远村庄与该国的其他地方隔绝了。","extra":"insula = island"},{"chapter":21,"key":"21:189","id":189,"word":"pharmacy","phonetic":"/ˈfɑːməsi/","pos":"n.","meaningCN":"药店；药剂学","tag":"高频","root":"","exampleEN":"You can buy painkillers at any local pharmacy without a prescription.","exampleCN":"你可以在任何当地的药店无需处方购买止痛药。","extra":"pharmacist, pharmaceutical"},{"chapter":21,"key":"21:190","id":190,"word":"medicine","phonetic":"/ˈmedɪsən/","pos":"n.","meaningCN":"药；医学","tag":"核心","root":"","exampleEN":"Traditional Chinese medicine has a history of thousands of years.","exampleCN":"传统中医有几千年的历史。","extra":"medicinal"},{"chapter":21,"key":"21:191","id":191,"word":"remedy","phonetic":"/ˈremədi/","pos":"n.","meaningCN":"药物，治疗法；解决方法","tag":"高频","root":"","exampleEN":"The government is trying to find a remedy for the rising unemployment rate.","exampleCN":"政府正试图为不断上升的失业率找到解决办法。","extra":""},{"chapter":21,"key":"21:192","id":192,"word":"drug","phonetic":"/drʌɡ/","pos":"n.","meaningCN":"毒品；药","tag":"核心","root":"","exampleEN":"The new drug has been proven to dramatically lower blood pressure.","exampleCN":"这种新药已被证明能大幅降低血压。","extra":""},{"chapter":21,"key":"21:193","id":193,"word":"pill","phonetic":"/pɪl/","pos":"n.","meaningCN":"药丸，丸剂","tag":"核心","root":"","exampleEN":"She takes a vitamin pill every morning with her breakfast.","exampleCN":"她每天早餐时服用一粒维生素丸。","extra":""},{"chapter":21,"key":"21:194","id":194,"word":"antibiotic","phonetic":"/ˌæntibaɪˈɒtɪk/","pos":"n.","meaningCN":"抗生素","tag":"高频","root":"","exampleEN":"You should finish the full course of antibiotics even if you start to feel better.","exampleCN":"即使开始感觉好转，你也应该服完整个疗程的抗生素。","extra":""},{"chapter":21,"key":"21:195","id":195,"word":"acupuncture","phonetic":"/ˈækjʊpʌŋktʃə/","pos":"n.","meaningCN":"针灸，中医针灸疗法","tag":"低频","root":"","exampleEN":"Many people use acupuncture as a complementary treatment for chronic pain.","exampleCN":"许多人用针灸作为治疗慢性疼痛的辅助疗法。","extra":"puncture"},{"chapter":21,"key":"21:196","id":196,"word":"penicillin","phonetic":"/ˌpenɪˈsɪlɪn/","pos":"n.","meaningCN":"青霉素","tag":"低频","root":"","exampleEN":"The discovery of penicillin revolutionised the treatment of bacterial infections.","exampleCN":"青霉素的发现彻底改变了细菌感染的治疗方法。","extra":""},{"chapter":21,"key":"21:197","id":197,"word":"morphine","phonetic":"/ˈmɔːfiːn/","pos":"n.","meaningCN":"吗啡","tag":"识记","root":"","exampleEN":"Morphine is sometimes used in hospitals to relieve severe pain after surgery.","exampleCN":"医院有时使用吗啡来缓解手术后的剧痛。","extra":"Morpheus"},{"chapter":21,"key":"21:198","id":198,"word":"dose","phonetic":"/dəʊs/","pos":"n.","meaningCN":"（药物的）一剂 v. 给......服药","tag":"高频","root":"","exampleEN":"The usual dose for adults is one tablet twice a day after meals.","exampleCN":"成人通常的剂量是一天两次，每次一片，饭后服用。","extra":""},{"chapter":21,"key":"21:199","id":199,"word":"recovery","phonetic":"/rɪˈkʌvəri/","pos":"n.","meaningCN":"恢复，痊愈","tag":"核心","root":"","exampleEN":"The doctor said her recovery was remarkable and she could leave the hospital soon.","exampleCN":"医生说她恢复得很好，很快就可以出院了。","extra":"recover"},{"chapter":21,"key":"21:200","id":200,"word":"refresh","phonetic":"/rɪˈfreʃ/","pos":"v.","meaningCN":"使恢复精神","tag":"高频","root":"","exampleEN":"A short walk outdoors can help refresh your mind after hours of studying.","exampleCN":"学习数小时后，到户外走一小段路有助于恢复精神。","extra":"refreshing；refresh sb.'s memory"},{"chapter":21,"key":"21:201","id":201,"word":"relief","phonetic":"/rɪˈliːf/","pos":"n.","meaningCN":"宽慰，轻松；减轻，缓解","tag":"核心","root":"","exampleEN":"To my great relief, the final exam turned out to be much easier than I expected.","exampleCN":"令我大为宽慰的是，期末考试比我预想的容易得多。","extra":""},{"chapter":21,"key":"21:202","id":202,"word":"relieve","phonetic":"/rɪˈliːv/","pos":"v.","meaningCN":"救济；减轻，解除（痛苦、不快等）","tag":"核心","root":"","exampleEN":"This medicine should relieve the pain within half an hour.","exampleCN":"这种药应该能在半小时内缓解疼痛。","extra":""},{"chapter":21,"key":"21:203","id":203,"word":"alleviate","phonetic":"/əˈliːvieɪt/","pos":"v.","meaningCN":"减轻（痛苦等），缓解","tag":"高频","root":"","exampleEN":"The new traffic system was designed to alleviate congestion in the city centre.","exampleCN":"新的交通系统旨在缓解市中心的拥堵。","extra":""},{"chapter":21,"key":"21:204","id":204,"word":"resume","phonetic":"/rɪˈzjuːm/","pos":"v.","meaningCN":"重新开始，（中断后）继续","tag":"高频","root":"","exampleEN":"We will resume the meeting after a short coffee break.","exampleCN":"短暂的咖啡休息之后，我们将继续开会。","extra":""},{"chapter":21,"key":"21:205","id":205,"word":"ease","phonetic":"/iːz/","pos":"v.","meaningCN":"减轻，放松，缓和 n. 容易；悠闲","tag":"核心","root":"","exampleEN":"He passed the difficult exam with ease, surprising his classmates.","exampleCN":"他轻松地通过了那场很难的考试，令同学感到惊讶。","extra":"easy, easily"},{"chapter":21,"key":"21:206","id":206,"word":"relax","phonetic":"/rɪˈlæks/","pos":"v.","meaningCN":"放松","tag":"核心","root":"","exampleEN":"Listening to music is a wonderful way to relax after a stressful day.","exampleCN":"压力大的一天结束后，听音乐是一种极好的放松方式。","extra":""},{"chapter":21,"key":"21:207","id":207,"word":"normal","phonetic":"/ˈnɔːməl/","pos":"adj.","meaningCN":"正常的；正规的，规范的","tag":"核心","root":"","exampleEN":"It is normal to feel nervous before giving a speech in front of a large audience.","exampleCN":"在众多听众面前演讲前感到紧张是正常的。","extra":"normally, abnormal"},{"chapter":21,"key":"21:208","id":208,"word":"common","phonetic":"/ˈkɒmən/","pos":"adj.","meaningCN":"共同的；普通的，平常的","tag":"核心","root":"","exampleEN":"Cold and flu are common illnesses during the winter months.","exampleCN":"感冒和流感是冬季常见的疾病。","extra":"commonly, uncommon"},{"chapter":21,"key":"21:209","id":209,"word":"usual","phonetic":"/ˈjuːʒuəl/","pos":"adj.","meaningCN":"通常的，惯常的","tag":"核心","root":"","exampleEN":"He left for work at his usual time even though he was not feeling well.","exampleCN":"尽管身体不舒服，他还是按往常的时间去上班了。","extra":"usually, unusual"},{"chapter":21,"key":"21:210","id":210,"word":"optimistic","phonetic":"/ˌɒptɪˈmɪstɪk/","pos":"adj.","meaningCN":"乐观的，乐观主义的","tag":"核心","root":"","exampleEN":"Despite the difficulties, the manager remained optimistic about the company's future.","exampleCN":"尽管困难重重，经理对公司的未来仍然保持乐观。","extra":"optimism, optimist"},{"chapter":21,"key":"21:211","id":211,"word":"pessimistic","phonetic":"/ˌpesɪˈmɪstɪk/","pos":"adj.","meaningCN":"悲观的，悲观主义的","tag":"核心","root":"","exampleEN":"He is pessimistic about the outcome of the current negotiations.","exampleCN":"他对当前谈判的结果持悲观态度。","extra":""},{"chapter":21,"key":"21:212","id":212,"word":"positive","phonetic":"/ˈpɒzətɪv/","pos":"adj.","meaningCN":"肯定的；积极的；绝对的","tag":"核心","root":"","exampleEN":"Having a positive attitude can make a big difference when facing challenges.","exampleCN":"面对挑战时，积极的态度能产生很大的不同。","extra":"have a positive impact/influence/effect on"},{"chapter":21,"key":"21:213","id":213,"word":"negative","phonetic":"/ˈneɡətɪv/","pos":"adj.","meaningCN":"怀疑的；消极的","tag":"核心","root":"","exampleEN":"A negative attitude towards learning will only hinder your progress.","exampleCN":"对学习的消极态度只会阻碍你的进步。","extra":"搭配：have a negative impact on (对……有消极影响)；反义词：positive"},{"chapter":21,"key":"21:214","id":214,"word":"passive","phonetic":"/ˈpæsɪv/","pos":"adj.","meaningCN":"被动的，消极的","tag":"核心","root":"","exampleEN":"Instead of being passive, you should take the initiative in solving problems.","exampleCN":"你应该主动解决问题，而不是被动等待。","extra":"搭配：passive smoking (被动吸烟，吸二手烟)"},{"chapter":21,"key":"21:215","id":215,"word":"enthusiastic","phonetic":"/ɪnˌθjuːziˈæstɪk/","pos":"adj.","meaningCN":"热心的，热情的","tag":"核心","root":"","exampleEN":"She was so enthusiastic about the project that she worked overtime every day.","exampleCN":"她对项目充满热情，每天都加班工作。","extra":"派生词：enthusiasm (n. 热情)"},{"chapter":21,"key":"21:216","id":216,"word":"indifferent","phonetic":"/ɪnˈdɪfərənt/","pos":"adj.","meaningCN":"漠不关心的；无关紧要的；平庸的；中立的","tag":"高频","root":"","exampleEN":"How can you be indifferent to the suffering of homeless animals?","exampleCN":"你怎么能对无家可归动物的痛苦漠不关心呢？","extra":"搭配：remain indifferent (保持中立)；名词：indifference"},{"chapter":21,"key":"21:217","id":217,"word":"apathetic","phonetic":"/ˌæpəˈθɛtɪk/","pos":"adj.","meaningCN":"无动于衷的，漠不关心的","tag":"低频","root":"","exampleEN":"The apathetic response from the government frustrated the protesters.","exampleCN":"政府无动于衷的反应让抗议者感到沮丧。","extra":"名词：apathy (冷漠)"},{"chapter":21,"key":"21:218","id":218,"word":"negligible","phonetic":"/ˈneɡlɪdʒəbl/","pos":"adj.","meaningCN":"可以忽略的，微不足道的","tag":"高频","root":"","exampleEN":"The difference between the two test results was negligible.","exampleCN":"两次测试结果之间的差异可以忽略不计。","extra":"同义词：trivial, insignificant"},{"chapter":21,"key":"21:219","id":219,"word":"happiness","phonetic":"/ˈhæpinəs/","pos":"n.","meaningCN":"幸福，快乐；适当","tag":"核心","root":"","exampleEN":"True happiness comes from meaningful relationships, not material possessions.","exampleCN":"真正的幸福来自有意义的人际关系，而非物质财富。","extra":"形容词：happy"},{"chapter":21,"key":"21:220","id":220,"word":"delight","phonetic":"/dɪˈlaɪt/","pos":"v.","meaningCN":"（使）高兴；爱好 n. 乐趣","tag":"核心","root":"","exampleEN":"The children delighted in playing games together during the holiday.","exampleCN":"孩子们在假期里一起玩游戏，非常开心。","extra":"搭配：delight in (以……为乐)；形容词：delightful"},{"chapter":21,"key":"21:221","id":221,"word":"merry","phonetic":"/ˈmeri/","pos":"adj.","meaningCN":"愉快的，欢乐的；微醉的","tag":"高频","root":"","exampleEN":"We spent a merry evening singing songs around the campfire.","exampleCN":"我们在篝火旁唱歌，度过了一个愉快的夜晚。","extra":"习语：Merry Christmas!；名词：merriment"},{"chapter":21,"key":"21:222","id":222,"word":"fun","phonetic":"/fʌn/","pos":"n.","meaningCN":"乐趣；玩笑 adj. 有趣的","tag":"核心","root":"","exampleEN":"Learning a new language can be great fun if you use creative methods.","exampleCN":"如果你使用创造性的方法，学习一门新语言可以非常有趣。","extra":"形容词：funny (滑稽的)"},{"chapter":21,"key":"21:223","id":223,"word":"joke","phonetic":"/dʒəʊk/","pos":"n.","meaningCN":"笑话；玩笑 v. 说笑话；开玩笑","tag":"核心","root":"","exampleEN":"He told a hilarious joke that made everyone in the room burst out laughing.","exampleCN":"他讲了一个搞笑的笑话，让房间里的每个人都大笑起来。","extra":"搭配：play a joke on sb. (开某人玩笑)"},{"chapter":21,"key":"21:224","id":224,"word":"laughter","phonetic":"/ˈlɑːftə/","pos":"n.","meaningCN":"笑，笑声","tag":"核心","root":"","exampleEN":"The sound of children's laughter filled the playground on a sunny afternoon.","exampleCN":"在一个阳光明媚的下午，孩子们的笑声充满了操场。","extra":"动词：laugh"},{"chapter":21,"key":"21:225","id":225,"word":"joy","phonetic":"/dʒɔɪ/","pos":"n.","meaningCN":"欢乐，喜悦；乐趣","tag":"核心","root":"","exampleEN":"Watching the sunrise from the mountain top brought us pure joy.","exampleCN":"在山顶看日出带给我们纯粹的喜悦。","extra":"形容词：joyful, joyous"},{"chapter":21,"key":"21:226","id":226,"word":"please","phonetic":"/pliːz/","pos":"v.","meaningCN":"使高兴，取悦 adv. 请","tag":"核心","root":"","exampleEN":"It's impossible to please everyone, so just be true to yourself.","exampleCN":"不可能让每个人都满意，所以只要做真实的自己。","extra":"反义词：displease；形容词：pleased, pleasant"},{"chapter":21,"key":"21:227","id":227,"word":"rejoice","phonetic":"/rɪˈdʒɔɪs/","pos":"v.","meaningCN":"（使）高兴，（使）欢喜","tag":"高频","root":"","exampleEN":"The whole nation rejoiced when the team won the championship.","exampleCN":"当这支队伍赢得冠军时，整个国家都欢欣鼓舞。","extra":"常用搭配：rejoice at/over sth."},{"chapter":21,"key":"21:228","id":228,"word":"thrill","phonetic":"/θrɪl/","pos":"n.","meaningCN":"激动 v.（使）激动；感到紧张","tag":"高频","root":"","exampleEN":"The thrill of bungee jumping attracted many adventure seekers.","exampleCN":"蹦极的刺激感吸引了许多寻求冒险的人。","extra":"形容词：thrilling"},{"chapter":21,"key":"21:229","id":229,"word":"cheer","phonetic":"/tʃɪə/","pos":"v.","meaningCN":"使振作；（向……）欢呼","tag":"核心","root":"","exampleEN":"The crowd cheered loudly when the marathon runner crossed the finish line.","exampleCN":"当马拉松选手冲过终点线时，人群大声欢呼。","extra":"搭配：cheer up (使振奋起来)；名词：cheerleader"},{"chapter":21,"key":"21:230","id":230,"word":"pleasure","phonetic":"/ˈpleʒə/","pos":"n.","meaningCN":"愉快，高兴；荣幸（用于回答对方的感谢）","tag":"核心","root":"","exampleEN":"It was a great pleasure meeting you at the conference last week.","exampleCN":"上周在会议上见到你非常荣幸。","extra":"形容词：pleasant, pleased"},{"chapter":21,"key":"21:231","id":231,"word":"agreeable","phonetic":"/ə'ɡriːəbl/","pos":"adj.","meaningCN":"使人愉快的；（欣然）同意的","tag":"高频","root":"","exampleEN":"She has an agreeable personality that makes everyone feel comfortable.","exampleCN":"她随和的个性让每个人都感到舒服。","extra":"动词：agree；反义词：disagreeable"},{"chapter":21,"key":"21:232","id":232,"word":"exhilarate","phonetic":"/ɪɡˈzɪləreɪt/","pos":"v.","meaningCN":"使高兴，使兴奋","tag":"低频","root":"","exampleEN":"The breathtaking view from the mountain top exhilarated all the climbers.","exampleCN":"山顶上令人惊叹的景色让所有登山者兴奋不已。","extra":"形容词：exhilarating, exhilarated"},{"chapter":21,"key":"21:233","id":233,"word":"satisfactory","phonetic":"/ˌsætɪsˈfæktəri/","pos":"adj.","meaningCN":"令人满意的","tag":"核心","root":"","exampleEN":"The quality of your work has been satisfactory this semester.","exampleCN":"你这学期的工作质量令人满意。","extra":"动词：satisfy；名词：satisfaction；反义词：unsatisfactory"},{"chapter":21,"key":"21:234","id":234,"word":"desirable","phonetic":"/dɪˈzaɪərəbl/","pos":"adj.","meaningCN":"可取的，值得拥有的，合意的","tag":"核心","root":"","exampleEN":"It is desirable to have some work experience before applying for this job.","exampleCN":"申请这份工作之前有一些工作经验是可取的。","extra":"动词：desire；反义词：undesirable"},{"chapter":21,"key":"21:235","id":235,"word":"exciting","phonetic":"/ɪkˈsaɪtɪŋ/","pos":"adj.","meaningCN":"令人兴奋的，使人激动的","tag":"核心","root":"","exampleEN":"The final match of the tournament was incredibly exciting.","exampleCN":"锦标赛的决赛令人难以置信地激动人心。","extra":"动词：excite；名词：excitement"},{"chapter":21,"key":"21:236","id":236,"word":"keen","phonetic":"/kiːn/","pos":"adj.","meaningCN":"强烈的；敏锐的；渴望的；[尤英]有强烈兴趣的","tag":"核心","root":"","exampleEN":"She is keen to learn new skills that will help her career development.","exampleCN":"她渴望学习有助于职业发展的新技能。","extra":"搭配：be keen on (对……感兴趣)"},{"chapter":21,"key":"21:237","id":237,"word":"zeal","phonetic":"/ziːl/","pos":"n.","meaningCN":"热心，热情，热忱","tag":"高频","root":"","exampleEN":"He worked with great zeal to complete the project ahead of schedule.","exampleCN":"他以极大的热情工作，提前完成了项目。","extra":"形容词：zealous (热心的)"},{"chapter":21,"key":"21:238","id":238,"word":"lively","phonetic":"/ˈlaɪvli/","pos":"adj.","meaningCN":"活泼的；活跃的；栩栩如生的","tag":"核心","root":"","exampleEN":"The market was lively with vendors shouting and customers bargaining.","exampleCN":"市场里小贩的叫卖声和顾客的讨价还价声充满了活力。","extra":"同义词：energetic, vivacious"},{"chapter":21,"key":"21:239","id":239,"word":"lovely","phonetic":"/ˈlʌvli/","pos":"adj.","meaningCN":"可爱的；令人愉快的","tag":"核心","root":"","exampleEN":"We had a lovely time walking along the beach at sunset.","exampleCN":"日落时分在海滩散步，我们度过了一段愉快的时光。","extra":"同义词：beautiful, delightful"},{"chapter":21,"key":"21:240","id":240,"word":"fond","phonetic":"/fɒnd/","pos":"adj.","meaningCN":"喜爱的；溺爱的","tag":"核心","root":"","exampleEN":"I am very fond of my grandmother who always tells me interesting stories.","exampleCN":"我非常喜欢我的祖母，她总是给我讲有趣的故事。","extra":"搭配：be fond of (喜欢)"},{"chapter":21,"key":"21:241","id":241,"word":"favour","phonetic":"/ˈfeɪvə/","pos":"n.","meaningCN":"偏爱；赞同；恩惠，帮助","tag":"核心","root":"","exampleEN":"Could you do me a favour and lend me your notes from yesterday's class?","exampleCN":"你能帮我个忙，把你昨天的课堂笔记借给我吗？","extra":"美式拼写：favor；形容词：favourable (赞成的；有利的)"},{"chapter":21,"key":"21:242","id":242,"word":"surprising","phonetic":"/səˈpraɪzɪŋ/","pos":"adj.","meaningCN":"令人惊讶的，出人意料","tag":"核心","root":"","exampleEN":"It is surprising how quickly children can learn a new language.","exampleCN":"孩子们学一门新语言的速度之快令人惊讶。","extra":"动词：surprise；副词：surprisingly"},{"chapter":21,"key":"21:243","id":243,"word":"startle","phonetic":"/ˈstɑːtl/","pos":"v.","meaningCN":"使大吃一惊 n. 吃惊","tag":"高频","root":"","exampleEN":"The sudden loud noise startled everyone in the library.","exampleCN":"突然的巨响吓了图书馆里的每个人一跳。","extra":"形容词：startled (受惊的), startling (惊人的)"},{"chapter":21,"key":"21:244","id":244,"word":"amazing","phonetic":"/əˈmeɪzɪŋ/","pos":"adj.","meaningCN":"令人惊叹的，惊人的","tag":"核心","root":"","exampleEN":"The magician's performance was truly amazing; nobody could figure out his tricks.","exampleCN":"魔术师的表演真是令人惊叹，没人能看穿他的把戏。","extra":"动词：amaze；名词：amazement"},{"chapter":21,"key":"21:245","id":245,"word":"astound","phonetic":"/əˈstaʊnd/","pos":"v.","meaningCN":"使大吃一惊，使惊骇","tag":"低频","root":"","exampleEN":"The news that he had won the lottery astounded his entire family.","exampleCN":"他中彩票的消息让全家人大吃一惊。","extra":"形容词：astounding, astounded"},{"chapter":21,"key":"21:246","id":246,"word":"hectic","phonetic":"/ˈhektɪk/","pos":"adj.","meaningCN":"兴奋活跃的，忙乱的，繁忙的","tag":"高频","root":"","exampleEN":"The week before the final exams is always hectic for students.","exampleCN":"期末考试前的一周对学生来说总是非常忙碌。","extra":"同义词：frantic, chaotic"},{"chapter":21,"key":"21:247","id":247,"word":"liberal","phonetic":"/ˈlɪbərəl/","pos":"adj.","meaningCN":"慷慨的，大方的；自由主义的","tag":"高频","root":"liber (自由的)","exampleEN":"She has a liberal attitude towards different cultures and lifestyles.","exampleCN":"她对不同的文化和生活方式持开明的态度。","extra":"搭配：liberal arts (文科)；动词：liberate (解放)"},{"chapter":21,"key":"21:248","id":248,"word":"generous","phonetic":"/ˈdʒenərəs/","pos":"adj.","meaningCN":"慷慨的；宽厚的","tag":"核心","root":"","exampleEN":"He was generous enough to donate a large sum to the local charity.","exampleCN":"他非常慷慨，向当地慈善机构捐赠了一大笔钱。","extra":"名词：generosity；反义词：stingy"},{"chapter":21,"key":"21:249","id":249,"word":"gentle","phonetic":"/ˈdʒentl/","pos":"adj.","meaningCN":"温和的；柔和的；文雅的；出身名门的","tag":"核心","root":"","exampleEN":"The mother spoke to her child in a gentle voice to calm him down.","exampleCN":"母亲用温柔的声音对孩子说话，让他平静下来。","extra":"名词：gentleman (绅士)；副词：gently"},{"chapter":21,"key":"21:250","id":250,"word":"mysterious","phonetic":"/mɪˈstɪəriəs/","pos":"adj.","meaningCN":"神秘的；不可思议的","tag":"核心","root":"","exampleEN":"There is something mysterious about the old house at the end of the street.","exampleCN":"街道尽头的老房子有些神秘。","extra":"名词：mystery (神秘)"},{"chapter":21,"key":"21:251","id":251,"word":"curious","phonetic":"/ˈkjʊəriəs/","pos":"adj.","meaningCN":"好奇的，好求知的","tag":"核心","root":"","exampleEN":"The little boy is curious about how airplanes can fly in the sky.","exampleCN":"小男孩对飞机如何能在天空飞翔感到好奇。","extra":"名词：curiosity (好奇心)"},{"chapter":21,"key":"21:252","id":252,"word":"humble","phonetic":"/ˈhʌmbəl/","pos":"adj.","meaningCN":"谦虚的；卑微的","tag":"核心","root":"hum (土地)","exampleEN":"Despite his great success, the scientist remains humble and approachable.","exampleCN":"尽管取得了巨大成功，这位科学家仍然谦虚而平易近人。","extra":"反义词：arrogant；动词：humble (使谦卑)"},{"chapter":21,"key":"21:253","id":253,"word":"modest","phonetic":"/ˈmɒdɪst/","pos":"adj.","meaningCN":"谦虚的，谦逊的","tag":"核心","root":"","exampleEN":"She won the award but was too modest to talk about her achievements.","exampleCN":"她获得了奖项，但过于谦虚，不愿谈论自己的成就。","extra":"名词：modesty；反义词：immodest"},{"chapter":21,"key":"21:254","id":254,"word":"humorous","phonetic":"/ˈhjuːmərəs/","pos":"adj.","meaningCN":"富于幽默感的，诙谐的","tag":"核心","root":"","exampleEN":"His humorous speech kept the audience laughing throughout the entire event.","exampleCN":"他幽默的演讲让观众在整个活动中笑声不断。","extra":"名词：humour (幽默)"},{"chapter":21,"key":"21:255","id":255,"word":"polite","phonetic":"/pəˈlaɪt/","pos":"adj.","meaningCN":"有礼貌的；客气的","tag":"核心","root":"","exampleEN":"It is polite to say 'thank you' when someone holds the door for you.","exampleCN":"当有人为你扶门时说'谢谢'是有礼貌的表现。","extra":"反义词：impolite (粗鲁的)；名词：politeness"},{"chapter":21,"key":"21:256","id":256,"word":"frank","phonetic":"/fræŋk/","pos":"adj.","meaningCN":"坦白的，直率的","tag":"高频","root":"","exampleEN":"He gave a frank opinion about the company's financial problems.","exampleCN":"他对公司的财务问题给出了坦率的意见。","extra":"副词：frankly；同义词：candid"},{"chapter":21,"key":"21:257","id":257,"word":"daring","phonetic":"/ˈdeərɪŋ/","pos":"adj.","meaningCN":"勇敢的，大胆的","tag":"高频","root":"","exampleEN":"The daring rescue of the climbers was praised by the whole community.","exampleCN":"对登山者的大胆营救受到了整个社区的赞扬。","extra":"动词：dare (敢于)"},{"chapter":21,"key":"21:258","id":258,"word":"manly","phonetic":"/ˈmænli/","pos":"adj.","meaningCN":"有男子气概的；果断的","tag":"低频","root":"","exampleEN":"He thinks that showing emotions is not considered manly behavior.","exampleCN":"他认为表露情感不被视为有男子气概的行为。","extra":"反义词：unmanly；对应词：womanly"},{"chapter":21,"key":"21:259","id":259,"word":"direct","phonetic":"/dɪˈrekt/","pos":"adj.","meaningCN":"直接的；直率的","tag":"核心","root":"","exampleEN":"She asked a direct question that made the politician uncomfortable.","exampleCN":"她问了一个直接的问题，让那位政客感到不舒服。","extra":"副词：directly；名词：direction"},{"chapter":21,"key":"21:260","id":260,"word":"earnest","phonetic":"/ˈɜːnɪst/","pos":"adj.","meaningCN":"认真的，诚恳的","tag":"高频","root":"","exampleEN":"The student made an earnest effort to improve his grades this semester.","exampleCN":"这学期这位学生认真努力地提高他的成绩。","extra":"副词：earnestly"},{"chapter":21,"key":"21:261","id":261,"word":"honesty","phonetic":"/ˈɒnɪsti/","pos":"n.","meaningCN":"诚实，正直","tag":"核心","root":"","exampleEN":"Honesty is the foundation of any healthy relationship.","exampleCN":"诚实是任何健康关系的基础。","extra":"形容词：honest；搭配：in all honesty (说实话)"},{"chapter":21,"key":"21:262","id":262,"word":"proud","phonetic":"/praʊd/","pos":"adj.","meaningCN":"骄傲的，自豪的；令人自豪的","tag":"核心","root":"","exampleEN":"Her parents were proud of her when she graduated from medical school.","exampleCN":"当她从医学院毕业时，她的父母为她感到骄傲。","extra":"搭配：be proud of；名词：pride"},{"chapter":21,"key":"21:263","id":263,"word":"rational","phonetic":"/ˈreɪʃənəl/","pos":"adj.","meaningCN":"理性的；合理的","tag":"核心","root":"","exampleEN":"Making a rational decision requires gathering all the relevant information first.","exampleCN":"做出理性的决定需要首先收集所有相关信息。","extra":"名词：rationality；反义词：irrational"},{"chapter":21,"key":"21:264","id":264,"word":"seriously","phonetic":"/ˈsɪəriəsli/","pos":"adv.","meaningCN":"严肃地；认真地；严重地","tag":"核心","root":"","exampleEN":"The doctor seriously warned him to quit smoking for his health.","exampleCN":"医生严肃地警告他为了健康应该戒烟。","extra":"形容词：serious"},{"chapter":21,"key":"21:265","id":265,"word":"stern","phonetic":"/stɜːn/","pos":"adj.","meaningCN":"严厉的；坚定的","tag":"高频","root":"","exampleEN":"The teacher gave the students a stern look when they misbehaved in class.","exampleCN":"当学生们在课堂上表现不佳时，老师给了他们一个严厉的眼神。","extra":"副词：sternly；名词：sternness"},{"chapter":21,"key":"21:266","id":266,"word":"friendly","phonetic":"/ˈfriːndli/","pos":"adj.","meaningCN":"友好的，友善的","tag":"核心","root":"","exampleEN":"The new neighbors are very friendly and invited us to dinner.","exampleCN":"新邻居非常友好，邀请我们去吃晚饭。","extra":"名词：friendliness"},{"chapter":21,"key":"21:267","id":267,"word":"hospitable","phonetic":"/ˈhɒspɪtəbl/","pos":"adj.","meaningCN":"好客的；热情友好的","tag":"高频","root":"","exampleEN":"The locals were extremely hospitable, offering us food and shelter.","exampleCN":"当地人非常好客，为我们提供食物和住处。","extra":"名词：hospitality (好客)；注意：文档原文为hospital，实际应为hospitable"},{"chapter":21,"key":"21:268","id":268,"word":"romantic","phonetic":"/ˌrɒmənˈtɑːk/","pos":"adj.","meaningCN":"浪漫的；充满传奇色彩的","tag":"核心","root":"","exampleEN":"They had a romantic dinner by the candlelight in a quiet restaurant.","exampleCN":"他们在一家安静的餐厅里，在烛光下共进浪漫晚餐。","extra":"名词：romance；词源：源自 Roman"},{"chapter":21,"key":"21:269","id":269,"word":"freedom","phonetic":"/ˈfriːdəm/","pos":"n.","meaningCN":"自由，独立自主","tag":"核心","root":"","exampleEN":"Freedom of speech is a fundamental right in many democratic societies.","exampleCN":"言论自由是许多民主社会的一项基本权利。","extra":"形容词：free"},{"chapter":21,"key":"21:270","id":270,"word":"careful","phonetic":"/ˈkɛrfl/","pos":"adj.","meaningCN":"仔细的，细致的；小心的，谨慎的","tag":"核心","root":"","exampleEN":"You need to be careful when crossing the busy intersection.","exampleCN":"穿过繁忙的十字路口时需要小心。","extra":"副词：carefully；名词：carefulness"},{"chapter":21,"key":"21:271","id":271,"word":"concern","phonetic":"/kənˈsɜːrn/","pos":"n.","meaningCN":"关心；忧虑 v. 涉及；使担忧；关心","tag":"核心","root":"","exampleEN":"The main concern of parents is their children's safety and education.","exampleCN":"父母主要关心的是孩子的安全和教育。","extra":"搭配：be concerned about (关心)；形容词：concerned"},{"chapter":21,"key":"21:272","id":272,"word":"confidence","phonetic":"/ˈkɒnfɪdəns/","pos":"n.","meaningCN":"自信；信任","tag":"核心","root":"fid (信任)","exampleEN":"With enough practice, you will gain confidence in speaking English.","exampleCN":"通过足够的练习，你会获得说英语的信心。","extra":"形容词：confident；反义词：diffidence"},{"chapter":21,"key":"21:273","id":273,"word":"considerate","phonetic":"/kənˈsɪdərət/","pos":"adj.","meaningCN":"考虑周到的，体谅的","tag":"高频","root":"","exampleEN":"It was very considerate of you to bring me a cup of tea while I was working.","exampleCN":"你在工作时给我端来一杯茶，真是考虑周到。","extra":"反义词：inconsiderate；动词：consider (考虑)"},{"chapter":21,"key":"21:274","id":274,"word":"thoughtful","phonetic":"/ˈθɔːtfəl/","pos":"adj.","meaningCN":"认真思考的；考虑周到的，体贴的","tag":"高频","root":"","exampleEN":"She sent a thoughtful gift that showed she knew my interests well.","exampleCN":"她送了一份体贴的礼物，说明她非常了解我的兴趣。","extra":"反义词：thoughtless"},{"chapter":21,"key":"21:275","id":275,"word":"sympathetic","phonetic":"/ˌsɪmpəˈθetɪk/","pos":"adj.","meaningCN":"同情的；和谐的","tag":"核心","root":"","exampleEN":"The counselor was sympathetic to the student's personal problems.","exampleCN":"辅导员对学生的个人问题表示同情。","extra":"名词：sympathy；动词：sympathize"},{"chapter":21,"key":"21:276","id":276,"word":"ready","phonetic":"/ˈredi/","pos":"adj.","meaningCN":"准备好的；愿意的","tag":"核心","root":"","exampleEN":"We need to be ready for any unexpected situation during the trip.","exampleCN":"我们需要为旅行中任何意外情况做好准备。","extra":"副词：readily；搭配：get ready for"},{"chapter":21,"key":"21:277","id":277,"word":"apologise","phonetic":"/əˈpɒlədʒaɪz/","pos":"v.","meaningCN":"道歉，赔罪","tag":"高频","root":"","exampleEN":"He apologised for being late, explaining that there was heavy traffic.","exampleCN":"他为迟到道歉，解释说路上堵车严重。","extra":"美式拼写：apologize；名词：apology"},{"chapter":21,"key":"21:278","id":278,"word":"apology","phonetic":"/əˈpɒlədʒi/","pos":"n.","meaningCN":"道歉；辩解","tag":"核心","root":"","exampleEN":"The company issued a public apology for its defective products.","exampleCN":"该公司为其有缺陷的产品发表了公开道歉。","extra":"动词：apologise"},{"chapter":21,"key":"21:279","id":279,"word":"mercy","phonetic":"/ˈmɜːsi/","pos":"n.","meaningCN":"仁慈，宽容，怜悯","tag":"高频","root":"","exampleEN":"The judge showed mercy to the young offender because of his difficult background.","exampleCN":"考虑到这名年轻罪犯的艰难背景，法官对他表示了宽容。","extra":"形容词：merciful；反义词：merciless"},{"chapter":21,"key":"21:280","id":280,"word":"admire","phonetic":"/ədˈmaɪə/","pos":"v.","meaningCN":"赞美，钦佩，仰慕","tag":"核心","root":"mir (惊讶，惊奇)","exampleEN":"I truly admire people who dedicate their lives to helping others.","exampleCN":"我真心钦佩那些毕生致力于帮助他人的人。","extra":"名词：admiration；形容词：admirable"},{"chapter":21,"key":"21:281","id":281,"word":"remarkable","phonetic":"/rɪˈmɑːkəbəl/","pos":"adj.","meaningCN":"值得注意的；非凡的，卓越的","tag":"核心","root":"","exampleEN":"The young pianist gave a remarkable performance at the concert hall.","exampleCN":"那位年轻的钢琴家在音乐厅里进行了卓越的表演。","extra":"动词：remark (评论)；副词：remarkably"},{"chapter":21,"key":"21:282","id":282,"word":"grateful","phonetic":"/ˈɡreɪtfəl/","pos":"adj.","meaningCN":"感激的；表示感激的","tag":"核心","root":"","exampleEN":"I am deeply grateful to all the teachers who supported me during my studies.","exampleCN":"我深深感激所有在我学习期间支持我的老师。","extra":"名词：gratitude"},{"chapter":21,"key":"21:283","id":283,"word":"gratitude","phonetic":"/ˈɡrætɪtjuːd/","pos":"n.","meaningCN":"感激，感谢，感恩","tag":"高频","root":"","exampleEN":"Words cannot express my gratitude for your generous help.","exampleCN":"言语无法表达我对你慷慨帮助的感激之情。","extra":"形容词：grateful"},{"chapter":21,"key":"21:284","id":284,"word":"eager","phonetic":"/ˈiːɡə/","pos":"adj.","meaningCN":"渴望的，热切的","tag":"核心","root":"","exampleEN":"The children were eager to open their presents on Christmas morning.","exampleCN":"孩子们急切地想打开他们的圣诞礼物。","extra":"名词：eagerness；副词：eagerly"},{"chapter":21,"key":"21:285","id":285,"word":"sound","phonetic":"/saʊnd/","pos":"adj.","meaningCN":"健全的；（睡眠）酣畅的；合理的","tag":"核心","root":"","exampleEN":"That is a sound investment strategy with minimal risk.","exampleCN":"这是一个风险极小的合理投资策略。","extra":"搭配：a sound sleep (酣睡)；名词含义：声音"},{"chapter":21,"key":"21:286","id":286,"word":"picturesque","phonetic":"/ˌpɪktʃəˈresk/","pos":"adj.","meaningCN":"如画的；独特的","tag":"高频","root":"","exampleEN":"The picturesque village attracts many tourists every autumn.","exampleCN":"这个如画般的村庄每年秋天都吸引许多游客。","extra":"后缀：-esque (风格)；相关：picture"},{"chapter":21,"key":"21:287","id":287,"word":"promising","phonetic":"/ˈprɒmɪsɪŋ/","pos":"adj.","meaningCN":"大有希望的，有前途的","tag":"核心","root":"","exampleEN":"He is a promising young scientist with several published papers.","exampleCN":"他是一位有前途的年轻科学家，已经发表了几篇论文。","extra":"动词：promise (承诺)"},{"chapter":21,"key":"21:288","id":288,"word":"prominent","phonetic":"/ˈprɒmɪnənt/","pos":"adj.","meaningCN":"突出的，显著的；重要的，杰出的","tag":"核心","root":"","exampleEN":"The prominent politician gave a speech about environmental protection.","exampleCN":"这位杰出的政治家就环境保护发表了演讲。","extra":"名词：prominence"},{"chapter":21,"key":"21:289","id":289,"word":"awesome","phonetic":"/ˈɔːsəm/","pos":"adj.","meaningCN":"卓越的，引起敬畏的","tag":"高频","root":"","exampleEN":"The view of the Grand Canyon at sunrise is absolutely awesome.","exampleCN":"日出时分大峡谷的景色绝对令人敬畏。","extra":"名词：awe (敬畏)；口语中常表示'很棒'"},{"chapter":21,"key":"21:290","id":290,"word":"arduous","phonetic":"/ˈɑːdjuəs/","pos":"adj.","meaningCN":"辛勤的；费力的；陡峭的","tag":"高频","root":"","exampleEN":"Climbing the mountain was an arduous journey that took three days.","exampleCN":"爬山是一段艰辛的旅程，花了三天时间。","extra":"同义词：difficult, strenuous"},{"chapter":21,"key":"21:291","id":291,"word":"tough","phonetic":"/tʌf/","pos":"adj.","meaningCN":"艰难的；坚强的，坚韧不拔的；强硬的","tag":"核心","root":"","exampleEN":"She has a tough personality and never gives up in the face of challenges.","exampleCN":"她性格坚韧，面对挑战从不放弃。","extra":"搭配：a tough policy (强硬的政策)；名词：toughness"},{"chapter":21,"key":"21:292","id":292,"word":"robust","phonetic":"/rəˈbʌst/","pos":"adj.","meaningCN":"强壮的，强健的","tag":"高频","root":"","exampleEN":"Regular exercise helps maintain a robust immune system.","exampleCN":"定期锻炼有助于维持强健的免疫系统。","extra":"名词：robustness；品牌：乐百氏 Robust"},{"chapter":21,"key":"21:293","id":293,"word":"sturdy","phonetic":"/ˈstɜːdi/","pos":"adj.","meaningCN":"强健的；坚定的","tag":"高频","root":"","exampleEN":"The sturdy oak table lasted for more than fifty years.","exampleCN":"这张坚固的橡木桌子用了五十多年。","extra":"同义词：strong, durable"},{"chapter":21,"key":"21:294","id":294,"word":"steadfast","phonetic":"/ˈstedfɑːst/","pos":"adj.","meaningCN":"坚定的","tag":"高频","root":"","exampleEN":"He remained steadfast in his decision to study abroad despite opposition.","exampleCN":"尽管有反对意见，他仍坚定地决定出国留学。","extra":"副词：steadfastly"},{"chapter":21,"key":"21:295","id":295,"word":"tender","phonetic":"/ˈtendə/","pos":"adj.","meaningCN":"脆弱的；温柔的；软弱的；疼痛的","tag":"高频","root":"","exampleEN":"The nurse gave the patient a tender touch that made him feel cared for.","exampleCN":"护士温柔地触摸病人，让他感到被关怀。","extra":"动词含义：提出；投标"},{"chapter":21,"key":"21:296","id":296,"word":"temperate","phonetic":"/ˈtempərət/","pos":"adj.","meaningCN":"（气候）温和的；温带的；有节制的；心平气和的","tag":"高频","root":"","exampleEN":"Most of Europe has a temperate climate with four distinct seasons.","exampleCN":"欧洲大部分地区属于温带气候，四季分明。","extra":"名词：temperateness"},{"chapter":21,"key":"21:297","id":297,"word":"delicate","phonetic":"/ˈdelɪkət/","pos":"adj.","meaningCN":"精致的；微妙的；脆弱的","tag":"核心","root":"","exampleEN":"The delicate glass ornaments must be handled with extreme care.","exampleCN":"精致的玻璃饰品必须极其小心地处理。","extra":"名词：delicacy"},{"chapter":21,"key":"21:298","id":298,"word":"mundane","phonetic":"/mʌnˈdeɪn/","pos":"adj.","meaningCN":"平凡的，世俗的；世界的","tag":"低频","root":"","exampleEN":"Even mundane tasks like washing dishes can be enjoyable with good music.","exampleCN":"即使像洗碗这样平凡的家务，有好音乐相伴也会变得愉快。","extra":"同义词：ordinary, routine"},{"chapter":21,"key":"21:299","id":299,"word":"naive","phonetic":"/naɪˈiːv/","pos":"adj.","meaningCN":"天真的；幼稚的","tag":"高频","root":"","exampleEN":"His naive belief that everyone is honest led him to be cheated.","exampleCN":"他天真地认为每个人都诚实，结果被骗了。","extra":"名词：naivety"},{"chapter":21,"key":"21:300","id":300,"word":"childish","phonetic":"/ˈtʃaɪldɪʃ/","pos":"adj.","meaningCN":"孩子般的；幼稚的","tag":"高频","root":"","exampleEN":"Arguing over such a small matter is rather childish behavior.","exampleCN":"为如此小的事情争吵是相当幼稚的行为。","extra":"中性词：childlike (孩子般天真的)"},{"chapter":21,"key":"21:301","id":301,"word":"sincere","phonetic":"/sɪnˈsɪə/","pos":"adj.","meaningCN":"真诚的，诚挚的","tag":"核心","root":"","exampleEN":"Please accept my sincere apologies for the mistake I made.","exampleCN":"请接受我对所犯错误诚挚的道歉。","extra":"副词：sincerely；名词：sincerity；词源：拉丁文 sine cerae (没有蜡)"},{"chapter":21,"key":"21:302","id":302,"word":"liable","phonetic":"/ˈlaɪəbl/","pos":"adj.","meaningCN":"有责任的；有……倾向的，可能的","tag":"高频","root":"","exampleEN":"Drivers are liable for any damage caused by their negligence.","exampleCN":"驾驶员对其疏忽造成的任何损害负有责任。","extra":"搭配：be liable for (对……负责)；be liable to do sth. (有做某事的倾向)"},{"chapter":21,"key":"21:303","id":303,"word":"trustworthy","phonetic":"/ˈtrʌstˌwɜːði/","pos":"adj.","meaningCN":"值得信赖的，可靠的","tag":"核心","root":"","exampleEN":"We need a trustworthy person to look after our house while we are away.","exampleCN":"我们需要一个值得信赖的人在我们外出时照看房子。","extra":"名词：trustworthiness；反义词：untrustworthy"},{"chapter":21,"key":"21:304","id":304,"word":"enterprising","phonetic":"/ˈentəpraɪzɪŋ/","pos":"adj.","meaningCN":"有事业心的，有进取心的；有魄力的","tag":"高频","root":"","exampleEN":"Enterprising students started a small business selling handmade crafts.","exampleCN":"有进取心的学生创办了一家销售手工艺品的小企业。","extra":"名词：enterprise (企业；事业心)"},{"chapter":21,"key":"21:305","id":305,"word":"sane","phonetic":"/seɪn/","pos":"adj.","meaningCN":"心智健全的；理智的","tag":"高频","root":"","exampleEN":"No sane person would jump off a bridge without safety equipment.","exampleCN":"没有理智的人会在没有安全设备的情况下从桥上跳下。","extra":"反义词：insane (疯狂的)；名词：sanity"},{"chapter":21,"key":"21:306","id":306,"word":"strenuous","phonetic":"/ˈstrenjuəs/","pos":"adj.","meaningCN":"发奋的；繁重的，艰苦的","tag":"高频","root":"","exampleEN":"The firefighters made strenuous efforts to rescue the trapped victims.","exampleCN":"消防员们付出了艰苦的努力营救被困的受害者。","extra":"后缀：-ous (充满……的)"},{"chapter":21,"key":"21:307","id":307,"word":"rigorous","phonetic":"/ˈrɪɡərəs/","pos":"adj.","meaningCN":"严格的，严厉的；一丝不苟的","tag":"高频","root":"","exampleEN":"The university has rigorous admission standards for its engineering program.","exampleCN":"该大学对工程专业有严格的录取标准。","extra":"名词：rigour (严格)"},{"chapter":21,"key":"21:308","id":308,"word":"strict","phonetic":"/strɪkt/","pos":"adj.","meaningCN":"严格的；严厉的","tag":"核心","root":"","exampleEN":"My parents were very strict with me when I was a teenager.","exampleCN":"我十几岁时，父母对我非常严格。","extra":"搭配：be strict with sb. (对某人严厉)；名词：strictness"},{"chapter":21,"key":"21:309","id":309,"word":"severe","phonetic":"/sɪˈvɪə/","pos":"adj.","meaningCN":"严厉的；十分严重的；艰巨的","tag":"核心","root":"","exampleEN":"The storm caused severe damage to many houses along the coast.","exampleCN":"暴风雨对沿海许多房屋造成了严重破坏。","extra":"副词：severely"},{"chapter":21,"key":"21:310","id":310,"word":"mutual","phonetic":"/ˈmjuːtʃuəl/","pos":"adj.","meaningCN":"相互的，彼此的；共同的","tag":"核心","root":"","exampleEN":"Successful business partnerships are built on mutual trust and respect.","exampleCN":"成功的商业伙伴关系建立在相互信任和尊重的基础上。","extra":"同源词：neutral (中立的)"},{"chapter":21,"key":"21:311","id":311,"word":"resemble","phonetic":"/rɪˈzembəl/","pos":"v.","meaningCN":"与……相像，类似","tag":"核心","root":"sembl (相似)","exampleEN":"This insect resembles a dead leaf, which helps it hide from predators.","exampleCN":"这种昆虫像一片枯叶，这有助于它躲避捕食者。","extra":"名词：resemblance"},{"chapter":21,"key":"21:312","id":312,"word":"similar","phonetic":"/ˈsɪmɪlə/","pos":"adj.","meaningCN":"相似的，类似的","tag":"核心","root":"sim/simu (相似)","exampleEN":"My teaching style is similar to that of my mentor.","exampleCN":"我的教学风格和我的导师相似。","extra":"名词：similarity；搭配：be similar to"},{"chapter":21,"key":"21:313","id":313,"word":"familiar","phonetic":"/fəˈmɪliə/","pos":"adj.","meaningCN":"熟悉的","tag":"核心","root":"","exampleEN":"The song sounded familiar, but I couldn't remember the name.","exampleCN":"这首歌听起来很熟悉，但我记不起名字了。","extra":"搭配：be familiar with (熟悉)；反义词：unfamiliar"},{"chapter":21,"key":"21:314","id":314,"word":"naked","phonetic":"/ˈneɪkɪd/","pos":"adj.","meaningCN":"裸体的，赤条条的","tag":"高频","root":"","exampleEN":"The toddler ran naked through the living room after his bath.","exampleCN":"幼儿洗完澡后光着身子跑过客厅。","extra":"搭配：naked eye (肉眼)"},{"chapter":21,"key":"21:315","id":315,"word":"bare","phonetic":"/beə/","pos":"adj.","meaningCN":"赤裸的；无遮蔽的","tag":"高频","root":"","exampleEN":"The trees are bare in winter after all the leaves have fallen.","exampleCN":"冬天的树木在叶子落完后光秃秃的。","extra":"动词：bare (暴露)"},{"chapter":21,"key":"21:316","id":316,"word":"private","phonetic":"/ˈpraɪvɪt/","pos":"adj.","meaningCN":"私人的，个人的；私下的","tag":"核心","root":"","exampleEN":"Everyone deserves a private space where they can relax without interruption.","exampleCN":"每个人都应该有一个可以不受打扰地放松的私人空间。","extra":"名词：privacy"},{"chapter":21,"key":"21:317","id":317,"word":"intuition","phonetic":"/ˌɪntjuːˈɪʃən/","pos":"n.","meaningCN":"直觉","tag":"高频","root":"","exampleEN":"My intuition told me not to trust that man, and I was right.","exampleCN":"我的直觉告诉我不要相信那个人，而我是对的。","extra":"形容词：intuitive"},{"chapter":21,"key":"21:318","id":318,"word":"spontaneous","phonetic":"/spɒnˈteɪniəs/","pos":"adj.","meaningCN":"自发的，自然的，本能的；自然产生的","tag":"高频","root":"","exampleEN":"The audience gave a spontaneous applause after the moving speech.","exampleCN":"感人的演讲结束后，观众自发地鼓掌。","extra":"副词：spontaneously"},{"chapter":21,"key":"21:319","id":319,"word":"implicit","phonetic":"/ɪmˈplɪsɪt/","pos":"adj.","meaningCN":"暗示的，含蓄的；不怀疑的，无保留的","tag":"高频","root":"","exampleEN":"His silence was an implicit agreement to our proposal.","exampleCN":"他的沉默是对我们提议的默许。","extra":"反义词：explicit (明确的)"},{"chapter":21,"key":"21:320","id":320,"word":"illusion","phonetic":"/ɪˈluːʒən/","pos":"n.","meaningCN":"错觉；幻想","tag":"高频","root":"","exampleEN":"The magician created the illusion that the rabbit had disappeared.","exampleCN":"魔术师制造了兔子消失的错觉。","extra":"形容词：illusory"},{"chapter":21,"key":"21:321","id":321,"word":"imaginary","phonetic":"/ɪˈmædʒɪnəri/","pos":"adj.","meaningCN":"想象的，虚构的","tag":"高频","root":"","exampleEN":"The child had an imaginary friend whom he talked to every day.","exampleCN":"这个孩子有一个每天与之交谈的想象中的朋友。","extra":"动词：imagine；名词：imagination"},{"chapter":21,"key":"21:322","id":322,"word":"fancy","phonetic":"/ˈfænsi/","pos":"n.","meaningCN":"想象（力）；爱好 v. 认为，想象","tag":"高频","root":"","exampleEN":"I fancy taking a walk along the beach later this evening.","exampleCN":"我想今晚晚些时候去海滩散步。","extra":"名词：fantasy (幻想)"},{"chapter":21,"key":"21:323","id":323,"word":"fate","phonetic":"/feɪt/","pos":"n.","meaningCN":"命运，宿命","tag":"核心","root":"","exampleEN":"They met by chance, but believed it was fate that brought them together.","exampleCN":"他们偶然相遇，但相信是命运让他们走到了一起。","extra":"形容词：fatal (致命的)"},{"chapter":21,"key":"21:324","id":324,"word":"fortune","phonetic":"/ˈfɔːtʃuːn/","pos":"n.","meaningCN":"命运；运气；财产","tag":"核心","root":"","exampleEN":"He had the good fortune to find a wallet full of cash on the street.","exampleCN":"他幸运地在街上发现了一个装满现金的钱包。","extra":"形容词：fortunate (幸运的), unfortunate (不幸的)"},{"chapter":21,"key":"21:325","id":325,"word":"agony","phonetic":"/ˈæɡəni/","pos":"n.","meaningCN":"极度的痛苦；挣扎","tag":"高频","root":"","exampleEN":"He was in agony after breaking his leg during the soccer match.","exampleCN":"他在足球比赛中摔断了腿，极度痛苦。","extra":"形容词：agonizing"},{"chapter":21,"key":"21:326","id":326,"word":"grief","phonetic":"/ɡriːf/","pos":"n.","meaningCN":"极度悲伤","tag":"高频","root":"","exampleEN":"The whole community shared their grief when the beloved teacher passed away.","exampleCN":"当敬爱的老师去世时，整个社区都沉浸在悲伤中。","extra":"动词：grieve (使悲痛)"},{"chapter":21,"key":"21:327","id":327,"word":"grieve","phonetic":"/ɡriːv/","pos":"v.","meaningCN":"（使）悲痛","tag":"高频","root":"","exampleEN":"She is still grieving for her pet dog that died last month.","exampleCN":"她仍在为上个月死去的宠物狗感到悲痛。","extra":"名词：grief"},{"chapter":21,"key":"21:328","id":328,"word":"miserable","phonetic":"/ˈmɪzərəbl/","pos":"adj.","meaningCN":"极不愉快的，痛苦的","tag":"核心","root":"","exampleEN":"He felt miserable after failing the driving test for the third time.","exampleCN":"第三次驾照考试失败后，他感到非常痛苦。","extra":"名词：misery"},{"chapter":21,"key":"21:329","id":329,"word":"distress","phonetic":"/dɪˈstres/","pos":"n.","meaningCN":"悲痛；穷困，不幸 v. 使伤心，使忧虑","tag":"核心","root":"","exampleEN":"The news of the accident caused great distress to the victim's family.","exampleCN":"事故的消息给受害者家属带来了巨大的悲痛。","extra":"形容词：distressing"},{"chapter":21,"key":"21:330","id":330,"word":"sadness","phonetic":"/ˈsædnəs/","pos":"n.","meaningCN":"悲痛，悲哀","tag":"核心","root":"","exampleEN":"There was a sense of sadness in the room after hearing the bad news.","exampleCN":"听到这个坏消息后，房间里弥漫着悲伤的气氛。","extra":"形容词：sad"},{"chapter":21,"key":"21:331","id":331,"word":"gloomy","phonetic":"/ˈɡluːmi/","pos":"adj.","meaningCN":"幽暗的；令人沮丧的","tag":"高频","root":"","exampleEN":"The weather forecast is gloomy, with rain predicted for the whole week.","exampleCN":"天气预报令人沮丧，预计整周都有雨。","extra":"名词：gloom"},{"chapter":21,"key":"21:332","id":332,"word":"frown","phonetic":"/fraʊn/","pos":"n.","meaningCN":"皱眉，不悦 v. 皱眉，表示不悦","tag":"高频","root":"","exampleEN":"The teacher frowned when she saw the students whispering in class.","exampleCN":"老师看到学生们在课堂上窃窃私语时皱起了眉头。","extra":"搭配：frown upon/on (不赞成)"},{"chapter":21,"key":"21:333","id":333,"word":"disappoint","phonetic":"/ˌdɪsəˈpɔɪnt/","pos":"v.","meaningCN":"使失望；使受挫折","tag":"核心","root":"","exampleEN":"I don't want to disappoint my parents, so I study very hard.","exampleCN":"我不想让父母失望，所以我非常努力地学习。","extra":"名词：disappointment；形容词：disappointed, disappointing"},{"chapter":21,"key":"21:334","id":334,"word":"rage","phonetic":"/reɪdʒ/","pos":"n.","meaningCN":"盛怒，狂怒","tag":"高频","root":"","exampleEN":"He flew into a rage when someone scratched his new car.","exampleCN":"有人划了他的新车时，他勃然大怒。","extra":"搭配：in a rage (怒气冲冲)；road rage (路怒)"},{"chapter":21,"key":"21:335","id":335,"word":"discourage","phonetic":"/dɪsˈkʌrɪdʒ/","pos":"v.","meaningCN":"使灰心，使气馁；劝阻","tag":"核心","root":"","exampleEN":"Don't let one failure discourage you from trying again.","exampleCN":"不要让一次失败气馁，放弃再次尝试。","extra":"反义词：encourage；名词：discouragement"},{"chapter":21,"key":"21:336","id":336,"word":"wretched","phonetic":"/ˈretʃɪd/","pos":"adj.","meaningCN":"不幸的，可怜的，悲惨的；恶劣的","tag":"低频","root":"","exampleEN":"The refugees were living in wretched conditions without enough food.","exampleCN":"难民们生活在没有足够食物的悲惨条件下。","extra":"名词：wretch (可怜的人)"},{"chapter":21,"key":"21:337","id":337,"word":"frustrating","phonetic":"/frʌˈstreɪtɪŋ/","pos":"adj.","meaningCN":"令人灰心的，使人沮丧的","tag":"核心","root":"","exampleEN":"It is frustrating to spend hours on a problem and still not find a solution.","exampleCN":"花几个小时解决一个问题却仍然找不到答案，真是令人沮丧。","extra":"动词：frustrate；名词：frustration"},{"chapter":21,"key":"21:338","id":338,"word":"mourn","phonetic":"/mɔːn/","pos":"v.","meaningCN":"（因失去……而）哀痛，哀悼","tag":"高频","root":"","exampleEN":"The whole nation mourned the death of the beloved leader.","exampleCN":"全国人民哀悼敬爱的领导人的逝世。","extra":"名词：mourning；形容词：mournful"},{"chapter":21,"key":"21:339","id":339,"word":"irritate","phonetic":"/ˈɪrɪteɪt/","pos":"v.","meaningCN":"激怒，使急躁；刺激","tag":"高频","root":"","exampleEN":"The constant noise from the construction site irritated the residents.","exampleCN":"建筑工地持续不断的噪音激怒了居民。","extra":"名词：irritation；形容词：irritating"},{"chapter":21,"key":"21:340","id":340,"word":"anger","phonetic":"/ˈæŋɡə/","pos":"n.","meaningCN":"怒，怒气 v. 使发怒","tag":"核心","root":"","exampleEN":"He struggled to control his anger when he heard the unfair criticism.","exampleCN":"听到不公正的批评时，他努力控制自己的怒气。","extra":"形容词：angry"},{"chapter":21,"key":"21:341","id":341,"word":"hate","phonetic":"/heɪt/","pos":"v.","meaningCN":"恨，憎恨；不喜欢","tag":"核心","root":"","exampleEN":"I hate it when people interrupt me while I'm speaking.","exampleCN":"我讨厌别人在我说话时打断我。","extra":"名词：hatred；形容词：hateful"},{"chapter":21,"key":"21:342","id":342,"word":"furious","phonetic":"/ˈfjʊəriəs/","pos":"adj.","meaningCN":"狂怒的，暴怒的","tag":"高频","root":"","exampleEN":"She was furious when she discovered that someone had used her computer.","exampleCN":"当她发现有人用了她的电脑时，她勃然大怒。","extra":"名词：fury"},{"chapter":21,"key":"21:343","id":343,"word":"hatred","phonetic":"/ˈheɪtrɪd/","pos":"n.","meaningCN":"憎恶，憎恨，仇恨","tag":"核心","root":"","exampleEN":"Years of injustice built up a deep hatred in his heart.","exampleCN":"多年的不公在他心中积累了深深的仇恨。","extra":"动词：hate"},{"chapter":21,"key":"21:344","id":344,"word":"nuisance","phonetic":"/ˈnjuːsəns/","pos":"n.","meaningCN":"讨厌或麻烦的人（或事物）","tag":"高频","root":"","exampleEN":"The barking dog next door has become a real nuisance to the whole neighborhood.","exampleCN":"隔壁的狗叫声已经成为整个街区的真正麻烦。","extra":"习语：Commit No Nuisance (禁止随地小便)"},{"chapter":21,"key":"21:345","id":345,"word":"disgust","phonetic":"/dɪsˈɡʌst/","pos":"v.","meaningCN":"使厌恶，使作呕 n. 厌恶，嫌恶","tag":"核心","root":"","exampleEN":"The dirty condition of the restaurant kitchen filled me with disgust.","exampleCN":"餐厅厨房的肮脏状况让我感到厌恶。","extra":"形容词：disgusting, disgusted"},{"chapter":21,"key":"21:346","id":346,"word":"vex","phonetic":"/veks/","pos":"v.","meaningCN":"使烦恼，使恼火","tag":"低频","root":"","exampleEN":"His constant complaints vexed all the other passengers on the bus.","exampleCN":"他不停的抱怨使公交车上的所有其他乘客都感到恼火。","extra":"形容词：vexing, vexed"},{"chapter":21,"key":"21:347","id":347,"word":"harass","phonetic":"/ˈhærəs/","pos":"v.","meaningCN":"烦扰","tag":"高频","root":"","exampleEN":"It is illegal to harass someone because of their race or gender.","exampleCN":"因种族或性别骚扰他人是非法的。","extra":"名词：harassment"},{"chapter":21,"key":"21:348","id":348,"word":"bore","phonetic":"/bɔː/","pos":"v.","meaningCN":"烦扰；钻孔 n. 讨厌的人；令人生厌的事","tag":"高频","root":"","exampleEN":"The long lecture bored the students, and many of them fell asleep.","exampleCN":"冗长的讲座让学生们感到厌烦，很多人睡着了。","extra":"形容词：boring, bored"},{"chapter":21,"key":"21:349","id":349,"word":"bother","phonetic":"/ˈbɒðə/","pos":"v.","meaningCN":"花费时间精力（做某事）；（使）苦恼 n. 麻烦，困难","tag":"核心","root":"","exampleEN":"Sorry to bother you, but could you help me with this heavy box?","exampleCN":"抱歉打扰了，你能帮我搬这个重箱子吗？","extra":"常见用法：bother to do sth."},{"chapter":21,"key":"21:350","id":350,"word":"troublesome","phonetic":"/ˈtrʌbəlsəm/","pos":"adj.","meaningCN":"令人烦恼的；麻烦的","tag":"高频","root":"","exampleEN":"A troublesome computer virus caused the entire system to crash.","exampleCN":"一个麻烦的电脑病毒导致整个系统崩溃。","extra":"名词：trouble"},{"chapter":21,"key":"21:351","id":351,"word":"awful","phonetic":"/ˈɔːfəl/","pos":"adj.","meaningCN":"令人不愉快的，极讨厌的","tag":"核心","root":"","exampleEN":"The weather was awful, so we decided to stay indoors all day.","exampleCN":"天气糟透了，所以我们决定整天待在室内。","extra":"副词：awfully (非常)"},{"chapter":21,"key":"21:352","id":352,"word":"unpleasant","phonetic":"/ʌnˈplezənt/","pos":"adj.","meaningCN":"令人不愉快的，讨厌的","tag":"核心","root":"","exampleEN":"There was an unpleasant smell coming from the garbage can.","exampleCN":"垃圾桶里传来一股难闻的气味。","extra":"反义词：pleasant"},{"chapter":21,"key":"21:353","id":353,"word":"adverse","phonetic":"/ˈædvɜːs/","pos":"adj.","meaningCN":"敌对的，不友好的；不利的","tag":"高频","root":"","exampleEN":"The new policy may have an adverse effect on small businesses.","exampleCN":"新政策可能对小企业产生不利影响。","extra":"名词：adversity (逆境)"},{"chapter":21,"key":"21:354","id":354,"word":"hostile","phonetic":"/ˈhɒstaɪl/","pos":"adj.","meaningCN":"怀有敌意的，不友善的；敌对的","tag":"核心","root":"","exampleEN":"The rival team's fans gave us a hostile reception at the stadium.","exampleCN":"对手球队的球迷在体育场给了我们不友好的接待。","extra":"名词：hostility"},{"chapter":21,"key":"21:355","id":355,"word":"indignant","phonetic":"/ɪnˈdɪɡnənt/","pos":"adj.","meaningCN":"愤慨的，义愤的","tag":"高频","root":"","exampleEN":"The workers were indignant about the unfair wage cuts.","exampleCN":"工人们对不公平的减薪感到愤慨。","extra":"名词：indignation"},{"chapter":21,"key":"21:356","id":356,"word":"radical","phonetic":"/ˈrædɪkəl/","pos":"adj.","meaningCN":"激进的；根本的","tag":"高频","root":"","exampleEN":"The government proposed radical reforms to the education system.","exampleCN":"政府提出了对教育体系的根本性改革。","extra":"副词：radically"},{"chapter":21,"key":"21:357","id":357,"word":"mad","phonetic":"/mæd/","pos":"adj.","meaningCN":"发疯的；恼火的","tag":"核心","root":"","exampleEN":"He was mad at himself for making such a silly mistake.","exampleCN":"他对自己犯下如此愚蠢的错误感到恼火。","extra":"比较级：madder；最高级：maddest"},{"chapter":21,"key":"21:358","id":358,"word":"crazy","phonetic":"/ˈkreɪzi/","pos":"adj.","meaningCN":"疯狂的；荒唐的","tag":"核心","root":"","exampleEN":"You would be crazy to go hiking in this stormy weather.","exampleCN":"在这种暴风雨天气去徒步旅行，你简直是疯了。","extra":"名词：craziness"},{"chapter":21,"key":"21:359","id":359,"word":"wicked","phonetic":"/ˈwɪkst/","pos":"adj.","meaningCN":"邪恶的，缺德的","tag":"高频","root":"","exampleEN":"The wicked witch cast a spell on the princess.","exampleCN":"邪恶的女巫对公主施了咒语。","extra":"名词：wickedness；同源词：witch (巫婆)"},{"chapter":21,"key":"21:360","id":360,"word":"vicious","phonetic":"/ˈvɪʃəs/","pos":"adj.","meaningCN":"邪恶的，不道德的","tag":"高频","root":"","exampleEN":"The dog made a vicious attack on the postman.","exampleCN":"那只狗对邮差发起了恶毒的攻击。","extra":"名词：viciousness；副词：viciously"},{"chapter":21,"key":"21:361","id":361,"word":"vulgar","phonetic":"/ˈvʌlɡə/","pos":"adj.","meaningCN":"粗俗的，庸俗的","tag":"低频","root":"","exampleEN":"His vulgar jokes offended many people at the party.","exampleCN":"他粗俗的笑话冒犯了聚会上的许多人。","extra":"名词：vulgarity"},{"chapter":21,"key":"21:362","id":362,"word":"mean","phonetic":"/miːn/","pos":"adj.","meaningCN":"卑鄙的；吝啬的 v. 意思是","tag":"核心","root":"","exampleEN":"Don't be so mean to your little brother; share your toys with him.","exampleCN":"别对你的弟弟那么刻薄，和他分享你的玩具。","extra":"名词：meanness"},{"chapter":21,"key":"21:363","id":363,"word":"ego","phonetic":"/ˈiːɡəʊ/","pos":"n.","meaningCN":"自我，自尊；自负","tag":"高频","root":"拉丁文'我'","exampleEN":"His huge ego prevents him from admitting when he is wrong.","exampleCN":"他巨大的自负使他不愿承认自己的错误。","extra":"派生词：egocentric (以自我为中心的), egoism (利己主义)"},{"chapter":21,"key":"21:364","id":364,"word":"selfish","phonetic":"/ˈselfɪʃ/","pos":"adj.","meaningCN":"自私的，利己主义的","tag":"核心","root":"","exampleEN":"It is selfish to take all the credit without acknowledging others' contributions.","exampleCN":"把所有的功劳都归于自己而不承认别人的贡献是自私的。","extra":"反义词：selfless；名词：selfishness"},{"chapter":21,"key":"21:365","id":365,"word":"nasty","phonetic":"/ˈnæsti/","pos":"adj.","meaningCN":"下流的；肮脏的；险恶的","tag":"高频","root":"","exampleEN":"The broken glass caused a nasty cut on my hand.","exampleCN":"碎玻璃在我手上划了一道很深的伤口。","extra":"比较级：nastier；最高级：nastiest"},{"chapter":21,"key":"21:366","id":366,"word":"rash","phonetic":"/ræʃ/","pos":"adj.","meaningCN":"草率的，鲁莽的","tag":"高频","root":"","exampleEN":"Making a rash decision without thinking could lead to serious consequences.","exampleCN":"不经思考草率决定可能导致严重后果。","extra":"名词：rashness；副词：rashly"},{"chapter":21,"key":"21:367","id":367,"word":"volatile","phonetic":"/ˈvɒləteɪl/","pos":"adj.","meaningCN":"易变的，反复无常的；易挥发的","tag":"高频","root":"","exampleEN":"The stock market is volatile, so investing involves risks.","exampleCN":"股市波动很大，因此投资有风险。","extra":"名词：volatility"},{"chapter":21,"key":"21:368","id":368,"word":"weird","phonetic":"/ˈwɪəd/","pos":"adj.","meaningCN":"怪诞的，古怪的","tag":"高频","root":"","exampleEN":"I heard a weird noise coming from the basement last night.","exampleCN":"昨晚我听到地下室传来奇怪的声音。","extra":"同义词：strange, odd"},{"chapter":21,"key":"21:369","id":369,"word":"excessive","phonetic":"/ɪkˈsesɪv/","pos":"adj.","meaningCN":"过分的，过多的","tag":"核心","root":"","exampleEN":"Excessive use of smartphones can damage your eyesight.","exampleCN":"过度使用手机会损害你的视力。","extra":"名词：excess；副词：excessively"},{"chapter":21,"key":"21:370","id":370,"word":"anxiety","phonetic":"/ˈænɪˈzeɪti/","pos":"n.","meaningCN":"焦虑，担心；渴望","tag":"核心","root":"","exampleEN":"Students often feel anxiety before important exams.","exampleCN":"学生在重要考试前常常感到焦虑。","extra":"形容词：anxious"},{"chapter":21,"key":"21:371","id":371,"word":"restless","phonetic":"/ˈrestl̩s/","pos":"adj.","meaningCN":"不安定的，焦躁不安的，不耐烦的","tag":"高频","root":"","exampleEN":"The children grew restless after sitting for two hours in the cinema.","exampleCN":"在电影院坐了两个小时后，孩子们变得焦躁不安。","extra":"反义词：restful"},{"chapter":21,"key":"21:372","id":372,"word":"uneasy","phonetic":"/ʌnˈiːzi/","pos":"adj.","meaningCN":"心神不安的，忧虑的","tag":"核心","root":"","exampleEN":"I felt uneasy about walking alone in the dark alley.","exampleCN":"我对独自走在黑暗的小巷里感到不安。","extra":"名词：unease"},{"chapter":21,"key":"21:373","id":373,"word":"fear","phonetic":"/fɪə/","pos":"v./n.","meaningCN":"害怕；担心","tag":"核心","root":"","exampleEN":"Many people have a fear of public speaking, but it can be overcome.","exampleCN":"许多人害怕公开演讲，但这是可以克服的。","extra":"形容词：fearful；搭配：for fear of (以免)"},{"chapter":21,"key":"21:374","id":374,"word":"timid","phonetic":"/ˈtɪmɪd/","pos":"adj.","meaningCN":"胆小的，羞怯的","tag":"高频","root":"","exampleEN":"The timid student never raised his hand in class, even when he knew the answer.","exampleCN":"这个胆小的学生即使在知道答案时也从不在课堂上举手。","extra":"名词：timidity"},{"chapter":21,"key":"21:375","id":375,"word":"fuss","phonetic":"/fʌs/","pos":"n.","meaningCN":"大惊小怪，无谓的纷扰","tag":"高频","root":"","exampleEN":"Stop making such a fuss over a tiny scratch on the table.","exampleCN":"别为桌子上一个小小的划痕大惊小怪。","extra":"搭配：make a fuss about (对……大惊小怪)"},{"chapter":21,"key":"21:376","id":376,"word":"insult","phonetic":"/ɪnˈsʌlt/","pos":"v.","meaningCN":"侮辱，凌辱 n. /ˈɪnsʌlt/ 侮辱","tag":"核心","root":"","exampleEN":"He insulted his colleague by calling her incompetent in front of the boss.","exampleCN":"他在老板面前称同事无能，以此侮辱她。","extra":"形容词：insulting"},{"chapter":21,"key":"21:377","id":377,"word":"unkind","phonetic":"/ʌnˈkaɪnd/","pos":"adj.","meaningCN":"不仁慈的，不和善的，刻薄的","tag":"高频","root":"","exampleEN":"It was unkind of you to laugh at his mistake in front of everyone.","exampleCN":"你在大家面前嘲笑他的错误，太不厚道了。","extra":"反义词：kind"},{"chapter":21,"key":"21:378","id":378,"word":"envy","phonetic":"/ˈenvi/","pos":"v./n.","meaningCN":"羡慕；嫉妒","tag":"核心","root":"","exampleEN":"I envy your ability to stay calm under pressure.","exampleCN":"我羡慕你在压力下保持冷静的能力。","extra":"形容词：envious"},{"chapter":21,"key":"21:379","id":379,"word":"jealous","phonetic":"/ˈdʒeləs/","pos":"adj.","meaningCN":"嫉妒的，妒忌的","tag":"核心","root":"","exampleEN":"She felt jealous when her friend got a promotion she wanted.","exampleCN":"当她的朋友得到了她想要晋升时，她感到嫉妒。","extra":"名词：jealousy；搭配：be jealous of"},{"chapter":21,"key":"21:380","id":380,"word":"doubt","phonetic":"/daʊt/","pos":"n.","meaningCN":"怀疑，疑问 v. 怀疑，不信","tag":"核心","root":"","exampleEN":"There is no doubt that practice is essential for mastering a skill.","exampleCN":"毫无疑问，练习对于掌握技能至关重要。","extra":"形容词：doubtful；搭配：beyond doubt (毋庸置疑)"},{"chapter":21,"key":"21:381","id":381,"word":"suspicion","phonetic":"/səˈspɪʃən/","pos":"n.","meaningCN":"怀疑，嫌疑","tag":"核心","root":"","exampleEN":"His strange behavior aroused the suspicion of the police.","exampleCN":"他奇怪的行为引起了警方的怀疑。","extra":"动词：suspect；形容词：suspicious"},{"chapter":21,"key":"21:382","id":382,"word":"sceptical","phonetic":"/ˈskeptɪkəl/","pos":"adj.","meaningCN":"怀疑的","tag":"核心","root":"","exampleEN":"Many scientists are sceptical about the new treatment's effectiveness.","exampleCN":"许多科学家对这种新疗法的有效性持怀疑态度。","extra":"美式拼写：skeptical；名词：scepticism"},{"chapter":21,"key":"21:383","id":383,"word":"unsatisfactory","phonetic":"/ˌʌnsætɪsˈfæktəri/","pos":"adj.","meaningCN":"不能令人满意的，不符合要求的，不足的","tag":"高频","root":"","exampleEN":"The hotel service was unsatisfactory, so we asked for a refund.","exampleCN":"酒店服务不能令人满意，所以我们要求退款。","extra":"反义词：satisfactory"},{"chapter":21,"key":"21:384","id":384,"word":"unstable","phonetic":"/ʌnˈsteɪbəl/","pos":"adj.","meaningCN":"不稳定的；易变的；不牢固的","tag":"核心","root":"","exampleEN":"The financial market remains unstable due to global uncertainties.","exampleCN":"由于全球不确定性，金融市场仍然不稳定。","extra":"反义词：stable"},{"chapter":21,"key":"21:385","id":385,"word":"unsuitable","phonetic":"/ʌnˈsuːtəbəl/","pos":"adj.","meaningCN":"不合适的，不适宜的","tag":"核心","root":"","exampleEN":"These shoes are unsuitable for hiking in the mountains.","exampleCN":"这双鞋不适合在山里徒步。","extra":"搭配：unsuitable for；反义词：suitable"},{"chapter":21,"key":"21:386","id":386,"word":"unwilling","phonetic":"/ʌnˈwɪlɪŋ/","pos":"adj.","meaningCN":"不愿意的，不情愿的；勉强的","tag":"核心","root":"","exampleEN":"She was unwilling to admit that she had made a mistake.","exampleCN":"她不愿意承认自己犯了错误。","extra":"反义词：willing；名词：unwillingness"},{"chapter":21,"key":"21:387","id":387,"word":"reluctant","phonetic":"/rɪˈlʌktənt/","pos":"adj.","meaningCN":"不情愿的；勉强的","tag":"核心","root":"","exampleEN":"He gave a reluctant agreement to lend his car to his brother.","exampleCN":"他不情愿地同意把车借给弟弟。","extra":"名词：reluctance；搭配：be reluctant to do sth."},{"chapter":21,"key":"21:388","id":388,"word":"hesitate","phonetic":"/ˈhezɪteɪt/","pos":"v.","meaningCN":"犹豫不决，踌躇；顾虑","tag":"核心","root":"","exampleEN":"Don't hesitate to call me if you need any help.","exampleCN":"如果你需要任何帮助，请毫不犹豫地给我打电话。","extra":"名词：hesitation"},{"chapter":21,"key":"21:389","id":389,"word":"confuse","phonetic":"/kənˈfjuːz/","pos":"v.","meaningCN":"使困惑，把（某人）弄糊涂；混淆","tag":"核心","root":"","exampleEN":"The similar spellings of these two words often confuse language learners.","exampleCN":"这两个词相似的拼写常常使语言学习者感到困惑。","extra":"形容词：confused, confusing；名词：confusion"},{"chapter":21,"key":"21:390","id":390,"word":"guilty","phonetic":"/ˈɡɪlti/","pos":"adj.","meaningCN":"有罪的；内疚的","tag":"核心","root":"","exampleEN":"She felt guilty for forgetting her mother's birthday.","exampleCN":"她因忘记母亲的生日而感到内疚。","extra":"名词：guilt"},{"chapter":21,"key":"21:391","id":391,"word":"embarrass","phonetic":"/ɪmˈbærəs/","pos":"v.","meaningCN":"使尴尬，使窘迫，使局促不安","tag":"核心","root":"","exampleEN":"His loud voice embarrassed me in the quiet library.","exampleCN":"他在安静图书馆里的大嗓门让我很尴尬。","extra":"形容词：embarrassed, embarrassing；名词：embarrassment"},{"chapter":21,"key":"21:392","id":392,"word":"regret","phonetic":"/rɪˈɡret/","pos":"n.","meaningCN":"遗憾；抱歉；悲叹 v. 后悔；痛惜，惋惜","tag":"核心","root":"","exampleEN":"I regret not learning to play a musical instrument when I was younger.","exampleCN":"我后悔年轻时没有学一门乐器。","extra":"形容词：regretful, regrettable"},{"chapter":21,"key":"21:393","id":393,"word":"repent","phonetic":"/rɪˈpent/","pos":"v.","meaningCN":"忏悔；后悔","tag":"低频","root":"","exampleEN":"The thief repented of his crimes and returned the stolen money.","exampleCN":"小偷为自己的罪行忏悔并归还了赃款。","extra":"名词：repentance；形容词：repentant"},{"chapter":21,"key":"21:394","id":394,"word":"ashamed","phonetic":"/əˈʃeɪmd/","pos":"adj.","meaningCN":"惭愧的，感到难为情的；耻于……的","tag":"核心","root":"","exampleEN":"He was ashamed of lying to his parents about his grades.","exampleCN":"他为在成绩上对父母撒谎感到惭愧。","extra":"名词：shame"},{"chapter":21,"key":"21:395","id":395,"word":"sigh","phonetic":"/saɪ/","pos":"n.","meaningCN":"叹息，叹气","tag":"高频","root":"","exampleEN":"She let out a deep sigh of relief when she heard the good news.","exampleCN":"听到好消息时，她如释重负地长舒了一口气。","extra":"动词：sigh"},{"chapter":21,"key":"21:396","id":396,"word":"weep","phonetic":"/wiːp/","pos":"v.","meaningCN":"哭泣；流泪；哀悼 n. 哭泣","tag":"高频","root":"","exampleEN":"The little girl began to weep when she lost her favorite toy.","exampleCN":"小女孩丢失了最喜欢的玩具时开始哭泣。","extra":"过去式/过去分词：wept"},{"chapter":21,"key":"21:397","id":397,"word":"tolerance","phonetic":"/ˈtɒlərəns/","pos":"n.","meaningCN":"忍受，容忍，宽容","tag":"核心","root":"","exampleEN":"Living in a multicultural society requires tolerance and understanding.","exampleCN":"生活在多元文化社会需要宽容和理解。","extra":"动词：tolerate；形容词：tolerant"},{"chapter":21,"key":"21:398","id":398,"word":"ignorant","phonetic":"/ˈɪɡnərənt/","pos":"adj.","meaningCN":"无知的，没有学识的，愚昧的","tag":"核心","root":"","exampleEN":"Many people remain ignorant of the dangers of climate change.","exampleCN":"许多人仍然对气候变化的危险一无所知。","extra":"动词：ignore；名词：ignorance"},{"chapter":21,"key":"21:399","id":399,"word":"endure","phonetic":"/ɪnˈdjʊə/","pos":"v.","meaningCN":"忍耐，忍受；持久","tag":"核心","root":"","exampleEN":"The homeless man had to endure the bitter cold winter nights.","exampleCN":"那个无家可归的人不得不忍受寒冷的冬夜。","extra":"名词：endurance；形容词：endurable"},{"chapter":21,"key":"21:400","id":400,"word":"sly","phonetic":"/slɑɪ/","pos":"adj.","meaningCN":"狡猾的，狡诈的","tag":"低频","root":"","exampleEN":"The sly fox managed to steal the cheese from under the crow's beak.","exampleCN":"狡猾的狐狸设法从乌鸦的喙下偷走了奶酪。","extra":"搭配：on the sly (秘密地)"},{"chapter":21,"key":"21:401","id":401,"word":"cunning","phonetic":"/ˈkʌnɪŋ/","pos":"adj.","meaningCN":"狡猾的；巧妙的","tag":"高频","root":"","exampleEN":"The detective used cunning tactics to catch the thief.","exampleCN":"侦探使用狡猾的计谋抓住了小偷。","extra":"名词：cunning"},{"chapter":21,"key":"21:402","id":402,"word":"arbitrary","phonetic":"/ˈɑːrbɪteri/","pos":"adj.","meaningCN":"武断的，专断的；任意的","tag":"高频","root":"","exampleEN":"The decision seemed arbitrary, without any logical reason.","exampleCN":"这个决定似乎是武断的，没有任何逻辑理由。","extra":"名词：arbitrariness"},{"chapter":21,"key":"21:403","id":403,"word":"ridiculous","phonetic":"/rɪˈdɪkjʊləs/","pos":"adj.","meaningCN":"荒谬的，可笑的","tag":"核心","root":"","exampleEN":"The idea of building a castle in the backyard is simply ridiculous.","exampleCN":"在后院建一座城堡的想法简直荒谬。","extra":"动词：ridicule (嘲笑)"},{"chapter":21,"key":"21:404","id":404,"word":"stupid","phonetic":"/ˈstjuːpɪd/","pos":"adj.","meaningCN":"愚蠢的；麻木的；乏味的 n. 傻瓜，笨蛋","tag":"核心","root":"","exampleEN":"It was a stupid mistake, but I learned from it.","exampleCN":"那是个愚蠢的错误，但我从中吸取了教训。","extra":"名词：stupidity"},{"chapter":21,"key":"21:405","id":405,"word":"awkward","phonetic":"/ˈɔːkwəd/","pos":"adj.","meaningCN":"笨拙的；尴尬的；棘手的；不合适的","tag":"核心","root":"","exampleEN":"There was an awkward silence after he told the inappropriate joke.","exampleCN":"他讲了不合时宜的笑话后，出现了一阵尴尬的沉默。","extra":"名词：awkwardness"},{"chapter":21,"key":"21:406","id":406,"word":"clumsy","phonetic":"/ˈklʌmzi/","pos":"adj.","meaningCN":"笨拙的","tag":"高频","root":"","exampleEN":"The clumsy waiter spilled coffee on the customer's shirt.","exampleCN":"笨手笨脚的服务员把咖啡洒在了顾客的衬衫上。","extra":"名词：clumsiness"},{"chapter":21,"key":"21:407","id":407,"word":"careless","phonetic":"/ˈkerələs/","pos":"adj.","meaningCN":"粗心的；无忧无虑的；淡漠的","tag":"核心","root":"","exampleEN":"A careless driver caused a serious accident on the highway.","exampleCN":"一个粗心的司机在高速公路上造成了严重的事故。","extra":"名词：carelessness"},{"chapter":21,"key":"21:408","id":408,"word":"oblivious","phonetic":"/əˈblɪviəs/","pos":"adj.","meaningCN":"不知道的，未注意的","tag":"低频","root":"","exampleEN":"He was oblivious to the fact that everyone was staring at him.","exampleCN":"他没有注意到所有人都在盯着他。","extra":"名词：oblivion"},{"chapter":21,"key":"21:409","id":409,"word":"naughty","phonetic":"/ˈnɔːti/","pos":"adj.","meaningCN":"淘气的，顽皮的","tag":"核心","root":"","exampleEN":"The naughty boy hid his teacher's chalk as a prank.","exampleCN":"那个淘气的男孩恶作剧地把老师的粉笔藏了起来。","extra":"名词：naughtiness"},{"chapter":21,"key":"21:410","id":410,"word":"greedy","phonetic":"/ˈɡriːdi/","pos":"adj.","meaningCN":"贪吃的；贪婪的","tag":"高频","root":"","exampleEN":"The greedy businessman refused to share his profits with employees.","exampleCN":"贪婪的商人拒绝与员工分享利润。","extra":"名词：greed；七宗罪之一"},{"chapter":21,"key":"21:411","id":411,"word":"obtrusive","phonetic":"/ˈɒbtruːsɪv/","pos":"adj.","meaningCN":"过分炫耀的，过分突出的，扎眼的","tag":"低频","root":"","exampleEN":"The bright orange sign on the historic building was obtrusive.","exampleCN":"历史建筑上亮橙色的标志显得很扎眼。","extra":"动词：obtrude"},{"chapter":21,"key":"21:412","id":412,"word":"slothful","phonetic":"/ˈsləʊθfəl/","pos":"adj.","meaningCN":"偷懒的，懒散的","tag":"低频","root":"","exampleEN":"A slothful employee who avoids work will soon be fired.","exampleCN":"一个偷懒、逃避工作的员工很快会被解雇。","extra":"名词：sloth (懒惰；树懒)"},{"chapter":21,"key":"21:413","id":413,"word":"sluggish","phonetic":"/ˈslʌɡɪʃ/","pos":"adj.","meaningCN":"行动迟缓的","tag":"高频","root":"","exampleEN":"I felt sluggish after eating a heavy meal at lunch.","exampleCN":"午餐吃了油腻的食物后，我感到行动迟缓。","extra":"名词：sluggishness"},{"chapter":21,"key":"21:414","id":414,"word":"impulse","phonetic":"/ˈɪmpʌls/","pos":"n.","meaningCN":"冲动，心血来潮","tag":"核心","root":"","exampleEN":"On impulse, she bought a plane ticket to Paris without planning.","exampleCN":"一时冲动之下，她没做计划就买了去巴黎的机票。","extra":"形容词：impulsive"},{"chapter":21,"key":"21:415","id":415,"word":"rigid","phonetic":"/ˈrɪdʒɪd/","pos":"adj.","meaningCN":"固执的；严格的；刚硬的","tag":"高频","root":"","exampleEN":"The school has rigid rules about students' uniforms.","exampleCN":"学校对学生校服有严格的规定。","extra":"名词：rigidity"},{"chapter":21,"key":"21:416","id":416,"word":"stubborn","phonetic":"/ˈstʌbən/","pos":"adj.","meaningCN":"顽固的，固执的","tag":"核心","root":"","exampleEN":"He is too stubborn to admit that his plan has failed.","exampleCN":"他太固执了，不愿承认他的计划已经失败。","extra":"名词：stubbornness"},{"chapter":21,"key":"21:417","id":417,"word":"stereotype","phonetic":"/ˈsteriətaɪp/","pos":"n.","meaningCN":"老一套，模式化观念，刻板印象","tag":"核心","root":"","exampleEN":"We should avoid cultural stereotypes when traveling abroad.","exampleCN":"在国外旅行时，我们应避免文化刻板印象。","extra":"动词：stereotype (对……形成刻板印象)"}],"22":[{"chapter":22,"key":"22:1","id":1,"word":"daily","phonetic":"/ˈdeɪli/","pos":"adj. adv. n.","meaningCN":"每日的；每日；日报","tag":"核心","root":"day（日）+ ly → 每日的","exampleEN":"Reading English daily helps improve your vocabulary.","exampleCN":"每天阅读英语有助于提高词汇量。","extra":"搭配：daily routine 日常生活"},{"chapter":22,"key":"22:2","id":2,"word":"monthly","phonetic":"/ˈmʌnθli/","pos":"adj. adv. n.","meaningCN":"每月的；每月一次；月刊","tag":"核心","root":"month（月）+ ly","exampleEN":"We make monthly payments for our car loan.","exampleCN":"我们每月支付汽车贷款。","extra":""},{"chapter":22,"key":"22:3","id":3,"word":"quarterly","phonetic":"/ˈkwɔːtəli/","pos":"adj. adv. n.","meaningCN":"季度的；按季度地；季刊","tag":"高频","root":"quarter（四分之一）+ ly","exampleEN":"The company releases its financial results quarterly.","exampleCN":"公司每季度发布财务业绩。","extra":""},{"chapter":22,"key":"22:4","id":4,"word":"annual","phonetic":"/ˈænjuəl/","pos":"adj. n.","meaningCN":"每年的；一年的；年报","tag":"核心","root":"ann（年）+ ual","exampleEN":"The annual conference attracts thousands of attendees.","exampleCN":"年度会议吸引了数千名与会者。","extra":"搭配：annual report 年度报告"},{"chapter":22,"key":"22:5","id":5,"word":"yearly","phonetic":"/ˈjɪəli/","pos":"adj. adv.","meaningCN":"每年的；每年地","tag":"核心","root":"year（年）+ ly","exampleEN":"We take a yearly trip to the mountains.","exampleCN":"我们每年去山里旅行一次。","extra":"近义词：annual"},{"chapter":22,"key":"22:6","id":6,"word":"anniversary","phonetic":"/ˌænɪˈvɜːsəri/","pos":"n.","meaningCN":"周年纪念日","tag":"核心","root":"ann（年）+ vers（转）+ ary → 一年转回的日子","exampleEN":"They celebrated their tenth wedding anniversary with a party.","exampleCN":"他们举办派对庆祝结婚十周年。","extra":""},{"chapter":22,"key":"22:7","id":7,"word":"era","phonetic":"/ˈɪərə/","pos":"n.","meaningCN":"时代，年代，纪元","tag":"核心","root":"源自拉丁语 aera（数字/时代）","exampleEN":"The invention of the internet marked a new era in communication.","exampleCN":"互联网的发明标志着通信新时代的到来。","extra":""},{"chapter":22,"key":"22:8","id":8,"word":"present","phonetic":"/ˈpreznt/","pos":"adj. n.","meaningCN":"现在的；目前；礼物","tag":"核心","root":"pre（前）+ sent（存在）→ 在眼前的","exampleEN":"At present, we have no plans to expand the business.","exampleCN":"目前，我们没有扩张业务的计划。","extra":"搭配：at present 目前"},{"chapter":22,"key":"22:9","id":9,"word":"contemporary","phonetic":"/kənˈtemprəri/","pos":"adj.","meaningCN":"当代的；同时代的","tag":"核心","root":"con（共同）+ tempor（时间）+ ary → 同时间的","exampleEN":"The artist's work is heavily influenced by contemporary culture.","exampleCN":"这位艺术家的作品深受当代文化的影响。","extra":""},{"chapter":22,"key":"22:10","id":10,"word":"medieval","phonetic":"/ˌmediˈiːvəl/","pos":"adj.","meaningCN":"中世纪的；守旧的","tag":"高频","root":"medi（中间）+ ev（时代）+ al → 中间时代","exampleEN":"This castle was built during medieval times.","exampleCN":"这座城堡建于中世纪。","extra":""},{"chapter":22,"key":"22:11","id":11,"word":"century","phonetic":"/ˈsentʃəri/","pos":"n.","meaningCN":"世纪；百年","tag":"核心","root":"cent（百）+ ury","exampleEN":"The 20th century saw many technological breakthroughs.","exampleCN":"20世纪见证了许多技术突破。","extra":""},{"chapter":22,"key":"22:12","id":12,"word":"millennium","phonetic":"/mɪˈleniəm/","pos":"n.","meaningCN":"一千年，千年期；千禧年","tag":"高频","root":"mill（千）+ enn（年）+ ium","exampleEN":"People around the world celebrated the new millennium in 2000.","exampleCN":"2000年全世界人民庆祝新千年的到来。","extra":"复数：millennia"},{"chapter":22,"key":"22:13","id":13,"word":"million","phonetic":"/ˈmɪljən/","pos":"num. n.","meaningCN":"百万；大量","tag":"核心","root":"源自拉丁语 mille（千）","exampleEN":"The project cost over ten million dollars.","exampleCN":"这个项目耗资超过一千万美元。","extra":"搭配：millions of 成千上万的"},{"chapter":22,"key":"22:14","id":14,"word":"billion","phonetic":"/ˈbɪljən/","pos":"num. n.","meaningCN":"十亿；大量","tag":"核心","root":"bi（二）+ million → 二百万的平方？源于法语","exampleEN":"There are nearly eight billion people on Earth.","exampleCN":"地球上近有80亿人。","extra":""},{"chapter":22,"key":"22:15","id":15,"word":"dozen","phonetic":"/ˈdʌzn/","pos":"n.","meaningCN":"一打，十二个；十来个","tag":"核心","root":"源自古法语 douzaine","exampleEN":"She bought two dozen eggs from the farmer's market.","exampleCN":"她从农贸市场买了两打鸡蛋。","extra":"短语：dozens of 很多"},{"chapter":22,"key":"22:16","id":16,"word":"dawn","phonetic":"/dɔːn/","pos":"n. v.","meaningCN":"黎明；开端；破晓","tag":"核心","root":"源自古英语 dagian（变白天）","exampleEN":"We woke up at dawn to watch the sunrise.","exampleCN":"我们在黎明醒来观看日出。","extra":"短语：dawn on 逐渐明白"},{"chapter":22,"key":"22:17","id":17,"word":"midday","phonetic":"/ˌmɪdˈdeɪ/","pos":"n.","meaningCN":"正午，中午","tag":"核心","root":"mid（中间）+ day（白天）","exampleEN":"The sun is directly overhead at midday.","exampleCN":"正午时分太阳直射头顶。","extra":"同义词：noon"},{"chapter":22,"key":"22:18","id":18,"word":"midnight","phonetic":"/ˈmɪdnaɪt/","pos":"n.","meaningCN":"午夜，子夜","tag":"核心","root":"mid（中间）+ night（夜晚）","exampleEN":"They returned home shortly before midnight.","exampleCN":"他们在午夜前不久回到家。","extra":"短语：burn the midnight oil 熬夜工作"},{"chapter":22,"key":"22:19","id":19,"word":"overnight","phonetic":"/ˌəʊvəˈnaɪt/","pos":"adv. adj.","meaningCN":"在晚上；一夜之间；突然","tag":"核心","root":"over（跨越）+ night（夜晚）","exampleEN":"The hotel offers overnight accommodation for travelers.","exampleCN":"这家酒店为旅客提供过夜住宿。","extra":"也可表示'一夜成名'：become famous overnight"},{"chapter":22,"key":"22:20","id":20,"word":"night","phonetic":"/naɪt/","pos":"n.","meaningCN":"夜，夜间","tag":"核心","root":"源自古英语 niht","exampleEN":"The city's night life is vibrant and exciting.","exampleCN":"这座城市的夜生活充满活力与激情。","extra":"搭配：night and day 夜以继日"},{"chapter":22,"key":"22:21","id":21,"word":"modern","phonetic":"/ˈmɒdn/","pos":"adj.","meaningCN":"现代的；近代的","tag":"核心","root":"源自拉丁语 modernus（当代的）","exampleEN":"Modern technology has changed the way we communicate.","exampleCN":"现代技术改变了我们的沟通方式。","extra":"反义词：ancient"},{"chapter":22,"key":"22:22","id":22,"word":"recent","phonetic":"/ˈriːsnt/","pos":"adj.","meaningCN":"新近的，最近的","tag":"核心","root":"源自拉丁语 recens（新鲜的）","exampleEN":"Recent studies show that exercise improves mental health.","exampleCN":"最近的研究表明运动有益心理健康。","extra":"副词：recently"},{"chapter":22,"key":"22:23","id":23,"word":"up-to-date","phonetic":"/ˌʌp tə ˈdeɪt/","pos":"adj.","meaningCN":"直到目前的；现代的，最新的","tag":"核心","root":"up（向上）+ to + date（日期）→ 紧跟日期","exampleEN":"Make sure your antivirus software is up-to-date.","exampleCN":"确保你的杀毒软件是最新版本。","extra":"反义词：out-of-date"},{"chapter":22,"key":"22:24","id":24,"word":"first","phonetic":"/fɜːst/","pos":"ord. adv.","meaningCN":"第一；最初","tag":"核心","root":"源自古英语 fyrest","exampleEN":"First, you need to gather all the ingredients.","exampleCN":"首先，你需要收集所有原料。","extra":"搭配：at first 起初"},{"chapter":22,"key":"22:25","id":25,"word":"secondly","phonetic":"/ˈsekəndli/","pos":"adv.","meaningCN":"第二，其次","tag":"核心","root":"second（第二）+ ly","exampleEN":"The plan has two advantages: firstly, it's cheap; secondly, it's fast.","exampleCN":"这个计划有两个优点：第一便宜，第二快速。","extra":"序列副词：thirdly, fourthly..."},{"chapter":22,"key":"22:26","id":26,"word":"finally","phonetic":"/ˈfaɪnəli/","pos":"adv.","meaningCN":"最后；终于；决定性地","tag":"核心","root":"final（最后的）+ ly","exampleEN":"After hours of waiting, the train finally arrived.","exampleCN":"经过数小时等待，火车终于到了。","extra":"同义词：eventually"},{"chapter":22,"key":"22:27","id":27,"word":"finish","phonetic":"/ˈfɪnɪʃ/","pos":"v. n.","meaningCN":"完成；结束；结尾","tag":"核心","root":"源自拉丁语 finire（结束）","exampleEN":"I need to finish this report before Friday.","exampleCN":"我需要在周五前完成这份报告。","extra":""},{"chapter":22,"key":"22:28","id":28,"word":"immediately","phonetic":"/ɪˈmiːdiətli/","pos":"adv.","meaningCN":"立即；直接地","tag":"核心","root":"im（无）+ medi（中间）+ ate + ly → 无间隔","exampleEN":"Please call me immediately if you see anything suspicious.","exampleCN":"如果你看到任何可疑情况，请立即给我打电话。","extra":"近义词：instantly"},{"chapter":22,"key":"22:29","id":29,"word":"instant","phonetic":"/ˈɪnstənt/","pos":"n. adj.","meaningCN":"瞬间；立即的","tag":"核心","root":"in（在内）+ stant（站立）→ 正站着的点","exampleEN":"For an instant, I thought I saw a shooting star.","exampleCN":"有那么一瞬间，我以为看到了流星。","extra":"短语：instant coffee 速溶咖啡"},{"chapter":22,"key":"22:30","id":30,"word":"moment","phonetic":"/ˈməʊmənt/","pos":"n.","meaningCN":"片刻；时刻","tag":"核心","root":"源自拉丁语 momentum（运动/瞬间）","exampleEN":"Could you wait a moment while I finish this call?","exampleCN":"你能等一会儿让我打完这个电话吗？","extra":"短语：at the moment 此刻"},{"chapter":22,"key":"22:31","id":31,"word":"minute","phonetic":"/ˈmɪnɪt/ (n.) /maɪˈnjuːt/ (adj.)","pos":"n. adj.","meaningCN":"分钟；一会儿；细微的","tag":"核心","root":"源自拉丁语 minutus（小的）","exampleEN":"I'll be there in five minutes.","exampleCN":"我五分钟后到。","extra":"辨析：moment 较短，minute 可精确，instant 极短"},{"chapter":22,"key":"22:32","id":32,"word":"prior","phonetic":"/ˈpraɪə/","pos":"adj.","meaningCN":"在先的，在前的","tag":"核心","root":"源自拉丁语 prior（更前的）","exampleEN":"All bookings must be made prior to the departure date.","exampleCN":"所有预订必须在出发日期之前完成。","extra":"搭配：prior to 在……之前"},{"chapter":22,"key":"22:33","id":33,"word":"former","phonetic":"/ˈfɔːmə/","pos":"adj. pron.","meaningCN":"以前的；前者的；前者","tag":"核心","root":"源自古英语 forma（第一）","exampleEN":"Of the two options, the former is more affordable.","exampleCN":"两个选项中，前者更实惠。","extra":"对比：latter 后者"},{"chapter":22,"key":"22:34","id":34,"word":"preceding","phonetic":"/prɪˈsiːdɪŋ/","pos":"adj.","meaningCN":"在前的，在先的","tag":"高频","root":"pre（前）+ ced（走）+ ing → 走在前的","exampleEN":"The preceding chapter introduced basic concepts.","exampleCN":"前一章介绍了基本概念。","extra":"动词：precede"},{"chapter":22,"key":"22:35","id":35,"word":"precedent","phonetic":"/ˈpresɪdənt/","pos":"n.","meaningCN":"先例；常规","tag":"核心","root":"pre（前）+ ced（走）+ ent → 走在前的例子","exampleEN":"The court's decision set a legal precedent.","exampleCN":"法院的判决开创了法律先例。","extra":""},{"chapter":22,"key":"22:36","id":36,"word":"foremost","phonetic":"/ˈfɔːməʊst/","pos":"adj.","meaningCN":"最前的；最重要的","tag":"核心","root":"fore（前）+ most（最）","exampleEN":"He is considered the foremost expert in the field.","exampleCN":"他被认为是该领域最重要的专家。","extra":"短语：first and foremost 首先"},{"chapter":22,"key":"22:37","id":37,"word":"opening","phonetic":"/ˈəʊpnɪŋ/","pos":"adj. n.","meaningCN":"开始的；开始，开端","tag":"核心","root":"open（开）+ ing","exampleEN":"The opening scene of the movie was very suspenseful.","exampleCN":"电影的开场非常悬念。","extra":"反义词：closing"},{"chapter":22,"key":"22:38","id":38,"word":"initially","phonetic":"/ɪˈnɪʃəli/","pos":"adv.","meaningCN":"最初","tag":"核心","root":"initial（初始的）+ ly","exampleEN":"Initially, I found the course difficult, but now I enjoy it.","exampleCN":"起初我觉得课程很难，但现在我喜欢它了。","extra":"形容词：initial"},{"chapter":22,"key":"22:39","id":39,"word":"intermediate","phonetic":"/ˌɪntəˈmiːdiət/","pos":"adj.","meaningCN":"中间的","tag":"高频","root":"inter（在……之间）+ medi（中间）+ ate","exampleEN":"This textbook is suitable for intermediate learners.","exampleCN":"这本教材适合中级学习者。","extra":""},{"chapter":22,"key":"22:40","id":40,"word":"midst","phonetic":"/mɪdst/","pos":"n.","meaningCN":"中部，中间","tag":"低频","root":"源自 midd（中间）的古英语","exampleEN":"He spotted a familiar face in the midst of the crowd.","exampleCN":"他在人群中认出了一张熟悉的面孔。","extra":"搭配：in the midst of 在……之中"},{"chapter":22,"key":"22:41","id":41,"word":"meantime","phonetic":"/ˈmiːntaɪm/","pos":"n.","meaningCN":"其间","tag":"核心","root":"mean（中间的）+ time","exampleEN":"The movie starts at 7; in the meantime, let's get some coffee.","exampleCN":"电影7点开始；在此期间，我们去喝点咖啡吧。","extra":"搭配：in the meantime 与此同时"},{"chapter":22,"key":"22:42","id":42,"word":"meanwhile","phonetic":"/ˈmiːnwaɪl/","pos":"adv.","meaningCN":"同时，其间","tag":"核心","root":"mean（中间的）+ while（一段时间）","exampleEN":"The cake is baking; meanwhile, you can prepare the frosting.","exampleCN":"蛋糕正在烘焙；与此同时，你可以准备糖霜。","extra":"近义词：meantime"},{"chapter":22,"key":"22:43","id":43,"word":"simultaneous","phonetic":"/ˌsɪmlˈteɪniəs/","pos":"adj.","meaningCN":"同时发生（或进行）的","tag":"核心","root":"simul（一起）+ taneous → 同时的","exampleEN":"The two explosions were nearly simultaneous.","exampleCN":"两次爆炸几乎是同时发生的。","extra":"副词：simultaneously"},{"chapter":22,"key":"22:44","id":44,"word":"ongoing","phonetic":"/ˈɒŋɡəʊɪŋ/","pos":"adj.","meaningCN":"进行中的；继续存在的","tag":"核心","root":"on（持续）+ going（进行）","exampleEN":"The investigation into the accident is ongoing.","exampleCN":"对这起事故的调查仍在进行中。","extra":""},{"chapter":22,"key":"22:45","id":45,"word":"everlasting","phonetic":"/ˌevəˈlɑːstɪŋ/","pos":"adj.","meaningCN":"永恒的","tag":"高频","root":"ever（永远）+ lasting（持续的）","exampleEN":"The couple made an everlasting commitment to each other.","exampleCN":"这对夫妇对彼此做出了永恒的承诺。","extra":"近义词：eternal"},{"chapter":22,"key":"22:46","id":46,"word":"permanent","phonetic":"/ˈpɜːmənənt/","pos":"adj.","meaningCN":"永久的","tag":"核心","root":"per（贯穿）+ man（停留）+ ent → 一直停留","exampleEN":"The accident left a permanent scar on his face.","exampleCN":"事故在他脸上留下了一道永久的疤痕。","extra":"反义词：temporary"},{"chapter":22,"key":"22:47","id":47,"word":"punctual","phonetic":"/ˈpʌŋktʃuəl/","pos":"adj.","meaningCN":"准时的，守时的","tag":"核心","root":"punct（点）+ ual → 守时间点的","exampleEN":"She is always punctual for meetings.","exampleCN":"她开会总是很准时。","extra":"名词：punctuality"},{"chapter":22,"key":"22:48","id":48,"word":"duration","phonetic":"/djuˈreɪʃn/","pos":"n.","meaningCN":"持续时间；期间","tag":"核心","root":"dur（持续）+ ation","exampleEN":"The duration of the flight is approximately ten hours.","exampleCN":"航班的持续时间大约为十个小时。","extra":"同根词：during"},{"chapter":22,"key":"22:49","id":49,"word":"consecutive","phonetic":"/kənˈsekjətɪv/","pos":"adj.","meaningCN":"连续不断的","tag":"核心","root":"con（一起）+ secut（跟随）+ ive → 一个接一个","exampleEN":"He has won the championship for three consecutive years.","exampleCN":"他连续三年赢得冠军。","extra":"近义词：successive"},{"chapter":22,"key":"22:50","id":50,"word":"periodically","phonetic":"/ˌpɪəriˈɒdɪkli/","pos":"adv.","meaningCN":"周期性地，定期地","tag":"高频","root":"period（周期）+ ically","exampleEN":"You should back up your data periodically.","exampleCN":"你应该定期备份数据。","extra":"形容词：periodic"},{"chapter":22,"key":"22:51","id":51,"word":"imminent","phonetic":"/ˈɪmɪnənt/","pos":"adj.","meaningCN":"（尤指不愉快的事）即将发生的，逼近的","tag":"高频","root":"源自拉丁语 imminere（悬在头顶）","exampleEN":"Dark clouds warned of imminent rain.","exampleCN":"乌云预示着即将下雨。","extra":"近义词：forthcoming"},{"chapter":22,"key":"22:52","id":52,"word":"incidentally","phonetic":"/ˌɪnsɪˈdentəli/","pos":"adv.","meaningCN":"偶然地；顺便提一句","tag":"核心","root":"incident（事件）+ ally","exampleEN":"Incidentally, have you seen my keys anywhere?","exampleCN":"顺便问一下，你在哪儿看到我的钥匙了吗？","extra":"用于引入补充信息或转换话题"},{"chapter":22,"key":"22:53","id":53,"word":"subsequent","phonetic":"/ˈsʌbsɪkwənt/","pos":"adj.","meaningCN":"随后的，后来的","tag":"核心","root":"sub（随后）+ sequ（跟随）+ ent → 跟在后面","exampleEN":"Subsequent events proved that our decision was correct.","exampleCN":"随后的事件证明我们的决定是正确的。","extra":"对比：previous 先前的"},{"chapter":22,"key":"22:54","id":54,"word":"chronological","phonetic":"/ˌkrɒnəˈlɒdʒɪkl/","pos":"adj.","meaningCN":"按时间顺序的","tag":"高频","root":"chrono（时间）+ logical（…学的）","exampleEN":"Please list the events in chronological order.","exampleCN":"请按时间顺序列出事件。","extra":"副词：chronologically"},{"chapter":22,"key":"22:55","id":55,"word":"epoch","phonetic":"/ˈiːpɒk/","pos":"n.","meaningCN":"时代，纪元；重要时期","tag":"低频","root":"源自希腊语 epokhe（停顿/固定点）","exampleEN":"The invention of the printing press marked an epoch in history.","exampleCN":"印刷机的发明标志着历史上的一个新时代。","extra":"同义词：era"},{"chapter":22,"key":"22:56","id":56,"word":"postpone","phonetic":"/pəˈspəʊn/","pos":"v.","meaningCN":"推迟，延期","tag":"核心","root":"post（后）+ pone（放置）→ 往后放","exampleEN":"Due to bad weather, the match has been postponed until next week.","exampleCN":"由于天气恶劣，比赛已推迟到下周。","extra":"近义词：delay；反义词：advance"},{"chapter":22,"key":"22:57","id":57,"word":"premature","phonetic":"/ˈpremətʃə/","pos":"adj.","meaningCN":"过早的；未成熟的","tag":"高频","root":"pre（前）+ mature（成熟的）→ 成熟前的","exampleEN":"His premature decision led to many problems later.","exampleCN":"他过早的决定后来导致了许多问题。","extra":"也可指婴儿早产：premature baby"}]}};
